--
-- Name: _bem_cardinality(); Type: FUNCTION; Schema: altlast; Owner: -
--

CREATE FUNCTION altlast._bem_cardinality() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    if (
        select exists(
            select count(*)
            from altlast.bem
            join altlast.bemgrp using(bemgrp_id)
            where bemgrp.multiple=FALSE and bemgrp_id=NEW.bemgrp_id and bem.key_value=NEW.key_value
            group by bemgrp_id, bem.key_value
            -- Abort inserts when 1 row exists, updates when more than 1 rows exist
            having count(*)>case when TG_OP='INSERT' then 0 else 1 end
            limit 1
        )
    ) then
        raise exception 'Cannot save annotation because group % does only allow 1 annotation per entity (key_value=%).',
        (select bemgrp from altlast.bemgrp where bemgrp_id=NEW.bemgrp_id),
        NEW.key_value;
    end if;

    return NEW;
END;$$;


--
-- Name: FUNCTION _bem_cardinality(); Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON FUNCTION altlast._bem_cardinality() IS 'Trigger to ensure only 1 annotation is added to groups where bemgrp.multiple=FALSE.';


--
-- Name: _byta_suffix(); Type: FUNCTION; Schema: altlast; Owner: -
--

CREATE FUNCTION altlast._byta_suffix() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
	if new.mime_type is not null then
		if new.mime_type ilike 'application/pdf%' then
			new.dateisuffix := 'pdf';
		else if new.mime_type ilike 'application/vnd.oasis.opendocument.text%' then
			new.dateisuffix := 'odt';
			end if;
		end if;
	end if;
	return new;
	
END
$$;


