--
-- Name: _check_pm_cache_subj(); Type: FUNCTION; Schema: altlast; Owner: -
--

CREATE FUNCTION altlast._check_pm_cache_subj() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
  DECLARE
   cnt integer;
    rec record;
    BEGIN
        SELECT count(*) INTO cnt FROM altlast.cod WHERE code=NEW.c_pm_cache_subj_bez_art AND c_cli_id=2;
            IF cnt=0 THEN
                    RAISE EXCEPTION 'Keine gültige Beziehungsart gewählt.';
            END IF;
            SELECT count(*) INTO cnt FROM altlast.pm_cache_subj WHERE subj_id=NEW.subj_id AND pm_cache_id=NEW.pm_cache_id AND c_pm_cache_subj_bez_art=NEW.c_pm_cache_subj_bez_art;
            IF cnt>0 THEN
                    SELECT c.bezeichnung,s.name INTO rec FROM altlast.subj s ,altlast.cod c WHERE c.c_cli_id=2 AND c.code=NEW.c_pm_cache_subj_bez_art AND s.subj_id=NEW.subj_id;
                    RAISE EXCEPTION 'Subjekt % ist diesem Standort bereits in der Beziehungsart % zugewiesen.',rec.name,rec.bezeichnung;
            END IF;

            RETURN NEW;
   END;$$;


--
-- Name: _check_pm_taskconf_configured_start_task(); Type: FUNCTION; Schema: altlast; Owner: -
--

CREATE FUNCTION altlast._check_pm_taskconf_configured_start_task() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
    BEGIN

	if exists (select  t2.pro_uid
			from altlast.pm_taskconf as tc1
			join altlast.pm_task as t1 on t1.tas_uid = tc1.tas_uid
			join altlast.pm_task as t2 on t2.pro_uid = t1.pro_uid
			join altlast.pm_taskconf as tc2 on t2.tas_uid = tc2.tas_uid
			where tc1.is_configured_start_task = True
				and tc2.is_configured_start_task = True
			group by t2.pro_uid
			having count(*) > 1) then
		raise exception 'Es ist nur eine konfigurierte Startaufgabe pro Prozess möglich.';
	end if;

	if exists(select tc.tas_uid 
			from altlast.pm_taskconf tc 
			join altlast.pm_task as t on t.tas_uid = tc.tas_uid
			where tc.is_configured_start_task and not t.is_start_task) then
		raise exception 'Die gewählte Aufgabe ist keine Startaufgabe.';
	end if;

   RETURN NEW;
   END;$$;


--
-- Name: _check_pm_taskconf_unterstand_bearbstand(); Type: FUNCTION; Schema: altlast; Owner: -
--

CREATE FUNCTION altlast._check_pm_taskconf_unterstand_bearbstand() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
    DECLARE
        i integer;
    BEGIN
        IF new.bearbstand IS NOT NULL AND new.c_vflz_bearbstand IS NULL THEN
            RAISE EXCEPTION 'No c_vflz_bearbstand defined';
        END IF;
        IF new.unterstand IS NOT NULL AND new.c_vflz_unterstand IS NULL THEN
            RAISE EXCEPTION 'No c_vflz_unterstand defined';
        END IF;
        IF new.unterstand IS NOT NULL THEN
            SELECT pc.unterstand INTO i FROM altlast.pm_processconf pc JOIN altlast.pm_task tc USING(pro_uid) WHERE tc.tas_uid=new.tas_uid;
            IF i IS NULL THEN
                RAISE EXCEPTION 'No unterstand defined for process';
            END IF;
        END IF;
        IF new.bearbstand IS NOT NULL THEN
            SELECT pc.bearbstand INTO i FROM altlast.pm_processconf pc JOIN altlast.pm_task tc USING(pro_uid) WHERE tc.tas_uid=new.tas_uid;
            IF i IS NULL THEN
                RAISE EXCEPTION 'No bearbstand defined for process';
            END IF;
        END IF;
        RETURN NEW;
   END;$$;


