-- Name: _delete_byta(); Type: FUNCTION; Schema: altlast; Owner: -
--

CREATE FUNCTION altlast._delete_byta() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE 
    anzahl integer;
BEGIN
    SELECT count(*) INTO anzahl FROM altlast.byta_gss where byta_id=OLD.byta_id AND gss_id!=OLD.gss_id;
    IF anzahl=0 THEN
        DELETE FROM altlast.byta WHERE byta_id=OLD.byta_id;
    END IF;
    RETURN OLD;
END;$$;


