-- Name: _dev_pool_dummy(text); Type: FUNCTION; Schema: altlast; Owner: -
--

CREATE FUNCTION altlast._dev_pool_dummy(bez text) RETURNS void
    LANGUAGE plpgsql
    AS $$ 
DECLARE
	poolid integer;
	sql character varying;
BEGIN	

/*
SELECT altlast._dev_pool_dummy('mydummy3');
SELECT * FROM altlast.pool WHERE bezeichnung in ('mydummy','mydummy2');
DELETE FROM altlast.pool WHERE pool_id > 74 ;
SELECT * FROM altlast.obje_pool WHERE pool_id > 74 ORDER BY obje_id;

SELECT * FROM (SELECT DISTINCT ON (r.c_typ,r.c_bearbstand,r.c_bewe) 99,obje_id
FROM altlast.obje o JOIN altlast.vflz v USING (obje_id) JOIN altlast.bere b USING(vflz_id) 
JOIN altlast.rpt_variants r ON r.c_typ=v.c_vflz_vftyp AND r.c_bearbstand=v.c_vflz_bearbstand AND r.c_bewe=b.c_bere_res_abwbewe
WHERE r.vorlage<>'undefined' ) foo
ORDER BY (SELECT COUNT(*) FROM altlast.obje_pool op WHERE op.obje_id=foo.obje_id) ASC;
*/

	INSERT INTO altlast.pool (bezeichnung) VALUES (bez);
	SELECT pool_id INTO poolid FROM altlast.pool WHERE bezeichnung=bez;
	

	sql := 'INSERT INTO altlast.obje_pool (pool_id,obje_id) 
	SELECT DISTINCT ON (c_typ,c_bearbstand,c_bewe) pool_id,obje_id FROM (
	SELECT r.c_typ,r.c_bearbstand,r.c_bewe, '||poolid::text||' AS pool_id,obje_id
	FROM altlast.obje o JOIN altlast.vflz v USING (obje_id) JOIN altlast.bere b USING(vflz_id) 
	JOIN altlast.rpt_variants r ON r.c_typ=v.c_vflz_vftyp AND r.c_bearbstand=v.c_vflz_bearbstand AND r.c_bewe=b.c_bere_res_abwbewe
	WHERE r.vorlage<>''undefined''
	/*hilft nix ORDER BY (SELECT COUNT(*) FROM altlast.obje_pool op WHERE op.obje_id=obje_id) ASC */
	) foo 
	;
	;';

	 EXECUTE sql;		
		
 		
END;
$$;


--
-- Name: _export_cfgtask_dependeny_check(); Type: FUNCTION; Schema: altlast; Owner: -
--

CREATE FUNCTION altlast._export_cfgtask_dependeny_check() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
    an_invalidly_referenced_export_cfgtask_id integer;
BEGIN
    select export_cfgtask_id into an_invalidly_referenced_export_cfgtask_id
    from (
        select altlast.explode_array(depends) as export_cfgtask_id
        from altlast_admin.export_cfgtask
        except
        select export_cfgtask_id
        from altlast_admin.export_cfgtask
    ) invalidly_referenced_export_cfgtask_ids
    limit 1;

    if an_invalidly_referenced_export_cfgtask_id is not null then
        raise exception 'A task depends on the not existing task %.', an_invalidly_referenced_export_cfgtask_id;
    end if;

    if TG_OP='DELETE' then
        return OLD;
    else
        return NEW;
    end if;
end$$;


--
-- Name: FUNCTION _export_cfgtask_dependeny_check(); Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON FUNCTION altlast._export_cfgtask_dependeny_check() IS 'Verifies that no task depends on missing tasks.';


--
-- Name: _fts_bem(); Type: FUNCTION; Schema: altlast; Owner: -
--

CREATE FUNCTION altlast._fts_bem() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
	_id integer;
	_bemgrp_id integer;
BEGIN
	if TG_OP='DELETE' then
		-- an update on a not existing row will delete it
		_id := old.key_value;
		_bemgrp_id := old.bemgrp_id;
	else
		_id := new.key_value;
		_bemgrp_id := new.bemgrp_id;
	end if;

	
	-- update the FTS
	perform altlast.fts_vflz_collect(vflz_id)
		from (
			-- stao referencing bems
			select _id as vflz_id
				from altlast.bemgrp 
				where bemgrp_id = _bemgrp_id
					and bemgrp.key_column = 'vflz_id'
					and bemgrp.rel_name = 'vflz'
			union
			-- pm_cache referencing bems
			select v.vflz_id as vflz_id
				from altlast.bemgrp, altlast.vflz v
				join altlast.pm_vfl pmv on v.vfl_id = pmv.vfl_id
				join altlast.pm_cache pmc on pmc.pm_vfl_id = pmv.pm_vfl_id
				where bemgrp_id = _bemgrp_id
					and bemgrp.key_column = 'pm_cache_id'
					and bemgrp.rel_name = 'pm_cache'
					and pmc.pm_cache_id = _id
			union
			-- intb referencing
			select i.vflz_id
				from altlast.bemgrp, altlast.intb i
				where bemgrp_id = _bemgrp_id
					and bemgrp.key_column = 'intb_id'
					and bemgrp.rel_name = 'intb'
					and i.intb_id = _id
			union
			-- inta referencing
			select i.vflz_id
				from altlast.bemgrp, altlast.inta i
				where bemgrp_id = _bemgrp_id
					and bemgrp.key_column = 'inta_id'
					and bemgrp.rel_name = 'inta'
					and i.inta_id = _id
			union
			-- intu referencing
			select i.vflz_id
				from altlast.bemgrp, altlast.intu i
				where bemgrp_id = _bemgrp_id
					and bemgrp.key_column = 'intu_id'
					and bemgrp.rel_name = 'intu'
					and i.intu_id = _id
		) foo
		where foo.vflz_id is not null -- reduce workload
		group by foo.vflz_id;

	if TG_OP='DELETE' then
		return old;
	else 
		return new;
	end if;
END;$$;


