--
-- Name: _fts_pm_cache(); Type: FUNCTION; Schema: altlast; Owner: -
--

CREATE FUNCTION altlast._fts_pm_cache() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
	 _id integer;
BEGIN
	if TG_OP='DELETE' then
		-- an update on a not existing pm_cache will delete it
		_id := old.pm_vfl_id;
	else
		_id := new.pm_vfl_id;
	end if;

	-- update the FTS
	perform altlast.fts_vflz_collect(v.vflz_id)
		from altlast.vflz_current_v v
		join altlast.pm_vfl pmv on v.vfl_id=pmv.vfl_id
		where pmv.pm_vfl_id = _id
		group by v.vflz_id;

	if TG_OP='DELETE' then
		return old;
	else
		return new;
	end if;
END;$$;


--
-- Name: _fts_pm_content(); Type: FUNCTION; Schema: altlast; Owner: -
--

CREATE FUNCTION altlast._fts_pm_content() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
	 _id text;
	 _con_category text;
BEGIN
	if TG_OP='DELETE' then
		-- an update on a not existing pm_content will delete it
		_id := old.con_id;
		_con_category := old.con_category;
	else
		_id := new.con_id;
		_con_category := new.con_category;
	end if;

	-- update the FTS -- all vflz_ids which have a process/task
	-- with that content_value --- update might take a while
	perform altlast.fts_vflz_collect(foo.vflz_id)
		from (
			-- processes
			select v.vflz_id
				from altlast.vflz v
				join altlast.pm_vfl pmv on pmv.vfl_id=v.vfl_id
				where pmv.pro_uid = _id and _con_category like 'PRO_%'
			union
			-- tasks
			select v.vflz_id
				from altlast.vflz v
				join altlast.pm_vfl pmv on pmv.vfl_id=v.vfl_id
				join altlast.pm_cache pmc on pmc.pm_vfl_id = pmv.pm_vfl_id
				where pmc.tas_uid = _id and _con_category like 'TAS_%'
		) foo
		where foo.vflz_id is not null
		group by foo.vflz_id;

	if TG_OP='DELETE' then
		return old;
	else 
		return new;
	end if;
END;$$;


