--
-- Name: _inta_zeitraum(); Type: FUNCTION; Schema: altlast; Owner: -
--

CREATE FUNCTION altlast._inta_zeitraum() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  bis date;
  von date;
  bisheute boolean;
  bisjahr boolean;
  vonjahr boolean;
  vflzid integer;
  retrec record;
BEGIN

    IF TG_OP = 'DELETE' THEN
      vflzid := OLD.vflz_id;
      retrec := OLD;
    ELSE
      retrec := NEW;
      vflzid := NEW.vflz_id;
    END IF;
    
    SELECT altlast.zeitraum_von(inta_ablag_von::date) INTO von FROM altlast.inta WHERE vflz_id=vflzid;
    SELECT altlast.zeitraum_bis(inta_ablag_bis::date,zeitraum_bisheute::boolean) INTO bis FROM altlast.inta WHERE vflz_id=vflzid;
    SELECT altlast.zeitraum_von_jahr(inta_ablag_von::date,zeitraum_vonjahr::boolean) INTO vonjahr FROM altlast.inta WHERE vflz_id=vflzid;
    SELECT altlast.zeitraum_bis_jahr(inta_ablag_bis::date,zeitraum_bisjahr::boolean,zeitraum_bisheute::boolean) INTO bisjahr FROM altlast.inta WHERE vflz_id=vflzid;
    SELECT altlast.zeitraum_bis_heute(zeitraum_bisheute::boolean) INTO bisheute FROM altlast.inta WHERE vflz_id=vflzid;

    UPDATE altlast.vflz SET zeitraum_bis=bis, zeitraum_von=von, zeitraum_vonjahr=vonjahr, zeitraum_bisjahr=bisjahr, zeitraum_bisheute=bisheute WHERE vflz_id=vflzid;
    
    RETURN retrec;
END;$$;


--
-- Name: FUNCTION _inta_zeitraum(); Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON FUNCTION altlast._inta_zeitraum() IS 'Trigger update of zeitraum in vflz';


