--
-- Name: _intb_zeitraum(); Type: FUNCTION; Schema: altlast; Owner: -
--

CREATE FUNCTION altlast._intb_zeitraum() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  vflzid integer;
  retrec record;
BEGIN

    IF TG_OP = 'DELETE' THEN
        vflzid := OLD.vflz_id;
        retrec := OLD;
    ELSE
        vflzid := NEW.vflz_id;
        retrec := NEW;
    END IF;

    UPDATE altlast.vflz SET zeitraum_bis=variables.bis, zeitraum_von=variables.von, zeitraum_vonjahr=variables.vonjahr, zeitraum_bisjahr=variables.bisjahr, zeitraum_bisheute=variables.bisheute
    from (
        select * from (
            select vflz_id, 
                    altlast.zeitraum_von(intb_vonbetrieb::date) as von,
                    altlast.zeitraum_bis(intb_bisbetrieb::date,zeitraum_bisheute::boolean) as bis,
                    altlast.zeitraum_von_jahr(intb_vonbetrieb::date,zeitraum_vonjahr::boolean) as vonjahr,
                    altlast.zeitraum_bis_jahr(intb_bisbetrieb::date,zeitraum_bisjahr::boolean,zeitraum_bisheute::boolean) as bisjahr,
                    altlast.zeitraum_bis_heute(zeitraum_bisheute::boolean) as bisheute,
                    1::int4 as order_prio
            FROM altlast.intb
            WHERE vflz_id=vflzid
                AND relevant
            group by vflz_id
            union
            select vflz_id, 
                    altlast.zeitraum_von(intb_vonbetrieb::date) as von,
                    altlast.zeitraum_bis(intb_bisbetrieb::date,zeitraum_bisheute::boolean) as bis,
                    altlast.zeitraum_von_jahr(intb_vonbetrieb::date,zeitraum_vonjahr::boolean) as vonjahr,
                    altlast.zeitraum_bis_jahr(intb_bisbetrieb::date,zeitraum_bisjahr::boolean,zeitraum_bisheute::boolean) as bisjahr,
                    altlast.zeitraum_bis_heute(zeitraum_bisheute::boolean) as bisheute,
                    2::int4 as order_prio
            FROM altlast.intb
            WHERE vflz_id=vflzid
            group by vflz_id
            union
            select vflzid, 
                    NULL,
                    NULL, 
                    FALSE, 
                    FALSE, 
                    FALSE,
                    567::int4 as order_prio
        ) yui
        order by yui.order_prio
        limit 1
    ) variables
    WHERE vflz.vflz_id=variables.vflz_id;

    RETURN retrec;
END;$$;


--
-- Name: FUNCTION _intb_zeitraum(); Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON FUNCTION altlast._intb_zeitraum() IS 'Trigger update of zeitraum in vflz';


