--
-- Name: _intu_zeitraum(); Type: FUNCTION; Schema: altlast; Owner: -
--

CREATE FUNCTION altlast._intu_zeitraum() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  von date;
  vonjahr boolean;
  vflzid integer;
  retrec record;
BEGIN

    IF TG_OP = 'DELETE' THEN
      vflzid := OLD.vflz_id;
      retrec := OLD;
    ELSE
      vflzid := NEW.vflz_id;
      retrec := NEW;
    END IF;
    
    SELECT altlast.zeitraum_von(intu_unfallvon::date) INTO von FROM altlast.intu WHERE vflz_id=vflzid;
    SELECT altlast.zeitraum_von_jahr(intu_unfallvon::date,zeitraum_jahr::boolean) INTO vonjahr FROM altlast.intu WHERE vflz_id=vflzid;

    UPDATE altlast.vflz SET zeitraum_bis=NULL, zeitraum_von=von, zeitraum_vonjahr=vonjahr WHERE vflz_id=vflzid;
    
    RETURN retrec;
END;$$;


