--

COMMENT ON FUNCTION altlast._intu_zeitraum() IS 'Trigger update of zeitraum in vflz';


--
-- Name: _kksk_zeitraum(); Type: FUNCTION; Schema: altlast; Owner: -
--

CREATE FUNCTION altlast._kksk_zeitraum() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  bis date;
  von date;
  bisheute boolean;
  bisjahr boolean;
  vonjahr boolean;
  intaid integer;
  retrec record;
BEGIN

    IF TG_OP = 'DELETE' THEN
      intaid := OLD.inta_id;
      retrec := OLD;
    ELSE
      intaid := NEW.inta_id;
      retrec := NEW;
    END IF;
    
    SELECT altlast.zeitraum_von(kksk_ablag_von::date) INTO von FROM altlast.kksk WHERE inta_id=intaid;
    SELECT altlast.zeitraum_bis(kksk_ablag_bis::date,zeitraum_bisheute::boolean) INTO bis FROM altlast.kksk WHERE inta_id=intaid;
    SELECT altlast.zeitraum_von_jahr(kksk_ablag_von::date,zeitraum_vonjahr::boolean) INTO vonjahr FROM altlast.kksk WHERE inta_id=intaid;
    SELECT altlast.zeitraum_bis_jahr(kksk_ablag_bis::date,zeitraum_bisjahr::boolean,zeitraum_bisheute::boolean) INTO bisjahr FROM altlast.kksk WHERE inta_id=intaid;
    SELECT altlast.zeitraum_bis_heute(zeitraum_bisheute::boolean) INTO bisheute FROM altlast.kksk WHERE inta_id=intaid;

    --update only cells without data
    UPDATE altlast.inta SET inta_ablag_bis=bis, zeitraum_bisjahr=bisjahr, zeitraum_bisheute=bisheute 
    WHERE inta_ablag_bis IS NULL AND zeitraum_bisheute=FALSE AND inta_id=intaid;
    UPDATE altlast.inta SET inta_ablag_von=von, zeitraum_vonjahr=vonjahr 
    WHERE inta_ablag_von IS NULL AND inta_id=intaid;    
    
    RETURN retrec;
END;$$;


--
-- Name: FUNCTION _kksk_zeitraum(); Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON FUNCTION altlast._kksk_zeitraum() IS 'Trigger update of zeitraum in inta';


--
-- Name: _materialize_gemeindeort_v(); Type: FUNCTION; Schema: altlast; Owner: -
--

CREATE FUNCTION altlast._materialize_gemeindeort_v() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
DECLARE
    where_fragment_delete text;
    where_fragment_insert text;
BEGIN

    if TG_RELNAME = 'h_ort' then
        if TG_OP = 'DELETE' then
            where_fragment_delete := 'h_ort ='||old.h_ort_id::text;
            where_fragment_insert := 'o.h_ort_id ='||old.h_ort_id::text;
        else
            where_fragment_delete := 'h_ort ='||new.h_ort_id::text;
            where_fragment_insert := 'o.h_ort_id ='||new.h_ort_id::text;
        end if;
    elsif TG_RELNAME = 'h_gem' then
        if TG_OP = 'DELETE' then
            where_fragment_delete := 'h_gem_id ='||old.h_gem_id::text;
            where_fragment_insert := 'g.h_gem_id ='||old.h_gem_id::text;
        else
            where_fragment_delete := 'h_gem_id ='||new.h_gem_id::text;
            where_fragment_insert := 'g.h_gem_id ='||new.h_gem_id::text;
        end if;
    else
        raise exception 'unsupported table: %', TG_RELNAME;
    end if;

    if where_fragment_insert is not null and where_fragment_delete is not null then

        execute 'DELETE FROM altlast.gemeindeort_v where '||where_fragment_delete;

        execute $s$INSERT INTO altlast.gemeindeort_v SELECT DISTINCT g.h_gem_id, o.h_ort_id, g.gemeinde, o.ortsname,
                CASE
                    WHEN g.gemeinde::text <> o.ortsname::text THEN ((g.gemeinde::text || ' - '::text) || o.ortsname::text)::character varying
                    ELSE g.gemeinde
                END AS gemeindeort, o.postleitzahl,
                CASE
                    WHEN o.postleitzahl_zusatz > 0 THEN o.postleitzahl_zusatz
                    ELSE NULL::smallint
                END AS "case"
           FROM altlast.h_ort o
           JOIN altlast.h_gem g ON g.h_gem_id = o.h_gem_id
           WHERE $s$ || where_fragment_insert || $s$
          ORDER BY
           CASE
               WHEN g.gemeinde::text <> o.ortsname::text THEN ((g.gemeinde::text || ' - '::text) || o.ortsname::text)::character varying
               ELSE g.gemeinde
           END, g.h_gem_id, o.h_ort_id, g.gemeinde, o.ortsname, o.postleitzahl,
           CASE
               WHEN o.postleitzahl_zusatz > 0 THEN o.postleitzahl_zusatz
               ELSE NULL::smallint
           END;$s$;

    else
        raise exception 'no where fragment given - this trigger has propably been called from an unsupported table';
    end if;
    RETURN NULL;
END;$_$;


--
-- Name: FUNCTION _materialize_gemeindeort_v(); Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON FUNCTION altlast._materialize_gemeindeort_v() IS 'Erstellt Materialized view aus Gemeinde/Ort. Getriggert aus h_gem und h_ort.';


--
-- Name: _materialize_gs_subj_all_v(); Type: FUNCTION; Schema: altlast; Owner: -
--

CREATE FUNCTION altlast._materialize_gs_subj_all_v() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  docontinue boolean;
BEGIN

IF TG_OP = 'DELETE' THEN

  --subj ist uber Cascade Delete bereits integriert
  IF TG_RELNAME='subj' THEN
    DELETE FROM altlast.subj_kennung_v WHERE subj_id=OLD.subj_id;
  END IF;     

  RETURN  OLD;

ELSE

  IF TG_RELNAME='subj' THEN
    docontinue:=TG_OP='INSERT';
    IF NOT docontinue THEN
      docontinue := (NEW.name is distinct from OLD.name) OR (NEW.vorname is distinct from OLD.vorname) OR (NEW.taetigkeit is distinct from OLD.taetigkeit);
    END IF;
    IF docontinue THEN
      INSERT INTO altlast.subj_kennung_v (subj_id,subj_kennung) VALUES (NEW.subj_id, altlast.concat_subj(NEW.name::text, NEW.vorname::text, NEW.taetigkeit::text));
    END IF;
  END IF;

  RETURN NEW;

END IF;


END;$$;


--
-- Name: FUNCTION _materialize_gs_subj_all_v(); Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON FUNCTION altlast._materialize_gs_subj_all_v() IS 'Maintains entries in altlast.subj_kennung_v.';


--
-- Name: _materialize_vflz_parzellen_v(); Type: FUNCTION; Schema: altlast; Owner: -
--

CREATE FUNCTION altlast._materialize_vflz_parzellen_v() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
	do_delete boolean;
	do_insert boolean;
	return_rec record;
	cnt integer;
BEGIN

    do_delete := false;
    do_insert := false;
    return_rec := NULL;

    if TG_OP = 'DELETE' then
	    do_delete := true;
	    return_rec := old;
    elseif TG_OP = 'UPDATE' then
        do_delete := true;
        do_insert := true;

       if TG_RELNAME = 'grun' then
       	    if st_isvalid(old.wkb_geometry) and st_isvalid(new.wkb_geometry)  then
		    -- only do something when the geometry has changed, or the gb_nummer or h_gem_id have changed
		    do_delete := (not (st_equals(new.wkb_geometry::geometry ,old.wkb_geometry::geometry)::boolean)) or 
		                 ((old.gb_nummer<>new.gb_nummer or old.h_gem_id<>new.h_gem_id)::boolean);
		    do_insert := do_delete;
            end if;
       elseif TG_RELNAME = 'vflgeo' then
       	    if st_isvalid(old.wkb_geometry) and st_isvalid(new.wkb_geometry)  then
		    -- only do something when the geometry has changed
		    do_delete := not (st_equals(new.wkb_geometry::geometry ,old.wkb_geometry::geometry)::boolean);
		    do_insert := do_delete;
	    end if;
        end if;

        return_rec := new;
    elseif TG_OP = 'INSERT' then
        do_insert := true;
        return_rec := new;
    end if;


    if TG_RELNAME = 'vflgeo' then

	    if do_delete then
	    	insert into altlast_admin.cronjob (cronjob_name, cronjob_data) select 'materialize_vflz_parzellen', old.vflz_id::text
	    		where not exists ( select cronjob_name from altlast_admin.cronjob where cronjob_name = 'materialize_vflz_parzellen'
	    		and cronjob_data = old.vflz_id::text);
		    insert into altlast._log_vflz_parzellen_v (log) VALUES (TG_RELNAME||':'||TG_OP||' deleting old.vflz_id = '||old.vflz_id::text);
	    end if;

	    if do_insert then
	    	insert into altlast_admin.cronjob (cronjob_name, cronjob_data) select 'materialize_vflz_parzellen', new.vflz_id::text
	    		where not exists ( select cronjob_name from altlast_admin.cronjob where cronjob_name = 'materialize_vflz_parzellen'
	    		and cronjob_data = new.vflz_id::text);
			insert into altlast._log_vflz_parzellen_v (log) VALUES (TG_RELNAME||':'||TG_OP||' inserting new.vflz_id = '||new.vflz_id::text);
	    end if;


elseif TG_RELNAME = 'grun' then

	   if do_delete then
		    delete from altlast.vflz_parzellen_v
			    using altlast.grun g
                join altlast.vflgeo vg on st_isvalid(vg.wkb_geometry) AND st_isvalid(g.wkb_geometry)
                    AND st_intersects(vg.wkb_geometry, g.wkb_geometry)
			    where g.grun_id = old.grun_id and old.grun_id is not null and vflz_parzellen_v.vflz_id = vg.vflz_id;
        	insert into altlast._log_vflz_parzellen_v (log) VALUES (TG_RELNAME||':'||TG_OP||' deleting old.grun_id = '||old.grun_id::text);
	    end if;

	    if do_insert then
			insert into altlast.vflz_parzellen_v (vflz_id, h_gem_id, parzellen)
				select vpm.vflz_id, vpm.h_gem_id, altlast.commacat_all(vpm.gb_nummer::text) AS parzellen
	                from altlast.vflz_parzellen_materialization_v vpm
				    left join altlast.vflz_parzellen_v vpv2 on vpm.vflz_id = vpv2.vflz_id
					    and vpv2.h_gem_id = vpm.h_gem_id
				    where vpv2.parzellen is null and vpm.grun_id = new.grun_id
					GROUP BY vpm.h_gem_id, vpm.vflz_id;
        	insert into altlast._log_vflz_parzellen_v (log) VALUES (TG_RELNAME||':'||TG_OP||' inserting new.grun_id = '||new.grun_id::text);
	    end if;


    elseif TG_RELNAME like 'subj_vflz%' then

	   if do_delete then
		    delete from altlast.vflz_parzellen_v
			    using altlast.subj_vflz
			    where vflz_parzellen_v.vflz_id = subj_vflz.vflz_id
				    and subj_vflz.subj_vflz_id = old.subj_vflz_id and old.subj_vflz_id is not null;
        	insert into altlast._log_vflz_parzellen_v (log) VALUES (TG_RELNAME||':'||TG_OP||' deleting old.subj_vflz_id = '||old.subj_vflz_id::text);
	    end if;

	    if do_insert then
		-- Inserts do only insert those parcels correctly for which the same h_gem_id does not yet exist for the location
			delete from altlast.vflz_parzellen_v where vflz_id=(select vflz_id from altlast.subj_vflz where subj_vflz_id = new.subj_vflz_id);

			insert into altlast.vflz_parzellen_v (vflz_id, h_gem_id, parzellen)
				select vpm.vflz_id, vpm.h_gem_id, altlast.commacat_all(vpm.gb_nummer::text) AS parzellen
	                from altlast.vflz_parzellen_materialization_v vpm
				    left join altlast.vflz_parzellen_v vpv2 on vpm.vflz_id = vpv2.vflz_id
	                    and vpv2.h_gem_id = vpm.h_gem_id
				    where vpv2.parzellen is null
	                    and vpm.vflz_id = (select vflz_id from altlast.subj_vflz where subj_vflz_id = new.subj_vflz_id) -- use subquery to force index usage
					GROUP BY vpm.h_gem_id, vpm.vflz_id;
	        insert into altlast._log_vflz_parzellen_v (log) VALUES (TG_RELNAME||':'||TG_OP||' inserting new.subj_vflz_id = '||new.subj_vflz_id::text);
	    end if;
    

else
	raise exception 'this function [_materialize_vflz_parzellen_v] does not handle the table %', TG_RELNAME;
end if;
	

    RETURN return_rec;
END;$$;


--
-- Name: FUNCTION _materialize_vflz_parzellen_v(); Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON FUNCTION altlast._materialize_vflz_parzellen_v() IS 'Trigger used to materialize vflz_parzellen_v when a single record of vflgeo or subj_vflz changes. Assumes there is only one record in vflgeo for each vflz_id. 
To materialize data after changes in grun, call materialize_vflz_parzellen_v once after all changes in grun are through.';


--
-- Name: _mutation(); Type: FUNCTION; Schema: altlast; Owner: -
--

CREATE FUNCTION altlast._mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    NEW.mutierer_kuerzel:=current_user;
    NEW.mutations_datum:=now()::timestamp without time zone;
    RETURN NEW;
END;$$;


--
-- Name: _nullstring_subj(); Type: FUNCTION; Schema: altlast; Owner: -
--

CREATE FUNCTION altlast._nullstring_subj() RETURNS trigger
    LANGUAGE plpgsql
    AS $$

BEGIN

    IF NEW.name='' THEN
        NEW.name=NULL;
    END IF;
    
    IF NEW.vorname='' THEN
        NEW.vorname=NULL;
    END IF;

    IF NEW.taetigkeit='' THEN
        NEW.taetigkeit=NULL;
    END IF;
    
    RETURN NEW;
END;$$;


