-- Name: _sync_vflz_parzellen_v(); Type: FUNCTION; Schema: altlast; Owner: -
--

CREATE FUNCTION altlast._sync_vflz_parzellen_v() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
	DELETE FROM altlast.vflz_parzellen_v;
	INSERT INTO altlast.vflz_parzellen_v
	SELECT vflz_id, h_gem_id, string_agg(parcel,', ') 
	FROM altlast.vflz_parcels_v
	GROUP BY vflz_id, h_gem_id;
        return NEW;
END;$$;


--
-- Name: FUNCTION _sync_vflz_parzellen_v(); Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON FUNCTION altlast._sync_vflz_parzellen_v() IS 'Trigger used to materialize vflz_parzellen_v when a single record of vflgeo or subj_vflz changes. Assumes there is only one record in vflgeo for each vflz_id.
To materialize data after changes in grun, call materialize_vflz_parzellen_v once after all changes in grun are through.';


