--
-- Name: _update_vflgeo_geometry(); Type: FUNCTION; Schema: altlast; Owner: -
--

CREATE FUNCTION altlast._update_vflgeo_geometry() RETURNS trigger
    LANGUAGE plpgsql
    AS $$DECLARE
    asql VARCHAR;
    centroid RECORD;
    koordinaten RECORD;
BEGIN

SELECT x_koordinate as x, y_koordinate as y FROM altlast.vflz WHERE vflz_id = NEW.vflz_id INTO koordinaten;

IF koordinaten.x IS NULL AND koordinaten.y IS NULL THEN

    SELECT INTO centroid ST_X(ST_Centroid(NEW.wkb_geometry)) AS x, ST_Y(ST_Centroid(NEW.wkb_geometry)) AS y;

    asql := 'UPDATE altlast.vflz SET x_koordinate='||centroid.x||', y_koordinate='||centroid.y;
    asql := asql || ' WHERE vflz_id=' || NEW.vflz_id;
    EXECUTE asql;
END IF;

NEW.wkb_geometry = ST_Reverse(ST_ForceRHR(NEW.wkb_geometry));

RETURN NEW;
END;$$;


--
-- Name: FUNCTION _update_vflgeo_geometry(); Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON FUNCTION altlast._update_vflgeo_geometry() IS 'Aktualisiert die Koordinaten in altlast.vflz, falls diese nicht vorhanden sind.';


--
-- Name: _vflnr_check_aktiv(); Type: FUNCTION; Schema: altlast; Owner: -
--

CREATE FUNCTION altlast._vflnr_check_aktiv() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
     prevent BOOLEAN;
BEGIN
    prevent = false;

    -- Updates are handled in _vflnr_to_vflz_combined_id_kt trigger

    IF (TG_OP='DELETE') THEN  
        IF OLD.aktiv=TRUE THEN
            SELECT COUNT(*)=0 INTO prevent
            FROM altlast.vflnr
            WHERE vflz_id=OLD.vflz_id AND vflnr_id<>OLD.vflnr_id and aktiv;
        END IF;
    END IF;

    -- Allow all deletions if the referrenced vflz was deleted (happens when this trigger is called in response to a cascade delete on vflz)
    if prevent then
    select exists(
        select vflz_id from altlast.vflz where vflz_id=OLD.vflz_id
    ) into prevent;
    end if;

    IF prevent THEN 
         RAISE EXCEPTION 'You need at least one active number';            
    END IF;

    RETURN OLD;
END;$$;


--
-- Name: FUNCTION _vflnr_check_aktiv(); Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON FUNCTION altlast._vflnr_check_aktiv() IS 'Make sure, at least one number per standort is active';


--
-- Name: _vflnr_to_vflz_combined_id_kt(); Type: FUNCTION; Schema: altlast; Owner: -
--

CREATE FUNCTION altlast._vflnr_to_vflz_combined_id_kt() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  doit BOOLEAN;
  cnt integer;
BEGIN
    doit := (TG_OP='INSERT');
    IF (TG_OP='UPDATE') THEN
         doit := ((NEW.aktiv<>OLD.aktiv OR NEW.org_id<>OLD.org_id OR NEW.nummer<>OLD.nummer) );
    END IF;
    IF doit THEN

        IF NEW.aktiv=TRUE THEN
            UPDATE altlast.vflnr SET aktiv=FALSE WHERE vflz_id=NEW.vflz_id AND vflnr_id<>NEW.vflnr_id;
        ELSE
            -- do not throw exceptions here as the condition will eventually not be correct
            -- when the trigger is called during a historization.
            -- simply emit a notice
            SELECT COUNT(*) INTO cnt FROM altlast.vflnr WHERE vflz_id=NEW.vflz_id AND vflnr_id<>NEW.vflnr_id AND aktiv=TRUE;
            IF (cnt=0) THEN
                 RAISE NOTICE 'You need at least one active vflnr.number';
            END IF;
        END IF;
            
            UPDATE altlast.vflz SET vflz_combined_id_kt=COALESCE(bav_nummer,COALESCE(akt_nummer,alt_nummer)) FROM
            (select vflnr.vflz_id,bavnr.nummer as bav_nummer, aktnr.nummer as akt_nummer, altnr.nummer as alt_nummer
            FROM altlast.vflnr
            LEFT JOIN (select * from altlast.vflnr where org_id=40) bavnr  on vflnr.vflz_id=bavnr.vflz_id
            LEFT JOIN (select * from altlast.vflnr where coalesce(aktiv,false)=true and coalesce(org_id,0)<>40) aktnr  on vflnr.vflz_id=aktnr.vflz_id     
            LEFT JOIN (select * from altlast.vflnr where coalesce(aktiv,false)=false and coalesce(org_id,0)<>40) altnr on vflnr.vflz_id=altnr.vflz_id
            ) foo
            WHERE vflz.vflz_id=NEW.vflz_id and foo.vflz_id=NEW.vflz_id;

        END IF;
    RETURN NEW;
END;$$;


--
-- Name: FUNCTION _vflnr_to_vflz_combined_id_kt(); Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON FUNCTION altlast._vflnr_to_vflz_combined_id_kt() IS 'When field aktiv is TRUE:
- Synchronizes new number into vflz.vflz_combined_id_kt
- special logic BAV here
- Sets all other entries to false

When aktiv is FALSE:
- check there is ';


--
-- Name: _vflz_dat_publizieren(); Type: FUNCTION; Schema: altlast; Owner: -
--

CREATE FUNCTION altlast._vflz_dat_publizieren() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  inkbs BOOLEAN;
BEGIN
    /* 
    * Reacts only on update.
    * This should be enough, if we assume, that
    * inserts always bring the correct dat_publizieren
    */
    IF TG_OP='UPDATE' THEN
        IF coalesce(NEW.publizieren, false)=TRUE AND coalesce(NEW.rechtskraft, false)=FALSE THEN
            -- Only prohibit publication of not legally binding location ratings that are in KbS
            -- TODO: Check if all ratings should lead to the exception upon next client request for changes to this function
            SELECT COALESCE(kbs,FALSE) INTO inkbs FROM altlast.bere_v WHERE vflz_id=NEW.vflz_id;
            IF inkbs=TRUE THEN
                RAISE EXCEPTION '%', altlast.t('Belastete nicht rechtskräftige Standorte können nicht zur Publikation freigegeben werden'::text);
            END IF;
        END IF;
        IF coalesce(NEW.publizieren, false)!=coalesce(OLD.publizieren, false) OR NEW.dat_publizieren is distinct from OLD.dat_publizieren  THEN
            IF coalesce(NEW.publizieren, false) =TRUE THEN 
                IF NEW.dat_publizieren IS NULL THEN
                    NEW.dat_publizieren:=now()::date;
                ENd IF;
            ELSE
                NEW.dat_publizieren:=NULL;
            END IF;
        END IF;
    END IF;
    RETURN NEW;
END;$$;


--
-- Name: FUNCTION _vflz_dat_publizieren(); Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON FUNCTION altlast._vflz_dat_publizieren() IS 'Set dat_publizieren when publizieren changes';


--
-- Name: _vflz_dat_rechtskraft(); Type: FUNCTION; Schema: altlast; Owner: -
--

CREATE FUNCTION altlast._vflz_dat_rechtskraft() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    /* 
    * Reacts only on update.
    * This should be enough, if we assume, that
    * inserts always bring the correct dat_rechtskraft
    */
    IF TG_OP='UPDATE' THEN
        IF NEW.rechtskraft!=OLD.rechtskraft OR NEW.dat_rechtskraft!=OLD.dat_rechtskraft THEN
            IF NEW.rechtskraft=TRUE THEN
                IF NEW.dat_rechtskraft IS NULL THEN
                    NEW.dat_rechtskraft=now()::date;
                END IF;
            ELSE
                /*
                *see function rechtskraft(integer): once 
                *rechtskraft is set never change it again.
                *so this condition should only meet after
                *(hopefully rare) manual changes.
                */
                NEW.dat_rechtskraft=NULL;
            END IF;
        END IF;
    END IF;
    RETURN NEW;
END;$$;


--
-- Name: FUNCTION _vflz_dat_rechtskraft(); Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON FUNCTION altlast._vflz_dat_rechtskraft() IS 'Set dat_rechtskraft when rechtskraft changes';


