--
-- Name: bearbstand(integer); Type: FUNCTION; Schema: altlast; Owner: -
--

CREATE FUNCTION altlast.bearbstand(pmvflid integer) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
  rec record;
  res text;
  rescod text;
  cnt integer;
BEGIN


  IF (pmvflid IS NULL) THEN
    res:=NULL;
  ELSE

    FOR rec IN
      SELECT DISTINCT ON(pc.bearbstand) tc.c_vflz_bearbstand
        FROM altlast.pm_vfl pv
        JOIN altlast.pm_cache ch on ch.pm_vfl_id = pv.pm_vfl_id
        JOIN altlast.pm_task t on ch.tas_uid = t.taS_uid
        JOIN altlast.pm_process p on p.pro_uid = pv.pro_uid
        JOIN altlast.pm_processconf pc on pc.pro_uid=p.pro_uid
        JOIN altlast.pm_taskconf tc on tc.tas_uid=t.tas_uid
        LEFT JOIN altlast.cod c ON c.c_cli_id=2001 AND c.code=ch.status
      WHERE ch.status='CLOSED' AND pv.pm_vfl_id=pmvflid AND tc.bearbstand IS NOT NULL AND pc.bearbstand IS NOT NULL ORDER BY pc.bearbstand ASC,tc.bearbstand ASC,ch.tas_delegate_date DESC
    LOOP
      res := rec.c_vflz_bearbstand;
    END LOOP;
  END IF;

  RETURN res;

END;$$;


--
-- Name: FUNCTION bearbstand(pmvflid integer); Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON FUNCTION altlast.bearbstand(pmvflid integer) IS 'Gets c_vflz_bearbstand for current state of a sto. See also function unterstand.';


--
-- Name: bestscalefactor(public.geometry, double precision, double precision); Type: FUNCTION; Schema: altlast; Owner: -
--

CREATE FUNCTION altlast.bestscalefactor(geom public.geometry, targetwidth_cm double precision, targetheight_cm double precision) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
	ex_height double precision; -- height of the geom in projected units
	ex_width double precision; -- width of the geom in projected units
	scalefactors integer[]; -- possible scale factors
	this_sf double precision;
	w_relation double precision; -- width relation of geom and targetwidth_cm
	h_relation double precision; -- height relation of geom and targetheight_cm
	factor integer;
	s_ex double precision;
	t_cm double precision;
	i integer;
BEGIN
    -- get the height and width of the geometry and use a default value if the size is to minimal
    -- like for example when the input geometry is a point
    SELECT ST_Distance(
        ST_MakePoint(ST_XMin(geom),ST_YMin(geom))::geometry,
        ST_MakePoint(ST_XMin(geom),ST_YMax(geom))::geometry)
        INTO ex_height;
    if ex_height < 10 then
        ex_height := 30;
    end if;

    SELECT ST_Distance(
        ST_MakePoint(ST_XMin(geom),ST_YMin(geom))::geometry,
        ST_MakePoint(ST_XMax(geom),ST_YMin(geom))::geometry)
        INTO ex_width;
    if ex_width < 10 then
        ex_width := 30;
    end if;

    -- legal scalefactors. this function will attempt to zoom to the closesd factor
	scalefactors := array[  100,
                            250,
                            500,
                            1000,
                            1500,
                            2000,
                            2500,
                            5000,
                            7500,
                            10000,
                            15000,
                            20000,
                            25000,
                            50000,
                            75000,
                            100000];
	factor := Null;

	w_relation := ex_width/(targetwidth_cm*100.0);
	h_relation := ex_height/(targetheight_cm*100.0);

	IF w_relation>h_relation THEN --scale by width
		s_ex := ex_width;
		t_cm := targetwidth_cm;
	ELSE --scale by height
		s_ex := ex_height;
		t_cm := targetheight_cm;
	END IF;

	FOR i IN SELECT generate_series(array_lower(scalefactors,1),array_upper(scalefactors,1)) LOOP
		this_sf := scalefactors[i]::double precision;

		IF ((this_sf*(t_cm/100.0))/s_ex)>1.0  THEN
			IF i=1 THEN
				factor := scalefactors[1]::integer;
			ELSE
				factor := scalefactors[i]::integer;
			END IF;
			EXIT;
		END IF;

	END LOOP;

	RETURN factor;
END
$$;


--
-- Name: FUNCTION bestscalefactor(geom public.geometry, targetwidth_cm double precision, targetheight_cm double precision); Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON FUNCTION altlast.bestscalefactor(geom public.geometry, targetwidth_cm double precision, targetheight_cm double precision) IS 'Calculate the best scalefactor to display a geometry in a rectangle of targetwidth_cm*targetheight_cm centimeters';


--
-- Name: calc_vflz_combined_id_kt(integer, integer, text); Type: FUNCTION; Schema: altlast; Owner: -
--

CREATE FUNCTION altlast.calc_vflz_combined_id_kt(bfs_nr integer, vflz_laufnr integer, vflz_vfltyp text) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
  res text;
  suf text;
  lnr integer;
BEGIN

  IF vflz_laufnr IS NULL OR vflz_laufnr=0 THEN

    SELECT altlast.next_laufnr(bfs_nr, NULL) INTO lnr;

    IF lnr IS NULL THEN
      SELECT h_gem_id INTO lnr FROM altlast.h_gem WHERE h_gem_id = bfs_nr;
      IF lnr IS NULL THEN
        RAISE EXCEPTION 'Ungueltige Gemeinde-Nummer %',bfs_nr;
      END IF;
      lnr:=0;
    END IF;


  ELSE
    lnr:=vflz_laufnr;
  END IF;
  IF lnr>9999 THEN
    RAISE EXCEPTION 'Laufnummrn > 9999 werden nicht unterstuetzt.';
  END IF;

  IF (vflz_vfltyp IN ('01','03') ) THEN
    suf := '-1';
  ELSE
    suf := '';
  END IF;

  res := 'AA' || TRIM(TO_CHAR(bfs_nr, '0000')) || '.' || TRIM(TO_CHAR(lnr, '0000')) || suf;

  RETURN res;

END
$$;


--
-- Name: FUNCTION calc_vflz_combined_id_kt(bfs_nr integer, vflz_laufnr integer, vflz_vfltyp text); Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON FUNCTION altlast.calc_vflz_combined_id_kt(bfs_nr integer, vflz_laufnr integer, vflz_vfltyp text) IS 'Berechnet Standortnummer nach AG-Schema';


--
-- Name: code_uses(); Type: FUNCTION; Schema: altlast; Owner: -
--

CREATE FUNCTION altlast.code_uses() RETURNS SETOF altlast.code_uses_result
    LANGUAGE plpgsql
    AS $$
  DECLARE
    res altlast.code_uses_result;
    ref_row record;
    code_row record;
    code_uses_query text;
  BEGIN
    FOR ref_row in
        select table_name as relation_name, col as column
        from altlast_admin.cod_references
        where col_count = 2
    LOOP
        code_uses_query := 'select ' || quote_ident('h_'||ref_row.column) || '::integer as c_cli_id, ' || quote_ident('c_'||ref_row.column) || '::text as code
            from altlast.'||ref_row.relation_name
            || ' where ' || quote_ident('c_'||ref_row.column) || ' is not null';

        for code_row in
            execute code_uses_query
        loop
            select ref_row.relation_name, ref_row.column, code_row.c_cli_id::integer, code_row.code::text into res;

            return next res;
        end loop;
    end loop;
return next res;
  END;
$$;


--
-- Name: commacat(text, text); Type: FUNCTION; Schema: altlast; Owner: -
--

CREATE FUNCTION altlast.commacat(acc text, instr text) RETURNS text
    LANGUAGE plpgsql
    AS $$
  BEGIN
    IF acc IS NULL OR acc = '' THEN
      RETURN instr;
    elsif instr is null or instr='' then
      return acc;
    ELSE
      RETURN acc || ', ' || instr;
    END IF;
  END;
$$;


--
-- Name: concat_subj(text, text, text); Type: FUNCTION; Schema: altlast; Owner: -
--

CREATE FUNCTION altlast.concat_subj(name text, vorname text, taetigkeit text) RETURNS text
    LANGUAGE plpgsql STABLE COST 10
    AS $$
  DECLARE
    res text;
  BEGIN
    res := altlast.remove_linebreaks(COALESCE(name||' ',''))||altlast.remove_linebreaks(COALESCE(vorname||' ',''));

    IF res<>'' AND taetigkeit<>'' AND taetigkeit IS NOT NULL THEN
      res := res || ', ';
    END IF;

    res:=res||altlast.remove_linebreaks(COALESCE(taetigkeit,''));
    RETURN res;
  END;
$$;


--
-- Name: FUNCTION concat_subj(name text, vorname text, taetigkeit text); Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON FUNCTION altlast.concat_subj(name text, vorname text, taetigkeit text) IS 'Setzt Name, Vorname und Taetigkeit zu einem String zusammen. Beim Aufruf NULL-Werte ggf. als text parsen, z.B. altlast.concat_subj(''heinze'',NULL::text,''eine taetigkeit'').';


