--
-- Name: db_fill_h_fields(); Type: FUNCTION; Schema: altlast; Owner: -
--

CREATE FUNCTION altlast.db_fill_h_fields() RETURNS void
    LANGUAGE plpgsql
    AS $$ 
DECLARE
	rec RECORD;
	sql character varying;
BEGIN	

 
 FOR rec in SELECT t2s.table_name,t2s.col 
   FROM 
	 (SELECT table_name, col, count(*) as n FROM (Select table_name, substring(column_name,E'[c|h]\\_(.*)') AS col 
		from information_schema.columns 
		WHERE table_schema='altlast' 
		AND column_name SIMILAR TO E'(c|h)\\_%' 
		AND table_name NOT IN 
			(SELECT table_name FROM information_schema.views WHERE table_schema='altlast')
		) AS foo GROUP BY table_name,col) AS t2s WHERE t2s.n=2 LOOP
		
	sql := 'UPDATE altlast.'|| rec.table_name || ' SET h_'|| rec.col || '=DEFAULT WHERE h_'|| rec.col || ' IS NULL';
	 EXECUTE sql;		
		
 END LOOP;
		

 		
END;
$$;


--
-- Name: db_fk_violations(); Type: FUNCTION; Schema: altlast; Owner: -
--

CREATE FUNCTION altlast.db_fk_violations() RETURNS void
    LANGUAGE plpgsql
    AS $$ 
DECLARE
	rec RECORD;
	sql character varying;
BEGIN	

sql := 'CREATE TEMPORARY TABLE fk_violations (table_name varchar,col_name varchar, c_cli_id int2,code varchar);';
EXECUTE sql;
 
 FOR rec in SELECT t2s.table_name,t2s.col 
   FROM 
	 (SELECT table_name, col, count(*) as n FROM (Select table_name, substring(column_name,E'[c|h]\\_(.*)') AS col 
		from information_schema.columns 
		WHERE table_schema='altlast' 
		AND column_name SIMILAR TO E'(c|h)\\_%' 
		AND table_name NOT IN 
			(SELECT table_name FROM information_schema.views WHERE table_schema='altlast')
		) AS foo GROUP BY table_name,col) AS t2s WHERE t2s.n=2 LOOP
		
   sql := 'INSERT INTO fk_violations SELECT '''|| rec.table_name || '''::text,'''|| rec.col || '''::text, h_' || rec.col || '::int2, c_' || rec.col || '::text FROM altlast.' || rec.table_name || ' t WHERE c_' || rec.col || ' IS NOT NULL EXCEPT SELECT ''' || rec.table_name || '''::text,''' || rec.col || '''::text,c_cli_id::int2,code::text FROM altlast.cod';
	 EXECUTE sql;		
		
 END LOOP;
		

 		
END;
$$;


