--
-- Name: fts_plainto_tsquery(text, text); Type: FUNCTION; Schema: altlast; Owner: -
--

CREATE FUNCTION altlast.fts_plainto_tsquery(plain_query text, concatenation text) RETURNS tsquery
    LANGUAGE plpgsql IMMUTABLE COST 500
    AS $_$
-- Parameters:
-- 	plain_query: Text entered by the user. Any asterisk at the end of a word will find any word end
--	concatenation: Text which is used to combine searches for more than one word. Use ' & ' for AND search and ' | ' for OR search
declare
	result tsquery;
begin
	declare
		query text;
	begin
		-- Remove special characters
		-- Note that this should replace something like [^[:alnum:]* ] instead of the following expression
		--     but this fails in Postgres 8.4 independed of set ctype with [:alnum:] always refering to [a-zA-Z0-9] only.
		query := regexp_replace(plain_query, E'[!"#$%&()+,\-./:;<=>?\[\\\]^_`~]', '', 'g');
		-- Remove asterisks at invalid positions
		query := regexp_replace(query, '[*] ', '+ ', 'g');
		query := regexp_replace(query, '[*]$', '+ ', 'g');
		query := regexp_replace(query, '[*]', '', 'g');
		query := regexp_replace(query, '[+]', ':*', 'g');
		-- Replace spaces with ampersands on trimmed string
		query := regexp_replace(query, E'^\\s+', '', 'g');
		query := regexp_replace(query, E'\\s+$', '', 'g');
		query := regexp_replace(query, E'\\s+', concatenation, 'g');

		select to_tsquery(query) into result;
	exception
		-- If upper expressions failed to construct a valid search query, use default function to transfer text to query which does not support placeholders
		when others then
			select plainto_tsquery(plain_query) into result;
	end;
	return result;
end;
$_$;


--
-- Name: fts_translations_reindex(text); Type: FUNCTION; Schema: altlast; Owner: -
--

CREATE FUNCTION altlast.fts_translations_reindex(p_msgid text) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
  declare
    _fts_vflz_id integer;
  BEGIN
    if (select p_msgid ~ E'code\\.\\d+\\..+' as is_code) then
    declare
      _c_cli_id integer;
      _code text;
      _table record;
      query_from text;
      _location record;
      _joins oid[];
      _relation_name text;
    begin
    -- Parse msgid
    select split_part(p_msgid, '.', 2)::integer into _c_cli_id;
    select split_part(p_msgid, '.', 3)::text into _code;

    for _table in
      select distinct relation_name, "column"
      from altlast.code_uses()
      where c_cli_id=_c_cli_id and code::text=_code
    loop
      select array(SELECT oid FROM (
        SELECT oid, CASE WHEN "table" = 'vflz'::name then 1 else 2 end as sort
        FROM altlast.routejoin_oidlookup
        WHERE (schema='altlast' and "table"='vflz') or (schema = 'altlast' and "table"=_table.relation_name)
      ) foo
      ORDER BY sort asc) into _joins;

      if array_length(_joins,1) > 1 then
        -- Get path to table holding value using routejoin
        SELECT altlast.routejoin_route_left(_joins) into _relation_name;

        query_from := 'select distinct vflz.vflz_id from ' || case when _table.relation_name='vflz' then 'altlast.vflz'
          else _relation_name  end
        || ' where ' || quote_ident(_table.relation_name)||'.'||quote_ident('h_'||_table.column) || '=' || quote_nullable(_c_cli_id)
        || ' and ' || quote_ident(_table.relation_name)||'.'||quote_ident('c_'||_table.column) || '=' || quote_nullable(_code);
        --execute query_from into _vflz_id;
        -- update the FTS
        for _location in
          execute query_from
        loop
          perform altlast.fts_vflz_collect(_location.vflz_id);
        end loop;
      end if;
    end loop;

    end;
    return true;
  end  if;
  return false;
 end;
$$;


--
-- Name: FUNCTION fts_translations_reindex(p_msgid text); Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON FUNCTION altlast.fts_translations_reindex(p_msgid text) IS 'Reindex translations for the fulltext search.';


