-- Name: fts_vflz_collect(); Type: FUNCTION; Schema: altlast; Owner: -
--

CREATE FUNCTION altlast.fts_vflz_collect() RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
	delete from altlast.fts_vflz; -- remove all, to get rid of deleted vflzs; use delete instead
		-- of truncat eto mak eal triggers fire 
	perform altlast.fts_vflz_collect(vflz_id) from altlast.vflz;
END;
$$;


--
-- Name: FUNCTION fts_vflz_collect(); Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON FUNCTION altlast.fts_vflz_collect() IS 'Baut den kompletten suchindex der Volltextsuche neu auf';


--
-- Name: fts_vflz_collect(integer); Type: FUNCTION; Schema: altlast; Owner: -
--

CREATE FUNCTION altlast.fts_vflz_collect(p_vflz_id integer) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
  declare
	_fts_vflz_id integer;
  BEGIN
	-- Add location to list of locations due for reindexing if not already in list
	insert into  altlast_admin.cronjob (cronjob_name, cronjob_data, scheduled_at) 
	select 'reindex_fts' as cronjob_name,
		p_vflz_id::text as cronjob_data,
		now() as scheduled_at
	where p_vflz_id::text not in (
		select cronjob_data from altlast_admin.cronjob
		where cronjob_name = 'reindex_fts'
		and process_pid is NULL
		and cronjob_data is not null
	);
	return true;
 end;
$$;


--
-- Name: FUNCTION fts_vflz_collect(p_vflz_id integer); Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON FUNCTION altlast.fts_vflz_collect(p_vflz_id integer) IS 'Adds a location to list of location due for reindexing.';


--
-- Name: fts_vflz_query(text); Type: FUNCTION; Schema: altlast; Owner: -
--

CREATE FUNCTION altlast.fts_vflz_query(searchterms text) RETURNS SETOF altlast.fts_result
    LANGUAGE plpgsql
    AS $$
  DECLARE
     res altlast.fts_result;
     rec record;
     rec2 record;
     andqry tsquery;
     orqry tsquery;
     highlight text;
  BEGIN

    -- generates a query qith all words linked together with "&"
    -- for searching in the main vector content_ts
    SELECT altlast.fts_plainto_tsquery(searchterms, ' & ') INTO andqry;

    -- create a query for finding PARTS of the searchterms in the single vectors
    -- of the fieldvector array; the terms are linked with "|"
    SELECT altlast.fts_plainto_tsquery(searchterms, ' | ') INTO orqry;

    FOR rec IN SELECT cv.vflz_id, cv.fts_vflz_id, max(cv.ranking) as ranking FROM (
                SELECT fts_vflz_id,
			vflz_id,
			rank(content_ts,andqry) AS ranking
                FROM altlast.fts_vflz
                WHERE content_ts @@ andqry) AS cv
            group by vflz_id, fts_vflz_id
            ORDER BY max(cv.ranking) DESC LOOP

	-- aggregate all higlightings in this string
        highlight := '';

        FOR rec2 IN SELECT ff.field_name, headline(ffc.text_content, orqry) as hlight
		from altlast.fts_field_content ffc
		join altlast.fts_vflz fv on fv.fts_vflz_id = ffc.fts_vflz_id
		join altlast.fts_field ff on ffc.fts_field_id = ff.fts_field_id
		where fv.fts_vflz_id = rec.fts_vflz_id
			and fv.fts_vflz_id = rec.fts_vflz_id
			and ffc.content_ts @@ orqry loop
		highlight := highlight || '<div class="highlight_h">' || altlast.t(rec2.field_name) || '</div>'
			|| '<div class="highlight_c">' || rec2.hlight || '</div>';

        END LOOP;

        SELECT rec.vflz_id AS vflz_id,
		rec.ranking,
		highlight INTO res;
        RETURN NEXT res;

    END LOOP;

  END;
$$;


--
-- Name: fts_vflz_query_temp_table(text); Type: FUNCTION; Schema: altlast; Owner: -
--

CREATE FUNCTION altlast.fts_vflz_query_temp_table(searchterms text) RETURNS SETOF altlast.fts_result
    LANGUAGE plpgsql
    AS $$
  DECLARE
     res altlast.fts_result;
     rec record;
     rec2 record;
     andqry tsquery;
     orqry tsquery;
     sql text;
  BEGIN
    -- Returning the upper query directly is really slow for no reason. Using a temporary table helps for common amount of results.
    drop table if exists tmp_fts_result;
    create temporary table tmp_fts_result (vflz_id bigint, ranking real, highlight text);
    sql := 'insert into tmp_fts_result
        select vflz_id::bigint, max(rank(fts_field_content.content_ts, altlast.fts_plainto_tsquery('||quote_literal(searchterms)||', '' & ''))) as ranking, altlast.textcat_all(field_name ||'': ''|| ts_headline(text_content, altlast.fts_plainto_tsquery('||quote_literal(searchterms)||', '' & ''))) as "highlight"
        from altlast.fts_field_content
        join altlast.fts_vflz on fts_vflz.fts_vflz_id=fts_field_content.fts_vflz_id
        join altlast.fts_field on fts_field.fts_field_id=fts_field_content.fts_field_id
        where fts_field_content.content_ts @@ altlast.fts_plainto_tsquery('||quote_literal(searchterms)||', '' & '')
        group by vflz_id
        ;';
         execute sql;

        return query select * from tmp_fts_result;

  END;
$$;


--
-- Name: fts_vflz_reindex(integer); Type: FUNCTION; Schema: altlast; Owner: -
--

CREATE FUNCTION altlast.fts_vflz_reindex(p_vflz_id integer) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
  declare
    _fts_vflz_id integer;
  BEGIN
    -- clean and recreate the fts_vflz row;
    _fts_vflz_id := null;
    delete from altlast.fts_vflz where vflz_id = p_vflz_id;
    insert into altlast.fts_vflz (vflz_id) (
        select vflz_id
        from altlast.vflz
        where vflz_id = p_vflz_id
        limit 1
    ) returning fts_vflz_id into _fts_vflz_id;

    if _fts_vflz_id is null then
        return false; -- vlfz_id does not seem to exist
    end if;

    -- Fetch data from searchfields
    declare
        query_from text;
        searchfield_data record;
        current_text_content record;
        qualified_column_name text;
    begin
    for searchfield_data in
        select label, schema, relation, col_output, c_cli_id, translate_output from (
            select label, split_part(rel_name, '.', 1) as schema, split_part(rel_name, '.', 2) as relation, col_output,
                c_cli_id, translate_output
            from altlast_admin.searchfield
            join altlast_admin.searchfield_searchcategory using(searchfield_id)
            join altlast_admin.searchcategory using(searchcategory_id)
            where searchfield.fts and searchcategory.category_name='Standorte'
        ) sd
        where coalesce(relation, '')!=''
    loop

        -- Get data as referred by current searchfield and add to index if not empty
        qualified_column_name := searchfield_data.schema||'.'||searchfield_data.relation||'.'||searchfield_data.col_output;
        query_from := 'select ';
        if searchfield_data.c_cli_id is null then
            if searchfield_data.translate_output then
                query_from := query_from || 'altlast.t(' || qualified_column_name || ', languages.locale)';
            else
                query_from := query_from || qualified_column_name;
            end if;
        else
            query_from := query_from || 'altlast.t(altlast.msgid_code(' || searchfield_data.c_cli_id
                || ', ' || qualified_column_name || '), languages.locale)';
        end if;
        query_from := query_from || '::text as value from ' || case when searchfield_data.relation='vflz' then 'altlast.vflz' else (
            -- Get path to table holding value using routejoin if value is not within altlast.vflz
            SELECT altlast.routejoin_route_left_cached(Array(
            SELECT oid FROM (
                SELECT
                oid,
                CASE WHEN "table" = 'vflz'::name then 1 else 2 end as sort
                FROM altlast.routejoin_oidlookup
                WHERE (schema='altlast' and "table"='vflz') or (schema = searchfield_data.schema and "table"=searchfield_data.relation)
            ) foo
            ORDER BY sort asc
            ))) end;
        if searchfield_data.translate_output or searchfield_data.c_cli_id is not null then
            -- Add locales only if needed to prevent indexing multiple times

            -- All multilingual content is indexed in all available languages but stored in the same index.
            -- The languages should use separate indices however the simpler approach is considered good-enough for now.
            query_from := query_from || ' cross join (select distinct locale from altlast.translations) languages';
        end if;
        query_from := query_from || ' where altlast.vflz.vflz_id=' || p_vflz_id;
        for current_text_content in
            execute query_from
        loop
            -- Put each textual value in the index. The loop is required since some data fields can occur multiple times
            if current_text_content.value is null or current_text_content.value='' then
                --raise notice 'Skipping % because it''s empty: %', searchfield_data.label, current_text_content.value;
            else
                --raise notice '%: %', searchfield_data.label, current_text_content.value;
                -- Save value into index
                insert into altlast.fts_field_content (
                    fts_vflz_id,
                    fts_field_id,
                    content_ts,
                    text_content)
                select _fts_vflz_id as fts_vflz_id,
                    ff.fts_field_id,
                    to_tsvector(current_text_content.value) as content_ts,
                    current_text_content.value as text_content
                from altlast.fts_field ff
                where ff.field_key = 'searchfield: ' || searchfield_data.label;
            end if;
        end loop;

    end loop;
    end;


    -- accumulate all field vectors in the main vector
    update altlast.fts_vflz set
            content_ts = foo.content_ts
        from (
            select fts_vflz_id, to_tsvector(altlast.commacat_all(text_content)) as content_ts
            from altlast.fts_field_content
            group by fts_vflz_id
            ) foo
        where foo.fts_vflz_id = fts_vflz.fts_vflz_id
            and fts_vflz.fts_vflz_id = _fts_vflz_id;

    return true;
 end;
$$;


--
-- Name: FUNCTION fts_vflz_reindex(p_vflz_id integer); Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON FUNCTION altlast.fts_vflz_reindex(p_vflz_id integer) IS 'Checks a location for violated mandatory fields and updates list of invalid locations';


--
-- Name: get_column_default(information_schema.sql_identifier, information_schema.sql_identifier, information_schema.sql_identifier); Type: FUNCTION; Schema: altlast; Owner: -
--

CREATE FUNCTION altlast.get_column_default(p_table_schema information_schema.sql_identifier, p_table_name information_schema.sql_identifier, p_column_name information_schema.sql_identifier) RETURNS information_schema.character_data
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare
	default_value information_schema.character_data;
  BEGIN
	select column_default into default_value
	from information_schema.columns
	where table_schema=p_table_schema
		and table_name=p_table_name
		and column_name=p_column_name;

	if default_value is null then
		raise exception 'Column %.%.% does not have a default value assigned or does not exist.', p_table_schema, p_table_name, p_column_name;
	end if;
	return default_value;
  END;
$$;


--
-- Name: FUNCTION get_column_default(p_table_schema information_schema.sql_identifier, p_table_name information_schema.sql_identifier, p_column_name information_schema.sql_identifier); Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON FUNCTION altlast.get_column_default(p_table_schema information_schema.sql_identifier, p_table_name information_schema.sql_identifier, p_column_name information_schema.sql_identifier) IS 'Fetches a columns default value';


--
-- Name: get_sachbearbeiter(); Type: FUNCTION; Schema: altlast; Owner: -
--

CREATE FUNCTION altlast.get_sachbearbeiter(OUT subj_id integer, OUT bez_art text) RETURNS record
    LANGUAGE plpgsql
    AS $$
DECLARE
  rec record;
BEGIN
SELECT b.subj_id INTO rec FROM altlast.ben b JOIN altlast.ben_grp bg ON UPPER(b.log_kuerzel)=UPPER(CURRENT_USER) AND b.subj_id=bg.subj_id JOIN altlast.grp g ON g.grp_kuerzel=bg.grp_kuerzel AND UPPER(g.grp_kuerzel)='ALTLAST' LIMIT 1;
    IF (rec.subj_id IS NOT NULL) THEN
      subj_id=rec.subj_id;
      bez_art='10';
    ELSE
      subj_id=NULL;
      bez_art=NULL;
    END IF;
END;
$$;


--
-- Name: FUNCTION get_sachbearbeiter(OUT subj_id integer, OUT bez_art text); Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON FUNCTION altlast.get_sachbearbeiter(OUT subj_id integer, OUT bez_art text) IS 'Nur Personen, die der Gruppe ALTLAST (in altlast.ben) zugewiesen sind, gelten als Sachbearbeiter.';


--
-- Name: hexcolor_to_mapserver(text); Type: FUNCTION; Schema: altlast; Owner: -
--

CREATE FUNCTION altlast.hexcolor_to_mapserver(hexcolor text) RETURNS text
    LANGUAGE plpgsql STABLE
    AS $$
declare
	colortriple integer[3];
begin
    colortriple := altlast.hexcolor_to_mapserver_color_triple(hexcolor);
	return colortriple[1]::text || ' ' || colortriple[2]::text || ' ' || colortriple[3]::text;
end
$$;


--
-- Name: FUNCTION hexcolor_to_mapserver(hexcolor text); Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON FUNCTION altlast.hexcolor_to_mapserver(hexcolor text) IS 'convert a hex color representation to a mapserver compatible one with a string containing three integer values.';


--
-- Name: hexcolor_to_mapserver_color_triple(text); Type: FUNCTION; Schema: altlast; Owner: -
--

CREATE FUNCTION altlast.hexcolor_to_mapserver_color_triple(hexcolor text) RETURNS integer[]
    LANGUAGE plpgsql STABLE
    AS $_$
declare
	thexcolor text;
	result int[3];
begin
	thexcolor := trim(both ' ' from hexcolor);
	if not thexcolor ~ '^#[0-9a-fA-F]{6}$' then
		raise exception 'the given value does not appear to be a valid hex color representation';
	end if;

	-- need to used excute for dynamic casting :(
	execute 'select array[x''' || substring(thexcolor,2,2) || '''::int, '||
            'x''' || substring(thexcolor,4,2) || '''::int, '||
            'x''' || substring(thexcolor,6,2) || '''::int];' into result;
	return result;
end
$_$;


--
-- Name: FUNCTION hexcolor_to_mapserver_color_triple(hexcolor text); Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON FUNCTION altlast.hexcolor_to_mapserver_color_triple(hexcolor text) IS 'convert a hex color represantation to a 3 element integer array containing R,G,B values (in this order).';


--
-- Name: imp_vflz_combined_id_tk_bz(text); Type: FUNCTION; Schema: altlast; Owner: -
--

CREATE FUNCTION altlast.imp_vflz_combined_id_tk_bz(vflz_combined_id_tk text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE
	obarray1 text[];
	obarray2 text[];
BEGIN
	obarray1=regexp_matches(vflz_combined_id_tk,'([a-zA-Z]+)');
	obarray2=regexp_matches(vflz_combined_id_tk,'([0-9]+)');
	RETURN (obarray1[1] || obarray2[1]);	
END;
$$;


