--
-- Name: is_cod_referenced(integer, text); Type: FUNCTION; Schema: altlast; Owner: -
--

CREATE FUNCTION altlast.is_cod_referenced(p_c_cli_id integer, p_code text) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE
  ref_row record;
  sql text;
  c_count integer;
  found boolean;

  table_start timestamp with time zone;
BEGIN
  found := false;

  -- Check if constraints prevent code deletions (is the case when a code is still in use
  begin
    delete from altlast.cod where c_cli_id=p_c_cli_id and code=p_code;
    -- Raise a dummy exception to rollback implicit savepoint that was created by begin because Postgres 8.3 does not support savepoints within functions
    raise exception 'dummy';
  exception
    -- Implicit transaction was rolled back when the exception block is reached
    when foreign_key_violation then
      -- A constraint blocked deletion, so code is still referenced
      found := true;
    when others then
      if SQLERRM = 'dummy' then
        -- Dummy exception was not caught, deletion was not blocked by constraint and needs to be tested manually
        found := false;
      else
        -- Re-raise any other exception to callee
        raise exception 'Rerisen: %', SQLERRM;
      end if;
  end;
  if found then
    -- Signalize code is still in use (because the deletion above was blocked by constraint)
    return true;
  end if;

  -- Check codes manually
  -- get all tables with codes. tables without h_colums will be ignores
  -- because they can not be queried.
  FOR ref_row in select * from (
      select table_name,
        col,
        default_c_cli_id,
        case when  default_c_cli_id=p_c_cli_id then 1::integer else 2::integer end as sort_key
        from  altlast_admin.cod_references
        where col_count = 2 and (table_name, 'h_'||col) not in (
          -- Exclude those columns from checks that are alread covered by constraints
          select from_table.relname as table_name, f_c_cli_id.attname as c_cli_id_column
          from pg_catalog.pg_namespace altlast_namespace
          join pg_catalog.pg_class altlast_cod on altlast_cod.relnamespace=altlast_namespace.oid and altlast_cod.relname='cod'
          join pg_catalog.pg_constraint to_cod on to_cod.confrelid=altlast_cod.oid
          join pg_catalog.pg_class from_table on from_table.oid=to_cod.conrelid
          join pg_catalog.pg_attribute cod_c_cli_id on cod_c_cli_id.attnum = any(to_cod.confkey) and cod_c_cli_id.attrelid=altlast_cod.oid and cod_c_cli_id.attname='c_cli_id'
          join pg_catalog.pg_attribute f_c_cli_id on f_c_cli_id.attnum = any(to_cod.conkey) and f_c_cli_id.attrelid=from_table.oid and f_c_cli_id.atttypid=cod_c_cli_id.atttypid
          where altlast_namespace.nspname='altlast'
        )) foo
      order by sort_key -- order to check the tables with the highest propability for this c_cli_id first.
    LOOP
    select clock_timestamp() into table_start;
    -- check each table for the given code
    if ref_row.default_c_cli_id is not null then
      -- give the default c_cli_id as fallback in case the h_column of the table contains null values
      sql := 'select count(*) as c_count from altlast."'|| ref_row.table_name ||'" where coalesce("h_'||ref_row.col||'", '|| ref_row.default_c_cli_id||')='||p_c_cli_id::text||' and "c_'||ref_row.col||'" = '''||p_code||''';';
    else
      sql := 'select count(*) as c_count from altlast."'|| ref_row.table_name ||'" where "h_'||ref_row.col||'"='||p_c_cli_id::text||' and "c_'||ref_row.col||'" = '''||p_code||''';';
    end if;
    --raise notice 'Took % time for table %', clock_timestamp()-table_start, ref_row.table_name||'.'||ref_row.col;
    --insert into test.is_cod_referenced (table_name, col_name, runtime) values (ref_row.table_name, ref_row.col, clock_timestamp()-table_start);

    execute sql into c_count;

    if c_count>0 then
      found := true;
      exit; -- break the loop to save some time
    end if;

  END LOOP;

  RETURN found;
END;
$$;


--
-- Name: FUNCTION is_cod_referenced(p_c_cli_id integer, p_code text); Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON FUNCTION altlast.is_cod_referenced(p_c_cli_id integer, p_code text) IS 'Testet ob ein gegebner Code von einer anderen Tabelle referenziert wird. Aufruf mit SELECT altlast.is_cod_referenced([c_cli_id], [code]);';


--
-- Name: kbs_datasheet_changed_since(timestamp without time zone); Type: FUNCTION; Schema: altlast; Owner: -
--

CREATE FUNCTION altlast.kbs_datasheet_changed_since(p_when timestamp without time zone) RETURNS SETOF altlast.kbs_datasheet_state
    LANGUAGE sql COST 1000
    AS $_$
select hfoo.vflz_id, max(hfoo.mutations_datum) as latest_mutations_datum
from (
-- altlast.vflz
select vflz.vflz_id, mutations_datum
    from altlast.vflz
union
-- altlast.bere
select bere.vflz_id, mutations_datum
    from altlast.bere
union
-- altlast.vflnr
select vflnr.vflz_id, max(mutations_datum)
    from altlast.vflnr
    group by vflnr.vflz_id
union
-- altlast.org
select  vflnr.vflz_id, max(org.mutations_datum)
    from altlast.vflnr
    join altlast.org on org.org_id=vflnr.org_id
    group by  vflnr.vflz_id
union
-- altlast.intb
select intb.vflz_id, max(intb.mutations_datum)
    from altlast.intb
    group by intb.vflz_id
union
-- altlast.intu
select intu.vflz_id, max(intu.mutations_datum)
    from altlast.intu
    group by intu.vflz_id
union
-- altlast.inta
select inta.vflz_id, max(inta.mutations_datum)
    from altlast.inta
    group by inta.vflz_id
union
-- altlast.vfus
select vfus.vflz_id, max(vfus.mutations_datum)
    from altlast.vfus
    group by vfus.vflz_id
union
-- altlast.gwnu
select gwnu.vflz_id, max(gwnu.mutations_datum)
    from altlast.gwnu
    group by gwnu.vflz_id
union
-- altlast.inum
select intu.vflz_id, max(inum.mutations_datum)
    from altlast.intu
    join altlast.inum on intu.intu_id=inum.intu_id
    group by intu.vflz_id
union
-- altlast.kksk
select inta.vflz_id, max(kksk.mutations_datum)
    from altlast.inta
    join altlast.kksk on inta.inta_id=kksk.inta_id
    group by inta.vflz_id
union
-- altlast.mass
select mass.vflz_id, max(mass.mutations_datum)
    from altlast.mass
    group by mass.vflz_id
union
-- altlast.pm_vfl
select vflz.vflz_id, max(pm_vfl.mutations_datum)
    from  altlast.vflz
    join altlast.pm_vfl on vflz.vfl_id = pm_vfl.vfl_id
    group by vflz.vflz_id
union
-- altlast.pm_cache
/*
select vflz.vflz_id, max(pm_cache.tas_due_date)
    from altlast.vflz
    join altlast.pm_vfl on vflz.vfl_id = pm_vfl.vfl_id
    join altlast.pm_cache on pm_cache.pm_vfl_id = pm_cache.pm_vfl_id
    where pm_cache.tas_due_date is not null and pm_cache.status != 'SLEEPING'
        and pm_cache.tas_due_date != '2037-12-31 00:00:00'::timestamp without time zone --never_due_date
        and pm_cache.tas_due_date != '2031-07-26 00:00:00'::timestamp without time zone --never_due_date
    group by vflz.vflz_id
union
*/
/* Processmaker controlled data is omitted since it contains schedules in the far future that tend to provoke the re-generation of a lot of up-to-date reports
select vflz.vflz_id, max(pm_cache.tas_finish_date)
    from altlast.vflz
    join altlast.pm_vfl on vflz.vfl_id = pm_vfl.vfl_id
    join altlast.pm_cache on pm_cache.pm_vfl_id = pm_cache.pm_vfl_id
    where pm_cache.tas_finish_date is not null and pm_cache.status != 'SLEEPING'
    group by vflz.vflz_id
union
select vflz.vflz_id, max(pm_cache.tas_delegate_date)
    from altlast.vflz
    join altlast.pm_vfl on vflz.vfl_id = pm_vfl.vfl_id
    join altlast.pm_cache on pm_cache.pm_vfl_id = pm_cache.pm_vfl_id
    where pm_cache.tas_delegate_date is not null and pm_cache.status != 'SLEEPING'
    group by vflz.vflz_id
union
-- altlast.pm_doc
select vflz.vflz_id, max(pm_doc.app_doc_due_date )
    from altlast.vflz
    join altlast.pm_vfl on vflz.vfl_id = pm_vfl.vfl_id
    join altlast.pm_cache on pm_cache.pm_vfl_id = pm_cache.pm_vfl_id
    join altlast.pm_doc on pm_doc.pm_cache_id = pm_cache.pm_cache_id
    where pm_doc.app_doc_due_date  is not null and pm_cache.status != 'SLEEPING'
    group by vflz.vflz_id
union*/
-- altlast.sani
select sani.vflz_id, max(sani.mutations_datum)
    from altlast.sani
    group by sani.vflz_id
union
-- altlast.vflgeo
select vflgeo.vflz_id, max(vflgeo.mutations_datum)
    from altlast.vflgeo
    group by vflgeo.vflz_id
union
-- altlast.subj_vflz
select subj_vflz.vflz_id, max(subj_vflz.mutations_datum)
    from altlast.subj_vflz
    group by subj_vflz.vflz_id
union
-- altlast.subj
select subj_vflz.vflz_id, max(subj.mutations_datum)
    from altlast.subj_vflz
    join altlast.subj on subj.subj_id = subj_vflz.subj_id
    group by subj_vflz.vflz_id
union
-- altlast.subj_adr
select subj_vflz.vflz_id, max(subj_adr.mutations_datum)
    from altlast.subj_vflz
    join altlast.subj on subj.subj_id = subj_vflz.subj_id
    join altlast.subj_adr on subj_adr.subj_id = subj.subj_id
    group by subj_vflz.vflz_id
union
-- altlast.adr
select subj_vflz.vflz_id, max(adr.mutations_datum)
    from altlast.subj_vflz
    join altlast.subj on subj.subj_id = subj_vflz.subj_id
    join altlast.subj_adr on subj_adr.subj_id = subj.subj_id
    join altlast.adr on subj_adr.adr_id = adr.adr_id
    group by subj_vflz.vflz_id
union
-- altlast.veen
select veen.vflz_id, max(veen.mutations_datum) from altlast.veen
    group by veen.vflz_id
union
-- altlast.h_gem
select vflz.vflz_id, max(h_gem.mutations_datum)
    from altlast.vflz
    join altlast.h_gem on vflz.h_gem_id = h_gem.h_gem_id
    group by vflz.vflz_id
union
-- altlast.bem_v | altlast.bem
select bem.key_value as vflz_id, max(bem.mutations_datum)
    from altlast.bemgrp
    join altlast.bem on bemgrp.bemgrp_id = bem.bemgrp_id
    where bemgrp.rel_name = 'vflz' and bemgrp.key_column = 'vflz_id'
    group by bem.key_value
union
select inta.vflz_id as vflz_id, max(bem.mutations_datum)
    from altlast.bemgrp
    join altlast.bem on bemgrp.bemgrp_id = bem.bemgrp_id
    join altlast.inta on inta.inta_id = bem.key_value
    where bemgrp.rel_name = 'inta' and bemgrp.key_column = 'inta_id'
    group by inta.vflz_id
union
select intb.vflz_id as vflz_id, max(bem.mutations_datum)
    from altlast.bemgrp
    join altlast.bem on bemgrp.bemgrp_id = bem.bemgrp_id
    join altlast.intb on intb.intb_id = bem.key_value
    where bemgrp.rel_name = 'intb' and bemgrp.key_column = 'intb_id'
    group by intb.vflz_id
union
select intu.vflz_id as vflz_id, max(bem.mutations_datum)
    from altlast.bemgrp
    join altlast.bem on bemgrp.bemgrp_id = bem.bemgrp_id
    join altlast.intu on intu.intu_id = bem.key_value
    where bemgrp.rel_name = 'intu' and bemgrp.key_column = 'intu_id'
    group by intu.vflz_id
union
select sani.vflz_id as vflz_id, max(bem.mutations_datum)
    from altlast.bemgrp
    join altlast.bem on bemgrp.bemgrp_id = bem.bemgrp_id
    join altlast.sani on sani.sani_id = bem.key_value
    where bemgrp.rel_name = 'sani' and bemgrp.key_column = 'sani_id'
    group by sani.vflz_id
union
select veen.vflz_id as vflz_id, max(bem.mutations_datum)
    from altlast.bemgrp
    join altlast.bem on bemgrp.bemgrp_id = bem.bemgrp_id
    join altlast.veen on veen.veen_id = bem.key_value
    where bemgrp.rel_name = 'veen' and bemgrp.key_column = 'veen_id'
    group by veen.vflz_id
union
select mass.vflz_id as vflz_id, max(bem.mutations_datum)
    from altlast.bemgrp
    join altlast.bem on bemgrp.bemgrp_id = bem.bemgrp_id
    join altlast.mass on mass.mass_id = bem.key_value
    where bemgrp.rel_name = 'mass' and bemgrp.key_column = 'mass_id'
    group by mass.vflz_id
union
select vfus.vflz_id as vflz_id, max(bem.mutations_datum)
    from altlast.bemgrp
    join altlast.bem on bemgrp.bemgrp_id = bem.bemgrp_id
    join altlast.vfus on vfus.vfus_id = bem.key_value
    where bemgrp.rel_name = 'vfus' and bemgrp.key_column = 'vfus_id'
    group by vfus.vflz_id
-- TODO: bem for subj, subj_vflz, pm_cache
union
-- altlast.cod + translations -- code changes will force a rebuild of lots of vflzs
/* generated with
select 'select distinct '||column_name ||' from altlast.'|| table_name
from information_schema.columns
    where table_schema = 'altlast' and column_name like 'h_%' and column_name != 'h_gem_id'
        and column_name != 'hausnummer'
        and table_name in ('vfus', 'bem', 'mass', 'bere', 'vflz', 'sani', 'veen','inta',
            'intb', 'intu', 'subj', 'subj_adr', 'adr', 'subj_vflz', 'vflgeo', 'pm_vfl'
            , 'inum', 'kksk', 'vfus', 'gwnu', 'vflnr', 'org')
*/
select relevant_c_cli_ids.vflz_id,
    case when max(translations.mutations_datum) is null or cod.mutations_datum>max(translations.mutations_datum)
        then cod.mutations_datum
        else max(translations.mutations_datum)
    end as mut_dat
    from altlast.cod
    join altlast.translations on translations.msgid = altlast.msgid_code(cod.c_cli_id, cod.code)
    join (
        select distinct vflz_id, h_intb_bran as c_cli_id, c_intb_bran as code from altlast.intb
/*
        union
        select distinct vflz_id,h_bere_art_autobewe,c_bere_art_autobewe from altlast.bere
*/
        union
        select distinct vflz_id,h_bere_res_autobewe,c_bere_res_autobewe from altlast.bere
        union
        select distinct vflz_id,h_bere_res_abwbewe,c_bere_res_abwbewe from altlast.bere
        union
        select distinct vflz_id,10103,c_bere_res_abwbewe from altlast.bere -- bav specific
        union
        select distinct vflz_id,10105,c_bere_res_abwbewe from altlast.bere -- bav specific
        union
        select distinct vflz_id,h_bere_antrag,c_bere_antrag from altlast.bere
        union
        select distinct vflz_id,10103,c_bere_antrag from altlast.bere --bav specific
        union
        select distinct vflz_id,10105,c_bere_antrag from altlast.bere --bav specific
        union
        select distinct vflz_id,h_land,c_land from altlast.subj_vflz join altlast.subj on subj.subj_id = subj_vflz.subj_id join altlast.subj_adr on subj_adr.subj_id = subj.subj_id join altlast.adr on subj_adr.adr_id = adr.adr_id
        union
        select distinct vflz_id,h_kanton, c_kanton from altlast.subj_vflz join altlast.subj on subj.subj_id = subj_vflz.subj_id join altlast.subj_adr on subj_adr.subj_id = subj.subj_id join altlast.adr on subj_adr.adr_id = adr.adr_id
        union
        select distinct vflz_id,h_inum_stoffe, c_inum_stoffe from altlast.intu join altlast.inum on intu.intu_id=inum.intu_id
        union
        select distinct vflz_id,h_gwnu_nutzung, c_gwnu_nutzung from altlast.gwnu
        union
  /*
        select distinct vflz_id, h_gwnu_infg_distanz, c_gwnu_infg_distanz from altlast.gwnu
        union
   */
        select distinct vflz_id, h_vfus_art_schaden, c_vfus_art_schaden from altlast.vfus
        union
        select distinct vflz_id, h_vfus_schaeden, c_vfus_schaeden from altlast.vfus
        union
        select distinct vflz_id, h_massnahme, c_massnahme from altlast.mass
        union
        select distinct vflz_id,h_veen_natuerlich, c_veen_natuerlich from altlast.veen
        union
        select distinct vflz_id,h_subj_vflz_bez_art, c_subj_vflz_bez_art from altlast.subj_vflz
        union
        select distinct vflz_id,h_saniziel, c_saniziel from altlast.sani
        union
        select distinct vflz_id,h_vflz_vftyp,c_vflz_vftyp from altlast.vflz
        union
        select distinct vflz_id,h_vflz_gws_bereich,c_vflz_gws_bereich from altlast.vflz
        union
        select distinct vflz_id,h_vflz_durchlaessigkeit,c_vflz_durchlaessigkeit from altlast.vflz
        union
        select distinct vflz_id,h_vflz_karstgeb,c_vflz_karstgeb from altlast.vflz
        union
        select distinct vflz_id,h_vflz_bearbstand, c_vflz_bearbstand from altlast.vflz
        union
    /*
        select distinct vflz_id,h_vflz_belastsit, c_vflz_belastsit from altlast.vflz
        union
   */
   /*
        select distinct vflz_id,h_vflz_handlbedarf, c_vflz_handlbedarf from altlast.vflz
        union
   */
   /*
        select distinct vflz_id,h_vfa_kntrsickerwasser,c_vfa_kntrsickerwasser from altlast.vflz
        union
   */
   /*
        select distinct vflz_id,h_vfaz_ablin, c_vfaz_ablin from altlast.vflz
        union
   */
   /*
        select distinct vflz_id,h_vfbz_unterkellerung, c_vfbz_unterkellerung from altlast.vflz
        union
   */
        select distinct vflz_id,h_vflz_gws_zone, c_vflz_gws_zone from altlast.vflz
        union
        select distinct vflz_id,h_vflz_unterstand, c_vflz_unterstand  from altlast.vflz
        union
   /*
        select distinct vflz_id, h_kksk_infg_teilvol, c_kksk_infg_teilvol from altlast.inta join altlast.kksk on inta.inta_id=kksk.inta_id
        union

   */
        select distinct vflz_id,h_kksk_stoffkl, c_kksk_stoffkl from altlast.inta join altlast.kksk on inta.inta_id=kksk.inta_id
    ) relevant_c_cli_ids on cod.c_cli_id = relevant_c_cli_ids.c_cli_id and relevant_c_cli_ids.code is not null and relevant_c_cli_ids.code = cod.code
    join altlast.kbs_v kbs on kbs.vflz_id = relevant_c_cli_ids.vflz_id
    group by relevant_c_cli_ids.vflz_id, cod.mutations_datum
) hfoo
join altlast.kbs_v kbs on kbs.vflz_id = hfoo.vflz_id
group by hfoo.vflz_id
having  max(hfoo.mutations_datum) >= $1;
$_$;


--
-- Name: FUNCTION kbs_datasheet_changed_since(p_when timestamp without time zone); Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON FUNCTION altlast.kbs_datasheet_changed_since(p_when timestamp without time zone) IS 'BAV specific: Lists all vflz_id and their latest mutations_datum which have been altered since the given date.

this function shoud check the same fields as those used by the used report stylesheet.

this is implemented as a function instead of a view to preserve formatting and comments';


--
-- Name: kbs_datasheet_create(integer); Type: FUNCTION; Schema: altlast; Owner: -
--

CREATE FUNCTION altlast.kbs_datasheet_create(p_vflz_id integer) RETURNS void
    LANGUAGE plpgsql
    AS $$
begin
    -- join to vflz to filter nonexisting ids
    insert into altlast_admin.cronjob (cronjob_name, cronjob_data, scheduled_at, priority)
        select 'datasheet_for_cadastre', 'create:'||vflz_id, current_date + '20:00:00'::interval, 4
        from altlast.vflz where vflz_id = p_vflz_id;

    -- create the empty entry in kbs_datasheet for nagios monitoring
    insert into altlast_admin.kbs_datasheet (vflz_id, is_waiting)
        select vflz_id, true from altlast.vflz where vflz_id = p_vflz_id
        except -- avoid double entries
        select vflz_id, true from altlast_admin.kbs_datasheet;

    update altlast_admin.kbs_datasheet set is_waiting = True 
        where vflz_id = p_vflz_id;

end
$$;


--
-- Name: FUNCTION kbs_datasheet_create(p_vflz_id integer); Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON FUNCTION altlast.kbs_datasheet_create(p_vflz_id integer) IS 'create a datasheet for the given standort via cron';


--
-- Name: kbs_datasheet_delete(integer); Type: FUNCTION; Schema: altlast; Owner: -
--

CREATE FUNCTION altlast.kbs_datasheet_delete(p_vflz_id integer) RETURNS void
    LANGUAGE plpgsql
    AS $$
begin
    -- do not join to vflz to allow dleetion of nonexisting vflz_ids
    insert into altlast_admin.cronjob (cronjob_name, cronjob_data, scheduled_at, priority)
        select 'datasheet_for_cadastre', 'delete:'||p_vflz_id, current_date + '20:00:00'::interval, 4;
end
$$;


--
-- Name: FUNCTION kbs_datasheet_delete(p_vflz_id integer); Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON FUNCTION altlast.kbs_datasheet_delete(p_vflz_id integer) IS 'delete a datasheet for the given standort via cron';


