--
-- Name: killlinebreaks(text); Type: FUNCTION; Schema: altlast; Owner: -
--

CREATE FUNCTION altlast.killlinebreaks(instr text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE 
  s character varying;
  rs character varying;
BEGIN
  RETURN altlast.killlinebreaks(instr,'>>><<<');	
END;$$;


--
-- Name: killlinebreaks(text, text); Type: FUNCTION; Schema: altlast; Owner: -
--

CREATE FUNCTION altlast.killlinebreaks(instr text, replacestr text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE 
  s character varying;
  rs character varying;
BEGIN
  RETURN altlast.killlinebreaks(instr,replacestr,TRUE);	
END;$$;


--
-- Name: killlinebreaks(text, text, boolean); Type: FUNCTION; Schema: altlast; Owner: -
--

CREATE FUNCTION altlast.killlinebreaks(instr text, replacestr text, breakonbreak boolean) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE 
  s character varying;
  rs character varying;
BEGIN

  rs:=replacestr;
  IF (rs IS NULL) OR (rs='') THEN
    rs:='>>><<<';
  END IF;

  IF instr ~ E'.*\n.*' THEN
    s:=regexp_replace(instr,E'[\n,\r\n]',rs,'gi');
    IF breakonbreak THEN
      RAISE EXCEPTION 'Der Text % enthaelt unzulaessige Zeilenumbrueche',s;
    END IF;    
  ELSE
    s:=instr;
  END IF;

  RETURN s;

END;$$;


--
-- Name: FUNCTION killlinebreaks(instr text, replacestr text, breakonbreak boolean); Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON FUNCTION altlast.killlinebreaks(instr text, replacestr text, breakonbreak boolean) IS 'Ersetzt Zeilenumbrueche ininstr durch Text in replacestr. Bei breakonbreak=TRUE wirft die Funktion beim Auftreten eines Zeilenumbruchs eine Exception.';


--
-- Name: lncat(text, text); Type: FUNCTION; Schema: altlast; Owner: -
--

CREATE FUNCTION altlast.lncat(acc text, instr text) RETURNS text
    LANGUAGE plpgsql
    AS $$
  BEGIN
    IF acc IS NULL OR acc = '' THEN
      RETURN '' || instr;
    ELSE
      IF (COALESCE(instr,'',instr)='') THEN
        RETURN '' || acc;
      ELSE
        RETURN acc || E'\n' || '' || instr;
      END IF;
    END IF;
    
  END;
$$;


--
-- Name: makegrit_2d_fromgeometries(public.geometry, integer, public.geometry[], integer); Type: FUNCTION; Schema: altlast; Owner: -
--

CREATE FUNCTION altlast.makegrit_2d_fromgeometries(bound_polygon public.geometry, grid_step integer, locations public.geometry[], metric_srid integer DEFAULT 28408) RETURNS public.geometry
    LANGUAGE plpgsql
    AS $_$
DECLARE
  BoundM public.geometry; --Bound polygon transformed to the metric projection (with metric_srid SRID)
  Xmin DOUBLE PRECISION;
  Xmax DOUBLE PRECISION;
  Ymin DOUBLE PRECISION;
  Ymax DOUBLE PRECISION;
  sectors public.geometry[];
  gg geometry; 
  i INTEGER;
BEGIN
  BoundM := ST_Transform($1, $4); --From WGS84 (SRID 4326) to the metric projection, to operate with step in meters
 
  i := 0;
  FOREACH gg IN ARRAY $3
  LOOP
     Xmin := ST_XMin(gg);
     Xmin := ST_XMin(BoundM) + (CAST((Xmin-ST_XMin(BoundM))/$2 AS INT)*$2)-$2;
     Xmax := ST_XMax(gg);
     Xmax := ST_XMin(BoundM) + ((CAST((Xmax-ST_XMin(BoundM))/$2 AS INT)*$2)+$2);
     
     Ymin := ST_YMin(gg);
     Ymin := ST_YMin(BoundM) + (CAST((Ymin-ST_YMin(BoundM))/$2 AS INT)*$2)-$2;
     Ymax := ST_YMax(gg);
     Ymax := ST_YMin(BoundM) + ((CAST((Ymax-ST_YMin(BoundM))/$2 AS INT)*$2)+$2);
      
     IF (Xmin >= ST_XMin(BoundM) AND Xmax <= ST_XMax(BoundM) AND Ymin >= ST_YMin(BoundM) AND Ymax <= ST_YMax(BoundM)) THEN
       IF (Xmin >= 651200 OR YMax <= 273600) THEN -- exclude unwanted temporary locations left top
  sectors[i] := ST_MakeEnvelope(Xmin, Ymin, Xmax, Ymax, $4);
  i := i + 1;
       END IF;
     END IF;
  
  END LOOP;
 RETURN  DISTINCT ST_Transform(ST_Collect(sectors), ST_SRID($1));
END;
$_$;


--
-- Name: mapserver_color_to_triple(text); Type: FUNCTION; Schema: altlast; Owner: -
--

CREATE FUNCTION altlast.mapserver_color_to_triple(mapservercolor text) RETURNS integer[]
    LANGUAGE plpgsql STABLE
    AS $_$
declare
	colortriple integer[3];
	thecolor text;
begin
	thecolor := trim(both ' ' from mapservercolor);
	if not thecolor ~ E'^[0-9]{1,3} [0-9]{1,3} [0-9]{1,3}$' then
		raise exception 'the given value does not appear to be a valid mapserver color representation';
	end if;

    select regexp_split_to_array(thecolor, E' ')::integer[3] into colortriple;
	return colortriple;
end
$_$;


--
-- Name: FUNCTION mapserver_color_to_triple(mapservercolor text); Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON FUNCTION altlast.mapserver_color_to_triple(mapservercolor text) IS 'convert a mapserver color representation string to a mapserver compatible one with a string containing three integer values.';


--
-- Name: mapserver_drawing_priority(integer[]); Type: FUNCTION; Schema: altlast; Owner: -
--

CREATE FUNCTION altlast.mapserver_drawing_priority(mapservercolor integer[]) RETURNS integer
    LANGUAGE plpgsql STABLE
    AS $$
declare
begin
	return (mapservercolor[1]*1000000)+(mapservercolor[2]*1000)+(mapservercolor[3]);
end
$$;


--
-- Name: FUNCTION mapserver_drawing_priority(mapservercolor integer[]); Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON FUNCTION altlast.mapserver_drawing_priority(mapservercolor integer[]) IS '
Drawing priority. Red colors have a higher priority than yellow than green.

this functionality is used to prevent features with a lower priority being drawn
over features with a higher priority.

see bug #2050010
';


--
-- Name: materialize_vflz_parzellen(integer); Type: FUNCTION; Schema: altlast; Owner: -
--

CREATE FUNCTION altlast.materialize_vflz_parzellen(p_vflz_id integer) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
  BEGIN

    delete from altlast.vflz_parzellen_v where vflz_id = p_vflz_id;

    insert into altlast.vflz_parzellen_v (vflz_id, h_gem_id, parzellen)
            select vpm.vflz_id, vpm.h_gem_id, altlast.commacat_all(vpm.gb_nummer::text) AS parzellen
                from altlast.vflz_parzellen_materialization_v vpm
                left join altlast.vflz_parzellen_v vpv2 on vpm.vflz_id = vpv2.vflz_id
                    and vpv2.h_gem_id = vpm.h_gem_id
                where vpv2.parzellen is null and vpm.vflz_id = p_vflz_id
                GROUP BY vpm.h_gem_id, vpm.vflz_id;

    return true;
 end;
$$;


--
-- Name: FUNCTION materialize_vflz_parzellen(p_vflz_id integer); Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON FUNCTION altlast.materialize_vflz_parzellen(p_vflz_id integer) IS 'materialize parzellen for vflz_id';


--
-- Name: msgid_code(integer, character varying); Type: FUNCTION; Schema: altlast; Owner: -
--

CREATE FUNCTION altlast.msgid_code(c_cli_id integer, code character varying) RETURNS text
    LANGUAGE plpgsql STABLE
    AS $$
-- Example calls:
-- select altlast.msgid_code(15, 'test'); -> code.15.test
-- select altlast.msgid_code(NULL, 'test'); -> code..test
-- select altlast.msgid_code(15, NULL); -> NULL
-- select altlast.msgid_code(NULL, NULL); -> NULL
--
-- Note that c_cli_id should never be NULL if code is not NULL. This function only handles this case to prevent complete failures on invalid data.
declare
	res text;
  BEGIN
	res := 'code.';
	if c_cli_id is not null then
		res := res || c_cli_id;
	end if;
	res := res || '.' || code;
	return res;
  END;
$$;


--
-- Name: FUNCTION msgid_code(c_cli_id integer, code character varying); Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON FUNCTION altlast.msgid_code(c_cli_id integer, code character varying) IS 'Generates an indentifier for translation of the code.';


--
-- Name: next_vfl_id(); Type: FUNCTION; Schema: altlast; Owner: -
--

CREATE FUNCTION altlast.next_vfl_id() RETURNS integer
    LANGUAGE plpgsql
    AS $$
declare
  next_vfl_id integer;
  sequence_is_off boolean;
begin

  next_vfl_id := nextval('altlast.vflz_vfl_id_seq'::regclass);

  -- check if the sequence is correct and the id is not in use anywhere
  select count(*)>0 into sequence_is_off
    from altlast.vflz where vfl_id = next_vfl_id;

  if sequence_is_off then

    -- set the sequence above the max vfl_id in vflz
    perform setval('altlast.vflz_vfl_id_seq'::regclass, max(vfl_id))
      from altlast.vflz where vfl_id is not null;

    -- re-get the next value
    next_vfl_id := nextval('altlast.vflz_vfl_id_seq'::regclass);

  end if;

  return next_vfl_id;
end $$;


--
-- Name: FUNCTION next_vfl_id(); Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON FUNCTION altlast.next_vfl_id() IS 'wrapper arround nextval for fetching the next free
vfl_id and setting the sequence to max(vfl_id) in case the sequence is off';


--
-- Name: parent_vfl(integer); Type: FUNCTION; Schema: altlast; Owner: -
--

CREATE FUNCTION altlast.parent_vfl(p_vfl_id integer) RETURNS SETOF integer
    LANGUAGE plpgsql STABLE
    AS $$
declare
    old_count integer;
    vfl_id_found integer[];
begin
    vfl_id_found[1] = p_vfl_id;

    loop
        old_count = array_upper(vfl_id_found, 1);
        select array(
            select parent_vfl_id
            from altlast.vfl_hierarchy
            where vfl_id=any(vfl_id_found)
            union
            select vfl_id_found[i]
            from (
                select generate_series(1, array_upper(vfl_id_found, 1)) as i
            ) indizies
        ) into vfl_id_found;
        -- Compare parent count to prevent endless loops in case hierarchy is circular (possible for not yet clean data)
        if not old_count < array_upper(vfl_id_found, 1) then
            exit;
        end if;
    end loop;

    -- Remove parameter from parents and convert array to a record set
    return query select vfl_id_found[i]
    from (
        select generate_series(1, array_upper(vfl_id_found, 1)) as i
    ) indizies
    where not vfl_id_found[i]=p_vfl_id;

    return;
end $$;


--
-- Name: FUNCTION parent_vfl(p_vfl_id integer); Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON FUNCTION altlast.parent_vfl(p_vfl_id integer) IS 'Climbs up the hierarchy of vfl and returns parent vfl in an unordered list';


--
-- Name: pm_cache_add_logentry(); Type: FUNCTION; Schema: altlast; Owner: -
--

CREATE FUNCTION altlast.pm_cache_add_logentry() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
    BEGIN
        IF (TG_OP = 'DELETE') THEN
            INSERT INTO altlast.pm_cache_log (pm_cache_id, app_uid, delete_date) SELECT OLD.pm_cache_id, OLD.app_uid, now();
            RETURN OLD;
        END IF;
        RETURN NULL;
    END;
$$;


--
-- Name: pm_cache_set_vflz_id(); Type: FUNCTION; Schema: altlast; Owner: -
--

CREATE FUNCTION altlast.pm_cache_set_vflz_id() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
	update_vflz boolean;
	new_vflz_id integer;
begin
    update_vflz:=false;

    if TG_OP = 'INSERT' then
	    update_vflz:=true;
    end if;

    if TG_OP='UPDATE' then
        update_vflz := old.status != 'CLOSED';
    end if;

    if update_vflz and new.vflz_id is null then

        select vflz_id into new_vflz_id
            from altlast.pm_vfl pv
		 join altlast.vflz_current_v v on pv.vfl_id = v.vfl_id
		 where pv.pm_vfl_id = new.pm_vfl_id
         ;
         /*in case we work on a deleted site (what should never
         happen), we leave the existing vflz_id*/
         new.vflz_id := coalesce(new_vflz_id,new.vflz_id);
    end if;

    return new;
end
$$;


--
-- Name: FUNCTION pm_cache_set_vflz_id(); Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON FUNCTION altlast.pm_cache_set_vflz_id() IS 'Trigger writes the vflz_id of the current version of the site
into pm_cache. Triggers with every change of pm_cache unless the task had benn closed before.';


--
-- Name: pm_content_get(text, text); Type: FUNCTION; Schema: altlast; Owner: -
--

CREATE FUNCTION altlast.pm_content_get(p_con_id text, p_con_category text) RETURNS text
    LANGUAGE sql STABLE COST 200
    AS $_$
	select con_value 
		from (
			select con_value, 1::integer as sort_key
				from altlast.pm_content pc
				join altlast_admin.setting st on pc.con_lang= st.value
				join altlast_admin.setitem si on si.setitem_id=st.setitem_id
				where si.key = 'language'
					and pc.con_id = $1
					and pc.con_category = $2
					and st.role_name = CURRENT_USER
			union
			select con_value, 2::integer as sort_key -- default language
				from altlast.pm_content pc
				where con_lang = 'de' and con_id = $1 and pc.con_category = $2
			union
			select * from (  -- subselect to encapsulate the limit statement
				select con_value, 3::integer as sort_key -- any language available
					from altlast.pm_content pc
					where con_id = $1 and pc.con_category = $2
					limit 1
				) foo2
		) foo
		order by foo.sort_key asc limit 1
	$_$;


--
-- Name: FUNCTION pm_content_get(p_con_id text, p_con_category text); Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON FUNCTION altlast.pm_content_get(p_con_id text, p_con_category text) IS 'pm_content inhalte entsprechend der vom nutzer festgelegten sprache abfragen';


--
-- Name: pm_content_get(text, text, text); Type: FUNCTION; Schema: altlast; Owner: -
--

CREATE FUNCTION altlast.pm_content_get(p_con_id text, p_con_category text, p_con_lang text) RETURNS text
    LANGUAGE sql STABLE COST 200
    AS $_$
	select con_value 
		from (
			select con_value, 1::integer as sort_key --  language parameter
				from altlast.pm_content pc
				where con_lang = $3 and con_id = $1 and pc.con_category = $2
			union
			select con_value, 2::integer as sort_key -- default language
				from altlast.pm_content pc
				where con_lang = 'de' and con_id = $1 and pc.con_category = $2
			union
			select * from (  -- subselect to encapsulate the limit statement			
				select con_value, 3::integer as sort_key -- any language available
					from altlast.pm_content pc
					where con_id = $1 and pc.con_category = $2
					limit 1
				) foo2
		) foo
		order by foo.sort_key asc limit 1
	$_$;


--
-- Name: FUNCTION pm_content_get(p_con_id text, p_con_category text, p_con_lang text); Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON FUNCTION altlast.pm_content_get(p_con_id text, p_con_category text, p_con_lang text) IS 'pm_content inhalte entsprechend der angegebenen sprache abfragen';


