--
-- Name: publizieren(integer); Type: FUNCTION; Schema: altlast; Owner: -
--

CREATE FUNCTION altlast.publizieren(pmvflid integer) RETURNS boolean
    LANGUAGE plpgsql STRICT
    AS $$
DECLARE
  publizieren boolean;
BEGIN
	SELECT tc.publizieren into publizieren 
		FROM altlast.pm_cache ch JOIN altlast.pm_task t USING(tas_uid)
		JOIN altlast.pm_taskconf tc USING(tas_uid)
		WHERE ch.pm_vfl_id=pmvflid AND ch.status='CLOSED' 
		ORDER BY ch.app_thread DESC, ch.del_index DESC LIMIT 1;

	RETURN nullif(publizieren, false);
END;$$;


--
-- Name: FUNCTION publizieren(pmvflid integer); Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON FUNCTION altlast.publizieren(pmvflid integer) IS 'Check if the task allows the publication of the current version

this function returns NULL if the publizieren flag ist not set to allow furher comparisons with coalesce';


--
-- Name: qs_token_map(text, character varying); Type: FUNCTION; Schema: altlast; Owner: -
--

CREATE FUNCTION altlast.qs_token_map(str text, typ character varying) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
    rec record;
    asql text;
    astr text;
BEGIN
    asql:='SELECT find, replace_with FROM altlast_admin.qs_token_mappings';
    astr:=str;

    IF typ='subj' THEN
        asql:=asql || ' WHERE use_subj=True';
    ELSIF typ='obje' THEN
        asql:=asql || ' WHERE use_obje=True';
    END IF;

    FOR rec IN EXECUTE asql LOOP
        astr:=UPPER(REPLACE(UPPER(astr), UPPER(rec.find), UPPER(rec.replace_with)));
    END LOOP;

    RETURN trim(both ' ' from astr);
END;$$;


