--
-- Name: rebuild_vflz_parzellen_v(); Type: FUNCTION; Schema: altlast; Owner: -
--

CREATE FUNCTION altlast.rebuild_vflz_parzellen_v() RETURNS void
    LANGUAGE plpgsql
    AS $$
begin
    
    truncate altlast.vflz_parzellen_v;

    insert into altlast.vflz_parzellen_v (vflz_id, h_gem_id, parzellen)
	select vpm.vflz_id, vpm.h_gem_id, altlast.commacat_all(vpm.gb_nummer::text) AS parzellen
        from altlast.vflz_parzellen_materialization_v vpm
	    left join altlast.vflz_parzellen_v vpv2 on vpm.vflz_id = vpv2.vflz_id
		    and vpv2.h_gem_id = vpm.h_gem_id
	    where vpv2.parzellen is null
		GROUP BY vpm.h_gem_id, vpm.vflz_id;
END;$$;


--
-- Name: FUNCTION rebuild_vflz_parzellen_v(); Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON FUNCTION altlast.rebuild_vflz_parzellen_v() IS 'recreate the content of the materialized view altlast.vflz_parzellen_v';


--
-- Name: rechtskraft(integer); Type: FUNCTION; Schema: altlast; Owner: -
--

CREATE FUNCTION altlast.rechtskraft(pmvflid integer) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE
  rec record;
BEGIN

  --SELECT altlast.rechtskraft(vfl_id) AS rechtskraft FROM altlast.vflz_current_v WHERE altlast.rechtskraft(vfl_id) IS NOT NULL;

  IF (pmvflid IS NULL) THEN
     return NULL;
  ELSE 

    SELECT rechtskraft INTO rec 
    FROM altlast.vflz_current_v v 
    JOIN altlast.pm_vfl pv ON pv.vfl_id=v.vfl_id 
    WHERE pv.pm_vfl_id = pmvflid AND v.rechtskraft=TRUE;
    --once rechtskraft is set never change it again
    --but allow for manual changes (that is why the check goes on vflz_current_v only)
    IF rec IS NOT NULL THEN
      RETURN TRUE;
    ELSE
      --find any closed task for the standort with status =closed and setting of rechtskraft configured 
      SELECT COUNT(*) AS cnt INTO rec
      FROM altlast.pm_cache ch JOIN altlast.pm_task t USING(tas_uid)
      JOIN altlast.pm_taskconf tc USING(tas_uid)
      WHERE ch.pm_vfl_id=pmvflid AND ch.status='CLOSED' AND COALESCE(tc.rechtskraft,FALSE)=TRUE;
      RETURN (rec.cnt>0);
    END IF;    
  END IF;

END;$$;


--
-- Name: FUNCTION rechtskraft(pmvflid integer); Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON FUNCTION altlast.rechtskraft(pmvflid integer) IS 'Gets rechtskraft for current state of a sto. Once set to TRUE this will never change back.';


