--
-- Name: required_field_reindex(); Type: FUNCTION; Schema: altlast; Owner: -
--

CREATE FUNCTION altlast.required_field_reindex() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
declare
	_vflz_id integer;
	_is_kbs boolean;
BEGIN
	if TG_OP='UPDATE' then
		-- Check if content has changed and stop early if it hasn't
		declare
			query text;
			rows_equal boolean;
			attribute record;
		begin
			query := 'select 1=1';
			for attribute in
				select attname from pg_attribute where attrelid=TG_RELID
					-- Ignore deleted columns and invisible columns
					and attisdropped=FALSE and attnum>0
					-- Ignore changes to columns that to always change
					and attname not in ('uoid', 'mutierer_kuerzel', 'mutations_datum')
			loop
				-- Compare values assuming NULL equals the empty string and everything can be casted to text
				query := query || ' and coalesce(($1).'||attribute.attname || '::text, '''')=coalesce(($2).'||attribute.attname ||'::text, '''')';
			end loop;
			execute query into rows_equal using NEW, OLD;

			if rows_equal then
				-- There was no change due to this update, so don't request rebuilding the cache (altlast.qs_mandatory_fields_cached_v)
				return NEW;
			end if;
		end;
	end if;

	if TG_RELNAME='vflz' then
		-- We know the primary key and can access it directly
		if TG_OP='DELETE' then
			-- an update on a not existing vflz_id will delete it
			_vflz_id := old.vflz_id;
		else
			_vflz_id := new.vflz_id;
		end if;
	elsif TG_RELNAME='vflnr' then
		if TG_OP='DELETE' then
			_vflz_id := old.vflz_id;
		else
			_vflz_id := new.vflz_id;
		end if;
	else
		-- Fetch the primary key and use its value to get the vflz_id
		declare
			primary_key_name name;
			query_from text;
			primary_key_value text;
		begin
			-- Get the name of the primary for the current table the trigger executes on
			SELECT into primary_key_name
				pg_attribute.attname
			FROM pg_index, pg_class, pg_attribute
			WHERE
				pg_class.oid = TG_RELID AND
				indrelid = pg_class.oid AND
				pg_attribute.attrelid = pg_class.oid AND
				pg_attribute.attnum = any(pg_index.indkey)
				AND indisprimary;
		    if primary_key_name is not null then
                -- Fetch the value of the primary key for the current row
                if TG_OP='DELETE' then
                    EXECUTE 'SELECT ($1).' || primary_key_name || '::text' INTO primary_key_value USING OLD;
                else
                    EXECUTE 'SELECT ($1).' || primary_key_name || '::text' INTO primary_key_value USING NEW;
                end if;
                -- Fetch the vflz_id that is referred directly or via other tables
                query_from := 'select vflz.vflz_id from ' || (
                    -- Get path to table holding value using routejoin
                    SELECT altlast.routejoin_route_left_cached(Array(
                    SELECT oid FROM (
                        SELECT
                        oid,
                        CASE WHEN "table" = 'vflz'::name then 1 else 2 end as sort
                        FROM altlast.routejoin_oidlookup
                        WHERE (schema='altlast' and "table"='vflz') or (schema = 'altlast' and "table"=TG_RELNAME)
                    ) foo
                    ORDER BY sort asc
                    )))
                    || ' where ' || quote_ident(TG_RELNAME)||'.'||primary_key_name||'='
                    || quote_literal(primary_key_value);
                execute query_from into _vflz_id;
			end if;
		end;
	end if;

	-- update the cache for the affected location
	select into _is_kbs count(*)>0
	from altlast.cod_required
	join altlast.bere on bere.h_bere_res_abwbewe=cod_required.h_bere_res_abwbewe and bere.c_bere_res_abwbewe=cod_required.c_bere_res_abwbewe
	where bere.vflz_id=_vflz_id and _vflz_id is not null;

	if _is_kbs is not distinct from true then
		-- Schedule for reindexing
		insert into altlast_admin.cronjob (cronjob_name, cronjob_data)
		select 'reindex_required_fields', _vflz_id
		where (
			select count(*) from altlast_admin.cronjob where cronjob_name='reindex_required_fields' and cronjob_data=_vflz_id::text
				and process_pid is null
		)=0;
	else
		-- There is nothing that could be violated, so remove from cached version of view
		delete from altlast.qs_mandatory_fields_cached_v where vflz_id=_vflz_id;
	end if;

	if TG_OP='DELETE' then
		return old;
	else
		return new;
	end if;
END;$_$;


--
-- Name: FUNCTION required_field_reindex(); Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON FUNCTION altlast.required_field_reindex() IS 'Schedules looking for violations to required fields on affected locations.';


--
-- Name: required_field_valid(integer, integer, character varying, text, name, text); Type: FUNCTION; Schema: altlast; Owner: -
--

CREATE FUNCTION altlast.required_field_valid(vflz_id integer, h_bere_res_abwbewe integer, c_bere_res_abwbewe character varying, table_name text, p_column_name name, require_check text) RETURNS boolean
    LANGUAGE plpgsql COST 999999
    AS $$
DECLARE
    query text;
    invalid_location record;
    column_name name;
    DUMMY constant name='dummy';
BEGIN
    -- Fix names where client does not use naming convention consistent with server
    if table_name='inta' and p_column_name='vol_kompartiment' then
        column_name := 'inta_vol_kompartiment';
    else
        column_name := p_column_name;
    end if;

    query := 'select vflz.vflz_id from ' ||
        case when table_name='vflz' or table_name=DUMMY then 'altlast.vflz'
        else (
        -- Get path to table holding value using routejoin if value is not within altlast.vflz
        SELECT altlast.routejoin_route_left_cached(Array(
        SELECT oid FROM (
            SELECT
            oid,
            CASE WHEN "table" = 'vflz'::name then 1 else 2 end as sort
            FROM altlast.routejoin_oidlookup
            WHERE (schema='altlast' and "table"='vflz') or (schema = 'altlast' and "table"=table_name)
        ) foo
        ORDER BY sort asc
        ))) end
        || ' join altlast.bere bere2 on bere2.vflz_id=vflz.vflz_id'
        || ' join altlast.vflz_current_v on vflz_current_v.vflz_id=vflz.vflz_id';
    if table_name=DUMMY and column_name='bav_number' and require_check='bav_number_present' then
        query := query || ' left join (
            select vflnr.vflz_id, nummer as bav_number from altlast.vflnr
            join altlast.org on org.org_id=vflnr.org_id
            where org.kuerzel='||quote_literal('BAV')||'
        ) dummy on dummy.vflz_id=vflz.vflz_id';
    elsif table_name=DUMMY and column_name='non_bav_number' and require_check='non_bav_number_present' then
        query := query || ' left join (
            select vflnr.vflz_id, nummer as non_bav_number from altlast.vflnr
            join altlast.org on org.org_id=vflnr.org_id
            where org.kuerzel!='||quote_literal('BAV')||'
        ) dummy on dummy.vflz_id=vflz.vflz_id';
    elsif table_name=DUMMY and column_name='betreiber' and require_check='betreiber_present' then
        query := query || ' left join (
            select subj_vflz.vflz_id, subj_vflz.subj_id as betreiber
            from altlast.subj_vflz
            where h_subj_vflz_bez_art='||quote_literal(22)|| ' and c_subj_vflz_bez_art='||quote_literal(8)||'
        ) dummy on dummy.vflz_id=vflz.vflz_id';
    elsif table_name=DUMMY and column_name='eigen' and require_check='eigen_present' then
        query := query || ' left join (
            select vflz_owner_v.vflz_id, vflz_owner_v.subj_id as eigen
            from altlast.vflz_owner_v
        ) dummy on dummy.vflz_id=vflz.vflz_id';
    elsif table_name=DUMMY and column_name='type_dependent_annotation' and require_check='any_filled' then
        query := query || ' left join (
            select inta.vflz_id as vflz_id, bem_v.bem as type_dependent_annotation
            from altlast.bem_v
            join altlast.inta on inta.inta_id=bem_v.key_value
            where bemgrp='||quote_literal('ablagerung')||'
            union
            select intb.vflz_id, bem_v.bem
            from altlast.bem_v
            join altlast.intb on intb.intb_id=bem_v.key_value
            where bemgrp='||quote_literal('bertrieb')||'
            union
            select intu.vflz_id, bem_v.bem
            from altlast.bem_v
            join altlast.intu on intu.intu_id=bem_v.key_value
            where bemgrp='||quote_literal('unfall')||'
        ) dummy on dummy.vflz_id=vflz.vflz_id';
    elsif table_name=DUMMY and column_name='bere_begr_abwbewe' and require_check='any_filled' then
        query := query || ' left join (
            select bem_v.key_value as vflz_id, bem_v.bem as bere_begr_abwbewe
            from altlast.bem_v
            where bemgrp='||quote_literal('bere_begr_abwbewe')||'
        ) dummy on dummy.vflz_id=vflz.vflz_id';
    elsif table_name=DUMMY and column_name='bem_massnahme' and require_check='any_filled' then
        query := query || ' left join (
            select mass.vflz_id, bem_v.bem as bem_massnahme
            from altlast.bem_v
            join altlast.mass on bem_v.key_value = mass.mass_id 
            where bemgrp='||quote_literal('mass.mass_id')||'
        ) dummy on dummy.vflz_id=vflz.vflz_id';
    end if;
    query := query || ' where bere2.h_bere_res_abwbewe='||h_bere_res_abwbewe;
    if c_bere_res_abwbewe is not NULL then
        query := query || ' and bere2.c_bere_res_abwbewe='||quote_literal(c_bere_res_abwbewe);
    end if;
    query := query || ' and vflz.vflz_id=' || quote_literal(vflz_id);

    if require_check in ('any_filled', 'any_filled_inta', 'any_filled_intb', 'any_filled_intu', 'bav_number_present',
        'non_bav_number_present', 'betreiber_present', 'eigen_present', 'vflz_inbetrieb_ja', 'vflz_inbetrieb_nein') then
        
        query := query || ' and (' ||quote_ident(table_name)||'.'||quote_ident(column_name) || ' is null'
            || ' or '||quote_ident(table_name)||'.'||quote_ident(column_name)||'::text=' || quote_literal('') || ')';
        if require_check='any_filled_inta' then
            query := query || ' and vflz.c_vflz_vftyp='||quote_literal('01');
        elsif require_check='any_filled_intb' then
            query := query || ' and (vflz.c_vflz_vftyp='||quote_literal('02') || ' or vflz.c_vflz_vftyp='||quote_literal('04') || ')';
        elsif require_check='any_filled_inta' then
            query := query || ' and vflz.c_vflz_vftyp='||quote_literal('03');
        elsif require_check='vflz_inbetrieb_ja' then
                query := query || ' and vflz.c_vflz_vftyp='||quote_literal('01') || ' and vflz.c_vflz_inbetrieb='||quote_literal('01');
        elsif require_check='vflz_inbetrieb_nein' then
                query := query || ' and vflz.c_vflz_vftyp='||quote_literal('01') || ' and vflz.c_vflz_inbetrieb='||quote_literal('02');
        end if;
    elsif require_check='vflnr_active_defined' then
        query := query || ' and (
            select count(*) from altlast.vflnr
            where vflnr.aktiv and vflnr.vflz_id=vflz.vflz_id
        )=0';
    else
        raise exception 'Unknown validation function: %', require_check;
    end if;
    --raise notice '%', query;
    for invalid_location in
        execute query
    loop
        -- A mismatch was found, signalize that value is invalid
        return FALSE;
    end loop;
    -- Signalize that validation suceeded and field content is valid or no validation needed
    return TRUE;
end;
$$;


--
-- Name: FUNCTION required_field_valid(vflz_id integer, h_bere_res_abwbewe integer, c_bere_res_abwbewe character varying, table_name text, p_column_name name, require_check text); Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON FUNCTION altlast.required_field_valid(vflz_id integer, h_bere_res_abwbewe integer, c_bere_res_abwbewe character varying, table_name text, p_column_name name, require_check text) IS 'Performs validation for empty mandatory fields.';


--
-- Name: required_field_vflz_reindex(integer); Type: FUNCTION; Schema: altlast; Owner: -
--

CREATE FUNCTION altlast.required_field_vflz_reindex(p_vflz_id integer) RETURNS void
    LANGUAGE plpgsql
    AS $$
  declare
	violation record;
  BEGIN
	select vflz_id, reason into violation from altlast.qs_mandatory_fields_v where vflz_id=p_vflz_id;
	-- Remove from list of locations with violations
	delete from altlast.qs_mandatory_fields_cached_v where vflz_id=p_vflz_id;
	if violation is not NULL then
		-- Add to list of location with violations
		insert into altlast.qs_mandatory_fields_cached_v (vflz_id, reason)
			values (violation.vflz_id, violation.reason);
	end if;
 end;
$$;



--
-- Name: routejoin_route_left_cached(oid[]); Type: FUNCTION; Schema: altlast; Owner: -
--

CREATE FUNCTION altlast.routejoin_route_left_cached(table_oids_in oid[]) RETURNS text
    LANGUAGE plpgsql
    AS $$
declare
    _route text;
    _tables oid[];
begin
    -- Sort array so it can serve as cache identifier
    select into _tables array(select unnest(table_oids_in) as v order by v);

    -- Fetch route from cache
    select into _route route from altlast.routejoin_cache where tables=_tables and expires>now();
    if _route is not null then
        -- Route was available in cache, so finish early
        return _route;
    end if;

    -- Calculate new route
    select into _route altlast.routejoin_route_left(table_oids_in);

    -- Remove possibly existent expired routes
    delete from altlast.routejoin_cache where expires<=now();
    -- Store the new route
    insert into altlast.routejoin_cache (tables, route, expires)
    values (
        _tables,
        _route,
        now()+'1h'::interval
    );

    return _route;
end
$$;


--
-- Name: FUNCTION routejoin_route_left_cached(table_oids_in oid[]); Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON FUNCTION altlast.routejoin_route_left_cached(table_oids_in oid[]) IS 'Calculates routes between two tables and caches result.';



