CREATE FUNCTION altlast.rpt_vorlage(vflzid integer) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
    rec record;
    rpt text;
BEGIN

/*
SELECT vflz_id,altlast.rpt_vorlage(vflz_id) FROM altlast.vflz 
LIMIT 100;
*/
	SELECT v.c_vflz_vftyp,v.c_vflz_bearbstand,b.c_bere_res_abwbewe INTO rec FROM altlast.vflz_current_v v LEFT JOIN altlast.bere b USING(vflz_id) WHERE v.vflz_id=vflzid;

	IF rec IS NULL THEN
		RAISE EXCEPTION 'VFLZ_ID % unknown',vflzid;
	END IF;

	SELECT INTO rpt altlast.rpt_vorlage(rec.c_vflz_vftyp,rec.c_vflz_bearbstand,rec.c_bere_res_abwbewe);    

        RETURN rpt;
END;$$;



