--
-- Name: scaleextent(public.geometry, double precision, double precision); Type: FUNCTION; Schema: altlast; Owner: -
--

CREATE FUNCTION altlast.scaleextent(geom public.geometry, targetwidth_cm double precision, targetheight_cm double precision) RETURNS public.geometry
    LANGUAGE plpgsql
    AS $$
DECLARE
	exnt geometry;
BEGIN

	exnt := altlast.scaleextent(geom, targetwidth_cm,targetheight_cm, altlast.bestscalefactor(geom, targetwidth_cm ,targetheight_cm));
	RETURN exnt;
END
$$;


--
-- Name: FUNCTION scaleextent(geom public.geometry, targetwidth_cm double precision, targetheight_cm double precision); Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON FUNCTION altlast.scaleextent(geom public.geometry, targetwidth_cm double precision, targetheight_cm double precision) IS 'Calculate the best extent for gem when displayed at a given scalefactor';


--
-- Name: scaleextent(public.geometry, double precision, double precision, integer); Type: FUNCTION; Schema: altlast; Owner: -
--

CREATE FUNCTION altlast.scaleextent(geom public.geometry, targetwidth_cm double precision, targetheight_cm double precision, scalefactor integer) RETURNS public.geometry
    LANGUAGE plpgsql
    AS $$
DECLARE
	m_x double precision; -- multiplier in x direction for scaling
	m_y double precision; -- multiplier in y direction for scaling
	gx box2d;
	gy box2d;
	exnt geometry;
BEGIN
	m_x := (scalefactor*(targetwidth_cm/100.0)/2);
	m_y := (scalefactor*(targetheight_cm/100.0)/2);

	gx := ST_Expand(st_centroid(geom),m_x)::box2d;
	gy := ST_Expand(st_centroid(geom),m_y)::box2d;

	exnt := ST_setSRID(ST_MakeBox2d(ST_MakePoint(ST_XMin(gx),ST_YMin(gy),0),ST_MakePoint(ST_XMax(gx),ST_YMax(gy),0))::geometry,st_srid(geom));

	RETURN exnt;
END
$$;


--
-- Name: FUNCTION scaleextent(geom public.geometry, targetwidth_cm double precision, targetheight_cm double precision, scalefactor integer); Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON FUNCTION altlast.scaleextent(geom public.geometry, targetwidth_cm double precision, targetheight_cm double precision, scalefactor integer) IS 'Calculate the best extent for gem when displayed at a given scalefactor';


--
-- Name: subj_duplicates_find(integer, integer); Type: FUNCTION; Schema: altlast; Owner: -
--

CREATE FUNCTION altlast.subj_duplicates_find(subjid integer, lvl integer) RETURNS SETOF integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    rec record;
    adrcnt integer;
BEGIN

    -- exception wenn irgendwo mehr als eine Address zu einem subjekt erfasst
    SELECT max(foo.cnt) INTO adrcnt FROM (SELECT count(*) as cnt FROM altlast.subj s JOIN altlast.subj_adr sa ON sa.subj_id=s.subj_id JOIN altlast.adr a on a.adr_id=sa.adr_id GROUP BY s.subj_id) AS foo;
    IF adrcnt>1 THEN
        RAISE EXCEPTION 'Mehr als eine Adresse pro Person wird momentan hier nicht unterstützt.';
    END IF;


    IF lvl=1 THEN

        RETURN QUERY SELECT  DISTINCT s.subj_id AS s_subj_id
                FROM (SELECT DISTINCT subj_id,
                    regexp_split_to_table(altlast.concat_subj(name,vorname,taetigkeit),E'[-_\\/\)\(\ \"\,]') AS match FROM altlast.subj) m
                JOIN  altlast.subj s ON s.name LIKE '%'||m.match||'%'
                JOIN altlast.subj_adr sa1 ON sa1.subj_id=s.subj_id
                JOIN altlast.adr a1 on a1.adr_id=sa1.adr_id
                JOIN altlast.subj_adr sa2 ON sa2.subj_id=m.subj_id
                JOIN altlast.adr a2 on a2.adr_id=sa2.adr_id
                WHERE m.subj_id<>s.subj_id
                    AND m.match IS NOT NULL AND LENGTH(TRIM(m.match))>3
                    AND UPPER(m.match) NOT IN (SELECT UPPER(find) FROM altlast_admin.qs_token_mappings)
                    AND m.subj_id=subjid
                    AND ((a1.ort LIKE '%'||m.match||'%') OR (a2.postleitzahl::text LIKE '%'||m.match||'%'));

    ELSIF lvl=2 THEN

        RETURN QUERY SELECT  s.subj_id AS s_subj_id
                FROM (SELECT DISTINCT subj_id,
                    regexp_split_to_table(altlast.concat_subj(name,vorname,taetigkeit),E'[-_\\/\)\(\ \"\,]') AS match FROM altlast.subj) m
                JOIN  altlast.subj s ON s.name LIKE '%'||m.match||'%'
                WHERE m.subj_id<>s.subj_id
                    AND m.match IS NOT NULL AND LENGTH(TRIM(m.match))>3
                    AND UPPER(m.match) NOT IN (SELECT UPPER(find) FROM altlast_admin.qs_token_mappings)
                    AND m.subj_id=subjid GROUP BY s.name,s.subj_id;

    ELSIF lvl=3 then

        RETURN QUERY SELECT  s.subj_id AS s_subj_id
                FROM (SELECT DISTINCT subj_id,
                    regexp_split_to_table(altlast.qs_token_map(altlast.concat_subj(name,vorname,taetigkeit),'subj'),E'[-_\\/\)\(\ \"\,]') AS match FROM altlast.subj) m
                JOIN  altlast.subj s ON altlast.qs_token_map(s.name,'subj') LIKE '%'||m.match||'%'
                WHERE m.subj_id<>s.subj_id
                    AND m.match IS NOT NULL AND LENGTH(TRIM(m.match))>3
                    AND UPPER(m.match) NOT IN (SELECT UPPER(find) FROM altlast_admin.qs_token_mappings)
                    AND m.subj_id=subjid GROUP BY s.name,s.subj_id;
    else
	raise exception 'Only levels 1, 2 and 3 are valid.';
    END IF;

    RETURN;
END;$$;


--
-- Name: FUNCTION subj_duplicates_find(subjid integer, lvl integer); Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON FUNCTION altlast.subj_duplicates_find(subjid integer, lvl integer) IS 'findet mögliche Duplikate eines Subjekts und wendet unterschiedliche Schärfe bei der Suche an';


--
-- Name: subj_duplicates_remove(integer, integer[]); Type: FUNCTION; Schema: altlast; Owner: -
--

CREATE FUNCTION altlast.subj_duplicates_remove(subj_ref integer, subj_dups integer[]) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    subjdup integer;
    asql text;
    rec record;
    isben boolean;
    hasPers boolean;
    hasSubjKennung boolean;
BEGIN

    FOR subjdup IN SELECT subj_dups[i] FROM generate_series(array_lower(subj_dups,1), array_upper(subj_dups,1)) AS i LOOP

        SELECT count(*)>0 INTO isben FROM altlast_admin.acl_user WHERE subj_id=subjdup;
        IF isben THEN
		-- Prevent removal of users with account on Altlast
		RAISE EXCEPTION 'Systembenutzer können nicht entfernt werden.';
        END IF;

        IF subjdup != subj_ref THEN
		-- Cleanup altlast.bem_subj
		for rec in
			select bs2.bem_subj_id
			from altlast.bem_subj bs1
			join altlast.bem_subj bs2 on bs1.bem_id=bs2.bem_id
				and bs1.h_bem_subj_bez_art=bs2.h_bem_subj_bez_art and bs1.c_bem_subj_bez_art=bs2.c_bem_subj_bez_art
			where bs1.subj_id=subj_ref and bs2.subj_id=subjdup
		loop
			delete from altlast.bem_subj where bem_subj_id=rec.bem_subj_id and subj_id=subdup;
		end loop;
		update altlast.bem_subj set subj_id=subj_ref where subj_id=subjdup;

		-- Cleanup altlast.grun_subj
		for rec in
			select gs2.grun_subj_id
			from altlast.grun_subj gs1
			join altlast.grun_subj gs2 on gs1.grun_id=gs2.grun_id and gs1.h_eigentums_art=gs2.h_eigentums_art
				and gs1.c_eigentums_art=gs2.c_eigentums_art
			where gs1.subj_id=subj_ref and gs2.subj_id=subjdup
		loop
			delete from altlast.grun_subj where grun_subj_id=rec.grun_subj_id and subj_id=subjdup;
		end loop;
		update altlast.grun_subj set subj_id=subj_ref where subj_id=subjdup;

		-- Cleanup altlast.pers
		select count(*)>0 into hasPers from altlast.pers where subj_id=subj_ref;
		if not hasPers then
			-- Use entry of first duplicate if subject does not have an entry
			update altlast.pers set subj_id=subj_ref where subj_id=subjdup;
		else
			-- Remove duplicated entries
			delete from altlast.pers where subj_id=subjdup;
		end if;

		-- Merge subject data
		update altlast.subj set "name"=c.name, vorname=c.vorname, taetigkeit=c.taetigkeit, zusatzcodefeld=c.zusatzcodefeld
		from (select coalesce(s1."name", s2."name") as "name", coalesce(s1.vorname, s2.vorname) as vorname,
				coalesce(s1.taetigkeit, s2.taetigkeit) as taetigkeit,
				coalesce(s1.zusatzcodefeld, s2.zusatzcodefeld) as zusatzcodefeld
			from altlast.subj s1
			cross join altlast.subj s2
			where s1.subj_id=subj_ref and s2.subj_id=subjdup) c
		where subj_id=subj_ref;

		-- Merge address data
		update altlast.adr a set c_land=c.c_land, c_kanton=c.c_kanton, h_gem_id=c.h_gem_id, ort=c.ort, postleitzahl=c.postleitzahl,
			postleitzahl_zusatz=c.postleitzahl_zusatz, strasse=c.strasse, hausnummer=c.hausnummer, pf_ort=c.pf_ort,
			zusatzcodefeld=c.zusatzcodefeld, h_land=c.h_land, h_kanton=c.h_kanton
		from (select sa1.adr_id, coalesce(a1.c_land , a2.c_land) as c_land, coalesce(a1.c_kanton, a2.c_kanton) as c_kanton,
			coalesce(a1.h_gem_id, a2.h_gem_id) as h_gem_id, coalesce(a1.ort, a2.ort) as ort,
			coalesce(a1.postleitzahl, a2.postleitzahl) as postleitzahl,
			coalesce(a1.postleitzahl_zusatz, a2.postleitzahl_zusatz) as postleitzahl_zusatz,
			coalesce(a1.strasse, a2.strasse) as strasse, coalesce(a1.hausnummer, a2.hausnummer) as hausnummer,
			coalesce(a1.pf_ort, a1.pf_ort) as pf_ort, coalesce(a1.zusatzcodefeld, a2.zusatzcodefeld) as zusatzcodefeld,
			coalesce(a1.h_land, a2.h_land) as h_land, coalesce(a1.h_kanton, a2.h_kanton) as h_kanton
			from altlast.subj_adr sa1
			join altlast.adr a1 on sa1.adr_id=a1.adr_id
			cross join altlast.subj_adr sa2
			join altlast.adr a2 on sa2.adr_id=a2.adr_id
			where sa1.subj_id=subj_ref and sa2.subj_id=subjdup) c
		where a.adr_id=c.adr_id;

		-- Cleanup altlast.pm_doc_subj
		for rec in
			select p2.pm_doc_subj_id
			from altlast.pm_doc_subj p1
			join altlast.pm_doc_subj p2 on p1.h_pm_doc_subj_bez_art=p2.h_pm_doc_subj_bez_art and p1.c_pm_doc_subj_bez_art=p2.c_pm_doc_subj_bez_art
			where p1.subj_id=subj_ref and p2.subj_id=subjdup
		loop
			delete from altlast.pm_doc_subj where subj_id=subjdup;
		end loop;
		update altlast.pm_doc_subj set subj_id=subj_ref where subj_id=subjdup;

		-- Cleanup altlast.pm_cache_subj
		for rec in
			select p2.pm_cache_subj_id
			from altlast.pm_cache_subj p1
			join altlast.pm_cache_subj p2 on p1.h_pm_cache_subj_bez_art=p2.h_pm_cache_subj_bez_art and p1.c_pm_cache_subj_bez_art=p2.c_pm_cache_subj_bez_art
			where p1.subj_id=subj_ref and p2.subj_id=subjdup
		loop
			delete from altlast.pm_cache_subj where subj_id=subjdup;
		end loop;
		update altlast.pm_cache_subj set subj_id=subj_ref where subj_id=subjdup;

		-- Cleanup altlast.subj_category
		for rec in
			select sc2.subj_category_id
			from altlast.subj_category sc1
			join altlast.subj_category sc2 on sc1.h_category=sc2.h_category and sc1.c_category=sc2.c_category
			where sc1.subj_id=subj_ref and sc2.subj_id=subjdup
		loop
			delete from altlast.subj_category where subj_category_id = rec.subj_category_id;
		end loop;
		update altlast.subj_category set subj_id=subj_ref where subj_id=subjdup;

		-- Cleanup altlast.subj_vflz
		for rec in
			select v2.subj_vflz_id
			from altlast.subj_vflz v1
			join altlast.subj_vflz v2 on v1.c_subj_vflz_bez_art=v2.c_subj_vflz_bez_art and v1.grundstueck_nr=v2.grundstueck_nr
				and v1.vflz_id=v2.vflz_id and v1.h_subj_vflz_bez_art=v2.h_subj_vflz_bez_art
			where v1.subj_id=subj_ref and v2.subj_id=subjdup
		loop
			delete from altlast.subj_vflz_id where subj_id=rec.subj_vflz_id;
		end loop;
		update altlast.subj_vflz set subj_id=subj_ref where subj_id=subjdup;

		-- Cleanup altlast.tele
		for rec in
			select t1.tele_id as tele_id, t2.tele_id as dup_tele_id
			from altlast.tele t1
			join altlast.tele t2 on t1.tele=t2.tele and t1.c_tele_typ=t2.c_tele_typ and t1.h_tele_typ=t2.h_tele_typ
			where t1.subj_id=subj_ref and t2.subj_id=subjdup
		loop
			-- Merke notes
			update altlast.tele set bemerkungen=c.bemerkungen
			from (select coalesce(t1.bemerkungen, t2.bemerkungen)
				from altlast.tele t1
				join altlast.tele t2 on t1.tele=t2.tele and t1.c_tele_typ=t2.c_tele_typ and t1.h_tele_typ=t2.h_tele_typ
				where t1.tele_id=rec.tele_id and t2.tele_id=rec.dup_tele_id) c
			where tele_id=rec.tele_id;
			delete from altlast.tele where tele_id=rec.dup_tele_id;
		end loop;
		update altlast.tele set subj_id=subj_ref where subj_id=subjdup;



            DELETE FROM altlast.adr WHERE adr_id IN (SELECT adr_id FROM altlast.subj_adr WHERE subj_id=subjdup);
            DELETE FROM altlast.subj WHERE subj_id=subjdup;
        END IF;
    END LOOP;

END;$$;


--
-- Name: FUNCTION subj_duplicates_remove(subj_ref integer, subj_dups integer[]); Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON FUNCTION altlast.subj_duplicates_remove(subj_ref integer, subj_dups integer[]) IS 'setzt alle Referenzen auf Subjekte, die durch die in subj_dups angegebenen Werte von subj_id definiert sind, um auf das in subj_ref definierte Subjekt -> löscht alle Einträge in subj für die in subj_dups definierten Einträge';


--
-- Name: t(text); Type: FUNCTION; Schema: altlast; Owner: -
--

CREATE FUNCTION altlast.t(message_identifier text) RETURNS text
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
    qry text;
BEGIN
    begin
        -- Extract language from LC_NUMERIC and use German if setting does not yield de, it or fr
        select altlast.t(message_identifier, case when substring(current_setting('lc_numeric') from '^[^_]+') in('de', 'it', 'fr') then substring(current_setting('lc_numeric') from '^[^_]+') else 'de' end) into strict qry;

    exception when others then
        select msgstr
        from altlast_admin.setitem si
        join altlast_admin.setting s using(setitem_id)
        join altlast.translations t on s."value"=t.locale
        where si.key='language' and t.msgid=message_identifier and s.role_name=current_user into qry;
        if qry is NULL then
            qry := message_identifier;
        end if;
    end;
    RETURN qry;
END
$$;


--
-- Name: FUNCTION t(message_identifier text); Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON FUNCTION altlast.t(message_identifier text) IS 'Translates to users language';


--
-- Name: t(text, text); Type: FUNCTION; Schema: altlast; Owner: -
--

CREATE FUNCTION altlast.t(message_identifier text, target_language text) RETURNS text
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE 
        qry text;
BEGIN   
        select msgstr
        from altlast.translations t
        where t.locale=target_language and t.msgid=message_identifier into qry;
        if qry is NULL then
                qry := message_identifier;
        end if;
    RETURN qry;
END
$$;


--
-- Name: FUNCTION t(message_identifier text, target_language text); Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON FUNCTION altlast.t(message_identifier text, target_language text) IS 'Translates to given language';


--
-- Name: t_zeitraum(date, boolean, date, boolean, boolean); Type: FUNCTION; Schema: altlast; Owner: -
--

CREATE FUNCTION altlast.t_zeitraum(p_von date, p_vonjahr boolean, p_bis date, p_bisjahr boolean, p_bisheute boolean) RETURNS text
    LANGUAGE plpgsql IMMUTABLE COST 10
    AS $$
BEGIN
    -- Note that this is not really correct for Italian since word endings are not correctly handled depending on the vocals of the following word
    return (
        select coalesce(case when p_vonjahr then extract(year from p_von)::text else p_von::text end, altlast.t('unbekannt'))
        || ' ' || altlast.t('bis') || ' '
        || case when p_bisheute then
            altlast.t('heute')
        else coalesce(case when p_bisjahr then extract(year from p_bis)::text else p_bis::text end, altlast.t('unbekannt')) end
    );
END;$$;


