-- Name: FUNCTION t_zeitraum(p_von date, p_vonjahr boolean, p_bis date, p_bisjahr boolean, p_bisheute boolean); Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON FUNCTION altlast.t_zeitraum(p_von date, p_vonjahr boolean, p_bis date, p_bisjahr boolean, p_bisheute boolean) IS 'Displays a date range in the user''s language.';


--
-- Name: unterstand(integer); Type: FUNCTION; Schema: altlast; Owner: -
--

CREATE FUNCTION altlast.unterstand(pmvflid integer) RETURNS text
    LANGUAGE plpgsql STRICT
    AS $$
DECLARE
  rec record;
  res text;
  rescod text;
  cnt integer;
BEGIN

    FOR rec IN
      SELECT DISTINCT ON(pc.unterstand) tc.c_vflz_unterstand
        FROM altlast.pm_vfl pv
        JOIN altlast.pm_cache ch on ch.pm_vfl_id = pv.pm_vfl_id
        JOIN altlast.pm_task t on ch.tas_uid = t.tas_uid
        JOIN altlast.pm_process p on p.pro_uid = pv.pro_uid
        JOIN altlast.pm_processconf pc on pc.pro_uid=p.pro_uid
        JOIN altlast.pm_taskconf tc on tc.tas_uid=t.tas_uid
        LEFT JOIN altlast.cod c ON c.c_cli_id=2001 AND c.code=ch.status
      WHERE ch.status='CLOSED' AND pv.pm_vfl_id=pmvflid AND tc.unterstand IS NOT NULL AND pc.unterstand IS NOT NULL 
      ORDER BY pc.unterstand ASC,tc.unterstand ASC, ch.app_thread DESC, ch.del_index DESC
    LOOP
      res := rec.c_vflz_unterstand;
    END LOOP;

    RETURN res;

END;$$;


--
-- Name: FUNCTION unterstand(pmvflid integer); Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON FUNCTION altlast.unterstand(pmvflid integer) IS 'Gets c_vflz_unterstand for current state of a sto. See also function bearbstand.';


