CREATE FUNCTION altlast.util_add_bemgrp(p_bemgrp character varying, p_title character varying, p_description character varying, p_sort integer, p_public boolean, p_key_column character varying, p_rel_name character varying, p_multiple boolean) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
      bem_grp character varying;

BEGIN

SELECT bemgrp INTO bem_grp FROM altlast.bemgrp where bemgrp=p_bemgrp;

IF bem_grp IS NULL THEN 
   	insert into altlast.bemgrp (bemgrp, title, description, sort, public, key_column, rel_name, multiple)
	values (p_bemgrp, p_title, p_description, p_sort, p_public, p_key_column, p_rel_name, p_multiple);
ELSE
    	UPDATE altlast.bemgrp SET title = p_title, description = p_description, sort = p_sort, public = p_public, key_column = p_key_column, rel_name = p_rel_name, multiple = p_multiple  WHERE bemgrp = p_bemgrp;

END IF;

end;
$$;


