--
-- Name: util_add_report(text, text, text, boolean, text, integer, text, text, text, text, text, text, text); Type: FUNCTION; Schema: altlast; Owner: -
--

CREATE FUNCTION altlast.util_add_report(p_bezeichnung text, p_stylesheet text, p_kategorie text, p_standard boolean, p_vorschau text, p_sortierung integer, p_sqlquery text, p_xmldef text, p_whereclause text, p_orderclause text, p_inlinevariables text, p_transformer text, p_use text) RETURNS void
    LANGUAGE plpgsql
    AS $$

    DECLARE
        r_report_id integer;
    BEGIN
    r_report_id := Null;

    select report_id into r_report_id from altlast.rpt_report 
        where kategorie = p_kategorie
        and standard = p_standard
        limit 1;

    if r_report_id is not null then 
       update altlast.rpt_report set
        bezeichnung = p_bezeichnung,
         stylesheet = p_stylesheet, 
         vorschau = p_vorschau, 
         sortierung = p_sortierung, 
         sqlquery = p_sqlquery, 
         xmldef = p_xmldef, 
         whereclause = p_whereclause, 
         orderclause = p_orderclause, 
         inlinevariables = p_inlinevariables, 
         transformer = p_transformer
    where report_id= r_report_id; 

    else
        insert into altlast.rpt_report (bezeichnung, stylesheet, kategorie, standard, vorschau, sortierung, sqlquery, xmldef, whereclause, orderclause, inlinevariables, transformer) 
        values (p_bezeichnung, p_stylesheet, p_kategorie, p_standard, p_vorschau, p_sortierung, p_sqlquery, p_xmldef, p_whereclause, p_orderclause, p_inlinevariables, p_transformer) RETURNING report_id INTO r_report_id;
    end if;

    IF p_use IS NOT NULL THEN
    insert into altlast.rpt_use (report_id, rpt_use) 
        select r_report_id, p_use
        except
        select report_id, rpt_use from altlast.rpt_use;
    END IF;

    END;
$$;


--
-- Name: FUNCTION util_add_report(p_bezeichnung text, p_stylesheet text, p_kategorie text, p_standard boolean, p_vorschau text, p_sortierung integer, p_sqlquery text, p_xmldef text, p_whereclause text, p_orderclause text, p_inlinevariables text, p_transformer text, p_use text); Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON FUNCTION altlast.util_add_report(p_bezeichnung text, p_stylesheet text, p_kategorie text, p_standard boolean, p_vorschau text, p_sortierung integer, p_sqlquery text, p_xmldef text, p_whereclause text, p_orderclause text, p_inlinevariables text, p_transformer text, p_use text) IS 'Utility function to add reports';


--
-- Name: util_add_report_param(text, text, text, text, text, text); Type: FUNCTION; Schema: altlast; Owner: -
--

CREATE FUNCTION altlast.util_add_report_param(p_r_kategorie text, p_p_tag text, p_p_bezeichnung text, p_p_datentyp text, p_p_lookup text, p_p_standardwert text) RETURNS void
    LANGUAGE plpgsql
    AS $$

    DECLARE
        p_r_report_id integer;
        p_p_param_id integer;
        is_new boolean;
    BEGIN


    select report_id into p_r_report_id from altlast.rpt_report where kategorie = p_r_kategorie;
    if p_r_report_id is null then
        raise notice 'No report found. No params updated';
        return;
    end if;
    select param_id into p_p_param_id from altlast.rpt_param where tag=p_p_tag and bezeichnung=p_p_bezeichnung;

    is_new := (p_p_param_id IS NULL);

    if p_p_param_id is null then
      insert into altlast.rpt_param (tag , bezeichnung , datentyp , lookup , standardwert )
      values (p_p_tag , p_p_bezeichnung , p_p_datentyp , p_p_lookup , p_p_standardwert );
    end if;

    select param_id into p_p_param_id from altlast.rpt_param where tag=p_p_tag and bezeichnung=p_p_bezeichnung;

    if (is_new=FALSE) and 
       (p_p_datentyp is not null or p_p_lookup is not null or p_p_standardwert is not null) then

      update altlast.rpt_param set 
      datentyp = coalesce(p_p_datentyp,datentyp),
      lookup = coalesce(p_p_lookup,lookup),
      standardwert = coalesce(p_p_standardwert,standardwert)
      where param_id=p_p_param_id;

    end if; 

    insert into altlast.rpt_report_param (report_id,param_id) select p_r_report_id,p_p_param_id
     except select report_id,param_id from altlast.rpt_report_param;

    END;
$$;


--
-- Name: FUNCTION util_add_report_param(p_r_kategorie text, p_p_tag text, p_p_bezeichnung text, p_p_datentyp text, p_p_lookup text, p_p_standardwert text); Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON FUNCTION altlast.util_add_report_param(p_r_kategorie text, p_p_tag text, p_p_bezeichnung text, p_p_datentyp text, p_p_lookup text, p_p_standardwert text) IS 'Define parameter for a report. 
If the parameter identified by its tag and bezeichnung is not already existent it will be created in table rpt_param.
If the values of the parama differ between thos given in the function and those in the table, the table will
be update with all values <> NULL.';


--
-- Name: util_add_user(text, text, text, text); Type: FUNCTION; Schema: altlast; Owner: -
--

CREATE FUNCTION altlast.util_add_user(pname text, pvorname text, ptaetigkeit text, pkuerzel text) RETURNS void
    LANGUAGE plpgsql
    AS $$
    DECLARE
        subjid integer;
        user_cnt integer;
    BEGIN

    SELECT subj_id INTO subjid FROM altlast.subj where name=pname and vorname=pvorname;

    IF subjid IS NULL THEN
        perform setval('altlast.subj_subj_id_seq',(SELECT max(subj_id)+1 from altlast.subj));
        INSERT INTO altlast.subj (name,vorname,taetigkeit) VALUES
        (pname,pvorname,ptaetigkeit) RETURNING subj_id INTO subjid;
    END IF;

    SELECT COUNT(*) INTO user_cnt FROM altlast_admin.acl_user au WHERE au.subj_id = subjid and au.rolname!=pkuerzel;
    IF user_cnt > 0 THEN
        DELETE FROM altlast_admin.acl_role_user WHERE user_id in 
            (select user_id from altlast_admin.acl_user au where au.subj_id = subjid and au.rolname!=pkuerzel);
        DELETE FROM altlast_admin.acl_user au WHERE au.subj_id = subjid and au.rolname!=pkuerzel;
    END IF;

    --the newly assigend subj_id takes precedence over existing ones
    SELECT COUNT(*) INTO user_cnt FROM altlast_admin.acl_user au WHERE au.rolname=pkuerzel;
    IF user_cnt > 0 THEN
        UPDATE altlast_admin.acl_user au SET subj_id = subjid WHERE au.rolname=pkuerzel;
    ELSE
        perform altlast_admin.save_user(subjid, pkuerzel, 'testtest', 'altlast');
    END IF;    

    END;
$$;


--
-- Name: FUNCTION util_add_user(pname text, pvorname text, ptaetigkeit text, pkuerzel text); Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON FUNCTION altlast.util_add_user(pname text, pvorname text, ptaetigkeit text, pkuerzel text) IS 'Creates a new user for altlast4web. checks existence in subj and adds record if missing.';


--
-- Name: util_add_user(text, text, text, text, text); Type: FUNCTION; Schema: altlast; Owner: -
--

CREATE FUNCTION altlast.util_add_user(pname text, pvorname text, ptaetigkeit text, pkuerzel text, pemail text) RETURNS void
    LANGUAGE plpgsql
    AS $$
    DECLARE
        subjid integer;
        user_cnt integer;
        teleid integer;
    BEGIN

    SELECT subj_id INTO subjid FROM altlast.subj where name=pname and vorname=pvorname;

    IF subjid IS NULL THEN
        perform setval('altlast.subj_subj_id_seq',(SELECT max(subj_id)+1 from altlast.subj));
        INSERT INTO altlast.subj (name,vorname,taetigkeit) VALUES
        (pname,pvorname,ptaetigkeit) RETURNING subj_id INTO subjid;
    END IF;

    SELECT tele_id INTO teleid FROM altlast.tele where subj_id=subjid and c_tele_typ='EMAIL' and tele=pemail;

    IF teleid IS NULL THEN
        INSERT INTO altlast.tele (tele, c_tele_typ, subj_id) VALUES (pemail, 'EMAIL', subjid);
    END IF;

    SELECT COUNT(*) INTO user_cnt FROM altlast_admin.acl_user au WHERE au.subj_id = subjid and au.rolname!=pkuerzel;
    IF user_cnt > 0 THEN
        DELETE FROM altlast_admin.acl_role_user WHERE user_id in 
            (select user_id from altlast_admin.acl_user au where au.subj_id = subjid and au.rolname!=pkuerzel);
        DELETE FROM altlast_admin.acl_user au WHERE au.subj_id = subjid and au.rolname!=pkuerzel;
    END IF;

    --the newly assigend subj_id takes precedence over existing ones
    SELECT COUNT(*) INTO user_cnt FROM altlast_admin.acl_user au WHERE au.rolname=pkuerzel;
    IF user_cnt > 0 THEN
        UPDATE altlast_admin.acl_user au SET subj_id = subjid WHERE au.rolname=pkuerzel;
    ELSE
        perform altlast_admin.save_user(subjid, pkuerzel, 'testtest', 'altlast');
    END IF;    

    END;
$$;


--
-- Name: FUNCTION util_add_user(pname text, pvorname text, ptaetigkeit text, pkuerzel text, pemail text); Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON FUNCTION altlast.util_add_user(pname text, pvorname text, ptaetigkeit text, pkuerzel text, pemail text) IS 'Creates a new user for altlast4web. Checks existence in subj and adds record if missing. Also adds email if missing.';


