CREATE FUNCTION altlast.util_create_codelist(p_c_cli_id integer, p_bemerkungen text) RETURNS text
    LANGUAGE plpgsql
    AS $$
    DECLARE
        codelist_exists boolean;
        msgid text;
    BEGIN
        select count(*)>0 into codelist_exists from altlast.c_cli
        where c_cli_id=p_c_cli_id;

        if codelist_exists=FALSE then
            insert into altlast.c_cli (c_cli_id, bezeichnung, bemerkungen)
            values(p_c_cli_id, 'code.' || p_c_cli_id, p_bemerkungen);
