--
-- Name: util_ensure_code_contraint(text, text, text, integer, boolean); Type: FUNCTION; Schema: altlast; Owner: -
--

CREATE FUNCTION altlast.util_ensure_code_contraint(p_schema text, p_table_name text, p_attribute text, p_h_column_restriction integer, p_match_simple boolean) RETURNS void
    LANGUAGE plpgsql
    AS $$
declare
    constraint_name text;
    check_name text;
begin
    constraint_name = 'fk_'||p_table_name||'_'||p_attribute;

    execute altlast.util_drop_constraint_if_exists(p_schema, p_table_name, constraint_name);
    -- Create a foreign key to altlast.cod
    execute 'ALTER TABLE ' || quote_ident(p_schema)||'.'||quote_ident(p_table_name) || ' ADD CONSTRAINT ' || quote_ident(constraint_name) || ' FOREIGN KEY ('||quote_ident('h_'||p_attribute)||', '||quote_ident('c_'||p_attribute)||') REFERENCES altlast.cod (c_cli_id, code) MATCH '|| case when p_match_simple=false then 'FULL' else 'SIMPLE' end || ' ON UPDATE CASCADE ON DELETE RESTRICT';

    if p_h_column_restriction is not null then
        -- Force code list
        check_name = 'chk_'||p_table_name||'_h_'||p_attribute;
        execute altlast.util_drop_constraint_if_exists(p_schema, p_table_name, check_name);
        execute 'ALTER TABLE ' || quote_ident(p_schema)||'.'||quote_ident(p_table_name) || ' ADD CONSTRAINT ' || quote_ident(check_name) || ' CHECK ('||quote_ident('h_'||p_attribute)||'='||quote_literal(p_h_column_restriction)||')';
    end if;

    -- Ignore foreign key in historization
    update altlast_hist.hist_tables set ignore_fks=(
        select array_agg(r.col)
        from (
            select unnest((select ignore_fks from altlast_hist.hist_tables where schema_name=p_schema and table_name=p_table_name)) as col
            union
            select 'h_'||p_attribute
            union
            select 'c_'||p_attribute
        ) r
    ) where schema_name=p_schema and table_name=p_table_name;
end;
$$;


--
-- Name: FUNCTION util_ensure_code_contraint(p_schema text, p_table_name text, p_attribute text, p_h_column_restriction integer, p_match_simple boolean); Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON FUNCTION altlast.util_ensure_code_contraint(p_schema text, p_table_name text, p_attribute text, p_h_column_restriction integer, p_match_simple boolean) IS 'Links code attribute (consisting of h- and c-colums) to altlast.cod.';


