--
-- Name: util_save_code(integer, text); Type: FUNCTION; Schema: altlast; Owner: -
--

CREATE FUNCTION altlast.util_save_code(p_c_cli_id integer, p_code text) RETURNS text
    LANGUAGE plpgsql
    AS $$
    DECLARE
        code_exists boolean;
        msgid text;
    BEGIN
        select count(*)>0 into code_exists
        from altlast.cod
        where c_cli_id=p_c_cli_id and code=p_code;

        if code_exists=TRUE then
            update altlast.cod set c_status=TRUE
            where c_cli_id=p_c_cli_id and code=p_code;
        else
            insert into altlast.cod (c_cli_id, code, c_status)
            values (p_c_cli_id, p_code, TRUE);
        end if;

        select altlast.msgid_code(p_c_cli_id, p_code) into msgid;
        return msgid;
    END;
$$;


--
-- Name: FUNCTION util_save_code(p_c_cli_id integer, p_code text); Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON FUNCTION altlast.util_save_code(p_c_cli_id integer, p_code text) IS 'Creates or enables a code and returs its translation identifier. Use altlast.util_save_translation to provide the visual representation of the code.';


--
-- Name: util_save_code(integer, text, integer); Type: FUNCTION; Schema: altlast; Owner: -
--

CREATE FUNCTION altlast.util_save_code(p_c_cli_id integer, p_code text, p_sort integer) RETURNS text
    LANGUAGE plpgsql
    AS $$
    DECLARE
        code_exists boolean;
        msgid text;
    BEGIN
        select count(*)>0 into code_exists
        from altlast.cod
        where c_cli_id=p_c_cli_id and code=p_code;

        if code_exists=TRUE then
            update altlast.cod set c_status=TRUE, sort_key=p_sort
            where c_cli_id=p_c_cli_id and code=p_code;
        else
            insert into altlast.cod (c_cli_id, code, c_status, sort_key)
            values (p_c_cli_id, p_code, TRUE, p_sort);
        end if;

        select altlast.msgid_code(p_c_cli_id, p_code) into msgid;
        return msgid;
    END;
$$;


