--
-- Name: util_save_route(name, name, name[], name, name, name[], boolean, character varying); Type: FUNCTION; Schema: altlast; Owner: -
--

CREATE FUNCTION altlast.util_save_route(p_t_pk_schema name, p_t_pk_table name, p_t_pk_columns name[], p_t_fk_schema name, p_t_fk_table name, p_t_fk_columns name[], p_left_join boolean, p_action character varying) RETURNS void
    LANGUAGE plpgsql
    AS $$

    DECLARE
        _ru_id integer;
    BEGIN
	-- Left and right part of join condition is the same thing, so both cases need to be checked
	select ru_id into _ru_id from altlast.routejoin_userdefined
	where t_pk_schema=p_t_pk_schema and t_pk_table=p_t_pk_table and t_pk_columns=p_t_pk_columns
		and t_fk_schema=p_t_fk_schema and t_fk_table=p_t_fk_table and t_fk_columns=p_t_fk_columns
	union
	select ru_id from altlast.routejoin_userdefined
	where t_fk_schema=p_t_pk_schema and t_fk_table=p_t_pk_table and t_fk_columns=p_t_pk_columns
		and t_pk_schema=p_t_fk_schema and t_pk_table=p_t_fk_table and t_pk_columns=p_t_fk_columns;

	if _ru_id is null then
		-- insert route since it's not yet present
		insert into altlast.routejoin_userdefined(t_pk_schema, t_pk_table, t_pk_columns, t_fk_schema, t_fk_table, t_fk_columns, left_join, "action")
		values (p_t_pk_schema, p_t_pk_table, p_t_pk_columns, p_t_fk_schema, p_t_fk_table, p_t_fk_columns, p_left_join, p_action);
	else
		-- Update existing route
		update altlast.routejoin_userdefined set t_pk_schema=p_t_pk_schema, t_pk_table=p_t_pk_table, t_pk_columns=p_t_pk_columns,
			t_fk_schema=p_t_fk_schema, t_fk_table=p_t_fk_table, t_fk_columns=p_t_fk_columns, left_join=p_left_join, "action"=p_action
		where ru_id=_ru_id;
	end if;

    END;
$$;


