--

CREATE FUNCTION altlast.util_save_translation(p_msgid character varying, p_msgstr character varying, p_locale character varying) RETURNS void
    LANGUAGE plpgsql
    AS $$
    BEGIN
    perform msgid from altlast.translations where msgid=p_msgid and locale=p_locale;
    if FOUND then
        update altlast.translations set msgstr=p_msgstr where msgid=p_msgid and locale=p_locale and msgstr!=p_msgstr;
    else
        insert into altlast.translations (msgid, msgstr, locale) values (p_msgid, p_msgstr, p_locale);
    end if;
    END;
$$;


