--
-- Name: util_set_cod_kbscolor(integer, text, integer, text, text); Type: FUNCTION; Schema: altlast; Owner: -
--

CREATE FUNCTION altlast.util_set_cod_kbscolor(p_h_bere_res_abwbewe integer, p_c_bere_res_abwbewe text, p_h_vflz_bearbstand integer, p_c_vflz_bearbstand text, p_color text) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Note: color_rgb column is written by mapserver_color trigger on altlast.cod_kbscolor

    -- Update only if this would change code to keep modification times as untouched as possible
    update altlast.cod_kbscolor set color=p_color where h_bere_res_abwbewe=p_h_bere_res_abwbewe and c_bere_res_abwbewe=p_c_bere_res_abwbewe and h_vflz_bearbstand=p_h_vflz_bearbstand and c_vflz_bearbstand=p_c_vflz_bearbstand and color!=p_color;
    -- Insert color if not yet there
    insert into altlast.cod_kbscolor (color, h_bere_res_abwbewe, c_bere_res_abwbewe, h_vflz_bearbstand, c_vflz_bearbstand)
    select p_color, p_h_bere_res_abwbewe, p_c_bere_res_abwbewe, p_h_vflz_bearbstand, p_c_vflz_bearbstand
    except
    select color, h_bere_res_abwbewe, c_bere_res_abwbewe, h_vflz_bearbstand, c_vflz_bearbstand
    from altlast.cod_kbscolor;
END;
$$;


