--
-- Name: util_set_report_parameters(text, text[]); Type: FUNCTION; Schema: altlast; Owner: -
--

CREATE FUNCTION altlast.util_set_report_parameters(p_report_kategorie text, p_parameter_tags text[]) RETURNS void
    LANGUAGE plpgsql
    AS $$
    BEGIN
    -- Ensure report has all required parameters
    insert into altlast.rpt_report_param (report_id, param_id)
    select 
        (select report_id from altlast.rpt_report where kategorie = p_report_kategorie) as report_id, 
        param_id
    from altlast.rpt_param
    where p_parameter_tags @> array[tag::text]
    except
    select report_id, param_id
    from altlast.rpt_report_param;

    -- Remove parameters that are bound to report but have not been given
    delete from altlast.rpt_report_param
    where report_id = (select report_id from altlast.rpt_report where kategorie = p_report_kategorie)
        and param_id in (
            select param_id
            from altlast.rpt_param
            where not(p_parameter_tags @> array[tag::text])
        );
END;
$$;


--
-- Name: FUNCTION util_set_report_parameters(p_report_kategorie text, p_parameter_tags text[]); Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON FUNCTION altlast.util_set_report_parameters(p_report_kategorie text, p_parameter_tags text[]) IS 'Creates or deletes entries in altlast.rpt_report_param so that the report is bound to the given parameters (and only to those parameters).';


--
-- Name: vflgeo_supports_geometrytype(public.geometry); Type: FUNCTION; Schema: altlast; Owner: -
--

CREATE FUNCTION altlast.vflgeo_supports_geometrytype(p_wkb_geoemtry public.geometry) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
declare
    constraintSource text;
    queryCheck text;
    geometryTypeSupported boolean;

    tableName text;
    schemaName text;
    columnName text;
    constraintName text;
begin
    tableName := 'vflgeo';
    columnName := 'wkb_geometry';
    schemaName := 'altlast';
    constraintName := 'enforce_geometry_type_wkb_geometry';

    -- fetch the source of the existing contraint
    select pg_get_expr(pcs.conbin, pcs.conrelid) into constraintSource
        from pg_class pc
        join pg_namespace pn on  pn.oid = pc.relnamespace and pn.nspname = schemaName
        join pg_attribute pa on pa.attrelid = pc.oid and pa.attname = columnName
        join pg_constraint pcs on pcs.conrelid = pc.oid and pcs.conkey = array[pa.attnum]
              and pcs.conname = constraintName
        where pc.relname = tableName;

    if constraintSource is null then
        raise exception 'No constraint % on %.% found. Can not determinate which geometrytypes are supported',
                    constraintName, schemaName, tableName;
    end if;

    queryCheck := 'select exists(select true from (' ||
        ' select st_GeomFromWKB(' || quote_literal(st_asbinary(p_wkb_geoemtry)) || '::bytea) as "'|| columnName || '"'
        ') foo ' ||
        ' where ' || constraintSource || ')';
    execute queryCheck into geometryTypeSupported;

    return geometryTypeSupported is not distinct from true;
end;
$$;


--
-- Name: FUNCTION vflgeo_supports_geometrytype(p_wkb_geoemtry public.geometry); Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON FUNCTION altlast.vflgeo_supports_geometrytype(p_wkb_geoemtry public.geometry) IS 'Function to check if altlast.vflgeo supports the storage of gemetries of the type of the given geometry. Depends on the contraint on vflgeo.wkb_geometry';


--
-- Name: vflz_laufnr(integer); Type: FUNCTION; Schema: altlast; Owner: -
--

CREATE FUNCTION altlast.vflz_laufnr(objeid integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  rec RECORD;
  lnr INTEGER;
BEGIN
/*
SELECT vflz_id,vflz_laufnr,altlast.vflz_laufnr(obje_id) FROM altlast.vflz_current_v LIMIT 5;

*/
    IF objeid IS NULL THEN
        RAISE EXCEPTION 'obje_id must not be empty';
    END IF;

    SELECT INTO rec COUNT(*) AS cnt, MAX(vflz_laufnr::integer) AS max FROM altlast.vflz_current_v WHERE obje_id=objeid GROUP BY obje_id ;

    IF rec IS NULL THEN
        RAISE EXCEPTION 'No records found for obje_id %', objeid;
    END IF;    

    lnr := INT4LARGER(COALESCE(rec.cnt,0)::integer,COALESCE(rec.max,0)::integer)+1;

    RETURN lnr;
END;$$;


