--

COMMENT ON FUNCTION altlast.vflz_laufnr(objeid integer) IS 'Calculate running number within a mother standort';


--
-- Name: zeitraum_bis(date, date, boolean); Type: FUNCTION; Schema: altlast; Owner: -
--

CREATE FUNCTION altlast.zeitraum_bis(acc date, indate date, inheute boolean) RETURNS date
    LANGUAGE plpgsql STABLE
    AS $$
  BEGIN
    if inheute or indate is null then
        -- Set aggregate to unknown value since an input value is unknown
        return '2999-01-01'::date;
    end if;

    IF indate IS NULL AND COALESCE(inheute,false,inheute) THEN
      RETURN '2999-01-01'::date;
    ELSE
      IF indate IS NULL THEN
        RETURN acc;
      ELSE
        IF COALESCE(acc,'1000-01-01'::date,acc)<indate THEN
          RETURN indate;
        ELSE
          RETURN acc;
        END IF;
      END IF;
    END IF;

  END;
$$;


