--
-- Name: zeitraum_bis_jahr(altlast.zeitraum_jahr, date, boolean, boolean); Type: FUNCTION; Schema: altlast; Owner: -
--

CREATE FUNCTION altlast.zeitraum_bis_jahr(acc altlast.zeitraum_jahr, indate date, injahr boolean, inheute boolean) RETURNS altlast.zeitraum_jahr
    LANGUAGE plpgsql
    AS $$
  DECLARE
    d date;
    j boolean;
    a altlast.zeitraum_jahr;
  BEGIN

    a := acc;
  
    IF indate IS NULL AND NOT COALESCE(inheute,false,inheute) THEN      
      a.d := NULL;
      a.j := injahr;
      a.h := inheute;
    ELSE
      
      j := COALESCE(injahr,false,injahr);
      d := COALESCE(indate,'1000-02-02'::date,indate);
      IF j THEN
        d := (date_part('year',indate)::text||'-01-01')::date;
      ELSE
        d := indate;
      END IF;

      IF d >= COALESCE(acc.d,'1000-01-01'::date,acc.d) THEN
        a.d:=indate;        
        a.j:=j;     
        a.h:=inheute;   
      END IF;

    END IF;

    RETURN a;
    
  END;
$$;


