--

CREATE FUNCTION altlast.zeitraum_von(acc date, indate date) RETURNS date
    LANGUAGE plpgsql
    AS $$
  BEGIN
    IF acc IS NULL THEN
      RETURN null::date;
    ELSEIF indate IS NULL THEN
        RETURN null::date;
    ELSEIF acc>indate THEN
      RETURN indate;
    ELSE
      RETURN acc;
    END IF;
  END;
$$;


--
-- Name: FUNCTION zeitraum_von(acc date, indate date); Type: COMMENT; Schema: altlast; Owner: -
--

