--
-- Name: zeitraum_von_jahr(altlast.zeitraum_jahr, date, boolean); Type: FUNCTION; Schema: altlast; Owner: -
--

CREATE FUNCTION altlast.zeitraum_von_jahr(acc altlast.zeitraum_jahr, indate date, injahr boolean) RETURNS altlast.zeitraum_jahr
    LANGUAGE plpgsql
    AS $$
  DECLARE
    d date;
    j boolean;
    a altlast.zeitraum_jahr;
  BEGIN
  
    IF indate IS NULL THEN
      RETURN acc;
    ELSE

      a := acc;
      
      j := COALESCE(injahr,false,injahr);
      IF j THEN
        d := (date_part('year',indate)::text||'-12-31')::date;
      ELSE
        d := indate;
      END IF;

      IF d <= COALESCE(acc.d,'2999-12-31'::date,acc.d) THEN
        a.d:=indate;        
        a.j:=j;        
      END IF;

      RETURN a;

    END IF;
  END;
$$;


