CREATE FUNCTION altlast_admin._export_remove_search() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
	if new.search_id is not null and new.status in ('DONE', 'FAILED') then
		delete from altlast_admin.searchconf where searchconf_id in (
			select searchconf_id from altlast_admin.search where search_id=new.search_id
			);
		delete from altlast_admin.search where search_id = new.search_id;
	end if;
	return new;
END;$$;


