--
-- Name: _fts_searchfield_synchronize_fts_fields(); Type: FUNCTION; Schema: altlast_admin; Owner: -
--

CREATE FUNCTION altlast_admin._fts_searchfield_synchronize_fts_fields() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
	_delete_fts_field boolean = FALSE;
	_include_in_fts_index boolean = FALSE;
BEGIN
	-- Note that nesting of if clauses is required to prevent accessing uninitialized variables since NEW and OLD are not always available

	if
		-- The searchfield was deleted so remove index and content for it.
		TG_OP='DELETE'
	then
		_delete_fts_field = TRUE;
	elsif
		-- The searchfield is not to be included in FTS
		(TG_OP='UPDATE' and not new.fts)
	then
		_delete_fts_field = TRUE;
	end if;
	if TG_OP='UPDATE' then
		-- The searchfield was renamed
		if new.label!=old.label then
			_delete_fts_field = TRUE;
		end if;
	end if;
	if _delete_fts_field=TRUE then
		delete from altlast.fts_field where field_key = 'searchfield: ' || old.label;
		-- Is potentially existent content in altlast.fts_field_content also removed?
	end if;

	if TG_OP='DELETE' then
		return old;
	else
		if
			-- The searchfield shall be included in FTS indexes, so add fts_key if missing
			(TG_OP='UPDATE' and new.fts)
			or
			-- A new searchfield was created
			(TG_OP='INSERT' and new.fts)
		then
			_include_in_fts_index = TRUE;
		end if;
		if TG_OP='UPDATE' then
			-- The searchfield was renamed
			if new.label!=old.label then
				_include_in_fts_index = TRUE;
			end if;
		end if;
		if _include_in_fts_index then
			insert into altlast.fts_field (field_name, field_key)
			select distinct new.label, 'searchfield: ' || new.label
			from altlast_admin.searchfield
			where 'searchfield: ' || new.label not in (select field_key from altlast.fts_field)
				and fts;
		end if;

		-- update FTS index for all affected locations
		--if new.fts then
		--	perform altlast.fts_vflz_collect();
		--end if;

		return new;
	end if;
END;$$;


--
-- Name: FUNCTION _fts_searchfield_synchronize_fts_fields(); Type: COMMENT; Schema: altlast_admin; Owner: -
--

COMMENT ON FUNCTION altlast_admin._fts_searchfield_synchronize_fts_fields() IS 'Synchronizes a row in altlast_admin.searchfield to altlast.fts_field';


--
-- Name: clean_history(); Type: FUNCTION; Schema: altlast_admin; Owner: -
--

CREATE FUNCTION altlast_admin.clean_history() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    DELETE FROM altlast_admin.history
  WHERE  (history.history_id IN ( SELECT history.history_id
           FROM altlast_admin.history WHERE user_id=NEW.user_id
          ORDER BY history."timestamp" DESC
         OFFSET 100));
    -- anmerkung: tatsaechlich wird immer ein eintrag mehr als der oben spezifizierte offset
    -- angezeigt, da direkt nach der ausfuehrung der funktion ein insert stattfindet
    DELETE FROM altlast_admin.history WHERE searchcategory_id=NEW.searchcategory_id AND user_id=NEW.user_id AND key_value=NEW.key_value;

   RETURN NEW;
END;$$;


--
-- Name: delete_user(integer); Type: FUNCTION; Schema: altlast_admin; Owner: -
--

CREATE FUNCTION altlast_admin.delete_user(subj integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
    DECLARE
        rec Record;
        role_rec Record;
    BEGIN
	SELECT * FROM altlast_admin.acl_user au WHERE au.subj_id = subj INTO rec;
        IF rec.subj_id IS NOT NULL THEN
		SELECT rolname FROM pg_roles WHERE rolname = rec.rolname INTO role_rec;
		IF role_rec IS NOT NULL THEN
			execute 'DROP ROLE ' || quote_ident(rec.rolname) || ';';
		END IF;
		DELETE FROM altlast_admin.acl_role_user WHERE user_id = rec.user_id;
		DELETE FROM altlast_admin.acl_user WHERE user_id = rec.user_id;
	ELSE
		raise exception 'No user exists for subj_id %', subj;
	END IF;
    END;
$$;


--
-- Name: FUNCTION delete_user(subj integer); Type: COMMENT; Schema: altlast_admin; Owner: -
--

COMMENT ON FUNCTION altlast_admin.delete_user(subj integer) IS 'Löscht alle passenden Einträge in altlast_admin.acl_user und altlast_admin.acl_role_user sowie den entsprechenden Benutzer aus der Datenbank.
Aufruf mit SELECT altlast_admin.delete_user([Subj_ID]);';


--
-- Name: getlastsearchgeo(integer); Type: FUNCTION; Schema: altlast_admin; Owner: -
--

CREATE FUNCTION altlast_admin.getlastsearchgeo(p_user_id integer) RETURNS SETOF integer
    LANGUAGE plpgsql
    AS $$
    DECLARE
        sqlquery text;
        rec Record;
    BEGIN
    SELECT sql FROM altlast_admin.lastsearch WHERE user_id = p_user_id INTO sqlquery;
    if sqlquery is null then
        -- No query there before a search was executed
        return;
    end if;
    if position('SELECT DISTINCT subj_kennung_v.subj_id AS data_id,' in sqlquery)=1 then
        -- No spatial data present for subjects yet
        return;
    end if;
    for rec in EXECUTE sqlquery loop
        return next rec.data_id;
    end loop;
    return;
    END $$;


--
-- Name: FUNCTION getlastsearchgeo(p_user_id integer); Type: COMMENT; Schema: altlast_admin; Owner: -
--

COMMENT ON FUNCTION altlast_admin.getlastsearchgeo(p_user_id integer) IS 'hightlighting the staos of the last search in mapserver';


--
-- Name: save_user(integer, text, text, text); Type: FUNCTION; Schema: altlast_admin; Owner: -
--

CREATE FUNCTION altlast_admin.save_user(p_subj_id integer, p_rolname text, p_password text, p_auth text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
    DECLARE
        subj_rolname text;
        user_cnt integer;
        auth_role text;
    BEGIN
        IF (COALESCE(p_rolname,'')='') THEN
            RAISE EXCEPTION 'Rolname must not be empty';
        END IF;
        IF (p_auth='altlast' and COALESCE(p_password,'')='') THEN
            RAISE EXCEPTION 'Empty password is not allowed for group altlast';
        END IF;

        IF (p_auth='altlast') THEN
            auth_role='altlast';
        ELSEIF (p_auth='ldap') THEN
            auth_role='altlast_ldap';
        ELSE
            auth_role='';
        END IF;

        select count(*) INTO user_cnt from pg_roles where rolname=auth_role AND rolcanlogin=FALSE;
        IF (auth_role!='' and user_cnt=0) THEN
            RAISE EXCEPTION 'The database doesn''t not provide the group role %',auth_role;
        END IF;

        --Rolname already in use?
        SELECT rolname FROM altlast_admin.acl_user au WHERE au.subj_id != p_subj_id AND lower(au.rolname)=lower(p_rolname) INTO subj_rolname;
        IF (subj_rolname IS NOT NULL) THEN
            RAISE EXCEPTION 'Role name % is already in use', p_rolname;
        END IF;

        --Should rolname be changed for an existing user?
        SELECT au.rolname FROM altlast_admin.acl_user au JOIN pg_roles pr ON pr.rolname=au.rolname WHERE au.subj_id = p_subj_id AND lower(au.rolname)!=lower(p_rolname) INTO subj_rolname;
        IF (subj_rolname IS NOT NULL) THEN
            EXECUTE 'ALTER ROLE ' || quote_ident(subj_rolname) || ' RENAME TO ' || quote_ident(p_rolname) || ';';
        END IF;

        perform rolname FROM pg_roles WHERE rolname = p_rolname;
        IF not FOUND THEN
            -- db role doesn't exist
            EXECUTE 'CREATE ROLE ' || quote_ident(p_rolname) || ' NOSUPERUSER INHERIT NOLOGIN;';
        END IF;

        --grant necessary roles
        EXECUTE 'REVOKE altlast FROM  ' || quote_ident(p_rolname) || ';';
        EXECUTE 'REVOKE altlast_ldap FROM  ' || quote_ident(p_rolname) || ';';
        IF p_auth = 'ldap' THEN
                EXECUTE 'ALTER ROLE ' || quote_ident(p_rolname) || ' LOGIN;';
                EXECUTE 'GRANT altlast TO ' || quote_ident(p_rolname) || ';';
                EXECUTE 'GRANT altlast_ldap TO ' || quote_ident(p_rolname) || ';';
        ELSIF COALESCE(p_password,'')<>'' AND p_auth = 'altlast' THEN
                EXECUTE 'ALTER ROLE ' || quote_ident(p_rolname) || ' LOGIN ;';
                EXECUTE 'ALTER ROLE ' || quote_ident(p_rolname) || ' WITH PASSWORD ' || quote_literal(p_password) || ';';
                EXECUTE 'GRANT altlast TO ' || quote_ident(p_rolname) || ';';
        ELSE --deactivate user
                EXECUTE 'ALTER ROLE ' || quote_ident(p_rolname) || ' NOLOGIN;';
        END IF;

        --go on to the acl_user part
        SELECT rolname FROM altlast_admin.acl_user au WHERE au.subj_id = p_subj_id INTO subj_rolname;
        IF (subj_rolname IS NULL) THEN
            INSERT INTO altlast_admin.acl_user (subj_id, rolname, auth) VALUES (p_subj_id, p_rolname, p_auth);
        ELSE
            UPDATE altlast_admin.acl_user au SET rolname = p_rolname, auth = p_auth WHERE subj_id = p_subj_id;
        END IF;

        RETURN user_id FROM altlast_admin.acl_user WHERE subj_id = p_subj_id;
    END;
$$;


--
-- Name: FUNCTION save_user(p_subj_id integer, p_rolname text, p_password text, p_auth text); Type: COMMENT; Schema: altlast_admin; Owner: -
--

COMMENT ON FUNCTION altlast_admin.save_user(p_subj_id integer, p_rolname text, p_password text, p_auth text) IS 'Erstellt neuen oder aktualisiert bestehenden Benutzer in der Datenbank und in altlast_admin.acl_user. Aufruf mit
SELECT altlast_admin.create_user([Subj_ID], [Benutzername], [Passwort], [Authenifizierung]);';


--
-- Name: setting_get(text, text); Type: FUNCTION; Schema: altlast_admin; Owner: -
--

CREATE FUNCTION altlast_admin.setting_get(p_setitem_key text, p_rolname text) RETURNS text
    LANGUAGE plpgsql
    AS $$
declare
	_result record;
begin
	if not exists(select * from altlast_admin.setitem se where se.key = p_setitem_key) then
		raise exception 'setitem key % does not exist', p_setitem_key;
	end if;

	select setting_id, "value" into _result from altlast_admin.setting st
		join altlast_admin.setitem se on se.setitem_id = st.setitem_id
		where se.key = p_setitem_key
			and st.role_name = p_rolname;
    if _result.setting_id is null then
        raise exception 'setting % for role % does not exist.',p_setitem_key, p_rolname;
    end if;
    return _result.value;
end
$$;


--
-- Name: FUNCTION setting_get(p_setitem_key text, p_rolname text); Type: COMMENT; Schema: altlast_admin; Owner: -
--

COMMENT ON FUNCTION altlast_admin.setting_get(p_setitem_key text, p_rolname text) IS 'return the value of a setting. Throws an excpetion if the setting is not found';


--
-- Name: setting_get_projection(); Type: FUNCTION; Schema: altlast_admin; Owner: -
--

CREATE FUNCTION altlast_admin.setting_get_projection() RETURNS integer
    LANGUAGE plpgsql IMMUTABLE
    AS $$
declare
    _epsg integer;
begin
    _epsg := altlast_admin.setting_get('map.projection.srid', 'default')::integer;

    if not exists(select * from public.spatial_ref_sys where srid = _epsg and _epsg is not null) then
        raise exception 'No spatial reference system with SRID % found', _epsg;
    end if;
    return _epsg; 
end
$$;


--
-- Name: FUNCTION setting_get_projection(); Type: COMMENT; Schema: altlast_admin; Owner: -
--

COMMENT ON FUNCTION altlast_admin.setting_get_projection() IS 'return epsg number of the configured projection';


--
-- Name: setting_set(text, text, text); Type: FUNCTION; Schema: altlast_admin; Owner: -
--

CREATE FUNCTION altlast_admin.setting_set(p_setitem_key text, p_rolname text, p_value text) RETURNS void
    LANGUAGE plpgsql
    AS $$
declare
	_setting_id integer;
begin

	if not exists(select * from altlast_admin.setitem se where se.key = p_setitem_key) then
		raise exception 'setitem key % does not exist', p_setitem_key;
	end if;

	select setting_id into _setting_id from altlast_admin.setting st
		join altlast_admin.setitem se on se.setitem_id = st.setitem_id
		where se.key = p_setitem_key
			and st.role_name = p_rolname;

	if  _setting_id is NULL then
		insert into altlast_admin.setting (setitem_id, role_name, "value") 
			select setitem_id, p_rolname, p_value
			from altlast_admin.setitem 
			where setitem.key = p_setitem_key limit 1;
	else
		update altlast_admin.setting
			set "value" = p_value
			where setting_id = _setting_id;
	end if;
end
$$;


