-- Name: FUNCTION setting_set(p_setitem_key text, p_rolname text, p_value text); Type: COMMENT; Schema: altlast_admin; Owner: -
--

COMMENT ON FUNCTION altlast_admin.setting_set(p_setitem_key text, p_rolname text, p_value text) IS 'Adds or updates a setting';


--
-- Name: update_searchfield_ident(); Type: FUNCTION; Schema: altlast_admin; Owner: -
--

CREATE FUNCTION altlast_admin.update_searchfield_ident() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
    ident_input text;

    tmp bigint;
    i int; 
    j int; 
    byte_length int; 
    word_array bytea;
begin

    -- collect a combination of the searchfield definitionin with as little client/gui specific stuff
    -- as possible. just the defintion relevant to the search implementation
    ident_input := coalesce(new.fld_type, '@') 
        || ':' || coalesce(new.lookup, '@') 
        || ':' || coalesce(new.search_type, '@') 
        || ':' || coalesce(new.rel_name, '@') 
        || ':' || coalesce(new.col, '@') 
        || ':' || coalesce(new.col_output, '@') 
        || ':' || coalesce(new.c_cli_id::text, '@');

    -- generate a crc32 checksum
    i := 0;
    tmp := 4294967295;
    byte_length := bit_length(ident_input) / 8; 
    word_array := decode(replace(ident_input, E'\\\\', E'\\\\\\\\'), 'escape');

    LOOP 
        tmp := (tmp # get_byte(word_array, i))::bigint;
        i := i + 1; 
        j := 0;
        LOOP 
            tmp := ((tmp >> 1) # (3988292384 * (tmp & 1)))::bigint;
            j := j + 1; 
            IF j >= 8 THEN 
                EXIT;
            END IF;
        END LOOP;
        IF i >= byte_length THEN 
            EXIT;
        END IF;
    END LOOP;
    new.searchfield_ident := (tmp # 4294967295);

    return new;
end;
$$;


--
-- Name: util_add_acl_action(text, text, boolean, text); Type: FUNCTION; Schema: altlast_admin; Owner: -
--

CREATE FUNCTION altlast_admin.util_add_acl_action(p_resource_name text, p_action_alias text, p_editable boolean, p_action_name text) RETURNS void
    LANGUAGE plpgsql
    AS $$

    DECLARE
        p_action_id integer;
        p_resource_id integer;
    BEGIN

    SELECT resource_id INTO p_resource_id FROM altlast_admin.acl_resource WHERE resource_name = p_resource_name;

    -- add resource if not available
    IF p_resource_id IS NULL THEN
        INSERT INTO altlast_admin.acl_resource (resource_name) VALUES (p_resource_name);
        SELECT resource_id INTO p_resource_id FROM altlast_admin.acl_resource WHERE resource_name = p_resource_name;
    END IF;

    SELECT action_id INTO p_action_id FROM altlast_admin.acl_action WHERE resource_id = p_resource_id AND action_alias = p_action_alias AND editable = p_editable AND action_name = p_action_name;

    IF p_action_id IS NULL THEN
        INSERT INTO altlast_admin.acl_action (resource_id, action_alias, editable, action_name) VALUES (p_resource_id, p_action_alias, p_editable, p_action_name);
    END IF;

	-- Rewrite permissions because another action might have been added with an already existing alias
	declare
		assignment record;
	begin
		for assignment in
		select distinct role_id, action_alias
		from altlast_admin.acl_acl
		join altlast_admin.acl_action on acl_action.action_id=acl_acl.action_id
		loop
			insert into altlast_admin.acl_acl (role_id, resource_id, action_id, allow)
			select assignment.role_id, resource_id, action_id, true
			from altlast_admin.acl_action
			where action_alias=assignment.action_alias
			except
			select role_id, acl_acl.resource_id, acl_acl.action_id, allow
            from altlast_admin.acl_acl
			join altlast_admin.acl_action on acl_action.action_id=acl_acl.action_id and acl_acl.resource_id=acl_action.resource_id
			where role_id=assignment.role_id and action_alias=assignment.action_alias;
		end loop;
	end;
    END;
$$;


--
-- Name: FUNCTION util_add_acl_action(p_resource_name text, p_action_alias text, p_editable boolean, p_action_name text); Type: COMMENT; Schema: altlast_admin; Owner: -
--

COMMENT ON FUNCTION altlast_admin.util_add_acl_action(p_resource_name text, p_action_alias text, p_editable boolean, p_action_name text) IS 'Utility function to add ACL actions';


--
-- Name: util_add_setitem(text, character varying, character varying, character, integer, integer, boolean, integer); Type: FUNCTION; Schema: altlast_admin; Owner: -
--

CREATE FUNCTION altlast_admin.util_add_setitem(p_key text, p_title character varying, p_description character varying, p_data_type character, p_sort integer, p_level integer, p_display boolean, p_codgrp_id integer) RETURNS void
    LANGUAGE plpgsql
    AS $$
declare
  p_setitem_id integer;
begin

  -- p_key text,
  -- p_title character varying(50), -- Bezeichnng der Einstellung
  -- p_description character varying,
  -- p_data_type character(1), -- Erlaubter Datenyp
  -- p_sort integer, -- Sortierung
  -- p_level integer, -- Beschreibt, wer Einträge ändern darf und für wen die Einräge gültig sind...
  -- p_display boolean, -- Attribut in allgemeiner Konfigurationsmaske darstellen oder generell ausblenden
  -- p_codgrp_id integer-- Referenz zu Codegruppen. Die erlaubten Werte für Einstellungen werden gegebenenfalls aus der Tabelle Code bezogen. Ohne Referenz zu einer Codegruppe ist freie Eingabe möglich.

select setitem_id into p_setitem_id from altlast_admin.setitem 
where "key"=p_key;

  if p_setitem_id is null then
    insert into altlast_admin.setitem (codgrp_id, data_type, title, description, sort, "level", 
            display, "key")
      VALUES (p_codgrp_id, p_data_type, p_title, p_description, p_sort, p_level, p_display, p_key);
  else
    update altlast_admin.setitem set
    codgrp_id=coalesce(p_codgrp_id,codgrp_id), data_type=coalesce(p_data_type,data_type), 
    title=coalesce(p_title,title), description=coalesce(p_description,description), 
    sort=coalesce(p_sort,sort),
    "level"=coalesce(p_level,"level"), display=coalesce(p_display,display)
    where "key"=p_key;
  end if;

end;
$$;


--
-- Name: FUNCTION util_add_setitem(p_key text, p_title character varying, p_description character varying, p_data_type character, p_sort integer, p_level integer, p_display boolean, p_codgrp_id integer); Type: COMMENT; Schema: altlast_admin; Owner: -
--

COMMENT ON FUNCTION altlast_admin.util_add_setitem(p_key text, p_title character varying, p_description character varying, p_data_type character, p_sort integer, p_level integer, p_display boolean, p_codgrp_id integer) IS 'Adds a new setitem';


