--

CREATE FUNCTION altlast_admin.util_execute_conditional(execution_condition boolean, commands_sql text) RETURNS void
    LANGUAGE plpgsql
    AS $$
begin
  if execution_condition is NULL then
    raise exception 'Cannot determine if commands shall be executed';
  end if;
  if execution_condition then
    execute commands_sql;
  end if;
end;
$$;


