CREATE FUNCTION altlast_admin.util_save_export_cfgoption(p_task_title text, p_phing_name text, p_parameter_title text, p_parameter_description text, p_value text) RETURNS void
    LANGUAGE plpgsql
    AS $$
    BEGIN

	insert into altlast_admin.export_cfgoption (export_cfgtask_id, phing_name, title, description, value)
