--
-- Name: util_save_jasper_export(text, text, text); Type: FUNCTION; Schema: altlast_admin; Owner: -
--

CREATE FUNCTION altlast_admin.util_save_jasper_export(p_title text, p_description text, p_path text) RETURNS integer
    LANGUAGE plpgsql
    AS $$
declare
  _export_cfgoption_id integer;
	_export_cfgtarget_id integer;
	_export_cfgcategory_id integer;
	_export_cfgtask_id integer;
begin
  SELECT export_cfgtarget_id INTO _export_cfgtarget_id FROM altlast_admin.export_cfgtarget WHERE phing_target = 'reports';
  SELECT export_cfgcategory_id INTO _export_cfgcategory_id FROM altlast_admin.export_cfgcategory WHERE title = 'Einzelreports';
	select export_cfgtask_id into _export_cfgtask_id from altlast_admin.export_cfgtask
		where phing_task = 'jasper' and title = p_title;


  SELECT export_cfgoption INTO _export_cfgoption_id FROM altlast_admin.export_cfgoption WHERE phing_name = 'path' AND export_cfgtask_id = _export_cfgtask_id;

	if _export_cfgtask_id is NULL then
	  SELECT max(export_cfgtask_id) + 1 into _export_cfgtask_id from altlast_admin.export_cfgtask;
		insert into altlast_admin.export_cfgtask (export_cfgtask_id, export_cfgtarget_id, export_cfgcategory_id, title, description, phing_task)
			values (_export_cfgtask_id, _export_cfgtarget_id, _export_cfgcategory_id, p_title, p_description, 'jasper');
	else
		update altlast_admin.export_cfgtask
			set export_cfgtarget_id = _export_cfgtarget_id, export_cfgcategory_id = _export_cfgcategory_id, description = p_description
			where export_cfgtask_id = _export_cfgtask_id;
	end if;

	select export_cfgtask_id into _export_cfgtask_id from altlast_admin.export_cfgtask
		where phing_task = 'jasper' and title = p_title;

	if _export_cfgoption_id is NULL then
		insert into altlast_admin.export_cfgoption (phing_name, title, "value", export_cfgtask_id)
			values ('path', 'Jasper Template path', p_path, _export_cfgtask_id);
	else
		update altlast_admin.export_cfgoption
			set "value" = p_path, title = 'Jasper Template path'
			where export_cfgoption = _export_cfgoption_id;
	end if;

	return _export_cfgtask_id;
end
$$;


--
-- Name: FUNCTION util_save_jasper_export(p_title text, p_description text, p_path text); Type: COMMENT; Schema: altlast_admin; Owner: -
--

COMMENT ON FUNCTION altlast_admin.util_save_jasper_export(p_title text, p_description text, p_path text) IS 'Adds or updates a Jasper export';


