--

CREATE FUNCTION altlast_admin.util_save_qs_category(p_title text, p_sort integer) RETURNS void
    LANGUAGE plpgsql
    AS $$
declare
  _qs_category_id integer;
begin
  select qs_category_id into _qs_category_id from altlast_admin.qs_category where title = p_title;

  if _qs_category_id is NULL then
    -- Create QA category
    insert into altlast_admin.qs_category (title, sort)
    values (p_title, p_sort);
  else
    -- Update QA task
    update altlast_admin.qs_category
    set title = p_title, sort = p_sort
    where qs_category_id = _qs_category_id;
  end if;
end
$$;


