--
-- Name: util_save_qs_task(text, text, text, name); Type: FUNCTION; Schema: altlast_admin; Owner: -
--

CREATE FUNCTION altlast_admin.util_save_qs_task(p_category text, p_title text, p_description text, p_view name) RETURNS void
    LANGUAGE plpgsql
    AS $$
declare
	_qs_task_id integer;
	_qs_task record;
begin
	select qs_task_id into _qs_task_id from altlast_admin.qs_task where ru_id = (
		select ru_id from altlast.routejoin_userdefined where t_pk_table=p_view or t_fk_table=p_view
	);

	select qs_category_id, p_title as title, p_description as description, ru_id, t_pk_columns as ru_columns, 'reason' as reason_column
	into _qs_task
	from altlast_admin.qs_category
	cross join altlast.routejoin_userdefined
	where qs_category.title=p_category and routejoin_userdefined.t_pk_table=p_view;

	if _qs_task_id is NULL then
		-- Create QA task
		insert into altlast_admin.qs_task (qs_category_id, title, description, ru_id, ru_columns, reason_column)
		values (_qs_task.qs_category_id, _qs_task.title, _qs_task.description, _qs_task.ru_id,
			_qs_task.ru_columns, _qs_task.reason_column);
	else
		-- Update QA task
		update altlast_admin.qs_task
		set qs_category_id = _qs_task.qs_category_id, title=_qs_task.title, description=_qs_task.description, ru_id=_qs_task.ru_id,
			ru_columns=_qs_task.ru_columns, reason_column=_qs_task.reason_column
		where qs_task_id=_qs_task_id;
	end if;
end
$$;


--
-- Name: FUNCTION util_save_qs_task(p_category text, p_title text, p_description text, p_view name); Type: COMMENT; Schema: altlast_admin; Owner: -
--

COMMENT ON FUNCTION altlast_admin.util_save_qs_task(p_category text, p_title text, p_description text, p_view name) IS 'Adds or updates a task/entry to QA for a route';


--
-- Name: util_save_role(text, text, boolean); Type: FUNCTION; Schema: altlast_admin; Owner: -
--

CREATE FUNCTION altlast_admin.util_save_role(p_rolname text, p_password text, p_login boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$ 
DECLARE 
  sql text; 
  rol_name text; 
BEGIN 
  SELECT rolname INTO rol_name FROM pg_roles WHERE rolname = p_rolname; 
  IF rol_name IS NULL THEN 
  -- db role doesn't exist 
    sql := 'create role ' || quote_ident(p_rolname) || ' password ' || quote_literal(p_password) || ';';
  ELSE 
    sql := 'alter role ' || quote_ident(p_rolname) || ' with password ' || quote_literal(p_password) || ';'; 
  END IF; 
  EXECUTE sql; 
  IF p_login THEN 
    sql := 'alter role ' || quote_ident(p_rolname) || ' with login;'; 
  ELSE 
    sql := 'alter role ' || quote_ident(p_rolname) || ' with nologin;'; 
  END IF; 
  EXECUTE sql; 
END; 
$$;


--
-- Name: FUNCTION util_save_role(p_rolname text, p_password text, p_login boolean); Type: COMMENT; Schema: altlast_admin; Owner: -
--

COMMENT ON FUNCTION altlast_admin.util_save_role(p_rolname text, p_password text, p_login boolean) IS 'Erstellt neuen oder aktualisiert bestehenden DB-Benutzer. Verwendung beispielsweise für Benutzer von Excelreport. Aufruf mit SELECT altlast_admin.create_user([Benutzername], [Passwort], [Login]);';


--
-- Name: util_save_searchfield(character varying, integer, character varying, character varying, character varying, character varying, character varying, character varying, character varying, integer, character varying, character varying, character varying, boolean, boolean, text[]); Type: FUNCTION; Schema: altlast_admin; Owner: -
--

CREATE FUNCTION altlast_admin.util_save_searchfield(p_label character varying, p_width integer, p_fld_type character varying, p_lookup character varying, p_search_type character varying, p_rel_name character varying, p_col character varying, p_col_output character varying, p_searchfieldgroup_name character varying, p_c_cli_id integer, p_rel_alt character varying, p_col_alt character varying, p_special_icon character varying, p_translate_output boolean, p_fts boolean, p_searchcategories text[]) RETURNS integer
    LANGUAGE plpgsql
    AS $$
declare
    _matched_searchfields integer;
    _searchfieldgroup_id integer;
    _searchfield_id integer;
begin
    select searchfieldgroup_id into _searchfieldgroup_id from altlast_admin.searchfieldgroup where group_name=p_searchfieldgroup_name;
    if _searchfieldgroup_id is null then
        raise exception 'Search field group % was not found.', p_searchfieldgroup_name;
    end if;

    -- See if label identifies a searchfield, if not abort to prevent messing things up
    select count(*) into _matched_searchfields from altlast_admin.searchfield where label=p_label;
    if _matched_searchfields=0 then
        -- Insert searchfield
        insert into altlast_admin.searchfield (label, width, fld_type, lookup, search_type, rel_name, col, col_output, searchfieldgroup_id, c_cli_id, rel_alt, col_alt, special_icon, translate_output, fts) values (p_label, p_width, p_fld_type, p_lookup, p_search_type,  p_rel_name, p_col, p_col_output, _searchfieldgroup_id, p_c_cli_id, p_rel_alt, p_col_alt, p_special_icon, p_translate_output, p_fts);
    elsif _matched_searchfields=1 then
        -- Update
        update altlast_admin.searchfield set width=p_width, fld_type=p_fld_type, lookup=p_lookup, search_type=p_search_type, rel_name=p_rel_name, col=p_col, col_output=p_col_output, searchfieldgroup_id=_searchfieldgroup_id, c_cli_id=p_c_cli_id, rel_alt=p_rel_alt, col_alt=p_col_alt, special_icon=p_special_icon, translate_output=p_translate_output, fts=p_fts
        where label=p_label;
    else
        raise exception 'Couldn''t identify searchfield by label: %', p_label;
    end if;

    select searchfield_id into _searchfield_id from altlast_admin.searchfield where label=p_label;

    -- Ensure search field is listed in altlast_admin.searchfield_searchcategory
    if (select count(*)<array_upper(p_searchcategories, 1) from altlast_admin.searchcategory where category_name = any(p_searchcategories)) then
        -- At least one search category was specified that does not exist in the database
        raise exception 'A searchcategory is not existent: %', p_searchcategories;
    end if;
    delete from altlast_admin.searchfield_searchcategory
    where searchfield_id=_searchfield_id and searchcategory_id not in (
        select searchcategory_id from altlast_admin.searchcategory
        where category_name = any(p_searchcategories)
    );
    insert into altlast_admin.searchfield_searchcategory (searchcategory_id, searchfield_id)
    select searchcategory_id, _searchfield_id
    from altlast_admin.searchcategory
    where category_name = any(p_searchcategories)
        and not (searchcategory_id, _searchfield_id) in (
            select searchcategory_id, searchfield_id
            from altlast_admin.searchfield_searchcategory
        );

    return _searchfield_id;
end
$$;


--
-- Name: util_save_setting(text, text, text); Type: FUNCTION; Schema: altlast_admin; Owner: -
--

CREATE FUNCTION altlast_admin.util_save_setting(p_setitem_key text, p_rolname text, p_value text) RETURNS void
    LANGUAGE plpgsql
    AS $$
declare
	_setting_id integer;
begin
	select setting_id into _setting_id from altlast_admin.setting st
		join altlast_admin.setitem se on se.setitem_id = st.setitem_id
		where se.key = p_setitem_key
			and st.role_name = p_rolname;


	if  _setting_id is NULL then
		insert into altlast_admin.setting (setitem_id, role_name, "value") 
			select setitem_id, p_rolname, p_value
			from altlast_admin.setitem 
			where setitem.key = p_setitem_key limit 1;
	else
		update altlast_admin.setting
			set "value" = p_value
			where setting_id = _setting_id;
	end if;
end
$$;


--
-- Name: FUNCTION util_save_setting(p_setitem_key text, p_rolname text, p_value text); Type: COMMENT; Schema: altlast_admin; Owner: -
--

COMMENT ON FUNCTION altlast_admin.util_save_setting(p_setitem_key text, p_rolname text, p_value text) IS 'Adds or updates a setting';



--
-- Name: create_triggers(text); Type: FUNCTION; Schema: altlast_hist; Owner: -
--

CREATE FUNCTION altlast_hist.create_triggers(p_key_column text) RETURNS void
    LANGUAGE plpgsql
    AS $$
declare
    htable record;
    sqlstring text;
begin
        perform altlast_hist.drop_triggers(p_key_column);

    for htable in select ht.schema_name, ht.table_name, h.history_id, ht.master_table from altlast_hist.hist_tables ht join altlast_hist.history h on
        h.history_id = ht.history_id where h.key_column = p_key_column and p_key_column is not null loop

        sqlstring := 'create trigger "hist_' || htable.history_id || '" before update on "' || htable.schema_name || '"."' || htable.table_name || '" for each row execute procedure altlast_hist.hist_trigger();';
        execute sqlstring;

        sqlstring := 'create trigger "hist_delete_' || htable.history_id || '" before delete on "' || htable.schema_name || '"."' || htable.table_name || '" for each row execute procedure altlast_hist.hist_trigger_delete();';
        execute sqlstring;

        if htable.master_table = True then
          sqlstring := 'create trigger "hist_insert_' || htable.history_id || '" before insert on "' || htable.schema_name || '"."' || htable.table_name || '" for each row execute procedure altlast_hist.hist_insert_trigger();';
          execute sqlstring;
        end if;

    end loop;

end;
$$;


--
-- Name: FUNCTION create_triggers(p_key_column text); Type: COMMENT; Schema: altlast_hist; Owner: -
--

COMMENT ON FUNCTION altlast_hist.create_triggers(p_key_column text) IS 'Create  tiggers for all tables associated with one history_id (referenced rows ith the altlast_hist.tables table). ';


--
-- Name: drop_triggers(text); Type: FUNCTION; Schema: altlast_hist; Owner: -
--

CREATE FUNCTION altlast_hist.drop_triggers(p_key_column text) RETURNS void
    LANGUAGE plpgsql
    AS $$
declare
    htable record;
    sqlstring text;
begin

    for htable in select ht.schema_name, ht.table_name, h.history_id, ht.master_table from altlast_hist.hist_tables ht join altlast_hist.history h on
        h.history_id = ht.history_id where h.key_column = p_key_column and p_key_column is not null loop

        sqlstring := 'drop trigger if exists "hist_' || htable.history_id || '" on "' || htable.schema_name || '"."' || htable.table_name || '";';
        execute sqlstring;

        sqlstring := 'drop trigger if exists "hist_delete_' || htable.history_id || '" on "' || htable.schema_name || '"."' || htable.table_name || '";';
        execute sqlstring;

        if htable.master_table = True then
          sqlstring := 'drop trigger if exists "hist_insert_' || htable.history_id || '" on "' || htable.schema_name || '"."' || htable.table_name || '";';
          execute sqlstring;
        end if;

  end loop;

end;
$$;


--
-- Name: FUNCTION drop_triggers(p_key_column text); Type: COMMENT; Schema: altlast_hist; Owner: -
--

COMMENT ON FUNCTION altlast_hist.drop_triggers(p_key_column text) IS 'Remove Triggers from the tables in hist_tables referenced my the history_id';



