--

CREATE FUNCTION altlast_hist.histtrig_bem(p_bemgrp text, p_old_key_value integer, p_new_key_value integer) RETURNS void
    LANGUAGE plpgsql
    AS $$
begin
	insert into altlast.bem (
		bemgrp_id,
		public,
		sort,
		bem,
		erfassungs_datum,
		erfasser_kuerzel,
		mutations_datum,
		mutierer_kuerzel,
		key_value)
	(select
		bem.bemgrp_id,
		bem.public,
		bem.sort,
		bem.bem,
		bem.erfassungs_datum,
		bem.erfasser_kuerzel,
		bem.mutations_datum,
		bem.mutierer_kuerzel,
		p_new_key_value as key_value
	from altlast.bem
	join altlast.bemgrp on bem.bemgrp_id = bemgrp.bemgrp_id
	where bemgrp.bemgrp=p_bemgrp and bem.key_value = p_old_key_value
	);
end;
$$;


--
-- Name: FUNCTION histtrig_bem(p_bemgrp text, p_old_key_value integer, p_new_key_value integer); Type: COMMENT; Schema: altlast_hist; Owner: -
--

COMMENT ON FUNCTION altlast_hist.histtrig_bem(p_bemgrp text, p_old_key_value integer, p_new_key_value integer) IS 'Historizes annotations of given annotation groups as identified by bemgrp';


