--
-- Name: util_ignore_foreign_key(text); Type: FUNCTION; Schema: altlast_hist; Owner: -
--

CREATE FUNCTION altlast_hist.util_ignore_foreign_key(p_fk_name text) RETURNS void
    LANGUAGE plpgsql
    AS $$
declare
    fk_columns record;
begin
	-- Find all referenced columns from given constraint names
	for fk_columns in
		select nspname, relname, attname
		from pg_catalog.pg_attribute
		join pg_catalog.pg_constraint on pg_attribute.attrelid=pg_constraint.conrelid and pg_attribute.attnum = any(pg_constraint.conkey)
		join pg_catalog.pg_class on pg_constraint.conrelid=pg_class.oid
		join pg_catalog.pg_namespace on pg_namespace.oid=pg_class.relnamespace
		where pg_constraint.conname=p_fk_name
	loop
		-- Add referenced column to array of columns that shall be ignored for historization
		update altlast_hist.hist_tables set ignore_fks=array(
			select altlast.explode_array(ignore_fks) as column_name
			from altlast_hist.hist_tables
			where table_name=fk_columns.relname and schema_name=fk_columns.nspname
			union
			select fk_columns.attname
		)
		where schema_name=fk_columns.nspname and table_name=fk_columns.relname;
	end loop;
end;
$$;


--
-- Name: FUNCTION util_ignore_foreign_key(p_fk_name text); Type: COMMENT; Schema: altlast_hist; Owner: -
--

COMMENT ON FUNCTION altlast_hist.util_ignore_foreign_key(p_fk_name text) IS 'Ignores the columns referenced by the given foreign key for historization.';


--
-- Name: _geoig_geometry_multipolygon(public.geometry); Type: FUNCTION; Schema: altlast_ili; Owner: -
--

CREATE FUNCTION altlast_ili._geoig_geometry_multipolygon(p_geom public.geometry) RETURNS xml
    LANGUAGE plpgsql STRICT
    AS $$
declare
    result xml;
    geom_type text;
    geom_srid integer;
begin
    geom_type := st_geometrytype(p_geom);
    geom_srid := st_srid(p_geom);
    if geom_type = 'ST_MultiPolygon' and geom_srid = 21781 then
        select xmlelement(name "KbS_LV03_V1_4.Belastete_Standorte.MultiPolygon",
            xmlelement(name "Polygones", xmlagg(geomxml))) into result
                        from (select altlast_ili._geoig_geometry_polygon_boundaries_internal(
                              st_geometryn(p_geom, generate_series(1,st_numgeometries(p_geom)))
                          )as geomxml
            ) foo;
    elsif geom_type = 'ST_MultiPolygon' and geom_srid = 2056 then
      select xmlelement(name "KbS_LV95_V1_4.Belastete_Standorte.MultiPolygon",
            xmlelement(name "Polygones", xmlagg(geomxml))) into result
                        from (select altlast_ili._geoig_geometry_polygon_boundaries_internal(
                              st_geometryn(p_geom, generate_series(1,st_numgeometries(p_geom)))
                          )as geomxml
            ) foo;
    elsif geom_type != 'ST_MultiPolygon' then
        raise 'unsupported geometry type: %', geom_type;
    else 
        raise 'unsupported geometry srid: %', geom_srid;
    end if;
    return result;
end
$$;


--
-- Name: _geoig_geometry_polygon_boundaries_internal(public.geometry); Type: FUNCTION; Schema: altlast_ili; Owner: -
--

CREATE FUNCTION altlast_ili._geoig_geometry_polygon_boundaries_internal(p_geom public.geometry) RETURNS xml
    LANGUAGE plpgsql STRICT
    AS $$
declare
    result xml;
    geom_type text;
    geom_srid integer;
    geom_numintrings integer;
begin
    geom_type := st_geometrytype(p_geom);
    geom_srid := st_srid(p_geom);
    geom_numintrings := st_numinteriorring(p_geom);
    if geom_type = 'ST_Polygon' and geom_srid = 21781 and geom_numintrings < 1 then
        select xmlagg(geoxmltext::xml) into result
                from (
                    select xmlelement(name "KbS_LV03_V1_4.Belastete_Standorte.PolygonStructure", 
                            xmlelement(name "Polygon",
                            xmlelement(name "SURFACE", 
                            xmlelement(name "BOUNDARY", geom))))::text as geoxmltext
                        from  (
                            select altlast_ili._geometry_line(
                                st_ExteriorRing(p_geom)
                                ) as geom
                            union all
                            select altlast_ili._geometry_line(
                                ST_InteriorRingN(p_geom, generate_series(1,st_NumInteriorRings(p_geom)))
                                )
                        ) foo2
                ) foo;
    elsif geom_type = 'ST_Polygon' and geom_srid = 2056 and geom_numintrings < 1 then
    select xmlagg(geoxmltext::xml) into result
                from (
                    select xmlelement(name "KbS_LV95_V1_4.Belastete_Standorte.PolygonStructure", 
                            xmlelement(name "Polygon",
                            xmlelement(name "SURFACE", 
                            xmlelement(name "BOUNDARY", geom))))::text as geoxmltext
                        from  (
                            select altlast_ili._geometry_line(
                                st_ExteriorRing(p_geom)
                                ) as geom
                            union all
                            select altlast_ili._geometry_line(
                                ST_InteriorRingN(p_geom, generate_series(1,st_NumInteriorRings(p_geom)))
                                )
                        ) foo2
                ) foo;

    elsif geom_type = 'ST_Polygon' and geom_srid = 21781 and geom_numintrings > 0 then
        select xmlagg(geoxmltext::xml) into result
                from (
                    select xmlelement(name "KbS_LV03_V1_4.Belastete_Standorte.PolygonStructure", 
                            xmlelement(name "Polygon",
                            xmlelement(name "SURFACE", geom)))::text as geoxmltext
                        from  (
                            select altlast_ili._geometry_polygon_boundaries_internal(p_geom) as geom
                        ) foo2
                ) foo;
    elsif geom_type = 'ST_Polygon' and geom_srid = 2056 and geom_numintrings > 0 then
    select xmlagg(geoxmltext::xml) into result
                from (
                    select xmlelement(name "KbS_LV95_V1_4.Belastete_Standorte.PolygonStructure", 
                            xmlelement(name "Polygon",
                            xmlelement(name "SURFACE", geom)))::text as geoxmltext
                        from  (
                            select altlast_ili._geometry_polygon_boundaries_internal(p_geom) as geom
                        ) foo2
                ) foo;

    elsif geom_type != 'ST_Polygon' then
        raise 'unsupported geometry type: %', geom_type;
    else 
        raise 'unsupported geometry srid: %', geom_srid;
    end if;
    return result;
end
$$;


