 begin                                                                                                   
     geom_type := st_geometrytype(p_geom);                                                               
     geom_srid := st_srid(p_geom);                                                                       
     geom_numintrings := st_numinteriorring(p_geom);


     if geom_type = 'ST_Polygon' and geom_srid = 2056 and geom_numintrings < 1 then                      
     select xmlagg(geoxmltext::xml) into result                                                          
                 from (                                                                                  
                     select  xmlelement(name "SURFACE",                                                  
                             xmlelement(name "BOUNDARY", geom))::text as geoxmltext                    
                         from  (                                                                         
                             select altlast_ili._geometry_line(                                          
                                 st_ExteriorRing(p_geom)                                                 
                                 ) as geom                                                               
                             union all                                                                   
                             select altlast_ili._geometry_line(                                          
                                 ST_InteriorRingN(p_geom, generate_series(1,st_NumInteriorRings(p_geom)))
                                 )                                                                       
                         ) foo2                                                                          
                 ) foo;                                                                                  
     elsif geom_type = 'ST_Polygon' and geom_srid = 2056 and geom_numintrings > 0 then                   
     select xmlagg(geoxmltext::xml) into result                                                          
                 from (                                                                                  
                     select xmlelement(name "SURFACE", geom)::text as geoxmltext                      
                         from  (                                                                         
                             select altlast_ili._geometry_polygon_boundaries_internal(p_geom) as geom    
                         ) foo2                                                                          
                 ) foo;                                                                                  
                                                                                                         
     elsif geom_type != 'ST_Polygon' then                                                                
         raise 'unsupported geometry type: %', geom_type;                                                
     else                                                                                                
         raise 'unsupported geometry srid: %', geom_srid;                                                
     end if;  




     return result;                                                                                      
 end
$$;


--
-- Name: _geometry_line(public.geometry); Type: FUNCTION; Schema: altlast_ili; Owner: -
--

CREATE FUNCTION altlast_ili._geometry_line(p_geom public.geometry) RETURNS xml
    LANGUAGE plpgsql STRICT
    AS $$
declare
    result xml;
    geom_type text;
begin
    geom_type := st_geometrytype(p_geom);
    if geom_type = 'ST_Line' or geom_type = 'ST_LineString' then
        -- TODO: check how internal rings are nested
        select xmlelement(name "POLYLINE", xmlagg(geomxml)) into result
            from (
                select altlast_ili._geometry_point(
                    altlast_ili._geometry_line_dumppoints(p_geom)
                ) as geomxml
            ) foo;
    else
        raise 'unsupported geometry type: %', geom_type;
    end if;
    return result;
end
$$;


--
-- Name: _geometry_line_dumppoints(public.geometry); Type: FUNCTION; Schema: altlast_ili; Owner: -
--

CREATE FUNCTION altlast_ili._geometry_line_dumppoints(p_geom public.geometry) RETURNS SETOF public.geometry
    LANGUAGE plpgsql STRICT
    AS $$
declare
    last_point geometry;
    this_point geometry;
    skip_point boolean;
begin
    /**
     dump all geoemtries from a line and skip duplicate points when they
     directly follow each other as this does not seem to be supported by the interlis
     format. At least the interlischecker complains about it.
    */
    last_point := Null;
for this_point in select st_snaptogrid(st_pointn(p_geom, generate_series(1,st_numpoints(p_geom))), 0.001) loop
        skip_point := true;
        if last_point is not null then
            skip_point := ST_Equals(last_point, this_point);
        else
            skip_point := false;
        end if;

        if not skip_point then
            return next this_point;
        end if;
        last_point := this_point;
    end loop;
    return;
end
 $$;


--
-- Name: _geometry_multipolygon(public.geometry); Type: FUNCTION; Schema: altlast_ili; Owner: -
--

CREATE FUNCTION altlast_ili._geometry_multipolygon(p_geom public.geometry) RETURNS xml
    LANGUAGE plpgsql STRICT
    AS $$
declare
    result xml;
    geom_type text;
begin
    geom_type := st_geometrytype(p_geom);
    if geom_type = 'ST_MultiPolygon' then
        select xmlelement(name "SURFACE", xmlagg(geomxml)) into result
            from (
                select altlast_ili._geometry_polygon_boundaries_internal(
                    st_geometryn(p_geom, generate_series(1,st_numgeometries(p_geom)))
                ) as geomxml
            ) foo;
    else
        raise 'unsupported geometry type: %', geom_type;
    end if;
    return result;
end
$$;


--
-- Name: _geometry_point(public.geometry); Type: FUNCTION; Schema: altlast_ili; Owner: -
--

CREATE FUNCTION altlast_ili._geometry_point(p_geom public.geometry) RETURNS xml
    LANGUAGE plpgsql STRICT
    AS $$
declare
    result xml;
    geom_type text;
begin
    geom_type := st_geometrytype(p_geom);
    if geom_type = 'ST_Point' then
        select xmlelement(name "COORD", xmlelement(name "C1", round(st_x(p_geom)::decimal,3)),
                xmlelement(name "C2", round(st_y(p_geom)::decimal, 3)),
                case when st_ndims(p_geom) > 2 then xmlelement(name "C3", st_z(p_geom)) else null end
                )
                into result;
    else
        raise 'unsupported geometry type: %', geom_type;
    end if;
    return result;
end
$$;


--
-- Name: _geometry_polygon(public.geometry); Type: FUNCTION; Schema: altlast_ili; Owner: -
--

CREATE FUNCTION altlast_ili._geometry_polygon(p_geom public.geometry) RETURNS xml
    LANGUAGE plpgsql STRICT
    AS $$
declare
    result xml;
    geom_type text;
begin
    geom_type := st_geometrytype(p_geom);
    if geom_type = 'ST_Polygon' then
        -- TODO: check how internal rings are nested
        select xmlelement(name "SURFACE", altlast_ili._geometry_polygon_boundaries_internal(p_geom) ) into result;
    else
        raise 'unsupported geometry type: %', geom_type;
    end if;
    return result;
end
$$;


