--
-- Name: export_geoig(integer[]); Type: FUNCTION; Schema: altlast_ili; Owner: -
--

CREATE FUNCTION altlast_ili.export_geoig(p_vflz_ids integer[]) RETURNS xml
    LANGUAGE sql
    AS $_$
/**

Development


part of this function got generated by cog: http://nedbatchelder.com/code/cog/
use that tool when modifying the autogenerated codeblocks

so do not delete the comment containing "cog" directives.



Regarding coordinate systems


Since Version 1.2 of the Geoig model the creators realized that there is more than one
coordinate system in existence. Since there seems no support for coordinate systems
in interlis itself, the coordinate systems name gets included in some of the tag names.

Example:
EPSG:21781  -> KbS_LV03_V1_2.Belastete_Standorte.Parzellenidentifikation
EPSG:2056   -> KbS_LV95_V1_2.Belastete_Standorte.Parzellenidentifikation

So, if the coordinate system used by altlast gets changed, this function also needs
a adaption.
*/

-- all sites of the list of vflz_ids
with wmsprops as (
    select
        wms_url as endpoint,
        wms_version,
        wms_layername as layername,
        geoportal_layername as layername_geoportal,
        geoportal_url as url_geoportal,
        geoportal_additional_layers as additional_layers_geoportal
     from altlast_ili.config_wms
     order by config_wms_id limit 1
),

-- wms requests
wmslayerrequest as (
    select
          geo.vflz_id,
          wmsprops.endpoint,
          wmsprops.wms_version,
          wmsprops.url_geoportal,
          wmsprops.additional_layers_geoportal,
          wmsprops.layername,
          -- calculate a boundinbox to fit the geometry in the given image dimensions
          st_xmin(geo.box)::text || ',' || st_ymin(geo.box)::text || ',' ||
                   st_xmax(geo.box)::text || ',' || st_ymax(geo.box)::text as bbox,
          geo.width as image_width,
          geo.height as image_height,
          geo.srid
    from  (
        select vflz_id,
            altlast.scaleextent(st_buffer(vflgeo.wkb_geometry, 10), imagesize.width::double precision/screen_dpi::double precision,
                    imagesize.height::double precision/screen_dpi::double precision)::box2d as box,
            st_srid(vflgeo.wkb_geometry) as srid,
            imagesize.width,
            imagesize.height
            from altlast.vflgeo, (
                -- dimensions of the wms image
                select 740 as width, 500 as height, 96 as screen_dpi
            ) as imagesize
     ) as geo, wmsprops
),

-- all sites of the list of vflz_ids
standorte as (
    select 'stao'||v.vflz_id::text as stao_tid,
        v.vflz_id,
        v.vfl_id,
        v.vflz_combined_id_kt,
        vflgeo.wkb_geometry,
        vflnr.org_id,
        'zb'||vflnr.org_id::text as zb_tid,
        bem_standort.bem as standort_bemerkungen,
        case when v.x_koordinate is not null and v.y_koordinate is not null then st_makepoint(v.x_koordinate, v.y_koordinate) else null end as wkb_point,
        staotyp_mapping.code_long as staotyp,
        null::text as deponietyp,
        false::text as nachsorge, -- bav wants this attribute to be missing, the spec wants it to be set -- so its always set to false now
        null::text as egrid,
        v.dat_rechtskraft::date as date_ersteintrag,
        (   -- legally binding date
            SELECT vflz_is_published_v.dat_latest_published::text AS dat_latest_published
               FROM altlast.vflz_is_published_v
               WHERE (vflz_is_published_v.vflz_id IN ( SELECT vflz_any_in_vfl.vflz_id
                                    FROM altlast.vflz vflz_any_in_vfl
                                    WHERE vflz_any_in_vfl.vfl_id = v.vfl_id)
                    ) AND vflz_is_published_v.is_latest_published
        )::date as date_letzteanpassung,
        statusaltlv_mapping.code_long as statusaltlv,
        /*v.zeitraum_bisheute*/ False as inbetrieb, /* Bei BAV keine Ablagerungen in Betrieb: Deshalb Wert standardmässig auf „NEIN“ */
        vfilename.baseurl || vfilename.filename as url_kbs_datasheet
    from altlast.vflz v
    join altlast.vflz_is_published_v vip on v.vflz_id = vip.vflz_id and vip.is_latest_published /* only published versions */
    join altlast_ili.cod_mapping_v staotyp_mapping on staotyp_mapping.c_cli_id = v.h_vflz_vftyp
                and staotyp_mapping.code = v.c_vflz_vftyp
    join altlast.bere_v on bere_v.vflz_id = v.vflz_id and bere_v.kbs
    join altlast_ili.cod_mapping_v statusaltlv_mapping on statusaltlv_mapping.c_cli_id = bere_v.h_bere_res_abwbewe
                and statusaltlv_mapping.code = bere_v.c_bere_res_abwbewe
    join altlast.vflnr on v.vflz_id = vflnr.vflz_id and vflnr.aktiv

    -- restrict using the ord configured in a4w
    join altlast_admin.setting stng on stng.value = vflnr.org_id::text
    join altlast_admin.setitem sit on sit.setitem_id = stng.setitem_id and sit.key = 'org'

    left  join altlast.vflgeo on vflgeo.vflz_id = v.vflz_id
    left join altlast.bemgrp bemg_standort on bemg_standort.public and bemg_standort.bemgrp='standort'
    left join altlast.bem bem_standort on bem_standort.bemgrp_id = bemg_standort.bemgrp_id and
                bem_standort.key_value = v.vflz_id and bem_standort.public

    left join altlast.vflz_filename_v vfilename on vfilename.vflz_id = v.vflz_id

    where v.vfl_id in (
        select vfl_id from altlast.vflz where vflz_id = any($1)
    )
),

geoportallinks as (
    select
        standorte.vflz_id,
        wmsprops.url_geoportal
                || '?Y=' || st_x(standorte.wkb_point)::text -- coordinates reversed -- not a typo
                || '&X=' || st_y(standorte.wkb_point)::text
                || '&zoom=12'
                || '&bgLayer=' || wmsprops.additional_layers_geoportal
                || '&layers=' || wmsprops.layername_geoportal
                || '&layers_opacity=1'
                || '&bgOpacity=0.8'
                || '&layers_visibility=true' as permalink_geoportal
    from standorte, wmsprops
),


-- parcels for all returned sites
parzellen as (
select
    null as nbident,  /* Der NBIdent  (Nummerierungsbereichidentifikator) setzt sich zusammen
                         aus dem Kt (Kantonskürzel) und der NBNummer  (Nummerierungsbereichnummer). */
    sv.vflz_id,
    g.gb_nummer

from altlast.subj_vflz sv
join altlast.subj_vflz_grun svg on sv.subj_vflz_id = svg.subj_vflz_id
join altlast.grun g on svg.grun_id = g.grun_id
where
    sv.vflz_id in (select vflz_id from standorte)
    and false /* never return any parcels as we can never returned the required nbident number */
),

-- parcels in xml form
parzellen_xml as (
select parzellen.vflz_id,
    xmlelement(name "KbS_LV03_V1_2.Belastete_Standorte.Parzellenidentifikation",
        xmlelement(name "NBIdent", parzellen.nbident),
        xmlelement(name "Parzellennummer", parzellen.gb_nummer)
    ) as x
from parzellen
),

untersuchungsmassnahmen_pre as (
select massn.*
from (
    select tm.code_long, tm.ili_code, tm.ili_c_cli_id, pv.vfl_id
    from altlast_ili.task_mapping_v tm
    join altlast.pm_cache_v pc on pc.pro_uid = tm.pro_uid
                and pc.status = 'CLOSED'
                and case when tm.tas_uid is null then true else tm.tas_uid = pc.tas_uid end
    join altlast.pm_vfl pv on pv.pm_vfl_id = pc.pm_vfl_id
) massn
join standorte s on massn.vfl_id = s.vfl_id
),

untersuchungsmassnahmen as (
select
    s.vfl_id, up.code_long, up.ili_code, up.ili_c_cli_id
from untersuchungsmassnahmen_pre up
join standorte s on up.vfl_id = s.vfl_id
union
-- provide UntMassn1 if no other untersuchungsmassnahme is available
select s.vfl_id, 'UntMassn1' as code_long, 'UM1' as ili_code, 20023 as ili_c_cli_id
from standorte s
    where s.vfl_id not in (select vfl_id from untersuchungsmassnahmen_pre)
    ),

untersuchungsmassnahmen_xml as (
select um.vfl_id,
    xmlelement(name "KbS_LV03_V1_2.Belastete_Standorte.UntersMassn_",
        xmlelement(name "value", um.code_long)
    ) as x
from untersuchungsmassnahmen um
),

-- sites in xml form
standorte_xml as (
    select xmlelement(name "KbS_LV03_V1_2.Belastete_Standorte.Belasteter_Standort",
          xmlattributes(standorte.stao_tid as "TID"),
          xmlelement(name "Katasternummer", standorte.vflz_combined_id_kt),
          xmlelement(name "URL_Standort", geoportallinks.permalink_geoportal),
          case when standorte.wkb_geometry is not null then
                case when st_geometrytype(standorte.wkb_geometry) = 'ST_Point' then
                    xmlelement(name "Geo_Lage_Punkt", altlast_ili.geometry(standorte.wkb_geometry))
                else
                    xmlelement(name "Geo_Lage_Polygon", altlast_ili.geometry(standorte.wkb_geometry))
                end
            else
                xmlelement(name "Geo_Lage_Punkt", altlast_ili.geometry(standorte.wkb_point))
          end,
          case
               when exists(select vflz_id from parzellen_xml where parzellen_xml.vflz_id = standorte.vflz_id) then
                  xmlelement(name "Parzellenverweis",
                        (select xmlagg(x) from parzellen_xml where parzellen_xml.vflz_id = standorte.vflz_id)
                  )
               else
                  xmlcomment('Parzellenverweis not available')
          end,
          case
               when standorte.egrid is not null then
                  xmlelement(name "EGRID", xmlelement(name "KbS_LV03_V1_2.Belastete_Standorte.EGRID_",
                        xmlelement(name "value", standorte.egrid)
                        )
                  )
                else
                    xmlcomment('EGRID not available')
          end, -- nicht bei BAV
          xmlelement(name "Standorttyp", standorte.staotyp),
          xmlelement(name "InBetrieb", standorte.inbetrieb),
          case
               when standorte.deponietyp is not null then
                  --  Nicht für BAV, da wir keine Ablagerungen „in Betrieb“ haben werden
                  xmlelement(name "Deponietyp", xmlelement(name "KbS_LV03_V1_2.Belastete_Standorte.Deponietyp_",
                        xmlelement(name "value", standorte.deponietyp)
                        )
                  )
                else
                    xmlcomment('Deponietyp not available')
          end,
          case
                when standorte.nachsorge is not null then
                    xmlelement(name "Nachsorge", standorte.nachsorge)
                else
                    xmlcomment('Nachsorge not available')
          end, -- Nicht bei BAV
          xmlelement(name "Untersuchungsmassnahmen",
                (select xmlagg(x) from untersuchungsmassnahmen_xml where untersuchungsmassnahmen_xml.vfl_id = standorte.vfl_id)
          ),
          xmlelement(name "StatusAltlV", standorte.statusaltlv),
          xmlelement(name "Ersteintrag", standorte.date_ersteintrag::date),
          xmlelement(name "LetzteAnpassung", standorte.date_letzteanpassung::date),
          xmlelement(name "URL_KbS_Auszug", standorte.url_kbs_datasheet),
          /*
          case
                when standorte.standort_bemerkungen != '' then
                    xmlelement(name "Bemerkung", altlast_ili.geoig_localisedmtext(coalesce(standorte.standort_bemerkungen,''), 'de'))
                else
                    */
                    xmlcomment('Bemerkung not available')
          /*end*/,
          xmlelement(name "ZustaendigkeitKataster",
            xmlattributes(
                standorte.zb_tid as "REF"
            )
          )
      ) as x
    from standorte
    join geoportallinks on geoportallinks.vflz_id = standorte.vflz_id
),

-- org
zustaendige_behoerde as (
   select distinct
         'zb'||org.org_id::text as zb_tid, /* this id also gets build in the standorte with-clause*/
         coalesce(org.bezeichnung_lang, org.bezeichnung) as behoerde,
         org.url_behoerde as url_behoerde,
         coalesce(org.katastername, org.bezeichnung)::text as katastername,
         org.url_webgis::text as url_webgis,
         org.org_id
     from altlast.org
       /* only load orgs which are referenced from sites*/
     where org.org_id in (select org_id from standorte)
),

-- org as xml
zustaendige_behoerde_xml as (
    select xmlelement(name "KbS_LV03_V1_2.Belastete_Standorte.ZustaendigkeitKataster",
      xmlattributes(zustaendige_behoerde.zb_tid as "TID"),
      xmlelement(name "Zustaendige_Behoerde", altlast_ili.geoig_localisedtext_t(zustaendige_behoerde.behoerde, array['de','fr','it'])),
      xmlelement(name "URL_Behoerde", zustaendige_behoerde.url_behoerde),
      xmlelement(name "Katastername",
           altlast_ili.geoig_localisedtext_t(zustaendige_behoerde.katastername, array['de','it','fr'])
      ),
      xmlelement(name "URL_Kataster", zustaendige_behoerde.url_webgis)
     ) as x from zustaendige_behoerde
)

-- assembling of the finished xml document according to the interlis schema
select xmlelement(name "TRANSFER",
   xmlattributes('http://www.interlis.ch/INTERLIS2.3' as xmlns),
   xmlelement(name "HEADERSECTION",
        xmlattributes('altlast4web' as "SENDER", '2.3' as "VERSION"),
        xmlelement(name "MODELS",
            -- need to add all used models by hand
            xmlelement(name "MODEL",
                xmlattributes(
                    'KbS_LV03_V1_2' as "NAME",
                    'http://models.geo.admin.ch/BAFU/KbS_V1_2.ili' as "URI",
                    '2014-05-20' as "VERSION"
                )
            ),
            xmlelement(name "MODEL",
                xmlattributes(
                    'GeometryCHLV03_V1' as "NAME",
                    'http://models.geo.admin.ch/CH/CHBase_Part1_GEOMETRY_20110830.ili' as "URI",
                    '2011-08-30' as "VERSION"
                )
            ),
            xmlelement(name "MODEL",
                xmlattributes(
                    'LocalisationCH_V1' as "NAME",
                    'http://models.geo.admin.ch/CH/CHBase_Part2_LOCALISATION_20110830.ili' as "URI",
                    '2011-08-30' as "VERSION"
                )
            )
        )
   ),
   xmlelement(name "DATASECTION",
        /* comment containing all affected vflz_ids. this has to be removed from the ouptut as it
           will caus ea buffer overflow in the intelischecker :)))
        xmlcomment('Generated when exporting the following vflz_ids: ' || $1::text),
        */
        xmlelement(name "KbS_LV03_V1_2.Belastete_Standorte",
            -- there is no attribute that could server as a bucket-identifier. so we generate an artiffical one.
            xmlattributes('bs'||extract(epoch from current_timestamp)::integer::text as "BID"),
            ( select xmlagg(x) from zustaendige_behoerde_xml),
            ( select xmlagg(x) from standorte_xml)),
        /*
        xmlelement(name "CoordSys.CoordsysTopic",
           xmlattributes('cs868' as "BID")
        ),
        */
        xmlelement(name "KbS_LV03_V1_2.Codelisten",
           xmlattributes('cl78868' as "BID")
/*[[[cog
# generate the queries for each of the codelists
import cog

# if you need to add new codelists just add them the the following python list
# and run this file through cog.py
codelists = (
    # c_cli_id, tagname, tidprefix
    (20333, 'KbS_LV03_V1_2.Codelisten.Deponietyp_Definition'),
    (20063, 'KbS_LV03_V1_2.Codelisten.Standorttyp_Definition'),
    (20103, 'KbS_LV03_V1_2.Codelisten.StatusAltlV_Definition'),
    (20023, 'KbS_LV03_V1_2.Codelisten.Untersuchungsmassnahmen_Definition')
    )
for cl in codelists:
    args = {
        'c_cli_id': int(cl[0]),
        'tid':      'cl' + str(cl[0]),
        'tag':      cl[1]
    }
    cog.outl(""", xmlcomment('Codes for codelist with c_cli_id = %(c_cli_id)s'),
            (select xmlagg(x) from (
               select xmlelement(name "%(tag)s",
                    xmlattributes( '%(tid)s'||lower(cod.code) as "TID"),
                    xmlelement(name "Code", cod_long.code_long),
                    xmlelement(name "Definition",
                        altlast_ili.geoig_localisedtext_code(cod.c_cli_id, cod.code::text)
                    )
                    ) as x
                from altlast.cod as cod
                join altlast_ili.cod_long on cod_long.code = cod.code and cod_long.c_cli_id = cod.c_cli_id
                where cod.c_cli_id = %(c_cli_id)d ) cle ) """ % args)
]]]*/
, xmlcomment('Codes for codelist with c_cli_id = 20333'),
            (select xmlagg(x) from (
               select xmlelement(name "KbS_LV03_V1_2.Codelisten.Deponietyp_Definition",
                    xmlattributes( 'cl20333'||lower(cod.code) as "TID"),
                    xmlelement(name "Code", cod_long.code_long),
                    xmlelement(name "Definition",
                        altlast_ili.geoig_localisedtext_code(cod.c_cli_id, cod.code::text)
                    )
                    ) as x
                from altlast.cod as cod
                join altlast_ili.cod_long on cod_long.code = cod.code and cod_long.c_cli_id = cod.c_cli_id
                where cod.c_cli_id = 20333 ) cle )
, xmlcomment('Codes for codelist with c_cli_id = 20063'),
            (select xmlagg(x) from (
               select xmlelement(name "KbS_LV03_V1_2.Codelisten.Standorttyp_Definition",
                    xmlattributes( 'cl20063'||lower(cod.code) as "TID"),
                    xmlelement(name "Code", cod_long.code_long),
                    xmlelement(name "Definition",
                        altlast_ili.geoig_localisedtext_code(cod.c_cli_id, cod.code::text)
                    )
                    ) as x
                from altlast.cod as cod
                join altlast_ili.cod_long on cod_long.code = cod.code and cod_long.c_cli_id = cod.c_cli_id
                where cod.c_cli_id = 20063 ) cle )
, xmlcomment('Codes for codelist with c_cli_id = 20103'),
            (select xmlagg(x) from (
               select xmlelement(name "KbS_LV03_V1_2.Codelisten.StatusAltlV_Definition",
                    xmlattributes( 'cl20103'||lower(cod.code) as "TID"),
                    xmlelement(name "Code", cod_long.code_long),
                    xmlelement(name "Definition",
                        altlast_ili.geoig_localisedtext_code(cod.c_cli_id, cod.code::text)
                    )
                    ) as x
                from altlast.cod as cod
                join altlast_ili.cod_long on cod_long.code = cod.code and cod_long.c_cli_id = cod.c_cli_id
                where cod.c_cli_id = 20103 ) cle )
, xmlcomment('Codes for codelist with c_cli_id = 20023'),
            (select xmlagg(x) from (
               select xmlelement(name "KbS_LV03_V1_2.Codelisten.Untersuchungsmassnahmen_Definition",
                    xmlattributes( 'cl20023'||lower(cod.code) as "TID"),
                    xmlelement(name "Code", cod_long.code_long),
                    xmlelement(name "Definition",
                        altlast_ili.geoig_localisedtext_code(cod.c_cli_id, cod.code::text)
                    )
                    ) as x
                from altlast.cod as cod
                join altlast_ili.cod_long on cod_long.code = cod.code and cod_long.c_cli_id = cod.c_cli_id
                where cod.c_cli_id = 20023 ) cle )
--[[[end]]]
        )
        )
   );
$_$;


--
-- Name: export_geoig_bl(integer[]); Type: FUNCTION; Schema: altlast_ili; Owner: -
--

CREATE FUNCTION altlast_ili.export_geoig_bl(p_vflz_ids integer[]) RETURNS xml
    LANGUAGE sql
    AS $_$
/**

Development


part of this function got generated by cog: http://nedbatchelder.com/code/cog/
use that tool when modifying the autogenerated codeblocks

so do not delete the comment containing "cog" directives.



Regarding coordinate systems


Since Version 1.2 of the Geoig model the creators realized that there is more than one
coordinate system in existence. Since there seems no support for coordinate systems
in interlis itself, the coordinate systems name gets included in some of the tag names.

Example:
EPSG:21781  -> KbS_LV95_V1_2.Belastete_Standorte.Parzellenidentifikation
EPSG:2056   -> KbS_LV95_V1_2.Belastete_Standorte.Parzellenidentifikation

So, if the coordinate system used by altlast gets changed, this function also needs
a adaption.
*/

-- all sites of the list of vflz_ids
with bidprops as (
    select 
        'kbs' || org.kuerzel as bid
    from altlast_admin.setitem
    join altlast_admin.setting using (setitem_id)
    join altlast.org on org.org_id=setting.value::int
    where key= 'org'
),

wmsprops as (
    select 
      case when (select value as url_geoportal from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_Standort') is not null then 
        (select value as url_geoportal from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_Standort')
      else null end as url_geoportal
),


-- all sites of the list of vflz_ids
standorte as (
    select 'stao'||v.vflz_id::text as stao_tid,
        v.vflz_id,
        v.vfl_id,
        v.vflz_combined_id_kt,
        vflgeo.wkb_geometry,
        vflnr.org_id,
        'zb'||vflnr.org_id::text as zb_tid,
        bem_standort.bem as standort_bemerkungen,
        case when v.x_koordinate is not null and v.y_koordinate is not null then st_makepoint(v.x_koordinate, v.y_koordinate) else null end as wkb_point,
        staotyp_mapping.code_long as staotyp,
        case when v.c_vflz_inbetrieb = '01' then v.c_vflz_deponietyp::text end as deponietyp,
        case when v.c_vflz_nachsorge = '01' then true::text else false::text end as nachsorge, -- bav wants this attribute to be missing, the spec wants it to be set -- so its always set to false now
        null::text as egrid,
        v.dat_rechtskraft::date as date_ersteintrag,
        (SELECT vflz_is_published_v.dat_latest_published::text AS dat_latest_published
               FROM altlast.vflz_is_published_v
               WHERE (vflz_is_published_v.vflz_id IN ( SELECT vflz_any_in_vfl.vflz_id
                                    FROM altlast.vflz vflz_any_in_vfl
                                    WHERE vflz_any_in_vfl.vfl_id = v.vfl_id)
                    ) AND vflz_is_published_v.is_latest_published
        )::date as date_letzteanpassung,
        statusaltlv_mapping.code_long as statusaltlv,
        case when v.c_vflz_inbetrieb = '01' then true::text else false::text end as inbetrieb, 
        case when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_KbS_Auszug') is null then null
          else (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_KbS_Auszug') || vfilename.filename end as url_kbs_datasheet,
        altlast.t(altlast.msgid_code(v.h_vflz_unterstand, v.c_vflz_unterstand), 'de') as untersuchungsstand,
        case 
          when v.zeitraum_von is null and v.zeitraum_bis is not null
            then 'unbekannt bis ' ||extract(year from v.zeitraum_bis)::text
          when v.zeitraum_von is not null and v.zeitraum_bis is null 
            then extract(year from v.zeitraum_von)::text || ' bis unbekannt'
          when v.zeitraum_von is not null and v.zeitraum_bis is not null and extract(year from v.zeitraum_von) = extract(year from v.zeitraum_bis)
            then extract(year from v.zeitraum_von)::text
          when v.zeitraum_von is not null and v.zeitraum_bis is not null
            then extract(year from v.zeitraum_von)::text || ' bis ' ||extract(year from v.zeitraum_bis)::text 
          else 'unbekannt'
        end as zeitraum
    from altlast.vflz v
    join altlast.vflz_is_published_v vip on v.vflz_id = vip.vflz_id and vip.is_latest_published /* only published versions */
    join altlast_ili.cod_mapping_v staotyp_mapping on staotyp_mapping.c_cli_id = v.h_vflz_vftyp
                and staotyp_mapping.code = v.c_vflz_vftyp
    join altlast.bere_v on bere_v.vflz_id = v.vflz_id and bere_v.kbs
    join altlast_ili.cod_mapping_v statusaltlv_mapping on statusaltlv_mapping.c_cli_id = bere_v.h_bere_res_abwbewe
                and statusaltlv_mapping.code = bere_v.c_bere_res_abwbewe
    join altlast.vflnr on v.vflz_id = vflnr.vflz_id and vflnr.aktiv

    -- restrict using the ord configured in a4w
    join altlast_admin.setting stng on stng.value = vflnr.org_id::text
    join altlast_admin.setitem sit on sit.setitem_id = stng.setitem_id and sit.key in ('org', 'astra')

    left  join altlast.vflgeo on vflgeo.vflz_id = v.vflz_id
    left join altlast.bemgrp bemg_standort on bemg_standort.public and bemg_standort.bemgrp='standort'
    left join altlast.bem bem_standort on bem_standort.bemgrp_id = bemg_standort.bemgrp_id and
                bem_standort.key_value = v.vflz_id and bem_standort.public

    left join altlast.vflz_filename_v vfilename on vfilename.vflz_id = v.vflz_id

    where v.vfl_id in (
        select vfl_id from altlast.vflz where vflz_id = any($1)
    )
),

geoportallinks as (
    select
        standorte.vflz_id,
        case when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_Standort_Indikator') = 'standortnummer' then
          wmsprops.url_geoportal || (regexp_replace(standorte.vflz_combined_id_kt::text, ' '::text, '%20'::text, 'g'::text))
        when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_Standort_Indikator') = 'xy_koordinates' then
           wmsprops.url_geoportal || 'Y=' || st_x(standorte.wkb_point)::text || '&X=' || st_y(standorte.wkb_point)::text
        when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_Standort_Indikator') = 'map_x_map_y_koordinates' then
           wmsprops.url_geoportal || 'map_x=' || st_x(standorte.wkb_point)::text || '&map_y=' || st_y(standorte.wkb_point)::text
        else wmsprops.url_geoportal 
        end as permalink_geoportal
    from standorte, wmsprops
),


-- parcels for all returned sites
parzellen as (
  select 
    org || bfsnr as nbident, vflz_id, parzelle 
  from (select 
      vpmv.h_gem_id as bfsnr,  /* Der NBIdent  (Nummerierungsbereichidentifikator) setzt sich zusammen
               aus dem Kt (Kantonskürzel) und der NBNummer  (Nummerierungsbereichnummer). */
      (select org.kuerzel from altlast_admin.setitem join altlast_admin.setting using (setitem_id) join altlast.org on org.org_id=setting.value::int where key= 'org') as org,
      vpmv.vflz_id as vflz_id,
      vpmv.gb_nummer as parzelle,
      case when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'Parzellenverweiss') = 'Ja' then true
      else false /* never return any parcels as we can never returned the required nbident number */
      end as parzellenverweiss
        from altlast.vflz_parzellen_materialization_v vpmv
        group by vpmv.h_gem_id, vpmv.vflz_id, vpmv.gb_nummer)foo
  where foo.vflz_id in (select vflz_id from standorte) and foo.parzellenverweiss
  order by bfsnr, parzelle
),

-- parcels in xml form
parzellen_xml as (
select parzellen.vflz_id,
        xmlelement(name "KbS_Basis_V1_4.Parzellenidentifikation",
        xmlelement(name "NBIdent", parzellen.nbident),
        xmlelement(name "Parzellennummer", parzellen.parzelle)
    ) as x_v14
from parzellen
),

untersuchungsmassnahmen_pre_pm as (
select massn.*
from (
      select tm.code_long, tm.ili_code, tm.ili_c_cli_id, pv.vfl_id from altlast_ili.task_mapping_v tm 
        join altlast.pm_cache_v pc on pc.pro_uid = tm.pro_uid and pc.status = 'CLOSED' and case when tm.tas_uid is null then true else tm.tas_uid = pc.tas_uid end
        join altlast.pm_vfl pv on pv.pm_vfl_id = pc.pm_vfl_id
) massn
join standorte s on massn.vfl_id = s.vfl_id
),

untersuchungsmassnahmen_pm as (
select
    s.vfl_id, up.code_long, up.ili_code, up.ili_c_cli_id
from untersuchungsmassnahmen_pre_pm up
join standorte s on up.vfl_id = s.vfl_id
union
-- provide UntMassn1 if no other untersuchungsmassnahme is available
select s.vfl_id, 'UntMassn1' as code_long, 'UM1' as ili_code, 20023 as ili_c_cli_id
from standorte s
    where s.vfl_id not in (select vfl_id from untersuchungsmassnahmen_pre_pm)
    ),

untersuchungsmassnahmen_xml_pm as (
select um.vfl_id,
        xmlelement(name "KbS_Basis_V1_4.UntersMassn_",
        xmlelement(name "value", um.code_long)
    ) as x_v14
from untersuchungsmassnahmen_pm um
),


untersuchungsmassnahmen_pre_vfl as (
select massn.*
from (
      select tm.code_long, tm.ili_code, tm.ili_c_cli_id, v.vfl_id from altlast_ili.task_mapping_v tm join altlast.vflz v on v.c_vflz_unterstand = tm.a4w_code
) massn
join standorte s on massn.vfl_id = s.vfl_id
),

untersuchungsmassnahmen_vfl as (
select
    s.vfl_id, up.code_long, up.ili_code, up.ili_c_cli_id
from untersuchungsmassnahmen_pre_vfl up
join standorte s on up.vfl_id = s.vfl_id
union
-- provide UntMassn1 if no other untersuchungsmassnahme is available
select s.vfl_id, 'UntMassn1' as code_long, 'UM1' as ili_code, 20023 as ili_c_cli_id
from standorte s
    where s.vfl_id not in (select vfl_id from untersuchungsmassnahmen_pre_vfl)
    ),

untersuchungsmassnahmen_xml_vfl as (
select um.vfl_id,
        xmlelement(name "KbS_Basis_V1_4.UntersMassn_",
        xmlelement(name "value", um.code_long)
    ) as x_v14
from untersuchungsmassnahmen_vfl um
),


untersuchungsmassnahmen_pre_vflz as (
select massn.*
from (
      select tm.code_long, tm.ili_code, tm.ili_c_cli_id, v.vfl_id, v.vflz_id from altlast_ili.task_mapping_v tm join altlast.vflz v on v.c_vflz_unterstand = tm.a4w_code
) massn
join standorte s on massn.vflz_id = s.vflz_id
),

untersuchungsmassnahmen_vflz as (
select
    s.vflz_id, s.vfl_id, up.code_long, up.ili_code, up.ili_c_cli_id
from untersuchungsmassnahmen_pre_vflz up
join standorte s on up.vflz_id = s.vflz_id
union
-- provide UntMassn1 if no other untersuchungsmassnahme is available
select s.vflz_id, s.vfl_id, 'UntMassn1' as code_long, 'UM1' as ili_code, 20023 as ili_c_cli_id
from standorte s
    where s.vflz_id not in (select vflz_id from untersuchungsmassnahmen_pre_vflz)
    ),



untersuchungsmassnahmen_xml_vflz as (
select um.vflz_id,
        xmlelement(name "KbS_Basis_V1_4.UntersMassn_",
        xmlelement(name "value", um.code_long)
    ) as x_v14
from untersuchungsmassnahmen_vflz um
),



-- sites in xml form
standorte_xml_v14_lv95 as (
    select xmlelement(name "KbS_LV95_V1_4_BL_V1.Belastete_Standorte.Belasteter_Standort",
          xmlattributes(standorte.stao_tid as "TID"),
          xmlelement(name "Katasternummer", standorte.vflz_combined_id_kt),
          xmlelement(name "URL_Standort", geoportallinks.permalink_geoportal),
          case when standorte.wkb_geometry is not null then
              case when st_geometrytype(standorte.wkb_geometry) = 'ST_Point' then
                  xmlelement(name "Geo_Lage_Punkt", altlast_ili.geoig_geometry(ST_Transform((standorte.wkb_geometry), 2056)))
              else
                  xmlelement(name "Geo_Lage_Polygon", altlast_ili.geoig_geometry(ST_Transform((standorte.wkb_geometry), 2056)))
              end
          else
              xmlelement(name "Geo_Lage_Punkt", altlast_ili.geoig_geometry(ST_Transform((standorte.wkb_geometry), 2056)))
          end,
         case
               when exists(select vflz_id from parzellen_xml where parzellen_xml.vflz_id = standorte.vflz_id) then
                  xmlelement(name "Parzellenverweis",
                        (select xmlagg(x_v14) from parzellen_xml where parzellen_xml.vflz_id = standorte.vflz_id)
                  )
               else
                  xmlcomment('Parzellenverweis not available')
          end,
          case
               when standorte.egrid is not null then
                  xmlelement(name "EGRID", xmlelement(name "KbS_Basis_V1_4.EGRID_",
                        xmlelement(name "value", standorte.egrid)
                        )
                  )
                else
                    xmlcomment('EGRID not available')
          end, -- nicht bei BAV
          xmlelement(name "Standorttyp", standorte.staotyp),
          xmlelement(name "InBetrieb", standorte.inbetrieb),
          case
               when standorte.deponietyp is not null then
                  --  Nicht für BAV, da wir keine Ablagerungen „in Betrieb“ haben werden
                  xmlelement(name "Deponietyp", xmlelement(name "KbS_Basis_V1_4.Deponietyp_",
                        xmlelement(name "value", standorte.deponietyp)
                        )
                  )
                else
                    xmlcomment('Deponietyp not available')
          end,
          case
                when standorte.nachsorge is not null then
                    xmlelement(name "Nachsorge", standorte.nachsorge)
                else
                    xmlcomment('Nachsorge not available')
          end, -- Nicht bei BAV
          case 
                when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'Mapping_Untersuchungsmassnahmen') = 'alle nach Geschäften' then
                  xmlelement(name "Untersuchungsmassnahmen", (select xmlagg(x_v14) from untersuchungsmassnahmen_xml_pm where untersuchungsmassnahmen_xml_pm.vfl_id = standorte.vfl_id))
                when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'Mapping_Untersuchungsmassnahmen') = 'alle nach Standortversionen' then
                  xmlelement(name "Untersuchungsmassnahmen", (select xmlagg(x_v14) from untersuchungsmassnahmen_xml_vfl where untersuchungsmassnahmen_xml_vfl.vfl_id = standorte.vfl_id))
                when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'Mapping_Untersuchungsmassnahmen') = 'aktuellste' then
                  xmlelement(name "Untersuchungsmassnahmen", (select xmlagg(x_v14) from untersuchungsmassnahmen_xml_vflz where untersuchungsmassnahmen_xml_vflz.vflz_id = standorte.vflz_id))
                else 
                  xmlelement(name "Untersuchungsmassnahmen", (select xmlagg(x_v14) from untersuchungsmassnahmen_xml_vflz where untersuchungsmassnahmen_xml_vflz.vflz_id = standorte.vflz_id))
          end,
          xmlelement(name "StatusAltlV", standorte.statusaltlv),
          xmlelement(name "Ersteintrag", standorte.date_ersteintrag::text),
          xmlelement(name "LetzteAnpassung", standorte.date_letzteanpassung::text),
          xmlelement(name "URL_KbS_Auszug", standorte.url_kbs_datasheet),
          /*
          case
                when standorte.standort_bemerkungen != '' then
                    xmlelement(name "Bemerkung", altlast_ili.geoig_localisedmtext(coalesce(standorte.standort_bemerkungen,''), 'de'))
                else
                    */
                    xmlcomment('Bemerkung not available')
          /*end*/,
          xmlelement(name "ZustaendigkeitKataster",
            xmlattributes(
                standorte.zb_tid as "REF"
            )
          ),
          xmlelement(name "Untersuchungsstand", standorte.untersuchungsstand),
          xmlelement(name "Zeitraum", standorte.zeitraum)
      ) as x
    from standorte
    join geoportallinks on geoportallinks.vflz_id = standorte.vflz_id
),


-- org
zustaendige_behoerde as (
select distinct
        'zb'||org.org_id::text as zb_tid, /* this id also gets build in the standorte with-clause*/
        case when org.org_id = 310 then org.bezeichnung_lang 
            else (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'Behoerde_Amt') 
            end as behoerde,
        case when org.org_id = 310 then org.url_behoerde 
            else (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_Behoerde_Amt') 
            end as url_behoerde,
        case when org.org_id = 310 then null
            else (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'UID_Behoerde_Amt') 
            end as uid,
        coalesce(org.katastername, org.bezeichnung)::text as katastername,
        (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_Standort_Kataster')::text as url_webgis,
        org.org_id
     from altlast.org
       /* only load orgs which are referenced from sites*/
     where org.org_id in (select org_id from standorte)
),

-- org as xml
zustaendige_behoerde_xml as (
    select 
    xmlelement(name "KbS_LV03_V1_4.Belastete_Standorte.ZustaendigkeitKataster",
      xmlattributes(zustaendige_behoerde.zb_tid as "TID"),
      xmlelement(name "Zustaendige_Behoerde", altlast_ili.geoig_localisedtext_t(zustaendige_behoerde.behoerde, 
        array['de',
            case when (select org.kuerzel from altlast_admin.setitem join altlast_admin.setting using (setitem_id) join altlast.org on org.org_id=setting.value::int where key= 'org') = 'GR' 
                then 'rm' 
            else 'fr' end,
            'it'
        ])),
      xmlelement(name "URL_Behoerde", zustaendige_behoerde.url_behoerde),
      xmlelement(name "UID", zustaendige_behoerde.uid),
      xmlelement(name "Katastername",
           altlast_ili.geoig_localisedtext_t(zustaendige_behoerde.katastername, 
                array['de',
                    case when (select org.kuerzel from altlast_admin.setitem join altlast_admin.setting using (setitem_id) join altlast.org on org.org_id=setting.value::int where key= 'org') = 'GR' 
                        then 'rm' 
                    else 'fr' end,
                    'it'
                ])
      ),
      xmlelement(name "URL_Kataster", zustaendige_behoerde.url_webgis)
    ) as x_v14_lv03,
    xmlelement(name "KbS_LV95_V1_4.Belastete_Standorte.ZustaendigkeitKataster",
      xmlattributes(zustaendige_behoerde.zb_tid as "TID"),
      xmlelement(name "Zustaendige_Behoerde", altlast_ili.geoig_localisedtext_t(zustaendige_behoerde.behoerde, 
        array['de',
            case when (select org.kuerzel from altlast_admin.setitem join altlast_admin.setting using (setitem_id) join altlast.org on org.org_id=setting.value::int where key= 'org') = 'GR' 
                then 'rm' 
            else 'fr' end,
            'it'
        ])),
      xmlelement(name "URL_Behoerde", zustaendige_behoerde.url_behoerde),
      xmlelement(name "UID", zustaendige_behoerde.uid),
      xmlelement(name "Katastername",
            altlast_ili.geoig_localisedtext_t(zustaendige_behoerde.katastername, 
            array['de',
                    case when (select org.kuerzel from altlast_admin.setitem join altlast_admin.setting using (setitem_id) join altlast.org on org.org_id=setting.value::int where key= 'org') = 'GR' 
                        then 'rm' 
                    else 'fr' end,
                    'it'
                ])
      ),
      xmlelement(name "URL_Kataster", zustaendige_behoerde.url_webgis)
    ) as x_v14_lv95
    from zustaendige_behoerde
)

-- assembling of the finished xml document according to the interlis schema
select xmlelement(name "TRANSFER", xmlattributes('http://www.interlis.ch/INTERLIS2.3' as xmlns),
    xmlelement(name "HEADERSECTION",
        xmlattributes('altlast4web' as "SENDER", '2.3' as "VERSION"),
          xmlelement(name "MODELS", -- need to add all used models by hand
              xmlelement(name "MODEL",xmlattributes('CoordSys' as "NAME",'2015-11-24' as "VERSION",'https://www.interlis.ch/models' as "URI")),
              xmlelement(name "MODEL",xmlattributes('InternationalCodes_V1' as "NAME",'2011-08-30' as "VERSION",'https://www.geo.admin.ch' as "URI")),
        xmlelement(name "MODEL",xmlattributes('Localisation_V1' as "NAME",'2011-08-30' as "VERSION",'https://www.geo.admin.ch' as "URI")),
              xmlelement(name "MODEL",xmlattributes('LocalisationCH_V1' as "NAME",'2011-08-30' as "VERSION",'https://www.geo.admin.ch' as "URI")),
              xmlelement(name "MODEL", xmlattributes('Dictionaries_V1' as "NAME",'2011-08-30' as "VERSION",'https://www.geo.admin.ch' as "URI")),
              xmlelement(name "MODEL",xmlattributes('DictionariesCH_V1' as "NAME",'2011-08-30' as "VERSION",'https://www.geo.admin.ch' as "URI")),
              xmlelement(name "MODEL",xmlattributes('Units' as "NAME",'2012-02-20' as "VERSION",'https://www.interlis.ch/models' as "URI")),
              xmlelement(name "MODEL",xmlattributes('GeometryCHLV03_V1' as "NAME",'2015-11-12' as "VERSION",'https://www.geo.admin.ch' as "URI")),
              xmlelement(name "MODEL",xmlattributes('GeometryCHLV95_V1' as "NAME",'2015-11-12' as "VERSION",'https://www.geo.admin.ch' as "URI")),
              xmlelement(name "MODEL",xmlattributes('KbS_Basis_V1_4' as "NAME",'2018-06-13' as "VERSION",'https://models.geo.admin.ch/BAFU' as "URI")),
              xmlelement(name "MODEL",xmlattributes('KbS_LV03_V1_4' as "NAME",'2018-06-13' as "VERSION",'https://models.geo.admin.ch/BAFU' as "URI")),
              xmlelement(name "MODEL",xmlattributes('KbS_LV95_V1_4' as "NAME",'2018-06-13' as "VERSION",'https://models.geo.admin.ch/BAFU' as "URI")),
              xmlelement(name "MODEL",xmlattributes('KbS_LV95_V1_4_BL_V1' as "NAME",'2018-11-08' as "VERSION",'http://models.geo.bl.ch/AUE' as "URI"))
          )
    ),

    xmlelement(name "DATASECTION",
        xmlelement(name "KbS_LV95_V1_4_BL_V1.Belastete_Standorte",-- there is no attribute that could server as a bucket-identifier. so we generate an artiffical one.
    xmlattributes((select bid from bidprops) as "BID"),
        ( select xmlagg(x_v14_lv95) from zustaendige_behoerde_xml),
        ( select xmlagg(x) from standorte_xml_v14_lv95)
        )
      )
);
          

$_$;


--
-- Name: export_geoig_gr(integer[], text); Type: FUNCTION; Schema: altlast_ili; Owner: -
--

CREATE FUNCTION altlast_ili.export_geoig_gr(p_vflz_ids integer[], ili_version text) RETURNS xml
    LANGUAGE sql
    AS $_$

/**
Development
part of this function got generated by cog: https://nedbatchelder.com/code/cog/
use that tool when modifying the autogenerated codeblocks
so do not delete the comment containing "cog" directives.
Regarding coordinate systems
*/

-- all sites of the list of vflz_ids
with bidprops as (
    select 
        'kbs' || org.kuerzel as bid
    from altlast_admin.setitem
    join altlast_admin.setting using (setitem_id)
    join altlast.org on org.org_id::text=setting.value
    where key = 'org'
),

wmsprops as (
    select 
      case when (select value as url_geoportal from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_Standort') is not null then 
        (select value as url_geoportal from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_Standort')
      else null end as url_geoportal
),


-- all sites of the list of vflz_ids
standorte as (
    select 'stao'||v.vflz_id::text as stao_tid,
        v.vflz_id,
        v.vfl_id,
        v.vflz_combined_id_kt,
        vflgeo.wkb_geometry,
        vflnr.org_id,
        'zb'||vflnr.org_id::text as zb_tid,
        bem_standort.bem as standort_bemerkungen,
        case when v.x_koordinate is not null and v.y_koordinate is not null then st_makepoint(v.x_koordinate, v.y_koordinate) else null end as wkb_point,
        staotyp_mapping.code_long as staotyp,
        v.c_vflz_deponietyp::text as deponietyp,
        case when v.c_vflz_nachsorge = '01' then true::text else false::text end as nachsorge, 
        null::text as egrid,
        v.dat_rechtskraft::date as date_ersteintrag,
        (   -- legally binding date
            SELECT vflz_is_published_v.dat_latest_published::text AS dat_latest_published
               FROM altlast.vflz_is_published_v
               WHERE (vflz_is_published_v.vflz_id IN ( SELECT vflz_any_in_vfl.vflz_id
                                    FROM altlast.vflz vflz_any_in_vfl
                                    WHERE vflz_any_in_vfl.vfl_id = v.vfl_id)
                    ) AND vflz_is_published_v.is_latest_published
        )::date as date_letzteanpassung,
        statusaltlv_mapping.code_long as statusaltlv,
        case when v.c_vflz_inbetrieb = '01' then true::text else false::text end as inbetrieb, 
        case when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_KbS_Auszug') is not null then
          (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_KbS_Auszug') 
          || vfilename.filename 
          else null end as url_kbs_datasheet,
          regexp_replace(v.bezeichnung, '[^a-zA-Z]', ' ', 'g') as bezeichnung
    from altlast.vflz v
    join altlast.vflz_is_published_v vip on v.vflz_id = vip.vflz_id and vip.is_latest_published /* only published versions */
    join altlast_ili.cod_mapping_v staotyp_mapping on staotyp_mapping.c_cli_id = v.h_vflz_vftyp
                and staotyp_mapping.code = v.c_vflz_vftyp
    join altlast.bere_v on bere_v.vflz_id = v.vflz_id and bere_v.kbs
    join altlast_ili.cod_mapping_v statusaltlv_mapping on statusaltlv_mapping.c_cli_id = bere_v.h_bere_res_abwbewe
                and statusaltlv_mapping.code = bere_v.c_bere_res_abwbewe
    join altlast.vflnr on v.vflz_id = vflnr.vflz_id and vflnr.aktiv

    -- restrict using the ord configured in a4w
    join altlast_admin.setting stng on stng.value = vflnr.org_id::text
    join altlast_admin.setitem sit on sit.setitem_id = stng.setitem_id and sit.key in ('org', 'astra')

    left  join altlast.vflgeo on vflgeo.vflz_id = v.vflz_id
    left join altlast.bemgrp bemg_standort on bemg_standort.public and bemg_standort.bemgrp='standort'
    left join altlast.bem bem_standort on bem_standort.bemgrp_id = bemg_standort.bemgrp_id and
                bem_standort.key_value = v.vflz_id and bem_standort.public

    left join altlast.vflz_filename_v vfilename on vfilename.vflz_id = v.vflz_id

    where v.vfl_id in (
        select vfl_id from altlast.vflz where vflz_id = any($1)
    )
    order by v.vflz_id
),

geoportallinks as (
    select
        standorte.vflz_id,
        case when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_Standort_Indikator') = 'standortnummer' then
          wmsprops.url_geoportal || (regexp_replace(standorte.vflz_combined_id_kt::text, ' '::text, '%20'::text, 'g'::text))
        when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_Standort_Indikator') = 'xy_koordinates' then
           wmsprops.url_geoportal || '&Y=' || st_x(standorte.wkb_point)::text || '&X=' || st_y(standorte.wkb_point)::text
        when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_Standort_Indikator') = 'map_x_map_y_koordinates' then
           wmsprops.url_geoportal || '&map_x=' || st_x(standorte.wkb_point)::text || '&map_y=' || st_y(standorte.wkb_point)::text
        else wmsprops.url_geoportal 
        end as permalink_geoportal
    from standorte, wmsprops
),


-- parcels for all returned sites
parzellen as (
  select 
    org || bfsnr as nbident, vflz_id, parzelle 
  from (select 
      vpmv.h_gem_id as bfsnr,  /* Der NBIdent  (Nummerierungsbereichidentifikator) setzt sich zusammen
               aus dem Kt (Kantonskürzel) und der NBNummer  (Nummerierungsbereichnummer). */
      (select org.kuerzel from altlast_admin.setitem join altlast_admin.setting using (setitem_id) join altlast.org on org.org_id=setting.value::int where key= 'org') as org,
      vpmv.vflz_id as vflz_id,
      vpmv.gb_nummer as parzelle,
      case when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'Parzellenverweiss') = 'Ja' then true
      else false /* never return any parcels as we can never returned the required nbident number */
      end as parzellenverweiss
        from altlast.vflz_parzellen_materialization_v vpmv
        group by vpmv.h_gem_id, vpmv.vflz_id, vpmv.gb_nummer)foo
  where foo.vflz_id in (select vflz_id from standorte) and foo.parzellenverweiss
  order by bfsnr, parzelle
),

-- parcels in xml form
parzellen_xml as (
select parzellen.vflz_id,
        xmlelement(name "KbS_Basis_V1_4.Parzellenidentifikation",
        xmlelement(name "NBIdent", parzellen.nbident),
        xmlelement(name "Parzellennummer", parzellen.parzelle)
    ) as x_v14
from parzellen
order by parzellen.parzelle
),

untersuchungsmassnahmen_pre_pm as (
select massn.*
from (
      select tm.code_long, tm.ili_code, tm.ili_c_cli_id, pv.vfl_id from altlast_ili.task_mapping_v tm 
        join altlast.pm_cache_v pc on pc.pro_uid = tm.pro_uid and pc.status = 'CLOSED' and case when tm.tas_uid is null then true else tm.tas_uid = pc.tas_uid end
        join altlast.pm_vfl pv on pv.pm_vfl_id = pc.pm_vfl_id
) massn
join standorte s on massn.vfl_id = s.vfl_id
),

untersuchungsmassnahmen_pm as (
select
    s.vfl_id, up.code_long, up.ili_code, up.ili_c_cli_id
from untersuchungsmassnahmen_pre_pm up
join standorte s on up.vfl_id = s.vfl_id
union
-- provide UntMassn1 if no other untersuchungsmassnahme is available
select s.vfl_id, 'UntMassn1' as code_long, 'UM1' as ili_code, 20023 as ili_c_cli_id
from standorte s
    where s.vfl_id not in (select vfl_id from untersuchungsmassnahmen_pre_pm)
    ),

untersuchungsmassnahmen_xml_pm as (
select um.vfl_id,
        xmlelement(name "KbS_Basis_V1_4.UntersMassn_",
        xmlelement(name "value", um.code_long)
    ) as x_v14
from untersuchungsmassnahmen_pm um
),


untersuchungsmassnahmen_pre_vfl as (
select massn.*
from (
      select tm.code_long, tm.ili_code, tm.ili_c_cli_id, v.vfl_id from altlast_ili.task_mapping_v tm join altlast.vflz v on v.c_vflz_unterstand = tm.a4w_code
) massn
join standorte s on massn.vfl_id = s.vfl_id
),

untersuchungsmassnahmen_vfl as (
select
    s.vfl_id, up.code_long, up.ili_code, up.ili_c_cli_id
from untersuchungsmassnahmen_pre_vfl up
join standorte s on up.vfl_id = s.vfl_id
union
-- provide UntMassn1 if no other untersuchungsmassnahme is available
select s.vfl_id, 'UntMassn1' as code_long, 'UM1' as ili_code, 20023 as ili_c_cli_id
from standorte s
    where s.vfl_id not in (select vfl_id from untersuchungsmassnahmen_pre_vfl)
    ),

untersuchungsmassnahmen_xml_vfl as (
select um.vfl_id,
        xmlelement(name "KbS_Basis_V1_4.UntersMassn_",
        xmlelement(name "value", um.code_long)
    ) as x_v14
from untersuchungsmassnahmen_vfl um
),


untersuchungsmassnahmen_pre_vflz as (
select massn.*
from (
      select tm.code_long, tm.ili_code, tm.ili_c_cli_id, v.vfl_id, v.vflz_id from altlast_ili.task_mapping_v tm join altlast.vflz v on v.c_vflz_unterstand = tm.a4w_code
) massn
join standorte s on massn.vflz_id = s.vflz_id
),

untersuchungsmassnahmen_vflz as (
select
    s.vflz_id, s.vfl_id, up.code_long, up.ili_code, up.ili_c_cli_id
from untersuchungsmassnahmen_pre_vflz up
join standorte s on up.vflz_id = s.vflz_id
union
-- provide UntMassn1 if no other untersuchungsmassnahme is available
select s.vflz_id, s.vfl_id, 'UntMassn1' as code_long, 'UM1' as ili_code, 20023 as ili_c_cli_id
from standorte s
    where s.vflz_id not in (select vflz_id from untersuchungsmassnahmen_pre_vflz)
    ),



untersuchungsmassnahmen_xml_vflz as (
select um.vflz_id,
        xmlelement(name "KbS_Basis_V1_4.UntersMassn_",
        xmlelement(name "value", um.code_long)
    ) as x_v14
from untersuchungsmassnahmen_vflz um
),


-- sites in xml form

standorte_xml_v14_lv03 as (
    select xmlelement(name "KbS_LV03_V1_4.Belastete_Standorte.Belasteter_Standort",
          xmlattributes(standorte.stao_tid as "TID"),
          xmlelement(name "Katasternummer", standorte.vflz_combined_id_kt),
          xmlelement(name "Bezeichnung", standorte.bezeichnung),
          xmlelement(name "URL_Standort", geoportallinks.permalink_geoportal),
          case when standorte.wkb_geometry is not null then
              case when st_geometrytype(standorte.wkb_geometry) = 'ST_Point' then
                  xmlelement(name "Geo_Lage_Punkt", altlast_ili.geoig_geometry(ST_Transform((standorte.wkb_geometry), 21781)))
              else
                  xmlelement(name "Geo_Lage_Polygon", altlast_ili.geoig_geometry(ST_Transform((standorte.wkb_geometry), 21781)))
              end
          else
              xmlelement(name "Geo_Lage_Punkt", altlast_ili.geoig_geometry(ST_Transform((standorte.wkb_geometry), 21781)))
          end,
          case
               when exists(select vflz_id from parzellen_xml where parzellen_xml.vflz_id = standorte.vflz_id) then
                  xmlelement(name "Parzellenverweis",
                        (select xmlagg(x_v14) from parzellen_xml where parzellen_xml.vflz_id = standorte.vflz_id)
                  )
               else
                  xmlcomment('Parzellenverweis not available')
          end,
          case
               when standorte.egrid is not null then
                  xmlelement(name "EGRID", xmlelement(name "KbS_Basis_V1_4.EGRID_",
                        xmlelement(name "value", standorte.egrid)
                        )
                  )
                else
                    xmlcomment('EGRID not available')
          end, -- nicht bei BAV
          xmlelement(name "Standorttyp", standorte.staotyp),
          xmlelement(name "InBetrieb", standorte.inbetrieb),
          case
               when standorte.deponietyp is not null then
                  --  Nicht für BAV, da wir keine Ablagerungen „in Betrieb“ haben werden
                  xmlelement(name "Deponietyp", xmlelement(name "KbS_Basis_V1_4.Deponietyp_",
                        xmlelement(name "value", standorte.deponietyp)
                        )
                  )
                else
                    xmlcomment('Deponietyp not available')
          end,
          case
                when standorte.nachsorge is not null then
                    xmlelement(name "Nachsorge", standorte.nachsorge)
                else
                    xmlcomment('Nachsorge not available')
          end, -- Nicht bei BAV
          case 
                when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'Mapping_Untersuchungsmassnahmen') = 'alle nach Geschäften' then
                  xmlelement(name "Untersuchungsmassnahmen", (select xmlagg(x_v14) from untersuchungsmassnahmen_xml_pm where untersuchungsmassnahmen_xml_pm.vfl_id = standorte.vfl_id))
                when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'Mapping_Untersuchungsmassnahmen') = 'alle nach Standortversionen' then
                  xmlelement(name "Untersuchungsmassnahmen", (select xmlagg(x_v14) from untersuchungsmassnahmen_xml_vfl where untersuchungsmassnahmen_xml_vfl.vfl_id = standorte.vfl_id))
                when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'Mapping_Untersuchungsmassnahmen') = 'aktuellste' then
                  xmlelement(name "Untersuchungsmassnahmen", (select xmlagg(x_v14) from untersuchungsmassnahmen_xml_vflz where untersuchungsmassnahmen_xml_vflz.vflz_id = standorte.vflz_id))
                else 
                  xmlelement(name "Untersuchungsmassnahmen", (select xmlagg(x_v14) from untersuchungsmassnahmen_xml_vflz where untersuchungsmassnahmen_xml_vflz.vflz_id = standorte.vflz_id))
          end,
          xmlelement(name "StatusAltlV", standorte.statusaltlv),
          xmlelement(name "Ersteintrag", standorte.date_ersteintrag::date),
          xmlelement(name "LetzteAnpassung", standorte.date_letzteanpassung::date),
          xmlelement(name "URL_KbS_Auszug", standorte.url_kbs_datasheet),
          /*
          case
                when standorte.standort_bemerkungen != '' then
                    xmlelement(name "Bemerkung", altlast_ili.geoig_localisedmtext(coalesce(standorte.standort_bemerkungen,''), 'de'))
                else
                    */
                    xmlcomment('Bemerkung not available')
          /*end*/,
          xmlelement(name "ZustaendigkeitKataster",
            xmlattributes(
                standorte.zb_tid as "REF"
            )
          )
      ) as x
    from standorte
    join geoportallinks on geoportallinks.vflz_id = standorte.vflz_id
    order by standorte.stao_tid
),


standorte_xml_v14_lv95 as (
    select xmlelement(name "KbS_LV95_V1_4_GR_V1.Belastete_Standorte.Belasteter_Standort",
          xmlattributes(standorte.stao_tid as "TID"),
          xmlelement(name "Katasternummer", standorte.vflz_combined_id_kt),
          xmlelement(name "Bezeichnung", standorte.bezeichnung),
          xmlelement(name "URL_Standort", geoportallinks.permalink_geoportal),
          case when standorte.wkb_geometry is not null then
              case when st_geometrytype(standorte.wkb_geometry) = 'ST_Point' then
                  xmlelement(name "Geo_Lage_Punkt", altlast_ili.geoig_geometry(ST_Transform((standorte.wkb_geometry), 2056)))
              else
                  xmlelement(name "Geo_Lage_Polygon", altlast_ili.geoig_geometry(ST_Transform((standorte.wkb_geometry), 2056)))
              end
          else
              xmlelement(name "Geo_Lage_Punkt", altlast_ili.geoig_geometry(ST_Transform((standorte.wkb_geometry), 2056)))
          end,
         case
               when exists(select vflz_id from parzellen_xml where parzellen_xml.vflz_id = standorte.vflz_id) then
                  xmlelement(name "Parzellenverweis",
                        (select xmlagg(x_v14) from parzellen_xml where parzellen_xml.vflz_id = standorte.vflz_id)
                  )
               else
                  xmlcomment('Parzellenverweis not available')
          end,
          case
               when standorte.egrid is not null then
                  xmlelement(name "EGRID", xmlelement(name "KbS_Basis_V1_4.EGRID_",
                        xmlelement(name "value", standorte.egrid)
                        )
                  )
                else
                    xmlcomment('EGRID not available')
          end, -- nicht bei BAV
          xmlelement(name "Standorttyp", standorte.staotyp),
          xmlelement(name "InBetrieb", standorte.inbetrieb),
          case
               when standorte.deponietyp is not null then
                  --  Nicht für BAV, da wir keine Ablagerungen „in Betrieb“ haben werden
                  xmlelement(name "Deponietyp", xmlelement(name "KbS_Basis_V1_4.Deponietyp_",
                        xmlelement(name "value", standorte.deponietyp)
                        )
                  )
                else
                    xmlcomment('Deponietyp not available')
          end,
          case
                when standorte.nachsorge is not null then
                    xmlelement(name "Nachsorge", standorte.nachsorge)
                else
                    xmlcomment('Nachsorge not available')
          end, -- Nicht bei BAV
          case 
                when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'Mapping_Untersuchungsmassnahmen') = 'alle nach Geschäften' then
                  xmlelement(name "Untersuchungsmassnahmen", (select xmlagg(x_v14) from untersuchungsmassnahmen_xml_pm where untersuchungsmassnahmen_xml_pm.vfl_id = standorte.vfl_id))
                when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'Mapping_Untersuchungsmassnahmen') = 'alle nach Standortversionen' then
                  xmlelement(name "Untersuchungsmassnahmen", (select xmlagg(x_v14) from untersuchungsmassnahmen_xml_vfl where untersuchungsmassnahmen_xml_vfl.vfl_id = standorte.vfl_id))
                when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'Mapping_Untersuchungsmassnahmen') = 'aktuellste' then
                  xmlelement(name "Untersuchungsmassnahmen", (select xmlagg(x_v14) from untersuchungsmassnahmen_xml_vflz where untersuchungsmassnahmen_xml_vflz.vflz_id = standorte.vflz_id))
                else 
                  xmlelement(name "Untersuchungsmassnahmen", (select xmlagg(x_v14) from untersuchungsmassnahmen_xml_vflz where untersuchungsmassnahmen_xml_vflz.vflz_id = standorte.vflz_id))
          end,
          xmlelement(name "StatusAltlV", standorte.statusaltlv),
          xmlelement(name "Ersteintrag", standorte.date_ersteintrag::date),
          xmlelement(name "LetzteAnpassung", standorte.date_letzteanpassung::date),
          xmlelement(name "URL_KbS_Auszug", standorte.url_kbs_datasheet),
          /*
          case
                when standorte.standort_bemerkungen != '' then
                    xmlelement(name "Bemerkung", altlast_ili.geoig_localisedmtext(coalesce(standorte.standort_bemerkungen,''), 'de'))
                else
                    */
                    xmlcomment('Bemerkung not available')
          /*end*/,
          xmlelement(name "ZustaendigkeitKataster",
            xmlattributes(
                standorte.zb_tid as "REF"
            )
          )
      ) as x
    from standorte
    join geoportallinks on geoportallinks.vflz_id = standorte.vflz_id
    order by standorte.stao_tid
),


-- org
zustaendige_behoerde as (
select distinct
        'zb'||org.org_id::text as zb_tid, /* this id also gets build in the standorte with-clause*/
        case when org.org_id = 310 then org.bezeichnung_lang 
            else (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'Behoerde_Amt') 
            end as behoerde,
        case when org.org_id = 310 then org.url_behoerde 
            else (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_Behoerde_Amt') 
            end as url_behoerde,
        case when org.org_id = 310 then null
            else (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'UID_Behoerde_Amt') 
            end as uid,
        coalesce(org.katastername, org.bezeichnung)::text as katastername,
        (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_Standort_Kataster')::text as url_webgis,
        org.org_id
     from altlast.org
       /* only load orgs which are referenced from sites*/
     where org.org_id in (select org_id from standorte)
),

-- org as xml
zustaendige_behoerde_xml as (
    select 
    xmlelement(name "KbS_LV03_V1_4.Belastete_Standorte.ZustaendigkeitKataster",
      xmlattributes(zustaendige_behoerde.zb_tid as "TID"),
      xmlelement(name "Zustaendige_Behoerde", altlast_ili.geoig_localisedtext_t(zustaendige_behoerde.behoerde, 
        array['de',
            case when (select org.kuerzel from altlast_admin.setitem join altlast_admin.setting using (setitem_id) join altlast.org on org.org_id=setting.value::int where key= 'org') = 'GR' 
                then 'rm' 
            else 'fr' end,
            'it'
        ])),
      xmlelement(name "URL_Behoerde", zustaendige_behoerde.url_behoerde),
      xmlelement(name "UID", zustaendige_behoerde.uid),
      xmlelement(name "Katastername",
           altlast_ili.geoig_localisedtext_t(zustaendige_behoerde.katastername, 
                array['de',
                    case when (select org.kuerzel from altlast_admin.setitem join altlast_admin.setting using (setitem_id) join altlast.org on org.org_id=setting.value::int where key= 'org') = 'GR' 
                        then 'rm' 
                    else 'fr' end,
                    'it'
                ])
      ),
      xmlelement(name "URL_Kataster", zustaendige_behoerde.url_webgis)
    ) as x_v14_lv03,
    xmlelement(name "KbS_LV95_V1_4.Belastete_Standorte.ZustaendigkeitKataster",
      xmlattributes(zustaendige_behoerde.zb_tid as "TID"),
      xmlelement(name "Zustaendige_Behoerde", altlast_ili.geoig_localisedtext_t(zustaendige_behoerde.behoerde, 
        array['de',
            case when (select org.kuerzel from altlast_admin.setitem join altlast_admin.setting using (setitem_id) join altlast.org on org.org_id=setting.value::int where key= 'org') = 'GR' 
                then 'rm' 
            else 'fr' end,
            'it'
        ])),
      xmlelement(name "URL_Behoerde", zustaendige_behoerde.url_behoerde),
      xmlelement(name "UID", zustaendige_behoerde.uid),
      xmlelement(name "Katastername",
            altlast_ili.geoig_localisedtext_t(zustaendige_behoerde.katastername, 
            array['de',
                    case when (select org.kuerzel from altlast_admin.setitem join altlast_admin.setting using (setitem_id) join altlast.org on org.org_id=setting.value::int where key= 'org') = 'GR' 
                        then 'rm' 
                    else 'fr' end,
                    'it'
                ])
      ),
      xmlelement(name "URL_Kataster", zustaendige_behoerde.url_webgis)
    ) as x_v14_lv95
    from zustaendige_behoerde
)

-- assembling of the finished xml document according to the interlis schema
select xmlelement(name "TRANSFER", xmlattributes('http://www.interlis.ch/INTERLIS2.3' as xmlns),
    xmlelement(name "HEADERSECTION",
        xmlattributes('altlast4web' as "SENDER", '2.3' as "VERSION"),
          xmlelement(name "MODELS", -- need to add all used models by hand
              xmlelement(name "MODEL",xmlattributes('CoordSys' as "NAME",'2015-11-24' as "VERSION",'https://www.interlis.ch/models' as "URI")),
              xmlelement(name "MODEL",xmlattributes('InternationalCodes_V1' as "NAME",'2011-08-30' as "VERSION",'https://www.geo.admin.ch' as "URI")),
        xmlelement(name "MODEL",xmlattributes('Localisation_V1' as "NAME",'2011-08-30' as "VERSION",'https://www.geo.admin.ch' as "URI")),
              xmlelement(name "MODEL",xmlattributes('LocalisationCH_V1' as "NAME",'2011-08-30' as "VERSION",'https://www.geo.admin.ch' as "URI")),
              xmlelement(name "MODEL", xmlattributes('Dictionaries_V1' as "NAME",'2011-08-30' as "VERSION",'https://www.geo.admin.ch' as "URI")),
              xmlelement(name "MODEL",xmlattributes('DictionariesCH_V1' as "NAME",'2011-08-30' as "VERSION",'https://www.geo.admin.ch' as "URI")),
              xmlelement(name "MODEL",xmlattributes('Units' as "NAME",'2012-02-20' as "VERSION",'https://www.interlis.ch/models' as "URI")),
              xmlelement(name "MODEL",xmlattributes('GeometryCHLV03_V1' as "NAME",'2015-11-12' as "VERSION",'https://www.geo.admin.ch' as "URI")),
              xmlelement(name "MODEL",xmlattributes('GeometryCHLV95_V1' as "NAME",'2015-11-12' as "VERSION",'https://www.geo.admin.ch' as "URI")),
              xmlelement(name "MODEL",xmlattributes('KbS_Basis_V1_4' as "NAME",'2018-06-13' as "VERSION",'https://models.geo.admin.ch/BAFU' as "URI")),
              xmlelement(name "MODEL",xmlattributes('KbS_LV03_V1_4' as "NAME",'2018-06-13' as "VERSION",'https://models.geo.admin.ch/BAFU' as "URI")),
              xmlelement(name "MODEL",xmlattributes('KbS_LV95_V1_4' as "NAME",'2018-06-13' as "VERSION",'https://models.geo.admin.ch/BAFU' as "URI")),
              xmlelement(name "MODEL",xmlattributes('KbS_LV95_V1_4_GR_V1' as "NAME",'2019-12-05' as "VERSION",'' as "URI"))
          )
    ),
         
   case when $2 = 'v14_lv03' then
       xmlelement(name "DATASECTION",
      xmlelement(name "KbS_LV03_V1_4.Belastete_Standorte", -- there is no attribute that could server as a bucket-identifier. so we generate an artiffical one.
    xmlattributes((select bid from bidprops) as "BID"),
        ( select xmlagg(x_v14_lv03) from zustaendige_behoerde_xml),
        ( select xmlagg(x) from standorte_xml_v14_lv03)
      )
        )
   end,
   
   case when $2 = 'v14_lv95' then
       xmlelement(name "DATASECTION",
           xmlelement(name "KbS_LV95_V1_4.Belastete_Standorte",-- there is no attribute that could server as a bucket-identifier. so we generate an artiffical one.
    xmlattributes((select bid from bidprops) as "BID"),
        ( select xmlagg(x_v14_lv95) from zustaendige_behoerde_xml),
        ( select xmlagg(x) from standorte_xml_v14_lv95)
           )
        )
   end
);

$_$;


--
-- Name: export_geoig_lu_v15(integer[]); Type: FUNCTION; Schema: altlast_ili; Owner: -
--

CREATE FUNCTION altlast_ili.export_geoig_lu_v15(p_vflz_ids integer[]) RETURNS xml
    LANGUAGE sql
    AS $_$


-- all sites of the list of vflz_ids
with bidprops as (
    select 
        'kbs' || org.kuerzel as bid
    from altlast_admin.setitem
    join altlast_admin.setting using (setitem_id)
    join altlast.org on org.org_id::text=setting.value
    where key = 'org'
),

wmsprops as (
    select 
      case when (select value as url_geoportal from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_Standort') is not null then 
        (select value as url_geoportal from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_Standort')
      else null end as url_geoportal
),


-- all sites of the list of vflz_ids
standorte as (
    select 'stao'||v.vflz_id::text as stao_tid,
        v.vflz_id,
        v.vfl_id,
        v.vflz_combined_id_kt,
        vflgeo.wkb_geometry,
        vflnr.org_id,
        'zb'||vflnr.org_id::text as zb_tid,
        bem_standort.bem as standort_bemerkungen,
        case when v.x_koordinate is not null and v.y_koordinate is not null then st_makepoint(v.x_koordinate, v.y_koordinate) else null end as wkb_point,
        staotyp_mapping.code_long as staotyp,
        v.c_vflz_deponietyp::text as deponietyp,
        case when v.c_vflz_nachsorge = '01' then true::text else false::text end as nachsorge, 
        null::text as egrid,
        v.dat_rechtskraft::date as date_ersteintrag,
        (   -- legally binding date
            SELECT vflz_is_published_v.dat_latest_published::text AS dat_latest_published
               FROM altlast.vflz_is_published_v
               WHERE (vflz_is_published_v.vflz_id IN ( SELECT vflz_any_in_vfl.vflz_id
                                    FROM altlast.vflz vflz_any_in_vfl
                                    WHERE vflz_any_in_vfl.vfl_id = v.vfl_id)
                    ) AND vflz_is_published_v.is_latest_published
        )::date as date_letzteanpassung,
        statusaltlv_mapping.code_long as statusaltlv,
        case when v.c_vflz_inbetrieb = '01' then true::text else false::text end as inbetrieb, 
        case when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_KbS_Auszug') is not null then
          (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_KbS_Auszug') 
          || (regexp_replace(vfilename.filename::text, ' '::text, '%20'::text, 'g'::text))
          else null end as url_kbs_datasheet,
          v.bezeichnung as bezeichnung,
          cod_bearb.bezeichnung as bearbeitungsstand
    from altlast.vflz v
    join altlast.vflz_is_current_v vic on v.vflz_id = vic.vflz_id and vic.is_current /* only published versions */
    left join altlast_ili.cod_mapping_v staotyp_mapping on staotyp_mapping.c_cli_id = v.h_vflz_vftyp
                and staotyp_mapping.code = v.c_vflz_vftyp
    left join altlast.bere_v on bere_v.vflz_id = v.vflz_id and bere_v.kbs
    left join altlast_ili.cod_mapping_v statusaltlv_mapping on statusaltlv_mapping.c_cli_id = bere_v.h_bere_res_abwbewe
                and statusaltlv_mapping.code = bere_v.c_bere_res_abwbewe
    left join altlast.vflnr on v.vflz_id = vflnr.vflz_id and vflnr.aktiv

    -- restrict using the ord configured in a4w
    left join altlast_admin.setting stng on stng.value = vflnr.org_id::text
    join altlast_admin.setitem sit on sit.setitem_id = stng.setitem_id and sit.key in ('org', 'astra')

    left  join altlast.vflgeo on vflgeo.vflz_id = v.vflz_id
    left join altlast.bemgrp bemg_standort on bemg_standort.public and bemg_standort.bemgrp='standort'
    left join altlast.bem bem_standort on bem_standort.bemgrp_id = bemg_standort.bemgrp_id and
                bem_standort.key_value = v.vflz_id and bem_standort.public

    left join altlast.vflz_filename_v vfilename on vfilename.vflz_id = v.vflz_id
    left join altlast.cod cod_bearb on cod_bearb.c_cli_id = v.h_vflz_bearbstand and cod_bearb.code = v.c_vflz_bearbstand

    where v.vfl_id in (
        select vfl_id from altlast.vflz where vflz_id = any($1)
    )
    order by v.vflz_id
),

branche as (
select bran.*
from (
      select vflz_id, cod_bran.bezeichnung as branchenbezeichnung from altlast.intb  
        left join altlast.cod cod_bran on cod_bran.c_cli_id = intb.h_intb_bran and cod_bran.code = intb.c_intb_bran
) bran
join standorte s on bran.vflz_id = s.vflz_id
),


branche_xml as (
select bran.vflz_id,
        xmlelement(name "KbS_V1_5_LU_V1.Branche",
        xmlelement(name "value", bran.branchenbezeichnung)
    )as x_v14
from branche bran
),

geoportallinks as (
    select
        standorte.vflz_id,
        case when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_Standort_Indikator') = 'standortnummer' then
          wmsprops.url_geoportal || (regexp_replace(standorte.vflz_combined_id_kt::text, ' '::text, '%20'::text, 'g'::text))
        when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_Standort_Indikator') = 'xy_koordinates' then
           wmsprops.url_geoportal || '&Y=' || st_x(standorte.wkb_point)::text || '&X=' || st_y(standorte.wkb_point)::text
        when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_Standort_Indikator') = 'map_x_map_y_koordinates' then
           wmsprops.url_geoportal || '&map_x=' || st_x(standorte.wkb_point)::text || '&map_y=' || st_y(standorte.wkb_point)::text
        when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_Standort_Indikator') = 'c_koordinates' then
           wmsprops.url_geoportal || '&c=' || st_y(standorte.wkb_point)::text || ',' || st_x(standorte.wkb_point)::text 
        else wmsprops.url_geoportal 
        end as permalink_geoportal
    from standorte, wmsprops
),


-- parcels for all returned sites
parzellen as (
  select 
    org || bfsnr as nbident, vflz_id, parzelle 
  from (select 
      vpmv.h_gem_id as bfsnr,  /* Der NBIdent  (Nummerierungsbereichidentifikator) setzt sich zusammen
               aus dem Kt (Kantonskürzel) und der NBNummer  (Nummerierungsbereichnummer). */
      (select org.kuerzel from altlast_admin.setitem join altlast_admin.setting using (setitem_id) join altlast.org on org.org_id=setting.value::int where key= 'org') as org,
      vpmv.vflz_id as vflz_id,
      vpmv.gb_nummer as parzelle,
      case when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'Parzellenverweiss') = 'Ja' then true
      else false /* never return any parcels as we can never returned the required nbident number */
      end as parzellenverweiss
        from altlast.vflz_parzellen_materialization_v vpmv
        group by vpmv.h_gem_id, vpmv.vflz_id, vpmv.gb_nummer)foo
  where foo.vflz_id in (select vflz_id from standorte) and foo.parzellenverweiss
  order by bfsnr, parzelle
),

-- parcels in xml form
parzellen_xml as (
select parzellen.vflz_id,
        xmlelement(name "KbS_V1_5.Parzellenidentifikation",
        xmlelement(name "NBIdent", parzellen.nbident),
        xmlelement(name "Parzellennummer", parzellen.parzelle)
    ) as x_v15
from parzellen
order by parzellen.parzelle
),

untersuchungsmassnahmen_pre_pm as (
select massn.*
from (
      select tm.code_long, tm.ili_code, tm.ili_c_cli_id, pv.vfl_id from altlast_ili.task_mapping_v tm 
        join altlast.pm_cache_v pc on pc.pro_uid = tm.pro_uid and pc.status = 'CLOSED' and case when tm.tas_uid is null then true else tm.tas_uid = pc.tas_uid end
        join altlast.pm_vfl pv on pv.pm_vfl_id = pc.pm_vfl_id
) massn
join standorte s on massn.vfl_id = s.vfl_id
),

untersuchungsmassnahmen_pm as (
select
    s.vfl_id, up.code_long, up.ili_code, up.ili_c_cli_id
from untersuchungsmassnahmen_pre_pm up
join standorte s on up.vfl_id = s.vfl_id
union
-- provide UntMassn1 if no other untersuchungsmassnahme is available
select s.vfl_id, 'UntMassn1' as code_long, 'UM1' as ili_code, 20023 as ili_c_cli_id
from standorte s
    where s.vfl_id not in (select vfl_id from untersuchungsmassnahmen_pre_pm)
    ),

untersuchungsmassnahmen_xml_pm as (
select um.vfl_id,
        xmlelement(name "KbS_V1_5.UntersMassn_",
        xmlelement(name "value", um.code_long)
    ) as x_v15
from untersuchungsmassnahmen_pm um
),


untersuchungsmassnahmen_pre_vfl as (
select massn.*
from (
      select tm.code_long, tm.ili_code, tm.ili_c_cli_id, v.vfl_id from altlast_ili.task_mapping_v tm join altlast.vflz v on v.c_vflz_unterstand = tm.a4w_code
) massn
join standorte s on massn.vfl_id = s.vfl_id
),

untersuchungsmassnahmen_vfl as (
select
    s.vfl_id, up.code_long, up.ili_code, up.ili_c_cli_id
from untersuchungsmassnahmen_pre_vfl up
join standorte s on up.vfl_id = s.vfl_id
union
-- provide UntMassn1 if no other untersuchungsmassnahme is available
select s.vfl_id, 'UntMassn1' as code_long, 'UM1' as ili_code, 20023 as ili_c_cli_id
from standorte s
    where s.vfl_id not in (select vfl_id from untersuchungsmassnahmen_pre_vfl)
    ),

untersuchungsmassnahmen_xml_vfl as (
select um.vfl_id,
        xmlelement(name "KbS_V1_5.UntersMassn_",
        xmlelement(name "value", um.code_long)
    ) as x_v15
from untersuchungsmassnahmen_vfl um
),


untersuchungsmassnahmen_pre_vflz as (
select massn.*
from (
      select tm.code_long, tm.ili_code, tm.ili_c_cli_id, v.vfl_id, v.vflz_id from altlast_ili.task_mapping_v tm join altlast.vflz v on v.c_vflz_unterstand = tm.a4w_code
) massn
join standorte s on massn.vflz_id = s.vflz_id
),

untersuchungsmassnahmen_vflz as (
select
    s.vflz_id, s.vfl_id, up.code_long, up.ili_code, up.ili_c_cli_id
from untersuchungsmassnahmen_pre_vflz up
join standorte s on up.vflz_id = s.vflz_id
union
-- provide UntMassn1 if no other untersuchungsmassnahme is available
select s.vflz_id, s.vfl_id, 'UntMassn1' as code_long, 'UM1' as ili_code, 20023 as ili_c_cli_id
from standorte s
    where s.vflz_id not in (select vflz_id from untersuchungsmassnahmen_pre_vflz)
    ),



untersuchungsmassnahmen_xml_vflz as (
select um.vflz_id,
        xmlelement(name "KbS_V1_5.UntersMassn_",
        xmlelement(name "value", um.code_long)
    ) as x_v15
from untersuchungsmassnahmen_vflz um
),


-- sites in xml form

standorte_xml_v15 as (
    select xmlelement(name "KbS_V1_5_LU_V1.Belastete_Standorte.Belasteter_Standort",
          xmlattributes(standorte.stao_tid as "TID"),
          xmlelement(name "Katasternummer", standorte.vflz_combined_id_kt),
          xmlelement(name "Bezeichnung", standorte.bezeichnung),
          xmlelement(name "Bearbeitungsstand", standorte.bearbeitungsstand),
          case
               when exists(select vflz_id from branche_xml where branche_xml.vflz_id = standorte.vflz_id) then
                  xmlelement(name "Branchenbezeichnung",
                        (select xmlagg(x_v14) from branche_xml where branche_xml.vflz_id = standorte.vflz_id)
                  )
               else
                  xmlcomment('Branchenbezeichnung not available')
          end,
          case when geoportallinks.permalink_geoportal is not null then
            xmlelement(name "URL_Standort", 
                xmlelement(name "KbS_V1_5.Belastete_Standorte.MultilingualUri",
                    xmlelement(name "LocalisedText",
                        xmlelement(name "KbS_V1_5.Belastete_Standorte.LocalisedUri",
                            xmlelement(name "Language", 'de'),
                            xmlelement(name "Text", concat(geoportallinks.permalink_geoportal, '&lang=de'))
                        ), 
                        xmlelement(name "KbS_V1_5.Belastete_Standorte.LocalisedUri",   
                            case when (select org.kuerzel from altlast_admin.setitem join altlast_admin.setting using (setitem_id) join altlast.org on org.org_id=setting.value::int where key= 'org') = 'GR' 
                                then xmlelement(name "Language", 'rm')
                                else xmlelement(name "Language", 'fr') end,
                            case when (select org.kuerzel from altlast_admin.setitem join altlast_admin.setting using (setitem_id) join altlast.org on org.org_id=setting.value::int where key= 'org') = 'GR' 
                                     then xmlelement(name "Text", concat(geoportallinks.permalink_geoportal, '&lang=rm'))
                                    else xmlelement(name "Text", concat(geoportallinks.permalink_geoportal, '&lang=fr')) end
                        ),
                        xmlelement(name "KbS_V1_5.Belastete_Standorte.LocalisedUri",
                            xmlelement(name "Language", 'it'),
                            xmlelement(name "Text", concat(geoportallinks.permalink_geoportal, '&lang=it'))
                        )
                    )
                )
            )
          else 
            xmlelement(name "URL_Standort", geoportallinks.permalink_geoportal)
          end,
          case when standorte.wkb_geometry is not null then
              case when st_geometrytype(standorte.wkb_geometry) = 'ST_Point' then
                  xmlelement(name "Geo_Lage_Punkt", altlast_ili.geoig_v1_5_geometry(ST_Transform((standorte.wkb_geometry), 2056)))
              else
                  xmlelement(name "Geo_Lage_Polygon", altlast_ili.geoig_v1_5_geometry(ST_Transform((standorte.wkb_geometry), 2056)))
              end
          else
              xmlelement(name "Geo_Lage_Punkt", altlast_ili.geoig_v1_5_geometry(ST_Transform((standorte.wkb_geometry), 2056)))
          end,
         case
               when exists(select vflz_id from parzellen_xml where parzellen_xml.vflz_id = standorte.vflz_id) then
                  xmlelement(name "Parzellenverweis",
                        (select xmlagg(x_v15) from parzellen_xml where parzellen_xml.vflz_id = standorte.vflz_id)
                  )
               else
                  xmlcomment('Parzellenverweis not available')
          end,
          case
               when standorte.egrid is not null then
                  xmlelement(name "EGRID", xmlelement(name "KbS_V1_5.EGRID_",
                        xmlelement(name "value", standorte.egrid)
                        )
                  )
                else
                    xmlcomment('EGRID not available')
          end, -- nicht bei BAV
          xmlelement(name "Standorttyp", standorte.staotyp),
          xmlelement(name "InBetrieb", standorte.inbetrieb),
          case
               when standorte.deponietyp is not null then
                  --  Nicht für BAV, da wir keine Ablagerungen „in Betrieb“ haben werden
                  xmlelement(name "Deponietyp", xmlelement(name "KbS_V1_5.Deponietyp_",
                        xmlelement(name "value", standorte.deponietyp)
                        )
                  )
                else
                    xmlcomment('Deponietyp not available')
          end,
          case
                when standorte.nachsorge is not null then
                    xmlelement(name "Nachsorge", standorte.nachsorge)
                else
                    xmlcomment('Nachsorge not available')
          end, -- Nicht bei BAV
          case 
                when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'Mapping_Untersuchungsmassnahmen') = 'alle nach Geschäften' then
                  xmlelement(name "Untersuchungsmassnahmen", (select xmlagg(x_v15) from untersuchungsmassnahmen_xml_pm where untersuchungsmassnahmen_xml_pm.vfl_id = standorte.vfl_id))
                when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'Mapping_Untersuchungsmassnahmen') = 'alle nach Standortversionen' then
                  xmlelement(name "Untersuchungsmassnahmen", (select xmlagg(x_v15) from untersuchungsmassnahmen_xml_vfl where untersuchungsmassnahmen_xml_vfl.vfl_id = standorte.vfl_id))
                when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'Mapping_Untersuchungsmassnahmen') = 'aktuellste' then
                  xmlelement(name "Untersuchungsmassnahmen", (select xmlagg(x_v15) from untersuchungsmassnahmen_xml_vflz where untersuchungsmassnahmen_xml_vflz.vflz_id = standorte.vflz_id))
                else 
                  xmlelement(name "Untersuchungsmassnahmen", (select xmlagg(x_v15) from untersuchungsmassnahmen_xml_vflz where untersuchungsmassnahmen_xml_vflz.vflz_id = standorte.vflz_id))
          end,
          xmlelement(name "StatusAltlV", standorte.statusaltlv),
          xmlelement(name "Ersteintrag", standorte.date_ersteintrag::date),
          xmlelement(name "LetzteAnpassung", standorte.date_letzteanpassung::date),
          xmlelement(name "URL_KbS_Auszug",                                                                                                                                                               
             xmlelement(name "KbS_V1_5.Belastete_Standorte.MultilingualUri",                                                                                                                               
                 xmlelement(name "LocalisedText",                                                                                                                                                          
                     xmlelement(name "KbS_V1_5.Belastete_Standorte.LocalisedUri",                                                                                                                          
                         xmlelement(name "Language", 'de'),                                                                                                                                                
                         xmlelement(name "Text", standorte.url_kbs_datasheet)                                                                                                                              
                     ),                                                                                                                                                                                    
                     xmlelement(name "KbS_V1_5.Belastete_Standorte.LocalisedUri",                                                                                                                          
                         case when (select org.kuerzel from altlast_admin.setitem join altlast_admin.setting using (setitem_id) join altlast.org on org.org_id=setting.value::int where key= 'org') = 'GR' 
                             then xmlelement(name "Language", 'rm')                                                                                                                                        
                             else xmlelement(name "Language", 'fr') end,                                                                                                                                   
                     xmlelement(name "Text", standorte.url_kbs_datasheet)                                                                                                                                  
                     ),                                                                                                                                                                                   
                     xmlelement(name "KbS_V1_5.Belastete_Standorte.LocalisedUri",                                                                                                                          
                         xmlelement(name "Language", 'it'),                                                                                                                                               
                         xmlelement(name "Text", standorte.url_kbs_datasheet)                                                                                                                              
                     )                                                                                                                                                                                     
                 )                                                                                                                                                                                        
             )                                                                                                                                                                                            
           ),   
          /*
          case
                when standorte.standort_bemerkungen != '' then
                    xmlelement(name "Bemerkung", altlast_ili.geoig_localisedmtext(coalesce(standorte.standort_bemerkungen,''), 'de'))
                else
                    */
                    xmlcomment('Bemerkung not available')
          /*end*/,
          xmlelement(name "ZustaendigkeitKataster",
            xmlattributes(
                standorte.zb_tid as "REF"
            )
          )
      ) as x
    from standorte
    join geoportallinks on geoportallinks.vflz_id = standorte.vflz_id
    order by standorte.stao_tid
),


-- org
zustaendige_behoerde as (
select distinct
        'zb'||org.org_id::text as zb_tid, /* this id also gets build in the standorte with-clause*/
        case when org.org_id = 310 then org.bezeichnung_lang 
            else (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'Behoerde_Amt') 
            end as behoerde,
        (select case 
            when org.org_id = 310 then (select url_behoerde from altlast.org where org_id = 310)
            else (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_Behoerde_Amt')
        end as url_behoerde) as url_behoerde_de,
        (select case 
            when org.org_id = 310 then (select url_behoerde from altlast.org where org_id = 310)
            else (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_Behoerde_Amt_fr')
        end as url_behoerde) as url_behoerde_fr,
        (select case 
            when org.org_id = 310 then (select url_behoerde from altlast.org where org_id = 310)
            else (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_Behoerde_Amt_it')
        end as url_behoerde) as url_behoerde_it,
        (select case 
            when org.org_id = 310 then (select url_behoerde from altlast.org where org_id = 310)
            else (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_Behoerde_Amt_fr')
        end as url_behoerde) as url_behoerde_rm,
        case when org.org_id = 310 then null
            else (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'UID_Behoerde_Amt') 
            end as uid,
        coalesce(org.katastername, org.bezeichnung)::text as katastername,
        (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_Standort_Kataster')::text as url_webgis,
        org.org_id
     from altlast.org
       /* only load orgs which are referenced from sites*/
     where org.org_id in (select org_id from standorte)
),

-- org as xml
zustaendige_behoerde_xml as (
    select 
    xmlelement(name "KbS_V1_5.Belastete_Standorte.ZustaendigkeitKataster",
      xmlattributes(zustaendige_behoerde.zb_tid as "TID"),
      xmlelement(name "Zustaendige_Behoerde", altlast_ili.geoig_localisedtext_t(zustaendige_behoerde.behoerde, 
        array['de',
            case when (select org.kuerzel from altlast_admin.setitem join altlast_admin.setting using (setitem_id) join altlast.org on org.org_id=setting.value::int where key= 'org') = 'GR' 
                then 'rm' 
            else 'fr' end,
            'it'
        ])),

      xmlelement(name "URL_Behoerde",                                                                                                                                                                     
             xmlelement(name "KbS_V1_5.Belastete_Standorte.MultilingualUri",                                                                                                                               
                 xmlelement(name "LocalisedText",                                                                                                                                                         
                     xmlelement(name "KbS_V1_5.Belastete_Standorte.LocalisedUri",                                                                                                                         
                         xmlelement(name "Language", 'de'),                                                                                                                                               
                         xmlelement(name "Text", zustaendige_behoerde.url_behoerde_de)                                                                                                                    
                     ),                                                                                                                                                                                   
                     xmlelement(name "KbS_V1_5.Belastete_Standorte.LocalisedUri",                                                                                                                         
                         case when (select org.kuerzel from altlast_admin.setitem join altlast_admin.setting using (setitem_id) join altlast.org on org.org_id=setting.value::int where key= 'org')= 'GR' 
                             then xmlelement(name "Language", 'rm')                                                                                                                                       
                             else xmlelement(name "Language", 'fr') end,                                                                                                                                  
                         xmlelement(name "Text", zustaendige_behoerde.url_behoerde_fr)                                                                                                                    
                     ),                                                                                                                                                                                   
                     xmlelement(name "KbS_V1_5.Belastete_Standorte.LocalisedUri",                                                                                                                         
                         xmlelement(name "Language", 'it'),                                                                                                                                               
                         xmlelement(name "Text", zustaendige_behoerde.url_behoerde_it)                                                                                                                    
                     )                                                                                                                                                                                    
                 )                                                                                                                                                                                        
             )                                                                                                                                                                                            
         ), 

      xmlelement(name "UID", zustaendige_behoerde.uid),
      xmlelement(name "Katastername",
            altlast_ili.geoig_localisedtext_t(zustaendige_behoerde.katastername, 
            array['de',
                    case when (select org.kuerzel from altlast_admin.setitem join altlast_admin.setting using (setitem_id) join altlast.org on org.org_id=setting.value::int where key= 'org') = 'GR' 
                        then 'rm' 
                    else 'fr' end,
                    'it'
                ])
      ),

      xmlelement(name "URL_Kataster",                                                                                                                                                                     
             xmlelement(name "KbS_V1_5.Belastete_Standorte.MultilingualUri",                                                                                                                               
                 xmlelement(name "LocalisedText",                                                                                                                                                         
                     xmlelement(name "KbS_V1_5.Belastete_Standorte.LocalisedUri",                                                                                                                         
                         xmlelement(name "Language", 'de'),                                                                                                                                               
                         xmlelement(name "Text", concat(zustaendige_behoerde.url_webgis, '&lang=de'))                                                                                                     
                     ),                                                                                                                                                                                   
                     xmlelement(name "KbS_V1_5.Belastete_Standorte.LocalisedUri",                                                                                                                         
                         case when (select org.kuerzel from altlast_admin.setitem join altlast_admin.setting using (setitem_id) join altlast.org on org.org_id=setting.value::int where key= 'org')= 'GR' 
                             then xmlelement(name "Language", 'rm')                                                                                                                                       
                             else xmlelement(name "Language", 'fr') end,                                                                                                                                  
                         case when (select org.kuerzel from altlast_admin.setitem join altlast_admin.setting using (setitem_id) join altlast.org on org.org_id=setting.value::int where key= 'or') = 'GR' 
                                  then xmlelement(name "Text", concat(zustaendige_behoerde.url_webgis, '&lang=rm'))                                                                                       
                                 else xmlelement(name "Text", concat(zustaendige_behoerde.url_webgis, '&lang=fr')) end                                                                                    
                     ),                                                                                                                                                                                   
                     xmlelement(name "KbS_V1_5.Belastete_Standorte.LocalisedUri",                                                                                                                         
                         xmlelement(name "Language", 'it'),                                                                                                                                               
                         xmlelement(name "Text", concat(zustaendige_behoerde.url_webgis, '&lang=it'))                                                                                                     
                     )                                                                                                                                                                                    
                 )                                                                                                                                                                                        
             )                                                                                                                                                                                            
         )   


    ) as x_v15
    from zustaendige_behoerde
)

-- assembling of the finished xml document according to the interlis schema
select xmlelement(name "TRANSFER", xmlattributes('http://www.interlis.ch/INTERLIS2.3' as xmlns),
    xmlelement(name "HEADERSECTION",
        xmlattributes('altlast4web' as "SENDER", '2.3' as "VERSION"),
          xmlelement(name "MODELS", -- need to add all used models by hand
              xmlelement(name "MODEL",xmlattributes('CoordSys' as "NAME",'2015-11-24' as "VERSION",'https://www.interlis.ch/models' as "URI")),
              xmlelement(name "MODEL",xmlattributes('InternationalCodes_V1' as "NAME",'2011-08-30' as "VERSION",'https://www.geo.admin.ch' as "URI")),
              xmlelement(name "MODEL",xmlattributes('Localisation_V1' as "NAME",'2011-08-30' as "VERSION",'https://www.geo.admin.ch' as "URI")),
              xmlelement(name "MODEL",xmlattributes('LocalisationCH_V1' as "NAME",'2011-08-30' as "VERSION",'https://www.geo.admin.ch' as "URI")),
              xmlelement(name "MODEL",xmlattributes('Dictionaries_V1' as "NAME",'2011-08-30' as "VERSION",'https://www.geo.admin.ch' as "URI")),
              xmlelement(name "MODEL",xmlattributes('DictionariesCH_V1' as "NAME",'2011-08-30' as "VERSION",'https://www.geo.admin.ch' as "URI")),
              xmlelement(name "MODEL",xmlattributes('Units' as "NAME",'2012-02-20' as "VERSION",'https://www.interlis.ch/models' as "URI")),
              xmlelement(name "MODEL",xmlattributes('GeometryCHLV95_V1' as "NAME",'2015-11-12' as "VERSION",'https://www.geo.admin.ch' as "URI")),
              xmlelement(name "MODEL",xmlattributes('KbS_V1_5' as "NAME",'2021-10-15' as "VERSION",'https://models.geo.admin.ch/BAFU' as "URI")),
              xmlelement(name "MODEL",xmlattributes('KbS_V1_5_LU_V1' as "NAME",'2022-05-30' as "VERSION",'' as "URI"))

          )
    ),
   
    xmlelement(name "DATASECTION",
        xmlelement(name "KbS_V1_5.Belastete_Standorte",-- there is no attribute that could server as a bucket-identifier. so we generate an artiffical one.
            xmlattributes((select bid from bidprops) as "BID"),
                ( select xmlagg(x_v15) from zustaendige_behoerde_xml),
                ( select xmlagg(x) from standorte_xml_v15)
        )
    )

);

$_$;


--
-- Name: export_geoig_v12(integer[]); Type: FUNCTION; Schema: altlast_ili; Owner: -
--

CREATE FUNCTION altlast_ili.export_geoig_v12(p_vflz_ids integer[]) RETURNS xml
    LANGUAGE sql
    AS $_$
/**

Development


part of this function got generated by cog: http://nedbatchelder.com/code/cog/
use that tool when modifying the autogenerated codeblocks

so do not delete the comment containing "cog" directives.



Regarding coordinate systems


Since Version 1.2 of the Geoig model the creators realized that there is more than one
coordinate system in existence. Since there seems no support for coordinate systems
in interlis itself, the coordinate systems name gets included in some of the tag names.

Example:
EPSG:21781  -> KbS_LV03_V1_2.Belastete_Standorte.Parzellenidentifikation
EPSG:2056   -> KbS_LV95_V1_2.Belastete_Standorte.Parzellenidentifikation

So, if the coordinate system used by altlast gets changed, this function also needs
a adaption.
*/

-- all sites of the list of vflz_ids
with wmsprops as (
    select
        wms_url as endpoint,
        wms_version,
        wms_layername as layername,
        geoportal_layername as layername_geoportal,
        geoportal_url as url_geoportal,
        geoportal_additional_layers as additional_layers_geoportal
     from altlast_ili.config_wms
     order by config_wms_id limit 1
),

-- wms requests
wmslayerrequest as (
    select
          geo.vflz_id,
          wmsprops.endpoint,
          wmsprops.wms_version,
          wmsprops.url_geoportal,
          wmsprops.additional_layers_geoportal,
          wmsprops.layername,
          -- calculate a boundinbox to fit the geometry in the given image dimensions
          st_xmin(geo.box)::text || ',' || st_ymin(geo.box)::text || ',' ||
                   st_xmax(geo.box)::text || ',' || st_ymax(geo.box)::text as bbox,
          geo.width as image_width,
          geo.height as image_height,
          geo.srid
    from  (
        select vflz_id,
            altlast.scaleextent(st_buffer(vflgeo.wkb_geometry, 10), imagesize.width::double precision/screen_dpi::double precision,
                    imagesize.height::double precision/screen_dpi::double precision)::box2d as box,
            st_srid(vflgeo.wkb_geometry) as srid,
            imagesize.width,
            imagesize.height
            from altlast.vflgeo, (
                -- dimensions of the wms image
                select 740 as width, 500 as height, 96 as screen_dpi
            ) as imagesize
     ) as geo, wmsprops
),

-- all sites of the list of vflz_ids
standorte as (
    select 'stao'||v.vflz_id::text as stao_tid,
        v.vflz_id,
        v.vfl_id,
        v.vflz_combined_id_kt,
        vflgeo.wkb_geometry,
        vflnr.org_id,
        'zb'||vflnr.org_id::text as zb_tid,
        bem_standort.bem as standort_bemerkungen,
        case when v.x_koordinate is not null and v.y_koordinate is not null then st_makepoint(v.x_koordinate, v.y_koordinate) else null end as wkb_point,
        staotyp_mapping.code_long as staotyp,
        null::text as deponietyp,
        false::text as nachsorge, -- bav wants this attribute to be missing, the spec wants it to be set -- so its always set to false now
        null::text as egrid,
        v.dat_rechtskraft::date as date_ersteintrag,
        (   -- legally binding date
            SELECT vflz_is_published_v.dat_latest_published::text AS dat_latest_published
               FROM altlast.vflz_is_published_v
               WHERE (vflz_is_published_v.vflz_id IN ( SELECT vflz_any_in_vfl.vflz_id
                                    FROM altlast.vflz vflz_any_in_vfl
                                    WHERE vflz_any_in_vfl.vfl_id = v.vfl_id)
                    ) AND vflz_is_published_v.is_latest_published
        )::date as date_letzteanpassung,
        statusaltlv_mapping.code_long as statusaltlv,
        /*v.zeitraum_bisheute*/ False as inbetrieb, /* Bei BAV keine Ablagerungen in Betrieb: Deshalb Wert standardmässig auf „NEIN“ */
        vfilename.baseurl || vfilename.filename as url_kbs_datasheet
    from altlast.vflz v
    join altlast.vflz_is_published_v vip on v.vflz_id = vip.vflz_id and vip.is_latest_published /* only published versions */
    join altlast_ili.cod_mapping_v staotyp_mapping on staotyp_mapping.c_cli_id = v.h_vflz_vftyp
                and staotyp_mapping.code = v.c_vflz_vftyp
    join altlast.bere_v on bere_v.vflz_id = v.vflz_id and bere_v.kbs
    join altlast_ili.cod_mapping_v statusaltlv_mapping on statusaltlv_mapping.c_cli_id = bere_v.h_bere_res_abwbewe
                and statusaltlv_mapping.code = bere_v.c_bere_res_abwbewe
    join altlast.vflnr on v.vflz_id = vflnr.vflz_id and vflnr.aktiv

    -- restrict using the ord configured in a4w
    join altlast_admin.setting stng on stng.value = vflnr.org_id::text
    join altlast_admin.setitem sit on sit.setitem_id = stng.setitem_id and sit.key = 'org'

    left  join altlast.vflgeo on vflgeo.vflz_id = v.vflz_id
    left join altlast.bemgrp bemg_standort on bemg_standort.public and bemg_standort.bemgrp='standort'
    left join altlast.bem bem_standort on bem_standort.bemgrp_id = bemg_standort.bemgrp_id and
                bem_standort.key_value = v.vflz_id and bem_standort.public

    left join altlast.vflz_filename_v vfilename on vfilename.vflz_id = v.vflz_id

    where v.vfl_id in (
        select vfl_id from altlast.vflz where vflz_id = any($1)
    )
),

geoportallinks as (
    select
        standorte.vflz_id,
        wmsprops.url_geoportal
                || '?Y=' || st_x(standorte.wkb_point)::text -- coordinates reversed -- not a typo
                || '&X=' || st_y(standorte.wkb_point)::text
                || '&zoom=12'
                || '&bgLayer=' || wmsprops.additional_layers_geoportal
                || '&layers=' || wmsprops.layername_geoportal
                || '&layers_opacity=1'
                || '&bgOpacity=0.8'
                || '&layers_visibility=true' as permalink_geoportal
    from standorte, wmsprops
),


-- parcels for all returned sites
parzellen as (
select
    null as nbident,  /* Der NBIdent  (Nummerierungsbereichidentifikator) setzt sich zusammen
                         aus dem Kt (Kantonskürzel) und der NBNummer  (Nummerierungsbereichnummer). */
    sv.vflz_id,
    g.gb_nummer

from altlast.subj_vflz sv
join altlast.subj_vflz_grun svg on sv.subj_vflz_id = svg.subj_vflz_id
join altlast.grun g on svg.grun_id = g.grun_id
where
    sv.vflz_id in (select vflz_id from standorte)
    and false /* never return any parcels as we can never returned the required nbident number */
),

-- parcels in xml form
parzellen_xml as (
select parzellen.vflz_id,
    xmlelement(name "KbS_LV03_V1_2.Belastete_Standorte.Parzellenidentifikation",
        xmlelement(name "NBIdent", parzellen.nbident),
        xmlelement(name "Parzellennummer", parzellen.gb_nummer)
    ) as x
from parzellen
),

untersuchungsmassnahmen_pre as (
select massn.*
from (
    select tm.code_long, tm.ili_code, tm.ili_c_cli_id, pv.vfl_id
    from altlast_ili.task_mapping_v tm
    join altlast.pm_cache_v pc on pc.pro_uid = tm.pro_uid
                and pc.status = 'CLOSED'
                and case when tm.tas_uid is null then true else tm.tas_uid = pc.tas_uid end
    join altlast.pm_vfl pv on pv.pm_vfl_id = pc.pm_vfl_id
) massn
join standorte s on massn.vfl_id = s.vfl_id
),

untersuchungsmassnahmen as (
select
    s.vfl_id, up.code_long, up.ili_code, up.ili_c_cli_id
from untersuchungsmassnahmen_pre up
join standorte s on up.vfl_id = s.vfl_id
union
-- provide UntMassn1 if no other untersuchungsmassnahme is available
select s.vfl_id, 'UntMassn1' as code_long, 'UM1' as ili_code, 20023 as ili_c_cli_id
from standorte s
    where s.vfl_id not in (select vfl_id from untersuchungsmassnahmen_pre)
    ),

untersuchungsmassnahmen_xml as (
select um.vfl_id,
    xmlelement(name "KbS_LV03_V1_2.Belastete_Standorte.UntersMassn_",
        xmlelement(name "value", um.code_long)
    ) as x
from untersuchungsmassnahmen um
),

-- sites in xml form
standorte_xml as (
    select xmlelement(name "KbS_LV03_V1_2.Belastete_Standorte.Belasteter_Standort",
          xmlattributes(standorte.stao_tid as "TID"),
          xmlelement(name "Katasternummer", standorte.vflz_combined_id_kt),
          xmlelement(name "URL_Standort", geoportallinks.permalink_geoportal),
          case when standorte.wkb_geometry is not null then
                case when st_geometrytype(standorte.wkb_geometry) = 'ST_Point' then
                    xmlelement(name "Geo_Lage_Punkt", altlast_ili.geometry(standorte.wkb_geometry))
                else
                    xmlelement(name "Geo_Lage_Polygon", altlast_ili.geometry(standorte.wkb_geometry))
                end
            else
                xmlelement(name "Geo_Lage_Punkt", altlast_ili.geometry(standorte.wkb_point))
          end,
          case
               when exists(select vflz_id from parzellen_xml where parzellen_xml.vflz_id = standorte.vflz_id) then
                  xmlelement(name "Parzellenverweis",
                        (select xmlagg(x) from parzellen_xml where parzellen_xml.vflz_id = standorte.vflz_id)
                  )
               else
                  xmlcomment('Parzellenverweis not available')
          end,
          case
               when standorte.egrid is not null then
                  xmlelement(name "EGRID", xmlelement(name "KbS_LV03_V1_2.Belastete_Standorte.EGRID_",
                        xmlelement(name "value", standorte.egrid)
                        )
                  )
                else
                    xmlcomment('EGRID not available')
          end, -- nicht bei BAV
          xmlelement(name "Standorttyp", standorte.staotyp),
          xmlelement(name "InBetrieb", standorte.inbetrieb),
          case
               when standorte.deponietyp is not null then
                  --  Nicht für BAV, da wir keine Ablagerungen „in Betrieb“ haben werden
                  xmlelement(name "Deponietyp", xmlelement(name "KbS_LV03_V1_2.Belastete_Standorte.Deponietyp_",
                        xmlelement(name "value", standorte.deponietyp)
                        )
                  )
                else
                    xmlcomment('Deponietyp not available')
          end,
          case
                when standorte.nachsorge is not null then
                    xmlelement(name "Nachsorge", standorte.nachsorge)
                else
                    xmlcomment('Nachsorge not available')
          end, -- Nicht bei BAV
          xmlelement(name "Untersuchungsmassnahmen",
                (select xmlagg(x) from untersuchungsmassnahmen_xml where untersuchungsmassnahmen_xml.vfl_id = standorte.vfl_id)
          ),
          xmlelement(name "StatusAltlV", standorte.statusaltlv),
          xmlelement(name "Ersteintrag", standorte.date_ersteintrag::date),
          xmlelement(name "LetzteAnpassung", standorte.date_letzteanpassung::date),
          xmlelement(name "URL_KbS_Auszug", standorte.url_kbs_datasheet),
          /*
          case
                when standorte.standort_bemerkungen != '' then
                    xmlelement(name "Bemerkung", altlast_ili.geoig_localisedmtext(coalesce(standorte.standort_bemerkungen,''), 'de'))
                else
                    */
                    xmlcomment('Bemerkung not available')
          /*end*/,
          xmlelement(name "ZustaendigkeitKataster",
            xmlattributes(
                standorte.zb_tid as "REF"
            )
          )
      ) as x
    from standorte
    join geoportallinks on geoportallinks.vflz_id = standorte.vflz_id
),

-- org
zustaendige_behoerde as (
   select distinct
         'zb'||org.org_id::text as zb_tid, /* this id also gets build in the standorte with-clause*/
         coalesce(org.bezeichnung_lang, org.bezeichnung) as behoerde,
         org.url_behoerde as url_behoerde,
         coalesce(org.katastername, org.bezeichnung)::text as katastername,
         org.url_webgis::text as url_webgis,
         org.org_id
     from altlast.org
       /* only load orgs which are referenced from sites*/
     where org.org_id in (select org_id from standorte)
),

-- org as xml
zustaendige_behoerde_xml as (
    select xmlelement(name "KbS_LV03_V1_2.Belastete_Standorte.ZustaendigkeitKataster",
      xmlattributes(zustaendige_behoerde.zb_tid as "TID"),
      xmlelement(name "Zustaendige_Behoerde", altlast_ili.geoig_localisedtext_t(zustaendige_behoerde.behoerde, array['de','fr','it'])),
      xmlelement(name "URL_Behoerde", zustaendige_behoerde.url_behoerde),
      xmlelement(name "Katastername",
           altlast_ili.geoig_localisedtext_t(zustaendige_behoerde.katastername, array['de','it','fr'])
      ),
      xmlelement(name "URL_Kataster", zustaendige_behoerde.url_webgis)
     ) as x from zustaendige_behoerde
)

-- assembling of the finished xml document according to the interlis schema
select xmlelement(name "TRANSFER",
   xmlattributes('http://www.interlis.ch/INTERLIS2.3' as xmlns),
   xmlelement(name "HEADERSECTION",
        xmlattributes('altlast4web' as "SENDER", '2.3' as "VERSION"),
        xmlelement(name "MODELS",
            -- need to add all used models by hand
            xmlelement(name "MODEL",
                xmlattributes(
                    'KbS_LV03_V1_2' as "NAME",
                    'http://models.geo.admin.ch/BAFU/KbS_V1_2.ili' as "URI",
                    '2014-05-20' as "VERSION"
                )
            ),
            xmlelement(name "MODEL",
                xmlattributes(
                    'GeometryCHLV03_V1' as "NAME",
                    'http://models.geo.admin.ch/CH/CHBase_Part1_GEOMETRY_20110830.ili' as "URI",
                    '2011-08-30' as "VERSION"
                )
            ),
            xmlelement(name "MODEL",
                xmlattributes(
                    'LocalisationCH_V1' as "NAME",
                    'http://models.geo.admin.ch/CH/CHBase_Part2_LOCALISATION_20110830.ili' as "URI",
                    '2011-08-30' as "VERSION"
                )
            )
        )
   ),
   xmlelement(name "DATASECTION",
        /* comment containing all affected vflz_ids. this has to be removed from the ouptut as it
           will caus ea buffer overflow in the intelischecker :)))
        xmlcomment('Generated when exporting the following vflz_ids: ' || $1::text),
        */
        xmlelement(name "KbS_LV03_V1_2.Belastete_Standorte",
            -- there is no attribute that could server as a bucket-identifier. so we generate an artiffical one.
            xmlattributes('bs'||extract(epoch from current_timestamp)::integer::text as "BID"),
            ( select xmlagg(x) from zustaendige_behoerde_xml),
            ( select xmlagg(x) from standorte_xml)),
        /*
        xmlelement(name "CoordSys.CoordsysTopic",
           xmlattributes('cs868' as "BID")
        ),
        */
        xmlelement(name "KbS_LV03_V1_2.Codelisten",
           xmlattributes('cl78868' as "BID")
/*[[[cog
# generate the queries for each of the codelists
import cog

# if you need to add new codelists just add them the the following python list
# and run this file through cog.py
codelists = (
    # c_cli_id, tagname, tidprefix
    (20333, 'KbS_LV03_V1_2.Codelisten.Deponietyp_Definition'),
    (20063, 'KbS_LV03_V1_2.Codelisten.Standorttyp_Definition'),
    (20103, 'KbS_LV03_V1_2.Codelisten.StatusAltlV_Definition'),
    (20023, 'KbS_LV03_V1_2.Codelisten.Untersuchungsmassnahmen_Definition')
    )
for cl in codelists:
    args = {
        'c_cli_id': int(cl[0]),
        'tid':      'cl' + str(cl[0]),
        'tag':      cl[1]
    }
    cog.outl(""", xmlcomment('Codes for codelist with c_cli_id = %(c_cli_id)s'),
            (select xmlagg(x) from (
               select xmlelement(name "%(tag)s",
                    xmlattributes( '%(tid)s'||lower(cod.code) as "TID"),
                    xmlelement(name "Code", cod_long.code_long),
                    xmlelement(name "Definition",
                        altlast_ili.geoig_localisedtext_code(cod.c_cli_id, cod.code::text)
                    )
                    ) as x
                from altlast.cod as cod
                join altlast_ili.cod_long on cod_long.code = cod.code and cod_long.c_cli_id = cod.c_cli_id
                where cod.c_cli_id = %(c_cli_id)d ) cle ) """ % args)
]]]*/
, xmlcomment('Codes for codelist with c_cli_id = 20333'),
            (select xmlagg(x) from (
               select xmlelement(name "KbS_LV03_V1_2.Codelisten.Deponietyp_Definition",
                    xmlattributes( 'cl20333'||lower(cod.code) as "TID"),
                    xmlelement(name "Code", cod_long.code_long),
                    xmlelement(name "Definition",
                        altlast_ili.geoig_localisedtext_code(cod.c_cli_id, cod.code::text)
                    )
                    ) as x
                from altlast.cod as cod
                join altlast_ili.cod_long on cod_long.code = cod.code and cod_long.c_cli_id = cod.c_cli_id
                where cod.c_cli_id = 20333 ) cle )
, xmlcomment('Codes for codelist with c_cli_id = 20063'),
            (select xmlagg(x) from (
               select xmlelement(name "KbS_LV03_V1_2.Codelisten.Standorttyp_Definition",
                    xmlattributes( 'cl20063'||lower(cod.code) as "TID"),
                    xmlelement(name "Code", cod_long.code_long),
                    xmlelement(name "Definition",
                        altlast_ili.geoig_localisedtext_code(cod.c_cli_id, cod.code::text)
                    )
                    ) as x
                from altlast.cod as cod
                join altlast_ili.cod_long on cod_long.code = cod.code and cod_long.c_cli_id = cod.c_cli_id
                where cod.c_cli_id = 20063 ) cle )
, xmlcomment('Codes for codelist with c_cli_id = 20103'),
            (select xmlagg(x) from (
               select xmlelement(name "KbS_LV03_V1_2.Codelisten.StatusAltlV_Definition",
                    xmlattributes( 'cl20103'||lower(cod.code) as "TID"),
                    xmlelement(name "Code", cod_long.code_long),
                    xmlelement(name "Definition",
                        altlast_ili.geoig_localisedtext_code(cod.c_cli_id, cod.code::text)
                    )
                    ) as x
                from altlast.cod as cod
                join altlast_ili.cod_long on cod_long.code = cod.code and cod_long.c_cli_id = cod.c_cli_id
                where cod.c_cli_id = 20103 ) cle )
, xmlcomment('Codes for codelist with c_cli_id = 20023'),
            (select xmlagg(x) from (
               select xmlelement(name "KbS_LV03_V1_2.Codelisten.Untersuchungsmassnahmen_Definition",
                    xmlattributes( 'cl20023'||lower(cod.code) as "TID"),
                    xmlelement(name "Code", cod_long.code_long),
                    xmlelement(name "Definition",
                        altlast_ili.geoig_localisedtext_code(cod.c_cli_id, cod.code::text)
                    )
                    ) as x
                from altlast.cod as cod
                join altlast_ili.cod_long on cod_long.code = cod.code and cod_long.c_cli_id = cod.c_cli_id
                where cod.c_cli_id = 20023 ) cle )
--[[[end]]]
        )
        )
   );
$_$;


--
-- Name: export_geoig_v14(integer[], text); Type: FUNCTION; Schema: altlast_ili; Owner: -
--

CREATE FUNCTION altlast_ili.export_geoig_v14(p_vflz_ids integer[], ili_version text) RETURNS xml
    LANGUAGE sql
    AS $_$

/**
Development
part of this function got generated by cog: https://nedbatchelder.com/code/cog/
use that tool when modifying the autogenerated codeblocks
so do not delete the comment containing "cog" directives.
Regarding coordinate systems
*/

-- all sites of the list of vflz_ids
with bidprops as (
    select 
        'kbsMGDM' || org.kuerzel as bid
    from altlast_admin.setitem
    join altlast_admin.setting using (setitem_id)
    join altlast.org on org.org_id::text=setting.value
    where key = 'org'
),

wmsprops as (
    select 
      case when (select value as url_geoportal from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_Standort') is not null then 
        (select value as url_geoportal from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_Standort')
      else null end as url_geoportal
),


-- all sites of the list of vflz_ids
standorte as (
    select 'stao'||v.vflz_id::text as stao_tid,
        v.vflz_id,
        v.vfl_id,
        v.vflz_combined_id_kt,
        vflgeo.wkb_geometry,
        vflnr.org_id,
        'zb'||vflnr.org_id::text as zb_tid,
        bem_standort.bem as standort_bemerkungen,
        case when v.x_koordinate is not null and v.y_koordinate is not null then st_makepoint(v.x_koordinate, v.y_koordinate) else null end as wkb_point,
        staotyp_mapping.code_long as staotyp,
        v.c_vflz_deponietyp::text as deponietyp,
        case when v.c_vflz_nachsorge = '01' then true::text else false::text end as nachsorge, 
        null::text as egrid,
        v.dat_rechtskraft::date as date_ersteintrag,
        (   -- legally binding date
            SELECT vflz_is_published_v.dat_latest_published::text AS dat_latest_published
               FROM altlast.vflz_is_published_v
               WHERE (vflz_is_published_v.vflz_id IN ( SELECT vflz_any_in_vfl.vflz_id
                                    FROM altlast.vflz vflz_any_in_vfl
                                    WHERE vflz_any_in_vfl.vfl_id = v.vfl_id)
                    ) AND vflz_is_published_v.is_latest_published
        )::date as date_letzteanpassung,
        statusaltlv_mapping.code_long as statusaltlv,
        case when v.c_vflz_inbetrieb = '01' then true::text else false::text end as inbetrieb, 
        case when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_KbS_Auszug') is not null then
          (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_KbS_Auszug') 
          || (regexp_replace(vfilename.filename::text, ' '::text, '%20'::text, 'g'::text))
          else null end as url_kbs_datasheet
    from altlast.vflz v
    join altlast.vflz_is_published_v vip on v.vflz_id = vip.vflz_id and vip.is_latest_published /* only published versions */
    join altlast_ili.cod_mapping_v staotyp_mapping on staotyp_mapping.c_cli_id = v.h_vflz_vftyp
                and staotyp_mapping.code = v.c_vflz_vftyp
    join altlast.bere_v on bere_v.vflz_id = v.vflz_id and bere_v.kbs
    join altlast_ili.cod_mapping_v statusaltlv_mapping on statusaltlv_mapping.c_cli_id = bere_v.h_bere_res_abwbewe
                and statusaltlv_mapping.code = bere_v.c_bere_res_abwbewe
    join altlast.vflnr on v.vflz_id = vflnr.vflz_id and vflnr.aktiv

    -- restrict using the ord configured in a4w
    join altlast_admin.setting stng on stng.value = vflnr.org_id::text
    join altlast_admin.setitem sit on sit.setitem_id = stng.setitem_id and sit.key in ('org', 'astra')

    left  join altlast.vflgeo on vflgeo.vflz_id = v.vflz_id
    left join altlast.bemgrp bemg_standort on bemg_standort.public and bemg_standort.bemgrp='standort'
    left join altlast.bem bem_standort on bem_standort.bemgrp_id = bemg_standort.bemgrp_id and
                bem_standort.key_value = v.vflz_id and bem_standort.public

    left join altlast.vflz_filename_v vfilename on vfilename.vflz_id = v.vflz_id

    where v.vfl_id in (
        select vfl_id from altlast.vflz where vflz_id = any($1)
    )
    order by v.vflz_id
),

geoportallinks as (
    select
        standorte.vflz_id,
        case when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_Standort_Indikator') = 'standortnummer' then
          wmsprops.url_geoportal || (regexp_replace(standorte.vflz_combined_id_kt::text, ' '::text, '%20'::text, 'g'::text))
        when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_Standort_Indikator') = 'xy_koordinates' then
           wmsprops.url_geoportal || '&Y=' || st_x(standorte.wkb_point)::text || '&X=' || st_y(standorte.wkb_point)::text
        when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_Standort_Indikator') = 'map_x_map_y_koordinates' then
           wmsprops.url_geoportal || '&map_x=' || st_x(standorte.wkb_point)::text || '&map_y=' || st_y(standorte.wkb_point)::text
        when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_Standort_Indikator') = 'c_koordinates' then
           wmsprops.url_geoportal || '&c=' || st_y(standorte.wkb_point)::text || ',' || st_x(standorte.wkb_point)::text 
        else wmsprops.url_geoportal 
        end as permalink_geoportal
    from standorte, wmsprops
),


-- parcels for all returned sites
parzellen as (
  select 
    org || bfsnr as nbident, vflz_id, parzelle 
  from (select 
      vpmv.h_gem_id as bfsnr,  /* Der NBIdent  (Nummerierungsbereichidentifikator) setzt sich zusammen
               aus dem Kt (Kantonskürzel) und der NBNummer  (Nummerierungsbereichnummer). */
      (select org.kuerzel from altlast_admin.setitem join altlast_admin.setting using (setitem_id) join altlast.org on org.org_id=setting.value::int where key= 'org') as org,
      vpmv.vflz_id as vflz_id,
      vpmv.gb_nummer as parzelle,
      case when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'Parzellenverweiss') = 'Ja' then true
      else false /* never return any parcels as we can never returned the required nbident number */
      end as parzellenverweiss
        from altlast.vflz_parzellen_materialization_v vpmv
        group by vpmv.h_gem_id, vpmv.vflz_id, vpmv.gb_nummer)foo
  where foo.vflz_id in (select vflz_id from standorte) and foo.parzellenverweiss
  order by bfsnr, parzelle
),

-- parcels in xml form
parzellen_xml as (
select parzellen.vflz_id,
        xmlelement(name "KbS_Basis_V1_4.Parzellenidentifikation",
        xmlelement(name "NBIdent", parzellen.nbident),
        xmlelement(name "Parzellennummer", parzellen.parzelle)
    ) as x_v14
from parzellen
order by parzellen.parzelle
),

untersuchungsmassnahmen_pre_pm as (
select massn.*
from (
      select tm.code_long, tm.ili_code, tm.ili_c_cli_id, pv.vfl_id from altlast_ili.task_mapping_v tm 
        join altlast.pm_cache_v pc on pc.pro_uid = tm.pro_uid and pc.status = 'CLOSED' and case when tm.tas_uid is null then true else tm.tas_uid = pc.tas_uid end
        join altlast.pm_vfl pv on pv.pm_vfl_id = pc.pm_vfl_id
) massn
join standorte s on massn.vfl_id = s.vfl_id
),

untersuchungsmassnahmen_pm as (
select
    s.vfl_id, up.code_long, up.ili_code, up.ili_c_cli_id
from untersuchungsmassnahmen_pre_pm up
join standorte s on up.vfl_id = s.vfl_id
union
-- provide UntMassn1 if no other untersuchungsmassnahme is available
select s.vfl_id, 'UntMassn1' as code_long, 'UM1' as ili_code, 20023 as ili_c_cli_id
from standorte s
    where s.vfl_id not in (select vfl_id from untersuchungsmassnahmen_pre_pm)
    ),

untersuchungsmassnahmen_xml_pm as (
select um.vfl_id,
        xmlelement(name "KbS_Basis_V1_4.UntersMassn_",
        xmlelement(name "value", um.code_long)
    ) as x_v14
from untersuchungsmassnahmen_pm um
),


untersuchungsmassnahmen_pre_vfl as (
select massn.*
from (
      select tm.code_long, tm.ili_code, tm.ili_c_cli_id, v.vfl_id from altlast_ili.task_mapping_v tm join altlast.vflz v on v.c_vflz_unterstand = tm.a4w_code
) massn
join standorte s on massn.vfl_id = s.vfl_id
),

untersuchungsmassnahmen_vfl as (
select
    s.vfl_id, up.code_long, up.ili_code, up.ili_c_cli_id
from untersuchungsmassnahmen_pre_vfl up
join standorte s on up.vfl_id = s.vfl_id
union
-- provide UntMassn1 if no other untersuchungsmassnahme is available
select s.vfl_id, 'UntMassn1' as code_long, 'UM1' as ili_code, 20023 as ili_c_cli_id
from standorte s
    where s.vfl_id not in (select vfl_id from untersuchungsmassnahmen_pre_vfl)
    ),

untersuchungsmassnahmen_xml_vfl as (
select um.vfl_id,
        xmlelement(name "KbS_Basis_V1_4.UntersMassn_",
        xmlelement(name "value", um.code_long)
    ) as x_v14
from untersuchungsmassnahmen_vfl um
),


untersuchungsmassnahmen_pre_vflz as (
select massn.*
from (
      select tm.code_long, tm.ili_code, tm.ili_c_cli_id, v.vfl_id, v.vflz_id from altlast_ili.task_mapping_v tm join altlast.vflz v on v.c_vflz_unterstand = tm.a4w_code
) massn
join standorte s on massn.vflz_id = s.vflz_id
),

untersuchungsmassnahmen_vflz as (
select
    s.vflz_id, s.vfl_id, up.code_long, up.ili_code, up.ili_c_cli_id
from untersuchungsmassnahmen_pre_vflz up
join standorte s on up.vflz_id = s.vflz_id
union
-- provide UntMassn1 if no other untersuchungsmassnahme is available
select s.vflz_id, s.vfl_id, 'UntMassn1' as code_long, 'UM1' as ili_code, 20023 as ili_c_cli_id
from standorte s
    where s.vflz_id not in (select vflz_id from untersuchungsmassnahmen_pre_vflz)
    ),



untersuchungsmassnahmen_xml_vflz as (
select um.vflz_id,
        xmlelement(name "KbS_Basis_V1_4.UntersMassn_",
        xmlelement(name "value", um.code_long)
    ) as x_v14
from untersuchungsmassnahmen_vflz um
),


-- sites in xml form

standorte_xml_v14_lv03 as (
    select xmlelement(name "KbS_LV03_V1_4.Belastete_Standorte.Belasteter_Standort",
          xmlattributes(standorte.stao_tid as "TID"),
          xmlelement(name "Katasternummer", standorte.vflz_combined_id_kt),
          xmlelement(name "URL_Standort", geoportallinks.permalink_geoportal),
          case when standorte.wkb_geometry is not null then
              case when st_geometrytype(standorte.wkb_geometry) = 'ST_Point' then
                  xmlelement(name "Geo_Lage_Punkt", altlast_ili.geoig_geometry(ST_Transform((standorte.wkb_geometry), 21781)))
              else
                  xmlelement(name "Geo_Lage_Polygon", altlast_ili.geoig_geometry(ST_Transform((standorte.wkb_geometry), 21781)))
              end
          else
              xmlelement(name "Geo_Lage_Punkt", altlast_ili.geoig_geometry(ST_Transform((standorte.wkb_geometry), 21781)))
          end,
          case
               when exists(select vflz_id from parzellen_xml where parzellen_xml.vflz_id = standorte.vflz_id) then
                  xmlelement(name "Parzellenverweis",
                        (select xmlagg(x_v14) from parzellen_xml where parzellen_xml.vflz_id = standorte.vflz_id)
                  )
               else
                  xmlcomment('Parzellenverweis not available')
          end,
          case
               when standorte.egrid is not null then
                  xmlelement(name "EGRID", xmlelement(name "KbS_Basis_V1_4.EGRID_",
                        xmlelement(name "value", standorte.egrid)
                        )
                  )
                else
                    xmlcomment('EGRID not available')
          end, -- nicht bei BAV
          xmlelement(name "Standorttyp", standorte.staotyp),
          xmlelement(name "InBetrieb", standorte.inbetrieb),
          case
               when standorte.deponietyp is not null then
                  --  Nicht für BAV, da wir keine Ablagerungen „in Betrieb“ haben werden
                  xmlelement(name "Deponietyp", xmlelement(name "KbS_Basis_V1_4.Deponietyp_",
                        xmlelement(name "value", standorte.deponietyp)
                        )
                  )
                else
                    xmlcomment('Deponietyp not available')
          end,
          case
                when standorte.nachsorge is not null then
                    xmlelement(name "Nachsorge", standorte.nachsorge)
                else
                    xmlcomment('Nachsorge not available')
          end, -- Nicht bei BAV
          case 
                when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'Mapping_Untersuchungsmassnahmen') = 'alle nach Geschäften' then
                  xmlelement(name "Untersuchungsmassnahmen", (select xmlagg(x_v14) from untersuchungsmassnahmen_xml_pm where untersuchungsmassnahmen_xml_pm.vfl_id = standorte.vfl_id))
                when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'Mapping_Untersuchungsmassnahmen') = 'alle nach Standortversionen' then
                  xmlelement(name "Untersuchungsmassnahmen", (select xmlagg(x_v14) from untersuchungsmassnahmen_xml_vfl where untersuchungsmassnahmen_xml_vfl.vfl_id = standorte.vfl_id))
                when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'Mapping_Untersuchungsmassnahmen') = 'aktuellste' then
                  xmlelement(name "Untersuchungsmassnahmen", (select xmlagg(x_v14) from untersuchungsmassnahmen_xml_vflz where untersuchungsmassnahmen_xml_vflz.vflz_id = standorte.vflz_id))
                else 
                  xmlelement(name "Untersuchungsmassnahmen", (select xmlagg(x_v14) from untersuchungsmassnahmen_xml_vflz where untersuchungsmassnahmen_xml_vflz.vflz_id = standorte.vflz_id))
          end,
          xmlelement(name "StatusAltlV", standorte.statusaltlv),
          xmlelement(name "Ersteintrag", standorte.date_ersteintrag::date),
          xmlelement(name "LetzteAnpassung", standorte.date_letzteanpassung::date),
          xmlelement(name "URL_KbS_Auszug", standorte.url_kbs_datasheet),
          /*
          case
                when standorte.standort_bemerkungen != '' then
                    xmlelement(name "Bemerkung", altlast_ili.geoig_localisedmtext(coalesce(standorte.standort_bemerkungen,''), 'de'))
                else
                    */
                    xmlcomment('Bemerkung not available')
          /*end*/,
          xmlelement(name "ZustaendigkeitKataster",
            xmlattributes(
                standorte.zb_tid as "REF"
            )
          )
      ) as x
    from standorte
    join geoportallinks on geoportallinks.vflz_id = standorte.vflz_id
    order by standorte.stao_tid
),


standorte_xml_v14_lv95 as (
    select xmlelement(name "KbS_LV95_V1_4.Belastete_Standorte.Belasteter_Standort",
          xmlattributes(standorte.stao_tid as "TID"),
          xmlelement(name "Katasternummer", standorte.vflz_combined_id_kt),
          xmlelement(name "URL_Standort", geoportallinks.permalink_geoportal),
          case when standorte.wkb_geometry is not null then
              case when st_geometrytype(standorte.wkb_geometry) = 'ST_Point' then
                  xmlelement(name "Geo_Lage_Punkt", altlast_ili.geoig_geometry(ST_Transform((standorte.wkb_geometry), 2056)))
              else
                  xmlelement(name "Geo_Lage_Polygon", altlast_ili.geoig_geometry(ST_Transform((standorte.wkb_geometry), 2056)))
              end
          else
              xmlelement(name "Geo_Lage_Punkt", altlast_ili.geoig_geometry(ST_Transform((standorte.wkb_geometry), 2056)))
          end,
         case
               when exists(select vflz_id from parzellen_xml where parzellen_xml.vflz_id = standorte.vflz_id) then
                  xmlelement(name "Parzellenverweis",
                        (select xmlagg(x_v14) from parzellen_xml where parzellen_xml.vflz_id = standorte.vflz_id)
                  )
               else
                  xmlcomment('Parzellenverweis not available')
          end,
          case
               when standorte.egrid is not null then
                  xmlelement(name "EGRID", xmlelement(name "KbS_Basis_V1_4.EGRID_",
                        xmlelement(name "value", standorte.egrid)
                        )
                  )
                else
                    xmlcomment('EGRID not available')
          end, -- nicht bei BAV
          xmlelement(name "Standorttyp", standorte.staotyp),
          xmlelement(name "InBetrieb", standorte.inbetrieb),
          case
               when standorte.deponietyp is not null then
                  --  Nicht für BAV, da wir keine Ablagerungen „in Betrieb“ haben werden
                  xmlelement(name "Deponietyp", xmlelement(name "KbS_Basis_V1_4.Deponietyp_",
                        xmlelement(name "value", standorte.deponietyp)
                        )
                  )
                else
                    xmlcomment('Deponietyp not available')
          end,
          case
                when standorte.nachsorge is not null then
                    xmlelement(name "Nachsorge", standorte.nachsorge)
                else
                    xmlcomment('Nachsorge not available')
          end, -- Nicht bei BAV
          case 
                when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'Mapping_Untersuchungsmassnahmen') = 'alle nach Geschäften' then
                  xmlelement(name "Untersuchungsmassnahmen", (select xmlagg(x_v14) from untersuchungsmassnahmen_xml_pm where untersuchungsmassnahmen_xml_pm.vfl_id = standorte.vfl_id))
                when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'Mapping_Untersuchungsmassnahmen') = 'alle nach Standortversionen' then
                  xmlelement(name "Untersuchungsmassnahmen", (select xmlagg(x_v14) from untersuchungsmassnahmen_xml_vfl where untersuchungsmassnahmen_xml_vfl.vfl_id = standorte.vfl_id))
                when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'Mapping_Untersuchungsmassnahmen') = 'aktuellste' then
                  xmlelement(name "Untersuchungsmassnahmen", (select xmlagg(x_v14) from untersuchungsmassnahmen_xml_vflz where untersuchungsmassnahmen_xml_vflz.vflz_id = standorte.vflz_id))
                else 
                  xmlelement(name "Untersuchungsmassnahmen", (select xmlagg(x_v14) from untersuchungsmassnahmen_xml_vflz where untersuchungsmassnahmen_xml_vflz.vflz_id = standorte.vflz_id))
          end,
          xmlelement(name "StatusAltlV", standorte.statusaltlv),
          xmlelement(name "Ersteintrag", standorte.date_ersteintrag::date),
          xmlelement(name "LetzteAnpassung", standorte.date_letzteanpassung::date),
          xmlelement(name "URL_KbS_Auszug", standorte.url_kbs_datasheet),
          /*
          case
                when standorte.standort_bemerkungen != '' then
                    xmlelement(name "Bemerkung", altlast_ili.geoig_localisedmtext(coalesce(standorte.standort_bemerkungen,''), 'de'))
                else
                    */
                    xmlcomment('Bemerkung not available')
          /*end*/,
          xmlelement(name "ZustaendigkeitKataster",
            xmlattributes(
                standorte.zb_tid as "REF"
            )
          )
      ) as x
    from standorte
    join geoportallinks on geoportallinks.vflz_id = standorte.vflz_id
    order by standorte.stao_tid
),


-- org
zustaendige_behoerde as (
select distinct
        'zb'||org.org_id::text as zb_tid, /* this id also gets build in the standorte with-clause*/
        case when org.org_id = 310 then org.bezeichnung_lang 
            else (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'Behoerde_Amt') 
            end as behoerde,
        case when org.org_id = 310 then org.url_behoerde 
            else (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_Behoerde_Amt') 
            end as url_behoerde,
        case when org.org_id = 310 then null
            else (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'UID_Behoerde_Amt') 
            end as uid,
        coalesce(org.katastername, org.bezeichnung)::text as katastername,
        (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_Standort_Kataster')::text as url_webgis,
        org.org_id
     from altlast.org
       /* only load orgs which are referenced from sites*/
     where org.org_id in (select org_id from standorte)
),

-- org as xml
zustaendige_behoerde_xml as (
    select 
    xmlelement(name "KbS_LV03_V1_4.Belastete_Standorte.ZustaendigkeitKataster",
      xmlattributes(zustaendige_behoerde.zb_tid as "TID"),
      xmlelement(name "Zustaendige_Behoerde", altlast_ili.geoig_localisedtext_t(zustaendige_behoerde.behoerde, 
        array['de',
            case when (select org.kuerzel from altlast_admin.setitem join altlast_admin.setting using (setitem_id) join altlast.org on org.org_id=setting.value::int where key= 'org') = 'GR' 
                then 'rm' 
            else 'fr' end,
            'it'
        ])),
      xmlelement(name "URL_Behoerde", zustaendige_behoerde.url_behoerde),
      xmlelement(name "UID", zustaendige_behoerde.uid),
      xmlelement(name "Katastername",
           altlast_ili.geoig_localisedtext_t(zustaendige_behoerde.katastername, 
                array['de',
                    case when (select org.kuerzel from altlast_admin.setitem join altlast_admin.setting using (setitem_id) join altlast.org on org.org_id=setting.value::int where key= 'org') = 'GR' 
                        then 'rm' 
                    else 'fr' end,
                    'it'
                ])
      ),
      xmlelement(name "URL_Kataster", zustaendige_behoerde.url_webgis)
    ) as x_v14_lv03,
    xmlelement(name "KbS_LV95_V1_4.Belastete_Standorte.ZustaendigkeitKataster",
      xmlattributes(zustaendige_behoerde.zb_tid as "TID"),
      xmlelement(name "Zustaendige_Behoerde", altlast_ili.geoig_localisedtext_t(zustaendige_behoerde.behoerde, 
        array['de',
            case when (select org.kuerzel from altlast_admin.setitem join altlast_admin.setting using (setitem_id) join altlast.org on org.org_id=setting.value::int where key= 'org') = 'GR' 
                then 'rm' 
            else 'fr' end,
            'it'
        ])),
      xmlelement(name "URL_Behoerde", zustaendige_behoerde.url_behoerde),
      xmlelement(name "UID", zustaendige_behoerde.uid),
      xmlelement(name "Katastername",
            altlast_ili.geoig_localisedtext_t(zustaendige_behoerde.katastername, 
            array['de',
                    case when (select org.kuerzel from altlast_admin.setitem join altlast_admin.setting using (setitem_id) join altlast.org on org.org_id=setting.value::int where key= 'org') = 'GR' 
                        then 'rm' 
                    else 'fr' end,
                    'it'
                ])
      ),
      xmlelement(name "URL_Kataster", zustaendige_behoerde.url_webgis)
    ) as x_v14_lv95
    from zustaendige_behoerde
)

-- assembling of the finished xml document according to the interlis schema
select xmlelement(name "TRANSFER", xmlattributes('http://www.interlis.ch/INTERLIS2.3' as xmlns),
    xmlelement(name "HEADERSECTION",
        xmlattributes('altlast4web' as "SENDER", '2.3' as "VERSION"),
          xmlelement(name "MODELS", -- need to add all used models by hand
              xmlelement(name "MODEL",xmlattributes('CoordSys' as "NAME",'2015-11-24' as "VERSION",'https://www.interlis.ch/models' as "URI")),
              xmlelement(name "MODEL",xmlattributes('InternationalCodes_V1' as "NAME",'2011-08-30' as "VERSION",'https://www.geo.admin.ch' as "URI")),
        xmlelement(name "MODEL",xmlattributes('Localisation_V1' as "NAME",'2011-08-30' as "VERSION",'https://www.geo.admin.ch' as "URI")),
              xmlelement(name "MODEL",xmlattributes('LocalisationCH_V1' as "NAME",'2011-08-30' as "VERSION",'https://www.geo.admin.ch' as "URI")),
              xmlelement(name "MODEL", xmlattributes('Dictionaries_V1' as "NAME",'2011-08-30' as "VERSION",'https://www.geo.admin.ch' as "URI")),
              xmlelement(name "MODEL",xmlattributes('DictionariesCH_V1' as "NAME",'2011-08-30' as "VERSION",'https://www.geo.admin.ch' as "URI")),
              xmlelement(name "MODEL",xmlattributes('Units' as "NAME",'2012-02-20' as "VERSION",'https://www.interlis.ch/models' as "URI")),
              xmlelement(name "MODEL",xmlattributes('GeometryCHLV03_V1' as "NAME",'2015-11-12' as "VERSION",'https://www.geo.admin.ch' as "URI")),
              xmlelement(name "MODEL",xmlattributes('GeometryCHLV95_V1' as "NAME",'2015-11-12' as "VERSION",'https://www.geo.admin.ch' as "URI")),
              xmlelement(name "MODEL",xmlattributes('KbS_Basis_V1_4' as "NAME",'2018-06-13' as "VERSION",'https://models.geo.admin.ch/BAFU' as "URI")),
              xmlelement(name "MODEL",xmlattributes('KbS_LV03_V1_4' as "NAME",'2018-06-13' as "VERSION",'https://models.geo.admin.ch/BAFU' as "URI")),
              xmlelement(name "MODEL",xmlattributes('KbS_LV95_V1_4' as "NAME",'2018-06-13' as "VERSION",'https://models.geo.admin.ch/BAFU' as "URI"))
          )
    ),
         
   case when $2 = 'v14_lv03' then
       xmlelement(name "DATASECTION",
      xmlelement(name "KbS_LV03_V1_4.Belastete_Standorte", -- there is no attribute that could server as a bucket-identifier. so we generate an artiffical one.
    xmlattributes((select bid from bidprops) as "BID"),
        ( select xmlagg(x_v14_lv03) from zustaendige_behoerde_xml),
        ( select xmlagg(x) from standorte_xml_v14_lv03)
      )
        )
   end,
   
   case when $2 = 'v14_lv95' then
       xmlelement(name "DATASECTION",
           xmlelement(name "KbS_LV95_V1_4.Belastete_Standorte",-- there is no attribute that could server as a bucket-identifier. so we generate an artiffical one.
    xmlattributes((select bid from bidprops) as "BID"),
        ( select xmlagg(x_v14_lv95) from zustaendige_behoerde_xml),
        ( select xmlagg(x) from standorte_xml_v14_lv95)
           )
        )
   end
);

$_$;


--
-- Name: export_geoig_v15(integer[]); Type: FUNCTION; Schema: altlast_ili; Owner: -
--

CREATE FUNCTION altlast_ili.export_geoig_v15(p_vflz_ids integer[]) RETURNS xml
    LANGUAGE sql
    AS $_$


-- all sites of the list of vflz_ids
with bidprops as (
    select 
        'kbsMGDM' || org.kuerzel as bid
    from altlast_admin.setitem
    join altlast_admin.setting using (setitem_id)
    join altlast.org on org.org_id::text=setting.value
    where key = 'org'
),

wmsprops as (
    select 
      case when (select value as url_geoportal from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_Standort') is not null then 
        (select value as url_geoportal from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_Standort')
      else null end as url_geoportal
),


-- all sites of the list of vflz_ids
standorte as (
    select 'stao'||v.vflz_id::text as stao_tid,
        v.vflz_id,
        v.vfl_id,
        v.vflz_combined_id_kt,
        vflgeo.wkb_geometry,
        vflnr.org_id,
        'zb'||vflnr.org_id::text as zb_tid,
        bem_standort.bem as standort_bemerkungen,
        case when v.x_koordinate is not null and v.y_koordinate is not null then st_makepoint(v.x_koordinate, v.y_koordinate) else null end as wkb_point,
        staotyp_mapping.code_long as staotyp,
        v.c_vflz_deponietyp::text as deponietyp,
        case when v.c_vflz_nachsorge = '01' then true::text else false::text end as nachsorge, 
        null::text as egrid,
        v.dat_rechtskraft::date as date_ersteintrag,
        (   -- legally binding date
            SELECT vflz_is_published_v.dat_latest_published::text AS dat_latest_published
               FROM altlast.vflz_is_published_v
               WHERE (vflz_is_published_v.vflz_id IN ( SELECT vflz_any_in_vfl.vflz_id
                                    FROM altlast.vflz vflz_any_in_vfl
                                    WHERE vflz_any_in_vfl.vfl_id = v.vfl_id)
                    ) AND vflz_is_published_v.is_latest_published
        )::date as date_letzteanpassung,
        statusaltlv_mapping.code_long as statusaltlv,
        case when v.c_vflz_inbetrieb = '01' then true::text else false::text end as inbetrieb, 
        case when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_KbS_Auszug') is not null then
          (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_KbS_Auszug') 
          || (regexp_replace(vfilename.filename::text, ' '::text, '%20'::text, 'g'::text))
          else null end as url_kbs_datasheet
    from altlast.vflz v
    join altlast.vflz_is_published_v vip on v.vflz_id = vip.vflz_id and vip.is_latest_published /* only published versions */
    join altlast_ili.cod_mapping_v staotyp_mapping on staotyp_mapping.c_cli_id = v.h_vflz_vftyp
                and staotyp_mapping.code = v.c_vflz_vftyp
    join altlast.bere_v on bere_v.vflz_id = v.vflz_id and bere_v.kbs
    join altlast_ili.cod_mapping_v statusaltlv_mapping on statusaltlv_mapping.c_cli_id = bere_v.h_bere_res_abwbewe
                and statusaltlv_mapping.code = bere_v.c_bere_res_abwbewe
    join altlast.vflnr on v.vflz_id = vflnr.vflz_id and vflnr.aktiv

    -- restrict using the ord configured in a4w
    join altlast_admin.setting stng on stng.value = vflnr.org_id::text
    join altlast_admin.setitem sit on sit.setitem_id = stng.setitem_id and sit.key in ('org', 'astra')

    left  join altlast.vflgeo on vflgeo.vflz_id = v.vflz_id
    left join altlast.bemgrp bemg_standort on bemg_standort.public and bemg_standort.bemgrp='standort'
    left join altlast.bem bem_standort on bem_standort.bemgrp_id = bemg_standort.bemgrp_id and
                bem_standort.key_value = v.vflz_id and bem_standort.public

    left join altlast.vflz_filename_v vfilename on vfilename.vflz_id = v.vflz_id

    where v.vfl_id in (
        select vfl_id from altlast.vflz where vflz_id = any($1)
    )
    order by v.vflz_id
),

geoportallinks as (
    select
        standorte.vflz_id,
        case when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_Standort_Indikator') = 'standortnummer' then
          wmsprops.url_geoportal || (regexp_replace(standorte.vflz_combined_id_kt::text, ' '::text, '%20'::text, 'g'::text))
        when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_Standort_Indikator') = 'xy_koordinates' then
           wmsprops.url_geoportal || '&Y=' || st_x(standorte.wkb_point)::text || '&X=' || st_y(standorte.wkb_point)::text
        when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_Standort_Indikator') = 'map_x_map_y_koordinates' then
           wmsprops.url_geoportal || '&map_x=' || st_x(standorte.wkb_point)::text || '&map_y=' || st_y(standorte.wkb_point)::text
        when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_Standort_Indikator') = 'c_koordinates' then
           wmsprops.url_geoportal || '&c=' || st_y(standorte.wkb_point)::text || ',' || st_x(standorte.wkb_point)::text 
        when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_Standort_Indikator') = 'ne_koordinates' then
           wmsprops.url_geoportal || '&E=' || st_x(standorte.wkb_point)::text || '&N=' || st_y(standorte.wkb_point)::text
        else wmsprops.url_geoportal 
        end as permalink_geoportal
    from standorte, wmsprops
),


-- parcels for all returned sites
parzellen as (
  select 
    org || bfsnr as nbident, vflz_id, parzelle 
  from (select 
      vpmv.h_gem_id as bfsnr,  /* Der NBIdent  (Nummerierungsbereichidentifikator) setzt sich zusammen
               aus dem Kt (Kantonskürzel) und der NBNummer  (Nummerierungsbereichnummer). */
      (select org.kuerzel from altlast_admin.setitem join altlast_admin.setting using (setitem_id) join altlast.org on org.org_id=setting.value::int where key= 'org') as org,
      vpmv.vflz_id as vflz_id,
      vpmv.gb_nummer as parzelle,
      case when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'Parzellenverweiss') = 'Ja' then true
      else false /* never return any parcels as we can never returned the required nbident number */
      end as parzellenverweiss
        from altlast.vflz_parzellen_materialization_v vpmv
        group by vpmv.h_gem_id, vpmv.vflz_id, vpmv.gb_nummer)foo
  where foo.vflz_id in (select vflz_id from standorte) and foo.parzellenverweiss
  order by bfsnr, parzelle
),

-- parcels in xml form
parzellen_xml as (
select parzellen.vflz_id,
        xmlelement(name "KbS_V1_5.Parzellenidentifikation",
        xmlelement(name "NBIdent", parzellen.nbident),
        xmlelement(name "Parzellennummer", parzellen.parzelle)
    ) as x_v15
from parzellen
order by parzellen.parzelle
),

untersuchungsmassnahmen_pre_pm as (
select massn.*
from (
      select tm.code_long, tm.ili_code, tm.ili_c_cli_id, pv.vfl_id from altlast_ili.task_mapping_v tm 
        join altlast.pm_cache_v pc on pc.pro_uid = tm.pro_uid and pc.status = 'CLOSED' and case when tm.tas_uid is null then true else tm.tas_uid = pc.tas_uid end
        join altlast.pm_vfl pv on pv.pm_vfl_id = pc.pm_vfl_id
) massn
join standorte s on massn.vfl_id = s.vfl_id
),

untersuchungsmassnahmen_pm as (
select
    s.vfl_id, up.code_long, up.ili_code, up.ili_c_cli_id
from untersuchungsmassnahmen_pre_pm up
join standorte s on up.vfl_id = s.vfl_id
union
-- provide UntMassn1 if no other untersuchungsmassnahme is available
select s.vfl_id, 'UntMassn1' as code_long, 'UM1' as ili_code, 20023 as ili_c_cli_id
from standorte s
    where s.vfl_id not in (select vfl_id from untersuchungsmassnahmen_pre_pm)
    ),

untersuchungsmassnahmen_xml_pm as (
select um.vfl_id,
        xmlelement(name "KbS_V1_5.UntersMassn_",
        xmlelement(name "value", um.code_long)
    ) as x_v15
from untersuchungsmassnahmen_pm um
),


untersuchungsmassnahmen_pre_vfl as (
select massn.*
from (
      select tm.code_long, tm.ili_code, tm.ili_c_cli_id, v.vfl_id from altlast_ili.task_mapping_v tm join altlast.vflz v on v.c_vflz_unterstand = tm.a4w_code
) massn
join standorte s on massn.vfl_id = s.vfl_id
),

untersuchungsmassnahmen_vfl as (
select
    s.vfl_id, up.code_long, up.ili_code, up.ili_c_cli_id
from untersuchungsmassnahmen_pre_vfl up
join standorte s on up.vfl_id = s.vfl_id
union
-- provide UntMassn1 if no other untersuchungsmassnahme is available
select s.vfl_id, 'UntMassn1' as code_long, 'UM1' as ili_code, 20023 as ili_c_cli_id
from standorte s
    where s.vfl_id not in (select vfl_id from untersuchungsmassnahmen_pre_vfl)
    ),

untersuchungsmassnahmen_xml_vfl as (
select um.vfl_id,
        xmlelement(name "KbS_V1_5.UntersMassn_",
        xmlelement(name "value", um.code_long)
    ) as x_v15
from untersuchungsmassnahmen_vfl um
),


untersuchungsmassnahmen_pre_vflz as (
select massn.*
from (
      select tm.code_long, tm.ili_code, tm.ili_c_cli_id, v.vfl_id, v.vflz_id from altlast_ili.task_mapping_v tm join altlast.vflz v on v.c_vflz_unterstand = tm.a4w_code
) massn
join standorte s on massn.vflz_id = s.vflz_id
),

untersuchungsmassnahmen_vflz as (
select
    s.vflz_id, s.vfl_id, up.code_long, up.ili_code, up.ili_c_cli_id
from untersuchungsmassnahmen_pre_vflz up
join standorte s on up.vflz_id = s.vflz_id
union
-- provide UntMassn1 if no other untersuchungsmassnahme is available
select s.vflz_id, s.vfl_id, 'UntMassn1' as code_long, 'UM1' as ili_code, 20023 as ili_c_cli_id
from standorte s
    where s.vflz_id not in (select vflz_id from untersuchungsmassnahmen_pre_vflz)
    ),



untersuchungsmassnahmen_xml_vflz as (
select um.vflz_id,
        xmlelement(name "KbS_V1_5.UntersMassn_",
        xmlelement(name "value", um.code_long)
    ) as x_v15
from untersuchungsmassnahmen_vflz um
),


-- sites in xml form

standorte_xml_v15 as (
    select xmlelement(name "KbS_V1_5.Belastete_Standorte.Belasteter_Standort",
          xmlattributes(standorte.stao_tid as "TID"),
          xmlelement(name "Katasternummer", standorte.vflz_combined_id_kt),
          case when geoportallinks.permalink_geoportal is not null then
            xmlelement(name "URL_Standort", 
                xmlelement(name "KbS_V1_5.Belastete_Standorte.MultilingualUri",
                    xmlelement(name "LocalisedText",
                        xmlelement(name "KbS_V1_5.Belastete_Standorte.LocalisedUri",
                            xmlelement(name "Language", 'de'),
                            xmlelement(name "Text", concat(geoportallinks.permalink_geoportal, '&lang=de'))
                        ), 
                        xmlelement(name "KbS_V1_5.Belastete_Standorte.LocalisedUri",   
                            case when (select org.kuerzel from altlast_admin.setitem join altlast_admin.setting using (setitem_id) join altlast.org on org.org_id=setting.value::int where key= 'org') = 'GR' 
                                then xmlelement(name "Language", 'rm')
                                else xmlelement(name "Language", 'fr') end,
                            case when (select org.kuerzel from altlast_admin.setitem join altlast_admin.setting using (setitem_id) join altlast.org on org.org_id=setting.value::int where key= 'org') = 'GR' 
                                     then xmlelement(name "Text", concat(geoportallinks.permalink_geoportal, '&lang=rm'))
                                    else xmlelement(name "Text", concat(geoportallinks.permalink_geoportal, '&lang=fr')) end
                        ),
                        xmlelement(name "KbS_V1_5.Belastete_Standorte.LocalisedUri",
                            xmlelement(name "Language", 'it'),
                            xmlelement(name "Text", concat(geoportallinks.permalink_geoportal, '&lang=it'))
                        )
                    )
                )
            )
          else 
            xmlelement(name "URL_Standort", geoportallinks.permalink_geoportal)
          end,
          case when standorte.wkb_geometry is not null then
              case when st_geometrytype(standorte.wkb_geometry) = 'ST_Point' then
                  xmlelement(name "Geo_Lage_Punkt", altlast_ili.geoig_v1_5_geometry(ST_Transform((standorte.wkb_geometry), 2056)))
              else
                  xmlelement(name "Geo_Lage_Polygon", altlast_ili.geoig_v1_5_geometry(ST_Transform((standorte.wkb_geometry), 2056)))
              end
          else
              xmlelement(name "Geo_Lage_Punkt", altlast_ili.geoig_v1_5_geometry(ST_Transform((standorte.wkb_geometry), 2056)))
          end,
         case
               when exists(select vflz_id from parzellen_xml where parzellen_xml.vflz_id = standorte.vflz_id) then
                  xmlelement(name "Parzellenverweis",
                        (select xmlagg(x_v15) from parzellen_xml where parzellen_xml.vflz_id = standorte.vflz_id)
                  )
               else
                  xmlcomment('Parzellenverweis not available')
          end,
          case
               when standorte.egrid is not null then
                  xmlelement(name "EGRID", xmlelement(name "KbS_V1_5.EGRID_",
                        xmlelement(name "value", standorte.egrid)
                        )
                  )
                else
                    xmlcomment('EGRID not available')
          end, -- nicht bei BAV
          xmlelement(name "Standorttyp", standorte.staotyp),
          xmlelement(name "InBetrieb", standorte.inbetrieb),
          case
               when standorte.deponietyp is not null then
                  --  Nicht für BAV, da wir keine Ablagerungen „in Betrieb“ haben werden
                  xmlelement(name "Deponietyp", xmlelement(name "KbS_V1_5.Deponietyp_",
                        xmlelement(name "value", standorte.deponietyp)
                        )
                  )
                else
                    xmlcomment('Deponietyp not available')
          end,
          case
                when standorte.nachsorge is not null then
                    xmlelement(name "Nachsorge", standorte.nachsorge)
                else
                    xmlcomment('Nachsorge not available')
          end, -- Nicht bei BAV
          case 
                when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'Mapping_Untersuchungsmassnahmen') = 'alle nach Geschäften' then
                  xmlelement(name "Untersuchungsmassnahmen", (select xmlagg(x_v15) from untersuchungsmassnahmen_xml_pm where untersuchungsmassnahmen_xml_pm.vfl_id = standorte.vfl_id))
                when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'Mapping_Untersuchungsmassnahmen') = 'alle nach Standortversionen' then
                  xmlelement(name "Untersuchungsmassnahmen", (select xmlagg(x_v15) from untersuchungsmassnahmen_xml_vfl where untersuchungsmassnahmen_xml_vfl.vfl_id = standorte.vfl_id))
                when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'Mapping_Untersuchungsmassnahmen') = 'aktuellste' then
                  xmlelement(name "Untersuchungsmassnahmen", (select xmlagg(x_v15) from untersuchungsmassnahmen_xml_vflz where untersuchungsmassnahmen_xml_vflz.vflz_id = standorte.vflz_id))
                else 
                  xmlelement(name "Untersuchungsmassnahmen", (select xmlagg(x_v15) from untersuchungsmassnahmen_xml_vflz where untersuchungsmassnahmen_xml_vflz.vflz_id = standorte.vflz_id))
          end,
          xmlelement(name "StatusAltlV", standorte.statusaltlv),
          xmlelement(name "Ersteintrag", standorte.date_ersteintrag::date),
          xmlelement(name "LetzteAnpassung", standorte.date_letzteanpassung::date),
          xmlelement(name "URL_KbS_Auszug",                                                                                                                                                               
             xmlelement(name "KbS_V1_5.Belastete_Standorte.MultilingualUri",                                                                                                                               
                 xmlelement(name "LocalisedText",                                                                                                                                                          
                     xmlelement(name "KbS_V1_5.Belastete_Standorte.LocalisedUri",                                                                                                                          
                         xmlelement(name "Language", 'de'),                                                                                                                                                
                         xmlelement(name "Text", standorte.url_kbs_datasheet)                                                                                                                              
                     ),                                                                                                                                                                                    
                     xmlelement(name "KbS_V1_5.Belastete_Standorte.LocalisedUri",                                                                                                                          
                         case when (select org.kuerzel from altlast_admin.setitem join altlast_admin.setting using (setitem_id) join altlast.org on org.org_id=setting.value::int where key= 'org') = 'GR' 
                             then xmlelement(name "Language", 'rm')                                                                                                                                        
                             else xmlelement(name "Language", 'fr') end,                                                                                                                                   
                     xmlelement(name "Text", standorte.url_kbs_datasheet)                                                                                                                                  
                     ),                                                                                                                                                                                   
                     xmlelement(name "KbS_V1_5.Belastete_Standorte.LocalisedUri",                                                                                                                          
                         xmlelement(name "Language", 'it'),                                                                                                                                               
                         xmlelement(name "Text", standorte.url_kbs_datasheet)                                                                                                                              
                     )                                                                                                                                                                                     
                 )                                                                                                                                                                                        
             )                                                                                                                                                                                            
           ),   
          /*
          case
                when standorte.standort_bemerkungen != '' then
                    xmlelement(name "Bemerkung", altlast_ili.geoig_localisedmtext(coalesce(standorte.standort_bemerkungen,''), 'de'))
                else
                    */
                    xmlcomment('Bemerkung not available')
          /*end*/,
          xmlelement(name "ZustaendigkeitKataster",
            xmlattributes(
                standorte.zb_tid as "REF"
            )
          )
      ) as x
    from standorte
    join geoportallinks on geoportallinks.vflz_id = standorte.vflz_id
    order by standorte.stao_tid
),


-- org
zustaendige_behoerde as (
select distinct
        'zb'||org.org_id::text as zb_tid, /* this id also gets build in the standorte with-clause*/
        case when org.org_id = 310 then org.bezeichnung_lang 
            else (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'Behoerde_Amt') 
            end as behoerde,
        (select case 
            when org.org_id = 310 then (select url_behoerde from altlast.org where org_id = 310)
            else (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_Behoerde_Amt')
        end as url_behoerde) as url_behoerde_de,
        (select case 
            when org.org_id = 310 then (select url_behoerde from altlast.org where org_id = 310)
            else (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_Behoerde_Amt_fr')
        end as url_behoerde) as url_behoerde_fr,
        (select case 
            when org.org_id = 310 then (select url_behoerde from altlast.org where org_id = 310)
            else (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_Behoerde_Amt_it')
        end as url_behoerde) as url_behoerde_it,
        (select case 
            when org.org_id = 310 then (select url_behoerde from altlast.org where org_id = 310)
            else (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_Behoerde_Amt_fr')
        end as url_behoerde) as url_behoerde_rm,
        case when org.org_id = 310 then null
            else (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'UID_Behoerde_Amt') 
            end as uid,
        coalesce(org.katastername, org.bezeichnung)::text as katastername,
        (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_Standort_Kataster')::text as url_webgis,
        org.org_id
     from altlast.org
       /* only load orgs which are referenced from sites*/
     where org.org_id in (select org_id from standorte)
),

-- org as xml
zustaendige_behoerde_xml as (
    select 
    xmlelement(name "KbS_V1_5.Belastete_Standorte.ZustaendigkeitKataster",
      xmlattributes(zustaendige_behoerde.zb_tid as "TID"),
      xmlelement(name "Zustaendige_Behoerde", altlast_ili.geoig_localisedtext_t(zustaendige_behoerde.behoerde, 
        array['de',
            case when (select org.kuerzel from altlast_admin.setitem join altlast_admin.setting using (setitem_id) join altlast.org on org.org_id=setting.value::int where key= 'org') = 'GR' 
                then 'rm' 
            else 'fr' end,
            'it'
        ])),

      xmlelement(name "URL_Behoerde",                                                                                                                                                                     
             xmlelement(name "KbS_V1_5.Belastete_Standorte.MultilingualUri",                                                                                                                               
                 xmlelement(name "LocalisedText",                                                                                                                                                         
                     xmlelement(name "KbS_V1_5.Belastete_Standorte.LocalisedUri",                                                                                                                         
                         xmlelement(name "Language", 'de'),                                                                                                                                               
                         xmlelement(name "Text", zustaendige_behoerde.url_behoerde_de)                                                                                                                    
                     ),                                                                                                                                                                                   
                     xmlelement(name "KbS_V1_5.Belastete_Standorte.LocalisedUri",                                                                                                                         
                         case when (select org.kuerzel from altlast_admin.setitem join altlast_admin.setting using (setitem_id) join altlast.org on org.org_id=setting.value::int where key= 'org')= 'GR' 
                             then xmlelement(name "Language", 'rm')                                                                                                                                       
                             else xmlelement(name "Language", 'fr') end,                                                                                                                                  
                         xmlelement(name "Text", zustaendige_behoerde.url_behoerde_fr)                                                                                                                    
                     ),                                                                                                                                                                                   
                     xmlelement(name "KbS_V1_5.Belastete_Standorte.LocalisedUri",                                                                                                                         
                         xmlelement(name "Language", 'it'),                                                                                                                                               
                         xmlelement(name "Text", zustaendige_behoerde.url_behoerde_it)                                                                                                                    
                     )                                                                                                                                                                                    
                 )                                                                                                                                                                                        
             )                                                                                                                                                                                            
         ), 

      xmlelement(name "UID", zustaendige_behoerde.uid),
      xmlelement(name "Katastername",
            altlast_ili.geoig_localisedtext_t(zustaendige_behoerde.katastername, 
            array['de',
                    case when (select org.kuerzel from altlast_admin.setitem join altlast_admin.setting using (setitem_id) join altlast.org on org.org_id=setting.value::int where key= 'org') = 'GR' 
                        then 'rm' 
                    else 'fr' end,
                    'it'
                ])
      ),

      xmlelement(name "URL_Kataster",                                                                                                                                                                     
             xmlelement(name "KbS_V1_5.Belastete_Standorte.MultilingualUri",                                                                                                                               
                 xmlelement(name "LocalisedText",                                                                                                                                                         
                     xmlelement(name "KbS_V1_5.Belastete_Standorte.LocalisedUri",                                                                                                                         
                         xmlelement(name "Language", 'de'),                                                                                                                                               
                         xmlelement(name "Text", concat(zustaendige_behoerde.url_webgis, '&lang=de'))                                                                                                     
                     ),                                                                                                                                                                                   
                     xmlelement(name "KbS_V1_5.Belastete_Standorte.LocalisedUri",                                                                                                                         
                         case when (select org.kuerzel from altlast_admin.setitem join altlast_admin.setting using (setitem_id) join altlast.org on org.org_id=setting.value::int where key= 'org')= 'GR' 
                             then xmlelement(name "Language", 'rm')                                                                                                                                       
                             else xmlelement(name "Language", 'fr') end,                                                                                                                                  
                         case when (select org.kuerzel from altlast_admin.setitem join altlast_admin.setting using (setitem_id) join altlast.org on org.org_id=setting.value::int where key= 'or') = 'GR' 
                                  then xmlelement(name "Text", concat(zustaendige_behoerde.url_webgis, '&lang=rm'))                                                                                       
                                 else xmlelement(name "Text", concat(zustaendige_behoerde.url_webgis, '&lang=fr')) end                                                                                    
                     ),                                                                                                                                                                                   
                     xmlelement(name "KbS_V1_5.Belastete_Standorte.LocalisedUri",                                                                                                                         
                         xmlelement(name "Language", 'it'),                                                                                                                                               
                         xmlelement(name "Text", concat(zustaendige_behoerde.url_webgis, '&lang=it'))                                                                                                     
                     )                                                                                                                                                                                    
                 )                                                                                                                                                                                        
             )                                                                                                                                                                                            
         )   


    ) as x_v15
    from zustaendige_behoerde
)

-- assembling of the finished xml document according to the interlis schema
select xmlelement(name "TRANSFER", xmlattributes('http://www.interlis.ch/INTERLIS2.3' as xmlns),
    xmlelement(name "HEADERSECTION",
        xmlattributes('altlast4web' as "SENDER", '2.3' as "VERSION"),
          xmlelement(name "MODELS", -- need to add all used models by hand
              xmlelement(name "MODEL",xmlattributes('CoordSys' as "NAME",'2015-11-24' as "VERSION",'https://www.interlis.ch/models' as "URI")),
              xmlelement(name "MODEL",xmlattributes('InternationalCodes_V1' as "NAME",'2011-08-30' as "VERSION",'https://www.geo.admin.ch' as "URI")),
              xmlelement(name "MODEL",xmlattributes('Localisation_V1' as "NAME",'2011-08-30' as "VERSION",'https://www.geo.admin.ch' as "URI")),
              xmlelement(name "MODEL",xmlattributes('LocalisationCH_V1' as "NAME",'2011-08-30' as "VERSION",'https://www.geo.admin.ch' as "URI")),
              xmlelement(name "MODEL",xmlattributes('Dictionaries_V1' as "NAME",'2011-08-30' as "VERSION",'https://www.geo.admin.ch' as "URI")),
              xmlelement(name "MODEL",xmlattributes('DictionariesCH_V1' as "NAME",'2011-08-30' as "VERSION",'https://www.geo.admin.ch' as "URI")),
              xmlelement(name "MODEL",xmlattributes('Units' as "NAME",'2012-02-20' as "VERSION",'https://www.interlis.ch/models' as "URI")),
              xmlelement(name "MODEL",xmlattributes('GeometryCHLV95_V1' as "NAME",'2015-11-12' as "VERSION",'https://www.geo.admin.ch' as "URI")),
              xmlelement(name "MODEL",xmlattributes('KbS_V1_5' as "NAME",'2021-10-15' as "VERSION",'https://models.geo.admin.ch/BAFU' as "URI"))
          )
    ),
   
    xmlelement(name "DATASECTION",
        xmlelement(name "KbS_V1_5.Belastete_Standorte",-- there is no attribute that could server as a bucket-identifier. so we generate an artiffical one.
            xmlattributes((select bid from bidprops) as "BID"),
                ( select xmlagg(x_v15) from zustaendige_behoerde_xml),
                ( select xmlagg(x) from standorte_xml_v15)
        )
    )

);

$_$;


--
-- Name: export_geoig_v15_bl(integer[]); Type: FUNCTION; Schema: altlast_ili; Owner: -
--

CREATE FUNCTION altlast_ili.export_geoig_v15_bl(p_vflz_ids integer[]) RETURNS xml
    LANGUAGE sql
    AS $_$


-- all sites of the list of vflz_ids
with bidprops as (
    select 
        'kbsMGDM' || org.kuerzel as bid
    from altlast_admin.setitem
    join altlast_admin.setting using (setitem_id)
    join altlast.org on org.org_id::text=setting.value
    where key = 'org'
),

wmsprops as (
    select 
      case when (select value as url_geoportal from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_Standort') is not null then 
        (select value as url_geoportal from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_Standort')
      else null end as url_geoportal
),


-- all sites of the list of vflz_ids
standorte as (
    select 'stao'||v.vflz_id::text as stao_tid,
        v.vflz_id,
        v.vfl_id,
        v.vflz_combined_id_kt,
        vflgeo.wkb_geometry,
        vflnr.org_id,
        'zb'||vflnr.org_id::text as zb_tid,
        bem_standort.bem as standort_bemerkungen,
        case when v.x_koordinate is not null and v.y_koordinate is not null then st_makepoint(v.x_koordinate, v.y_koordinate) else null end as wkb_point,
        staotyp_mapping.code_long as staotyp,
        v.c_vflz_deponietyp::text as deponietyp,
        case when v.c_vflz_nachsorge = '01' then true::text else false::text end as nachsorge, 
        null::text as egrid,
        v.dat_rechtskraft::date as date_ersteintrag,
        (   -- legally binding date
            SELECT vflz_is_published_v.dat_latest_published::text AS dat_latest_published
               FROM altlast.vflz_is_published_v
               WHERE (vflz_is_published_v.vflz_id IN ( SELECT vflz_any_in_vfl.vflz_id
                                    FROM altlast.vflz vflz_any_in_vfl
                                    WHERE vflz_any_in_vfl.vfl_id = v.vfl_id)
                    ) AND vflz_is_published_v.is_latest_published
        )::date as date_letzteanpassung,
        statusaltlv_mapping.code_long as statusaltlv,
        case when v.c_vflz_inbetrieb = '01' then true::text else false::text end as inbetrieb, 
        case when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_KbS_Auszug') is not null then
          (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_KbS_Auszug') 
          || (regexp_replace(vfilename.filename::text, ' '::text, '%20'::text, 'g'::text))
          else null end as url_kbs_datasheet,
          altlast.t(altlast.msgid_code(v.h_vflz_unterstand, v.c_vflz_unterstand), 'de') as untersuchungsstand,
        case 
          when v.zeitraum_von is null and v.zeitraum_bis is not null
            then 'unbekannt bis ' ||extract(year from v.zeitraum_bis)::text
          when v.zeitraum_von is not null and v.zeitraum_bis is null 
            then extract(year from v.zeitraum_von)::text || ' bis unbekannt'
          when v.zeitraum_von is not null and v.zeitraum_bis is not null and extract(year from v.zeitraum_von) = extract(year from v.zeitraum_bis)
            then extract(year from v.zeitraum_von)::text
          when v.zeitraum_von is not null and v.zeitraum_bis is not null
            then extract(year from v.zeitraum_von)::text || ' bis ' ||extract(year from v.zeitraum_bis)::text 
          else 'unbekannt'
        end as zeitraum
    from altlast.vflz v
    join altlast.vflz_is_published_v vip on v.vflz_id = vip.vflz_id and vip.is_latest_published /* only published versions */
    join altlast_ili.cod_mapping_v staotyp_mapping on staotyp_mapping.c_cli_id = v.h_vflz_vftyp
                and staotyp_mapping.code = v.c_vflz_vftyp
    join altlast.bere_v on bere_v.vflz_id = v.vflz_id and bere_v.kbs
    join altlast_ili.cod_mapping_v statusaltlv_mapping on statusaltlv_mapping.c_cli_id = bere_v.h_bere_res_abwbewe
                and statusaltlv_mapping.code = bere_v.c_bere_res_abwbewe
    join altlast.vflnr on v.vflz_id = vflnr.vflz_id and vflnr.aktiv

    -- restrict using the ord configured in a4w
    join altlast_admin.setting stng on stng.value = vflnr.org_id::text
    join altlast_admin.setitem sit on sit.setitem_id = stng.setitem_id and sit.key in ('org', 'astra')

    left  join altlast.vflgeo on vflgeo.vflz_id = v.vflz_id
    left join altlast.bemgrp bemg_standort on bemg_standort.public and bemg_standort.bemgrp='standort'
    left join altlast.bem bem_standort on bem_standort.bemgrp_id = bemg_standort.bemgrp_id and
                bem_standort.key_value = v.vflz_id and bem_standort.public

    left join altlast.vflz_filename_v vfilename on vfilename.vflz_id = v.vflz_id

    where v.vfl_id in (
        select vfl_id from altlast.vflz where vflz_id = any($1)
    )
    order by v.vflz_id
),

geoportallinks as (
    select
        standorte.vflz_id,
        case when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_Standort_Indikator') = 'standortnummer' then
          wmsprops.url_geoportal || (regexp_replace(standorte.vflz_combined_id_kt::text, ' '::text, '%20'::text, 'g'::text))
        when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_Standort_Indikator') = 'xy_koordinates' then
           wmsprops.url_geoportal || '&Y=' || st_x(standorte.wkb_point)::text || '&X=' || st_y(standorte.wkb_point)::text
        when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_Standort_Indikator') = 'map_x_map_y_koordinates' then
           wmsprops.url_geoportal || '&map_x=' || st_x(standorte.wkb_point)::text || '&map_y=' || st_y(standorte.wkb_point)::text
        when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_Standort_Indikator') = 'c_koordinates' then
           wmsprops.url_geoportal || '&c=' || st_y(standorte.wkb_point)::text || ',' || st_x(standorte.wkb_point)::text 
        else wmsprops.url_geoportal 
        end as permalink_geoportal
    from standorte, wmsprops
),


-- parcels for all returned sites
parzellen as (
  select 
    org || bfsnr as nbident, vflz_id, parzelle 
  from (select 
      vpmv.h_gem_id as bfsnr,  /* Der NBIdent  (Nummerierungsbereichidentifikator) setzt sich zusammen
               aus dem Kt (Kantonskürzel) und der NBNummer  (Nummerierungsbereichnummer). */
      (select org.kuerzel from altlast_admin.setitem join altlast_admin.setting using (setitem_id) join altlast.org on org.org_id=setting.value::int where key= 'org') as org,
      vpmv.vflz_id as vflz_id,
      vpmv.gb_nummer as parzelle,
      case when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'Parzellenverweiss') = 'Ja' then true
      else false /* never return any parcels as we can never returned the required nbident number */
      end as parzellenverweiss
        from altlast.vflz_parzellen_materialization_v vpmv
        group by vpmv.h_gem_id, vpmv.vflz_id, vpmv.gb_nummer)foo
  where foo.vflz_id in (select vflz_id from standorte) and foo.parzellenverweiss
  order by bfsnr, parzelle
),

-- parcels in xml form
parzellen_xml as (
select parzellen.vflz_id,
        xmlelement(name "KbS_V1_5.Parzellenidentifikation",
        xmlelement(name "NBIdent", parzellen.nbident),
        xmlelement(name "Parzellennummer", parzellen.parzelle)
    ) as x_v15
from parzellen
order by parzellen.parzelle
),

untersuchungsmassnahmen_pre_pm as (
select massn.*
from (
      select tm.code_long, tm.ili_code, tm.ili_c_cli_id, pv.vfl_id from altlast_ili.task_mapping_v tm 
        join altlast.pm_cache_v pc on pc.pro_uid = tm.pro_uid and pc.status = 'CLOSED' and case when tm.tas_uid is null then true else tm.tas_uid = pc.tas_uid end
        join altlast.pm_vfl pv on pv.pm_vfl_id = pc.pm_vfl_id
) massn
join standorte s on massn.vfl_id = s.vfl_id
),

untersuchungsmassnahmen_pm as (
select
    s.vfl_id, up.code_long, up.ili_code, up.ili_c_cli_id
from untersuchungsmassnahmen_pre_pm up
join standorte s on up.vfl_id = s.vfl_id
union
-- provide UntMassn1 if no other untersuchungsmassnahme is available
select s.vfl_id, 'UntMassn1' as code_long, 'UM1' as ili_code, 20023 as ili_c_cli_id
from standorte s
    where s.vfl_id not in (select vfl_id from untersuchungsmassnahmen_pre_pm)
    ),

untersuchungsmassnahmen_xml_pm as (
select um.vfl_id,
        xmlelement(name "KbS_V1_5.UntersMassn_",
        xmlelement(name "value", um.code_long)
    ) as x_v15
from untersuchungsmassnahmen_pm um
),


untersuchungsmassnahmen_pre_vfl as (
select massn.*
from (
      select tm.code_long, tm.ili_code, tm.ili_c_cli_id, v.vfl_id from altlast_ili.task_mapping_v tm join altlast.vflz v on v.c_vflz_unterstand = tm.a4w_code
) massn
join standorte s on massn.vfl_id = s.vfl_id
),

untersuchungsmassnahmen_vfl as (
select
    s.vfl_id, up.code_long, up.ili_code, up.ili_c_cli_id
from untersuchungsmassnahmen_pre_vfl up
join standorte s on up.vfl_id = s.vfl_id
union
-- provide UntMassn1 if no other untersuchungsmassnahme is available
select s.vfl_id, 'UntMassn1' as code_long, 'UM1' as ili_code, 20023 as ili_c_cli_id
from standorte s
    where s.vfl_id not in (select vfl_id from untersuchungsmassnahmen_pre_vfl)
    ),

untersuchungsmassnahmen_xml_vfl as (
select um.vfl_id,
        xmlelement(name "KbS_V1_5.UntersMassn_",
        xmlelement(name "value", um.code_long)
    ) as x_v15
from untersuchungsmassnahmen_vfl um
),


untersuchungsmassnahmen_pre_vflz as (
select massn.*
from (
      select tm.code_long, tm.ili_code, tm.ili_c_cli_id, v.vfl_id, v.vflz_id from altlast_ili.task_mapping_v tm join altlast.vflz v on v.c_vflz_unterstand = tm.a4w_code
) massn
join standorte s on massn.vflz_id = s.vflz_id
),

untersuchungsmassnahmen_vflz as (
select
    s.vflz_id, s.vfl_id, up.code_long, up.ili_code, up.ili_c_cli_id
from untersuchungsmassnahmen_pre_vflz up
join standorte s on up.vflz_id = s.vflz_id
union
-- provide UntMassn1 if no other untersuchungsmassnahme is available
select s.vflz_id, s.vfl_id, 'UntMassn1' as code_long, 'UM1' as ili_code, 20023 as ili_c_cli_id
from standorte s
    where s.vflz_id not in (select vflz_id from untersuchungsmassnahmen_pre_vflz)
    ),



untersuchungsmassnahmen_xml_vflz as (
select um.vflz_id,
        xmlelement(name "KbS_V1_5.UntersMassn_",
        xmlelement(name "value", um.code_long)
    ) as x_v15
from untersuchungsmassnahmen_vflz um
),


-- sites in xml form

standorte_xml_v15 as (
    select xmlelement(name "KbS_V1_5_BL_V1.Belastete_Standorte.Belasteter_Standort",
          xmlattributes(standorte.stao_tid as "TID"),
          xmlelement(name "Katasternummer", standorte.vflz_combined_id_kt),
          xmlelement(name "URL_Standort", 
            xmlelement(name "KbS_V1_5.Belastete_Standorte.MultilingualUri",
                xmlelement(name "LocalisedText",
                    xmlelement(name "KbS_V1_5.Belastete_Standorte.LocalisedUri",
                        xmlelement(name "Language", 'de'),
                        xmlelement(name "Text", concat(geoportallinks.permalink_geoportal, '&lang=de'))
                    ), 
                    xmlelement(name "KbS_V1_5.Belastete_Standorte.LocalisedUri",   
                        case when (select org.kuerzel from altlast_admin.setitem join altlast_admin.setting using (setitem_id) join altlast.org on org.org_id=setting.value::int where key= 'org') = 'GR' 
                            then xmlelement(name "Language", 'rm')
                            else xmlelement(name "Language", 'fr') end,
                        case when (select org.kuerzel from altlast_admin.setitem join altlast_admin.setting using (setitem_id) join altlast.org on org.org_id=setting.value::int where key= 'org') = 'GR' 
                                 then xmlelement(name "Text", concat(geoportallinks.permalink_geoportal, '&lang=rm'))
                                else xmlelement(name "Text", concat(geoportallinks.permalink_geoportal, '&lang=fr')) end
                    ),
                    xmlelement(name "KbS_V1_5.Belastete_Standorte.LocalisedUri",
                        xmlelement(name "Language", 'it'),
                        xmlelement(name "Text", concat(geoportallinks.permalink_geoportal, '&lang=it'))
                    )
                )
            )
          ),
          case when standorte.wkb_geometry is not null then
              case when st_geometrytype(standorte.wkb_geometry) = 'ST_Point' then
                  xmlelement(name "Geo_Lage_Punkt", altlast_ili.geoig_v1_5_geometry(ST_Transform((standorte.wkb_geometry), 2056)))
              else
                  xmlelement(name "Geo_Lage_Polygon", altlast_ili.geoig_v1_5_geometry(ST_Transform((standorte.wkb_geometry), 2056)))
              end
          else
              xmlelement(name "Geo_Lage_Punkt", altlast_ili.geoig_v1_5_geometry(ST_Transform((standorte.wkb_geometry), 2056)))
          end,
         case
               when exists(select vflz_id from parzellen_xml where parzellen_xml.vflz_id = standorte.vflz_id) then
                  xmlelement(name "Parzellenverweis",
                        (select xmlagg(x_v15) from parzellen_xml where parzellen_xml.vflz_id = standorte.vflz_id)
                  )
               else
                  xmlcomment('Parzellenverweis not available')
          end,
          case
               when standorte.egrid is not null then
                  xmlelement(name "EGRID", xmlelement(name "KbS_V1_5.EGRID_",
                        xmlelement(name "value", standorte.egrid)
                        )
                  )
                else
                    xmlcomment('EGRID not available')
          end, -- nicht bei BAV
          xmlelement(name "Standorttyp", standorte.staotyp),
          xmlelement(name "InBetrieb", standorte.inbetrieb),
          case
               when standorte.deponietyp is not null then
                  --  Nicht für BAV, da wir keine Ablagerungen „in Betrieb“ haben werden
                  xmlelement(name "Deponietyp", xmlelement(name "KbS_V1_5.Deponietyp_",
                        xmlelement(name "value", standorte.deponietyp)
                        )
                  )
                else
                    xmlcomment('Deponietyp not available')
          end,
          case
                when standorte.nachsorge is not null then
                    xmlelement(name "Nachsorge", standorte.nachsorge)
                else
                    xmlcomment('Nachsorge not available')
          end, -- Nicht bei BAV
          case 
                when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'Mapping_Untersuchungsmassnahmen') = 'alle nach Geschäften' then
                  xmlelement(name "Untersuchungsmassnahmen", (select xmlagg(x_v15) from untersuchungsmassnahmen_xml_pm where untersuchungsmassnahmen_xml_pm.vfl_id = standorte.vfl_id))
                when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'Mapping_Untersuchungsmassnahmen') = 'alle nach Standortversionen' then
                  xmlelement(name "Untersuchungsmassnahmen", (select xmlagg(x_v15) from untersuchungsmassnahmen_xml_vfl where untersuchungsmassnahmen_xml_vfl.vfl_id = standorte.vfl_id))
                when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'Mapping_Untersuchungsmassnahmen') = 'aktuellste' then
                  xmlelement(name "Untersuchungsmassnahmen", (select xmlagg(x_v15) from untersuchungsmassnahmen_xml_vflz where untersuchungsmassnahmen_xml_vflz.vflz_id = standorte.vflz_id))
                else 
                  xmlelement(name "Untersuchungsmassnahmen", (select xmlagg(x_v15) from untersuchungsmassnahmen_xml_vflz where untersuchungsmassnahmen_xml_vflz.vflz_id = standorte.vflz_id))
          end,
          xmlelement(name "StatusAltlV", standorte.statusaltlv),
          xmlelement(name "Ersteintrag", standorte.date_ersteintrag::date),
          xmlelement(name "LetzteAnpassung", standorte.date_letzteanpassung::date),
          xmlelement(name "URL_KbS_Auszug",                                                                                                                                                               
             xmlelement(name "KbS_V1_5.Belastete_Standorte.MultilingualUri",                                                                                                                               
                 xmlelement(name "LocalisedText",                                                                                                                                                          
                     xmlelement(name "KbS_V1_5.Belastete_Standorte.LocalisedUri",                                                                                                                          
                         xmlelement(name "Language", 'de'),                                                                                                                                                
                         xmlelement(name "Text", standorte.url_kbs_datasheet)                                                                                                                              
                     ),                                                                                                                                                                                    
                     xmlelement(name "KbS_V1_5.Belastete_Standorte.LocalisedUri",                                                                                                                          
                         case when (select org.kuerzel from altlast_admin.setitem join altlast_admin.setting using (setitem_id) join altlast.org on org.org_id=setting.value::int where key= 'org') = 'GR' 
                             then xmlelement(name "Language", 'rm')                                                                                                                                        
                             else xmlelement(name "Language", 'fr') end,                                                                                                                                   
                     xmlelement(name "Text", standorte.url_kbs_datasheet)                                                                                                                                  
                     ),                                                                                                                                                                                   
                     xmlelement(name "KbS_V1_5.Belastete_Standorte.LocalisedUri",                                                                                                                          
                         xmlelement(name "Language", 'it'),                                                                                                                                               
                         xmlelement(name "Text", standorte.url_kbs_datasheet)                                                                                                                              
                     )                                                                                                                                                                                     
                 )                                                                                                                                                                                        
             )                                                                                                                                                                                            
           ),   
          /*
          case
                when standorte.standort_bemerkungen != '' then
                    xmlelement(name "Bemerkung", altlast_ili.geoig_localisedmtext(coalesce(standorte.standort_bemerkungen,''), 'de'))
                else
                    */
                    xmlcomment('Bemerkung not available')
          /*end*/,
          xmlelement(name "ZustaendigkeitKataster",
            xmlattributes(
                standorte.zb_tid as "REF"
            )
          ),
          xmlelement(name "Untersuchungsstand", standorte.untersuchungsstand),
          xmlelement(name "Zeitraum", standorte.zeitraum)
      ) as x
    from standorte
    join geoportallinks on geoportallinks.vflz_id = standorte.vflz_id
    order by standorte.stao_tid
),


-- org
zustaendige_behoerde as (
select distinct
        'zb'||org.org_id::text as zb_tid, /* this id also gets build in the standorte with-clause*/
        case when org.org_id = 310 then org.bezeichnung_lang 
            else (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'Behoerde_Amt') 
            end as behoerde,
        (select case 
            when org.org_id = 310 then (select url_behoerde from altlast.org where org_id = 310)
            else (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_Behoerde_Amt')
        end as url_behoerde) as url_behoerde_de,
        (select case 
            when org.org_id = 310 then (select url_behoerde from altlast.org where org_id = 310)
            else (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_Behoerde_Amt_fr')
        end as url_behoerde) as url_behoerde_fr,
        (select case 
            when org.org_id = 310 then (select url_behoerde from altlast.org where org_id = 310)
            else (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_Behoerde_Amt_it')
        end as url_behoerde) as url_behoerde_it,
        (select case 
            when org.org_id = 310 then (select url_behoerde from altlast.org where org_id = 310)
            else (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_Behoerde_Amt_fr')
        end as url_behoerde) as url_behoerde_rm,
        case when org.org_id = 310 then null
            else (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'UID_Behoerde_Amt') 
            end as uid,
        coalesce(org.katastername, org.bezeichnung)::text as katastername,
        (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_Standort_Kataster')::text as url_webgis,
        org.org_id
     from altlast.org
       /* only load orgs which are referenced from sites*/
     where org.org_id in (select org_id from standorte)
),

-- org as xml
zustaendige_behoerde_xml as (
    select 
    xmlelement(name "KbS_V1_5.Belastete_Standorte.ZustaendigkeitKataster",
      xmlattributes(zustaendige_behoerde.zb_tid as "TID"),
      xmlelement(name "Zustaendige_Behoerde", altlast_ili.geoig_localisedtext_t(zustaendige_behoerde.behoerde, 
        array['de',
            case when (select org.kuerzel from altlast_admin.setitem join altlast_admin.setting using (setitem_id) join altlast.org on org.org_id=setting.value::int where key= 'org') = 'GR' 
                then 'rm' 
            else 'fr' end,
            'it'
        ])),

      xmlelement(name "URL_Behoerde",                                                                                                                                                                     
             xmlelement(name "KbS_V1_5.Belastete_Standorte.MultilingualUri",                                                                                                                               
                 xmlelement(name "LocalisedText",                                                                                                                                                         
                     xmlelement(name "KbS_V1_5.Belastete_Standorte.LocalisedUri",                                                                                                                         
                         xmlelement(name "Language", 'de'),                                                                                                                                               
                         xmlelement(name "Text", zustaendige_behoerde.url_behoerde_de)                                                                                                                    
                     ),                                                                                                                                                                                   
                     xmlelement(name "KbS_V1_5.Belastete_Standorte.LocalisedUri",                                                                                                                         
                         case when (select org.kuerzel from altlast_admin.setitem join altlast_admin.setting using (setitem_id) join altlast.org on org.org_id=setting.value::int where key= 'org')= 'GR' 
                             then xmlelement(name "Language", 'rm')                                                                                                                                       
                             else xmlelement(name "Language", 'fr') end,                                                                                                                                  
                         xmlelement(name "Text", zustaendige_behoerde.url_behoerde_fr)                                                                                                                    
                     ),                                                                                                                                                                                   
                     xmlelement(name "KbS_V1_5.Belastete_Standorte.LocalisedUri",                                                                                                                         
                         xmlelement(name "Language", 'it'),                                                                                                                                               
                         xmlelement(name "Text", zustaendige_behoerde.url_behoerde_it)                                                                                                                    
                     )                                                                                                                                                                                    
                 )                                                                                                                                                                                        
             )                                                                                                                                                                                            
         ), 

      xmlelement(name "UID", zustaendige_behoerde.uid),
      xmlelement(name "Katastername",
            altlast_ili.geoig_localisedtext_t(zustaendige_behoerde.katastername, 
            array['de',
                    case when (select org.kuerzel from altlast_admin.setitem join altlast_admin.setting using (setitem_id) join altlast.org on org.org_id=setting.value::int where key= 'org') = 'GR' 
                        then 'rm' 
                    else 'fr' end,
                    'it'
                ])
      ),

      xmlelement(name "URL_Kataster",                                                                                                                                                                     
             xmlelement(name "KbS_V1_5.Belastete_Standorte.MultilingualUri",                                                                                                                               
                 xmlelement(name "LocalisedText",                                                                                                                                                         
                     xmlelement(name "KbS_V1_5.Belastete_Standorte.LocalisedUri",                                                                                                                         
                         xmlelement(name "Language", 'de'),                                                                                                                                               
                         xmlelement(name "Text", concat(zustaendige_behoerde.url_webgis, '&lang=de'))                                                                                                     
                     ),                                                                                                                                                                                   
                     xmlelement(name "KbS_V1_5.Belastete_Standorte.LocalisedUri",                                                                                                                         
                         case when (select org.kuerzel from altlast_admin.setitem join altlast_admin.setting using (setitem_id) join altlast.org on org.org_id=setting.value::int where key= 'org')= 'GR' 
                             then xmlelement(name "Language", 'rm')                                                                                                                                       
                             else xmlelement(name "Language", 'fr') end,                                                                                                                                  
                         case when (select org.kuerzel from altlast_admin.setitem join altlast_admin.setting using (setitem_id) join altlast.org on org.org_id=setting.value::int where key= 'or') = 'GR' 
                                  then xmlelement(name "Text", concat(zustaendige_behoerde.url_webgis, '&lang=rm'))                                                                                       
                                 else xmlelement(name "Text", concat(zustaendige_behoerde.url_webgis, '&lang=fr')) end                                                                                    
                     ),                                                                                                                                                                                   
                     xmlelement(name "KbS_V1_5.Belastete_Standorte.LocalisedUri",                                                                                                                         
                         xmlelement(name "Language", 'it'),                                                                                                                                               
                         xmlelement(name "Text", concat(zustaendige_behoerde.url_webgis, '&lang=it'))                                                                                                     
                     )                                                                                                                                                                                    
                 )                                                                                                                                                                                        
             )                                                                                                                                                                                            
         )   


    ) as x_v15
    from zustaendige_behoerde
)

-- assembling of the finished xml document according to the interlis schema
select xmlelement(name "TRANSFER", xmlattributes('http://www.interlis.ch/INTERLIS2.3' as xmlns),
    xmlelement(name "HEADERSECTION",
        xmlattributes('altlast4web' as "SENDER", '2.3' as "VERSION"),
          xmlelement(name "MODELS", -- need to add all used models by hand
              xmlelement(name "MODEL",xmlattributes('CoordSys' as "NAME",'2015-11-24' as "VERSION",'https://www.interlis.ch/models' as "URI")),
              xmlelement(name "MODEL",xmlattributes('InternationalCodes_V1' as "NAME",'2011-08-30' as "VERSION",'https://www.geo.admin.ch' as "URI")),
              xmlelement(name "MODEL",xmlattributes('Localisation_V1' as "NAME",'2011-08-30' as "VERSION",'https://www.geo.admin.ch' as "URI")),
              xmlelement(name "MODEL",xmlattributes('LocalisationCH_V1' as "NAME",'2011-08-30' as "VERSION",'https://www.geo.admin.ch' as "URI")),
              xmlelement(name "MODEL",xmlattributes('Dictionaries_V1' as "NAME",'2011-08-30' as "VERSION",'https://www.geo.admin.ch' as "URI")),
              xmlelement(name "MODEL",xmlattributes('DictionariesCH_V1' as "NAME",'2011-08-30' as "VERSION",'https://www.geo.admin.ch' as "URI")),
              xmlelement(name "MODEL",xmlattributes('Units' as "NAME",'2012-02-20' as "VERSION",'https://www.interlis.ch/models' as "URI")),
              xmlelement(name "MODEL",xmlattributes('GeometryCHLV95_V1' as "NAME",'2015-11-12' as "VERSION",'https://www.geo.admin.ch' as "URI")),
              xmlelement(name "MODEL",xmlattributes('KbS_V1_5' as "NAME",'2021-07-29' as "VERSION",'https://models.geo.admin.ch/BAFU' as "URI")),
              xmlelement(name "MODEL",xmlattributes('KbS_V1_5_BL_V1' as "NAME",'2022-02-24' as "VERSION",'http://models.geo.bl.ch/AUE' as "URI"))

          )
    ),
   
    xmlelement(name "DATASECTION",
        xmlelement(name "KbS_V1_5.Belastete_Standorte",-- there is no attribute that could server as a bucket-identifier. so we generate an artiffical one.
            xmlattributes((select bid from bidprops) as "BID"),
                ( select xmlagg(x_v15) from zustaendige_behoerde_xml),
                ( select xmlagg(x) from standorte_xml_v15)
        )
    )

);

$_$;


--
-- Name: export_geoig_v15_bl_intern(integer[]); Type: FUNCTION; Schema: altlast_ili; Owner: -
--

CREATE FUNCTION altlast_ili.export_geoig_v15_bl_intern(p_vflz_ids integer[]) RETURNS xml
    LANGUAGE sql
    AS $_$


-- all sites of the list of vflz_ids
with bidprops as (
    select 
        'kbs' || org.kuerzel as bid
    from altlast_admin.setitem
    join altlast_admin.setting using (setitem_id)
    join altlast.org on org.org_id::text=setting.value
    where key = 'org'
),



-- all sites of the list of vflz_ids
standorte as (
    select 'stao'||v.vflz_id::text as stao_tid,
        v.vflz_id,
        v.vfl_id,
        v.vflz_combined_id_kt,
        v.bezeichnung,
        v.c_vflz_vftyp,
        altlast.t(altlast.msgid_code(v.h_vflz_vftyp, v.c_vflz_vftyp), 'de') as vftyp,
        v.c_vflz_bearbstand,
        CASE
            WHEN b.c_bere_res_abwbewe IS NULL THEN 'BLKR09'::character varying
            ELSE b.c_bere_res_abwbewe
        END::text AS c_bere_res_abwbewe,
        vflgeo.wkb_geometry,
        vflnr.org_id,
        staotyp_mapping.code_long as staotyp,
        v.c_vflz_deponietyp::text as deponietyp,
        case when v.c_vflz_nachsorge = '01' then true::text else false::text end as nachsorge, 
        statusaltlv_mapping.code_long as statusaltlv,
        altlast.t(altlast.msgid_code( 
            CASE
                WHEN bere_v.h_bere_res_abwbewe IS NULL THEN '103'::integer
                ELSE bere_v.h_bere_res_abwbewe
            END,
            CASE
                WHEN bere_v.c_bere_res_abwbewe IS NULL THEN 'BLKR09'::character varying
                ELSE bere_v.c_bere_res_abwbewe
            END
            ), 'de') as bewertung,
        altlast.t(altlast.msgid_code(v.h_vflz_bearbstand, v.c_vflz_bearbstand), 'de') as bearbeitungsstand,

        v.c_vflz_unterstand,
        v.h_gem_id,
        h_gem.gemeinde as gemeinde,
        case when v.c_vflz_inbetrieb = '01' then true::text else false::text end as inbetrieb, 
        altlast.t(altlast.msgid_code(v.h_vflz_unterstand, v.c_vflz_unterstand), 'de') as untersuchungsstand

    from altlast.vflz_current_v vic
    join altlast.vflgeo g_1 on g_1.vflz_id = vic.vflz_id
    left join altlast.bere b on b.vflz_id = vic.vflz_id 
    join altlast.vflz v on v.vflz_id = vic.vflz_id 
    left join altlast_ili.cod_mapping_v staotyp_mapping on staotyp_mapping.c_cli_id = v.h_vflz_vftyp
                and staotyp_mapping.code = v.c_vflz_vftyp
    left join altlast.bere_v on bere_v.vflz_id = v.vflz_id
    left join altlast_ili.cod_mapping_v statusaltlv_mapping on statusaltlv_mapping.c_cli_id = bere_v.h_bere_res_abwbewe
                and statusaltlv_mapping.code = bere_v.c_bere_res_abwbewe
    left join altlast.h_gem on h_gem.h_gem_id = v.h_gem_id
    left join altlast.vflnr on v.vflz_id = vflnr.vflz_id and vflnr.aktiv

    -- restrict using the ord configured in a4w
    left join altlast_admin.setting stng on stng.value = vflnr.org_id::text
    left join altlast_admin.setitem sit on sit.setitem_id = stng.setitem_id and sit.key in ('org', 'astra')

    left  join altlast.vflgeo on vflgeo.vflz_id = v.vflz_id

    where v.vfl_id in (
        select vfl_id from altlast.vflz where vflz_id = any($1)
    )
    order by v.vflz_id
),




-- sites in xml form

standorte_xml_v15 as (
    select xmlelement(name "model_bl.kataster_belasteter_standorte.belasteter_standort",
          xmlattributes(standorte.stao_tid as "TID"),
          xmlelement(name "id", standorte.vflz_id),
          xmlelement(name "vflz_id", standorte.vflz_id),
          xmlelement(name "vflz_combined_id_kt", standorte.vflz_combined_id_kt),
          xmlelement(name "obje_bezeichnung", standorte.bezeichnung),
          xmlelement(name "c_vflz_vftyp", standorte.c_vflz_vftyp),
          xmlelement(name "standorttyp", standorte.staotyp),
          xmlelement(name "vftyp", standorte.vftyp),
          xmlelement(name "c_vflz_bearbeitungsstand", standorte.c_vflz_bearbstand),
          case 
              when standorte.c_bere_res_abwbewe = '00' then 
                xmlelement(name "c_bewertung", null)
          else xmlelement(name "c_bewertung", standorte.c_bere_res_abwbewe)
          end,
          xmlelement(name "status_altl_v", standorte.statusaltlv),
          xmlelement(name "bewertung", standorte.bewertung),
          xmlelement(name "bearbeitungsstand", standorte.bearbeitungsstand),
          xmlelement(name "c_vflz_untersuchungsstand", standorte.c_vflz_unterstand),
          xmlelement(name "untersuchungsstand", standorte.untersuchungsstand),
          xmlelement(name "h_gememeinde_id", standorte.h_gem_id),
          xmlelement(name "gemeinde", standorte.gemeinde),
          case
               when standorte.deponietyp is not null then
                  xmlelement(name "deponietyp", xmlelement(name "KbS_V1_5.Deponietyp_",
                        xmlelement(name "value", standorte.deponietyp)
                        )
                  )
                else
                    xmlcomment('Deponietyp not available')
          end,
          xmlelement(name "in_betrieb", standorte.inbetrieb),
          xmlelement(name "nachsorge", standorte.nachsorge),
                
          case when standorte.wkb_geometry is not null then
              case when st_geometrytype(standorte.wkb_geometry) = 'ST_Point' then
                  xmlelement(name "geo_lage_punkt", altlast_ili.geoig_v1_5_geometry_bl(ST_Transform((standorte.wkb_geometry), 2056)))
              else
                  xmlelement(name "geo_lage_polygon", altlast_ili.geoig_v1_5_geometry_bl(ST_Transform((standorte.wkb_geometry), 2056)))
              end
          else
              xmlelement(name "geo_lage_punkt", altlast_ili.geoig_v1_5_geometry_bl(ST_Transform((standorte.wkb_geometry), 2056)))
          end
      ) as x
    from standorte
    order by standorte.stao_tid
),


-- org
zustaendige_behoerde as (
select distinct
        'zb'||org.org_id::text as zb_tid, /* this id also gets build in the standorte with-clause*/
        case when org.org_id = 310 then org.bezeichnung_lang 
            else (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'Behoerde_Amt') 
            end as behoerde,
        (select case 
            when org.org_id = 310 then (select url_behoerde from altlast.org where org_id = 310)
            else (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_Behoerde_Amt')
        end as url_behoerde) as url_behoerde_de,
        (select case 
            when org.org_id = 310 then (select url_behoerde from altlast.org where org_id = 310)
            else (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_Behoerde_Amt_fr')
        end as url_behoerde) as url_behoerde_fr,
        (select case 
            when org.org_id = 310 then (select url_behoerde from altlast.org where org_id = 310)
            else (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_Behoerde_Amt_it')
        end as url_behoerde) as url_behoerde_it,
        (select case 
            when org.org_id = 310 then (select url_behoerde from altlast.org where org_id = 310)
            else (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_Behoerde_Amt_fr')
        end as url_behoerde) as url_behoerde_rm,
        case when org.org_id = 310 then null
            else (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'UID_Behoerde_Amt') 
            end as uid,
        coalesce(org.katastername, org.bezeichnung)::text as katastername,
        (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_Standort_Kataster')::text as url_webgis,
        org.org_id
     from altlast.org
       /* only load orgs which are referenced from sites*/
     where org.org_id in (select org_id from standorte)
),

-- org as xml
zustaendige_behoerde_xml as (
    select 
    xmlelement(name "model_bl.kataster_belasteter_standorte.zustaendigkeit_kataster",
      xmlattributes(zustaendige_behoerde.zb_tid as "TID"),
      xmlelement(name "zustaendige_behoerde", altlast_ili.geoig_localisedtext_t(zustaendige_behoerde.behoerde, 
        array['de',
            case when (select org.kuerzel from altlast_admin.setitem join altlast_admin.setting using (setitem_id) join altlast.org on org.org_id=setting.value::int where key= 'org') = 'GR' 
                then 'rm' 
            else 'fr' end,
            'it'
        ])),

      xmlelement(name "url_behoerde",                                                                                                                                                                     
             xmlelement(name "KbS_V1_5.Belastete_Standorte.MultilingualUri",                                                                                                                               
                 xmlelement(name "LocalisedText",                                                                                                                                                         
                     xmlelement(name "KbS_V1_5.Belastete_Standorte.LocalisedUri",                                                                                                                         
                         xmlelement(name "Language", 'de'),                                                                                                                                               
                         xmlelement(name "Text", zustaendige_behoerde.url_behoerde_de)                                                                                                                    
                     ),                                                                                                                                                                                   
                     xmlelement(name "KbS_V1_5.Belastete_Standorte.LocalisedUri",                                                                                                                         
                         case when (select org.kuerzel from altlast_admin.setitem join altlast_admin.setting using (setitem_id) join altlast.org on org.org_id=setting.value::int where key= 'org')= 'GR' 
                             then xmlelement(name "Language", 'rm')                                                                                                                                       
                             else xmlelement(name "Language", 'fr') end,                                                                                                                                  
                         xmlelement(name "Text", zustaendige_behoerde.url_behoerde_fr)                                                                                                                    
                     ),                                                                                                                                                                                   
                     xmlelement(name "KbS_V1_5.Belastete_Standorte.LocalisedUri",                                                                                                                         
                         xmlelement(name "Language", 'it'),                                                                                                                                               
                         xmlelement(name "Text", zustaendige_behoerde.url_behoerde_it)                                                                                                                    
                     )                                                                                                                                                                                    
                 )                                                                                                                                                                                        
             )                                                                                                                                                                                            
         ), 

      xmlelement(name "uid", zustaendige_behoerde.uid),
      xmlelement(name "katastername",
            altlast_ili.geoig_localisedtext_t(zustaendige_behoerde.katastername, 
            array['de',
                    case when (select org.kuerzel from altlast_admin.setitem join altlast_admin.setting using (setitem_id) join altlast.org on org.org_id=setting.value::int where key= 'org') = 'GR' 
                        then 'rm' 
                    else 'fr' end,
                    'it'
                ])
      ),

      xmlelement(name "url_kataster",                                                                                                                                                                     
             xmlelement(name "KbS_V1_5.Belastete_Standorte.MultilingualUri",                                                                                                                               
                 xmlelement(name "LocalisedText",                                                                                                                                                         
                     xmlelement(name "KbS_V1_5.Belastete_Standorte.LocalisedUri",                                                                                                                         
                         xmlelement(name "Language", 'de'),                                                                                                                                               
                         xmlelement(name "Text", concat(zustaendige_behoerde.url_webgis, '&lang=de'))                                                                                                     
                     ),                                                                                                                                                                                   
                     xmlelement(name "KbS_V1_5.Belastete_Standorte.LocalisedUri",                                                                                                                         
                         case when (select org.kuerzel from altlast_admin.setitem join altlast_admin.setting using (setitem_id) join altlast.org on org.org_id=setting.value::int where key= 'org')= 'GR' 
                             then xmlelement(name "Language", 'rm')                                                                                                                                       
                             else xmlelement(name "Language", 'fr') end,                                                                                                                                  
                         case when (select org.kuerzel from altlast_admin.setitem join altlast_admin.setting using (setitem_id) join altlast.org on org.org_id=setting.value::int where key= 'or') = 'GR' 
                                  then xmlelement(name "Text", concat(zustaendige_behoerde.url_webgis, '&lang=rm'))                                                                                       
                                 else xmlelement(name "Text", concat(zustaendige_behoerde.url_webgis, '&lang=fr')) end                                                                                    
                     ),                                                                                                                                                                                   
                     xmlelement(name "KbS_V1_5.Belastete_Standorte.LocalisedUri",                                                                                                                         
                         xmlelement(name "Language", 'it'),                                                                                                                                               
                         xmlelement(name "Text", concat(zustaendige_behoerde.url_webgis, '&lang=it'))                                                                                                     
                     )                                                                                                                                                                                    
                 )                                                                                                                                                                                        
             )                                                                                                                                                                                            
         )   


    ) as x_v15
    from zustaendige_behoerde
)

-- assembling of the finished xml document according to the interlis schema
select xmlelement(name "TRANSFER", xmlattributes('http://www.interlis.ch/INTERLIS2.3' as xmlns),
    xmlelement(name "HEADERSECTION",
        xmlattributes('altlast4web' as "SENDER", '2.3' as "VERSION"),
          xmlelement(name "MODELS", -- need to add all used models by hand
              xmlelement(name "MODEL",xmlattributes('CoordSys' as "NAME",'2015-11-24' as "VERSION",'https://www.interlis.ch/models' as "URI")),
              xmlelement(name "MODEL",xmlattributes('InternationalCodes_V1' as "NAME",'2011-08-30' as "VERSION",'https://www.geo.admin.ch' as "URI")),
              xmlelement(name "MODEL",xmlattributes('Localisation_V1' as "NAME",'2011-08-30' as "VERSION",'https://www.geo.admin.ch' as "URI")),
              xmlelement(name "MODEL",xmlattributes('LocalisationCH_V1' as "NAME",'2011-08-30' as "VERSION",'https://www.geo.admin.ch' as "URI")),
              xmlelement(name "MODEL",xmlattributes('Dictionaries_V1' as "NAME",'2011-08-30' as "VERSION",'https://www.geo.admin.ch' as "URI")),
              xmlelement(name "MODEL",xmlattributes('DictionariesCH_V1' as "NAME",'2011-08-30' as "VERSION",'https://www.geo.admin.ch' as "URI")),
              xmlelement(name "MODEL",xmlattributes('Units' as "NAME",'2012-02-20' as "VERSION",'https://www.interlis.ch/models' as "URI")),
              xmlelement(name "MODEL",xmlattributes('GeometryCHLV95_V1' as "NAME",'2015-11-12' as "VERSION",'https://www.geo.admin.ch' as "URI")),
              xmlelement(name "MODEL",xmlattributes('KbS_V1_5' as "NAME",'2021-07-29' as "VERSION",'https://models.geo.admin.ch/BAFU' as "URI")),
              xmlelement(name "MODEL",xmlattributes('ch_bl_aue_kbs_intern_v1_0' as "NAME",'2022-02-18' as "VERSION",'https://models.geo.bl.ch/AUE' as "URI"))
          )
    ),
   
    xmlelement(name "DATASECTION",
        xmlelement(name "model_bl.kataster_belasteter_standorte",-- there is no attribute that could server as a bucket-identifier. so we generate an artiffical one.
            xmlattributes((select bid from bidprops) as "BID"),
                ( select xmlagg(x_v15) from zustaendige_behoerde_xml),
                ( select xmlagg(x) from standorte_xml_v15)
        )
    )

);

$_$;


--
-- Name: export_geoig_v15_gr(integer[]); Type: FUNCTION; Schema: altlast_ili; Owner: -
--

CREATE FUNCTION altlast_ili.export_geoig_v15_gr(p_vflz_ids integer[]) RETURNS xml
    LANGUAGE sql
    AS $_$


-- all sites of the list of vflz_ids
with bidprops as (
    select 
        'kbsMGDM' || org.kuerzel as bid
    from altlast_admin.setitem
    join altlast_admin.setting using (setitem_id)
    join altlast.org on org.org_id::text=setting.value
    where key = 'org'
),

wmsprops as (
    select 
      case when (select value as url_geoportal from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_Standort') is not null then 
        (select value as url_geoportal from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_Standort')
      else null end as url_geoportal
),


-- all sites of the list of vflz_ids
standorte as (
    select 'stao'||v.vflz_id::text as stao_tid,
        v.vflz_id,
        v.vfl_id,
        v.vflz_combined_id_kt,
        vflgeo.wkb_geometry,
        vflnr.org_id,
        'zb'||vflnr.org_id::text as zb_tid,
        bem_standort.bem as standort_bemerkungen,
        case when v.x_koordinate is not null and v.y_koordinate is not null then st_makepoint(v.x_koordinate, v.y_koordinate) else null end as wkb_point,
        staotyp_mapping.code_long as staotyp,
        v.c_vflz_deponietyp::text as deponietyp,
        case when v.c_vflz_nachsorge = '01' then true::text else false::text end as nachsorge, 
        null::text as egrid,
        v.dat_rechtskraft::date as date_ersteintrag,
        (   -- legally binding date
            SELECT vflz_is_published_v.dat_latest_published::text AS dat_latest_published
               FROM altlast.vflz_is_published_v
               WHERE (vflz_is_published_v.vflz_id IN ( SELECT vflz_any_in_vfl.vflz_id
                                    FROM altlast.vflz vflz_any_in_vfl
                                    WHERE vflz_any_in_vfl.vfl_id = v.vfl_id)
                    ) AND vflz_is_published_v.is_latest_published
        )::date as date_letzteanpassung,
        statusaltlv_mapping.code_long as statusaltlv,
        case when v.c_vflz_inbetrieb = '01' then true::text else false::text end as inbetrieb, 
        case when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_KbS_Auszug') is not null then
          (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_KbS_Auszug') 
          || (regexp_replace(vfilename.filename::text, ' '::text, '%20'::text, 'g'::text))
          else null end as url_kbs_datasheet,
        regexp_replace(v.bezeichnung, E'[\\n\\r]+', ' ', 'g' ) as bezeichnung
    from altlast.vflz v
    join altlast.vflz_is_published_v vip on v.vflz_id = vip.vflz_id and vip.is_latest_published /* only published versions */
    join altlast_ili.cod_mapping_v staotyp_mapping on staotyp_mapping.c_cli_id = v.h_vflz_vftyp
                and staotyp_mapping.code = v.c_vflz_vftyp
    join altlast.bere_v on bere_v.vflz_id = v.vflz_id and bere_v.kbs
    join altlast_ili.cod_mapping_v statusaltlv_mapping on statusaltlv_mapping.c_cli_id = bere_v.h_bere_res_abwbewe
                and statusaltlv_mapping.code = bere_v.c_bere_res_abwbewe
    join altlast.vflnr on v.vflz_id = vflnr.vflz_id and vflnr.aktiv

    -- restrict using the ord configured in a4w
    join altlast_admin.setting stng on stng.value = vflnr.org_id::text
    join altlast_admin.setitem sit on sit.setitem_id = stng.setitem_id and sit.key in ('org', 'astra')

    left  join altlast.vflgeo on vflgeo.vflz_id = v.vflz_id
    left join altlast.bemgrp bemg_standort on bemg_standort.public and bemg_standort.bemgrp='standort'
    left join altlast.bem bem_standort on bem_standort.bemgrp_id = bemg_standort.bemgrp_id and
                bem_standort.key_value = v.vflz_id and bem_standort.public

    left join altlast.vflz_filename_v vfilename on vfilename.vflz_id = v.vflz_id

    where v.vfl_id in (
        select vfl_id from altlast.vflz where vflz_id = any($1)
    )
    order by v.vflz_id
),

geoportallinks as (
    select
        standorte.vflz_id,
        case when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_Standort_Indikator') = 'standortnummer' then
          wmsprops.url_geoportal || (regexp_replace(standorte.vflz_combined_id_kt::text, ' '::text, '%20'::text, 'g'::text))
        when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_Standort_Indikator') = 'xy_koordinates' then
           wmsprops.url_geoportal || '&Y=' || st_x(standorte.wkb_point)::text || '&X=' || st_y(standorte.wkb_point)::text
        when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_Standort_Indikator') = 'map_x_map_y_koordinates' then
           wmsprops.url_geoportal || '&map_x=' || st_x(standorte.wkb_point)::text || '&map_y=' || st_y(standorte.wkb_point)::text
        when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_Standort_Indikator') = 'c_koordinates' then
           wmsprops.url_geoportal || '&c=' || st_y(standorte.wkb_point)::text || ',' || st_x(standorte.wkb_point)::text 
        else wmsprops.url_geoportal 
        end as permalink_geoportal
    from standorte, wmsprops
),


-- parcels for all returned sites
parzellen as (
  select 
    org || bfsnr as nbident, vflz_id, parzelle 
  from (select 
      vpmv.h_gem_id as bfsnr,  /* Der NBIdent  (Nummerierungsbereichidentifikator) setzt sich zusammen
               aus dem Kt (Kantonskürzel) und der NBNummer  (Nummerierungsbereichnummer). */
      (select org.kuerzel from altlast_admin.setitem join altlast_admin.setting using (setitem_id) join altlast.org on org.org_id=setting.value::int where key= 'org') as org,
      vpmv.vflz_id as vflz_id,
      vpmv.gb_nummer as parzelle,
      case when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'Parzellenverweiss') = 'Ja' then true
      else false /* never return any parcels as we can never returned the required nbident number */
      end as parzellenverweiss
        from altlast.vflz_parzellen_materialization_v vpmv
        group by vpmv.h_gem_id, vpmv.vflz_id, vpmv.gb_nummer)foo
  where foo.vflz_id in (select vflz_id from standorte) and foo.parzellenverweiss
  order by bfsnr, parzelle
),

-- parcels in xml form
parzellen_xml as (
select parzellen.vflz_id,
        xmlelement(name "KbS_V1_5.Parzellenidentifikation",
        xmlelement(name "NBIdent", parzellen.nbident),
        xmlelement(name "Parzellennummer", parzellen.parzelle)
    ) as x_v15
from parzellen
order by parzellen.parzelle
),

untersuchungsmassnahmen_pre_pm as (
select massn.*
from (
      select tm.code_long, tm.ili_code, tm.ili_c_cli_id, pv.vfl_id from altlast_ili.task_mapping_v tm 
        join altlast.pm_cache_v pc on pc.pro_uid = tm.pro_uid and pc.status = 'CLOSED' and case when tm.tas_uid is null then true else tm.tas_uid = pc.tas_uid end
        join altlast.pm_vfl pv on pv.pm_vfl_id = pc.pm_vfl_id
) massn
join standorte s on massn.vfl_id = s.vfl_id
),

untersuchungsmassnahmen_pm as (
select
    s.vfl_id, up.code_long, up.ili_code, up.ili_c_cli_id
from untersuchungsmassnahmen_pre_pm up
join standorte s on up.vfl_id = s.vfl_id
union
-- provide UntMassn1 if no other untersuchungsmassnahme is available
select s.vfl_id, 'UntMassn1' as code_long, 'UM1' as ili_code, 20023 as ili_c_cli_id
from standorte s
    where s.vfl_id not in (select vfl_id from untersuchungsmassnahmen_pre_pm)
    ),

untersuchungsmassnahmen_xml_pm as (
select um.vfl_id,
        xmlelement(name "KbS_V1_5.UntersMassn_",
        xmlelement(name "value", um.code_long)
    ) as x_v15
from untersuchungsmassnahmen_pm um
),


untersuchungsmassnahmen_pre_vfl as (
select massn.*
from (
      select tm.code_long, tm.ili_code, tm.ili_c_cli_id, v.vfl_id from altlast_ili.task_mapping_v tm join altlast.vflz v on v.c_vflz_unterstand = tm.a4w_code
) massn
join standorte s on massn.vfl_id = s.vfl_id
),

untersuchungsmassnahmen_vfl as (
select
    s.vfl_id, up.code_long, up.ili_code, up.ili_c_cli_id
from untersuchungsmassnahmen_pre_vfl up
join standorte s on up.vfl_id = s.vfl_id
union
-- provide UntMassn1 if no other untersuchungsmassnahme is available
select s.vfl_id, 'UntMassn1' as code_long, 'UM1' as ili_code, 20023 as ili_c_cli_id
from standorte s
    where s.vfl_id not in (select vfl_id from untersuchungsmassnahmen_pre_vfl)
    ),

untersuchungsmassnahmen_xml_vfl as (
select um.vfl_id,
        xmlelement(name "KbS_V1_5.UntersMassn_",
        xmlelement(name "value", um.code_long)
    ) as x_v15
from untersuchungsmassnahmen_vfl um
),


untersuchungsmassnahmen_pre_vflz as (
select massn.*
from (
      select tm.code_long, tm.ili_code, tm.ili_c_cli_id, v.vfl_id, v.vflz_id from altlast_ili.task_mapping_v tm join altlast.vflz v on v.c_vflz_unterstand = tm.a4w_code
) massn
join standorte s on massn.vflz_id = s.vflz_id
),

untersuchungsmassnahmen_vflz as (
select
    s.vflz_id, s.vfl_id, up.code_long, up.ili_code, up.ili_c_cli_id
from untersuchungsmassnahmen_pre_vflz up
join standorte s on up.vflz_id = s.vflz_id
union
-- provide UntMassn1 if no other untersuchungsmassnahme is available
select s.vflz_id, s.vfl_id, 'UntMassn1' as code_long, 'UM1' as ili_code, 20023 as ili_c_cli_id
from standorte s
    where s.vflz_id not in (select vflz_id from untersuchungsmassnahmen_pre_vflz)
    ),



untersuchungsmassnahmen_xml_vflz as (
select um.vflz_id,
        xmlelement(name "KbS_V1_5.UntersMassn_",
        xmlelement(name "value", um.code_long)
    ) as x_v15
from untersuchungsmassnahmen_vflz um
),


-- sites in xml form

standorte_xml_v15 as (
    select xmlelement(name "KbS_V1_5_GR_V1.Belastete_Standorte.Belasteter_Standort",
          xmlattributes(standorte.stao_tid as "TID"),
          xmlelement(name "Katasternummer", standorte.vflz_combined_id_kt),
          xmlelement(name "Bezeichnung", standorte.bezeichnung),
          xmlelement(name "URL_Standort", 
            xmlelement(name "KbS_V1_5.Belastete_Standorte.MultilingualUri",
                xmlelement(name "LocalisedText",
                    xmlelement(name "KbS_V1_5.Belastete_Standorte.LocalisedUri",
                        xmlelement(name "Language", 'de'),
                        xmlelement(name "Text", concat(geoportallinks.permalink_geoportal, '&lang=de'))
                    ), 
                    xmlelement(name "KbS_V1_5.Belastete_Standorte.LocalisedUri",   
                        case when (select org.kuerzel from altlast_admin.setitem join altlast_admin.setting using (setitem_id) join altlast.org on org.org_id=setting.value::int where key= 'org') = 'GR' 
                            then xmlelement(name "Language", 'rm')
                            else xmlelement(name "Language", 'fr') end,
                        case when (select org.kuerzel from altlast_admin.setitem join altlast_admin.setting using (setitem_id) join altlast.org on org.org_id=setting.value::int where key= 'org') = 'GR' 
                                 then xmlelement(name "Text", concat(geoportallinks.permalink_geoportal, '&lang=rm'))
                                else xmlelement(name "Text", concat(geoportallinks.permalink_geoportal, '&lang=fr')) end
                    ),
                    xmlelement(name "KbS_V1_5.Belastete_Standorte.LocalisedUri",
                        xmlelement(name "Language", 'it'),
                        xmlelement(name "Text", concat(geoportallinks.permalink_geoportal, '&lang=it'))
                    )
                )
            )
          ),
          case when standorte.wkb_geometry is not null then
              case when st_geometrytype(standorte.wkb_geometry) = 'ST_Point' then
                  xmlelement(name "Geo_Lage_Punkt", altlast_ili.geoig_v1_5_geometry(ST_Transform((standorte.wkb_geometry), 2056)))
              else
                  xmlelement(name "Geo_Lage_Polygon", altlast_ili.geoig_v1_5_geometry(ST_Transform((standorte.wkb_geometry), 2056)))
              end
          else
              xmlelement(name "Geo_Lage_Punkt", altlast_ili.geoig_v1_5_geometry(ST_Transform((standorte.wkb_geometry), 2056)))
          end,
         case
               when exists(select vflz_id from parzellen_xml where parzellen_xml.vflz_id = standorte.vflz_id) then
                  xmlelement(name "Parzellenverweis",
                        (select xmlagg(x_v15) from parzellen_xml where parzellen_xml.vflz_id = standorte.vflz_id)
                  )
               else
                  xmlcomment('Parzellenverweis not available')
          end,
          case
               when standorte.egrid is not null then
                  xmlelement(name "EGRID", xmlelement(name "KbS_V1_5.EGRID_",
                        xmlelement(name "value", standorte.egrid)
                        )
                  )
                else
                    xmlcomment('EGRID not available')
          end, -- nicht bei BAV
          xmlelement(name "Standorttyp", standorte.staotyp),
          xmlelement(name "InBetrieb", standorte.inbetrieb),
          case
               when standorte.deponietyp is not null then
                  --  Nicht für BAV, da wir keine Ablagerungen „in Betrieb“ haben werden
                  xmlelement(name "Deponietyp", xmlelement(name "KbS_V1_5.Deponietyp_",
                        xmlelement(name "value", standorte.deponietyp)
                        )
                  )
                else
                    xmlcomment('Deponietyp not available')
          end,
          case
                when standorte.nachsorge is not null then
                    xmlelement(name "Nachsorge", standorte.nachsorge)
                else
                    xmlcomment('Nachsorge not available')
          end, -- Nicht bei BAV
          case 
                when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'Mapping_Untersuchungsmassnahmen') = 'alle nach Geschäften' then
                  xmlelement(name "Untersuchungsmassnahmen", (select xmlagg(x_v15) from untersuchungsmassnahmen_xml_pm where untersuchungsmassnahmen_xml_pm.vfl_id = standorte.vfl_id))
                when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'Mapping_Untersuchungsmassnahmen') = 'alle nach Standortversionen' then
                  xmlelement(name "Untersuchungsmassnahmen", (select xmlagg(x_v15) from untersuchungsmassnahmen_xml_vfl where untersuchungsmassnahmen_xml_vfl.vfl_id = standorte.vfl_id))
                when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'Mapping_Untersuchungsmassnahmen') = 'aktuellste' then
                  xmlelement(name "Untersuchungsmassnahmen", (select xmlagg(x_v15) from untersuchungsmassnahmen_xml_vflz where untersuchungsmassnahmen_xml_vflz.vflz_id = standorte.vflz_id))
                else 
                  xmlelement(name "Untersuchungsmassnahmen", (select xmlagg(x_v15) from untersuchungsmassnahmen_xml_vflz where untersuchungsmassnahmen_xml_vflz.vflz_id = standorte.vflz_id))
          end,
          xmlelement(name "StatusAltlV", standorte.statusaltlv),
          xmlelement(name "Ersteintrag", standorte.date_ersteintrag::date),
          xmlelement(name "LetzteAnpassung", standorte.date_letzteanpassung::date),
          xmlelement(name "URL_KbS_Auszug",                                                                                                                                                               
             xmlelement(name "KbS_V1_5.Belastete_Standorte.MultilingualUri",                                                                                                                               
                 xmlelement(name "LocalisedText",                                                                                                                                                          
                     xmlelement(name "KbS_V1_5.Belastete_Standorte.LocalisedUri",                                                                                                                          
                         xmlelement(name "Language", 'de'),                                                                                                                                                
                         xmlelement(name "Text", standorte.url_kbs_datasheet)                                                                                                                              
                     ),                                                                                                                                                                                    
                     xmlelement(name "KbS_V1_5.Belastete_Standorte.LocalisedUri",                                                                                                                          
                         case when (select org.kuerzel from altlast_admin.setitem join altlast_admin.setting using (setitem_id) join altlast.org on org.org_id=setting.value::int where key= 'org') = 'GR' 
                             then xmlelement(name "Language", 'rm')                                                                                                                                        
                             else xmlelement(name "Language", 'fr') end,                                                                                                                                   
                     xmlelement(name "Text", standorte.url_kbs_datasheet)                                                                                                                                  
                     ),                                                                                                                                                                                   
                     xmlelement(name "KbS_V1_5.Belastete_Standorte.LocalisedUri",                                                                                                                          
                         xmlelement(name "Language", 'it'),                                                                                                                                               
                         xmlelement(name "Text", standorte.url_kbs_datasheet)                                                                                                                              
                     )                                                                                                                                                                                     
                 )                                                                                                                                                                                        
             )                                                                                                                                                                                            
           ),   
          /*
          case
                when standorte.standort_bemerkungen != '' then
                    xmlelement(name "Bemerkung", altlast_ili.geoig_localisedmtext(coalesce(standorte.standort_bemerkungen,''), 'de'))
                else
                    */
                    xmlcomment('Bemerkung not available')
          /*end*/,
          xmlelement(name "ZustaendigkeitKataster",
            xmlattributes(
                standorte.zb_tid as "REF"
            )
          )
      ) as x
    from standorte
    join geoportallinks on geoportallinks.vflz_id = standorte.vflz_id
    order by standorte.stao_tid
),


-- org
zustaendige_behoerde as (
select distinct
        'zb'||org.org_id::text as zb_tid, /* this id also gets build in the standorte with-clause*/
        case when org.org_id = 310 then org.bezeichnung_lang 
            else (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'Behoerde_Amt') 
            end as behoerde,
        (select case 
            when org.org_id = 310 then (select url_behoerde from altlast.org where org_id = 310)
            else (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_Behoerde_Amt')
        end as url_behoerde) as url_behoerde_de,
        (select case 
            when org.org_id = 310 then (select url_behoerde from altlast.org where org_id = 310)
            else (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_Behoerde_Amt_fr')
        end as url_behoerde) as url_behoerde_fr,
        (select case 
            when org.org_id = 310 then (select url_behoerde from altlast.org where org_id = 310)
            else (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_Behoerde_Amt_it')
        end as url_behoerde) as url_behoerde_it,
        (select case 
            when org.org_id = 310 then (select url_behoerde from altlast.org where org_id = 310)
            else (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_Behoerde_Amt_fr')
        end as url_behoerde) as url_behoerde_rm,
        case when org.org_id = 310 then null
            else (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'UID_Behoerde_Amt') 
            end as uid,
        coalesce(org.katastername, org.bezeichnung)::text as katastername,
        (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_Standort_Kataster')::text as url_webgis,
        org.org_id
     from altlast.org
       /* only load orgs which are referenced from sites*/
     where org.org_id in (select org_id from standorte)
),

-- org as xml
zustaendige_behoerde_xml as (
    select 
    xmlelement(name "KbS_V1_5.Belastete_Standorte.ZustaendigkeitKataster",
      xmlattributes(zustaendige_behoerde.zb_tid as "TID"),
      xmlelement(name "Zustaendige_Behoerde", altlast_ili.geoig_localisedtext_t(zustaendige_behoerde.behoerde, 
        array['de',
            case when (select org.kuerzel from altlast_admin.setitem join altlast_admin.setting using (setitem_id) join altlast.org on org.org_id=setting.value::int where key= 'org') = 'GR' 
                then 'rm' 
            else 'fr' end,
            'it'
        ])),

      xmlelement(name "URL_Behoerde",                                                                                                                                                                     
             xmlelement(name "KbS_V1_5.Belastete_Standorte.MultilingualUri",                                                                                                                               
                 xmlelement(name "LocalisedText",                                                                                                                                                         
                     xmlelement(name "KbS_V1_5.Belastete_Standorte.LocalisedUri",                                                                                                                         
                         xmlelement(name "Language", 'de'),                                                                                                                                               
                         xmlelement(name "Text", zustaendige_behoerde.url_behoerde_de)                                                                                                                    
                     ),                                                                                                                                                                                   
                     xmlelement(name "KbS_V1_5.Belastete_Standorte.LocalisedUri",                                                                                                                         
                         case when (select org.kuerzel from altlast_admin.setitem join altlast_admin.setting using (setitem_id) join altlast.org on org.org_id=setting.value::int where key= 'org')= 'GR' 
                             then xmlelement(name "Language", 'rm')                                                                                                                                       
                             else xmlelement(name "Language", 'fr') end,                                                                                                                                  
                         xmlelement(name "Text", zustaendige_behoerde.url_behoerde_fr)                                                                                                                    
                     ),                                                                                                                                                                                   
                     xmlelement(name "KbS_V1_5.Belastete_Standorte.LocalisedUri",                                                                                                                         
                         xmlelement(name "Language", 'it'),                                                                                                                                               
                         xmlelement(name "Text", zustaendige_behoerde.url_behoerde_it)                                                                                                                    
                     )                                                                                                                                                                                    
                 )                                                                                                                                                                                        
             )                                                                                                                                                                                            
         ), 

      xmlelement(name "UID", zustaendige_behoerde.uid),
      xmlelement(name "Katastername",
            altlast_ili.geoig_localisedtext_t(zustaendige_behoerde.katastername, 
            array['de',
                    case when (select org.kuerzel from altlast_admin.setitem join altlast_admin.setting using (setitem_id) join altlast.org on org.org_id=setting.value::int where key= 'org') = 'GR' 
                        then 'rm' 
                    else 'fr' end,
                    'it'
                ])
      ),

      xmlelement(name "URL_Kataster",                                                                                                                                                                     
             xmlelement(name "KbS_V1_5.Belastete_Standorte.MultilingualUri",                                                                                                                               
                 xmlelement(name "LocalisedText",                                                                                                                                                         
                     xmlelement(name "KbS_V1_5.Belastete_Standorte.LocalisedUri",                                                                                                                         
                         xmlelement(name "Language", 'de'),                                                                                                                                               
                         xmlelement(name "Text", concat(zustaendige_behoerde.url_webgis, '&lang=de'))                                                                                                     
                     ),                                                                                                                                                                                   
                     xmlelement(name "KbS_V1_5.Belastete_Standorte.LocalisedUri",                                                                                                                         
                         case when (select org.kuerzel from altlast_admin.setitem join altlast_admin.setting using (setitem_id) join altlast.org on org.org_id=setting.value::int where key= 'org')= 'GR' 
                             then xmlelement(name "Language", 'rm')                                                                                                                                       
                             else xmlelement(name "Language", 'fr') end,                                                                                                                                  
                         case when (select org.kuerzel from altlast_admin.setitem join altlast_admin.setting using (setitem_id) join altlast.org on org.org_id=setting.value::int where key= 'or') = 'GR' 
                                  then xmlelement(name "Text", concat(zustaendige_behoerde.url_webgis, '&lang=rm'))                                                                                       
                                 else xmlelement(name "Text", concat(zustaendige_behoerde.url_webgis, '&lang=fr')) end                                                                                    
                     ),                                                                                                                                                                                   
                     xmlelement(name "KbS_V1_5.Belastete_Standorte.LocalisedUri",                                                                                                                         
                         xmlelement(name "Language", 'it'),                                                                                                                                               
                         xmlelement(name "Text", concat(zustaendige_behoerde.url_webgis, '&lang=it'))                                                                                                     
                     )                                                                                                                                                                                    
                 )                                                                                                                                                                                        
             )                                                                                                                                                                                            
         )   


    ) as x_v15
    from zustaendige_behoerde
)

-- assembling of the finished xml document according to the interlis schema
select xmlelement(name "TRANSFER", xmlattributes('http://www.interlis.ch/INTERLIS2.3' as xmlns),
    xmlelement(name "HEADERSECTION",
        xmlattributes('altlast4web' as "SENDER", '2.3' as "VERSION"),
          xmlelement(name "MODELS", -- need to add all used models by hand
              xmlelement(name "MODEL",xmlattributes('CoordSys' as "NAME",'2015-11-24' as "VERSION",'https://www.interlis.ch/models' as "URI")),
              xmlelement(name "MODEL",xmlattributes('InternationalCodes_V1' as "NAME",'2011-08-30' as "VERSION",'https://www.geo.admin.ch' as "URI")),
              xmlelement(name "MODEL",xmlattributes('Localisation_V1' as "NAME",'2011-08-30' as "VERSION",'https://www.geo.admin.ch' as "URI")),
              xmlelement(name "MODEL",xmlattributes('LocalisationCH_V1' as "NAME",'2011-08-30' as "VERSION",'https://www.geo.admin.ch' as "URI")),
              xmlelement(name "MODEL",xmlattributes('Dictionaries_V1' as "NAME",'2011-08-30' as "VERSION",'https://www.geo.admin.ch' as "URI")),
              xmlelement(name "MODEL",xmlattributes('DictionariesCH_V1' as "NAME",'2011-08-30' as "VERSION",'https://www.geo.admin.ch' as "URI")),
              xmlelement(name "MODEL",xmlattributes('Units' as "NAME",'2012-02-20' as "VERSION",'https://www.interlis.ch/models' as "URI")),
              xmlelement(name "MODEL",xmlattributes('GeometryCHLV95_V1' as "NAME",'2015-11-12' as "VERSION",'https://www.geo.admin.ch' as "URI")),
              xmlelement(name "MODEL",xmlattributes('KbS_V1_5' as "NAME",'2021-07-29' as "VERSION",'https://models.geo.admin.ch/BAFU' as "URI")),
              xmlelement(name "MODEL",xmlattributes('KbS_V1_5_GR_V1' as "NAME",'2022-02-24' as "VERSION",'https://models.geo.gr.ch/2_Natur_und_Umwelt/L_Umweltschutz_Naturschutz' as "URI"))

          )
    ),
   
    xmlelement(name "DATASECTION",
        xmlelement(name "KbS_V1_5.Belastete_Standorte",-- there is no attribute that could server as a bucket-identifier. so we generate an artiffical one.
            xmlattributes((select bid from bidprops) as "BID"),
                ( select xmlagg(x_v15) from zustaendige_behoerde_xml),
                ( select xmlagg(x) from standorte_xml_v15)
        )
    )

);

$_$;


--
-- Name: export_geoig_v15_so(integer[]); Type: FUNCTION; Schema: altlast_ili; Owner: -
--

CREATE FUNCTION altlast_ili.export_geoig_v15_so(p_vflz_ids integer[]) RETURNS xml
    LANGUAGE sql
    AS $_$


-- all sites of the list of vflz_ids
with bidprops as (
    select 
        'SO_AFU_KbS_Publikation' || org.kuerzel as bid
    from altlast_admin.setitem
    join altlast_admin.setting using (setitem_id)
    join altlast.org on org.org_id::text=setting.value
    where key = 'org'
),



-- all sites of the list of vflz_ids
standorte as (
    select 'stao'||v.vflz_id::text as stao_tid,
        v.vflz_id,
        v.vfl_id,
        v.vflz_combined_id_kt,
        vflgeo.wkb_geometry,
        vflnr.org_id,
        'zb'||vflnr.org_id::text as zb_tid,
        statusaltlv_mapping.code_long as statusaltlv,
        altlast.t(altlast.msgid_code(v.h_vflz_vftyp, v.c_vflz_vftyp), 'de') as staotyp,       
        altlast.t(altlast.msgid_code(bere_v.h_bere_res_abwbewe, bere_v.c_bere_res_abwbewe), 'de') as bewertung,
        altlast.t(altlast.msgid_code(v.h_vflz_unterstand, v.c_vflz_unterstand), 'de') as untersuchungsstand,
        altlast.t(altlast.msgid_code(v.h_vflz_bearbstand, v.c_vflz_bearbstand), 'de') as Bearbeitungsstand,

        concat((altlast.t(altlast.msgid_code(v.h_vflz_unterstand, v.c_vflz_unterstand), 'de')), ' / ', 
            altlast.t(altlast.msgid_code(v.h_vflz_bearbstand, v.c_vflz_bearbstand), 'de')) as stand,
        org.org_id,
        case when org.org_id = 210 then org.kuerzel
            else 'andere'
        end as vollzug
    from altlast.vflz v
    join altlast.vflz_is_published_v vip on v.vflz_id = vip.vflz_id and vip.is_latest_published /* only published versions */
    join altlast_ili.cod_mapping_v staotyp_mapping on staotyp_mapping.c_cli_id = v.h_vflz_vftyp
                and staotyp_mapping.code = v.c_vflz_vftyp
    join altlast.bere_v on bere_v.vflz_id = v.vflz_id and bere_v.kbs
    join altlast_ili.cod_mapping_v statusaltlv_mapping on statusaltlv_mapping.c_cli_id = bere_v.h_bere_res_abwbewe
                and statusaltlv_mapping.code = bere_v.c_bere_res_abwbewe
    join altlast.vflnr on v.vflz_id = vflnr.vflz_id and vflnr.aktiv

    -- restrict using the ord configured in a4w
    join altlast_admin.setting stng on stng.value = vflnr.org_id::text
    join altlast_admin.setitem sit on sit.setitem_id = stng.setitem_id and sit.key in ('org', 'astra')

    left  join altlast.vflgeo on vflgeo.vflz_id = v.vflz_id
    left join altlast.org on vflnr.org_id = org.org_id

    where v.vfl_id in (
        select vfl_id from altlast.vflz where vflz_id = any($1)
    )
    order by v.vflz_id
),


-- sites in xml form

standorte_xml_v15 as (
    select xmlelement(name "model_so.Belastete_Standorte.Belasteter_Standort",
          xmlattributes(standorte.stao_tid as "TID"),
          xmlelement(name "Standortnummer", standorte.vflz_combined_id_kt),
          xmlelement(name "Standorttyp", standorte.staotyp),
          xmlelement(name "Bewertung", standorte.bewertung),
          xmlelement(name "Stand", standorte.stand),
          xmlelement(name "Vollzug", standorte.vollzug),
          case when standorte.wkb_geometry is not null then
              case when st_geometrytype(standorte.wkb_geometry) = 'ST_Point' then
                  xmlelement(name "Geometrie", altlast_ili.geometry_so(ST_Transform((standorte.wkb_geometry), 2056)))
              else
                  xmlelement(name "Geometrie", altlast_ili.geometry_so(ST_Transform((standorte.wkb_geometry), 2056)))
              end
          else
              xmlelement(name "Geometrie", altlast_ili.geometry_so(ST_Transform((standorte.wkb_geometry), 2056)))
          end
         ) as x
    from standorte
    order by standorte.stao_tid
)



-- assembling of the finished xml document according to the interlis schema
select xmlelement(name "TRANSFER", xmlattributes('http://www.interlis.ch/INTERLIS2.3' as xmlns),
    xmlelement(name "HEADERSECTION",
        xmlattributes('altlast4web' as "SENDER", '2.3' as "VERSION"),
          xmlelement(name "MODELS", -- need to add all used models by hand
              xmlelement(name "MODEL",xmlattributes('CoordSys' as "NAME",'2015-11-24' as "VERSION",'https://www.interlis.ch/models' as "URI")),
              xmlelement(name "MODEL",xmlattributes('InternationalCodes_V1' as "NAME",'2011-08-30' as "VERSION",'https://www.geo.admin.ch' as "URI")),
              xmlelement(name "MODEL",xmlattributes('Localisation_V1' as "NAME",'2011-08-30' as "VERSION",'https://www.geo.admin.ch' as "URI")),
              xmlelement(name "MODEL",xmlattributes('LocalisationCH_V1' as "NAME",'2011-08-30' as "VERSION",'https://www.geo.admin.ch' as "URI")),
              xmlelement(name "MODEL",xmlattributes('Dictionaries_V1' as "NAME",'2011-08-30' as "VERSION",'https://www.geo.admin.ch' as "URI")),
              xmlelement(name "MODEL",xmlattributes('DictionariesCH_V1' as "NAME",'2011-08-30' as "VERSION",'https://www.geo.admin.ch' as "URI")),
              xmlelement(name "MODEL",xmlattributes('Units' as "NAME",'2012-02-20' as "VERSION",'https://www.interlis.ch/models' as "URI")),
              xmlelement(name "MODEL",xmlattributes('GeometryCHLV95_V1' as "NAME",'2015-11-12' as "VERSION",'https://www.geo.admin.ch' as "URI")),
              xmlelement(name "MODEL",xmlattributes('SO_AFU_KbS_Publikation__20230104' as "NAME",'2023-01-04' as "VERSION",'https://afu.so.ch' as "URI"))
          )
    ),
   
    xmlelement(name "DATASECTION",
        xmlelement(name "model_so.Belastete_Standorte",-- there is no attribute that could server as a bucket-identifier. so we generate an artiffical one.
            xmlattributes((select bid from bidprops) as "BID"),
                ( select xmlagg(x) from standorte_xml_v15)
        )
    )

);

$_$;


--
-- Name: export_geoig_v15_so_restricted(integer[]); Type: FUNCTION; Schema: altlast_ili; Owner: -
--

CREATE FUNCTION altlast_ili.export_geoig_v15_so_restricted(p_vflz_ids integer[]) RETURNS xml
    LANGUAGE sql
    AS $_$


-- all sites of the list of vflz_ids
with bidprops as (
    select 
        'SO_AFU_KbS_Publikation' || org.kuerzel as bid
    from altlast_admin.setitem
    join altlast_admin.setting using (setitem_id)
    join altlast.org on org.org_id::text=setting.value
    where key = 'org'
),


-- all sites of the list of vflz_ids
standorte as (
    select 'stao'||v.vflz_id::text as stao_tid,
        v.vflz_id,
        v.vfl_id,
        v.vflz_combined_id_kt,
        v.bezeichnung,
        vflgeo.wkb_geometry,
        vflnr.org_id,
        'zb'||vflnr.org_id::text as zb_tid,
        altlast.t(altlast.msgid_code(v.h_vflz_vftyp, v.c_vflz_vftyp), 'de') as staotyp,  
        altlast.t(altlast.msgid_code(v.h_vflz_bearbstand, v.c_vflz_bearbstand), 'de') as bearbeitungsstand,
        altlast.t(altlast.msgid_code(bere_v.h_bere_res_abwbewe, bere_v.c_bere_res_abwbewe), 'de') as bewertung,
        altlast.t(altlast.msgid_code(v.h_vflz_unterstand, v.c_vflz_unterstand), 'de') as untersuchungsstand,
        org.org_id,
        case when org.org_id = 210 then org.kuerzel
            else 'andere'
        end as vollzug
    from altlast.vflz v
    join altlast.vflz_is_current_v vic on v.vflz_id = vic.vflz_id and vic.is_current /* only current versions */
    join altlast.bere_v on bere_v.vflz_id = v.vflz_id and bere_v.c_bere_res_abwbewe != '00'
    join altlast.vflnr on v.vflz_id = vflnr.vflz_id and vflnr.aktiv

    join altlast.vflgeo on vflgeo.vflz_id = v.vflz_id
    left join altlast.org on vflnr.org_id = org.org_id

    where v.vfl_id in (
        select vfl_id from altlast.vflz where vflz_id = any($1)
    )
    order by v.vflz_id
),


-- sites in xml form

standorte_xml_v15 as (
    select xmlelement(name "model_so.Belastete_Standorte.Belasteter_Standort",
          xmlattributes(standorte.stao_tid as "TID"),
          xmlelement(name "Standortnummer", standorte.vflz_combined_id_kt),
          xmlelement(name "Bezeichnung", standorte.bezeichnung),          
          xmlelement(name "Standorttyp", standorte.staotyp),
          xmlelement(name "Bearbeitungsstand", standorte.bearbeitungsstand),
          xmlelement(name "Bewertung", standorte.bewertung),
          xmlelement(name "Untersuchungsstand", standorte.untersuchungsstand),
          xmlelement(name "Vollzug", standorte.vollzug),
          case when standorte.wkb_geometry is not null then
              case when st_geometrytype(standorte.wkb_geometry) = 'ST_Point' then
                  xmlelement(name "Geometrie", altlast_ili.geometry_so(ST_Transform((standorte.wkb_geometry), 2056)))
              else
                  xmlelement(name "Geometrie", altlast_ili.geometry_so(ST_Transform((standorte.wkb_geometry), 2056)))
              end
          else
              xmlelement(name "Geometrie", altlast_ili.geometry_so(ST_Transform((standorte.wkb_geometry), 2056)))
          end
         ) as x
    from standorte
    order by standorte.stao_tid
)



-- assembling of the finished xml document according to the interlis schema
select xmlelement(name "TRANSFER", xmlattributes('http://www.interlis.ch/INTERLIS2.3' as xmlns),
    xmlelement(name "HEADERSECTION",
        xmlattributes('altlast4web' as "SENDER", '2.3' as "VERSION"),
          xmlelement(name "MODELS", -- need to add all used models by hand
              xmlelement(name "MODEL",xmlattributes('CoordSys' as "NAME",'2015-11-24' as "VERSION",'https://www.interlis.ch/models' as "URI")),
              xmlelement(name "MODEL",xmlattributes('InternationalCodes_V1' as "NAME",'2011-08-30' as "VERSION",'https://www.geo.admin.ch' as "URI")),
              xmlelement(name "MODEL",xmlattributes('Localisation_V1' as "NAME",'2011-08-30' as "VERSION",'https://www.geo.admin.ch' as "URI")),
              xmlelement(name "MODEL",xmlattributes('LocalisationCH_V1' as "NAME",'2011-08-30' as "VERSION",'https://www.geo.admin.ch' as "URI")),
              xmlelement(name "MODEL",xmlattributes('Dictionaries_V1' as "NAME",'2011-08-30' as "VERSION",'https://www.geo.admin.ch' as "URI")),
              xmlelement(name "MODEL",xmlattributes('DictionariesCH_V1' as "NAME",'2011-08-30' as "VERSION",'https://www.geo.admin.ch' as "URI")),
              xmlelement(name "MODEL",xmlattributes('Units' as "NAME",'2012-02-20' as "VERSION",'https://www.interlis.ch/models' as "URI")),
              xmlelement(name "MODEL",xmlattributes('GeometryCHLV95_V1' as "NAME",'2015-11-12' as "VERSION",'https://www.geo.admin.ch' as "URI")),
              xmlelement(name "MODEL",xmlattributes('SO_AFU_KbS_Publikation_restricted_20221209' as "NAME",'2023-01-04' as "VERSION",'https://afu.so.ch' as "URI"))
          )
    ),
   
    xmlelement(name "DATASECTION",
        xmlelement(name "model_so.Belastete_Standorte",-- there is no attribute that could server as a bucket-identifier. so we generate an artiffical one.
            xmlattributes((select bid from bidprops) as "BID"),
                ( select xmlagg(x) from standorte_xml_v15)
        )
    )

);

$_$;


--
-- Name: export_geoview(integer[]); Type: FUNCTION; Schema: altlast_ili; Owner: -
--

CREATE FUNCTION altlast_ili.export_geoview(p_vflz_ids integer[]) RETURNS xml
    LANGUAGE sql
    AS $_$
-- sites in xml form
with                                            
standorte_xml as (                                
    select xmlelement(name "geoview.Belastete_Standorte_fuer_Geoviewer.Belasteter_Standort",                          
          xmlattributes(vflgeo_id as "vflgeo_id"),
          xmlelement(name "vflz_id", vflz_id),    
          xmlelement(name "staonr", staonr),      
          xmlelement(name "Katasternummer", staonr),              
          xmlelement(name "staotyp", staotyp),    
      xmlelement(name "Standorttyp",              
      case when staotyp = 'Ablagerungsstandort' then 'StaoTyp1'   
      when staotyp = 'Betriebsstandort' then 'StaoTyp2'           
      when staotyp = 'Unfallstandort' then 'StaoTyp3'             
      when staotyp = 'Schiessanlagen' then 'StaoTyp4' end),       
          xmlelement(name "h_gem_id", h_gem_id),  
          xmlelement(name "gemeinde", gemeinde),  
          xmlelement(name "beweart5", beweart5),  
          xmlelement(name "beweart8", beweart8),  
          xmlelement(name "StatusAltlV", case     
            when c_bere_res_abwbewe = 'BLKR14' then 'StatusAltlV1'
            when c_bere_res_abwbewe = 'BLKR13' then 'StatusAltlV2'
            when c_bere_res_abwbewe = 'BLKR06' then 'StatusAltlV3'
            when c_bere_res_abwbewe = 'BLKR07' then 'StatusAltlV4'
            when c_bere_res_abwbewe = 'BLKR08' then 'StatusAltlV5'
            when c_bere_res_abwbewe = 'BLKR05' then 'StatusAltlV6'
            else null end),                       
          xmlelement(name "ustand", ustand),      
          xmlelement(name "Untersuchungsmassnahmen",              
              case when ustand is null or ustand = '' then 'UntMassn1'                    
                            
              when ustand LIKE 'Historische%' then 'UntMassn2'    
              when ustand LIKE 'Technische%' then 'UntMassn3'     
              when ustand LIKE 'Detailuntersuchung%' then 'UntMassn4'                     
                            
              when ustand LIKE 'Überwachung%' then 'UntMassn5'    
              when ustand LIKE 'Sanierung%' then 'UntMassn6' end),
          xmlelement(name "zeitraum", zeitraum),  
          xmlelement(name "Ersteintrag", ersteintrag),            
          xmlelement(name "LetztePublikation", letzte_publikation),                       
                            
      xmlelement(name "Rechtsstatus",             
      case when ersteintrag LIKE 'rechtskräftig%' then 'inKraft'  
      else 'laufendeAenderung' end),              
      case when staotyp = 'Ablagerungsstandort' then              
        xmlelement(name "Deponietyp", c_vflz_deponietyp)          
      end,                                        
      case when staotyp = 'Ablagerungsstandort' then              
        xmlelement(name "InBetrieb", case when c_vflz_inbetrieb = '01' then true::text else false::text end)          
      end,                                        
      case when staotyp = 'Ablagerungsstandort' then              
        xmlelement(name "Nachsorge", case when c_vflz_nachsorge = '01' then true::text else false::text end)          
      end,                                        
          xmlelement(name "symbol", symbol),      
          case when wkb_geometry is not null then 
                case when st_geometrytype(wkb_geometry) = 'ST_Point' then                 
                            
                    xmlelement(name "Geo_Lage_Punkt", altlast_ili.geometry(wkb_geometry)) 
                            
                else                              
                    xmlelement(name "Geo_Lage_Polygon", altlast_ili.geometry(wkb_geometry)
)                           
                end                               
          end                                     
  ) as x FROM altlast.kbs_public_v where vflz_id = any($1))       
                                                  
   -- assembling of the finished xml document according to the interlis schema            
                            
select xmlelement(name "TRANSFER",                
   xmlattributes('http://www.interlis.ch/INTERLIS2.3' as xmlns),  
   xmlelement(name "HEADERSECTION",               
        xmlattributes('altlast4web' as "SENDER", '2.3' as "VERSION"),                     
                            
        xmlelement(name "MODELS",                 
            -- need to add all used models by hand
            xmlelement(name "MODEL",              
                xmlattributes(                    
                    'GeometryCHLV95_V1' as "NAME",
                    'http://models.geo.admin.ch/CH/CHBase_Part1_GEOMETRY_20110830.ili' as "URI",                      
                    '2011-08-30' as "VERSION"     
                )                                 
            ),                                    
            xmlelement(name "MODEL",              
                xmlattributes(                    
                    'LocalisationCH_V1' as "NAME",
                    'http://models.geo.admin.ch/CH/CHBase_Part2_LOCALISATION_20110830.ili' as "URI",                  
                    '2011-08-30' as "VERSION"     
                )                                 
            ),                                    
            xmlelement(name "MODEL",              
                xmlattributes(                    
                    'geoview' as "NAME",          
                    'https://altlast.bl.ch/interlis_exports/models/KbS_Basis_V1_3_geoviewer_internal.ili' as "URI",   
                    '2017-04-12' as "VERSION"     
                )                                 
            )                                     
        )                                         
   ),                                             
   xmlelement(name "DATASECTION",                 
        /* comment containing all affected vflz_ids. this has to be removed from the ouptu
t as it                     
           will caus ea buffer overflow in the intelischecker :)))
        xmlcomment('Generated when exporting the following vflz_ids' || $1::text),      
                            
        */                                        
        xmlelement(name "geoview.Belastete_Standorte_fuer_Geoviewer",                     
                            
            -- there is no attribute that could server as a bucket-identifier. so we generate an artiffical one.      
            xmlattributes('bs'||extract(epoch from current_timestamp)::integer::text as "BID"),                       
            ( select xmlagg(x) from standorte_xml)),              
        /*                                        
        xmlelement(name "CoordSys.CoordsysTopic", 
           xmlattributes('cs868' as "BID")        
        ),                                        
        */                                        
        xmlelement(name "KbS_Basis_V1_3.Codelisten",              
           xmlattributes('ch.admin.bafu.kbs_codetexte_v1_3' as "BID"), 
           xmlcomment('Codes for codelist with c_cli_id = 20333'),         
            (select xmlagg(x) from (              
               select xmlelement(name "KbS_Basis_V1_3.Codelisten.Deponietyp_Definition",  
                            
                    xmlattributes( cod_long.code_long as "TID"),  
                    xmlelement(name "Code", cod_long.code_long),  
                    xmlelement(name "Definition", 
                        altlast_ili.geoig_localisedtext_code(cod.c_cli_id, cod.code::text)
                            
                    )                             
                    ) as x                        
                from altlast.cod as cod           
                join altlast_ili.cod_long on cod_long.code = cod.code and cod_long.c_cli_id = cod.c_cli_id            
                where cod.c_cli_id = 20333 ) cle )
, xmlcomment('Codes for codelist with c_cli_id = 20063'),         
            (select xmlagg(x) from (              
               select xmlelement(name "KbS_Basis_V1_3.Codelisten.Standorttyp_Definition", 
                            
                    xmlattributes( cod_long.code_long as "TID"),  
                    xmlelement(name "Code", cod_long.code_long),  
                    xmlelement(name "Definition", 
                        altlast_ili.geoig_localisedtext_code(cod.c_cli_id, cod.code::text)
                            
                    )                             
                    ) as x                        
                from altlast.cod as cod           
                join altlast_ili.cod_long on cod_long.code = cod.code and cod_long.c_cli_id = cod.c_cli_id            
                where cod.c_cli_id = 20063 ) cle )
, xmlcomment('Codes for codelist with c_cli_id = 20103'),         
            (select xmlagg(x) from (              
               select xmlelement(name "KbS_Basis_V1_3.Codelisten.StatusAltlV_Definition", 
                            
                    xmlattributes( cod_long.code_long as "TID"),  
                    xmlelement(name "Code", cod_long.code_long),  
                    xmlelement(name "Definition", 
                        altlast_ili.geoig_localisedtext_code(cod.c_cli_id, cod.code::text)
                            
                    ),                            
                    xmlelement(name "Symbol",     
                      xmlelement(name "BINBLBOX", symbol.symbol)  
                    )                             
                    ) as x                        
                from altlast.cod as cod           
                join altlast_ili.cod_long on cod_long.code = cod.code and cod_long.c_cli_id = cod.c_cli_id            
                join altlast_ili.symbol on symbol.code = cod.code and symbol.c_cli_id = cod.c_cli_id                  
                where cod.c_cli_id = 20103 ) cle )
, xmlcomment('Codes for codelist with c_cli_id = 20023'),         
            (select xmlagg(x) from (              
               select xmlelement(name "KbS_Basis_V1_3.Codelisten.Untersuchungsmassnahmen_Definition",                 
                    xmlattributes( cod_long.code_long as "TID"),  
                    xmlelement(name "Code", cod_long.code_long),  
                    xmlelement(name "Definition", 
                        altlast_ili.geoig_localisedtext_code(cod.c_cli_id, cod.code::text)
                            
                    )                             
                    ) as x                        
                from altlast.cod as cod           
                join altlast_ili.cod_long on cod_long.code = cod.code and cod_long.c_cli_id = cod.c_cli_id            
                where cod.c_cli_id = 20023 ) cle )
--[[[end]]]                                       
        )                                         
        )                                         
   );                                             
$_$;


--
-- Name: export_internal_data(integer[]); Type: FUNCTION; Schema: altlast_ili; Owner: -
--

CREATE FUNCTION altlast_ili.export_internal_data(p_vflz_ids integer[]) RETURNS xml
    LANGUAGE sql
    AS $_$
-- sites in xml form                           
with                                              
standorte_xml as (                                
    select xmlelement(name "internal.Belastete_Standorte_internal.Belasteter_Standort",                            
          xmlattributes(vflgeo_id as "vflgeo_id"),
          xmlelement(name "vflz_id", vflz_id),    
          xmlelement(name "vflz_combined_id_kt", vflz_combined_id_kt),              
                               
          xmlelement(name "obje_bezeichnung", obje_bezeichnung),
          xmlelement(name "c_vflz_vftyp", c_vflz_vftyp),        
          xmlelement(name "Standorttyp",          
          case when c_vflz_vftyp = '01' then 'StaoTyp1'         
          when c_vflz_vftyp = '02' then 'StaoTyp2'
          when c_vflz_vftyp = '03' then 'StaoTyp3'
          when c_vflz_vftyp = '04' then 'StaoTyp4' end),        
          xmlelement(name "vftyp",vftyp),         
          xmlelement(name "c_vflz_bearbstand", c_vflz_bearbstand),                  
                               
          xmlelement(name "c_bewertung", c_bewertung),          
          xmlelement(name "StatusAltlV",          
          case when c_bewertung = 'BLKR14' then 'StatusAltlV1'  
          when c_bewertung = 'BLKR13' then 'StatusAltlV2'       
          when c_bewertung = 'BLKR06' then 'StatusAltlV3'       
          when c_bewertung = 'BLKR07' then 'StatusAltlV4'       
          when c_bewertung = 'BLKR08' then 'StatusAltlV5'       
          when c_bewertung = 'BLKR05' then 'StatusAltlV6'       
          else null::text end),                   
          xmlelement(name "bewertung", bewertung),
          xmlelement(name "bearbstand", bearbstand),            
          xmlelement(name "c_vflz_unterstand", c_vflz_unterstand),                  
                               
          xmlelement(name "unterstand", unterstand),            
          xmlelement(name "h_gem_id", h_gem_id),  
          xmlelement(name "gemeinde", gemeinde),  
                                                  
      case when vftyp = 'Ablagerungsstandort' then
        xmlelement(name "Deponietyp", c_vflz_deponietyp)        
      end,                                        
      case when vftyp = 'Ablagerungsstandort' then
        xmlelement(name "InBetrieb",              
                case when c_vflz_inbetrieb = '01' then true::text                   
                               
                else false::text end)             
      end,                                        
      case when vftyp = 'Ablagerungsstandort' then
        xmlelement(name "Nachsorge",              
                case when c_vflz_nachsorge = '01' then true::text                   
                               
                else false::text end)             
      end,                                        
          case when wkb_geometry is not null then 
                case when st_geometrytype(wkb_geometry) = 'ST_Point' then           
                               
                    xmlelement(name "Geo_Lage_Punkt", altlast_ili.geometry(wkb_geometry))                          
                else                              
                    xmlelement(name "Geo_Lage_Polygon", altlast_ili.geometry(wkb_geometry))                        
                end                               
          end                                     
  ) as x FROM altlast.vflgeo_bud_parzis_v)        
                                                  
   -- assembling of the finished xml document according to the interlis schema      
                               
select xmlelement(name "TRANSFER",                
   xmlattributes('http://www.interlis.ch/INTERLIS2.3' as xmlns),
   xmlelement(name "HEADERSECTION",               
        xmlattributes('altlast4web' as "SENDER", '2.3' as "VERSION"),               
                               
        xmlelement(name "MODELS",                 
            -- need to add all used models by hand
            xmlelement(name "MODEL",              
                xmlattributes(                    
                    'internal' as "NAME",         
                    '' as "URI",                  
                    '' as "VERSION"               
                )                                 
            ),                                    
            xmlelement(name "MODEL",              
                xmlattributes(                    
                    'GeometryCHLV95_V1' as "NAME",
                    'http://models.geo.admin.ch/CH/CHBase_Part1_GEOMETRY_20110830.ili' as "URI",                   
                    '2011-08-30' as "VERSION"     
                )                                 
            ),                                    
            xmlelement(name "MODEL",              
                xmlattributes(                    
                    'LocalisationCH_V1' as "NAME",
                    'http://models.geo.admin.ch/CH/CHBase_Part2_LOCALISATION_20110830.ili' as "URI",               
                    '2011-08-30' as "VERSION"     
                )                                 
            )                                     
        )                                         
   ),                                             
   xmlelement(name "DATASECTION",                 
        /* comment containing all affected vflz_ids. this has to be removed from the
 ouptut as it                  
           will caus ea buffer overflow in the intelischecker :)))                  
                               
        xmlcomment('Generated when exporting the following vflz_ids: ' || $1::text),
                               
        */                                        
        xmlelement(name "internal.Belastete_Standorte_internal",
            -- there is no attribute that could server as a bucket-identifier. so wegenerate an artiffical one.   
            xmlattributes('bs'||extract(epoch from current_timestamp)::integer::text as "BID"),                    
            ( select xmlagg(x) from standorte_xml)),            
        /*                                        
        xmlelement(name "CoordSys.CoordsysTopic", 
           xmlattributes('cs868' as "BID")        
        ),                                        
        */                                        
        xmlelement(name "KbS_Basis_V1_3.Codelisten",            
           xmlattributes('ch.admin.bafu.kbs_codetexte_v1_3' as "BID")               
                              
, xmlcomment('Codes for codelist with c_cli_id = 20333'),       
            (select xmlagg(x) from (              
               select xmlelement(name "KbS_Basis_V1_3.Codelisten.Deponietyp_Definition",                           
                    xmlattributes( cod_long.code_long as "TID"),
                    xmlelement(name "Code", cod_long.code_long),
                    xmlelement(name "Definition", 
                        altlast_ili.geoig_localisedtext_code(cod.c_cli_id, cod.code::text)                         
                    )                             
                    ) as x                        
                from altlast.cod as cod           
                join altlast_ili.cod_long on cod_long.code = cod.code and cod_long.c_cli_id = cod.c_cli_id         
                where cod.c_cli_id = 20333 ) cle )
, xmlcomment('Codes for codelist with c_cli_id = 20063'),       
            (select xmlagg(x) from (              
               select xmlelement(name "KbS_Basis_V1_3.Codelisten.Standorttyp_Definition",                          
                    xmlattributes( cod_long.code_long as "TID"),
                    xmlelement(name "Code", cod_long.code_long),
                    xmlelement(name "Definition", 
                        altlast_ili.geoig_localisedtext_code(cod.c_cli_id, cod.code::text)                         
                    )                             
                    ) as x                        
                from altlast.cod as cod           
                join altlast_ili.cod_long on cod_long.code = cod.code and cod_long.c_cli_id = cod.c_cli_id         
                where cod.c_cli_id = 20063 ) cle )
, xmlcomment('Codes for codelist with c_cli_id = 20103'),       
            (select xmlagg(x) from (              
               select xmlelement(name "KbS_Basis_V1_3.Codelisten.StatusAltlV_Definition",                          
                    xmlattributes( cod_long.code_long as "TID"),
                    xmlelement(name "Code", cod_long.code_long),
                    xmlelement(name "Definition", 
                        altlast_ili.geoig_localisedtext_code(cod.c_cli_id, cod.code::text)                         
                    ),                            
                    xmlelement(name "Symbol",     
                      xmlelement(name "BINBLBOX", symbol.symbol)
                    )                             
                    ) as x                        
                from altlast.cod as cod           
                join altlast_ili.cod_long on cod_long.code = cod.code and cod_long.c_cli_id = cod.c_cli_id         
                join altlast_ili.symbol on symbol.code = cod.code and symbol.c_cli_id = cod.c_cli_id               
                where cod.c_cli_id = 20103 ) cle )
, xmlcomment('Codes for codelist with c_cli_id = 20023'),       
            (select xmlagg(x) from (              
               select xmlelement(name "KbS_Basis_V1_3.Codelisten.Untersuchungsmassnahmen_Definition",              
                    xmlattributes( cod_long.code_long as "TID"),
                    xmlelement(name "Code", cod_long.code_long),
                    xmlelement(name "Definition", 
                        altlast_ili.geoig_localisedtext_code(cod.c_cli_id, cod.code::text)                         
                    )                             
                    ) as x                        
                from altlast.cod as cod           
                join altlast_ili.cod_long on cod_long.code = cod.code and cod_long.c_cli_id = cod.c_cli_id         
                where cod.c_cli_id = 20023 ) cle )
--[[[end]]]                                       
        )                                         
        )                                         
   );  
$_$;


--
-- Name: export_oereb(integer[]); Type: FUNCTION; Schema: altlast_ili; Owner: -
--

CREATE FUNCTION altlast_ili.export_oereb(p_vflz_ids integer[]) RETURNS xml
    LANGUAGE sql
    AS $_$


-- attributes for wms
with wmsprops as (
    select
        wms_url as endpoint,
        wms_version,
        wms_layername as layername,
        geoportal_layername as layername_geoportal,
        geoportal_url as url_geoportal,
        geoportal_additional_layers as additional_layers_geoportal
     from altlast_ili.config_wms
     order by config_wms_id limit 1
),

-- wms requests
wmslayerrequest as (
    select
          geo.vflz_id,
          wmsprops.endpoint,
          wmsprops.wms_version,
          wmsprops.url_geoportal,
          wmsprops.additional_layers_geoportal,
          wmsprops.layername,
          -- calculate a boundinbox to fit the geometry in the given image dimensions
          st_xmin(geo.box)::text || ',' || st_ymin(geo.box)::text || ',' ||
                   st_xmax(geo.box)::text || ',' || st_ymax(geo.box)::text as bbox,
          geo.width as image_width,
          geo.height as image_height,
          geo.srid
    from  (
        select vflz_id,
            altlast.scaleextent(st_buffer(vflgeo.wkb_geometry, 10), imagesize.width::double precision/screen_dpi::double precision,
                    imagesize.height::double precision/screen_dpi::double precision)::box2d as box,
            st_srid(vflgeo.wkb_geometry) as srid,
            imagesize.width,
            imagesize.height
            from altlast.vflgeo, (
                -- dimensions of the wms image
                select 740 as width, 500 as height, 96 as screen_dpi
            ) as imagesize
     ) as geo, wmsprops
),

standortwmslinks as (
    select
        wlr.vflz_id,
        wlr.endpoint || '?SERVICE=WMS&REQUEST=GetMap&VERSION=' || wlr.wms_version || '&LAYERS=' || wlr.layername ||
                '&FORMAT=image/png&STYLE=default&SRS=EPSG:' || wlr.srid::text ||
                '&WIDTH=' || wlr.image_width::text || '&HEIGHT=' || wlr.image_height::text ||
                '&BBOX=' ||  wlr.bbox::text as url_getmap,
        -- assemble the url for a getlegend request
        wlr.endpoint || '?SERVICE=WMS&REQUEST=GetLegendGraphic&VERSION=' || wlr.wms_version ||
                '&LAYER=' || wlr.layername || '&FORMAT=image/png&STYLE=default' as url_getlegend
    from wmslayerrequest wlr
),

-- all sites of the list of vflz_ids
standorte as (
    select
        v.vflz_id,
        v.vfl_id,
        v.vflz_combined_id_kt,
        vflnr.org_id,
        v.dat_rechtskraft::date as date_ersteintrag,
        statusaltlv_mapping.code_long as statusaltlv_long,
        statusaltlv_mapping.ili_code as statusaltlv_ili_code,
        statusaltlv_mapping.ili_c_cli_id as statusaltlv_ili_c_cli_id,
        true as rechtsstatus,
        vflgeo.wkb_geometry,
        case when v.x_koordinate is not null and v.y_koordinate is not null then st_makepoint(v.x_koordinate, v.y_koordinate) else st_centroid(vflgeo.wkb_geometry) end as wkb_point,
        -- artifficial transfer ids:
        'geom'||v.vflz_id::text as geom_tid,
        v.c_vflz_vftyp,
        v.h_vflz_vftyp
    from altlast.vflz v
    join altlast.vflz_is_published_v vip on v.vflz_id = vip.vflz_id and vip.is_latest_published /* only published versions */
    join altlast.vflgeo on vflgeo.vflz_id = v.vflz_id
    join altlast.vflnr on v.vflz_id = vflnr.vflz_id and vflnr.aktiv

        -- restrict using the org configured in a4w
    join altlast_admin.setting stng on stng.value = vflnr.org_id::text
    join altlast_admin.setitem sit on sit.setitem_id = stng.setitem_id and sit.key = 'org'

    join altlast.bere_v on bere_v.vflz_id = v.vflz_id
    join altlast_ili.cod_mapping_v statusaltlv_mapping on statusaltlv_mapping.c_cli_id = bere_v.h_bere_res_abwbewe
                and statusaltlv_mapping.code = bere_v.c_bere_res_abwbewe
    where v.vfl_id in (
        select vfl_id from altlast.vflz where vflz_id = any($1)
    )
),

geoportallinks as (
    select
        standorte.vflz_id,
        wmsprops.url_geoportal
                || '?Y=' || st_x(standorte.wkb_point)::text -- coordinates reversed -- not a typo
                || '&X=' || st_y(standorte.wkb_point)::text
                || '&zoom=12'
                || '&bgLayer=' || wmsprops.additional_layers_geoportal
                || '&layers=' || wmsprops.layername_geoportal
                || '&layers_opacity=1'
                || '&bgOpacity=0.8'
                || '&layers_visibility=true' as permalink_geoportal
    from standorte, wmsprops
),

-- org
aemter as (
   select distinct
         coalesce(org.bezeichnung_lang, org.bezeichnung) as behoerde,
         org.url_behoerde as url_behoerde,
         coalesce(org.katastername, org.bezeichnung)::text as katastername,
         org.url_webgis::text as url_webgis,
         org.org_id,
         'amt' || org.org_id::text as tid
     from altlast.org
       /* only load orgs which are referenced from sites*/
     where org.org_id in (select org_id from standorte)
),

darstellungsdiente as (
    select
        'dd' || wmsprops.layername as tid,
        wmsprops.endpoint
            || '?SERVICE=WMS&REQUEST=GetMap'
            || '&VERSION=' || wmsprops.wms_version
            || '&STYLES=' || 'default'
            || '&SRS=' || 'EPSG:21781'
            || '&BBOX=' || '475000,60000,845000,310000'
            || '&WIDTH=' || 740::text
            || '&HEIGHT=' || 500::text
            || '&FORMAT=' || 'image/png'
            || '&LAYERS=' || wmsprops.layername as url_verweiswms,
        wmsprops.endpoint
            || '?SERVICE=WMS&REQUEST=GetLegendGraphic'
            || '&VERSION=' || wmsprops.wms_version
            || '&FORMAT=' || 'image/png'
            || '&LAYER=' || wmsprops.layername as url_legendeimweb
    from wmsprops
),

-- thema
thema as (
    select org.org_id,
        case when org.kuerzel='VBS' then 'BelasteteStandorteMilitaer'
             when org.kuerzel='BAV' then 'BelasteteStandorteOeffentlicherVerkehr'
             when org.kuerzel='BAZL' then 'BelasteteStandorteZivileFlugplaetze'
             else /* Kantone */ 'BelasteteStandorte'
        end as thema
    from altlast.org
),

eigentumsbeschraenkung as (
    select
        standorte.vflz_id,
        staotyp_mapping.code_long as art_code,
        'eb' || standorte.vflz_id::text as tid,
        thema.thema,
                    /* typ: OeREBKRM09.RechtsStatus  enum (inKraft|laufendeAenderung) */
        case when standorte.rechtsstatus then 'inKraft' else 'laufendeAenderung' end as rechtsstatus,
        standorte.date_ersteintrag,
        aemter.tid as aemter_tid,
        (select tid from darstellungsdiente) as darstellungsdiente_tid
    from standorte
    join aemter on aemter.org_id = standorte.org_id
    join thema on thema.org_id = standorte.org_id
    join altlast_ili.cod_mapping_v staotyp_mapping on staotyp_mapping.c_cli_id = standorte.h_vflz_vftyp
                and staotyp_mapping.code = standorte.c_vflz_vftyp
),


rechtsvorschrift as (
    select
        standorte.vflz_id,
        'rv'||standorte.vflz_id::text as tid,
        gpl.permalink_geoportal as web_link,
            /* typ: OeREBKRM09.RechtsStatus  enum (inKraft|laufendeAenderung) */
        case when standorte.rechtsstatus then 'inKraft' else 'laufendeAenderung' end as rechtsstatus,
        standorte.date_ersteintrag::date,
        aemter.katastername,
        aemter.tid as aemter_tid,
        standorte.vflz_combined_id_kt
    from standorte
    join aemter on aemter.org_id = standorte.org_id
    join standortwmslinks swl on swl.vflz_id = standorte.vflz_id
    join geoportallinks gpl on gpl.vflz_id = standorte.vflz_id
),


weitere_dokumente as ( -- issue #4010049 comment 31
    -- Umweltschutzgesetz
    select 'ch.admin.bk.sr.814.01' as dokument_tid
    union
    -- Altlasten-Verordnung
    select 'ch.admin.bk.sr.814.680' as dokument_tid
),

-- status code description in all available languages
statusaltlv_xml as (
    select standorte.vflz_id,
        xmlelement(name "MultilingualText09.MultilingualMText",
           xmlelement(name "localizedText",
              xmlagg(xmlelement(name "MultilingualText09.LocalizedMText",
                  xmlelement(name "Language", lower(translations.locale)),
                  xmlelement(name "Text", translations.msgstr)
              ))
           )
        ) as x
    from standorte
    join altlast.translations on translations.msgid = altlast.msgid_code(standorte.statusaltlv_ili_c_cli_id, standorte.statusaltlv_ili_code)
    group by standorte.vflz_id
),
aemter_xml as (
    select xmlelement(name "OeREBKRM09vs.Vorschriften.Amt",
                xmlattributes(aemter.tid as "TID"),
                xmlelement(name "Name", altlast_ili.oereb_localisedtext_t(aemter.behoerde, array['de', 'fr', 'it'])),
                xmlelement(name "AmtImWeb", aemter.url_behoerde)
    ) as x
    from aemter
),

darstellungsdiente_xml as (
    select xmlelement(name "OeREBKRM09trsfr.Transferstruktur.DarstellungsDienst",
                xmlattributes(darstellungsdiente.tid as "TID"),
                xmlelement(name "VerweisWMS", darstellungsdiente.url_verweiswms),
                xmlelement(name "LegendeImWeb", darstellungsdiente.url_legendeimweb)
        ) as x
    from darstellungsdiente
),

eigentumsbeschraenkung_xml as (
    select xmlelement(name "OeREBKRM09trsfr.Transferstruktur.Eigentumsbeschraenkung",
                xmlattributes(eb.tid as "TID"),
                xmlelement(name "Aussage", statusaltlv_xml.x),
                xmlelement(name "Thema", eb.thema),
                xmlelement(name "ArtCode", eb.art_code),
                xmlelement(name "Rechtsstatus",
                    eb.rechtsstatus
                ),
                xmlelement(name "publiziertAb", eb.date_ersteintrag::date),
                xmlelement(name "DarstellungsDienst",
                    xmlattributes( eb.darstellungsdiente_tid as "REF")
                ),
                xmlelement(name "ZustaendigeStelle",
                    xmlattributes( eb.aemter_tid as "REF")
                )
        ) as x
    from eigentumsbeschraenkung eb
    join statusaltlv_xml on statusaltlv_xml.vflz_id = eb.vflz_id
),

rechtsvorschrift_xml as (
    select xmlelement(name "OeREBKRM09vs.Vorschriften.Rechtsvorschrift",
                xmlattributes(rv.tid as "TID"),
                xmlelement(name "TextImWeb", rv.web_link),
                xmlelement(name "Rechtsstatus", rv.rechtsstatus),
                xmlelement(name "publiziertAb", rv.date_ersteintrag::date),
                xmlelement(name "Titel", altlast_ili.oereb_localisedtext_t(rv.vflz_combined_id_kt, array['de', 'fr', 'it'])),
                xmlelement(name "ZustaendigeStelle",
                    xmlattributes( rv.aemter_tid as "REF")
                )
        ) as x
    from rechtsvorschrift rv
),

weitere_dokumente_xml as (
    select xmlelement(name "OeREBKRM09vs.Vorschriften.HinweisWeitereDokumente",
            xmlelement(name "Ursprung",
                xmlattributes(rv.tid as "REF")
            ),
            xmlelement(name "Hinweis",
                xmlattributes(wd.dokument_tid as "REF")
            )
        ) as x
    from rechtsvorschrift rv, weitere_dokumente wd
),

geometrie_xml as (
    select xmlelement(name "OeREBKRM09trsfr.Transferstruktur.Geometrie",
                xmlattributes(standorte.geom_tid as "TID"),
                case when standorte.wkb_geometry is not null then
                    case when st_geometrytype(standorte.wkb_geometry) = 'ST_Point' then
                        xmlelement(name "Punkt", altlast_ili.geometry(standorte.wkb_geometry))
                    else
                        xmlelement(name "Flaeche", altlast_ili.geometry(standorte.wkb_geometry))
                    end
                else
                    xmlelement(name "Punkt", altlast_ili.geometry(standorte.wkb_point))
                end,
                xmlelement(name "Rechtsstatus",
                    /* typ: OeREBKRM09.RechtsStatus  enum (inKraft|laufendeAenderung) */
                    case when standorte.rechtsstatus then 'inKraft' else 'laufendeAenderung' end
                ),
                xmlelement(name "publiziertAb", standorte.date_ersteintrag::date),
                xmlelement(name "Eigentumsbeschraenkung",
                    xmlattributes( eb.tid as "REF")
                ),
                xmlelement(name "ZustaendigeStelle",
                    xmlattributes( aemter.tid as "REF")
                )
        ) as x
    from standorte
    join eigentumsbeschraenkung eb on eb.vflz_id = standorte.vflz_id
    join aemter on aemter.org_id = standorte.org_id

),

hinweisvorschrift_xml as (
    select xmlelement(name "OeREBKRM09trsfr.Transferstruktur.HinweisVorschrift",
        xmlelement(name "Eigentumsbeschraenkung", xmlattributes(eb.tid as "REF") ),
        xmlelement(name "Vorschrift", xmlattributes(rv.tid as "REF") )
    ) as x
    from eigentumsbeschraenkung eb
    join rechtsvorschrift rv on rv.vflz_id = eb.vflz_id
)

-- assembling of the finished xml document according to the interlis schema
select xmlelement(name "TRANSFER",
   xmlattributes('http://www.interlis.ch/INTERLIS2.3' as xmlns),
   xmlelement(name "HEADERSECTION",
        xmlattributes('altlast4web' as "SENDER", '2.3' as "VERSION"),
        xmlelement(name "MODELS",
            xmlelement(name "MODEL",
                xmlattributes(
                    'chGeoId10' as "NAME",
                    '2010-05-03' as "VERSION",
                    'mailto:ce@eisenhutinformatik.ch' as "URI"
                )
            ),
            xmlelement(name "MODEL",
                xmlattributes(
                    'CodeISO' as "NAME",
                    '20060808' as "VERSION",
                    'http://www.kogis.ch' as "URI"
                )
            ),
            xmlelement(name "MODEL",
                xmlattributes(
                    'MultilingualText09' as "NAME",
                    '2010-02-26' as "VERSION",
                    'mailto:ce@eisenhutinformatik.ch' as "URI"
                )
            ),
            xmlelement(name "MODEL",
                xmlattributes(
                    'OeREBKRM09' as "NAME",
                    '2010-10-26' as "VERSION",
                    'mailto:ce@eisenhutinformatik.ch' as "URI"
                )
            ),
            xmlelement(name "MODEL",
                xmlattributes(
                    'OeREBKRM09vs' as "NAME",
                    '2010-10-26' as "VERSION",
                    'mailto:ce@eisenhutinformatik.ch' as "URI"
                )
            ),
            xmlelement(name "MODEL",
                xmlattributes(
                    'OeREBKRM09trsfr' as "NAME",
                    '2010-10-26' as "VERSION",
                    'mailto:ce@eisenhutinformatik.ch' as "URI"
                )
            )
        )
   ),
   xmlelement(name "DATASECTION",
        xmlelement(name "OeREBKRM09trsfr.Transferstruktur",
             xmlattributes('B01' as "BID") ,
             --xmlcomment('OeREBKRM09vs.Vorschriften.Amt'),
             (select xmlagg(x) from aemter_xml),
             --xmlcomment('OeREBKRM09trsfr.Transferstruktur.DarstellungsDienst'),
             (select xmlagg(x) from darstellungsdiente_xml),
             -- not needed xmlcomment('OeREBKRM09trsfr.Transferstruktur.HinweisVorschrift'),
             --xmlcomment('OeREBKRM09trsfr.Transferstruktur.Eigentumsbeschraenkung'),
             (select xmlagg(x) from eigentumsbeschraenkung_xml),
             --xmlcomment('OeREBKRM09vs.Vorschriften.Rechtsvorschrift'),
             (select xmlagg(x) from rechtsvorschrift_xml),
             -- xmlcomment('OeREBKRM09vs.Vorschriften.HinweisWeitereDokumente'),
             (select xmlagg(x) from weitere_dokumente_xml),
             -- not needed xmlcomment('OeREBKRM09vs.Vorschriften.Dokument'),
             --xmlcomment('OeREBKRM09trsfr.Transferstruktur.Geometrie'),
             (select xmlagg(x) from geometrie_xml),
             --xmlcomment('OeREBKRM09trsfr.Transferstruktur.HinweisVorschrift'),
             (select xmlagg(x) from hinweisvorschrift_xml)
             -- what about Dokument (not available in a4w) and the n:m-relation HinweisWeitereDokumente to link them to Rechtsvorschrift
           )
        )
   );
$_$;


--
-- Name: export_oereb_v10(integer[]); Type: FUNCTION; Schema: altlast_ili; Owner: -
--

CREATE FUNCTION altlast_ili.export_oereb_v10(p_vflz_ids integer[]) RETURNS xml
    LANGUAGE sql
    AS $_$


-- attributes for wms
with wmsprops as (
    select
        wms_url as endpoint,
        wms_version,
        wms_layername as layername,
        geoportal_layername as layername_geoportal,
        geoportal_url as url_geoportal,
        geoportal_additional_layers as additional_layers_geoportal
     from altlast_ili.config_wms
     order by config_wms_id limit 1
),

-- wms requests
wmslayerrequest as (
    select
          geo.vflz_id,
          wmsprops.endpoint,
          wmsprops.wms_version,
          wmsprops.url_geoportal,
          wmsprops.additional_layers_geoportal,
          wmsprops.layername,
          -- calculate a boundinbox to fit the geometry in the given image dimensions
          st_xmin(geo.box)::text || ',' || st_ymin(geo.box)::text || ',' ||
                   st_xmax(geo.box)::text || ',' || st_ymax(geo.box)::text as bbox,
          geo.width as image_width,
          geo.height as image_height,
          geo.srid
    from  (
        select vflz_id,
            altlast.scaleextent(st_buffer(vflgeo.wkb_geometry, 10), imagesize.width::double precision/screen_dpi::double precision,
                    imagesize.height::double precision/screen_dpi::double precision)::box2d as box,
            st_srid(vflgeo.wkb_geometry) as srid,
            imagesize.width,
            imagesize.height
            from altlast.vflgeo, (
                -- dimensions of the wms image
                select 740 as width, 500 as height, 96 as screen_dpi
            ) as imagesize
     ) as geo, wmsprops
),

standortwmslinks as (
    select
        wlr.vflz_id,
        wlr.endpoint || '?SERVICE=WMS&REQUEST=GetMap&VERSION=' || wlr.wms_version || '&LAYERS=' || wlr.layername ||
                '&FORMAT=image/png&STYLE=default&SRS=EPSG:' || wlr.srid::text ||
                '&WIDTH=' || wlr.image_width::text || '&HEIGHT=' || wlr.image_height::text ||
                '&BBOX=' ||  wlr.bbox::text as url_getmap,
        -- assemble the url for a getlegend request
        wlr.endpoint || '?SERVICE=WMS&REQUEST=GetLegendGraphic&VERSION=' || wlr.wms_version ||
                '&LAYER=' || wlr.layername || '&FORMAT=image/png&STYLE=default' as url_getlegend
    from wmslayerrequest wlr
),

-- all sites of the list of vflz_ids
standorte as (
    select
        v.vflz_id,
        v.vfl_id,
        v.vflz_combined_id_kt,
        vflnr.org_id,
        v.dat_rechtskraft::date as date_ersteintrag,
        statusaltlv_mapping.code_long as statusaltlv_long,
        statusaltlv_mapping.ili_code as statusaltlv_ili_code,
        statusaltlv_mapping.ili_c_cli_id as statusaltlv_ili_c_cli_id,
        true as rechtsstatus,
        vflgeo.wkb_geometry,
        case when v.x_koordinate is not null and v.y_koordinate is not null then st_makepoint(v.x_koordinate, v.y_koordinate) else st_centroid(vflgeo.wkb_geometry) end as wkb_point,
        -- artifficial transfer ids:
        'geom'||v.vflz_id::text as geom_tid,
        v.c_vflz_vftyp,
        v.h_vflz_vftyp
    from altlast.vflz v
    join altlast.vflz_is_published_v vip on v.vflz_id = vip.vflz_id and vip.is_latest_published /* only published versions */
    join altlast.vflgeo on vflgeo.vflz_id = v.vflz_id
    join altlast.vflnr on v.vflz_id = vflnr.vflz_id and vflnr.aktiv

        -- restrict using the org configured in a4w
    join altlast_admin.setting stng on stng.value = vflnr.org_id::text
    join altlast_admin.setitem sit on sit.setitem_id = stng.setitem_id and sit.key = 'org'

    join altlast.bere_v on bere_v.vflz_id = v.vflz_id
    join altlast_ili.cod_mapping_v statusaltlv_mapping on statusaltlv_mapping.c_cli_id = bere_v.h_bere_res_abwbewe
                and statusaltlv_mapping.code = bere_v.c_bere_res_abwbewe
    where v.vfl_id in (
        select vfl_id from altlast.vflz where vflz_id = any($1)
    )
),

geoportallinks as (
    select
        standorte.vflz_id,
        wmsprops.url_geoportal
                || '?Y=' || st_x(standorte.wkb_point)::text -- coordinates reversed -- not a typo
                || '&X=' || st_y(standorte.wkb_point)::text
                || '&zoom=12'
                || '&bgLayer=' || wmsprops.additional_layers_geoportal
                || '&layers=' || wmsprops.layername_geoportal
                || '&layers_opacity=1'
                || '&bgOpacity=0.8'
                || '&layers_visibility=true' as permalink_geoportal
    from standorte, wmsprops
),

-- org
aemter as (
   select distinct
         coalesce(org.bezeichnung_lang, org.bezeichnung) as behoerde,
         org.url_behoerde as url_behoerde,
         coalesce(org.katastername, org.bezeichnung)::text as katastername,
         org.url_webgis::text as url_webgis,
         org.org_id,
         'amt' || org.org_id::text as tid
     from altlast.org
       /* only load orgs which are referenced from sites*/
     where org.org_id in (select org_id from standorte)
),

darstellungsdiente as (
    select
        'dd' || wmsprops.layername as tid,
        wmsprops.endpoint
            || '?SERVICE=WMS&REQUEST=GetMap'
            || '&VERSION=' || wmsprops.wms_version
            || '&STYLES=' || 'default'
            || '&SRS=' || 'EPSG:21781'
            || '&BBOX=' || '475000,60000,845000,310000'
            || '&WIDTH=' || 740::text
            || '&HEIGHT=' || 500::text
            || '&FORMAT=' || 'image/png'
            || '&LAYERS=' || wmsprops.layername as url_verweiswms,
        wmsprops.endpoint
            || '?SERVICE=WMS&REQUEST=GetLegendGraphic'
            || '&VERSION=' || wmsprops.wms_version
            || '&FORMAT=' || 'image/png'
            || '&LAYER=' || wmsprops.layername as url_legendeimweb
    from wmsprops
),

-- thema
thema as (
    select org.org_id,
        case when org.kuerzel='VBS' then 'BelasteteStandorteMilitaer'
             when org.kuerzel='BAV' then 'BelasteteStandorteOeffentlicherVerkehr'
             when org.kuerzel='BAZL' then 'BelasteteStandorteZivileFlugplaetze'
             else /* Kantone */ 'BelasteteStandorte'
        end as thema
    from altlast.org
),

eigentumsbeschraenkung as (
    select
        standorte.vflz_id,
        staotyp_mapping.code_long as art_code,
        'eb' || standorte.vflz_id::text as tid,
        thema.thema,
                    /* typ: OeREBKRM09.RechtsStatus  enum (inKraft|laufendeAenderung) */
        case when standorte.rechtsstatus then 'inKraft' else 'laufendeAenderung' end as rechtsstatus,
        standorte.date_ersteintrag,
        aemter.tid as aemter_tid,
        (select tid from darstellungsdiente) as darstellungsdiente_tid
    from standorte
    join aemter on aemter.org_id = standorte.org_id
    join thema on thema.org_id = standorte.org_id
    join altlast_ili.cod_mapping_v staotyp_mapping on staotyp_mapping.c_cli_id = standorte.h_vflz_vftyp
                and staotyp_mapping.code = standorte.c_vflz_vftyp
),


rechtsvorschrift as (
    select
        standorte.vflz_id,
        'rv'||standorte.vflz_id::text as tid,
        gpl.permalink_geoportal as web_link,
            /* typ: OeREBKRM09.RechtsStatus  enum (inKraft|laufendeAenderung) */
        case when standorte.rechtsstatus then 'inKraft' else 'laufendeAenderung' end as rechtsstatus,
        standorte.date_ersteintrag::date,
        aemter.katastername,
        aemter.tid as aemter_tid,
        standorte.vflz_combined_id_kt
    from standorte
    join aemter on aemter.org_id = standorte.org_id
    join standortwmslinks swl on swl.vflz_id = standorte.vflz_id
    join geoportallinks gpl on gpl.vflz_id = standorte.vflz_id
),


weitere_dokumente as ( -- issue #4010049 comment 31
    -- Umweltschutzgesetz
    select 'ch.admin.bk.sr.814.01' as dokument_tid
    union
    -- Altlasten-Verordnung
    select 'ch.admin.bk.sr.814.680' as dokument_tid
),

-- status code description in all available languages
statusaltlv_xml as (
    select standorte.vflz_id,
        xmlelement(name "MultilingualText09.MultilingualMText",
           xmlelement(name "localizedText",
              xmlagg(xmlelement(name "MultilingualText09.LocalizedMText",
                  xmlelement(name "Language", lower(translations.locale)),
                  xmlelement(name "Text", translations.msgstr)
              ))
           )
        ) as x
    from standorte
    join altlast.translations on translations.msgid = altlast.msgid_code(standorte.statusaltlv_ili_c_cli_id, standorte.statusaltlv_ili_code)
    group by standorte.vflz_id
),
aemter_xml as (
    select xmlelement(name "OeREBKRM09vs.Vorschriften.Amt",
                xmlattributes(aemter.tid as "TID"),
                xmlelement(name "Name", altlast_ili.oereb_localisedtext_t(aemter.behoerde, array['de', 'fr', 'it'])),
                xmlelement(name "AmtImWeb", aemter.url_behoerde)
    ) as x
    from aemter
),

darstellungsdiente_xml as (
    select xmlelement(name "OeREBKRM09trsfr.Transferstruktur.DarstellungsDienst",
                xmlattributes(darstellungsdiente.tid as "TID"),
                xmlelement(name "VerweisWMS", darstellungsdiente.url_verweiswms),
                xmlelement(name "LegendeImWeb", darstellungsdiente.url_legendeimweb)
        ) as x
    from darstellungsdiente
),

eigentumsbeschraenkung_xml as (
    select xmlelement(name "OeREBKRM09trsfr.Transferstruktur.Eigentumsbeschraenkung",
                xmlattributes(eb.tid as "TID"),
                xmlelement(name "Aussage", statusaltlv_xml.x),
                xmlelement(name "Thema", eb.thema),
                xmlelement(name "ArtCode", eb.art_code),
                xmlelement(name "Rechtsstatus",
                    eb.rechtsstatus
                ),
                xmlelement(name "publiziertAb", eb.date_ersteintrag::date),
                xmlelement(name "DarstellungsDienst",
                    xmlattributes( eb.darstellungsdiente_tid as "REF")
                ),
                xmlelement(name "ZustaendigeStelle",
                    xmlattributes( eb.aemter_tid as "REF")
                )
        ) as x
    from eigentumsbeschraenkung eb
    join statusaltlv_xml on statusaltlv_xml.vflz_id = eb.vflz_id
),

rechtsvorschrift_xml as (
    select xmlelement(name "OeREBKRM09vs.Vorschriften.Rechtsvorschrift",
                xmlattributes(rv.tid as "TID"),
                xmlelement(name "TextImWeb", rv.web_link),
                xmlelement(name "Rechtsstatus", rv.rechtsstatus),
                xmlelement(name "publiziertAb", rv.date_ersteintrag::date),
                xmlelement(name "Titel", altlast_ili.oereb_localisedtext_t(rv.vflz_combined_id_kt, array['de', 'fr', 'it'])),
                xmlelement(name "ZustaendigeStelle",
                    xmlattributes( rv.aemter_tid as "REF")
                )
        ) as x
    from rechtsvorschrift rv
),

weitere_dokumente_xml as (
    select xmlelement(name "OeREBKRM09vs.Vorschriften.HinweisWeitereDokumente",
            xmlelement(name "Ursprung",
                xmlattributes(rv.tid as "REF")
            ),
            xmlelement(name "Hinweis",
                xmlattributes(wd.dokument_tid as "REF")
            )
        ) as x
    from rechtsvorschrift rv, weitere_dokumente wd
),

geometrie_xml as (
    select xmlelement(name "OeREBKRM09trsfr.Transferstruktur.Geometrie",
                xmlattributes(standorte.geom_tid as "TID"),
                case when standorte.wkb_geometry is not null then
                    case when st_geometrytype(standorte.wkb_geometry) = 'ST_Point' then
                        xmlelement(name "Punkt", altlast_ili.geometry(standorte.wkb_geometry))
                    else
                        xmlelement(name "Flaeche", altlast_ili.geometry(standorte.wkb_geometry))
                    end
                else
                    xmlelement(name "Punkt", altlast_ili.geometry(standorte.wkb_point))
                end,
                xmlelement(name "Rechtsstatus",
                    /* typ: OeREBKRM09.RechtsStatus  enum (inKraft|laufendeAenderung) */
                    case when standorte.rechtsstatus then 'inKraft' else 'laufendeAenderung' end
                ),
                xmlelement(name "publiziertAb", standorte.date_ersteintrag::date),
                xmlelement(name "Eigentumsbeschraenkung",
                    xmlattributes( eb.tid as "REF")
                ),
                xmlelement(name "ZustaendigeStelle",
                    xmlattributes( aemter.tid as "REF")
                )
        ) as x
    from standorte
    join eigentumsbeschraenkung eb on eb.vflz_id = standorte.vflz_id
    join aemter on aemter.org_id = standorte.org_id

),

hinweisvorschrift_xml as (
    select xmlelement(name "OeREBKRM09trsfr.Transferstruktur.HinweisVorschrift",
        xmlelement(name "Eigentumsbeschraenkung", xmlattributes(eb.tid as "REF") ),
        xmlelement(name "Vorschrift", xmlattributes(rv.tid as "REF") )
    ) as x
    from eigentumsbeschraenkung eb
    join rechtsvorschrift rv on rv.vflz_id = eb.vflz_id
)

-- assembling of the finished xml document according to the interlis schema
select xmlelement(name "TRANSFER",
   xmlattributes('http://www.interlis.ch/INTERLIS2.3' as xmlns),
   xmlelement(name "HEADERSECTION",
        xmlattributes('altlast4web' as "SENDER", '2.3' as "VERSION"),
        xmlelement(name "MODELS",
            xmlelement(name "MODEL",
                xmlattributes(
                    'chGeoId10' as "NAME",
                    '2010-05-03' as "VERSION",
                    'mailto:ce@eisenhutinformatik.ch' as "URI"
                )
            ),
            xmlelement(name "MODEL",
                xmlattributes(
                    'CodeISO' as "NAME",
                    '20060808' as "VERSION",
                    'http://www.kogis.ch' as "URI"
                )
            ),
            xmlelement(name "MODEL",
                xmlattributes(
                    'MultilingualText09' as "NAME",
                    '2010-02-26' as "VERSION",
                    'mailto:ce@eisenhutinformatik.ch' as "URI"
                )
            ),
            xmlelement(name "MODEL",
                xmlattributes(
                    'OeREBKRM09' as "NAME",
                    '2010-10-26' as "VERSION",
                    'mailto:ce@eisenhutinformatik.ch' as "URI"
                )
            ),
            xmlelement(name "MODEL",
                xmlattributes(
                    'OeREBKRM09vs' as "NAME",
                    '2010-10-26' as "VERSION",
                    'mailto:ce@eisenhutinformatik.ch' as "URI"
                )
            ),
            xmlelement(name "MODEL",
                xmlattributes(
                    'OeREBKRM09trsfr' as "NAME",
                    '2010-10-26' as "VERSION",
                    'mailto:ce@eisenhutinformatik.ch' as "URI"
                )
            )
        )
   ),
   xmlelement(name "DATASECTION",
        xmlelement(name "OeREBKRM09trsfr.Transferstruktur",
             xmlattributes('B01' as "BID") ,
             --xmlcomment('OeREBKRM09vs.Vorschriften.Amt'),
             (select xmlagg(x) from aemter_xml),
             --xmlcomment('OeREBKRM09trsfr.Transferstruktur.DarstellungsDienst'),
             (select xmlagg(x) from darstellungsdiente_xml),
             -- not needed xmlcomment('OeREBKRM09trsfr.Transferstruktur.HinweisVorschrift'),
             --xmlcomment('OeREBKRM09trsfr.Transferstruktur.Eigentumsbeschraenkung'),
             (select xmlagg(x) from eigentumsbeschraenkung_xml),
             --xmlcomment('OeREBKRM09vs.Vorschriften.Rechtsvorschrift'),
             (select xmlagg(x) from rechtsvorschrift_xml),
             -- xmlcomment('OeREBKRM09vs.Vorschriften.HinweisWeitereDokumente'),
             (select xmlagg(x) from weitere_dokumente_xml),
             -- not needed xmlcomment('OeREBKRM09vs.Vorschriften.Dokument'),
             --xmlcomment('OeREBKRM09trsfr.Transferstruktur.Geometrie'),
             (select xmlagg(x) from geometrie_xml),
             --xmlcomment('OeREBKRM09trsfr.Transferstruktur.HinweisVorschrift'),
             (select xmlagg(x) from hinweisvorschrift_xml)
             -- what about Dokument (not available in a4w) and the n:m-relation HinweisWeitereDokumente to link them to Rechtsvorschrift
           )
        )
   );
$_$;


--
-- Name: export_oereb_v11(integer[]); Type: FUNCTION; Schema: altlast_ili; Owner: -
--

CREATE FUNCTION altlast_ili.export_oereb_v11(p_vflz_ids integer[]) RETURNS xml
    LANGUAGE sql
    AS $_$


-- attributes for wms 
with bidprops as (
    select 
        'kbsOEREB' || org.kuerzel as bid
    from altlast_admin.setitem
    join altlast_admin.setting using (setitem_id)
    join altlast.org on org.org_id=setting.value::int
    where key= 'org'
),


wmsprops as (
    select
        wms_url as endpoint,
        wms_version,
        wms_layername as layername,
        geoportal_layername as layername_geoportal,
        geoportal_url as url_geoportal,
        geoportal_additional_layers as additional_layers_geoportal
     from altlast_ili.config_wms
     order by config_wms_id limit 1
),


wmsprops_2 as (
    select value as url_geoportal
    from altlast_admin.setting s
    join altlast_admin.setitem t using (setitem_id) 
    where t.title = 'URL_Rechtsvorschrift_TextImWeb'
),




-- wms requests
wmslayerrequest as (
    select
          geo.vflz_id,
          wmsprops.endpoint,
          wmsprops.wms_version,
          wmsprops.url_geoportal,
          wmsprops.additional_layers_geoportal,
          wmsprops.layername,
          -- calculate a boundinbox to fit the geometry in the given image dimensions
          st_xmin(geo.box)::text || ',' || st_ymin(geo.box)::text || ',' ||
                   st_xmax(geo.box)::text || ',' || st_ymax(geo.box)::text as bbox,
          geo.width as image_width,
          geo.height as image_height,
          geo.srid
    from  (
        select vflz_id,
            altlast.scaleextent(st_buffer(vflgeo.wkb_geometry, 10), imagesize.width::double precision/screen_dpi::double precision,
                    imagesize.height::double precision/screen_dpi::double precision)::box2d as box,
            st_srid(vflgeo.wkb_geometry) as srid,
            imagesize.width,
            imagesize.height
            from altlast.vflgeo, (
                -- dimensions of the wms image
                select 740 as width, 500 as height, 96 as screen_dpi
            ) as imagesize
     ) as geo, wmsprops
),

standortwmslinks as (
    select
        wlr.vflz_id,
        wlr.endpoint || '?SERVICE=WMS&REQUEST=GetMap&VERSION=' || wlr.wms_version || '&LAYERS=' || wlr.layername ||
                '&FORMAT=image/png&STYLE=default&SRS=EPSG:' || wlr.srid::text ||
                '&WIDTH=' || wlr.image_width::text || '&HEIGHT=' || wlr.image_height::text ||
                '&BBOX=' ||  wlr.bbox::text as url_getmap,
        -- assemble the url for a getlegend request
        wlr.endpoint || '?SERVICE=WMS&REQUEST=GetLegendGraphic&VERSION=' || wlr.wms_version ||
                '&LAYER=' || wlr.layername || '&FORMAT=image/png&STYLE=default' as url_getlegend
    from wmslayerrequest wlr
),

-- all sites of the list of vflz_ids
standorte as (
    select
        v.vflz_id,
        v.vfl_id,
        v.vflz_combined_id_kt,
        vflnr.org_id,
        v.dat_rechtskraft::date as date_ersteintrag,
        statusaltlv_mapping.code_long as statusaltlv_long,
        statusaltlv_mapping.ili_code as statusaltlv_ili_code,
        statusaltlv_mapping.ili_c_cli_id as statusaltlv_ili_c_cli_id,
        true as rechtsstatus,
        (st_dump(vflgeo.wkb_geometry)).geom as wkb_geometry,
        case when v.x_koordinate is not null and v.y_koordinate is not null then st_makepoint(v.x_koordinate, v.y_koordinate) 
            else st_centroid(vflgeo.wkb_geometry) end as wkb_point,
        -- artifficial transfer ids:
        (st_dump(vflgeo.wkb_geometry)).path[1] as laufnummer,
        (st_numgeometries(vflgeo.wkb_geometry)) as numgeom,
        'geom'||v.vflz_id::text as geom_tid,
        'geom'||v.vflz_id::text||'-'||(st_dump(vflgeo.wkb_geometry)).path[1] as geom_tid_laufnummer,
        v.c_vflz_vftyp,
        v.h_vflz_vftyp
    from altlast.vflz v
    join altlast.vflz_is_published_v vip on v.vflz_id = vip.vflz_id and vip.is_latest_published /* only published versions */
    join altlast.vflgeo on vflgeo.vflz_id = v.vflz_id
    join altlast.vflnr on v.vflz_id = vflnr.vflz_id and vflnr.aktiv

        -- restrict using the org configured in a4w
    join altlast_admin.setting stng on stng.value = vflnr.org_id::text
    join altlast_admin.setitem sit on sit.setitem_id = stng.setitem_id and sit.key in ('org', 'astra')

    join altlast.bere_v on bere_v.vflz_id = v.vflz_id
    join altlast_ili.cod_mapping_v statusaltlv_mapping on statusaltlv_mapping.c_cli_id = bere_v.h_bere_res_abwbewe
                and statusaltlv_mapping.code = bere_v.c_bere_res_abwbewe
    where v.vfl_id in (
        select vfl_id from altlast.vflz where vflz_id = any($1)
    )
),

geoportallinks as (
    select
        standorte.vflz_id,
        case when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_TextImWeb_Indikator') = 'standortnummer' then
          wmsprops_2.url_geoportal || (regexp_replace(standorte.vflz_combined_id_kt::text, ' '::text, '%20'::text, 'g'::text)) || '&lang=de'
        when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_TextImWeb_Indikator') = 'xy_koordinates' then
           wmsprops_2.url_geoportal || 'Y=' || st_x(standorte.wkb_point)::text || '&X=' || st_y(standorte.wkb_point)::text || '&lang=de' 
        when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_TextImWeb_Indikator') = 'map_x_map_y_koordinates' then
           wmsprops_2.url_geoportal || 'map_x=' || st_x(standorte.wkb_point)::text || '&map_y=' || st_y(standorte.wkb_point)::text || '&lang=de' 
        when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_TextImWeb_Indikator') = 'c_koordinates' then
           wmsprops_2.url_geoportal || '&c=' || st_x(standorte.wkb_point)::text || ',' || st_y(standorte.wkb_point)::text || '&lang=de' 
        else wmsprops_2.url_geoportal || '&lang=de'
        end as permalink_geoportal_de,
        case when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_TextImWeb_Indikator') = 'standortnummer' then
          wmsprops_2.url_geoportal || (regexp_replace(standorte.vflz_combined_id_kt::text, ' '::text, '%20'::text, 'g'::text)) || '&lang=fr'
        when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_TextImWeb_Indikator') = 'xy_koordinates' then
           wmsprops_2.url_geoportal || 'Y=' || st_x(standorte.wkb_point)::text || '&X=' || st_y(standorte.wkb_point)::text || '&lang=fr' 
        when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_TextImWeb_Indikator') = 'map_x_map_y_koordinates' then
           wmsprops_2.url_geoportal || 'map_x=' || st_x(standorte.wkb_point)::text || '&map_y=' || st_y(standorte.wkb_point)::text || '&lang=fr' 
        when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_TextImWeb_Indikator') = 'c_koordinates' then
           wmsprops_2.url_geoportal || '&c=' || st_x(standorte.wkb_point)::text || ',' || st_y(standorte.wkb_point)::text || '&lang=fr' 
        else wmsprops_2.url_geoportal || '&lang=fr'
        end as permalink_geoportal_fr,
        case when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_TextImWeb_Indikator') = 'standortnummer' then
          wmsprops_2.url_geoportal || (regexp_replace(standorte.vflz_combined_id_kt::text, ' '::text, '%20'::text, 'g'::text)) || '&lang=rm'
        when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_TextImWeb_Indikator') = 'xy_koordinates' then
           wmsprops_2.url_geoportal || 'Y=' || st_x(standorte.wkb_point)::text || '&X=' || st_y(standorte.wkb_point)::text || '&lang=rm' 
        when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_TextImWeb_Indikator') = 'map_x_map_y_koordinates' then
           wmsprops_2.url_geoportal || 'map_x=' || st_x(standorte.wkb_point)::text || '&map_y=' || st_y(standorte.wkb_point)::text || '&lang=rm' 
        when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_TextImWeb_Indikator') = 'c_koordinates' then
           wmsprops_2.url_geoportal || '&c=' || st_x(standorte.wkb_point)::text || ',' || st_y(standorte.wkb_point)::text || '&lang=rm' 
        else wmsprops_2.url_geoportal || '&lang=rm'
        end as permalink_geoportal_rm,
        case when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_TextImWeb_Indikator') = 'standortnummer' then
          wmsprops_2.url_geoportal || (regexp_replace(standorte.vflz_combined_id_kt::text, ' '::text, '%20'::text, 'g'::text)) || '&lang=it'
        when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_TextImWeb_Indikator') = 'xy_koordinates' then
           wmsprops_2.url_geoportal || 'Y=' || st_x(standorte.wkb_point)::text || '&X=' || st_y(standorte.wkb_point)::text || '&lang=it' 
        when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_TextImWeb_Indikator') = 'map_x_map_y_koordinates' then
           wmsprops_2.url_geoportal || 'map_x=' || st_x(standorte.wkb_point)::text || '&map_y=' || st_y(standorte.wkb_point)::text || '&lang=it' 
        when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_TextImWeb_Indikator') = 'c_koordinates' then
           wmsprops_2.url_geoportal || '&c=' || st_x(standorte.wkb_point)::text || ',' || st_y(standorte.wkb_point)::text || '&lang=it' 
        else wmsprops_2.url_geoportal || '&lang=it'
        end as permalink_geoportal_it
    from standorte, wmsprops_2
),

-- org
aemter as (
   select distinct
         coalesce(org.bezeichnung_lang, org.bezeichnung) as behoerde,
         org.url_behoerde as url_behoerde,
         (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'UID_Behoerde_Amt') as uid,
         coalesce(org.katastername, org.bezeichnung)::text as katastername,
         org.url_webgis::text as url_webgis,
         org.org_id,
         'amt' || org.org_id::text as tid
     from altlast.org
       /* only load orgs which are referenced from sites*/
     where org.org_id in (select org_id from standorte)
),

dokumentbasis as (
   select
        owd.dokument_tid as tid,
        owd.beschreibung,
        owd.url_de as web_link_de,
        owd.url_fr as web_link_fr,
        owd.url_fr as web_link_rm,
        owd.url_it as web_link_it,
        owd.rechtsstatus,
        owd.publiziert_ab::date,
        (select tid from aemter) as aemter_tid
    from altlast_ili.oereb_weitere_dokumente owd
    where owd.url_de is not null
),

darstellungsdienste_1 as (
    select
        'dd' || wmsprops.layername as tid
    from wmsprops
),

darstellungsdienste_2 as (
    select
            symbol.code as code,
            symbol.c_cli_id as c_cli_id,
            symbol.symbol as binblbox,
            symbol.thema as thema,
            symbol.def_code as definition,
            symbol.artcodeliste as url_artcodeliste,
            (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'VerweisWMS_Darstellungsdienst') as url_verweiswms
    from altlast_ili.symbol where export = 'oereb'
),


-- thema
thema as (
    select org.org_id,
        case when org.kuerzel='VBS' then 'BelasteteStandorteMilitaer'
             when org.kuerzel='BAV' then 'BelasteteStandorteOeffentlicherVerkehr'
             when org.kuerzel='BAZL' then 'BelasteteStandorteZivileFlugplaetze'
             else /* Kantone */ 'BelasteteStandorte'
        end as thema
    from altlast.org
),

eigentumsbeschraenkung as (
    select
        standorte.vflz_id,
        staotyp_mapping.code_long as art_code,
        standorte.statusaltlv_long as art_code2,
        'https://models.geo.admin.ch/BAFU/KbS_Codetexte_V1_4.xml' as art_codeliste,
        'eb' || standorte.vflz_id::text as tid,
        thema.thema,
                    /* typ: OeREBKRM09.RechtsStatus  enum (inKraft|laufendeAenderung) */
        case when standorte.rechtsstatus then 'inKraft' else 'laufendeAenderung' end as rechtsstatus,
        standorte.date_ersteintrag,
        aemter.tid as aemter_tid,
        (select tid from darstellungsdienste_1) as darstellungsdienste_tid
    from standorte
    join aemter on aemter.org_id = standorte.org_id
    join thema on thema.org_id = standorte.org_id
    join altlast_ili.cod_mapping_v staotyp_mapping on staotyp_mapping.c_cli_id = standorte.h_vflz_vftyp
                and staotyp_mapping.code = standorte.c_vflz_vftyp
    group by standorte.vflz_id, staotyp_mapping.code_long, standorte.statusaltlv_long, 'eb' || standorte.vflz_id::text, thema.thema, standorte.date_ersteintrag, 
    aemter.tid, (select tid from darstellungsdienste_1), standorte.rechtsstatus
),


rechtsvorschrift as (
    select
        standorte.vflz_id,
        'rv'||standorte.vflz_id::text as tid,
        gpl.permalink_geoportal_de as web_link_de,
        gpl.permalink_geoportal_fr as web_link_fr,
        gpl.permalink_geoportal_rm as web_link_rm,
        gpl.permalink_geoportal_it as web_link_it,
            /* typ: OeREBKRM09.RechtsStatus  enum (inKraft|laufendeAenderung) */
        case when standorte.rechtsstatus then 'inKraft' else 'laufendeAenderung' end as rechtsstatus,
        standorte.date_ersteintrag::date,
        aemter.katastername,
        aemter.tid as aemter_tid,
        standorte.vflz_combined_id_kt
    from standorte
    join aemter on aemter.org_id = standorte.org_id
    left join standortwmslinks swl on swl.vflz_id::text = standorte.vflz_id::text
    join geoportallinks gpl on gpl.vflz_id = standorte.vflz_id
    group by standorte.vflz_id, gpl.permalink_geoportal_de, gpl.permalink_geoportal_fr, gpl.permalink_geoportal_rm, gpl.permalink_geoportal_it, standorte.rechtsstatus, standorte.date_ersteintrag::date, 
    aemter.katastername,aemter.tid, standorte.vflz_combined_id_kt
),



weitere_dokumente as (
    select dokument_tid 
    from altlast_ili.oereb_weitere_dokumente
),

-- status code description in all available languages
statusaltlv_xml as (
  select standorte.vflz_id,
        xmlelement(name "LocalisationCH_V1.MultilingualMText",
           xmlelement(name "LocalisedText",
              xmlagg(xmlelement(name "LocalisationCH_V1.LocalisedMText",
                  xmlelement(name "Language", lower(translations.locale)),
                  xmlelement(name "Text", translations.msgstr)
              )order by translations.locale)
            )
        ) as x_v11   
    from standorte
    join altlast.translations on translations.msgid = altlast.msgid_code(standorte.statusaltlv_ili_c_cli_id, standorte.statusaltlv_ili_code)
    group by standorte.vflz_id
),
aemter_xml as (
    select 
  xmlelement(name "OeREBKRMvs_V1_1.Vorschriften.Amt",
                xmlattributes(aemter.tid as "TID"),
                xmlelement(name "Name", altlast_ili.oereb_localisedtext_t_v11(
                  (select case when aemter.org_id = 310 then (select bezeichnung_lang from altlast.org where aemter.org_id = org.org_id)
      else (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'Behoerde_Amt') 
      end as name), 
                  array['de',
                    case when (select org.kuerzel from altlast_admin.setitem join altlast_admin.setting using (setitem_id) join altlast.org on org.org_id=setting.value::int where key= 'org') = 'GR' 
                      then 'rm' 
                    else 'fr' end,
                    'it'
                  ]
                  )),
                xmlelement(name "AmtImWeb", (select case when aemter.org_id = 310 then (select url_behoerde from altlast.org where aemter.org_id = org.org_id)
        else (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_Behoerde_Amt')
        end as amtimweb)),
                xmlelement(name "UID", (select case when aemter.org_id = 310 then (select uid from altlast.org where aemter.org_id = org.org_id)
  else aemter.uid
  end as uid ))
  ) as x_v11
    from aemter
),

dokumentbasis_xml as (
  select 
        xmlelement(name "OeREBKRMvs_V1_1.Vorschriften.Dokument",
                xmlattributes(db.tid as "TID"),
                xmlelement(name "Titel", altlast_ili.oereb_localisedtext_t_v11(db.beschreibung, 
                  array['de',
                    case when (select org.kuerzel from altlast_admin.setitem join altlast_admin.setting using (setitem_id) join altlast.org on org.org_id=setting.value::int where key= 'org') = 'GR' 
                      then 'rm' 
                    else 'fr' end,
                    'it'
                  ]
                  )),
                xmlelement(name "TextImWeb", 
                    xmlelement(name "OeREBKRM_V1_1.MultilingualUri",
                        xmlelement(name "LocalisedText",
                            xmlelement(name "OeREBKRM_V1_1.LocalisedUri",
                                xmlelement(name "Language", 'de'),
                                xmlelement(name "Text", db.web_link_de)
                            ), 
                            xmlelement(name "OeREBKRM_V1_1.LocalisedUri",   
                                case when (select org.kuerzel from altlast_admin.setitem join altlast_admin.setting using (setitem_id) join altlast.org on org.org_id=setting.value::int where key= 'org') = 'GR' 
                                 then xmlelement(name "Language", 'rm')
                                else xmlelement(name "Language", 'fr') end,
                                case when (select org.kuerzel from altlast_admin.setitem join altlast_admin.setting using (setitem_id) join altlast.org on org.org_id=setting.value::int where key= 'org') = 'GR' 
                                 then xmlelement(name "Text", db.web_link_rm)
                                else xmlelement(name "Text", db.web_link_fr) end
                            ),
                            xmlelement(name "OeREBKRM_V1_1.LocalisedUri",
                                xmlelement(name "Language", 'it'),
                                xmlelement(name "Text", db.web_link_it)
                            )
                        )
                    )
                ),
                xmlelement(name "Rechtsstatus", db.rechtsstatus),
                xmlelement(name "publiziertAb", db.publiziert_ab::date),
                xmlelement(name "ZustaendigeStelle",
                    xmlattributes( db.aemter_tid as "REF")
                )
        ) as x_v11
    from dokumentbasis db
),


darstellungsdienste_xml as (
    select 
        xmlelement(name "OeREBKRMtrsfr_V1_1.Transferstruktur.DarstellungsDienst",
                xmlattributes(darstellungsdienste_1.tid as "TID"),
                xmlelement(name "VerweisWMS", darstellungsdienste_2.url_verweiswms),
                xmlelement(name "Legende", 
      xmlagg(xmlelement(name "OeREBKRMtrsfr_V1_1.Transferstruktur.LegendeEintrag", 
          xmlelement(name "Symbol",
            xmlelement(name "BINBLBOX",darstellungsdienste_2.binblbox)),
          xmlelement(name "LegendeText", altlast_ili.oereb_localisedtext_t_v11(altlast.msgid_code(darstellungsdienste_2.c_cli_id, darstellungsdienste_2.code), 
            array['de',
              case when (select org.kuerzel from altlast_admin.setitem join altlast_admin.setting using (setitem_id) join altlast.org on org.org_id=setting.value::int where key= 'org') = 'GR' 
                then 'rm' 
                else 'fr' end,
                'it'
              ]
            )),
          xmlelement(name "ArtCode", darstellungsdienste_2.definition),
          xmlelement(name "ArtCodeliste", darstellungsdienste_2.url_artcodeliste),
          xmlelement(name "Thema", darstellungsdienste_2.thema)
        )
      )
    )     
        ) as x_v11
    from darstellungsdienste_1, darstellungsdienste_2
    group by darstellungsdienste_1.tid, darstellungsdienste_2.url_verweiswms
),

eigentumsbeschraenkung_xml as (
    select 
        xmlelement(name "OeREBKRMtrsfr_V1_1.Transferstruktur.Eigentumsbeschraenkung",
                xmlattributes(eb.tid as "TID"),
                xmlelement(name "Aussage", statusaltlv_xml.x_v11),
                xmlelement(name "Thema", eb.thema),
                xmlelement(name "ArtCode", eb.art_code2),
                xmlelement(name "ArtCodeliste", eb.art_codeliste),
                xmlelement(name "Rechtsstatus",
                    eb.rechtsstatus
                ),
                xmlelement(name "publiziertAb", eb.date_ersteintrag::date),
                xmlelement(name "DarstellungsDienst",
                    xmlattributes( eb.darstellungsdienste_tid as "REF")
                ),
                xmlelement(name "ZustaendigeStelle",
                    xmlattributes( eb.aemter_tid as "REF")
                )
        ) as x_v11 
    from eigentumsbeschraenkung eb
    join statusaltlv_xml on statusaltlv_xml.vflz_id = eb.vflz_id
),

rechtsvorschrift_xml as (
    select 
        xmlelement(name "OeREBKRMvs_V1_1.Vorschriften.Rechtsvorschrift",
                xmlattributes(rv.tid as "TID"),
                xmlelement(name "TextImWeb", 
                    xmlelement(name "OeREBKRM_V1_1.MultilingualUri",
                        xmlelement(name "LocalisedText",
                            xmlelement(name "OeREBKRM_V1_1.LocalisedUri",
                                xmlelement(name "Language", 'de'),
                                xmlelement(name "Text", rv.web_link_de)
                            ), 
                            xmlelement(name "OeREBKRM_V1_1.LocalisedUri",   
                                case when (select org.kuerzel from altlast_admin.setitem join altlast_admin.setting using (setitem_id) join altlast.org on org.org_id=setting.value::int where key= 'org') = 'GR' 
                                 then xmlelement(name "Language", 'rm')
                                else xmlelement(name "Language", 'fr') end,
                                case when (select org.kuerzel from altlast_admin.setitem join altlast_admin.setting using (setitem_id) join altlast.org on org.org_id=setting.value::int where key= 'org') = 'GR' 
                                 then xmlelement(name "Text", rv.web_link_rm)
                                else xmlelement(name "Text", rv.web_link_fr) end
                            ),
                            xmlelement(name "OeREBKRM_V1_1.LocalisedUri",
                                xmlelement(name "Language", 'it'),
                                xmlelement(name "Text", rv.web_link_it)
                            )
                        )
                    )
                ),
                xmlelement(name "Rechtsstatus", rv.rechtsstatus),
                xmlelement(name "publiziertAb", rv.date_ersteintrag::date),
                xmlelement(name "Titel", altlast_ili.oereb_localisedtext_t_v11(rv.vflz_combined_id_kt, 
                  array['de',
                    case when (select org.kuerzel from altlast_admin.setitem join altlast_admin.setting using (setitem_id) join altlast.org on org.org_id=setting.value::int where key= 'org') = 'GR' 
                      then 'rm' 
                    else 'fr' end,
                    'it'
                  ]
                )),
                xmlelement(name "ZustaendigeStelle",
                    xmlattributes( rv.aemter_tid as "REF")
                )
        ) as x_v11
    from rechtsvorschrift rv
),

weitere_dokumente_xml as (
    select 
        xmlelement(name "OeREBKRMvs_V1_1.Vorschriften.HinweisWeitereDokumente",
            xmlelement(name "Ursprung",
                xmlattributes(rv.tid as "REF")
            ),
            xmlelement(name "Hinweis",
                xmlattributes(wd.dokument_tid as "REF")
            )
        ) as x_v11
    from rechtsvorschrift rv, weitere_dokumente wd
),

geometrie_xml as (
    select 
        xmlelement(name "OeREBKRMtrsfr_V1_1.Transferstruktur.Geometrie",
                xmlattributes(case when standorte.numgeom > 1 then standorte.geom_tid_laufnummer 
            else standorte.geom_tid end as "TID"),
                case when standorte.geom_tid is not null then
                    case when st_geometrytype(standorte.wkb_geometry) = 'ST_Point' then
                        xmlelement(name "Punkt_LV03", altlast_ili.oereb_geometry(ST_Transform((standorte.wkb_geometry), 21781)))
                    else
                        xmlelement(name "Flaeche_LV03", altlast_ili.oereb_geometry(ST_Transform((standorte.wkb_geometry), 21781)))
                    end
                else
                    xmlelement(name "Punkt_LV03", altlast_ili.oereb_geometry(ST_Transform((standorte.wkb_geometry), 21781)))
                end,
                case when standorte.wkb_geometry is not null then
                    case when st_geometrytype(standorte.wkb_geometry) = 'ST_Point' then
                        xmlelement(name "Punkt_LV95", altlast_ili.oereb_geometry(ST_Transform((standorte.wkb_geometry), 2056)))
                    else
                        xmlelement(name "Flaeche_LV95", altlast_ili.oereb_geometry(ST_Transform((standorte.wkb_geometry), 2056)))
                    end
                else
                    xmlelement(name "Punkt_LV95", altlast_ili.oereb_geometry(ST_Transform((standorte.wkb_geometry), 2056)))
                end,
                xmlelement(name "Rechtsstatus",
                    /* typ: OeREBKRM09.RechtsStatus  enum (inKraft|laufendeAenderung) */
                    case when standorte.rechtsstatus then 'inKraft' else 'laufendeAenderung' end
                ),
                xmlelement(name "publiziertAb", standorte.date_ersteintrag::date),
                xmlelement(name "Eigentumsbeschraenkung",
                    xmlattributes( eb.tid as "REF")
                ),
                xmlelement(name "ZustaendigeStelle",
                    xmlattributes( aemter.tid as "REF")
                )
        ) as x_v11
    from standorte
    join eigentumsbeschraenkung eb on eb.vflz_id = standorte.vflz_id
    join aemter on aemter.org_id = standorte.org_id

),

hinweisvorschrift_xml as (
    select 
  xmlelement(name "OeREBKRMtrsfr_V1_1.Transferstruktur.HinweisVorschrift",
    xmlelement(name "Eigentumsbeschraenkung", xmlattributes(eb.tid as "REF") ),
    xmlelement(name "Vorschrift", xmlattributes(rv.tid as "REF") )
  ) as x_v11
    from eigentumsbeschraenkung eb
    join rechtsvorschrift rv on rv.vflz_id = eb.vflz_id
)

-- assembling of the finished xml document according to the interlis schema
select xmlelement(name "TRANSFER", xmlattributes('http://www.interlis.ch/INTERLIS2.3' as xmlns),
   xmlelement(name "HEADERSECTION",
        xmlattributes('altlast4web' as "SENDER", '2.3' as "VERSION"),
    xmlelement(name "MODELS",
        xmlelement(name "MODEL",xmlattributes('CoordSys' as "NAME",'2015-11-24' as "VERSION",'https://www.interlis.ch/models' as "URI")),
        xmlelement(name "MODEL",xmlattributes('CatalogueObjects_V1' as "NAME",'2011-08-30' as "VERSION",'https://www.geo.admin.ch' as "URI")),
        xmlelement(name "MODEL",xmlattributes('CatalogueObjectTrees_V1' as "NAME",'2011-08-30' as "VERSION",'https://www.geo.admin.ch' as "URI")),
        xmlelement(name "MODEL",xmlattributes('InternationalCodes_V1' as "NAME",'2011-08-30' as "VERSION",'https://www.geo.admin.ch' as "URI")),
        xmlelement(name "MODEL",xmlattributes('Localisation_V1' as "NAME",'2011-08-30' as "VERSION",'https://www.geo.admin.ch' as "URI")),
        xmlelement(name "MODEL",xmlattributes('LocalisationCH_V1' as "NAME",'2011-08-30' as "VERSION",'https://www.geo.admin.ch' as "URI")),
        xmlelement(name "MODEL",xmlattributes('Dictionaries_V1' as "NAME",'2011-08-30' as "VERSION",'https://www.geo.admin.ch' as "URI")),
        xmlelement(name "MODEL",xmlattributes('DictionariesCH_V1' as "NAME",'2011-08-30' as "VERSION",'https://www.geo.admin.ch' as "URI")),
        xmlelement(name "MODEL",xmlattributes('Units' as "NAME",'2012-02-20' as "VERSION",'https://www.interlis.ch/models' as "URI")),
        xmlelement(name "MODEL",xmlattributes('OeREBKRM_V1_1' as "NAME",'2016-08-15' as "VERSION",'https://models.geo.admin.ch/V_D/OeREB/' as "URI") ),
        xmlelement(name "MODEL",xmlattributes('CHAdminCodes_V1' as "NAME",'2011-08-30' as "VERSION",'https://www.geo.admin.ch' as "URI")),
        xmlelement(name "MODEL",xmlattributes('AdministrativeUnits_V1' as "NAME",'2011-08-30' as "VERSION",'https://www.geo.admin.ch' as "URI")),
        xmlelement(name "MODEL",xmlattributes('AdministrativeUnitsCH_V1' as "NAME",'2011-08-30' as "VERSION",'https://www.geo.admin.ch' as "URI")),
        xmlelement(name "MODEL",xmlattributes('GeometryCHLV03_V1' as "NAME",'2015-11-12' as "VERSION",'https://www.geo.admin.ch' as "URI")),
        xmlelement(name "MODEL",xmlattributes('GeometryCHLV95_V1' as "NAME",'2015-11-12' as "VERSION",'https://www.geo.admin.ch' as "URI")),
        xmlelement(name "MODEL",xmlattributes('OeREBKRMvs_V1_1' as "NAME",'2016-08-15' as "VERSION",'https://models.geo.admin.ch/V_D/OeREB/' as "URI")),
        xmlelement(name "MODEL",xmlattributes('OeREBKRMtrsfr_V1_1' as "NAME",'2016-08-15' as "VERSION",'https://models.geo.admin.ch/V_D/OeREB/' as "URI"))
    )
   ),
  xmlelement(name "DATASECTION",
    xmlelement(name "OeREBKRMtrsfr_V1_1.Transferstruktur",
         xmlattributes(( select bid from bidprops) as "BID"),
         --xmlcomment('OeREBKRMvs_V1_1..Vorschriften.Amt'),
         (select xmlagg(x_v11) from aemter_xml),
         --xmlcomment('OeREBKRMvs_V1_1..Vorschriften.DokumentBasis'),
         (select xmlagg(x_v11) from dokumentbasis_xml),
         --xmlcomment('OeREBKRMtrsfr_V1_1.Transferstruktur.DarstellungsDienst'),
         (select xmlagg(x_v11) from darstellungsdienste_xml),
         -- not needed xmlcomment('OeREBKRMtrsfr_V1_1.Transferstruktur.HinweisVorschrift'),
         --xmlcomment('OeREBKRMtrsfr_V1_1.Transferstruktur.Eigentumsbeschraenkung'),
         (select xmlagg(x_v11) from eigentumsbeschraenkung_xml),
         --xmlcomment('OeREBKRMvs_V1_1..Vorschriften.Rechtsvorschrift'),
         (select xmlagg(x_v11) from rechtsvorschrift_xml),
         -- xmlcomment('OeREBKRMvs_V1_1..Vorschriften.HinweisWeitereDokumente'),
         (select xmlagg(x_v11) from weitere_dokumente_xml),
         -- not needed xmlcomment('OeREBKRM09vs.Vorschriften.Dokument'),
         --xmlcomment('OeREBKRMtrsfr_V1_1.Transferstruktur.Geometrie'),
         (select xmlagg(x_v11) from geometrie_xml),
         --xmlcomment('OeREBKRMtrsfr_V1_1.Transferstruktur.HinweisVorschrift'),
         (select xmlagg(x_v11) from hinweisvorschrift_xml)
         -- what about Dokument (not available in a4w) and the n:m-relation HinweisWeitereDokumente to link them to Rechtsvorschrift
    )
    )
);



$_$;


--
-- Name: export_oereb_v2(integer[]); Type: FUNCTION; Schema: altlast_ili; Owner: -
--

CREATE FUNCTION altlast_ili.export_oereb_v2(p_vflz_ids integer[]) RETURNS xml
    LANGUAGE sql
    AS $_$


-- attributes for wms 
with bidprops as (
    select 
        'kbsOEREB' || org.kuerzel as bid
    from altlast_admin.setitem
    join altlast_admin.setting using (setitem_id)
    join altlast.org on org.org_id=setting.value::int
    where key= 'org'
),


-- all sites of the list of vflz_ids
standorte as (
    select
        v.vflz_id,
        v.vfl_id,
        v.vflz_combined_id_kt,
        vflnr.org_id,
        v.dat_rechtskraft::date as date_ersteintrag,
        statusaltlv_mapping.code_long as statusaltlv_long,
        statusaltlv_mapping.ili_code as statusaltlv_ili_code,
        statusaltlv_mapping.ili_c_cli_id as statusaltlv_ili_c_cli_id,
        true as rechtsstatus,
        (st_dump(vflgeo.wkb_geometry)).geom as wkb_geometry,
        case when v.x_koordinate is not null and v.y_koordinate is not null then st_makepoint(v.x_koordinate, v.y_koordinate) 
            else st_centroid(vflgeo.wkb_geometry) end as wkb_point,
        -- artifficial transfer ids:
        (st_dump(vflgeo.wkb_geometry)).path[1] as laufnummer,
        (st_numgeometries(vflgeo.wkb_geometry)) as numgeom,
        'geom'||v.vflz_id::text as geom_tid,
        'geom'||v.vflz_id::text||'-'||(st_dump(vflgeo.wkb_geometry)).path[1] as geom_tid_laufnummer,
        v.c_vflz_vftyp,
        v.h_vflz_vftyp
    from altlast.vflz v
    join altlast.vflz_is_published_v vip on v.vflz_id = vip.vflz_id and vip.is_latest_published /* only published versions */
    join altlast.vflgeo on vflgeo.vflz_id = v.vflz_id

    join altlast.vflnr on v.vflz_id = vflnr.vflz_id and vflnr.aktiv

        -- restrict using the org configured in a4w
    join altlast_admin.setting stng on stng.value = vflnr.org_id::text
    join altlast_admin.setitem sit on sit.setitem_id = stng.setitem_id and sit.key in ('org', 'astra')

    join altlast.bere_v on bere_v.vflz_id = v.vflz_id
    join altlast_ili.cod_mapping_v statusaltlv_mapping on statusaltlv_mapping.c_cli_id = bere_v.h_bere_res_abwbewe
                and statusaltlv_mapping.code = bere_v.c_bere_res_abwbewe
    where v.vfl_id in (
        select vfl_id from altlast.vflz where vflz_id = any($1)
    )
),


aemter as (
    select distinct
        coalesce(org.bezeichnung_lang, org.bezeichnung) as behoerde,
        org.url_behoerde as url_behoerde,
        (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'UID_Behoerde_Amt') as uid,
        coalesce(org.katastername, org.bezeichnung)::text as katastername,
        org.url_webgis::text as url_webgis,
        org.org_id,
        'amt' || org.org_id::text as tid,
        (select case 
            when org.org_id = 310 then (select url_behoerde from altlast.org where org_id = 310)
            else (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_Behoerde_Amt')
        end as amtimweb) as web_link_de,
        (select case 
            when org.org_id = 310 then (select url_behoerde from altlast.org where org_id = 310)
            else (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_Behoerde_Amt_fr')
        end as amtimweb) as web_link_fr,
        (select case 
            when org.org_id = 310 then (select url_behoerde from altlast.org where org_id = 310)
            else (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_Behoerde_Amt_it')
        end as amtimweb) as web_link_it,
        (select case 
            when org.org_id = 310 then (select url_behoerde from altlast.org where org_id = 310)
            else (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_Behoerde_Amt_fr')
        end as amtimweb) as web_link_rm
    from altlast.org
    /* only load orgs which are referenced from sites*/
    where org.org_id in (select org_id from standorte)
),


thema as (
  select 
        owd.dokument_tid as tid,
        owd.beschreibung as code, 
        owd.titel_de as titel, 
        owd.titel_fr, 
        owd.titel_it, 
        owd.titel_rm, 
        owd.auszugindex
        from altlast_ili.oereb_weitere_dokumente owd      
),


wmsprops as (
    select
        wms_layername as layername,
        'dd' || wms_layername as tid
    from altlast_ili.config_wms
    order by config_wms_id limit 1
),


darstellungsdienste as (
    select
            (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) 
                where t.title = 'VerweisWMS_Darstellungsdienst') as url_verweiswms_de,
            (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) 
                where t.title = 'VerweisWMS_Darstellungsdienst_fr') as url_verweiswms_fr,
            (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) 
                where t.title = 'VerweisWMS_Darstellungsdienst_it') as url_verweiswms_it
    from altlast_ili.symbol where export = 'oereb2'
),


legendeeintrag as (
    select
        symbol.legende_status as tid,
        symbol.code as code,
        symbol.c_cli_id as c_cli_id,
        symbol.symbol as binblbox,
        symbol.thema as thema,
        symbol.def_code as definition,
        symbol.artcodeliste as url_artcodeliste,
        symbol.geometrytype,
        (select tid from wmsprops) as darstellungsdienst
    from altlast_ili.symbol where export = 'oereb2'
),


legendedarstellungsdienst as (
    select
        (select tid from wmsprops) as darstellungsdienst,
        symbol.legende_status as legende
    from altlast_ili.symbol where export = 'oereb2'
),


eigentumsbeschraenkung as (
    select
        standorte.vflz_id,
        'eb' || standorte.vflz_id::text as tid,
        /* typ: OeREBKRM09.RechtsStatus  enum (inKraft|laufendeAenderung) */
        case when standorte.rechtsstatus then 'inKraft' else 'laufendeAenderung' end as rechtsstatus,
        standorte.date_ersteintrag,
        (select tid from wmsprops) as darstellungsdienste_tid,
        aemter.tid as aemter_tid,
        legendeeintrag.tid as legende
        
    from standorte
    join aemter on aemter.org_id = standorte.org_id
    join legendeeintrag on standorte.statusaltlv_ili_code = legendeeintrag.code and GeometryType(standorte.wkb_geometry)= legendeeintrag.geometrytype
    group by standorte.vflz_id, 'eb' || standorte.vflz_id::text, standorte.date_ersteintrag, 
    aemter.tid, (select tid from wmsprops), standorte.rechtsstatus, legendeeintrag.tid
),


wmsprops_2 as (
    select value as url_geoportal
    from altlast_admin.setting s
    join altlast_admin.setitem t using (setitem_id) 
    where t.title = 'URL_Rechtsvorschrift_TextImWeb'
),


geoportallinks as (
    select
        standorte.vflz_id,
        case when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_TextImWeb_Indikator') = 'standortnummer' then
          wmsprops_2.url_geoportal || (regexp_replace(standorte.vflz_combined_id_kt::text, ' '::text, '%20'::text, 'g'::text)) || '&lang=de'
        when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_TextImWeb_Indikator') = 'xy_koordinates' then
           wmsprops_2.url_geoportal || 'Y=' || st_x(standorte.wkb_point)::text || '&X=' || st_y(standorte.wkb_point)::text || '&lang=de' 
        when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_TextImWeb_Indikator') = 'map_x_map_y_koordinates' then
           wmsprops_2.url_geoportal || 'map_x=' || st_x(standorte.wkb_point)::text || '&map_y=' || st_y(standorte.wkb_point)::text || '&lang=de' 
        when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_TextImWeb_Indikator') = 'c_koordinates' then
           wmsprops_2.url_geoportal || '&c=' || st_x(standorte.wkb_point)::text || ',' || st_y(standorte.wkb_point)::text || '&lang=de' 
        when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_TextImWeb_Indikator') = 'ne_koordinates' then
           wmsprops_2.url_geoportal || '&E=' || st_x(standorte.wkb_point)::text || '&N=' || st_y(standorte.wkb_point)::text
        else wmsprops_2.url_geoportal || '&lang=de'
        end as permalink_geoportal_de,
        case when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_TextImWeb_Indikator') = 'standortnummer' then
          wmsprops_2.url_geoportal || (regexp_replace(standorte.vflz_combined_id_kt::text, ' '::text, '%20'::text, 'g'::text)) || '&lang=fr'
        when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_TextImWeb_Indikator') = 'xy_koordinates' then
           wmsprops_2.url_geoportal || 'Y=' || st_x(standorte.wkb_point)::text || '&X=' || st_y(standorte.wkb_point)::text || '&lang=fr' 
        when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_TextImWeb_Indikator') = 'map_x_map_y_koordinates' then
           wmsprops_2.url_geoportal || 'map_x=' || st_x(standorte.wkb_point)::text || '&map_y=' || st_y(standorte.wkb_point)::text || '&lang=fr' 
        when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_TextImWeb_Indikator') = 'c_koordinates' then
           wmsprops_2.url_geoportal || '&c=' || st_x(standorte.wkb_point)::text || ',' || st_y(standorte.wkb_point)::text || '&lang=fr' 
        when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_TextImWeb_Indikator') = 'ne_koordinates' then
           wmsprops_2.url_geoportal || '&E=' || st_x(standorte.wkb_point)::text || '&N=' || st_y(standorte.wkb_point)::text
        else wmsprops_2.url_geoportal || '&lang=fr'
        end as permalink_geoportal_fr,
        case when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_TextImWeb_Indikator') = 'standortnummer' then
          wmsprops_2.url_geoportal || (regexp_replace(standorte.vflz_combined_id_kt::text, ' '::text, '%20'::text, 'g'::text)) || '&lang=rm'
        when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_TextImWeb_Indikator') = 'xy_koordinates' then
           wmsprops_2.url_geoportal || 'Y=' || st_x(standorte.wkb_point)::text || '&X=' || st_y(standorte.wkb_point)::text || '&lang=rm' 
        when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_TextImWeb_Indikator') = 'map_x_map_y_koordinates' then
           wmsprops_2.url_geoportal || 'map_x=' || st_x(standorte.wkb_point)::text || '&map_y=' || st_y(standorte.wkb_point)::text || '&lang=rm' 
        when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_TextImWeb_Indikator') = 'c_koordinates' then
           wmsprops_2.url_geoportal || '&c=' || st_x(standorte.wkb_point)::text || ',' || st_y(standorte.wkb_point)::text || '&lang=rm' 
        when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_TextImWeb_Indikator') = 'ne_koordinates' then
           wmsprops_2.url_geoportal || '&E=' || st_x(standorte.wkb_point)::text || '&N=' || st_y(standorte.wkb_point)::text
        else wmsprops_2.url_geoportal || '&lang=rm'
        end as permalink_geoportal_rm,
        case when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_TextImWeb_Indikator') = 'standortnummer' then
          wmsprops_2.url_geoportal || (regexp_replace(standorte.vflz_combined_id_kt::text, ' '::text, '%20'::text, 'g'::text)) || '&lang=it'
        when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_TextImWeb_Indikator') = 'xy_koordinates' then
           wmsprops_2.url_geoportal || 'Y=' || st_x(standorte.wkb_point)::text || '&X=' || st_y(standorte.wkb_point)::text || '&lang=it' 
        when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_TextImWeb_Indikator') = 'map_x_map_y_koordinates' then
           wmsprops_2.url_geoportal || 'map_x=' || st_x(standorte.wkb_point)::text || '&map_y=' || st_y(standorte.wkb_point)::text || '&lang=it' 
        when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_TextImWeb_Indikator') = 'c_koordinates' then
           wmsprops_2.url_geoportal || '&c=' || st_x(standorte.wkb_point)::text || ',' || st_y(standorte.wkb_point)::text || '&lang=it' 
        when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_TextImWeb_Indikator') = 'ne_koordinates' then
           wmsprops_2.url_geoportal || '&E=' || st_x(standorte.wkb_point)::text || '&N=' || st_y(standorte.wkb_point)::text
        else wmsprops_2.url_geoportal || '&lang=it'
        end as permalink_geoportal_it
    from standorte, wmsprops_2
),


dokument as (
    select
        standorte.vflz_id,
        'rv'||standorte.vflz_id::text as tid,
        'Rechtsvorschrift' as typ,
        standorte.vflz_combined_id_kt,
        gpl.permalink_geoportal_de as web_link_de,
        gpl.permalink_geoportal_fr as web_link_fr,
        gpl.permalink_geoportal_rm as web_link_rm,
        gpl.permalink_geoportal_it as web_link_it,
        '1' as auszugindex,
            /* typ: OeREBKRM09.RechtsStatus  enum (inKraft|laufendeAenderung) */
        case when standorte.rechtsstatus then 'inKraft' else 'laufendeAenderung' end as rechtsstatus,
        standorte.date_ersteintrag::date,
        aemter.katastername,
        aemter.tid as aemter_tid
    from standorte
    join aemter on aemter.org_id = standorte.org_id
    join geoportallinks gpl on gpl.vflz_id = standorte.vflz_id
    group by standorte.vflz_id, gpl.permalink_geoportal_de, gpl.permalink_geoportal_fr, gpl.permalink_geoportal_rm, gpl.permalink_geoportal_it, standorte.rechtsstatus, standorte.date_ersteintrag::date, 
    aemter.katastername,aemter.tid, standorte.vflz_combined_id_kt
),


-------------------------------------------------------------------------------------------------------------------
-- xml queries
-------------------------------------------------------------------------------------------------------------------


aemter_xml as (
    select 
  xmlelement(name "OeREBKRM_V2_0.Amt.Amt",
                xmlattributes(aemter.tid as "TID"),
                xmlelement(name "Name", altlast_ili.oereb_localisedtext_t_v11(
                  (select case when aemter.org_id = 310 then (select bezeichnung_lang from altlast.org where aemter.org_id = org.org_id)
      else (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'Behoerde_Amt') 
      end as name), 
                  array['de',
                    case when (select org.kuerzel from altlast_admin.setitem join altlast_admin.setting using (setitem_id) join altlast.org on org.org_id=setting.value::int where key= 'org') = 'GR' 
                      then 'rm' 
                    else 'fr' end,
                    'it'
                  ]
                  )),
                xmlelement(name "AmtImWeb", 
                    xmlelement(name "OeREBKRM_V2_0.MultilingualUri",
                        xmlelement(name "LocalisedText",
                            xmlelement(name "OeREBKRM_V2_0.LocalisedUri",
                                xmlelement(name "Language", 'de'),
                                xmlelement(name "Text", aemter.web_link_de)
                            ), 
                            xmlelement(name "OeREBKRM_V2_0.LocalisedUri",   
                                case when (select org.kuerzel from altlast_admin.setitem join altlast_admin.setting using (setitem_id) join altlast.org on org.org_id=setting.value::int where key= 'org') = 'GR' 
                                 then xmlelement(name "Language", 'rm')
                                else xmlelement(name "Language", 'fr') end,
                                case when (select org.kuerzel from altlast_admin.setitem join altlast_admin.setting using (setitem_id) join altlast.org on org.org_id=setting.value::int where key= 'org') = 'GR' 
                                 then xmlelement(name "Text", aemter.web_link_rm)
                                else xmlelement(name "Text", aemter.web_link_fr) end
                            ),
                            xmlelement(name "OeREBKRM_V2_0.LocalisedUri",
                                xmlelement(name "Language", 'it'),
                                xmlelement(name "Text", aemter.web_link_it)
                            )
                        )
                    )
                ),
                xmlelement(name "UID", (select case when aemter.org_id = 310 then (select uid from altlast.org where aemter.org_id = org.org_id)
  else aemter.uid
  end as uid ))
  ) as x_v2
    from aemter
),


thema_xml as (
  select 
        xmlelement(name "OeREBKRMkvs_V2_0.Thema.Thema",
                xmlattributes(thema.tid as "TID"),
                xmlelement(name "Code", thema.code), 
                xmlelement(name "Titel", altlast_ili.oereb_localisedtext_t_v11(thema.titel, 
                  array['de',
                    case when (select org.kuerzel from altlast_admin.setitem join altlast_admin.setting using (setitem_id) join altlast.org on org.org_id=setting.value::int where key= 'org') = 'GR' 
                      then 'rm' 
                    else 'fr' end,
                    'it'
                  ]
                  )),
                xmlelement(name "AuszugIndex", thema.auszugindex) 
        ) as x_v2
    from thema
),


darstellungsdienste_xml as (
    select 
        xmlelement(name "OeREBKRMtrsfr_V2_0.Transferstruktur.DarstellungsDienst",
                xmlattributes(wmsprops.tid as "TID"),
                xmlelement(name "VerweisWMS",
                    xmlelement(name "OeREBKRM_V2_0.MultilingualUri",
                        xmlelement(name "LocalisedText",
                            xmlelement(name "OeREBKRM_V2_0.LocalisedUri",
                                xmlelement(name "Language", 'de'),
                                xmlelement(name "Text", darstellungsdienste.url_verweiswms_de)
                                
                            ), 
                            xmlelement(name "OeREBKRM_V2_0.LocalisedUri",   
                                case when (select org.kuerzel from altlast_admin.setitem join altlast_admin.setting using (setitem_id) join altlast.org on org.org_id=setting.value::int where key= 'org') = 'GR' 
                                 then xmlelement(name "Language", 'rm')
                                else xmlelement(name "Language", 'fr') end,
                                case when (select org.kuerzel from altlast_admin.setitem join altlast_admin.setting using (setitem_id) join altlast.org on org.org_id=setting.value::int where key= 'org') = 'GR' 
                                 then xmlelement(name "Text", darstellungsdienste.url_verweiswms_fr)
                                else xmlelement(name "Text", darstellungsdienste.url_verweiswms_fr)
                                 end
                            ),
                            xmlelement(name "OeREBKRM_V2_0.LocalisedUri",
                                xmlelement(name "Language", 'it'),
                                xmlelement(name "Text", darstellungsdienste.url_verweiswms_it)
                                
                            )
                        )
                    )

                )                
        ) as x_v2
    from wmsprops, darstellungsdienste
    group by wmsprops.tid, darstellungsdienste.url_verweiswms_de, darstellungsdienste.url_verweiswms_fr, darstellungsdienste.url_verweiswms_it
),


legendeeintrag_xml as (
    select
        xmlelement(name "OeREBKRMtrsfr_V2_0.Transferstruktur.LegendeEintrag", xmlattributes(legendeeintrag.tid as "TID"),
          xmlelement(name "Symbol",
            xmlelement(name "BINBLBOX",legendeeintrag.binblbox)),
          xmlelement(name "LegendeText", altlast_ili.oereb_localisedtext_t_v11(altlast.msgid_code(legendeeintrag.c_cli_id, legendeeintrag.code), 
            array['de',
              case when (select org.kuerzel from altlast_admin.setitem join altlast_admin.setting using (setitem_id) join altlast.org on org.org_id=setting.value::int where key= 'org') = 'GR' 
                then 'rm' 
                else 'fr' end,
                'it'
              ]
            )),
          xmlelement(name "ArtCode", legendeeintrag.definition),
          xmlelement(name "ArtCodeliste", legendeeintrag.url_artcodeliste),
          xmlelement(name "Thema", legendeeintrag.thema),
          xmlelement(name "DarstellungsDienst", xmlattributes(legendeeintrag.darstellungsdienst as "REF"))
        )
        as x_v2
    from legendeeintrag
),


legendedarstellungsdienst_xml as (
select
        xmlelement(name "OeREBKRMtrsfr_V2_0.Transferstruktur.LegendeDarstellungsdienst", 
            xmlelement(name "DarstellungsDienst", xmlattributes(legendedarstellungsdienst.darstellungsdienst as "REF")),
            xmlelement(name "Legende", xmlattributes(legendedarstellungsdienst.legende as "REF"))
          
        )
        as x_v2
    from legendedarstellungsdienst
),


eigentumsbeschraenkung_xml as (
    select 
        xmlelement(name "OeREBKRMtrsfr_V2_0.Transferstruktur.Eigentumsbeschraenkung", xmlattributes(eb.tid as "TID"),
                xmlelement(name "Rechtsstatus", eb.rechtsstatus),
                xmlelement(name "publiziertAb", eb.date_ersteintrag::date),
                xmlelement(name "DarstellungsDienst", xmlattributes( eb.darstellungsdienste_tid as "REF")),
                xmlelement(name "Legende", xmlattributes(eb.legende as "REF")),
                xmlelement(name "ZustaendigeStelle", xmlattributes( eb.aemter_tid as "REF"))
        ) as x_v2
    from eigentumsbeschraenkung eb
),


dokument_xml as (
    select 
        xmlelement(name "OeREBKRM_V2_0.Dokumente.Dokument", xmlattributes(dokument.tid as "TID"),
                xmlelement(name "Typ", dokument.typ),
                xmlelement(name "Titel", altlast_ili.oereb_localisedtext_t_v11(dokument.vflz_combined_id_kt, 
                  array['de',
                    case when (select org.kuerzel from altlast_admin.setitem join altlast_admin.setting using (setitem_id) join altlast.org on org.org_id=setting.value::int where key= 'org') = 'GR' 
                      then 'rm' 
                    else 'fr' end,
                    'it'
                  ]
                )),
                xmlelement(name "TextImWeb", 
                    xmlelement(name "OeREBKRM_V2_0.MultilingualUri",
                        xmlelement(name "LocalisedText",
                            xmlelement(name "OeREBKRM_V2_0.LocalisedUri",
                                xmlelement(name "Language", 'de'),
                                xmlelement(name "Text", dokument.web_link_de)
                            ), 
                            xmlelement(name "OeREBKRM_V2_0.LocalisedUri",   
                                case when (select org.kuerzel from altlast_admin.setitem join altlast_admin.setting using (setitem_id) join altlast.org on org.org_id=setting.value::int where key= 'org') = 'GR' 
                                 then xmlelement(name "Language", 'rm')
                                else xmlelement(name "Language", 'fr') end,
                                case when (select org.kuerzel from altlast_admin.setitem join altlast_admin.setting using (setitem_id) join altlast.org on org.org_id=setting.value::int where key= 'org') = 'GR' 
                                 then xmlelement(name "Text", dokument.web_link_rm)
                                else xmlelement(name "Text", dokument.web_link_fr) end
                            ),
                            xmlelement(name "OeREBKRM_V2_0.LocalisedUri",
                                xmlelement(name "Language", 'it'),
                                xmlelement(name "Text", dokument.web_link_it)
                            )
                        )
                    )
                ),
                xmlelement(name "AuszugIndex", dokument.auszugindex),
                xmlelement(name "Rechtsstatus", dokument.rechtsstatus),
                xmlelement(name "publiziertAb", dokument.date_ersteintrag::date),
                xmlelement(name "ZustaendigeStelle", xmlattributes(dokument.aemter_tid as "REF"))
        ) as x_v2
    from dokument
),


geometrie_xml as (
    select 
        xmlelement(name "OeREBKRMtrsfr_V2_0.Transferstruktur.Geometrie",
                xmlattributes(case when standorte.numgeom > 1 then standorte.geom_tid_laufnummer 
            else standorte.geom_tid end as "TID"),
                case when standorte.wkb_geometry is not null then
                    case when st_geometrytype(standorte.wkb_geometry) = 'ST_Point' then
                        xmlelement(name "Punkt", altlast_ili.oereb_geometry(ST_Transform((standorte.wkb_geometry), 2056)))
                    else
                        xmlelement(name "Flaeche", altlast_ili.oereb_geometry(ST_Transform((standorte.wkb_geometry), 2056)))
                    end
                else
                    xmlelement(name "Punkt", altlast_ili.oereb_geometry(ST_Transform((standorte.wkb_geometry), 2056)))
                end,
                xmlelement(name "Rechtsstatus",
                    /* typ: OeREBKRM09.RechtsStatus  enum (inKraft|laufendeAenderung) */
                    case when standorte.rechtsstatus then 'inKraft' else 'laufendeAenderung' end
                ),
                xmlelement(name "publiziertAb", standorte.date_ersteintrag::date),
                xmlelement(name "Eigentumsbeschraenkung",
                    xmlattributes( eb.tid as "REF")
                )
        ) as x_v2
    from standorte
    join eigentumsbeschraenkung eb on eb.vflz_id = standorte.vflz_id
),

hinweisvorschrift_xml as (
    select 
  xmlelement(name "OeREBKRMtrsfr_V2_0.Transferstruktur.HinweisVorschrift",
    xmlelement(name "Eigentumsbeschraenkung", xmlattributes(eb.tid as "REF") ),
    xmlelement(name "Vorschrift", xmlattributes(dokument.tid as "REF") )
  ) as x_v2
    from eigentumsbeschraenkung eb
    join dokument  on dokument.vflz_id = eb.vflz_id
),


eigentumsbeschraenkunglegende_xml as (
    select 
  xmlelement(name "OeREBKRMtrsfr_V2_0.Transferstruktur.EigentumsbeschraenkungLegende",
    xmlelement(name "Eigentumsbeschraenkung", xmlattributes(eb.tid as "REF") ),
    xmlelement(name "Legende", xmlattributes(legendeeintrag.tid as "REF") )
  ) as x_v2
    from eigentumsbeschraenkung eb
    join standorte on eb.vflz_id = standorte.vflz_id
    join legendeeintrag on standorte.statusaltlv_ili_code = legendeeintrag.code 
        and GeometryType(standorte.wkb_geometry)= legendeeintrag.geometrytype
)


-------------------------------------------------------------------------------------------------------------------
-- assembling of the finished xml document according to the interlis schema
-------------------------------------------------------------------------------------------------------------------


select xmlelement(name "TRANSFER", xmlattributes('http://www.interlis.ch/INTERLIS2.3' as xmlns),
   xmlelement(name "HEADERSECTION",
        xmlattributes('altlast4web' as "SENDER", '2.3' as "VERSION"),
    xmlelement(name "MODELS",
        xmlelement(name "MODEL",xmlattributes('CoordSys' as "NAME",'2015-11-24' as "VERSION",'https://www.interlis.ch/models' as "URI")),
        xmlelement(name "MODEL",xmlattributes('CatalogueObjects_V1' as "NAME",'2011-08-30' as "VERSION",'https://www.geo.admin.ch' as "URI")),
        xmlelement(name "MODEL",xmlattributes('CatalogueObjectTrees_V1' as "NAME",'2011-08-30' as "VERSION",'https://www.geo.admin.ch' as "URI")),
        xmlelement(name "MODEL",xmlattributes('InternationalCodes_V1' as "NAME",'2011-08-30' as "VERSION",'https://www.geo.admin.ch' as "URI")),
        xmlelement(name "MODEL",xmlattributes('Localisation_V1' as "NAME",'2011-08-30' as "VERSION",'https://www.geo.admin.ch' as "URI")),
        xmlelement(name "MODEL",xmlattributes('LocalisationCH_V1' as "NAME",'2011-08-30' as "VERSION",'https://www.geo.admin.ch' as "URI")),
        xmlelement(name "MODEL",xmlattributes('Dictionaries_V1' as "NAME",'2011-08-30' as "VERSION",'https://www.geo.admin.ch' as "URI")),
        xmlelement(name "MODEL",xmlattributes('DictionariesCH_V1' as "NAME",'2011-08-30' as "VERSION",'https://www.geo.admin.ch' as "URI")),
        xmlelement(name "MODEL",xmlattributes('Units' as "NAME",'2012-02-20' as "VERSION",'https://www.interlis.ch/models' as "URI")),
        xmlelement(name "MODEL",xmlattributes('OeREBKRM_V2_0' as "NAME",'2021-04-14' as "VERSION",'https://models.geo.admin.ch/V_D/OeREB/' as "URI") ),
        xmlelement(name "MODEL",xmlattributes('CHAdminCodes_V1' as "NAME",'2011-08-30' as "VERSION",'https://www.geo.admin.ch' as "URI")),
        xmlelement(name "MODEL",xmlattributes('AdministrativeUnits_V1' as "NAME",'2011-08-30' as "VERSION",'https://www.geo.admin.ch' as "URI")),
        xmlelement(name "MODEL",xmlattributes('AdministrativeUnitsCH_V1' as "NAME",'2011-08-30' as "VERSION",'https://www.geo.admin.ch' as "URI")),
        xmlelement(name "MODEL",xmlattributes('GeometryCHLV03_V1' as "NAME",'2015-11-12' as "VERSION",'https://www.geo.admin.ch' as "URI")),
        xmlelement(name "MODEL",xmlattributes('GeometryCHLV95_V1' as "NAME",'2015-11-12' as "VERSION",'https://www.geo.admin.ch' as "URI")),
        xmlelement(name "MODEL",xmlattributes('OeREBKRMkvs_V2_0' as "NAME",'2021-04-14' as "VERSION",'https://models.geo.admin.ch/V_D/OeREB/' as "URI")),
        xmlelement(name "MODEL",xmlattributes('OeREBKRMtrsfr_V2_0' as "NAME",'2021-04-14' as "VERSION",'https://models.geo.admin.ch/V_D/OeREB/' as "URI"))
    )
   ),
  xmlelement(name "DATASECTION",
    xmlelement(name "OeREBKRMtrsfr_V2_0.Transferstruktur",
         xmlattributes(( select bid from bidprops) as "BID"),
         --xmlcomment('OeREBKRM_V2_0.Amt.Amt'),
         (select xmlagg(x_v2) from aemter_xml),
         --xmlcomment('OeREBKRMtrsfr_V2_0.Transferstruktur.DarstellungsDienst'),
         (select xmlagg(x_v2) from darstellungsdienste_xml),
         --xmlcomment('OeREBKRMtrsfr_V2_0.Transferstruktur.LegendeEintrag'),
         (select xmlagg(x_v2) from legendeeintrag_xml),
         -- xmlcomment('OeREBKRMtrsfr_V2_0.Transferstruktur.Eigentumsbeschraenkung'),
         (select xmlagg(x_v2) from eigentumsbeschraenkung_xml),
         --xmlcomment('OeREBKRM_V2_0.Dokumente.Dokument'),
         (select xmlagg(x_v2) from dokument_xml),
         --xmlcomment('OeREBKRMtrsfr_V2_0.Transferstruktur.Geometrie'),
         (select xmlagg(x_v2) from geometrie_xml),
         --xmlcomment('OeREBKRMtrsfr_V2_0.Transferstruktur.HinweisVorschrift'),
         (select xmlagg(x_v2) from hinweisvorschrift_xml)
    )
    )
);



$_$;


--
-- Name: export_oereb_v2_thema(integer[]); Type: FUNCTION; Schema: altlast_ili; Owner: -
--

CREATE FUNCTION altlast_ili.export_oereb_v2_thema(p_vflz_ids integer[]) RETURNS xml
    LANGUAGE sql
    AS $_$


-- attributes for wms 
with bidprops as (
    select 
        'kbsOEREB' || org.kuerzel as bid
    from altlast_admin.setitem
    join altlast_admin.setting using (setitem_id)
    join altlast.org on org.org_id=setting.value::int
    where key= 'org'
),


-- all sites of the list of vflz_ids
standorte as (
    select
        v.vflz_id,
        v.vfl_id,
        v.vflz_combined_id_kt,
        vflnr.org_id,
        v.dat_rechtskraft::date as date_ersteintrag,
        statusaltlv_mapping.code_long as statusaltlv_long,
        statusaltlv_mapping.ili_code as statusaltlv_ili_code,
        statusaltlv_mapping.ili_c_cli_id as statusaltlv_ili_c_cli_id,
        true as rechtsstatus,
        (st_dump(vflgeo.wkb_geometry)).geom as wkb_geometry,
        case when v.x_koordinate is not null and v.y_koordinate is not null then st_makepoint(v.x_koordinate, v.y_koordinate) 
            else st_centroid(vflgeo.wkb_geometry) end as wkb_point,
        -- artifficial transfer ids:
        (st_dump(vflgeo.wkb_geometry)).path[1] as laufnummer,
        (st_numgeometries(vflgeo.wkb_geometry)) as numgeom,
        'geom'||v.vflz_id::text as geom_tid,
        'geom'||v.vflz_id::text||'-'||(st_dump(vflgeo.wkb_geometry)).path[1] as geom_tid_laufnummer,
        v.c_vflz_vftyp,
        v.h_vflz_vftyp
    from altlast.vflz v
    join altlast.vflz_is_published_v vip on v.vflz_id = vip.vflz_id and vip.is_latest_published /* only published versions */
    join altlast.vflgeo on vflgeo.vflz_id = v.vflz_id

    join altlast.vflnr on v.vflz_id = vflnr.vflz_id and vflnr.aktiv

        -- restrict using the org configured in a4w
    join altlast_admin.setting stng on stng.value = vflnr.org_id::text
    join altlast_admin.setitem sit on sit.setitem_id = stng.setitem_id and sit.key in ('org', 'astra')

    join altlast.bere_v on bere_v.vflz_id = v.vflz_id
    join altlast_ili.cod_mapping_v statusaltlv_mapping on statusaltlv_mapping.c_cli_id = bere_v.h_bere_res_abwbewe
                and statusaltlv_mapping.code = bere_v.c_bere_res_abwbewe
    where v.vfl_id in (
        select vfl_id from altlast.vflz where vflz_id = any($1)
    )
),


aemter as (
    select distinct
        coalesce(org.bezeichnung_lang, org.bezeichnung) as behoerde,
        org.url_behoerde as url_behoerde,
        (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'UID_Behoerde_Amt') as uid,
        coalesce(org.katastername, org.bezeichnung)::text as katastername,
        org.url_webgis::text as url_webgis,
        org.org_id,
        'amt' || org.org_id::text as tid,
        (select case 
            when org.org_id = 310 then (select url_behoerde from altlast.org where org_id = 310)
            else (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_Behoerde_Amt')
        end as amtimweb) as web_link_de,
        (select case 
            when org.org_id = 310 then (select url_behoerde from altlast.org where org_id = 310)
            else (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_Behoerde_Amt_fr')
        end as amtimweb) as web_link_fr,
        (select case 
            when org.org_id = 310 then (select url_behoerde from altlast.org where org_id = 310)
            else (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_Behoerde_Amt_it')
        end as amtimweb) as web_link_it,
        (select case 
            when org.org_id = 310 then (select url_behoerde from altlast.org where org_id = 310)
            else (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_Behoerde_Amt_fr')
        end as amtimweb) as web_link_rm
    from altlast.org
    /* only load orgs which are referenced from sites*/
    where org.org_id in (select org_id from standorte)
),


thema as (
  select 
        owd.dokument_tid as tid,
        owd.beschreibung as code, 
        owd.titel_de as titel, 
        owd.titel_fr, 
        owd.titel_it, 
        owd.titel_rm, 
        owd.auszugindex
        from altlast_ili.oereb_weitere_dokumente owd      
),


wmsprops as (
    select
        wms_layername as layername,
        'dd' || wms_layername as tid
    from altlast_ili.config_wms
    order by config_wms_id limit 1
),


darstellungsdienste as (
    select
            (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) 
                where t.title = 'VerweisWMS_Darstellungsdienst') as url_verweiswms_de,
            (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) 
                where t.title = 'VerweisWMS_Darstellungsdienst_fr') as url_verweiswms_fr,
            (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) 
                where t.title = 'VerweisWMS_Darstellungsdienst_it') as url_verweiswms_it
    from altlast_ili.symbol where export = 'oereb2'
),


legendeeintrag as (
    select
        symbol.legende_status as tid,
        symbol.code as code,
        symbol.c_cli_id as c_cli_id,
        symbol.symbol as binblbox,
        symbol.thema as thema,
        symbol.def_code as definition,
        symbol.artcodeliste as url_artcodeliste,
        symbol.geometrytype,
        (select tid from wmsprops) as darstellungsdienst
    from altlast_ili.symbol where export = 'oereb2'
),


legendedarstellungsdienst as (
    select
        (select tid from wmsprops) as darstellungsdienst,
        symbol.legende_status as legende
    from altlast_ili.symbol where export = 'oereb2'
),


eigentumsbeschraenkung as (
    select
        standorte.vflz_id,
        'eb' || standorte.vflz_id::text as tid,
        /* typ: OeREBKRM09.RechtsStatus  enum (inKraft|laufendeAenderung) */
        case when standorte.rechtsstatus then 'inKraft' else 'laufendeAenderung' end as rechtsstatus,
        standorte.date_ersteintrag,
        (select tid from wmsprops) as darstellungsdienste_tid,
        aemter.tid as aemter_tid,
        legendeeintrag.tid as legende
        
    from standorte
    join aemter on aemter.org_id = standorte.org_id
    join legendeeintrag on standorte.statusaltlv_ili_code = legendeeintrag.code and GeometryType(standorte.wkb_geometry)= legendeeintrag.geometrytype
    group by standorte.vflz_id, 'eb' || standorte.vflz_id::text, standorte.date_ersteintrag, 
    aemter.tid, (select tid from wmsprops), standorte.rechtsstatus, legendeeintrag.tid
),


wmsprops_2 as (
    select value as url_geoportal
    from altlast_admin.setting s
    join altlast_admin.setitem t using (setitem_id) 
    where t.title = 'URL_Rechtsvorschrift_TextImWeb'
),


geoportallinks as (
    select
        standorte.vflz_id,
        case when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_TextImWeb_Indikator') = 'standortnummer' then
          wmsprops_2.url_geoportal || (regexp_replace(standorte.vflz_combined_id_kt::text, ' '::text, '%20'::text, 'g'::text)) || '&lang=de'
        when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_TextImWeb_Indikator') = 'xy_koordinates' then
           wmsprops_2.url_geoportal || 'Y=' || st_x(standorte.wkb_point)::text || '&X=' || st_y(standorte.wkb_point)::text || '&lang=de' 
        when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_TextImWeb_Indikator') = 'map_x_map_y_koordinates' then
           wmsprops_2.url_geoportal || 'map_x=' || st_x(standorte.wkb_point)::text || '&map_y=' || st_y(standorte.wkb_point)::text || '&lang=de' 
        when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_TextImWeb_Indikator') = 'c_koordinates' then
           wmsprops_2.url_geoportal || '&c=' || st_x(standorte.wkb_point)::text || ',' || st_y(standorte.wkb_point)::text || '&lang=de' 
        else wmsprops_2.url_geoportal || '&lang=de'
        end as permalink_geoportal_de,
        case when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_TextImWeb_Indikator') = 'standortnummer' then
          wmsprops_2.url_geoportal || (regexp_replace(standorte.vflz_combined_id_kt::text, ' '::text, '%20'::text, 'g'::text)) || '&lang=fr'
        when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_TextImWeb_Indikator') = 'xy_koordinates' then
           wmsprops_2.url_geoportal || 'Y=' || st_x(standorte.wkb_point)::text || '&X=' || st_y(standorte.wkb_point)::text || '&lang=fr' 
        when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_TextImWeb_Indikator') = 'map_x_map_y_koordinates' then
           wmsprops_2.url_geoportal || 'map_x=' || st_x(standorte.wkb_point)::text || '&map_y=' || st_y(standorte.wkb_point)::text || '&lang=fr' 
        when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_TextImWeb_Indikator') = 'c_koordinates' then
           wmsprops_2.url_geoportal || '&c=' || st_x(standorte.wkb_point)::text || ',' || st_y(standorte.wkb_point)::text || '&lang=fr' 
        else wmsprops_2.url_geoportal || '&lang=fr'
        end as permalink_geoportal_fr,
        case when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_TextImWeb_Indikator') = 'standortnummer' then
          wmsprops_2.url_geoportal || (regexp_replace(standorte.vflz_combined_id_kt::text, ' '::text, '%20'::text, 'g'::text)) || '&lang=rm'
        when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_TextImWeb_Indikator') = 'xy_koordinates' then
           wmsprops_2.url_geoportal || 'Y=' || st_x(standorte.wkb_point)::text || '&X=' || st_y(standorte.wkb_point)::text || '&lang=rm' 
        when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_TextImWeb_Indikator') = 'map_x_map_y_koordinates' then
           wmsprops_2.url_geoportal || 'map_x=' || st_x(standorte.wkb_point)::text || '&map_y=' || st_y(standorte.wkb_point)::text || '&lang=rm' 
        when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_TextImWeb_Indikator') = 'c_koordinates' then
           wmsprops_2.url_geoportal || '&c=' || st_x(standorte.wkb_point)::text || ',' || st_y(standorte.wkb_point)::text || '&lang=rm' 
        else wmsprops_2.url_geoportal || '&lang=rm'
        end as permalink_geoportal_rm,
        case when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_TextImWeb_Indikator') = 'standortnummer' then
          wmsprops_2.url_geoportal || (regexp_replace(standorte.vflz_combined_id_kt::text, ' '::text, '%20'::text, 'g'::text)) || '&lang=it'
        when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_TextImWeb_Indikator') = 'xy_koordinates' then
           wmsprops_2.url_geoportal || 'Y=' || st_x(standorte.wkb_point)::text || '&X=' || st_y(standorte.wkb_point)::text || '&lang=it' 
        when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_TextImWeb_Indikator') = 'map_x_map_y_koordinates' then
           wmsprops_2.url_geoportal || 'map_x=' || st_x(standorte.wkb_point)::text || '&map_y=' || st_y(standorte.wkb_point)::text || '&lang=it' 
        when (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'URL_TextImWeb_Indikator') = 'c_koordinates' then
           wmsprops_2.url_geoportal || '&c=' || st_x(standorte.wkb_point)::text || ',' || st_y(standorte.wkb_point)::text || '&lang=it' 
        else wmsprops_2.url_geoportal || '&lang=it'
        end as permalink_geoportal_it
    from standorte, wmsprops_2
),


dokument as (
    select
        standorte.vflz_id,
        'rv'||standorte.vflz_id::text as tid,
        'Rechtsvorschrift' as typ,
        standorte.vflz_combined_id_kt,
        gpl.permalink_geoportal_de as web_link_de,
        gpl.permalink_geoportal_fr as web_link_fr,
        gpl.permalink_geoportal_rm as web_link_rm,
        gpl.permalink_geoportal_it as web_link_it,
        '1' as auszugindex,
            /* typ: OeREBKRM09.RechtsStatus  enum (inKraft|laufendeAenderung) */
        case when standorte.rechtsstatus then 'inKraft' else 'laufendeAenderung' end as rechtsstatus,
        standorte.date_ersteintrag::date,
        aemter.katastername,
        aemter.tid as aemter_tid
    from standorte
    join aemter on aemter.org_id = standorte.org_id
    join geoportallinks gpl on gpl.vflz_id = standorte.vflz_id
    group by standorte.vflz_id, gpl.permalink_geoportal_de, gpl.permalink_geoportal_fr, gpl.permalink_geoportal_rm, gpl.permalink_geoportal_it, standorte.rechtsstatus, standorte.date_ersteintrag::date, 
    aemter.katastername,aemter.tid, standorte.vflz_combined_id_kt
),


-------------------------------------------------------------------------------------------------------------------
-- xml queries
-------------------------------------------------------------------------------------------------------------------


aemter_xml as (
    select 
  xmlelement(name "OeREBKRM_V2_0.Amt.Amt",
                xmlattributes(aemter.tid as "TID"),
                xmlelement(name "Name", altlast_ili.oereb_localisedtext_t_v11(
                  (select case when aemter.org_id = 310 then (select bezeichnung_lang from altlast.org where aemter.org_id = org.org_id)
      else (select value from altlast_admin.setting s join altlast_admin.setitem t using (setitem_id) where t.title = 'Behoerde_Amt') 
      end as name), 
                  array['de',
                    case when (select org.kuerzel from altlast_admin.setitem join altlast_admin.setting using (setitem_id) join altlast.org on org.org_id=setting.value::int where key= 'org') = 'GR' 
                      then 'rm' 
                    else 'fr' end,
                    'it'
                  ]
                  )),
                xmlelement(name "AmtImWeb", 
                    xmlelement(name "OeREBKRM_V2_0.MultilingualUri",
                        xmlelement(name "LocalisedText",
                            xmlelement(name "OeREBKRM_V2_0.LocalisedUri",
                                xmlelement(name "Language", 'de'),
                                xmlelement(name "Text", aemter.web_link_de)
                            ), 
                            xmlelement(name "OeREBKRM_V2_0.LocalisedUri",   
                                case when (select org.kuerzel from altlast_admin.setitem join altlast_admin.setting using (setitem_id) join altlast.org on org.org_id=setting.value::int where key= 'org') = 'GR' 
                                 then xmlelement(name "Language", 'rm')
                                else xmlelement(name "Language", 'fr') end,
                                case when (select org.kuerzel from altlast_admin.setitem join altlast_admin.setting using (setitem_id) join altlast.org on org.org_id=setting.value::int where key= 'org') = 'GR' 
                                 then xmlelement(name "Text", aemter.web_link_rm)
                                else xmlelement(name "Text", aemter.web_link_fr) end
                            ),
                            xmlelement(name "OeREBKRM_V2_0.LocalisedUri",
                                xmlelement(name "Language", 'it'),
                                xmlelement(name "Text", aemter.web_link_it)
                            )
                        )
                    )
                ),
                xmlelement(name "UID", (select case when aemter.org_id = 310 then (select uid from altlast.org where aemter.org_id = org.org_id)
  else aemter.uid
  end as uid ))
  ) as x_v2
    from aemter
),


thema_xml as (
  select 
        xmlelement(name "OeREBKRMkvs_V2_0.Thema.Thema",
