    )
);



$_$;


--
-- Name: geoig_geometry(public.geometry); Type: FUNCTION; Schema: altlast_ili; Owner: -
--

CREATE FUNCTION altlast_ili.geoig_geometry(p_geom public.geometry) RETURNS xml
    LANGUAGE plpgsql STRICT
    AS $$
declare
    result xml;
    geom_type text;
begin
/*
for a "documentation" how to read/write interlis xml geometries see the
iom library in the Gdal (1.10.0+) source tree in ogr/ogrsf_frmts/ili/iom
*/

    geom_type := st_geometrytype(p_geom);
    if geom_type = 'ST_Point' then
        result := altlast_ili._geometry_point(p_geom);
    elsif geom_type = 'ST_Line' or geom_type = 'ST_LineString' then
        result := altlast_ili._geometry_line(p_geom);
    elsif geom_type = 'ST_Polygon' then
        result := altlast_ili._geometry_polygon(p_geom);
     elsif geom_type = 'ST_MultiPolygon' then
        result := altlast_ili._geoig_geometry_multipolygon(p_geom);
    else
        raise 'unsupported geometry type: %', geom_type;
    end if;
    return result;
end
$$;


--
-- Name: geoig_localisedmtext(text, text); Type: FUNCTION; Schema: altlast_ili; Owner: -
--

CREATE FUNCTION altlast_ili.geoig_localisedmtext(p_text text, p_locale text) RETURNS xml
    LANGUAGE plpgsql STRICT
    AS $$
declare 
    result xml;
begin
    select xmlelement(name "LocalisationCH_V1.MultilingualMText", 
            xmlelement(name "LocalisedText", xmlagg(foo.lt))
            ) into result
        from (
            select xmlelement(name "LocalisationCH_V1.LocalisedMText",
                xmlelement(name "Language", p_locale ),
                xmlelement(name "Text", p_text )
                ) as lt
        ) foo;
    return result;
end
$$;


--
-- Name: geoig_localisedtext(text, text); Type: FUNCTION; Schema: altlast_ili; Owner: -
--

CREATE FUNCTION altlast_ili.geoig_localisedtext(p_text text, p_locale text) RETURNS xml
    LANGUAGE plpgsql STRICT
    AS $$
declare 
    result xml;
begin
    select xmlelement(name "LocalisationCH_V1.MultilingualText", 
            xmlelement(name "LocalisedText", xmlagg(foo.lt))
            ) into result
        from (
            select xmlelement(name "LocalisationCH_V1.LocalisedText",
                xmlelement(name "Language", p_locale ),
                xmlelement(name "Text", p_text )
                ) as lt
        ) foo;
    return result;
end
$$;


--
-- Name: geoig_localisedtext_code(integer, text); Type: FUNCTION; Schema: altlast_ili; Owner: -
--

CREATE FUNCTION altlast_ili.geoig_localisedtext_code(p_c_cli_id integer, p_code text) RETURNS xml
    LANGUAGE plpgsql STRICT
    AS $$
declare 
    result xml;
begin
    select xmlelement(name "LocalisationCH_V1.MultilingualText", 
            xmlelement(name "LocalisedText", xmlagg(foo.lt))
            ) into result
        from (
            select xmlelement(name "LocalisationCH_V1.LocalisedText",
                xmlelement(name "Language", t.locale ),
                xmlelement(name "Text", t.msgstr )
                ) as lt
            from altlast.translations t
            left join altlast_ili.language_ordering lo on lo.lang=t.locale
            where t.msgid = altlast.msgid_code(p_c_cli_id, p_code)
            order by coalesce(lo.sort_key, 1337)
        ) foo;
    return result;
end
$$;


--
-- Name: geoig_localisedtext_t(text, text[]); Type: FUNCTION; Schema: altlast_ili; Owner: -
--

CREATE FUNCTION altlast_ili.geoig_localisedtext_t(p_text text, p_locales text[]) RETURNS xml
    LANGUAGE plpgsql STRICT
    AS $$
declare
    result xml;
begin
    select xmlelement(name "LocalisationCH_V1.MultilingualText",
            xmlelement(name "LocalisedText", xmlagg(foo.lt))
            ) into result
        from (
            select xmlelement(name "LocalisationCH_V1.LocalisedText",
                xmlelement(name "Language", ls.locale ),
                xmlelement(name "Text", altlast.t(p_text, ls.locale) )
                ) as lt
            from (
               select lower(locale) as locale, coalesce(lo.sort_key, 1337) as sort_key
               from unnest(p_locales) p(locale)
               left join altlast_ili.language_ordering lo on lo.lang=lower(p.locale)
            ) ls
            order by ls.sort_key
        ) foo;
    return result;
end
$$;


