--
-- Name: geometry_multisurface_so(public.geometry); Type: FUNCTION; Schema: altlast_ili; Owner: -
--

CREATE FUNCTION altlast_ili.geometry_multisurface_so(p_geom public.geometry) RETURNS xml
    LANGUAGE plpgsql STRICT
    AS $$
 declare                                                                                           
     result xml;                                                                                  
     geom_type text;                                                                               
     geom_srid integer;                                                                            
 begin                                                                                             
     geom_type := st_geometrytype(p_geom);                                                         
     geom_srid := st_srid(p_geom);                                                                 
     if geom_type = 'ST_MultiPolygon' and geom_srid = 2056 then                                    
       select xmlelement(name "GeometryCHLV95_V1.MultiSurface",                         
             xmlelement(name "Surfaces", xmlagg(geomxml))) into result                            
                         from (select altlast_ili.geometry_polygon_boundaries_internal_so(
                               st_geometryn(p_geom, generate_series(1,st_numgeometries(p_geom)))   
                           )as geomxml                                                             
             ) foo;                                                                                
     elsif geom_type != 'ST_MultiPolygon' then                                                     
         raise 'unsupported geometry type: %', geom_type;                                          
     else                                                                                          
         raise 'unsupported geometry srid: %', geom_srid;                                          
     end if;                                                                                       
     return result;                                                                                
 end 
$$;


--
-- Name: geometry_polygon_boundaries_internal_so(public.geometry); Type: FUNCTION; Schema: altlast_ili; Owner: -
--

CREATE FUNCTION altlast_ili.geometry_polygon_boundaries_internal_so(p_geom public.geometry) RETURNS xml
    LANGUAGE plpgsql STRICT
    AS $$
 declare                                                                                                 
     result xml;                                                                                         
     geom_type text;                                                                                     
     geom_srid integer;                                                                                  
     geom_numintrings integer;                                                                           
 begin                                                                                                   
     geom_type := st_geometrytype(p_geom);                                                               
     geom_srid := st_srid(p_geom);                                                                       
     geom_numintrings := st_numinteriorring(p_geom);                                                     
     if geom_type = 'ST_Polygon' and geom_srid = 2056 and geom_numintrings < 1 then                      
     select xmlagg(geoxmltext::xml) into result                                                          
                 from (                                                                                  
                     select xmlelement(name "GeometryCHLV95_V1.SurfaceStructure",             
                             xmlelement(name "Surface",                                                  
                             xmlelement(name "SURFACE",                                                  
                             xmlelement(name "BOUNDARY", geom))))::text as geoxmltext                    
                         from  (                                                                         
                             select altlast_ili._geometry_line(                                          
                                 st_ExteriorRing(p_geom)                                                 
                                 ) as geom                                                               
                             union all                                                                   
                             select altlast_ili._geometry_line(                                          
                                 ST_InteriorRingN(p_geom, generate_series(1,st_NumInteriorRings(p_geom)))
                                 )                                                                       
                         ) foo2                                                                          
                 ) foo;                                                                                  
     elsif geom_type = 'ST_Polygon' and geom_srid = 2056 and geom_numintrings > 0 then                   
     select xmlagg(geoxmltext::xml) into result                                                          
                 from (                                                                                  
                     select xmlelement(name "GeometryCHLV95_V1.SurfaceStructure",             
                             xmlelement(name "Surface",                                                  
                             xmlelement(name "SURFACE", geom)))::text as geoxmltext                      
                         from  (                                                                         
                             select altlast_ili._geometry_polygon_boundaries_internal(p_geom) as geom    
                         ) foo2                                                                          
                 ) foo;                                                                                  
                                                                                                         
     elsif geom_type != 'ST_Polygon' then                                                                
         raise 'unsupported geometry type: %', geom_type;                                                
     else                                                                                                
         raise 'unsupported geometry srid: %', geom_srid;                                                
     end if;                                                                                             
     return result;                                                                                      
 end
$$;


