--
-- Name: _archive_grun(); Type: FUNCTION; Schema: altlast_version1; Owner: -
--

CREATE FUNCTION altlast_version1._archive_grun() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    rec record;
    new_grun_id int4;
BEGIN

    IF TG_OP='DELETE' THEN
        UPDATE altlast_version1.grun SET mutations_datum=now(), mutierer_kuerzel=current_user, c_status=FALSE 
        WHERE grun.grun_id=OLD.grun_id;
        RETURN null;
    ELSE
        IF NEW.c_status=TRUE THEN
            SELECT h_gem_id,gb_nummer,c_grun_art,wkb_geometry,bemerkungen INTO rec FROM altlast_version1.grun WHERE grun.c_status=TRUE AND grun.h_gem_id=NEW.h_gem_id AND grun.gb_nummer=NEW.gb_nummer;
            IF rec.wkb_geometry=NEW.wkb_geometry AND rec.bemerkungen=NEW.bemerkungen AND rec.c_grun_art=NEW.c_grun_art THEN
                RETURN NULL;
            ELSE
                IF TG_OP='UPDATE' THEN
                    INSERT INTO altlast_version1.grun (h_gem_id,gb_nummer,c_grun_art,wkb_geometry,bemerkungen,erfassungs_datum,erfasser_kuerzel,c_status) 
                    VALUES (OLD.h_gem_id,OLD.gb_nummer,OLD.c_grun_art,OLD.wkb_geometry,OLD.bemerkungen,OLD.erfassungs_datum,OLD.erfasser_kuerzel,FALSE);

                ELSE --TG_OP='INSERT' 
                    UPDATE altlast_version1.grun SET mutations_datum=now(), mutierer_kuerzel=current_user, c_status=FALSE WHERE grun.c_status=TRUE AND grun.h_gem_id=NEW.h_gem_id AND grun.gb_nummer=NEW.gb_nummer;
                END IF;
                RETURN new;
            END IF;
        ELSE
            RETURN new;
        END IF;
    ENd IF;

END;$$;


--
-- Name: FUNCTION _archive_grun(); Type: COMMENT; Schema: altlast_version1; Owner: -
--

COMMENT ON FUNCTION altlast_version1._archive_grun() IS 'Inkrementelle Archivierung von grun.';


--
-- Name: _archive_grun_after(); Type: FUNCTION; Schema: altlast_version1; Owner: -
--

CREATE FUNCTION altlast_version1._archive_grun_after() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    rec record;
    new_grun_id int4;
BEGIN

    IF TG_OP='DELETE' THEN
        --subj_obje_grun bezeiht sich fortan auf einen archivierten Datensatz aus grun
        RETURN old;
    ELSE
        IF NEW.c_status=TRUE THEN

            FOR rec IN SELECT so.grun_id FROM altlast_version1.subj_obje_grun so JOIN altlast_version1.grun g ON g.grun_id=so.grun_id WHERE g.h_gem_id=NEW.h_gem_id AND g.gb_nummer=NEW.gb_nummer AND g.c_status=FALSE LOOP
                UPDATE altlast_version1.subj_obje_grun SET grun_id=NEW.grun_id WHERE subj_obje_grun.grun_id=rec.grun_id;
            END LOOp;

        END IF;
        RETURN new;
    ENd IF;

END;$$;


--
-- Name: FUNCTION _archive_grun_after(); Type: COMMENT; Schema: altlast_version1; Owner: -
--

COMMENT ON FUNCTION altlast_version1._archive_grun_after() IS 'Aktualisiert grun_subj_obje nach Aenderungen an grun. Bei unveraenderter gb_nummer und h_gem_id wird Referenz auf neuen Datensatz gesetzt. Anderernfalls bleibt Referenz auf archiviertem Datensatz aus grun.';


--
-- Name: _autocomplete_hgemid(); Type: FUNCTION; Schema: altlast_version1; Owner: -
--

CREATE FUNCTION altlast_version1._autocomplete_hgemid() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    hgemid integer;
BEGIN
    IF (NEW.postleitzahl IS NOT NULL AND NEW.ort IS NOT NULL) THEN
        SELECT hgem INTO hgemid FROM (SELECT h_gem_id AS hgem FROM altlast_version1.h_ort WHERE postleitzahl::character varying=NEW.postleitzahl AND ortsname=NEW.ort UNION SELECT NULL AS hgem) AS FOO  LIMIT 1;
        IF hgemid IS NULL THEN
            RAISE NOTICE 'keine Gemeinde mit Postleitzahl % und Ort %',NEW.postleitzahl,NEW.ort;
        END IF;
        -- subje updaten
        UPDATE altlast_version1.subj SET h_gem_id=hgemid WHERE subj_id IN (SELECT subj_id FROM altlast_version1.subj_adr WHERE adr_id=NEW.adr_id);
    
        NEW.h_gem_id := hgemid;
    END IF;
    RETURN NEW;
END;$$;


--
-- Name: _byta_suffix(); Type: FUNCTION; Schema: altlast_version1; Owner: -
--

CREATE FUNCTION altlast_version1._byta_suffix() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  if new.mime_type is not null then
    if new.mime_type ilike 'application/pdf%' then
      new.dateisuffix := 'pdf';
    else if new.mime_type ilike 'application/vnd.oasis.opendocument.text%' then
      new.dateisuffix := 'odt';
      end if;
    end if;
  end if;
  return new;
  
END
$$;


--
-- Name: FUNCTION _byta_suffix(); Type: COMMENT; Schema: altlast_version1; Owner: -
--

COMMENT ON FUNCTION altlast_version1._byta_suffix() IS 'Setzen der Dateiendungen.';


--
-- Name: _check_gs(); Type: FUNCTION; Schema: altlast_version1; Owner: -
--

CREATE FUNCTION altlast_version1._check_gs() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare 
  retval record;
  tmprec record;
BEGIN

    -- CHECKs

    IF TG_OP='UPDATE' THEN



        -- GS "def. KE" darf nicht manuell abgeschlossen werden wenn Datum Fälligkeit
        -- plus 7 Tage noch nicht erreicht ist [Bug 1512]
        if coalesce(new.c_gs_typ = '5' and new.c_gs_status = '50', false) then

    -- Das Feld "Datum Fälligkeit" darf nicht leer sein (wird beim Anlegen des GS
    -- automatisch gefüllt und muss ggf. geändert werden können; darf aber nicht
    -- gelöscht werden) [Bug 1512]
    -- nur bei def KE [Bug 2070]
    if new.end_datum_planung is null then
        raise exception 'SHOWMSG Das Fälligkeitsdatum darf nicht leer sein';
    end if;

        
          if now()<new.end_datum_planung+'7 days'::interval then
            raise NOTICE 'SHOWMSG Das Geschäft darf erst frühestens 7 Tage nach dem Fälligkeitsdatum abgeschlossen werden.';
          end if;
        end if;
        
        IF NOT ((OLD.end_datum_planung IS NOT NULL) AND (NEW.end_datum_planung IS NULL)) THEN -- kein manuelles loeschen des faelligkeitsdatums ist erfolgt
           IF (COALESCE(NEW.end_datum_planung,'1809-02-12'::date)!=COALESCE(OLD.end_datum_planung,'1809-02-12'::date)) OR (COALESCE(NEW.start_datum_planung,'1809-02-12'::date)!=COALESCE(OLD.start_datum_planung,'1809-02-12'::date)) THEN -- 1809-02-12 ist ein platzhalter um nullwerte aus dem vergleich auzuschliesen, da diese nicht mit dem = operator vergleichbar sind -> vergleich ergibt null; nebenbei geburtstag von charles darwin
                IF NEW.end_datum_planung < NEW.start_datum_planung THEN
                    RAISE EXCEPTION 'SHOWMSG Enddatum liegt vor Startdatum.';
                END IF;
                
                IF altlast_version1.default_gs_gss_end_datum_planung(COALESCE(NEW.start_datum_planung,now()::date), NEW.c_gs_typ) IS NOT NULL THEN
                    IF COALESCE(NEW.end_datum_planung,'1809-02-12'::date) != altlast_version1.default_gs_gss_end_datum_planung(COALESCE(NEW.start_datum_planung,now()::date), NEW.c_gs_typ) THEN
                        RAISE NOTICE 'SHOWMSG Enddatum weicht vom Defaultwert ab.';
                    END IF;
                END IF;
            END IF;
        END IF;        
        
        IF NEW.c_gs_typ!=OLD.c_gs_typ THEN
            IF NEW.c_gs_typ IS NULL THEN
                RAISE EXCEPTION 'SHOWMSG Es ist kein Typ für dieses Geschäft definiert.';
            END IF; 
        END IF;
        
        NEW.c_gs_status := COALESCE(NEW.c_gs_status,altlast.default_gs_gss_c_gs_status(NEW.end_datum_ist));
        
        IF ((NEW.c_gs_status=OLD.c_gs_status) AND (OLD.end_datum_ist=NEW.end_datum_ist))=False THEN  -- um updates bei alten, aber nicht den durch die 
                                                                                                     -- tigger definierten contraints entsprechenden daten zu erlauben
        IF NEW.c_gs_status!='50' AND NEW.end_datum_ist IS NOT NULL THEN
                RAISE EXCEPTION 'SHOWMSG Enddatum ist bereits eingetragen, daher gilt das Geschäft als abgeschlossen.';
            END IF;
        END IF;

        retval := new;
    ELSIF TG_OP='INSERT' THEN
    
        -- DEFAULTs
        NEW.gs_titel := COALESCE(NEW.gs_titel,altlast.default_gs_gs_titel(NEW.c_gs_typ));
        NEW.start_datum_ist := COALESCE(NEW.start_datum_ist,altlast.default_gs_gss_start_datum_ist());
        --NEW.start_datum_planung := COALESCE(NEW.start_datum_planung,altlast.default_gs_gss_start_datum_planung(NEW.start_datum_ist));
        NEW.end_datum_planung := COALESCE(NEW.end_datum_planung,altlast.default_gs_gss_end_datum_planung(altlast.default_gs_gss_start_datum_planung(NEW.start_datum_ist), NEW.c_gs_typ));
        NEW.c_gs_status := COALESCE(NEW.c_gs_status,altlast.default_gs_gss_c_gs_status(NEW.end_datum_ist));


        IF NEW.c_gs_typ = '99' THEN --dokumentenimports immer schliessen
            NEW.c_gs_status := '50';
        END IF;
       
        IF NEW.end_datum_planung < NEW.start_datum_planung THEN
            RAISE EXCEPTION 'SHOWMSG Enddatum liegt vor Startdatum.';
        END IF;
        IF NEW.end_datum_planung != altlast_version1.default_gs_gss_end_datum_planung(COALESCE(NEW.start_datum_planung,now()::date), NEW.c_gs_typ) THEN
            RAISE NOTICE 'SHOWMSG Enddatum weicht vom Defaultwert ab.';
        END IF; 
        IF NEW.c_gs_typ IS NULL THEN
            RAISE EXCEPTION 'SHOWMSG Es ist kein Typ für dieses Geschäft definiert.';
        END IF; 

        -- GS "def. KE" darf nicht manuell abgelegt werden falls Bewe <> eine der
        -- belasteten Kategorien (c_bere_res_abwbewe IN ('BLKR06','BLKR07','BLKR08','BLKR13','BLKR14'))
        -- [Bug 1512]
        if new.c_gs_typ = '5' then
    select cod.bezeichnung
      into tmprec
      from altlast_version1.vflz_current_v v 
      join altlast_version1.bere b on b.vflz_id=v.vflz_id
      join altlast_version1.gs_obje gso on gso.obje_id = v.obje_id
      join altlast_version1.cod cod on cod.code=b.c_bere_res_abwbewe and cod.c_cli_id=b.h_bere_res_abwbewe
      where 
        gso.gs_id = new.gs_id
        and
        b.c_bere_res_abwbewe IN ('BLKR06','BLKR07','BLKR08','BLKR13','BLKR14')
      limit 1;
    if tmprec is not null then
      raise exception 'SHOWMSG Geschäft "def. KE" darf aufgrund der Stao-bewertung von "%" nicht angelegt werden.',tmprec.bezeichnung;
    end if;
    
        end if;

        retval := NEW;
    ELSEIF TG_OP='DELETE' THEN
    
        -- GS "def. KE" und GS "Brief Nichteintrag" dürfen nicht manuell gelöscht werden
        -- [Bug 1512]
        if old.c_gs_typ in ('5','7') then
          RAISE EXCEPTION 'SHOWMSG Das Geschäft darf nicht gelöscht werden.';
        end if;
        
        retval := old;
    END IF;
    
    RETURN retval;
END;$$;


--
-- Name: _check_gss(); Type: FUNCTION; Schema: altlast_version1; Owner: -
--

CREATE FUNCTION altlast_version1._check_gss() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN

    
    -- CHECKS
    
    IF TG_OP='UPDATE' THEN

        IF NOT ((OLD.end_datum_planung IS NOT NULL) AND (NEW.end_datum_planung IS NULL)) THEN -- kein manuelles loeschen des faelligkeitsdatums ist erfolgt
           IF (COALESCE(NEW.end_datum_planung,'1809-02-12'::date)!=COALESCE(OLD.end_datum_planung,'1809-02-12'::date)) OR (COALESCE(NEW.start_datum_planung,'1809-02-12'::date)!=COALESCE(OLD.start_datum_planung,'1809-02-12'::date)) THEN -- 1809-02-12 ist ein platzhalter um nullwerte aus dem vergleich auzuschliesen, da diese nicht mit dem = operator vergleichbar sind -> vergleich ergibt null; nebenbei geburtstag von charles darwin
                IF NEW.end_datum_planung < NEW.start_datum_planung THEN
                    RAISE EXCEPTION 'SHOWMSG Enddatum liegt vor Startdatum.';
                END IF;
                
                IF altlast_version1.default_gs_gss_end_datum_planung(COALESCE(NEW.start_datum_planung,now()::date), NEW.c_gss_typ) IS NOT NULL THEN
                    IF COALESCE(NEW.end_datum_planung,'1809-02-12'::date) != altlast_version1.default_gs_gss_end_datum_planung(COALESCE(NEW.start_datum_planung,now()::date), NULL::character varying) THEN
                        RAISE NOTICE 'SHOWMSG Enddatum weicht vom Defaultwert ab.';
                    END IF;
                END IF;
            END IF;
        END IF;    
    /*
        IF (NEW.end_datum_planung!=OLD.end_datum_planung) OR (NEW.start_datum_planung!=OLD.start_datum_planung) THEN
            IF NEW.end_datum_planung<NEW.start_datum_planung THEN
                RAISE EXCEPTION 'SHOWMSG Enddatum liegt vor Startdatum.';
            END IF;
            
            IF NEW.end_datum_planung != altlast_version1.default_gs_gss_end_datum_planung(COALESCE(NEW.start_datum_planung,now()::date), NULL::character varying) THEN
                RAISE NOTICE 'SHOWMSG Enddatum weicht vom Defaultwert ab.';
            END IF;
        END IF;
*/
        IF NEW.c_gss_typ!=OLD.c_gss_typ THEN
            IF NEW.c_gss_typ IS NULL THEN
                RAISE EXCEPTION 'SHOWMSG Es ist kein Typ für dieses Teilgeschäft definiert.';
            END IF;
        END IF;
        
        NEW.c_gss_status := COALESCE(NEW.c_gss_status,altlast.default_gs_gss_c_gs_status(NEW.end_datum_ist));
        
        IF ((NEW.c_gss_status=OLD.c_gss_status) AND (OLD.end_datum_ist=NEW.end_datum_ist))=False THEN  -- um updates bei alten, aber nicht den durch die 
                                                                                                       -- tigger definierten contraints entsprechenden daten zu erlauben
            IF NEW.c_gss_status!='50' AND NEW.end_datum_ist IS NOT NULL THEN
                RAISE EXCEPTION 'SHOWMSG Enddatum ist bereits eingetragen, daher gilt das Teilgeschäft als abgeschlossen.';
            END IF;
        END IF;
    
    ELSIF TG_OP='INSERT' THEN

        -- DEFAULT-werte
        NEW.gss_titel := COALESCE(NEW.gss_titel,altlast.default_gss_gss_titel(NEW.c_gss_typ,NEW.gs_id));
        NEW.start_datum_ist := COALESCE(NEW.start_datum_ist,altlast.default_gs_gss_start_datum_ist());
        --NEW.start_datum_planung := COALESCE(NEW.start_datum_planung,altlast.default_gs_gss_start_datum_planung(NEW.start_datum_ist));
        NEW.end_datum_planung := COALESCE(NEW.end_datum_planung,altlast.default_gs_gss_end_datum_planung(altlast.default_gs_gss_start_datum_planung(NEW.start_datum_ist), NULL::character varying));
        NEW.c_gss_status := COALESCE(NEW.c_gss_status,altlast.default_gs_gss_c_gs_status(NEW.end_datum_ist));

    
        IF NEW.c_gss_typ = '99' THEN --dokumentenimports immer schliessen
            NEW.c_gss_status := '50';
        END IF;
    
        IF NEW.end_datum_planung<NEW.start_datum_planung THEN
            RAISE EXCEPTION 'SHOWMSG Enddatum liegt vor Startdatum.';
        END IF;
        IF NEW.end_datum_planung != altlast_version1.default_gs_gss_end_datum_planung(COALESCE(NEW.start_datum_planung,now()::date), NULL::character varying) THEN
            RAISE NOTICE 'SHOWMSG Enddatum weicht vom Defaultwert ab.';
        END IF;   
        IF NEW.c_gss_typ IS NULL THEN
            RAISE EXCEPTION 'SHOWMSG Es ist kein Typ für dieses Teilgeschäft definiert.';
        END IF;
    
    END IF;
    
   RETURN NEW;
END;$$;


--
-- Name: _check_subj_obje(); Type: FUNCTION; Schema: altlast_version1; Owner: -
--

CREATE FUNCTION altlast_version1._check_subj_obje() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
 cnt integer;
 rec record;
BEGIN
    SELECT count(*) INTO cnt FROM altlast_version1.cod WHERE code=NEW.c_subj_obje_bez_art AND c_cli_id=22;
    IF cnt=0 THEN
        RAISE EXCEPTION 'SHOWMSG Keine gültige Beziehungsart gewählt.';
    END IF;

    SELECT count(*) INTO cnt FROM altlast_version1.subj_obje WHERE subj_id=NEW.subj_id AND obje_id=NEW.obje_id AND c_subj_obje_bez_art=NEW.c_subj_obje_bez_art;
    IF cnt>0 THEN
        SELECT c.bezeichnung,s.name INTO rec FROM altlast_version1.subj s ,altlast.cod c WHERE c.c_cli_id=22 AND c.code=NEW.c_subj_obje_bez_art AND s.subj_id=NEW.subj_id;
        RAISE EXCEPTION 'SHOWMSG Subjekt % ist diesem Standort bereits in der Bezeihungsart % zugewiesen.',rec.name,rec.bezeichnung;
    END IF;
    
    RETURN NEW;
END;$$;


--
-- Name: _clean_history(); Type: FUNCTION; Schema: altlast_version1; Owner: -
--

CREATE FUNCTION altlast_version1._clean_history() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    DELETE FROM altlast_version1.history
  WHERE  (history.history_id IN ( SELECT history.history_id
           FROM altlast_version1.history WHERE user_id=NEW.user_id
          ORDER BY history."timestamp" DESC
         OFFSET 11));
    -- anmerkung: tatsaechlich wird immer ein eintrag mehr als der oben spezifizierte offset
    -- angezeigt, da direkt nach der ausfuehrung der funktion ein insert stattfindet
DELETE FROM altlast_version1.history WHERE kategorie=NEW.kategorie AND user_id=NEW.user_id AND params=NEW.params;

   RETURN NEW;
END;$$;


--
-- Name: _delete_byta(); Type: FUNCTION; Schema: altlast_version1; Owner: -
--

CREATE FUNCTION altlast_version1._delete_byta() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE 
    anzahl integer;
BEGIN
    SELECT count(*) INTO anzahl FROM altlast_version1.byta_gss where byta_id=OLD.byta_id AND gss_id!=OLD.gss_id;
    IF anzahl=0 THEN
        DELETE FROM altlast_version1.byta WHERE byta_id=OLD.byta_id;
    END IF;
    RETURN OLD;
END;$$;


--
-- Name: _gs_hist(); Type: FUNCTION; Schema: altlast_version1; Owner: -
--

CREATE FUNCTION altlast_version1._gs_hist() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  msgtext text;
  vflzid integer;
BEGIN
  if new.c_gs_status is not null then
    if new.c_gs_status in ('7', '5') then
      select 'Automatische Historisieriung wg. Änderunge des Geschäftstatus auf ' ||coalesce( bezeichnung,'') into msgtext
        from altlast_version1.cod
        where c_cli_id = new.h_gs_status and code = new.c_gs_status
        limit 1;

      perform hist.snapshot(1, v.vflz_id, msgtext)  from 
        altlast_version1.vflz_hist_v vh
        join altlast_version1.vflz v on v.vflz_id = vh.vflz_id 
        join altlast_version1.obje o on v.obje_id = o.obje_id
        join altlast_version1.gs_obje gso on gso.obje_id=o.obje_id
        join altlast_version1.gs gs on gs.gs_id = gso.gs_id
        where gs.gs_id = new.gs_id;

    end if; 
  end if;
    
   RETURN NEW;
END;$$;


--
-- Name: _gs_set_vflz_bearbstand(); Type: FUNCTION; Schema: altlast_version1; Owner: -
--

CREATE FUNCTION altlast_version1._gs_set_vflz_bearbstand() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    abgeschlossen boolean;
    bearbstand character varying(8);
    do_execute boolean;
BEGIN
    do_execute := False;
    
    -- nur ausfuehren wenn sich der status geaendert hat
    IF TG_OP='INSERT' THEN
        do_execute:=True;
    ELSIF TG_OP='UPDATE' THEN
        IF NEW.c_gs_status!=OLD.c_gs_status THEN
            do_execute:=True;
        END IF;
    END IF;

    --

    -- war vorläufig auskommentiert nach Telefonat Marcel, 090709, s. #908
    -- Bug 1175
    IF do_execute=True THEN

        IF NEW.h_gs_status=2001 AND NEW.c_gs_status='50' THEN
            bearbstand := Null;
        
            IF NEW.c_gs_typ='7' THEN  -- Abschluss des Geschäfts "Brief Nichteintrag" => Bearbeitungsstand setzen "Brief Nichteintrag verschickt, Bearbeitung abgeschlossen"
                bearbstand:='BLBS06';
            ELSIF NEW.c_gs_typ='5' THEN -- bschluss des Geschäftes "def. Eintrag in Kataster: Information Inhaber" => BLBS09: "definitiver Katastereintrag rechtskräftig"
                bearbstand:='BLBS05';
            END IF;
        
            IF bearbstand IS NOT NULL THEN
                UPDATE altlast_version1.vflz SET c_vflz_bearbstand=bearbstand WHERE vflz_id IN (SELECT v.vflz_id FROM altlast_version1.vflz v JOIN altlast_version1.obje o ON o.obje_id=v.obje_id JOIN altlast_version1.gs_obje gso ON gso.obje_id=o.obje_id WHERE gso.gs_id=NEW.gs_id);
            END IF;
        END IF;

    END IF;
    
    
  RETURN NEW;
END;$$;


--
-- Name: _gss_set_gs_status(); Type: FUNCTION; Schema: altlast_version1; Owner: -
--

CREATE FUNCTION altlast_version1._gss_set_gs_status() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    alle_abgeschlossen boolean;
    do_execute boolean;
BEGIN

/*nach Telefonat mit MArcel, 090709: alle EXCEPTIONs zu NOTICEs geändert. UPDATE auskommentiert, s. #908*/
    
    IF TG_OP='INSERT' THEN
    
        -- checken ob gs geschlossen
        SELECT ((c_gs_status='50' AND h_gs_status=2001) AND NEW.c_gss_status!='50') INTO alle_abgeschlossen FROM altlast_version1.gs WHERE gs_id=NEW.gs_id;
        IF alle_abgeschlossen THEN
                RAISE NOTICE 'SHOWMSG Teilgeschäfte sind in Bearbeitung, obwohl das Geschäft als abgeschlossen markiert ist.';
        END IF;
    
    ELSIF TG_OP='UPDATE' THEN
    
        -- checken ob gs geschlossen und ob der neue gss status was anderes als 'geschlossen' ist
        SELECT (c_gs_status='50' AND h_gs_status=2001) AND (NEW.c_gss_status!='50') INTO alle_abgeschlossen FROM altlast_version1.gs WHERE gs_id=NEW.gs_id;
        IF alle_abgeschlossen THEN
            RAISE NOTICE 'SHOWMSG Teilgeschäfte sind in Bearbeitung, obwohl das Geschäft als abgeschlossen markiert ist.';
        END IF;
    
    
        -- wenn die zahl aller teilgeschaefte mehr als 0 ist und diese alle abgeschlossen sind -> auch geschaeft abschliessen. 
        -- den status der aktuellen aenderung mit einbeziehen
        SELECT ((count(gss1.gss_id)=count(gss2.gss_id)) AND (count(gss1.gss_id)>0)) INTO alle_abgeschlossen 
            FROM altlast_version1.gss gss1, 
                (SELECT gss_id,gs_id,h_gss_status,c_gss_status 
                    FROM altlast_version1.gss 
                    WHERE gs_id=NEW.gs_id AND gss_id!=NEW.gss_id
                UNION 
                SELECT NEW.gss_id,NEW.gs_id,NEW.h_gss_status,NEW.c_gss_status ) gss2 
            WHERE gss1.gs_id=NEW.gs_id AND gss2.gs_id=NEW.gs_id AND gss2.h_gss_status=2001 AND gss2.c_gss_status='50';
            
        IF alle_abgeschlossen=True THEN 
            --UPDATE altlast_version1.gs SET end_datum_ist=now()::date, h_gs_status=2001, c_gs_status='50' WHERE gs_id=NEW.gs_id;
            --RAISE NOTICE 'SHOWMSG Das übergeordnete Geschäft wurde ebenfalls als abgeschlossen markiert.';
            RAISE NOTICE 'SHOWMSG Alle Teilgeschäfte sind abgeschlossen.';
        END IF;  
    
    END IF;

  RETURN NEW;
END;$$;


--
-- Name: _historize_grun(); Type: FUNCTION; Schema: altlast_version1; Owner: -
--

CREATE FUNCTION altlast_version1._historize_grun() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    rec record;
BEGIN


    SELECT h_gem_id,gb_nummer,c_grun_art,wkb_geometry,bemerkungen INTO rec FROM altlast_version1.grun WHERE grun.h_gem_id=NEW.h_gem_id AND grun.gb_nummer=NEW.gb_nummer;
    IF rec.wkb_geometry=NEW.wkb_geometry AND rec.bemerkungen=NEW.bemerkungen AND rec.c_grun_art=NEW.c_grun_art THEN
        RETURN NULL;
    ELSE
        UPDATE altlast_version1.grun SET mutations_datum=now(), mutierer_kuerzel=current_user, c_status=FALSE WHERE grun.h_gem_id=NEW.h_gem_id AND grun.gb_nummer=NEW.gb_nummer;
        RETURN new;
    END IF;

END;$$;


