--
-- Name: _latest_changes_gs(); Type: FUNCTION; Schema: altlast_version1; Owner: -
--

CREATE FUNCTION altlast_version1._latest_changes_gs() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    ititel text;
    ichanges text;
    istandort text;
BEGIN
    SELECT ok.sto_kennung INTO istandort FROM altlast_version1.gs_obje gso JOIN altlast_version1.obje_kennung_v ok ON ok.obje_id=gso.obje_id WHERE gso.gs_id=NEW.gs_id;
    SELECT NEW.gs_titel INTO ititel;

    ichanges:=NULL;
    
    IF TG_OP='INSERT' THEN
        IF NEW.gs_titel IS NOt NULL THEN
            SELECT altlast_version1.commacat(ichanges,'Titel ' || NEW.gs_titel) INTO ichanges;
        END IF;
        
        IF NEW.bemerkungen IS NOt NULL THEN
            SELECT altlast_version1.commacat(ichanges,'Bemerkungen ' || NEW.bemerkungen) INTO ichanges;
        END IF;
        
        IF NEW.start_datum_planung IS NOt NULL THEN
            SELECT altlast_version1.commacat(ichanges,'geplanter Start ' || to_char(NEW.start_datum_planung, 'DD.MM.YYYY')) INTO ichanges;
        END IF;

        IF  NEW.start_datum_ist IS NOt NULL THEN
            SELECT altlast_version1.commacat(ichanges,'Start ' || to_char(NEW.start_datum_planung, 'DD.MM.YYYY') ) INTO ichanges;
        END IF;

        IF NEW.end_datum_planung IS NOt NULL THEN
            SELECT altlast_version1.commacat(ichanges,'Fälligkeit ' || to_char(NEW.end_datum_planung, 'DD.MM.YYYY') ) INTO ichanges;
        END IF;   

        IF NEW.end_datum_ist IS NOt NULL THEN
            SELECT altlast_version1.commacat(ichanges,'Abschluss ' || to_char(NEW.end_datum_ist, 'DD.MM.YYYY'))  INTO ichanges;
        END IF;
        
    ELSIF TG_OP='UPDATE' THEN
        IF OLD.gs_titel!=NEW.gs_titel OR (OLD.gs_titel IS NULL AND NEW.gs_titel IS NOt NULL) THEN
            SELECT altlast_version1.commacat(ichanges,'Titel ' || NEW.gs_titel) INTO ichanges;
        END IF;
        
        IF OLD.bemerkungen!=NEW.bemerkungen OR (OLD.bemerkungen IS NULL AND NEW.bemerkungen IS NOt NULL) THEN
            SELECT altlast_version1.commacat(ichanges,'Bemerkungen ' || NEW.bemerkungen) INTO ichanges;
        END IF;
        
        IF OLD.start_datum_planung!=NEW.start_datum_planung OR (OLD.start_datum_planung IS NULL AND NEW.start_datum_planung IS NOt NULL) THEN
            SELECT altlast_version1.commacat(ichanges,'geplanter Start ' || to_char(NEW.start_datum_planung, 'DD.MM.YYYY')) INTO ichanges;
        END IF;

        IF OLD.start_datum_ist!=NEW.start_datum_ist OR (OLD.start_datum_ist IS NULL AND NEW.start_datum_ist IS NOt NULL) THEN
            SELECT altlast_version1.commacat(ichanges,'Start ' || to_char(NEW.start_datum_planung, 'DD.MM.YYYY') ) INTO ichanges;
        END IF;

        IF OLD.end_datum_planung!=NEW.end_datum_planung OR (OLD.end_datum_planung IS NULL AND NEW.end_datum_planung IS NOt NULL) THEN
            SELECT altlast_version1.commacat(ichanges,'Fälligkeit ' || to_char(NEW.end_datum_planung, 'DD.MM.YYYY') ) INTO ichanges;
        END IF;   

        IF OLD.end_datum_ist!=NEW.end_datum_ist OR (OLD.end_datum_ist IS NULL AND NEW.end_datum_ist IS NOt NULL) THEN
            SELECT altlast_version1.commacat(ichanges,'Abschluss ' || to_char(NEW.end_datum_ist, 'DD.MM.YYYY'))  INTO ichanges;
        END IF;    
    END IF;

    INSERT INTO altlast_version1.latest_changes (titel,changes,kategorie,mutierer_kuerzel,key_id,standort) VALUES (ititel,ichanges,'gs',current_user,NEW.gs_id,istandort);
    
    RETURN NEW;
END;$$;


--
-- Name: _latest_changes_gs_subj(); Type: FUNCTION; Schema: altlast_version1; Owner: -
--

CREATE FUNCTION altlast_version1._latest_changes_gs_subj() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    ititel text;
    ichanges text;
    istandort text;
BEGIN

    IF TG_OP!='INSERT' THEN
        SELECT gs.gs_titel INTO ititel FROM altlast_version1.gs gs WHERE gs.gs_id=OLD.gs_id;
        SELECT ok.sto_kennung INTO istandort FROM altlast_version1.gs gs JOIN altlast_version1.gs_obje gso ON gs.gs_id=gso.gs_id JOIN altlast_version1.obje_kennung_v ok ON ok.obje_id=gso.obje_id WHERE gs.gs_id=OLD.gs_id;
    ELSE
        SELECT gs.gs_titel INTO ititel FROM altlast_version1.gs gs WHERE gs.gs_id=NEW.gs_id;
        SELECT ok.sto_kennung INTO istandort FROM altlast_version1.gs gs JOIN altlast_version1.gs_obje gso ON gs.gs_id=gso.gs_id JOIN altlast_version1.obje_kennung_v ok ON ok.obje_id=gso.obje_id WHERE gs.gs_id=NEW.gs_id;
    END IF;


    ichanges:=NULL;
    
    
    IF TG_OP='DELETE' THEN
        SELECT 'Beteiligte entfernt :' || COALESCE(s.vorname,'') || ' ' || COALESCE(s.name,'') INTO ichanges FROM altlast_version1.subj s WHERE s.subj_id=OLD.subj_id;
    ELSE
        SELECT 'Beteiligte ' || COALESCE(s.vorname,'') || ' ' || COALESCE(s.name,'') INTO ichanges FROM altlast_version1.subj s WHERE s.subj_id=NEW.subj_id;
    END IF;
    
    IF TG_OP!='INSERT' THEN
        INSERT INTO altlast_version1.latest_changes (titel,changes,kategorie,mutierer_kuerzel,key_id,standort) VALUES (ititel,ichanges,'gs',current_user,OLD.gs_id,istandort);
    ELSE
        INSERT INTO altlast_version1.latest_changes (titel,changes,kategorie,mutierer_kuerzel,key_id,standort) VALUES (ititel,ichanges,'gs',current_user,NEW.gs_id,istandort);
    END IF;

    IF TG_OP='DELETE' THEN
  RETURN OLD;
    ELSE
  RETURN NEW;
    END IF;
END;$$;


--
-- Name: _latest_changes_gss(); Type: FUNCTION; Schema: altlast_version1; Owner: -
--

CREATE FUNCTION altlast_version1._latest_changes_gss() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    ititel text;
    ichanges text;
    istandort text;
BEGIN
    SELECT NEW.gss_titel INTO ititel; 
    SELECT ok.sto_kennung INTO istandort FROM altlast_version1.gs gs JOIN altlast_version1.gs_obje gso ON gs.gs_id=gso.gs_id JOIN altlast_version1.obje_kennung_v ok ON ok.obje_id=gso.obje_id WHERE gs.gs_id=NEW.gs_id;
    
    
    ichanges:=NULL;
 
    IF TG_OP='INSERT' THEN
        IF NEW.gss_titel IS NOt NULL THEN
            SELECT altlast_version1.commacat(ichanges,'Titel ' || NEW.gss_titel) INTO ichanges;
        END IF;
        
        IF NEW.bemerkungen IS NOt NULL THEN
            SELECT altlast_version1.commacat(ichanges,'Bemerkungen ' || NEW.bemerkungen) INTO ichanges;
        END IF;
        
        IF NEW.start_datum_planung IS NOt NULL THEN
            SELECT altlast_version1.commacat(ichanges,'geplanter Start ' || to_char(NEW.start_datum_planung, 'DD.MM.YYYY')) INTO ichanges;
        END IF;

        IF NEW.start_datum_ist IS NOt NULL THEN
            SELECT altlast_version1.commacat(ichanges,'Start ' || to_char(NEW.start_datum_planung, 'DD.MM.YYYY') ) INTO ichanges;
        END IF;

        IF NEW.end_datum_planung IS NOt NULL THEN
            SELECT altlast_version1.commacat(ichanges,'Fälligkeit ' || to_char(NEW.end_datum_planung, 'DD.MM.YYYY') ) INTO ichanges;
        END IF;   

        IF NEW.end_datum_ist IS NOt NULL THEN
            SELECT altlast_version1.commacat(ichanges,'Abschluss ' || to_char(NEW.end_datum_ist, 'DD.MM.YYYY'))  INTO ichanges;
        END IF;  
 
    ELSIF TG_OP='UPDATE' THEN
        IF OLD.gss_titel!=NEW.gss_titel OR (OLD.gss_titel IS NULL AND NEW.gss_titel IS NOt NULL) THEN
            SELECT altlast_version1.commacat(ichanges,'Titel ' || NEW.gss_titel) INTO ichanges;
        END IF;
        
        IF OLD.bemerkungen!=NEW.bemerkungen OR (OLD.bemerkungen IS NULL AND NEW.bemerkungen IS NOt NULL) THEN
            SELECT altlast_version1.commacat(ichanges,'Bemerkungen ' || NEW.bemerkungen) INTO ichanges;
        END IF;
        
        IF OLD.start_datum_planung!=NEW.start_datum_planung OR (OLD.start_datum_planung IS NULL AND NEW.start_datum_planung IS NOt NULL) THEN
            SELECT altlast_version1.commacat(ichanges,'geplanter Start ' || to_char(NEW.start_datum_planung, 'DD.MM.YYYY')) INTO ichanges;
        END IF;

        IF OLD.start_datum_ist!=NEW.start_datum_ist OR (OLD.start_datum_ist IS NULL AND NEW.start_datum_ist IS NOt NULL) THEN
            SELECT altlast_version1.commacat(ichanges,'Start ' || to_char(NEW.start_datum_planung, 'DD.MM.YYYY') ) INTO ichanges;
        END IF;

        IF OLD.end_datum_planung!=NEW.end_datum_planung OR (OLD.end_datum_planung IS NULL AND NEW.end_datum_planung IS NOt NULL) THEN
            SELECT altlast_version1.commacat(ichanges,'Fälligkeit ' || to_char(NEW.end_datum_planung, 'DD.MM.YYYY') ) INTO ichanges;
        END IF;   

        IF OLD.end_datum_ist!=NEW.end_datum_ist OR (OLD.end_datum_ist IS NULL AND NEW.end_datum_ist IS NOt NULL) THEN
            SELECT altlast_version1.commacat(ichanges,'Abschluss ' || to_char(NEW.end_datum_ist, 'DD.MM.YYYY'))  INTO ichanges;
        END IF;   
    END IF;

    INSERT INTO altlast_version1.latest_changes (titel,changes,kategorie,mutierer_kuerzel,key_id,standort) VALUES (ititel,ichanges,'gss',current_user,NEW.gss_id,istandort);
    
    RETURN NEW;
END;$$;


--
-- Name: _latest_changes_gss_subj(); Type: FUNCTION; Schema: altlast_version1; Owner: -
--

CREATE FUNCTION altlast_version1._latest_changes_gss_subj() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    ititel text;
    ichanges text;
    istandort text;
BEGIN

    IF TG_OP!='INSERT' THEN 
        SELECT  gss.gss_titel INTO ititel FROM altlast_version1.gss  WHERE gss.gss_id=OLD.gss_id;
        SELECT ok.sto_kennung INTO istandort FROM altlast_version1.gss gss JOIN altlast_version1.gs gs ON gs.gs_id=gss.gs_id JOIN altlast_version1.gs_obje gso ON gs.gs_id=gso.gs_id JOIN altlast_version1.obje_kennung_v ok ON ok.obje_id=gso.obje_id WHERE gss.gss_id=OLD.gss_id;
    ELSE
        SELECT gss.gss_titel INTO ititel FROM altlast_version1.gss  WHERE gss.gss_id=NEW.gss_id;
        SELECT ok.sto_kennung INTO istandort FROM altlast_version1.gss gss JOIN altlast_version1.gs gs ON gs.gs_id=gss.gs_id JOIN altlast_version1.gs_obje gso ON gs.gs_id=gso.gs_id JOIN altlast_version1.obje_kennung_v ok ON ok.obje_id=gso.obje_id WHERE gss.gss_id=NEW.gss_id;
    END IF;


    ichanges:=NULL;
      
    IF TG_OP='DELETE' THEN
        SELECT 'Beteiligte entfernt :' || COALESCE(s.vorname,'') || ' ' || COALESCE(s.name,'') INTO ichanges FROM altlast_version1.subj s WHERE s.subj_id=OLD.subj_id;
    ELSE
        SELECT 'Beteiligte ' || COALESCE(s.vorname,'') || ' ' || COALESCE(s.name,'') INTO ichanges FROM altlast_version1.subj s WHERE s.subj_id=NEW.subj_id;
    END IF;
    
    
    IF TG_OP!='INSERT' THEN
        INSERT INTO altlast_version1.latest_changes (titel,changes,kategorie,mutierer_kuerzel,key_id,standort) VALUES (ititel,ichanges,'gss',current_user,OLD.gs_id,istandort);
    ELSE
        INSERT INTO altlast_version1.latest_changes (titel,changes,kategorie,mutierer_kuerzel,key_id,standort) VALUES (ititel,ichanges,'gss',current_user,NEW.gs_id,istandort);
    END IF;
    
    
    IF TG_OP='DELETE' THEN
        RETURN OLD;
    ELSE
        RETURN NEW;
    END IF;
    
END;$$;


--
-- Name: _materialize_gemeindeort_v(); Type: FUNCTION; Schema: altlast_version1; Owner: -
--

CREATE FUNCTION altlast_version1._materialize_gemeindeort_v() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN

DELETE FROM altlast_version1.gemeindeort_v;

INSERT INTO altlast_version1.gemeindeort_v SELECT DISTINCT g.h_gem_id, o.h_ort_id, g.gemeinde, o.ortsname, 
        CASE
            WHEN g.gemeinde::text <> o.ortsname::text THEN ((g.gemeinde::text || ' - '::text) || o.ortsname::text)::character varying
            ELSE g.gemeinde
        END AS gemeindeort, o.postleitzahl, 
        CASE
            WHEN o.postleitzahl_zusatz > 0 THEN o.postleitzahl_zusatz
            ELSE NULL::smallint
        END AS "case"
   FROM altlast_version1.h_ort o
   JOIN altlast_version1.h_gem g ON g.h_gem_id = o.h_gem_id
  ORDER BY 
   CASE
       WHEN g.gemeinde::text <> o.ortsname::text THEN ((g.gemeinde::text || ' - '::text) || o.ortsname::text)::character varying
       ELSE g.gemeinde
   END, g.h_gem_id, o.h_ort_id, g.gemeinde, o.ortsname, o.postleitzahl, 
   CASE
       WHEN o.postleitzahl_zusatz > 0 THEN o.postleitzahl_zusatz
       ELSE NULL::smallint
   END;
   
RETURN NULL;   
   

END;$$;


--
-- Name: FUNCTION _materialize_gemeindeort_v(); Type: COMMENT; Schema: altlast_version1; Owner: -
--

COMMENT ON FUNCTION altlast_version1._materialize_gemeindeort_v() IS 'Erstellt Materialized view aus Gemeinde/Ort. Getriggert aus h_gem und h_ort.';


--
-- Name: _materialize_gs_subj_all_v(); Type: FUNCTION; Schema: altlast_version1; Owner: -
--

CREATE FUNCTION altlast_version1._materialize_gs_subj_all_v() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  docontinue boolean;
BEGIN

IF TG_OP = 'DELETE' THEN

  --subj ist uber Cascade Delete bereits integriert
  IF TG_RELNAME='gs_subj' THEN
    DELETE FROM altlast_version1.gs_subj_all_v WHERE gs_gss_id=OLD.gs_id AND isgs;
  ELSIF TG_RELNAME='gss_subj' THEN
    DELETE FROM altlast_version1.gs_subj_all_v WHERE gs_gss_id=OLD.gss_id AND NOT isgs;
  ELSIF TG_RELNAME='subj' THEN
    DELETE FROM altlast_version1.subj_kennung_v WHERE subj_id=OLD.subj_id;
  END IF;    
  

  RETURN  OLD;

ELSE

  IF TG_RELNAME='gs_subj' THEN
    INSERT INTO altlast_version1.gs_subj_all_v (gs_gss_id,isgs,subj) VALUES (NEW.gs_id,TRUE,altlast.collect_subj(NEW.gs_id,TRUE));
  ELSIF TG_RELNAME='gss_subj' THEN
    INSERT INTO altlast_version1.gs_subj_all_v (gs_gss_id,isgs,subj) VALUES (NEW.gss_id,FALSE,altlast.collect_subj(NEW.gss_id,FALSE));
  ELSIF TG_RELNAME='subj' THEN
    docontinue:=TG_OP='INSERT';
    IF NOT docontinue THEN
      docontinue:=NEW.name<>OLD.name OR NEW.vorname<>OLD.vorname OR NEW.taetigkeit<>OLD.taetigkeit ;
    END IF;
    IF docontinue THEN
      INSERT INTO altlast_version1.gs_subj_all_v (gs_gss_id,isgs,subj) SELECT gs_id,TRUE,altlast.collect_subj(gs_id,TRUE) FROM altlast_version1.gs_subj WHERE gs_subj.subj_id=NEW.subj_id;
      INSERT INTO altlast_version1.gs_subj_all_v (gs_gss_id,isgs,subj) SELECT gss_id,FALSE,altlast.collect_subj(gss_id,FALSE) FROM altlast_version1.gss_subj WHERE gss_subj.subj_id=NEW.subj_id;
      INSERT INTO altlast_version1.subj_kennung_v (subj_id,subj_kennung) VALUES (NEW.subj_id, altlast_version1.concat_subj(NEW.name::text, NEW.vorname::text, NEW.taetigkeit::text));
    END IF;
  END IF;

  RETURN NEW;

END IF;


END;$$;


