--

CREATE FUNCTION altlast_version1._nullstring_subj() RETURNS trigger
    LANGUAGE plpgsql
    AS $$

BEGIN

    IF NEW.name='' THEN
        NEW.name=NULL;
    END IF;
    
    IF NEW.vorname='' THEN
