    -- ist der aktuelle user Mitgleide der Gruppe ALTLAST     
     SELECT subj_id,bez_art INTO rec FROM altlast_version1.get_sachbearbeiter();

    IF rec.subj_id IS NOT NULL THEN
    
            -- Als Sachbearbeiter einsetzen (c_cli_id=22 code 10: Behoerde AUE)
            BEGIN
                IF TG_TABLE_NAME='gs' THEN
