--
-- Name: _update_kbsgeo_geometry(); Type: FUNCTION; Schema: altlast_version1; Owner: -
--

CREATE FUNCTION altlast_version1._update_kbsgeo_geometry() RETURNS trigger
    LANGUAGE plpgsql
    AS $$DECLARE
  asql VARCHAR;
  rec RECORD;
  rec2 RECORD;
  geom VARCHAR;
  doContinue BOOLEAN;
BEGIN

IF (TG_OP = 'UPDATE') THEN
  doContinue := (TG_OP = 'UPDATE' AND (NEW.wkb_geometry IS NOT NULL) AND (NEW.wkb_geometry <> OLD.wkb_geometry)) ;
END IF;
IF (TG_OP = 'INSERT') THEN
  doContinue := true;
END IF;

IF doContinue THEN

  geom := ST_AsText(NEW.wkb_geometry);

  SELECT INTO rec ST_Union(wkb_geometry) AS wkb_geometry FROM altlast_version1.kbsgeo WHERE kbsgeo.vflz_id=NEW.vflz_id;
  IF rec.wkb_geometry IS NOT NULL THEN  
    geom := ST_AsText(ST_Union(rec.wkb_geometry,GeometryFromText(geom)));
  END IF;
  
  SELECT INTO rec2 ST_Union(wkb_geometry) AS wkb_geometry FROM altlast_version1.vflgeo WHERE vflgeo.vflz_id=NEW.vflz_id;
  IF rec2.wkb_geometry IS NOT NULL THEN 
    geom := ST_AsText(ST_Union(rec2.wkb_geometry,GeometryFromText(geom)));
  END IF;     
  
  IF geom <> ST_AsText(NEW.wkb_geometry) THEN
    asql := 'UPDATE altlast_version1.vflgeo SET wkb_geometry=GeometryFromText(''' || geom || ''');';
    EXECUTE asql;
  END IF;
  
END IF; 


RETURN NEW;
END;$$;


--
-- Name: FUNCTION _update_kbsgeo_geometry(); Type: COMMENT; Schema: altlast_version1; Owner: -
--

COMMENT ON FUNCTION altlast_version1._update_kbsgeo_geometry() IS 'Schreibt zusammenhängende Geoemtrie aus allen Einzelgeometrien eines Standortes in vflgeo. Triggert damit indirekt _UPDATE_vflgeo_geometry.';


--
-- Name: _update_vflgeo_geometry(); Type: FUNCTION; Schema: altlast_version1; Owner: -
--

CREATE FUNCTION altlast_version1._update_vflgeo_geometry() RETURNS trigger
    LANGUAGE plpgsql
    AS $$DECLARE
  asql VARCHAR;
  rec RECORD;
  rec2 RECORD;
  doContinue BOOLEAN;
BEGIN

IF (TG_OP = 'UPDATE') THEN

doContinue := (TG_OP = 'UPDATE' AND (NEW.wkb_geometry <> OLD.wkb_geometry)) OR (TG_OP = 'INSERT');

IF doContinue THEN

  SELECT INTO rec obje_id FROM altlast_version1.vflz v WHERE v.vflz_id=NEW.vflz_id;
  SELECT INTO rec2 X(ST_Centroid(NEW.wkb_geometry)) AS x, Y(ST_Centroid(NEW.wkb_geometry)) AS y;
  IF rec.obje_id IS NOT NULL THEN
    asql := 'UPDATE altlast_version1.obje SET x_koordinate='||rec2.x||', y_koordinate='||rec2.y;
    asql := asql || ' WHERE obje_id=' || rec.obje_id;
    EXECUTE asql; 
  END IF;
END IF;

END IF;

RETURN NEW;
END;$$;


