--
-- Name: bestscalefactor(public.geometry, double precision, double precision); Type: FUNCTION; Schema: altlast_version1; Owner: -
--

CREATE FUNCTION altlast_version1.bestscalefactor(geom public.geometry, targetwidth_cm double precision, targetheight_cm double precision) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  ex_height double precision; -- height of the geom in projected units
  ex_width double precision; -- width of the geom in projected units
  scalefactors integer[]; -- possible scale factors
  this_sf double precision; 
  w_relation double precision; -- width relation of geom and targetwidth_cm
  h_relation double precision; -- height relation of geom and targetheight_cm
  factor integer;
  s_ex double precision;
  t_cm double precision;
  i integer;
BEGIN
  SELECT altlast_version1.height(geom) INTO ex_height;
  SELECT altlast_version1.width(geom) INTO ex_width;
  scalefactors := '{100,250,500,1000,1500,2000,2500,5000,7500,10000,15000,20000,25000,50000,75000,100000}'::integer[];
  factor := Null;

  w_relation := ex_width/(targetwidth_cm*100.0);
  h_relation := ex_height/(targetheight_cm*100.0);

  IF w_relation>h_relation THEN --scale by width
    s_ex := ex_width;
    t_cm := targetwidth_cm;
  ELSE --scale by height
    s_ex := ex_height;
    t_cm := targetheight_cm;
  END IF;

  FOR i IN SELECT generate_series(array_lower(scalefactors,1),array_upper(scalefactors,1)) LOOP
    this_sf := scalefactors[i]::double precision;
    --IF ((s_ex/(this_sf/1000.0))/(t_cm*100.0))<=1.0 THEN
    
    
    IF ((this_sf*(t_cm/100.0))/s_ex)>1.0  THEN
      IF i=1 THEN
        factor := scalefactors[1]::integer;
      ELSE
        factor := scalefactors[i]::integer;
      END IF;
      EXIT;
    END IF;
  
  END LOOP;

  RETURN factor;
END
$$;


--
-- Name: FUNCTION bestscalefactor(geom public.geometry, targetwidth_cm double precision, targetheight_cm double precision); Type: COMMENT; Schema: altlast_version1; Owner: -
--

COMMENT ON FUNCTION altlast_version1.bestscalefactor(geom public.geometry, targetwidth_cm double precision, targetheight_cm double precision) IS 'Calculate the best scalefactor to display a geometry in a rectangle of targetwidth_cm*targetheight_cm centimeters';


