--

CREATE FUNCTION altlast_version1.byta_prefix(pc_cli_id integer, pcode character varying) RETURNS character varying
    LANGUAGE sql
    AS $_$
    SELECT filename FROM ( 
  SELECT filename::character varying, 0::integer AS sortk FROM altlast_version1.byta_cod WHERE c_cli_id=$1 and code=$2
