--
-- Name: byta_rename(bigint); Type: FUNCTION; Schema: altlast_version1; Owner: -
--

CREATE FUNCTION altlast_version1.byta_rename(pbytaid bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
    UPDATE altlast_version1.byta SET bezeichnung=foo.bez FROM 
        (SELECT altlast_version1.byta_prefix(2002,gs.c_gs_typ) || 
                '_' || 
                v.vflz_combined_id_kt ||
                regexp_replace( regexp_replace( (SELECT altlast_version1.textcat_all('_'|| s.name) 
                    FROM altlast_version1.gss_subj gsj 
                    JOIN altlast_version1.subj s on (gsj.subj_id=s.subj_id)
                    WHERE gsj.gss_id=gss.gss_id), '[^a-zA-Z0-9üÜöÖäÄß_]', '-','g'),'([-]+)', '-','g') || 
                '_' || 
                to_char(gss.start_datum_ist,'YYYYMMDD') || '.' || byta.dateisuffix AS bez
            FROM altlast_version1.gs gs 
            JOIN altlast_version1.gss gss on (gs.gs_id=gss.gs_id)
            JOIN altlast_version1.gs_obje go on (go.gs_id=gs.gs_id)
            JOIN altlast_version1.obje o on (go.obje_id=o.obje_id)
            JOIN altlast_version1.vflz_current_v v on (v.obje_id=o.obje_id)
            JOIN altlast_version1.byta_gss bg on (bg.gss_id=gss.gss_id)
            JOIN altlast_version1.byta byta on (byta.byta_id=bg.byta_id)
            WHERE byta.byta_id=pbytaid
            GROUP BY gs.c_gs_typ,v.vflz_combined_id_kt,gss.start_datum_ist,gss.gss_id,byta.dateisuffix) foo 
        WHERE byta_id=pbytaid;
        
END;$$;


