--

COMMENT ON FUNCTION altlast_version1.byta_rename(pbytaid bigint) IS 'Gibt einem Dokument einen Dateinamen entsprechend der in Bug 1177 beschriebenen Syntax';


--
-- Name: collect_subj(integer, boolean); Type: FUNCTION; Schema: altlast_version1; Owner: -
--

CREATE FUNCTION altlast_version1.collect_subj(gsi integer, isgs boolean) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
  rec record;
  res text;
  asql text;
BEGIN

  res := '';

  
  IF isgs THEN
    asql := 'SELECT altlast_version1.remove_linebreaks(COALESCE(s.name||'' '',''''))||altlast.remove_linebreaks(COALESCE(s.vorname||'' '',''''))||altlast.remove_linebreaks(COALESCE(s.taetigkeit||'' '','''')) AS subjs FROM altlast_version1.gs_subj gs JOIN altlast_version1.subj s ON gs.subj_id=s.subj_id WHERE gs.gs_id='||gsi::text||';';
  ELSE
    asql := 'SELECT altlast_version1.remove_linebreaks(COALESCE(s.name||'' '',''''))||altlast.remove_linebreaks(COALESCE(s.vorname||'' '',''''))||altlast.remove_linebreaks(COALESCE(s.taetigkeit||'' '','''')) AS subjs FROM altlast_version1.gss_subj gs JOIN altlast_version1.subj s ON gs.subj_id=s.subj_id WHERE gs.gss_id='||gsi::text||';';
  END IF;
  
  FOR rec IN EXECUTE asql LOOP
    res := res || regexp_replace(rec.subjs, E'[-_\\/]', ' ','gi');
  END LOOP;
  
  RETURN res;

END;$$;


--
-- Name: FUNCTION collect_subj(gsi integer, isgs boolean); Type: COMMENT; Schema: altlast_version1; Owner: -
--

COMMENT ON FUNCTION altlast_version1.collect_subj(gsi integer, isgs boolean) IS 'Gibt alle Beteiligte eines GS oder GSS als String zuruck';


--
-- Name: commacat(text, text); Type: FUNCTION; Schema: altlast_version1; Owner: -
--

CREATE FUNCTION altlast_version1.commacat(acc text, instr text) RETURNS text
    LANGUAGE plpgsql
    AS $$
  BEGIN
    IF acc IS NULL OR acc = '' THEN
      RETURN instr;
    ELSE
      RETURN acc || ', ' || instr;
    END IF;
  END;
$$;


--
-- Name: concat_subj(text, text, text); Type: FUNCTION; Schema: altlast_version1; Owner: -
--

CREATE FUNCTION altlast_version1.concat_subj(name text, vorname text, taetigkeit text) RETURNS text
    LANGUAGE plpgsql COST 10
    AS $$
  DECLARE
    res text;
  BEGIN
    res := altlast_version1.remove_linebreaks(COALESCE(name||' ',''))||altlast.remove_linebreaks(COALESCE(vorname||' ',''));

  IF res<>'' AND taetigkeit<>'' AND taetigkeit IS NOT NULL THEN 
    res := res || ', ';
  END IF;
    
  res:=res||altlast.remove_linebreaks(COALESCE(taetigkeit,''));    
    RETURN res;
  END;
$$;


--
-- Name: FUNCTION concat_subj(name text, vorname text, taetigkeit text); Type: COMMENT; Schema: altlast_version1; Owner: -
--

COMMENT ON FUNCTION altlast_version1.concat_subj(name text, vorname text, taetigkeit text) IS 'Setzt Name, Vorname und Taetigkeit zu einem String zusammen. Beim Aufruf NULL-Werte ggf. als text parsen, z.B. altlast_version1.concat_subj(''heinze'',NULL::text,''eine taetigkeit'').';


--
-- Name: create_altlusr(text, text); Type: FUNCTION; Schema: altlast_version1; Owner: -
--

CREATE FUNCTION altlast_version1.create_altlusr(username text, password text) RETURNS void
    LANGUAGE plpgsql
    AS $$
    DECLARE
        sql text;
        username_l text;
    BEGIN
        SELECT username INTO username_l;

        -- postgres kennt nur kleingeschriebene rollen
        sql := 'CREATE ROLE "' || lower(username_l) || '" NOSUPERUSER INHERIT LOGIN PASSWORD ''' || password || ''';';
        EXECUTE sql;

        sql := 'GRANT altlast TO "' || lower(username_l) || '";';
        EXECUTE sql;

        sql := 'INSERT INTO altlast_version1.subj (name,vorname,erfassungs_datum,erfasser_kuerzel,mutations_datum,mutierer_kuerzel) VALUES (''' || username || ''',''' || username || ''',now(),current_user,now(),current_user);';
        EXECUTE sql;

        sql := 'INSERT INTO altlast_version1.ben (subj_id,log_kuerzel,passwort,erfassungs_datum,erfasser_kuerzel,mutations_datum,mutierer_kuerzel) SELECT subj_id, lower(''' || username_l || '''),''' || password || ''', now(),current_user,now(),current_user FROM altlast_version1.subj WHERE name = ''' || username || ''' LIMIT 1;';
        EXECUTE sql;

        sql := 'INSERT INTO altlast_version1.ben_grp (subj_id,grp_kuerzel,erfassungs_datum,erfasser_kuerzel,mutations_datum,mutierer_kuerzel) SELECT subj_id, ''ALTLAST'', now(),current_user,now(),current_user FROM altlast_version1.subj WHERE name = ''' || username || ''' LIMIT 1;';
        EXECUTE sql;


    END;
$$;


--
-- Name: FUNCTION create_altlusr(username text, password text); Type: COMMENT; Schema: altlast_version1; Owner: -
--

COMMENT ON FUNCTION altlast_version1.create_altlusr(username text, password text) IS 'Deprecated, use altlast_version1.create_altlusr(text, text, text, text): Legt einen Benutzer für Altlast4PC und in der Datenbank an. Aufruf mit 
SELECT altlast_version1.create_altlusr([Benutzername],[Passwort]);';


--
-- Name: create_altlusr(text, text, text, text); Type: FUNCTION; Schema: altlast_version1; Owner: -
--

CREATE FUNCTION altlast_version1.create_altlusr(name text, vorname text, username text, password text) RETURNS void
    LANGUAGE plpgsql
    AS $$
    DECLARE
        sql text;
        username_l text;
        rec Record;
    BEGIN

        SELECT username INTO username_l;

        FOR rec IN SELECT COUNT(*),MIN(subj_id) AS subj_id  FROM altlast_version1.ben WHERE log_kuerzel=username LOOP

          IF rec.subj_id IS NOT NULL THEN

                sql := 'UPDATE altlast_version1.ben SET passwort=''' || password || ''', mutations_datum=now(),mutierer_kuerzel=current_user WHERE subj_id = ' || rec.subj_id || ';';
                EXECUTE sql;

          ELSE
                 -- postgres kennt nur kleingeschriebene rollen
                sql := 'CREATE ROLE ' || lower(username_l) || ' NOSUPERUSER INHERIT LOGIN PASSWORD ''' || password || ''';';
                EXECUTE sql;

                sql := 'GRANT altlast TO ' || lower(username_l) || ';';
                EXECUTE sql;

                sql := 'INSERT INTO altlast_version1.subj (name,vorname,erfassungs_datum,erfasser_kuerzel,mutations_datum,mutierer_kuerzel) VALUES (''' || username || ''',''' || username || ''',now(),current_user,now(),current_user);';
                EXECUTE sql;

                sql := 'INSERT INTO altlast_version1.ben (subj_id,log_kuerzel,passwort,erfassungs_datum,erfasser_kuerzel,mutations_datum,mutierer_kuerzel) SELECT subj_id, ''' || username_l || ''',''' || password || ''', now(),current_user,now(),current_user FROM altlast_version1.subj WHERE name = ''' || username || ''' LIMIT 1;';
                EXECUTE sql;

                sql := 'INSERT INTO altlast_version1.ben_grp (subj_id,grp_kuerzel,erfassungs_datum,erfasser_kuerzel,mutations_datum,mutierer_kuerzel) SELECT subj_id, ''ALTLAST'', now(),current_user,now(),current_user FROM altlast_version1.subj WHERE name = ''' || username || ''' LIMIT 1;';
                EXECUTE sql;

          END IF;

        END LOOP;



    END;
$$;


--
-- Name: FUNCTION create_altlusr(name text, vorname text, username text, password text); Type: COMMENT; Schema: altlast_version1; Owner: -
--

COMMENT ON FUNCTION altlast_version1.create_altlusr(name text, vorname text, username text, password text) IS 'Legt einen Benutzer für Altlast4PC und in der Datenbank an. Aufruf mit 
SELECT altlast_version1.create_altlusr([Name],[Vorname],[Benutzername],[Passwort]);';


--
-- Name: create_gss_from_report(bigint, bigint, bytea, text); Type: FUNCTION; Schema: altlast_version1; Owner: -
--

CREATE FUNCTION altlast_version1.create_gss_from_report(pgs_id bigint, preport_id bigint, pdata bytea, pmimetype text) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
DECLARE
    agss_typ character varying(8);
    agss_id bigint;
BEGIN
    -- teilgeschaefttyp feststellen - bishe rnur hartkodiert
    agss_typ:=null;
    IF preport_id in (1,13) THEN
        agss_typ:='103';
    END IF;
    
    -- kein teilgeschaftstyp gefunden -> exception
    IF agss_typ IS NULL THEN
        RAISE EXCEPTION 'SHOWMSG Dem Report kann kein Teilgeschäftstyp zugeordnet werden.';
    END IF;
    
    -- teilgeschaeft anlegen
    INSERT INTO altlast_version1.gss (gs_id,c_gss_typ) VALUES (pgs_id,agss_typ) RETURNING gss_id INTO agss_id;
    IF agss_id IS NULL THEN
        RAISE EXCEPTION 'SHOWMSG Fehler beim Anlegen des Teilgeschäftes';
    END IF;

    -- report anhaengen
    SELECT altlast_version1.gss_append_report(pgs_id,agss_id,preport_id,pdata, pmimetype) INTO agss_id;
    
    RETURN agss_id;
END;$$;


--
-- Name: create_gss_from_report(bigint, bigint, bytea, date, text); Type: FUNCTION; Schema: altlast_version1; Owner: -
--

CREATE FUNCTION altlast_version1.create_gss_from_report(pgs_id bigint, preport_id bigint, pdata bytea, startdatum date, pmimetype text) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
DECLARE
    agss_typ character varying(8);
    agss_id bigint;
BEGIN
    -- teilgeschaefttyp feststellen - bishe rnur hartkodiert
    agss_typ:=null;
    IF preport_id in (1,13) THEN
        agss_typ:='103';
    END IF;
    
    -- kein teilgeschaftstyp gefunden -> exception
    IF agss_typ IS NULL THEN
        RAISE EXCEPTION 'SHOWMSG Dem Report kann kein Teilgeschäftstyp zugeordnet werden.';
    END IF;
    
    -- teilgeschaeft anlegen
    INSERT INTO altlast_version1.gss (gs_id,c_gss_typ, start_datum_ist) VALUES (pgs_id,agss_typ, startdatum) RETURNING gss_id INTO agss_id;
    IF agss_id IS NULL THEN
        RAISE EXCEPTION 'SHOWMSG Fehler beim Anlegen des Teilgeschäftes';
    END IF;

    -- report anhaengen
    SELECT altlast_version1.gss_append_report(pgs_id,agss_id,preport_id,pdata, pmimetype) INTO agss_id;
    
    RETURN agss_id;
END;$$;


--
-- Name: db_fill_h_fields(); Type: FUNCTION; Schema: altlast_version1; Owner: -
--

CREATE FUNCTION altlast_version1.db_fill_h_fields() RETURNS void
    LANGUAGE plpgsql
    AS $$ 
DECLARE
  rec RECORD;
  sql character varying;
BEGIN 

 
 FOR rec in SELECT t2s.table_name,t2s.col 
   FROM 
   (SELECT table_name, col, count(*) as n FROM (Select table_name, substring(column_name,E'[c|h]\\_(.*)') AS col 
    from information_schema.columns 
    WHERE table_schema='altlast' 
    AND column_name SIMILAR TO E'(c|h)\\_%' 
    AND table_name NOT IN 
      (SELECT table_name FROM information_schema.views WHERE table_schema='altlast')
    ) AS foo GROUP BY table_name,col) AS t2s WHERE t2s.n=2 LOOP
    
  sql := 'UPDATE altlast_version1.'|| rec.table_name || ' SET h_'|| rec.col || '=DEFAULT WHERE h_'|| rec.col || ' IS NULL';
   EXECUTE sql;   
    
 END LOOP;
    
-- SELECT * FROM fk_violations;

    
END;
$$;


--
-- Name: db_fk_violations(); Type: FUNCTION; Schema: altlast_version1; Owner: -
--

CREATE FUNCTION altlast_version1.db_fk_violations() RETURNS void
    LANGUAGE plpgsql
    AS $$ 
DECLARE
  rec RECORD;
  sql character varying;
BEGIN 

sql := 'CREATE TEMPORARY TABLE fk_violations (table_name varchar,col_name varchar, c_cli_id int2,code varchar);';
EXECUTE sql;
 
 FOR rec in SELECT t2s.table_name,t2s.col 
   FROM 
   (SELECT table_name, col, count(*) as n FROM (Select table_name, substring(column_name,E'[c|h]\\_(.*)') AS col 
    from information_schema.columns 
    WHERE table_schema='altlast' 
    AND column_name SIMILAR TO E'(c|h)\\_%' 
    AND table_name NOT IN 
      (SELECT table_name FROM information_schema.views WHERE table_schema='altlast')
    ) AS foo GROUP BY table_name,col) AS t2s WHERE t2s.n=2 LOOP
    
   sql := 'INSERT INTO fk_violations SELECT '''|| rec.table_name || '''::text,'''|| rec.col || '''::text, h_' || rec.col || '::int2, c_' || rec.col || '::text FROM altlast_version1.' || rec.table_name || ' t WHERE c_' || rec.col || ' IS NOT NULL EXCEPT SELECT ''' || rec.table_name || '''::text,''' || rec.col || '''::text,c_cli_id::int2,code::text FROM altlast_version1.cod';
   EXECUTE sql;   
    
 END LOOP;
    
-- SELECT * FROM db_fk_violations;

    
END;
$$;


