--
-- Name: default_gs_gss_c_gs_status(text); Type: FUNCTION; Schema: altlast_version1; Owner: -
--

CREATE FUNCTION altlast_version1.default_gs_gss_c_gs_status(end_datum_ist text) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Durch die Sachbearbeiter wird das Abschlussdatum eingefuegt > der Status wird automatisch auf "abgeschlossen" geaendert.
    IF end_datum_ist IS NULL THEN
        RETURN '20';
    elseif end_datum_ist = '' then
  return '20';
    ELSE
        RETURN '50';
    END IF;
END;$$;


