--

CREATE FUNCTION altlast_version1.default_gs_gss_end_datum_ist(c_status character varying) RETURNS date
    LANGUAGE plpgsql
    AS $$
DECLARE
    rslt date;
BEGIN
    IF c_status='50' THEN
        SELECT now()::date INTO rslt;
    ELSE
        rslt:=null::date;
    END IF;
    RETURN rslt;
END;
$$;


