--
-- Name: default_gs_gss_end_datum_planung(date, character varying); Type: FUNCTION; Schema: altlast_version1; Owner: -
--

CREATE FUNCTION altlast_version1.default_gs_gss_end_datum_planung(start_datum_planung date, c_gs_typ character varying) RETURNS date
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF c_gs_typ='5' THEN -- 'Information Inhaber: definitiver Katastereintrag' 
        RETURN (start_datum_planung +interval '37 days')::date ;
    ELSEIF c_gs_typ='6' THEN --  'Bereinigung mit Inhaber: Feststellungsverfügung' 
        RETURN (start_datum_planung +interval '10 days')::date ;
    ELSE
        --RETURN (start_datum_planung +interval '30 days')::date ;
        RETURN NULL::date ; -- bug 1047
    END IF;
END;$$;


