--

COMMENT ON FUNCTION altlast_version1.default_gs_gss_start_datum_planung(start_datum_ist date) IS 'Defaultwert für gs.start_datum_planung und gss.start_datum_planung, Argumente: [gs|gss].start_datum_ist';


--
-- Name: default_gs_gss_start_datum_planung_german(date); Type: FUNCTION; Schema: altlast_version1; Owner: -
--

CREATE FUNCTION altlast_version1.default_gs_gss_start_datum_planung_german(start_datum_ist date) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN to_char(altlast.default_gs_gss_start_datum_planung(start_datum_ist), 'DD.MM.YYYY');
END;$$;


--
-- Name: FUNCTION default_gs_gss_start_datum_planung_german(start_datum_ist date); Type: COMMENT; Schema: altlast_version1; Owner: -
--

COMMENT ON FUNCTION altlast_version1.default_gs_gss_start_datum_planung_german(start_datum_ist date) IS 'Defaultwert für gs.start_datum_planung und gss.start_datum_planung, Rückgabe als charcter varying in deutscher Formatierung, Argumente: [gs|gss].start_datum_ist';


--
-- Name: default_gs_gss_start_datum_planung_german(character varying); Type: FUNCTION; Schema: altlast_version1; Owner: -
--

CREATE FUNCTION altlast_version1.default_gs_gss_start_datum_planung_german(start_datum_ist character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
     tget date;
BEGIN
    BEGIN
        tget:=start_datum_ist::date;
    EXCEPTION WHEN invalid_datetime_format THEN
        tget:=null::date;
    END;
    RETURN altlast_version1.default_gs_gss_start_datum_planung_german(tget);
END;$$;


--
-- Name: FUNCTION default_gs_gss_start_datum_planung_german(start_datum_ist character varying); Type: COMMENT; Schema: altlast_version1; Owner: -
--

COMMENT ON FUNCTION altlast_version1.default_gs_gss_start_datum_planung_german(start_datum_ist character varying) IS 'Defaultwert für gs.start_datum_planung und gss.start_datum_planung, Rückgabe als charcter varying in deutscher Formatierung, Argumente: [gs|gss].start_datum_ist, Aliasfunktion um Zend-defizit bzgl Nullwerten und leetstrings auszugleichen';


--
-- Name: default_gss_gss_titel(character varying, bigint); Type: FUNCTION; Schema: altlast_version1; Owner: -
--

CREATE FUNCTION altlast_version1.default_gss_gss_titel(c_gss_typ_f character varying, gs_id_f bigint) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
    t text;
BEGIN
    SELECT  gs.gs_titel || ' : ' || cod.bezeichnung INTO t FROM altlast_version1.cod cod, altlast_version1.gs gs WHERE cod.c_cli_id=2003 AND cod.code=c_gss_typ_f::character varying AND gs.gs_id=gs_id_f;
    RETURN t;
END;$$;


--
-- Name: FUNCTION default_gss_gss_titel(c_gss_typ_f character varying, gs_id_f bigint); Type: COMMENT; Schema: altlast_version1; Owner: -
--

COMMENT ON FUNCTION altlast_version1.default_gss_gss_titel(c_gss_typ_f character varying, gs_id_f bigint) IS 'Defaultwert für gss.gss_titel, Argumente: gss.c_gss_typ, gss.gss_id';


--
-- Name: due_gs(boolean, text, date, date, date, date); Type: FUNCTION; Schema: altlast_version1; Owner: -
--

CREATE FUNCTION altlast_version1.due_gs(isgs boolean, c_gs_status text, start_datum_planung date, end_datum_planung date, start_datum_ist date, end_datum_ist date) RETURNS smallint
    LANGUAGE plpgsql
    AS $$
  DECLARE
    res text;
  BEGIN

    --erledigt, abgebrochen
    IF c_gs_status IS NULL THEN
      RETURN NULL;      
    END IF; 
  
    --erledigt, abgebrochen
    IF c_gs_status='50' OR c_gs_status='51' THEN
      RETURN 0;      
    END IF; 
    
    --sistiert, Versand zurueckstellen
    IF c_gs_status='30' OR c_gs_status='52' THEN
      RETURN 1;
    END IF;    
    
    --in Planung, in Bearbeitung
    IF c_gs_status='20' OR c_gs_status='10' THEN

      IF end_datum_planung<=now() OR (start_datum_ist IS NULL AND start_datum_planung <= now()) THEN
        RETURN 2;
      ELSEIF end_datum_planung IS NULL THEN
        RETURN 1;
      ELSEIF end_datum_planung < now() AND (start_datum_planung IS NULL OR start_datum_ist IS NOT NULL) THEN
        RETURN 1;              
      END IF;
      
    END IF;

    RETURN 2;
  
END;$$;


--
-- Name: fix_bewe_valid_historize(integer); Type: FUNCTION; Schema: altlast_version1; Owner: -
--

CREATE FUNCTION altlast_version1.fix_bewe_valid_historize(objeid integer) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    rec2 RECORD;
    rec RECORD;
    vflzid INTEGER;
BEGIN
    /*
    SELECT altlast_hist.snapshot(1,vflz_id,'Initial clone') FROM altlast_version1.vflz_current_v OFFSET 50;
    SELECT altlast_version1.fix_bewe_valid_historize(39);
    SELECT * FROM hist.snapshot WHERE key_value=39 or parent_key_value=39;

    xxxALTER TABLE altlast_version1.vflz DISABLE TRIGGER ALL;
    xxxDELETE FROM altlast_version1.vflz where vflz_id=2000380;
    xxxALTER TABLE altlast_version1.vflz ENABLE TRIGGER ALL;
    xxDELETE FROM hist.snapshot WHERE parent_key_value=39;
    xxUPDATE hist.snapshot SET is_current=TRUE WHERE key_value=39;

    SELECT v.obje_id,v.vflz_id,b.c_bere_res_abwbewe,v.mutations_datum,c.vflz_id FROM altlast_version1.bere b LEFT JOIN altlast_version1.vflz v USING(vflz_id) LEFT JOIN altlast_version1.vflz_current_v c USING(vflz_id) WHERE v.obje_id=39;

    SELECT altlast_version1.get_bewe_valid(obje_id) FROM (SELECT DISTINCT obje_id FROM altlast_version1.gs_obje LIMIT 10) x;
    SELECT hist.snapshot(1,39,'Initiale Historisierung aller Standorte - Standort ohne rechtswirksames Geschaeft.')
    */

    SELECT g.c_gs_typ, g.c_gs_status, g.end_datum_ist 
    FROM altlast_version1.obje o 
    JOIN altlast_version1.gs_obje go USING(obje_id) 
    JOIN altlast_version1.gs g USING (gs_id)
    WHERE o.obje_id=objeid
    AND g.c_gs_status = '50' --Gesch�ft abgeschlossen
    AND g.c_gs_typ IN ('5','88','7') -- def. Eintrag, �nderung Bewertung, Nichteintrag
    AND end_datum_ist IS NOT NULL 
    ORDER BY end_datum_ist DESC
    INTO rec;

    IF rec IS NULL THEN
        --Standort ohne rechtswirksames Geschaeft

        SELECT vflz_id FROM altlast_version1.vflz_current_v WHERE obje_id=objeid INTO vflzid;
        ALTER TABLE altlast_version1.vflz DISABLE TRIGGER _check_vflz_bearbstand;
        RAISE NOTICE 'Standort ohne rechtswirksames Geschaeft: archiving vflz_id %',vflzid;
        PERFORM hist.snapshot(1,vflzid,'Initiale Historisierung - Standort ohne rechtswirksames Geschaeft.');
        ALTER TABLE altlast_version1.vflz ENABLE TRIGGER _check_vflz_bearbstand;
    ELSE
        --Standort mit rechtswirksamem Geschaeft
        SELECT b.c_bere_res_abwbewe, v.vflz_id         
        FROM altlast_version1.bere b 
        JOIN altlast_version1.vflz v USING (vflz_id)
        JOIN hist.snapshot h ON b.vflz_id=h.key_value AND h.history_id=1
        WHERE obje_id=objeid AND h.created<=rec.end_datum_ist 
        ORDER BY h.created DESC
        INTO rec2;

        IF rec2 IS NOT NULL THEN
            --Historisierter Stand <= rechtwirksames Geschaeft vorhanden
            ALTER TABLE altlast_version1.vflz DISABLE TRIGGER _check_vflz_bearbstand;
            RAISE NOTICE 'Historisierter Stand <= rechtwirksames Geschaeft vorhanden: archiving vflz_id %',rec2.vflz_id;
            PERFORM hist.snapshot(1,rec2.vflz_id,'Initiale Historisierung - rechtsgueltiger Stand vorhanden, wird geklont');
            ALTER TABLE altlast_version1.vflz ENABLE TRIGGER _check_vflz_bearbstand; 
        ELSE
            --Historisierter Stand <= rechtwirksames Geschaeft fehlt
            ALTER TABLE altlast_version1.vflz DISABLE TRIGGER _check_vflz_bearbstand;
            SELECT vflz_id FROM altlast_version1.vflz_current_v WHERE obje_id=objeid INTO vflzid;
            RAISE NOTICE 'Historisierter Stand <= rechtwirksames Geschaeft fehlt: archiving vflz_id %',vflzid;
            PERFORM hist.snapshot(1,vflzid,'Initiale Historisierung auf das Datum des letzten rechtwirksamen Geschaefts');
            ALTER TABLE altlast_version1.vflz ENABLE TRIGGER _check_vflz_bearbstand;   
            --Historisierte Version auf Datum des rechtswirksamen Geschaefts setzen     
            UPDATE hist.snapshot SET created=rec.end_datum_ist WHERE history_id=1 AND key_value=objeid;
        END IF;

    END IF;


END
$$;


--
-- Name: FUNCTION fix_bewe_valid_historize(objeid integer); Type: COMMENT; Schema: altlast_version1; Owner: -
--

COMMENT ON FUNCTION altlast_version1.fix_bewe_valid_historize(objeid integer) IS 'Prueft, ob fuer das letzte abgeschlossene Geschaeft eine historisierte Version vorhanden ist. Historisiert ansonsten einmalig und setzt das Historisierungsdatum auf das Datum des Geschaefts. Diese Funktion ist nur zur EINMALIGEN Anwendung bei Einfuehren der Historisierung und nur bei SOLGEO gedacht.';


--
-- Name: fts_collect_obje(); Type: FUNCTION; Schema: altlast_version1; Owner: -
--

CREATE FUNCTION altlast_version1.fts_collect_obje() RETURNS void
    LANGUAGE plpgsql
    AS $$

  BEGIN
  TRUNCATE altlast_version1.fts_obje;

  INSERT INTO altlast_version1.fts_obje (vflz_id,obje_id,sto_kennung,content_ts,fieldcontent,fieldvector,fieldname) SELECT 
    vflz_id,
    obje_id,
    sto_kennung,
    to_tsvector('german',"Bemerkungen Standort"||' '||"Standort"||' '||"Bemerkungen Ablagerung"||' '||"Stoffklasse"||' '||"Stoffgruppe Ablagerung"||' '||"Bemerkungen Betrieb"||' '||"Bemerkungen Unfall"||' '||"Unfall"||' '||"Befragte Personen"||' '||"Bewertung"||' '||"Dokumentation"||' '||"Emissionen"||' '||"Fremdwasser"||' '||"Geologie"||' '||"Geschäft"||' '||"Teilgeschäft"||' '||"GW-Messstelle"||' '||"Grundwasser"||' '||"Grundwasservork"||' '||"Bemerkungen künstl. Umfeld"||' '||"Nutzung Boden"||' '||"Bemerkungen nat. Umfeld"||' '||"Bemerkungen Nutzung Boden"||' '||"Bemerkungen Nutzung Wasser"||' '||"Nutzung OGW"||' '||"Ereignis"||' '||"Ereignis natürlich"||' '||"Sonst. Vorkommnisse"||' '||"Schäden"||' '||"Pot. Gasemissionen"||' '||"Zusatzakten"||' '||"Nat. Umfeld"||' '||"Exfiltration") as content_ts,
    ARRAY[quote_literal("Bemerkungen Standort"),quote_literal("Standort"), quote_literal("Bemerkungen Ablagerung"), quote_literal("Stoffklasse"), quote_literal("Stoffgruppe Ablagerung"), quote_literal("Bemerkungen Betrieb"), quote_literal("Bemerkungen Unfall"), quote_literal("Unfall"), quote_literal("Befragte Personen"), quote_literal("Bewertung"), quote_literal("Dokumentation"), quote_literal("Emissionen"), quote_literal("Fremdwasser"), quote_literal("Geologie"), quote_literal("Geschäft"), quote_literal("Teilgeschäft"), quote_literal("GW-Messstelle"), quote_literal("Grundwasser"), quote_literal("Grundwasservork"), quote_literal("Bemerkungen künstl. Umfeld"), quote_literal("Nutzung Boden"), quote_literal("Bemerkungen nat. Umfeld"), quote_literal("Bemerkungen Nutzung Boden"), quote_literal("Bemerkungen Nutzung Wasser"), quote_literal("Nutzung OGW"), quote_literal("Ereignis"), quote_literal("Ereignis natürlich"), quote_literal("Sonst. Vorkommnisse"), quote_literal("Schäden"), quote_literal("Pot. Gasemissionen"), quote_literal("Zusatzakten"), quote_literal("Nat. Umfeld"), quote_literal("Exfiltration")] AS fieldcontent,
    ARRAY[to_tsvector('german',"Bemerkungen Standort"), to_tsvector('german',"Standort"), to_tsvector('german',"Bemerkungen Ablagerung"), to_tsvector('german',"Stoffklasse"), to_tsvector('german',"Stoffgruppe Ablagerung"), to_tsvector('german',"Bemerkungen Betrieb"), to_tsvector('german',"Bemerkungen Unfall"),to_tsvector('german',"Unfall"), to_tsvector('german',"Befragte Personen"), to_tsvector('german',"Bewertung"), to_tsvector('german',"Dokumentation"), to_tsvector('german',"Emissionen"), to_tsvector('german',"Fremdwasser"), to_tsvector('german',"Geologie"), to_tsvector('german',"Geschäft"), to_tsvector('german',"Teilgeschäft"), to_tsvector('german',"GW-Messstelle"), to_tsvector('german',"Grundwasser"), to_tsvector('german',"Grundwasservork"), to_tsvector('german',"Bemerkungen künstl. Umfeld"), to_tsvector('german',"Nutzung Boden"), to_tsvector('german',"Bemerkungen nat. Umfeld"), to_tsvector('german',"Bemerkungen Nutzung Boden"), to_tsvector('german',"Bemerkungen Nutzung Wasser"), to_tsvector('german',"Nutzung OGW"), to_tsvector('german',"Ereignis"), to_tsvector('german',"Ereignis natürlich"), to_tsvector('german',"Sonst. Vorkommnisse"), to_tsvector('german',"Schäden"), to_tsvector('german',"Pot. Gasemissionen"), to_tsvector('german',"Zusatzakten"), to_tsvector('german',"Nat. Umfeld"), to_tsvector('german',"Exfiltration")] AS fieldvector,
    ARRAY['Bemerkungen Standort','Standort','Bemerkungen Ablagerung','Stoffklasse','Stoffgruppe Ablagerung', 'Bemerkungen Betrieb', 'Bemerkungen Unfall','Unfall','Befragte Personen','Bewertung','Dokumentation','Emissionen','Fremdwasser','Geologie','Geschäft','Teilgeschäft','GW-Messstelle','Grundwasser','Grundwasservork','Bemerkungen künstl. Umfeld','Nutzung Boden','Bemerkungen nat. Umfeld','Bemerkungen Nutzung Boden','Bemerkungen Nutzung Wasser','Nutzung OGW','Ereignis','Ereignis natürlich','Sonst. Vorkommnisse','Schäden','Pot. Gasemissionen','Zusatzakten','Nat. Umfeld','Exfiltration'] AS fieldname


    FROM ( SELECT v.vflz_id, o.obje_id , sto_kennung, 
        COALESCE(v.bemerkungen,'') as "Bemerkungen Standort",
        COALESCE(sto_kennung,'') as "Standort",
        COALESCE(ia.inta_ergaenzung,'') AS "Bemerkungen Ablagerung",
        COALESCE((SELECT cod.bezeichnung FROM altlast_version1.cod WHERE k.c_kksk_stoffkl::text = cod.code::text AND cod.c_cli_id = 94),'')  AS "Stoffklasse",
        COALESCE((SELECT cod.bezeichnung FROM altlast_version1.cod WHERE kg.c_kksg_stoffgrp::text = cod.code::text AND cod.c_cli_id >= 110 AND cod.c_cli_id <= 114),'')  AS "Stoffgruppe Ablagerung",
        COALESCE(ib.intb_ergaenzung,'') AS "Bemerkungen Betrieb", 
        COALESCE(iu.intu_ergaenzung,'') AS "Bemerkungen Unfall",
        COALESCE((SELECT cod.bezeichnung FROM altlast_version1.cod WHERE k.c_kksk_stoffkl::text = cod.code::text AND cod.c_cli_id = 117),'') AS "Unfall",
        COALESCE(bf.befr_aussage,'')||' '||COALESCE(bf.befr_zusatzinfo,'') AS "Befragte Personen",
        COALESCE(be.bere_begr_abwbewe,'')||' '||COALESCE(be.bere_begr_abw_art32c,'') AS "Bewertung",
        COALESCE(dk.doku_titel,'')||' '||COALESCE(dk.doku_abstract,'') AS "Dokumentation",
        COALESCE(eg.emiss_ergpotemissionen,'') AS "Emissionen",
        COALESCE((SELECT cod.bezeichnung FROM altlast_version1.cod WHERE fw.c_frwa_fremdwasser::text = cod.code::text AND cod.c_cli_id = 6),'')  AS "Fremdwasser",
        COALESCE(ge.geol_geologie,'') AS "Geologie",
        COALESCE(gs.gs_titel,'') || ' ' || COALESCE(gs.bemerkungen,'') AS "Geschäft",
        COALESCE(gss.gss_titel,'')|| ' '||COALESCE(gss.bemerkungen,'') AS "Teilgeschäft",
        COALESCE(gw.gwms_bezeichnung,'')||' '||COALESCE(gw.gwms_gaso_nummer::text,'') AS "GW-Messstelle",
        COALESCE((SELECT cod.bezeichnung FROM altlast_version1.cod WHERE gu.c_gwnu_nutzung::text = cod.code::text AND cod.c_cli_id = 88),'')  AS "Grundwasser",
        COALESCE(gv.gwvk_name_gw,'') AS "Grundwasservork",
        COALESCE(kf.kumf_ergkunstumfeld,'') AS "Bemerkungen künstl. Umfeld",
        COALESCE((SELECT cod.bezeichnung FROM altlast_version1.cod WHERE nb.c_nubo_nutzungsart::text = cod.code::text AND cod.c_cli_id = 87),'')
        ||' akt. Nutzung '||  COALESCE((SELECT COALESCE(cod.bezeichnung,'unbekannt') FROM altlast_version1.cod WHERE nb.c_nubo_akt_nutzung::text = cod.code::text AND 
            CASE 
            WHEN nb.c_nubo_nutzungsart='01' THEN cod.c_cli_id = 83
            WHEN nb.c_nubo_nutzungsart='02' THEN cod.c_cli_id = 84
            WHEN nb.c_nubo_nutzungsart='03' THEN cod.c_cli_id = 85
            WHEN nb.c_nubo_nutzungsart='04' THEN cod.c_cli_id = 86    
            ELSE cod.c_cli_id<-9999 END
        ),'') AS "Nutzung Boden",
        COALESCE(nf.numf_ergnatumfeld,'') AS "Bemerkungen nat. Umfeld",
        COALESCE(nz.nutzb_ergnutzboden,'') AS "Bemerkungen Nutzung Boden",
        COALESCE(nw.nutzw_ergnutzwasser,'') AS "Bemerkungen Nutzung Wasser",
        COALESCE((SELECT cod.bezeichnung FROM altlast_version1.cod WHERE ogw.c_ogw_nutzung::text = cod.code::text AND cod.c_cli_id = 89),'')  AS "Nutzung OGW",
        COALESCE((SELECT cod.bezeichnung FROM altlast_version1.cod WHERE vk.c_veek_verdflaeche::text = cod.code::text AND cod.c_cli_id = 60),'') AS "Ereignis",
        COALESCE((SELECT cod.bezeichnung FROM altlast_version1.cod WHERE vn.c_veen_natuerlich::text = cod.code::text AND cod.c_cli_id = 61),'') AS "Ereignis natürlich",
        COALESCE(vs.vfsv_sonst_vorkomm,'') AS "Sonst. Vorkommnisse",
        COALESCE((SELECT cod.bezeichnung FROM altlast_version1.cod WHERE vu.c_vfus_art_schaden::text = cod.code::text AND cod.c_cli_id = 101),'')
        ||' '||  COALESCE((SELECT COALESCE(cod.bezeichnung,'unbekannt') FROM altlast_version1.cod WHERE vu.c_vfus_schaeden::text = cod.code::text AND 
            CASE 
            WHEN vu.c_vfus_art_schaden='02' THEN cod.c_cli_id = 102
            WHEN vu.c_vfus_art_schaden='03' THEN cod.c_cli_id = 102
            WHEN vu.c_vfus_art_schaden='04' THEN cod.c_cli_id = 100    
            WHEN vu.c_vfus_art_schaden='05' THEN cod.c_cli_id = 99
            ELSE cod.c_cli_id<-9999 END
        ),'') AS "Schäden",
        COALESCE((SELECT cod.bezeichnung FROM altlast_version1.cod WHERE gu.c_gwnu_nutzung::text = cod.code::text AND cod.c_cli_id = 91),'')  AS "Pot. Gasemissionen",
        COALESCE((SELECT cod.bezeichnung FROM altlast_version1.cod WHERE zs.c_zusa_art::text = cod.code::text AND cod.c_cli_id = 57),'')||' '||COALESCE(zs.zusa_angaben,'')  AS "Zusatzakten",
        COALESCE((SELECT cod.bezeichnung FROM altlast_version1.cod WHERE v.c_vflz_gws_bereich::text = cod.code::text AND cod.c_cli_id = 72),'') || COALESCE((SELECT cod.bezeichnung FROM altlast_version1.cod WHERE v.c_vflz_durchlaessigkeit::text = cod.code::text AND cod.c_cli_id = 58),'') || CASE WHEN v.c_vflz_ex_infiltration::text = '01' OR v.c_vflz_ex_infiltration::text = '03' THEN ' Exfiltration ' ELSE '' END  || CASE WHEN v.c_vflz_ex_infiltration::text = '01' OR v.c_vflz_ex_infiltration::text = '02' THEN ' Karstgebiet ' ELSE '' END AS "Nat. Umfeld",

        
        COALESCE((SELECT cod.bezeichnung FROM altlast_version1.cod WHERE v.c_vflz_ex_infiltration::text = cod.code::text AND cod.c_cli_id = 68),'')  AS "Exfiltration"
        
    FROM altlast_version1.vflz_current_v v
      JOIN altlast_version1.obje_kennung_v o ON o.obje_id = v.obje_id 
      JOIN altlast_version1.obje o2 on o2.obje_id = o.obje_id
      /*Ablagerungen*/
      LEFT JOIN altlast_version1.inta ia ON ia.vflz_id=v.vflz_id
      LEFT JOIN altlast_version1.kksk k ON k.vflz_id=v.vflz_id
      LEFT JOIN altlast_version1.kksg kg ON kg.kksk_id=k.kksk_id
      /*Betriebe*/  
      LEFT JOIN altlast_version1.intb ib ON ib.vflz_id=v.vflz_id
      LEFT JOIN altlast_version1.formba fa ON ib.intb_id=fa.intb_id AND fa.intb_formblatt=ib.intb_formblatt AND fa.antwort='J'
      LEFT JOIN altlast_version1.formbq fq ON fq.intb_formblatt=fa.intb_formblatt AND fq.fragenr=fa.fragenr
      /*Unfaelle*/
      LEFT JOIN altlast_version1.intu iu ON iu.vflz_id=v.vflz_id  
      LEFT JOIN altlast_version1.inum inu ON inu.intu_id=iu.intu_id     
      /*Sonstige Tabellen alphabetisch*/
      
      LEFT JOIN altlast_version1.befr bf ON bf.vflz_id=v.vflz_id
      LEFT JOIN altlast_version1.bere be ON be.vflz_id = v.vflz_id
      LEFT JOIN altlast_version1.doku dk ON dk.vflz_id=v.vflz_id
      LEFT JOIN altlast_version1.emiss eg ON eg.vflz_id=v.vflz_id
      LEFT JOIN altlast_version1.frwa fw ON fw.vflz_id=v.vflz_id
      LEFT JOIN altlast_version1.geol ge ON ge.vflz_id=v.vflz_id
      LEFT JOIN altlast_version1.gs_obje go ON go.obje_id=o.obje_id
      LEFT JOIN altlast_version1.gs gs ON gs.gs_id=go.gs_id
      LEFT JOIN altlast_version1.gss gss ON gss.gs_id=gs.gs_id
      LEFT JOIN altlast_version1.gwms gw ON gw.vflz_id=v.vflz_id
      LEFT JOIN altlast_version1.gwnu gu ON v.vflz_id=gu.vflz_id
      LEFT JOIN altlast_version1.gwvk gv ON gv.vflz_id=v.vflz_id
      LEFT JOIN altlast_version1.kumf kf ON kf.vflz_id=v.vflz_id
      LEFT JOIN altlast_version1.nubo nb ON nb.vflz_id=v.vflz_id
      LEFT JOIN altlast_version1.numf nf ON nf.vflz_id=v.vflz_id
      LEFT JOIN altlast_version1.nutzb nz ON nz.vflz_id=v.vflz_id
      LEFT JOIN altlast_version1.nutzw nw ON nw.vflz_id=v.vflz_id
      LEFT JOIN altlast_version1.ogw ogw ON ogw.vflz_id=v.vflz_id
      LEFT JOIN altlast_version1.veek vk ON vk.vflz_id=v.vflz_id
      LEFT JOIN altlast_version1.veen vn ON vn.vflz_id=v.vflz_id
      LEFT JOIN altlast_version1.vfsv vs ON vs.vflz_id=v.vflz_id
      LEFT JOIN altlast_version1.vfus vu ON vu.vflz_id=v.vflz_id
      LEFT JOIN altlast_version1.vgas vg ON vg.vflz_id=v.vflz_id
      LEFT JOIN altlast_version1.zusa zs ON zs.vflz_id=v.vflz_id 
      WHERE  COALESCE(be.c_bere_res_abwbewe::text, ''::text) <> ALL (ARRAY['00'::character varying, 'BLKR10'::character varying]::text[]))   AS foo;

  END;
$$;


--
-- Name: fts_query_obje(text); Type: FUNCTION; Schema: altlast_version1; Owner: -
--

CREATE FUNCTION altlast_version1.fts_query_obje(searchterms text) RETURNS SETOF altlast_version1.fts_obje_result
    LANGUAGE plpgsql
    AS $$
  DECLARE
     res altlast_version1.fts_obje_result;
     rec record;
     andqry tsquery;
     orqry tsquery;
     i integer;
  BEGIN
  
    -- generates a query qith all words linked together with "&"
    -- for searching in the main vector content_ts
    SELECT plainto_tsquery('german',searchterms) INTO andqry;
    
    -- create a query for finding PARTS of the searchterms in the single vectors
    -- of the fieldvector array; the terms are linked with "|"
    SELECT to_tsquery(array_to_string(regexp_split_to_array(searchterms, E'\\s+'),' | ')) INTO orqry;
    
    FOR rec IN SELECT * FROM (
                SELECT vflz_id,obje_id,sto_kennung,fieldcontent,fieldvector,fieldname, rank(content_ts,andqry) AS ranking 
                FROM altlast_version1.fts_obje 
                WHERE content_ts @@ andqry) AS foo
            ORDER BY ranking DESC, obje_id ASC LOOP
        
        FOR i IN SELECT generate_series(array_lower(rec.fieldcontent,1), array_upper(rec.fieldcontent,1))  LOOP
            IF rec.fieldvector[i] @@ orqry THEN
                SELECT rec.vflz_id AS vflz_id, rec.obje_id AS obje_id, rec.sto_kennung AS sto_kennung, rec.fieldname[i] AS fieldname, headline(rec.fieldcontent[i], orqry) AS fieldcontent INTO res;
                RETURN NEXT res;
            END IF;
        
        END LOOP;
    
    END LOOP;

  END;
$$;


--
-- Name: fts_query_obje(text, integer, integer); Type: FUNCTION; Schema: altlast_version1; Owner: -
--

CREATE FUNCTION altlast_version1.fts_query_obje(searchterms text, page integer, results_per_page integer) RETURNS SETOF altlast_version1.fts_obje_result
    LANGUAGE plpgsql
    AS $$
  DECLARE
     res altlast_version1.fts_obje_result;
     rec record;
     andqry tsquery;
     orqry tsquery;
     i integer;
  BEGIN
  
    -- generates a query qith all words linked together with "&"
    -- for searching in the main vector content_ts
    SELECT plainto_tsquery('german',searchterms) INTO andqry;
    
    -- create a query for finding PARTS of the searchterms in the single vectors
    -- of the fieldvector array; the terms are linked with "|"
    SELECT to_tsquery(array_to_string(regexp_split_to_array(searchterms, E'\\s+'),' | ')) INTO orqry;
    
    FOR rec IN SELECT DISTINCT ON (obje_id) * FROM (SELECT  * FROM (
                SELECT vflz_id,obje_id,sto_kennung,fieldcontent,fieldvector,fieldname, rank(content_ts,andqry) AS ranking 
                FROM altlast_version1.fts_obje 
                WHERE content_ts @@ andqry) AS foo
            ORDER BY ranking DESC, obje_id ASC) foo2 LIMIT results_per_page OFFSET page*results_per_page LOOP
        
        FOR i IN SELECT generate_series(array_lower(rec.fieldcontent,1), array_upper(rec.fieldcontent,1))  LOOP
            IF rec.fieldvector[i] @@ orqry THEN
                SELECT rec.vflz_id AS vflz_id, rec.obje_id AS obje_id, rec.sto_kennung AS sto_kennung, rec.fieldname[i] AS fieldname, headline(rec.fieldcontent[i], orqry,'StartSel=<b>, StopSel=</b>') AS fieldcontent INTO res;
                RETURN NEXT res;
            END IF;
        
        END LOOP;
    
    END LOOP;

  END;
$$;


--
-- Name: get_bewe_date(integer); Type: FUNCTION; Schema: altlast_version1; Owner: -
--

CREATE FUNCTION altlast_version1.get_bewe_date(objeid integer) RETURNS date
    LANGUAGE plpgsql
    AS $$
DECLARE
    rec RECORD;
    res DATE;

BEGIN

    res = NULL;

    FOR rec in SELECT g.c_gs_typ, g.c_gs_status, g.end_datum_ist 
    FROM altlast_version1.obje o 
    JOIN altlast_version1.gs_obje go USING(obje_id) 
    JOIN altlast_version1.gs g USING (gs_id)
    WHERE o.obje_id=objeid
    AND g.c_gs_status = '50' --Gesch�ft abgeschlossen
    AND g.c_gs_typ IN ('5','88','7') -- def. Eintrag, �nderung Bewertung, Nichteintrag
    AND end_datum_ist IS NOT NULL 
    ORDER BY end_datum_ist ASC --Sortierutn fuer Auswertung relevant!
    LIMIT 1 LOOP

  IF rec.c_gs_typ IN ('5','88') AND rec.c_gs_status ='50' THEN 
    res := rec.end_datum_ist;
  END IF;
  IF rec.c_gs_typ IN ('7') AND rec.c_gs_status ='50' THEN
          res := NULL;
  END IF;

    END LOOP;



    RETURN res;
END
$$;


--
-- Name: FUNCTION get_bewe_date(objeid integer); Type: COMMENT; Schema: altlast_version1; Owner: -
--

COMMENT ON FUNCTION altlast_version1.get_bewe_date(objeid integer) IS 'Datum des juengsten rechtsgueltigen Eintrags. Ein spaeteres GS Nichteintrag annuliert das Datum des Eintrags.';


--
-- Name: get_bewe_valid(integer); Type: FUNCTION; Schema: altlast_version1; Owner: -
--

CREATE FUNCTION altlast_version1.get_bewe_valid(objeid integer) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
    res TEXT;
    rec RECORD;

BEGIN
    /*
    SELECT altlast_hist.snapshot(1,vflz_id,'Initial clone') FROM altlast_version1.vflz_current_v OFFSET 50;
    SELECT * FROM altlast_version1.vflz_current_v WHERE obje_id=39;
    SELECT * FROM altlast_version1.gs g JOIN altlast_version1.gs_obje go USING(gs_id) WHERE obje_id=39;
    SELECT COUNT(*) FROM altlast_version1.vflz WHERE obje_id=39;
    SELECT altlast_version1.get_bewe_valid(39);
    SELECT obje_id,vflz_id,c_bere_res_abwbewe FROM altlast_version1.bere JOIN altlast_version1.vflz USING(vflz_id) WHERE obje_id=39;
    SELECT altlast_version1.get_bewe_valid(obje_id) FROM (SELECT DISTINCT obje_id FROM altlast_version1.gs_obje LIMIT 10) x;
    */

    res = NULL;

    SELECT g.c_gs_typ, g.c_gs_status, g.end_datum_ist 
    FROM altlast_version1.obje o 
    JOIN altlast_version1.gs_obje go USING(obje_id) 
    JOIN altlast_version1.gs g USING (gs_id)
    WHERE o.obje_id=objeid
    AND g.c_gs_status = '50' --Gesch�ft abgeschlossen
    AND g.c_gs_typ IN ('5','88','7') -- def. Eintrag, �nderung Bewertung, Nichteintrag
    AND end_datum_ist IS NOT NULL 
    ORDER BY end_datum_ist DESC
    INTO rec;

    IF rec IS NULL THEN
        res = NULL;
    ELSE
        SELECT b.c_bere_res_abwbewe 
        FROM altlast_version1.bere b 
        JOIN altlast_version1.vflz v USING (vflz_id)
        JOIN hist.snapshot h ON b.vflz_id=h.key_value AND h.history_id=1
        WHERE obje_id=objeid AND h.created<=rec.end_datum_ist 
        ORDER BY h.created DESC
        INTO res;
        IF res IS NULL THEN
            RAISE NOTICE 'F�r den Standort obje_id=% sind keine historisierten Daten f�r das lettze abgeschlossene Gesch�ft verf�gbar',objeid;
        END IF;

    END IF;

    RETURN res;
END
$$;


--
-- Name: FUNCTION get_bewe_valid(objeid integer); Type: COMMENT; Schema: altlast_version1; Owner: -
--

COMMENT ON FUNCTION altlast_version1.get_bewe_valid(objeid integer) IS 'Datum des juengsten rechtsgueltigen Eintrags. Ein spaeteres GS Nichteintrag annuliert das Datum des Eintrags.';


--
-- Name: get_massnahmen_date(integer, text); Type: FUNCTION; Schema: altlast_version1; Owner: -
--

CREATE FUNCTION altlast_version1.get_massnahmen_date(objeid integer, gstyp text) RETURNS date
    LANGUAGE plpgsql
    AS $$
DECLARE
    dat TIMESTAMP;

BEGIN
    /*
    SELECT altlast_version1.get_massnahmen_date(obje_id,'5') FROM (SELECT DISTINCT obje_id FROM altlast_version1.gs_obje LIMIT 10) x;
    */



    SELECT g.end_datum_ist 
    FROM altlast_version1.obje o 
    JOIN altlast_version1.gs_obje go USING(obje_id) 
    JOIN altlast_version1.gs g USING (gs_id)
    WHERE o.obje_id=objeid
    AND g.c_gs_status = '50' --Geschaeft abgeschlossen
    AND g.c_gs_typ = gstyp 
    AND end_datum_ist IS NOT NULL 
    ORDER BY end_datum_ist DESC
    INTO dat;

    RETURN dat;
END
$$;


