--
-- Name: get_sachbearbeiter(); Type: FUNCTION; Schema: altlast_version1; Owner: -
--

CREATE FUNCTION altlast_version1.get_sachbearbeiter(OUT subj_id integer, OUT bez_art text) RETURNS record
    LANGUAGE plpgsql
    AS $$
DECLARE
  rec record;
BEGIN
SELECT b.subj_id INTO rec FROM altlast_version1.ben b JOIN altlast_version1.ben_grp bg ON UPPER(b.log_kuerzel)=UPPER(CURRENT_USER) AND b.subj_id=bg.subj_id JOIN altlast_version1.grp g ON g.grp_kuerzel=bg.grp_kuerzel AND UPPER(g.grp_kuerzel)='ALTLAST' LIMIT 1;
    IF (rec.subj_id IS NOT NULL) THEN
      subj_id=rec.subj_id;
      bez_art='10';
    ELSE
      subj_id=NULL;
      bez_art=NULL;
    END IF;
END;
$$;


