) as non_closable
WHERE non_closable.medp>=CURRENT_DATE LOOP

       
        UPDATE altlast_version1.gss SET end_datum_ist=CURRENT_DATE, c_gss_status='50', h_gss_status=2001 WHERE gs_id IN (SELECT gs_id FROM altlast_version1.gs_obje WHERE obje_id=objeid) AND c_gss_status!='50';
        UPDATE altlast_version1.gs SET end_datum_ist=CURRENT_DATE, c_gs_status='50', h_gs_status=2001 WHERE gs_id IN (SELECT gs_id FROM altlast_version1.gs_obje WHERE obje_id=objeid) AND c_gs_status!='50';
    END LOOP;   
         */

