--
-- Name: gss_append_report(bigint, bigint, bigint, bytea, text); Type: FUNCTION; Schema: altlast_version1; Owner: -
--

CREATE FUNCTION altlast_version1.gss_append_report(pgs_id bigint, pgss_id bigint, preport_id bigint, pdata bytea, pmimetype text) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
DECLARE
    bytaid bigint;
    bez text;
    gsid bigint;

BEGIN
    SELECT bezeichnung INTO bez FROM altlast_version1.rpt_report WHERE report_id=preport_id;
    IF bez IS NULL THEN
        RAISE EXCEPTION 'SHOWMSG Report mit angegebener ID existiert nicht.';
    END IF;
    
    SELECT gs_id INTO gsid FROM altlast_version1.gss WHERE gss_id=pgss_id AND gs_id=pgs_id;
    IF gsid IS NULL THEN
        RAISE EXCEPTION 'SHOWMSG Kein passendes Geschäft/Teilgeschäft gefunden.';
    END IF;
    
    INSERT INTO altlast_version1.byta (bezeichnung,datum,mime_type,daten,dateityp,dateisuffix) (
  select bez as bezeichnung ,
    now()::date as datum ,
    pmimetype,
    pdata as daten ,
    10 as dateityp,
    null
    ) RETURNING byta_id INTO bytaid;
    IF bytaid IS NULL THEN
        RAISE EXCEPTION 'SHOWMSG Fehler beim Speichern der Daten.';
    END IF;    
    
    INSERT INTO altlast_version1.byta_gss (gs_id,gss_id,byta_id) VALUES (gsid,pgss_id,bytaid);
    
    PERFORM altlast_version1.byta_rename(bytaid);
    
    RETURN pgss_id;
END;$$;


