--
-- Name: height(public.geometry); Type: FUNCTION; Schema: altlast_version1; Owner: -
--

CREATE FUNCTION altlast_version1.height(geom public.geometry) RETURNS double precision
    LANGUAGE plpgsql
    AS $$
DECLARE
  this_srid integer;
  bx box3d;
  dist double precision;
BEGIN
  SELECT srid(geom) INTO this_srid;
  SELECT ST_Extent(geom)::box3d INTO bx;
  SELECT ST_Distance( 
    SetSRID(ST_MakePoint(ST_XMin(bx),ST_YMin(bx))::geometry,this_srid), 
    SetSRID(ST_MakePoint(ST_XMin(bx),ST_YMax(bx))::geometry,this_srid))
    INTO dist;
  RETURN dist;
END
$$;


--
-- Name: FUNCTION height(geom public.geometry); Type: COMMENT; Schema: altlast_version1; Owner: -
--

COMMENT ON FUNCTION altlast_version1.height(geom public.geometry) IS 'Calculate the height of a geometry in projection units.';


--
-- Name: imp_parz(); Type: FUNCTION; Schema: altlast_version1; Owner: -
--

CREATE FUNCTION altlast_version1.imp_parz() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    rec record;
    rec2 record;
    rec3 record;
    rec4 record;
    do_insert boolean;
BEGIN

    --Aufruf via Trigger auf imp_parz_log: 
    --INSERT INTO altlast_version1.imp_parz_log (import_date) VALUES (NOW());


    RAISE NOTICE 'Import Start: %, %', NOW()::date, NOW()::time;

    -- auf nicht mehr vorhandene parzellen ueberpruefen und deren c_status auf false setzen    
    RAISE NOTICE 'Deaktiviere Parzellen in Tabelle grun';
    UPDATE altlast_version1.grun set c_status=False FROM (
  SELECT grun_id
  FROM altlast_version1.grun g 
  LEFT JOIN altlast_version1.imp_parz ip ON ip.gemeinde_id_bfs=g.h_gem_id and g.gb_nummer=ip.nummer 
  WHERE grundstueck is null and g.c_status=true) foo
   WHERE grun.grun_id=foo.grun_id;

  
    RAISE NOTICE 'Importiere Parzellen';
    
    FOR rec IN SELECT DISTINCT ON (ip.gemeinde_id_bfs) ip.gemeinde_id_bfs,hg.gemeinde FROM altlast_version1.imp_parz ip LEFT JOIN altlast_version1.h_gem hg ON (ip.gemeinde_id_bfs=hg.h_gem_id) LOOP

        RAISE NOTICE 'Bearbeite Gemeinde Nr %',rec.gemeinde_id_bfs;
        
        IF rec.gemeinde IS NULL THEN
            RAISE EXCEPTION 'Es existiert keine Gemeinde mit der Nummer ',rec.gemeinde_id_bfs;
        ELSE
            FOR rec2 IN SELECT foo.nummer,cod.code,ST_Collect(GeomFromText(foo.grundstueck,21781)) AS geom,foo.code_bez FROM (SELECT ip.nummer,(CASE WHEN ip.art='Quellenrecht' THEN 'Quellrecht' ELSE ip.art END) AS code_bez,ip.grundstueck FROM altlast_version1.imp_parz ip WHERE ip.gemeinde_id_bfs=rec.gemeinde_id_bfs AND grundstueck IS NOT NULL ) AS foo LEFT JOIN altlast_version1.cod cod ON (cod.bezeichnung=foo.code_bez) WHERE cod.c_cli_id=20 GROUP BY foo.nummer,cod.code,foo.code_bez LOOP
                IF rec2.code IS NULL THEN
                    RAISE EXCEPTION 'Es existiert kein code fuer ', rec2.code_bez;
                END IF;
                
                BEGIN
                    INSERT INTO altlast_version1.grun (h_gem_id,gb_nummer,c_grun_art,wkb_geometry,bemerkungen) VALUES (rec.gemeinde_id_bfs,rec2.nummer,rec2.code,rec2.geom,'Aus Parzis übernommen');
                EXCEPTION WHEN unique_violation THEN
                    --RAISE NOTICE 'Existiert bereits - wird ignoriert.';
                    --UPDATE altlast_version1.grun SET c_grun_art=rec2.code AND wkb_geometry=GeomFromText(rec2.grundstueck,21781) WHERE h_gem_id=rec.gemeinde_id_bfs AND gb_nummer=rec2.nummer;
                END;
    
        
            END LOOP;
        END IF; 
        
    END LOOP;
    
    
    RAISE NOTICE 'Importiere Besitzer';
    FOR rec IN SELECT id,name1 AS name ,name2 AS taetigkeit,(CASE WHEN adresse LIKE 'Postfach%' THEN name3 ELSE adresse END) AS strasse,plz,ort FROM altlast_version1.imp_bgv_pers LOOP
        RAISE NOTICE 'Subjekt % %',coalesce(rec.name,'?'),coalesce(rec.taetigkeit,'?');
        do_insert:=False;
        -- backup ueberpruefen
        SELECT subj_id INTO rec2 FROM altlast_version1.imp_subj WHERE coalesce(name,'')=coalesce(rec.name,'') AND coalesce(taetigkeit,'')=coalesce(rec.taetigkeit,'') AND coalesce(strasse,'')=coalesce(rec.strasse,'') AND coalesce(postleitzahl,'')=coalesce(rec.plz::character varying,'') AND coalesce(ort,'')=coalesce(rec.ort,'');
        IF rec2.subj_id IS NOT NULL THEN
            -- wenn nicht mehr in subj existent neu anlegen
            SELECT subj_id,name INTO rec4 FROM altlast_version1.subj WHERE subj_id=rec2.subj_id;
            IF rec4.subj_id IS NULL THEN
                DELETE FROM altlast_version1.imp_subj WHERE subj_id=rec2.subj_id;
                do_insert:=True;
            END IF;
        ELSE
            -- komplett neu anlegen
            do_insert:=True;
        END IF;
        
        IF do_insert=True THEN
            INSERT INTO altlast_version1.subj (name,taetigkeit,bemerkungen,herkunft) VALUES (rec.name,rec.taetigkeit,'Aus BGV übernommen',1) RETURNING subj_id INTO rec2;
            INSERT INTO altlast_version1.adr (ort,postleitzahl,strasse,bemerkungen) VALUES (rec.ort,rec.plz::character varying,rec.strasse,'Aus BGV übernommen') RETURNING adr_id INTO rec3;
            INSERT INTO altlast_version1.subj_adr (subj_id,adr_id) VALUES (rec2.subj_id,rec3.adr_id);
            -- backup
            INSERT INTO altlast_version1.imp_subj (subj_id,name,taetigkeit,strasse,postleitzahl,ort) VALUES (rec2.subj_id,rec.name,rec.taetigkeit,rec.strasse,rec.plz::character varying,rec.ort);
        END IF;
        
   
        
        -- verknuepfung besitzer-parzellen herstellen
        FOR rec3 IN SELECT g.grun_id FROM altlast_version1.imp_bgv_geb ibg JOIN altlast_version1.h_ort ho ON (ho.postleitzahl=ibg.plz/* AND ho.ortsname=ibg.ort*/) JOIN altlast_version1.grun g ON g.h_gem_id=ho.h_gem_id AND g.gb_nummer=ibg.parzelle WHERE ibg.eigentuemer=rec.id LOOP
            BEGIN
                INSERT INTO altlast_version1.grun_subj (subj_id, grun_id) VALUES (rec2.subj_id,rec3.grun_id);
            EXCEPTION WHEN unique_violation THEN
                --RAISE NOTICE 'Existiert bereits - wird ignoriert.';
                    WHEN foreign_key_violation THEN
                    -- passender eintrag in grun existiert nicht - ignoriert
                    WHEN datatype_mismatch THEN
            END;
        END LOOP;
    END LOOP;

    RAISE NOTICE 'Import Ende: %, %', NOW()::date, NOW()::time;
    
    RETURN NEW;
END;$$;


--
-- Name: kbs_ustand(integer); Type: FUNCTION; Schema: altlast_version1; Owner: -
--

CREATE FUNCTION altlast_version1.kbs_ustand(pobje_id integer) RETURNS text
    LANGUAGE sql
    AS $_$


select stand_txt_1 || ', ' || stand_txt_2 || ' ' || end_datum

from (
  select  end_datum_ist,
    case 
      -- 9 Historische Untersuchung / Pflichtenheft
      when gses.c_gs_typ = '9' then 'Historische Untersuchung'
      -- 10 Technische Untersuchung
      when gses.c_gs_typ = '10' then 'Technische Untersuchung'
      -- 11 Detailuntersuchung
      when gses.c_gs_typ = '11' then 'Detailuntersuchung'
      -- 16 Ueberwachungskonzept
      when gses.c_gs_typ = '16' then 'Überwachung'
      -- 12 Sanierungsprojekt
      when gses.c_gs_typ = '13' then 'Sanierung'
    end as stand_txt_1,
    /*case 
      -- 9 Historische Untersuchung / Pflichtenheft
      when gses.c_gs_typ = '9' then 4
      -- 10 Technische Untersuchung
      when gses.c_gs_typ = '10' then 3
      -- 11 Detailuntersuchung
      when gses.c_gs_typ = '11' then 2
      -- 16 Ueberwachungskonzept
      when gses.c_gs_typ = '16' then 1
      -- 12 Sanierungsprojekt
      when gses.c_gs_typ = '13' then 0
    end as stand_sort_1,*/
    case 
      -- 50 abgeschlossen
      when gses.c_gs_status = '50' then 'abgeschlossen'
    end as stand_txt_2,
    to_char(end_datum_ist,'DD.MM.YYYY')::text AS end_datum
    /*case 
      -- 20 in bearbeitung
      when gses.c_gs_status = '20' then 1
      -- 50 abgeschlossen
      when gses.c_gs_status = '50' then 0
    end as stand_sort_2*/
  from (
    select c_gs_typ, c_gs_status ,end_datum_ist
    from altlast_version1.gs gs 
    join altlast_version1.gs_obje gso on gso.gs_id = gs.gs_id 
    where gso.obje_id = $1
      and c_gs_typ in ('13', '9', '10', '11', '16')
      and c_gs_status in ( '50')
  ) gses
) uall
order by end_datum_ist/*((stand_sort_1*2)+stand_sort_2)*/ desc limit 1

$_$;


--
-- Name: londiste_priviledges(); Type: FUNCTION; Schema: altlast_version1; Owner: -
--

CREATE FUNCTION altlast_version1.londiste_priviledges() RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE 
  tablename text;
  
BEGIN
  FOR tablename in SELECT table_name FROM londiste.subscriber_table LOOP
    EXECUTE 'REVOKE ALL PRIVILEGES ON TABLE ' || tablename || ' FROM public';
    EXECUTE 'GRANT SELECT ON TABLE ' || tablename || ' TO public';

    EXECUTE 'REVOKE ALL PRIVILEGES ON TABLE ' || tablename || ' FROM altlsys';
    EXECUTE 'GRANT SELECT ON TABLE ' || tablename || ' TO altlsys';

    EXECUTE 'REVOKE ALL PRIVILEGES ON TABLE ' || tablename || ' FROM altlast';
    EXECUTE 'GRANT SELECT ON TABLE ' || tablename || ' TO altlast';
  END LOOP;
END
$$;


--
-- Name: FUNCTION londiste_priviledges(); Type: COMMENT; Schema: altlast_version1; Owner: -
--

COMMENT ON FUNCTION altlast_version1.londiste_priviledges() IS 'Setzt die Berechtigungen auf Tabellen die von anderen Servern repliziert werden für die lokalen Rollen public,altlast,altlsys auf nur lesend.';


--
-- Name: pool_gs_sync(bigint, bigint, boolean, boolean); Type: FUNCTION; Schema: altlast_version1; Owner: -
--

CREATE FUNCTION altlast_version1.pool_gs_sync(ppool_id bigint, pgs_id bigint, psyncgss boolean, pclonesubj boolean) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    meta_info record;
    existing_gsid bigint;
    tgss bigint;
    obje record;
    syncfields character varying[];
    syncfieldssubj character varying[];
    syncfieldsgsobje character varying[];
    asql text;
    counter_sync integer;
    counter_total integer;
    more_than_allowed character varying;
BEGIN

    -- meta_info feststellen
    SELECT gs.c_gs_typ,ac.bezeichnung INTO meta_info FROM altlast_version1.gs gs JOIN altlast_version1.cod ac ON ac.code=gs.c_gs_typ  WHERE gs.gs_id=pgs_id AND ac.c_cli_id=2002;
    IF meta_info IS NULL THEN
        RAISE EXCEPTION 'SHOWMSG Geschäft existiert nicht.';
    END IF;

    
    -- feststellen ob geschaeftstyp noch bei einem anderen geschaeft im pool vorhanden, wenn ja exception 
    SELECT array_to_string(array(SELECT obje_id FROM 
        (SELECT op.obje_id
            FROM altlast_version1.gs gs 
            JOIN altlast_version1.gs_obje gso ON gso.gs_id=gs.gs_id 
            JOIN altlast_version1.obje_pool op ON op.obje_id=gso.obje_id
            WHERE op.pool_id=ppool_id AND gs.c_gs_typ=meta_info.c_gs_typ AND gs.gs_id!=pgs_id) as foo),', ') INTO more_than_allowed;
        
    IF more_than_allowed!='' THEN
        RAISE EXCEPTION 'SHOWMSG Das Geschäft % ist bereits für folgende[n] Standort[e] registriert: %. Kopieren ist nicht möglich.', meta_info.bezeichnung, more_than_allowed;
    END IF;
    
    
    
    -- zu ubernehmende spalten feststellen

    -- achtung: bei  mehreren datenbanken mit altlast-schemen -> evtl probleme
    SELECT array(select DISTINCT column_name::character varying from information_schema.columns 
        WHERE table_name='gs' AND table_schema='altlast' AND column_name!='gs_id') INTO syncfields;
    SELECT array(select DISTINCT column_name::character varying from information_schema.columns 
        WHERE table_name='gs_subj' AND table_schema='altlast' AND column_name!='gs_id') INTO syncfieldssubj;
    SELECT array(select DISTINCT column_name::character varying from information_schema.columns 
        WHERE table_name='gs_obje' AND table_schema='altlast' AND column_name!='gs_id' AND column_name!='obje_id') INTO syncfieldsgsobje;
    
    
    
    counter_sync := 0;
    counter_total :=0;
    FOR obje IN SELECT aop.obje_id FROM altlast_version1.obje_pool aop WHERE aop.pool_id=ppool_id LOOP
        -- existiert fuer diesen standort schon ein geschaeft dieses typs?
        SELECT ag.gs_id INTO existing_gsid FROM altlast_version1.gs_obje ago JOIN altlast_version1.gs ag ON ag.gs_id=ago.gs_id WHERE ago.obje_id=obje.obje_id AND ag.c_gs_typ=meta_info.c_gs_typ;
        
        IF existing_gsid IS NULL THEN -- KOPIEREN / NEU ANLEGEN 
            -- gs neu anlegen
            asql := 'INSERT INTO altlast_version1.gs (' || array_to_string(syncfields,',') || ') (SELECT ' || array_to_string(syncfields,',') || ' FROM altlast_version1.gs WHERE gs_id=' || pgs_id || ') RETURNING gs_id';
            --RAISE NOTICE '%',asql;
            EXECUTE asql INTO existing_gsid; 
            
            -- mit dem obje verknuepfen
            asql := 'INSERT INTO altlast_version1.gs_obje (gs_id,obje_id,'|| array_to_string(syncfieldsgsobje,',') ||') (SELECT '|| existing_gsid ||' AS gs_id,' || obje.obje_id || ' AS obje_id,' || array_to_string(syncfieldsgsobje,',') || ' FROM altlast_version1.gs_obje WHERE gs_id=' || pgs_id || ')';
            
            -- RAISE NOTICE '%',asql;
            EXECUTE asql;
            
            IF pclonesubj =TRUE THEN     
                -- nicht bereits vorhandene beteiligte uebernehmen falls gewuenscht
                asql := 'INSERT INTO altlast_version1.gs_subj (gs_id,' || array_to_string(syncfieldssubj,',') || ') (SELECT '|| existing_gsid ||' AS gs_id,'|| array_to_string(syncfieldssubj,',') ||' FROM altlast_version1.gs_subj WHERE gs_id='|| pgs_id ||' EXCEPT SELECT '|| existing_gsid ||' AS gs_id,'|| array_to_string(syncfieldssubj,',') ||' FROM altlast_version1.gs_subj WHERE gs_id='|| existing_gsid ||')';
                --RAISE NOTICE '%',asql;
                EXECUTE asql;
            END IF;
                  
            SELECT counter_sync+1 INTO counter_sync;
        END IF;         
            
        SELECT counter_total+1 INTO counter_total;
        
    END LOOP;
    
    -- teilgeschaefte falls gewuenscht uebernehmen
    IF psyncgss=True THEN 
        FOR tgss IN SELECT gss_id FROM altlast_version1.gss WHERE gs_id=pgs_id LOOP
            
            PERFORM altlast_version1.pool_gss_sync(ppool_id, tgss, pclonesubj );
        END LOOP;
    END IF;
    
    RAISE NOTICE 'SHOWMSG Geschäft % in % von % Standorten angelegt.', meta_info.bezeichnung, counter_sync, counter_total;
    
END;$$;


--
-- Name: pool_gs_sync(bigint, bigint, boolean, boolean, character varying[]); Type: FUNCTION; Schema: altlast_version1; Owner: -
--

CREATE FUNCTION altlast_version1.pool_gs_sync(ppool_id bigint, pgs_id bigint, psyncgss boolean, pclonesubj boolean, pfields character varying[]) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    meta_info record;
    --gses character varying;
    existing_gsid bigint;
    tgss bigint;
    obje record;
    syncfields character varying[];
    syncfieldssubj character varying[];
    asql text;
    counter_sync integer;
    counter_total integer;
    more_than_allowed character varying;
BEGIN

    -- meta_info feststellen
    SELECT gs.c_gs_typ,ac.bezeichnung INTO meta_info FROM altlast_version1.gs gs JOIN altlast_version1.cod ac ON ac.code=gs.c_gs_typ  WHERE gs.gs_id=pgs_id AND ac.c_cli_id=2002;
    IF meta_info IS NULL THEN
        RAISE EXCEPTION 'SHOWMSG Geschäft existiert nicht.';
    END IF;

    
    -- feststellen ob geschaeftstyp bei keinem geschaeft im pool mehr als einmal vorhanden, ansonsten exception 
    SELECT array_to_string(array(SELECT obje_id FROM 
        (SELECT op.obje_id,count(gs.gs_id) AS cnt
            FROM altlast_version1.gs gs 
            JOIN altlast_version1.gs_obje gso ON gso.gs_id=gs.gs_id 
            JOIN altlast_version1.obje_pool op ON op.obje_id=gso.obje_id
            WHERE op.pool_id=ppool_id AND gs.c_gs_typ=meta_info.c_gs_typ
            GROUP BY op.obje_id) AS foo 
        WHERE cnt>1) ,', ') INTO more_than_allowed;    
    IF more_than_allowed!='' THEN
        RAISE EXCEPTION 'SHOWMSG Das Geschäft % ist für den/die Standort[e] % mehrfach registriert. Eine Synchronisierung ist nicht möglich.', meta_info.bezeichnung, more_than_allowed;
    END IF;
    
    
    
    -- zu ubernehmende spalten feststellen
    IF pfields IS NULL THEN
        -- achtung: bei  mehreren datenbanken mit altlast-schemen -> evtl probleme
        SELECT array(select DISTINCT column_name::character varying from information_schema.columns 
            WHERE table_name='gs' AND table_schema='altlast' AND column_name!='gs_id') INTO syncfields;
    ELSE
        syncfields:=pfields;
    END IF;
    SELECT array(select DISTINCT column_name::character varying from information_schema.columns 
        WHERE table_name='gs_subj' AND table_schema='altlast' AND column_name!='gs_id') INTO syncfieldssubj;
        
    
    counter_sync := 0;
    counter_total :=0;
    FOR obje IN SELECT aop.obje_id FROM altlast_version1.obje_pool aop WHERE aop.pool_id=ppool_id LOOP
        -- existiert fuer diesen standort schon ein geschaeft dieses typs?
        SELECT ag.gs_id INTO existing_gsid FROM altlast_version1.gs_obje ago JOIN altlast_version1.gs ag ON ag.gs_id=ago.gs_id WHERE ago.obje_id=obje.obje_id AND ag.c_gs_typ=meta_info.c_gs_typ;        
      
        IF existing_gsid IS NOT NULL AND existing_gsid!=pgs_id  THEN -- SYNCHRONISIEREN
            --gs syncronisieren
            asql := 'UPDATE altlast_version1.gs SET (' || array_to_string(syncfields,',') || ') = ( foo.' || array_to_string(syncfields,', foo.') || ') FROM (SELECT bar.' || array_to_string(syncfields,', bar.') || ' FROM altlast_version1.gs bar WHERE bar.gs_id=' || pgs_id || ') AS foo WHERE gs_id=' || existing_gsid;
            --RAISE NOTICE '%',asql;
            EXECUTE asql;
            
            SELECT counter_sync+1 INTO counter_sync;
                 
                
            IF pclonesubj =TRUE THEN     
                -- nicht bereits vorhandene beteiligte uebernehmen falls gewuenscht
                asql := 'INSERT INTO altlast_version1.gs_subj (gs_id,' || array_to_string(syncfieldssubj,',') || ') (SELECT '|| existing_gsid ||' AS gs_id,'|| array_to_string(syncfieldssubj,',') ||' FROM altlast_version1.gs_subj WHERE gs_id='|| pgs_id ||' EXCEPT SELECT '|| existing_gsid ||' AS gs_id,'|| array_to_string(syncfieldssubj,',') ||' FROM altlast_version1.gs_subj WHERE gs_id='|| existing_gsid ||')';
                --RAISE NOTICE '%',asql;
                EXECUTE asql;
            END IF;
        END IF;
        
        SELECT counter_total+1 INTO counter_total;
        
    END LOOP;
    
    -- teilgeschaefte falls gewuenscht uebernehmen
    IF psyncgss=True THEN 
        FOR tgss IN SELECT gss_id FROM altlast_version1.gss WHERE gs_id=pgs_id LOOP
            PERFORM altlast_version1.pool_gss_sync(ppool_id, tgss, pclonesubj, NULL );
        END LOOP;
    END IF;
    
    RAISE NOTICE 'SHOWMSG Synchronisierung des Geschäfts % für % von % Standorten ausgeführt.', meta_info.bezeichnung, counter_sync, counter_total;
    
END;$$;


--
-- Name: pool_gss_sync(bigint, bigint, boolean); Type: FUNCTION; Schema: altlast_version1; Owner: -
--

CREATE FUNCTION altlast_version1.pool_gss_sync(ppool_id bigint, pgss_id bigint, pclonesubj boolean) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    meta_info record;
    tgssid bigint; 
    existing_gss record;  
    obje record;
    syncfields character varying[];
    syncfieldssubj character varying[];
    syncfieldsgssobje character varying[];
    asql text;
    counter_sync integer;
    counter_total integer;
    more_than_allowed character varying;
BEGIN


    -- meta_info feststellen
    SELECT gs.c_gs_typ,gss.c_gss_typ,ac1.bezeichnung AS gs_bez,ac2.bezeichnung AS gss_bez,gs.gs_id INTO meta_info 
        FROM altlast_version1.gs gs 
        JOIN altlast_version1.cod ac1 ON ac1.code=gs.c_gs_typ  
        JOIN altlast_version1.gss gss ON gss.gs_id=gs.gs_id  
        JOIN altlast_version1.cod ac2 ON ac2.code=gss.c_gss_typ 
        WHERE gss.gss_id=pgss_id AND ac1.c_cli_id=2002 AND ac2.c_cli_id=2003;
        
    IF meta_info IS NULL THEN
        RAISE EXCEPTION 'SHOWMSG Teilgeschäft existiert nicht.';
    END IF;


    -- feststellen ob teilgeschaeftstyp noch bei einem anderen geschaeft im pool vorhanden, wenn ja exception 
    SELECT array_to_string(array(SELECT obje_id FROM 
        (SELECT op.obje_id
            FROM altlast_version1.gss gss 
            JOIN altlast_version1.gs gs ON gs.gs_id=gss.gs_id 
            JOIN altlast_version1.gs_obje gso ON gso.gs_id=gs.gs_id 
            JOIN altlast_version1.obje_pool op ON op.obje_id=gso.obje_id
            WHERE op.pool_id=ppool_id AND gs.c_gs_typ=meta_info.c_gs_typ AND gs.gs_id!=meta_info.gs_id AND gss.gss_id!=pgss_id AND gss.c_gss_typ=meta_info.c_gss_typ) as foo),', ') INTO more_than_allowed;
        
    IF more_than_allowed!='' THEN
        RAISE EXCEPTION 'SHOWMSG Das Teilgeschäft % ist bereits für folgende[n] Standort[e] registriert: %. Kopieren ist nicht möglich.', meta_info.gss_bez, more_than_allowed;
    END IF;

    
    -- zu ubernehmende spalten feststellen
    -- achtung: bei  mehreren datenbanken mit altlast-schemen -> evtl probleme
    SELECT array(select DISTINCT column_name::character varying from information_schema.columns 
        WHERE table_name='gss' AND table_schema='altlast' AND column_name!='gs_id' AND column_name!='gss_id') INTO syncfields;
    SELECT array(select DISTINCT column_name::character varying from information_schema.columns 
        WHERE table_name='gss_subj' AND table_schema='altlast' AND column_name!='gs_id' AND column_name!='gss_id') INTO syncfieldssubj;
    SELECT array(select DISTINCT column_name::character varying from information_schema.columns 
        WHERE table_name='gss_obje' AND table_schema='altlast' AND column_name!='gs_id' AND column_name!='gss_id' AND column_name!='obje_id') INTO syncfieldsgssobje;
    
    
    counter_sync := 0;
    counter_total := 0;
    FOR obje IN SELECT aop.obje_id FROM altlast_version1.obje_pool aop WHERE aop.pool_id=ppool_id LOOP
        -- existiert fuer diesen standort schon ein teilgeschaeft dieses typs? 
        SELECT ags.gs_id,agss.gss_id INTO existing_gss FROM altlast_version1.gs_obje ago JOIN altlast_version1.gs ags ON ags.gs_id=ago.gs_id LEFT JOIN (SELECT gss_id,gs_id FROM altlast_version1.gss WHERE c_gss_typ=meta_info.c_gss_typ ) AS agss ON agss.gs_id=ags.gs_id WHERE ago.obje_id=obje.obje_id AND ags.c_gs_typ=meta_info.c_gs_typ;
        
        IF existing_gss.gs_id IS NOT NULL THEN
            IF existing_gss.gss_id IS NULL AND existing_gss.gs_id!=meta_info.gs_id THEN -- KOPIEREN / NEU ANLEGEN 
                -- gss neu anlegen
                asql := 'INSERT INTO altlast_version1.gss (gs_id,' || array_to_string(syncfields,',') || ') (SELECT '|| existing_gss.gs_id ||' AS gs_id,' || array_to_string(syncfields,',') || ' FROM altlast_version1.gss WHERE gss_id=' || pgss_id || ') RETURNING gss_id';
                --RAISE NOTICE '%',asql;
                EXECUTE asql INTO tgssid; 
                
                existing_gss.gss_id := tgssid;
                -- mit dem obje verknuepfen
                asql := 'INSERT INTO altlast_version1.gss_obje (gss_id,gs_id,obje_id,'|| array_to_string(syncfieldsgssobje,',') ||') (SELECT '|| existing_gss.gss_id ||' AS gss_id,'|| existing_gss.gs_id ||' AS gs_id,' || obje.obje_id || ' AS obje_id,' || array_to_string(syncfieldsgssobje,',') || ' FROM altlast_version1.gss_obje WHERE gss_id=' || pgss_id || ')';
                --RAISE NOTICE '%',asql;
                EXECUTE asql;
                
                
                IF pclonesubj=TRUE THEN     
                    -- nicht bereits vorhandene beteiligte uebernehmen falls gewuenscht
                    asql := 'INSERT INTO altlast_version1.gss_subj (gss_id,gs_id,' || array_to_string(syncfieldssubj,',') || ') (SELECT '|| existing_gss.gss_id ||' AS gss_id,'|| existing_gss.gs_id ||' AS gs_id,'|| array_to_string(syncfieldssubj,',') ||' FROM altlast_version1.gss_subj WHERE gss_id='|| pgss_id ||' EXCEPT SELECT '|| existing_gss.gss_id ||' AS gss_id,'|| existing_gss.gs_id ||' AS gs_id,'|| array_to_string(syncfieldssubj,',') ||' FROM altlast_version1.gss_subj WHERE gss_id='|| existing_gss.gss_id ||')';
                    --RAISE NOTICE '%',asql;
                    EXECUTE asql;
                END IF;               
                
                SELECT counter_sync+1 INTO counter_sync;
                
            END IF;    
                
            
            SELECT counter_total+1 INTO counter_total;
            
        END IF;
    END LOOP;
    
    RAISE NOTICE 'SHOWMSG Teilgeschäft % in % von % Standorten angelegt.', meta_info.gss_bez, counter_sync, counter_total;
    
    
END;$$;


--
-- Name: pool_gss_sync(bigint, bigint, boolean, character varying[]); Type: FUNCTION; Schema: altlast_version1; Owner: -
--

CREATE FUNCTION altlast_version1.pool_gss_sync(ppool_id bigint, pgss_id bigint, pclonesubj boolean, pfields character varying[]) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    meta_info record;
    tgssid bigint; 
    existing_gss record;  
    obje record;
    syncfields character varying[];
    syncfieldssubj character varying[];
    asql text;
    counter_sync integer;
    counter_total integer;
    more_than_allowed character varying;
BEGIN


    -- meta_info feststellen
    SELECT gs.c_gs_typ,gss.c_gss_typ,ac1.bezeichnung AS gs_bez,ac2.bezeichnung AS gss_bez,gs.gs_id INTO meta_info 
        FROM altlast_version1.gs gs 
        JOIN altlast_version1.cod ac1 ON ac1.code=gs.c_gs_typ  
        JOIN altlast_version1.gss gss ON gss.gs_id=gs.gs_id  
        JOIN altlast_version1.cod ac2 ON ac2.code=gss.c_gss_typ 
        WHERE gss.gss_id=pgss_id AND ac1.c_cli_id=2002 AND ac2.c_cli_id=2003;
        
    IF meta_info IS NULL THEN
        RAISE EXCEPTION 'SHOWMSG Teilgeschäft existiert nicht.';
    END IF;


    -- feststellen ob teilgeschaeftstyp  bei einem anderen geschaeft im pool mehr als einmal vorhanden, wenn ja exception 
    SELECT array_to_string(array(SELECT obje_id FROM 
        (SELECT op.obje_id,count(gss.gss_id) as cnt
            FROM altlast_version1.gss gss 
            JOIN altlast_version1.gs gs ON gs.gs_id=gss.gs_id 
            JOIN altlast_version1.gs_obje gso ON gso.gs_id=gs.gs_id 
            JOIN altlast_version1.obje_pool op ON op.obje_id=gso.obje_id
            WHERE op.pool_id=ppool_id AND gs.gs_id!=meta_info.gs_id AND gss.gss_id!=pgss_id AND gss.c_gss_typ=meta_info.c_gss_typ
            GROUP BY op.obje_id) as foo 
        WHERE cnt>1),', ') INTO more_than_allowed;
        
    IF more_than_allowed!='' THEN
        RAISE EXCEPTION 'SHOWMSG Das Teilgeschäft % ist für den/die Standort[e] % mehrfach registriert. Eine Synchronisierung ist nicht möglich.', meta_info.gss_bez, more_than_allowed;
    END IF;

    
    -- zu ubernehmende spalten feststellen
    IF pfields IS NULL THEN
        -- achtung: bei  mehreren datenbanken mit altlast-schemen -> evtl probleme
        SELECT array(select DISTINCT column_name::character varying from information_schema.columns 
            WHERE table_name='gss' AND table_schema='altlast' AND column_name!='gs_id' AND column_name!='gss_id') INTO syncfields;
    ELSE
        syncfields:=pfields;
    END IF;
    SELECT array(select DISTINCT column_name::character varying from information_schema.columns 
        WHERE table_name='gss_subj' AND table_schema='altlast' AND column_name!='gs_id' AND column_name!='gss_id') INTO syncfieldssubj;
    
    
    counter_sync := 0;
    counter_total := 0;
    FOR obje IN SELECT aop.obje_id FROM altlast_version1.obje_pool aop WHERE aop.pool_id=ppool_id LOOP
        -- existiert fuer diesen standort schon ein teilgeschaeft dieses typs? 
        SELECT ags.gs_id,agss.gss_id INTO existing_gss FROM altlast_version1.gs_obje ago JOIN altlast_version1.gs ags ON ags.gs_id=ago.gs_id LEFT JOIN (SELECT gss_id,gs_id FROM altlast_version1.gss WHERE c_gss_typ=meta_info.c_gss_typ ) AS agss ON agss.gs_id=ags.gs_id WHERE ago.obje_id=obje.obje_id AND ags.c_gs_typ=meta_info.c_gs_typ;
        
        IF existing_gss.gs_id IS NOT NULL THEN
            IF existing_gss.gss_id!=pgss_id AND existing_gss.gs_id!=meta_info.gs_id THEN  -- SYNCHRONISIEREN
                --gss syncronisieren
                asql := 'UPDATE altlast_version1.gss SET (' || array_to_string(syncfields,',') || ') = ( foo.' || array_to_string(syncfields,', foo.') || ') FROM (SELECT bar.' || array_to_string(syncfields,', bar.') || ' FROM altlast_version1.gss bar WHERE bar.gss_id=' || pgss_id || ') AS foo WHERE gss_id=' || existing_gss.gss_id;
                --RAISE NOTICE '%',asql;
                EXECUTE asql;
                
                
                IF pclonesubj=TRUE THEN     
                    -- nicht bereits vorhandene beteiligte uebernehmen falls gewuenscht
                    asql := 'INSERT INTO altlast_version1.gss_subj (gss_id,gs_id,' || array_to_string(syncfieldssubj,',') || ') (SELECT '|| existing_gss.gss_id ||' AS gss_id,'|| existing_gss.gs_id ||' AS gs_id,'|| array_to_string(syncfieldssubj,',') ||' FROM altlast_version1.gss_subj WHERE gss_id='|| pgss_id ||' EXCEPT SELECT '|| existing_gss.gss_id ||' AS gss_id,'|| existing_gss.gs_id ||' AS gs_id,'|| array_to_string(syncfieldssubj,',') ||' FROM altlast_version1.gss_subj WHERE gss_id='|| existing_gss.gss_id ||')';
                    --RAISE NOTICE '%',asql;
                    EXECUTE asql;
                END IF;
                
                SELECT counter_sync+1 INTO counter_sync;
                        
            END IF;    
                
            SELECT counter_total+1 INTO counter_total;
            
        END IF;
    END LOOP;
    
    RAISE NOTICE 'SHOWMSG Synchronisierung des Teilgeschäftes % für % von % Standorten ausgeführt.', meta_info.gss_bez ,counter_sync,counter_total;
    
END;$$;


--
-- Name: qs_token_map(text, character varying); Type: FUNCTION; Schema: altlast_version1; Owner: -
--

CREATE FUNCTION altlast_version1.qs_token_map(str text, typ character varying) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
    rec record;
    asql text;
    astr text;
BEGIN
    asql:='SELECT find,replace_with FROM altlast_version1.qs_token_mappings';
    astr:=str;

    IF typ='subj' THEN
        asql:=asql || ' WHERE use_subj=True';
    ELSIF typ='obje' THEN
        asql:=asql || ' WHERE use_obje=True';
    END IF;
    
    FOR rec IN EXECUTE asql LOOP
        astr:=UPPER(REPLACE(UPPER(astr),UPPER(rec.find),UPPER(rec.replace_with)));
    END LOOP;
    
    RETURN trim(both ' ' from astr);
END;$$;


--
-- Name: queryextent(public.geometry); Type: FUNCTION; Schema: altlast_version1; Owner: -
--

CREATE FUNCTION altlast_version1.queryextent(geom public.geometry) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE 
  qry text;
BEGIN
    SELECT translate(translate((ST_extent(geom)::box2d)::text,'BOX()',''),' ',',') INTO qry;
    RETURN qry;
END
$$;


--
-- Name: FUNCTION queryextent(geom public.geometry); Type: COMMENT; Schema: altlast_version1; Owner: -
--

COMMENT ON FUNCTION altlast_version1.queryextent(geom public.geometry) IS 'Get the extent of a geometry as text suitable for a wms query string';


