--
-- Name: report_create_gs(bigint); Type: FUNCTION; Schema: altlast_version1; Owner: -
--

CREATE FUNCTION altlast_version1.report_create_gs(poolid bigint) RETURNS SETOF altlast_version1.rel_obje_gs
    LANGUAGE plpgsql
    AS $$
DECLARE
    rec record;
    gsid integer;
    reslt altlast_version1.rel_obje_gs;
BEGIN

    FOR rec IN SELECT foo.obje_id, bcg.gs_code, c.bezeichnung
                FROM
                    (SELECT op.obje_id, 
                        CASE
                            WHEN b.c_bere_res_abwbewe::text = ''::text OR b.c_bere_res_abwbewe IS NULL THEN b.c_bere_res_autobewe
                            ELSE b.c_bere_res_abwbewe
                        END AS c_bez_max_katrel
                    FROM altlast_version1.obje_pool op 
                    JOIN altlast_version1.vflz_current_v v ON v.obje_id=op.obje_id 
                    JOIN altlast_version1.bere b ON b.vflz_id=v.vflz_id
                    WHERE op.pool_id = poolid) AS foo
                JOIN altlast_version1.bere_cod_gs bcg ON bcg.bere_code=foo.c_bez_max_katrel 
                JOIN altlast_version1.cod c ON c.code=bcg.gs_code AND c.c_cli_id = gs_cli_id LOOP
        

        -- geschäfte entsprechend der Standortbewertung anlegen
        INSERT INTO altlast_version1.gs (h_gs_typ,c_gs_typ) VALUES (2002,rec.gs_code) RETURNING gs_id INTO gsid;
        -- mit objekt verknuepfen
        INSERT INTO altlast_version1.gs_obje (gs_id,obje_id,c_gs_obje_bez_art) VALUES (gsid, rec.obje_id, 6);
        -- beteiligte hinzufuegen
        INSERT INTO altlast_version1.gs_subj (gs_id,subj_id,c_gs_subj_bez_art) (
            SELECT gsid AS gs_id, so.subj_id, cb.gs_subj 
                FROM altlast_version1.subj_obje so 
                JOIN altlast_version1.cod_bezart cb ON cb.subj_obje=so.c_subj_obje_bez_art 
                WHERE cb.automap=True AND so.obje_id=rec.obje_id);
                
        reslt.obje_id:=rec.obje_id;
        reslt.gs_id:=gsid;
        RETURN NEXT reslt;
    END LOOP;
END;$$;


--
-- Name: report_create_gs(bigint, date); Type: FUNCTION; Schema: altlast_version1; Owner: -
--

CREATE FUNCTION altlast_version1.report_create_gs(poolid bigint, startdatum date) RETURNS SETOF altlast_version1.rel_obje_gs
    LANGUAGE plpgsql
    AS $$
DECLARE
    rec record;
    gsid integer;
    reslt altlast_version1.rel_obje_gs;
BEGIN

    FOR rec IN SELECT foo.obje_id, bcg.gs_code, c.bezeichnung
                FROM
                    (SELECT op.obje_id, 
                        CASE
                            WHEN b.c_bere_res_abwbewe::text = ''::text OR b.c_bere_res_abwbewe IS NULL THEN b.c_bere_res_autobewe
                            ELSE b.c_bere_res_abwbewe
                        END AS c_bez_max_katrel
                    FROM altlast_version1.obje_pool op 
                    JOIN altlast_version1.vflz_current_v v ON v.obje_id=op.obje_id 
                    JOIN altlast_version1.bere b ON b.vflz_id=v.vflz_id
                    WHERE op.pool_id = poolid) AS foo
                JOIN altlast_version1.bere_cod_gs bcg ON bcg.bere_code=foo.c_bez_max_katrel 
                JOIN altlast_version1.cod c ON c.code=bcg.gs_code AND c.c_cli_id = gs_cli_id LOOP
        

        -- geschäfte entsprechend der Standortbewertung anlegen
        INSERT INTO altlast_version1.gs (h_gs_typ,c_gs_typ, start_datum_ist) VALUES (2002,rec.gs_code,startdatum) RETURNING gs_id INTO gsid;
        -- mit objekt verknuepfen
        INSERT INTO altlast_version1.gs_obje (gs_id,obje_id,c_gs_obje_bez_art) VALUES (gsid, rec.obje_id, 6);
        -- beteiligte hinzufuegen
        INSERT INTO altlast_version1.gs_subj (gs_id,subj_id,c_gs_subj_bez_art) (
            SELECT gsid AS gs_id, so.subj_id, cb.gs_subj 
                FROM altlast_version1.subj_obje so 
                JOIN altlast_version1.cod_bezart cb ON cb.subj_obje=so.c_subj_obje_bez_art 
                WHERE cb.automap=True AND so.obje_id=rec.obje_id);
                
                
        reslt.obje_id:=rec.obje_id;
        reslt.gs_id:=gsid;
        RETURN NEXT reslt;
    END LOOP;
END;$$;


--
-- Name: report_create_gs_from_obje(bigint); Type: FUNCTION; Schema: altlast_version1; Owner: -
--

CREATE FUNCTION altlast_version1.report_create_gs_from_obje(objeid bigint) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
DECLARE
    rec record;
    gsid integer;
    reslt altlast_version1.rel_obje_gs;
BEGIN

    FOR rec IN SELECT foo.obje_id, bcg.gs_code, c.bezeichnung
                FROM
                    (SELECT o.obje_id, 
                        CASE
                            WHEN b.c_bere_res_abwbewe::text = ''::text OR b.c_bere_res_abwbewe IS NULL THEN b.c_bere_res_autobewe
                            ELSE b.c_bere_res_abwbewe
                        END AS c_bez_max_katrel
                    FROM altlast_version1.obje o 
                    JOIN altlast_version1.vflz_current_v v ON v.obje_id=o.obje_id 
                    JOIN altlast_version1.bere b ON b.vflz_id=v.vflz_id
                    WHERE o.obje_id = objeid) AS foo
                JOIN altlast_version1.bere_cod_gs bcg ON bcg.bere_code=foo.c_bez_max_katrel 
                JOIN altlast_version1.cod c ON c.code=bcg.gs_code AND c.c_cli_id = gs_cli_id LOOP
        

        -- geschäfte entsprechend der Standortbewertung anlegen
        INSERT INTO altlast_version1.gs (h_gs_typ,c_gs_typ) VALUES (2002,rec.gs_code) RETURNING gs_id INTO gsid;
        -- mit objekt verknuepfen
        INSERT INTO altlast_version1.gs_obje (gs_id,obje_id,c_gs_obje_bez_art) VALUES (gsid, objeid, 6);

        RETURN gsid;
    END LOOP;
END;$$;


--
-- Name: report_finalize_gs(integer, date); Type: FUNCTION; Schema: altlast_version1; Owner: -
--

CREATE FUNCTION altlast_version1.report_finalize_gs(gsid integer, enddatum date) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    rec record;
BEGIN
        -- Schliesst die Geschäftserstellung ab.
        -- 

    SELECT INTO rec go.gs_id,v.obje_id, gs.c_gs_typ, 
            CASE
                WHEN b.c_bere_res_abwbewe::text = ''::text OR b.c_bere_res_abwbewe IS NULL THEN b.c_bere_res_autobewe
                ELSE b.c_bere_res_abwbewe
            END AS c_bez_max_katrel
            
            FROM altlast_version1.vflz_current_v v
            JOIN altlast_version1.bere b ON b.vflz_id=v.vflz_id
            JOIN altlast_version1.gs_obje go ON v.obje_id=go.obje_id
            JOIN altlast_version1.gs gs on go.gs_id=gs.gs_id
            WHERE go.gs_id=gsid;
            
        
    -- Bug 1166 : Im Rahmen der Erstellung des Hauptreports wird das Geschäft "Brief
    -- Nichteintrag" bei unbelasteten Standorten sogleich mit dem Versanddatum
    -- abgeschlossen, inkl. aller Teilgeschäfte
    -- + Bug 1534
    IF rec.c_bez_max_katrel='BLKR01' and rec.c_gs_typ='7' THEN
        UPDATE altlast_version1.gs SET end_datum_ist=enddatum, c_gs_status='50' WHERE gs_id=gsid;
        UPDATE altlast_version1.gss SET end_datum_ist=enddatum, c_gss_status='50' WHERE gs_id=gsid;
    END IF;
    
    -- bug 1534 : * Ersteintrag: alle Teilgeschäfte werden mit Reportdatum automatisch
    -- abgeschlossen [...]. Das Geschäft hat den Status in
    -- Bearbeitung, Startdatum = Reportdatum, Datum Fälligkeit = Startdatum + 37 Tage
    -- Anm. Nico: sicher GS "def. Eintrag in Kataster: Information Inhaber" gemeint
    IF rec.c_gs_typ = '5' THEN
        UPDATE altlast_version1.gs SET start_datum_ist=enddatum, end_datum_planung=enddatum+'37 days'::interval, c_gs_status='20' WHERE gs_id=gsid;
        UPDATE altlast_version1.gss SET end_datum_ist=enddatum, c_gss_status='50' WHERE gs_id=gsid;
    END IF;

    -- Bug 1534 : geänderter Eintrag: analog zum Nichteintrag werden alle Geschäfte und
    -- Teilgeschäfte mit Reportdatum automatisch abgeschlossen
    IF  rec.c_gs_typ='88' THEN
        UPDATE altlast_version1.gs SET end_datum_ist=enddatum, c_gs_status='50' WHERE gs_id=gsid;
        UPDATE altlast_version1.gss SET end_datum_ist=enddatum, c_gss_status='50' WHERE gs_id=gsid;
    END IF;
        

END;$$;


--
-- Name: report_validate_gs_creation(bigint); Type: FUNCTION; Schema: altlast_version1; Owner: -
--

CREATE FUNCTION altlast_version1.report_validate_gs_creation(poolid bigint) RETURNS SETOF text
    LANGUAGE plpgsql
    AS $$
DECLARE
    rec record;
    vorhanden text;
BEGIN

    FOR rec IN SELECT foo.obje_id, bcg.gs_code, c.bezeichnung
                FROM
                    (SELECT op.obje_id, 
                        CASE
                            WHEN b.c_bere_res_abwbewe::text = ''::text OR b.c_bere_res_abwbewe IS NULL THEN b.c_bere_res_autobewe
                            ELSE b.c_bere_res_abwbewe
                        END AS c_bez_max_katrel
                    FROM altlast_version1.obje_pool op 
                    JOIN altlast_version1.vflz_current_v v ON v.obje_id=op.obje_id 
                    JOIN altlast_version1.bere b ON b.vflz_id=v.vflz_id
                    WHERE op.pool_id = poolid) AS foo
                JOIN altlast_version1.bere_cod_gs bcg ON bcg.bere_code=foo.c_bez_max_katrel 
                JOIN altlast_version1.cod c ON c.code=bcg.gs_code AND c.c_cli_id = gs_cli_id LOOP
        
        SELECT v.vflz_combined_id_kt INTO vorhanden
            FROM altlast_version1.vflz_current_v v 
            JOIN altlast_version1.gs_obje go ON go.obje_id=v.obje_id 
            JOIN altlast_version1.gs gs ON gs.gs_id=go.gs_id 
            JOIN altlast_version1.obje_pool op ON op.obje_id=v.obje_id 
            WHERE gs.h_gs_typ=2002 AND gs.c_gs_typ=rec.gs_code AND go.obje_id=rec.obje_id;
        IF vorhanden IS NOT NULL THEN
            RETURN NEXT 'Standort '||vorhanden||' verfügt bereits über ein Geschäft des Typs '||rec.bezeichnung;
        END IF;
       
    END LOOP;
END;$$;


--
-- Name: rpt_vorlage(integer); Type: FUNCTION; Schema: altlast_version1; Owner: -
--

CREATE FUNCTION altlast_version1.rpt_vorlage(vflzid integer) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
    rec record;
    rpt text;
BEGIN

/*
SELECT vflz_id,altlast.rpt_vorlage(vflz_id) FROM altlast_version1.vflz 
--WHERE altlast_version1.rpt_vorlage(vflz_id)='missing' 
LIMIT 100;
*/
  SELECT v.c_vflz_vftyp,v.c_vflz_bearbstand,b.c_bere_res_abwbewe INTO rec FROM altlast_version1.vflz_current_v v LEFT JOIN altlast_version1.bere b USING(vflz_id) WHERE v.vflz_id=vflzid;

  IF rec IS NULL THEN
    RAISE EXCEPTION 'VFLZ_ID % unknown',vflzid;
  END IF;

  SELECT INTO rpt altlast_version1.rpt_vorlage(rec.c_vflz_vftyp,rec.c_vflz_bearbstand,rec.c_bere_res_abwbewe);    

        RETURN rpt;
END;$$;


