CREATE FUNCTION altlast_version1.rpt_vorlage(typ text, bearbstand text, bewe text) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
    rpt text;
BEGIN
  SELECT vorlage INTO rpt FROM altlast_version1.rpt_variants WHERE c_typ=typ AND c_bearbstand=bearbstand AND c_bewe=bewe;

  IF rpt IS NULL THEN
    rpt = 'Platzhalter.ott';
  ENd IF;
    

        RETURN rpt;
END;$$;


