--
-- Name: scaleextent(public.geometry, double precision, double precision); Type: FUNCTION; Schema: altlast_version1; Owner: -
--

CREATE FUNCTION altlast_version1.scaleextent(geom public.geometry, targetwidth_cm double precision, targetheight_cm double precision) RETURNS public.geometry
    LANGUAGE plpgsql
    AS $$
DECLARE
  exnt geometry;
BEGIN

  exnt := altlast_version1.scaleextent(geom, targetwidth_cm,targetheight_cm, altlast_version1.bestscalefactor(geom, targetwidth_cm ,targetheight_cm));
  RETURN exnt;
END
$$;


--
-- Name: FUNCTION scaleextent(geom public.geometry, targetwidth_cm double precision, targetheight_cm double precision); Type: COMMENT; Schema: altlast_version1; Owner: -
--

COMMENT ON FUNCTION altlast_version1.scaleextent(geom public.geometry, targetwidth_cm double precision, targetheight_cm double precision) IS 'Calculate the best extent for gem when displayed at a given scalefactor';


--
-- Name: scaleextent(public.geometry, double precision, double precision, integer); Type: FUNCTION; Schema: altlast_version1; Owner: -
--

CREATE FUNCTION altlast_version1.scaleextent(geom public.geometry, targetwidth_cm double precision, targetheight_cm double precision, scalefactor integer) RETURNS public.geometry
    LANGUAGE plpgsql
    AS $$
DECLARE
  m_x double precision; -- multiplier in x direction for scaling
  m_y double precision; -- multiplier in y direction for scaling
  gx box3d;
  gy box3d;
  exnt geometry;
BEGIN
  m_x := (scalefactor*(targetwidth_cm/100.0)/2);
  m_y := (scalefactor*(targetheight_cm/100.0)/2);

  gx := ST_Expand(st_centroid(geom),m_x)::box3d;
  gy := ST_Expand(st_centroid(geom),m_y)::box3d;

  exnt := ST_setSRID(ST_MakeBox3d(ST_MakePoint(ST_XMin(gx),ST_YMin(gy),0),ST_MakePoint(ST_XMax(gx),ST_YMax(gy),0))::geometry,srid(geom));

  RETURN exnt;
END
$$;


--
-- Name: FUNCTION scaleextent(geom public.geometry, targetwidth_cm double precision, targetheight_cm double precision, scalefactor integer); Type: COMMENT; Schema: altlast_version1; Owner: -
--

COMMENT ON FUNCTION altlast_version1.scaleextent(geom public.geometry, targetwidth_cm double precision, targetheight_cm double precision, scalefactor integer) IS 'Calculate the best extent for gem when displayed at a given scalefactor';


--
-- Name: setnull(); Type: FUNCTION; Schema: altlast_version1; Owner: -
--

CREATE FUNCTION altlast_version1.setnull() RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  rec RECORD;
  sql character varying;
BEGIN
      -- get all columns and their types
  FOR rec in SELECT a.attname,t.typname,c.relname FROM pg_catalog.pg_namespace n INNER JOIN pg_catalog.pg_class c ON n.oid=c.relnamespace INNER JOIN pg_catalog.pg_attribute a ON c.oid=a.attrelid INNER JOIN pg_catalog.pg_type t ON t.oid = a.atttypid WHERE n.nspname='altlast' AND c.relkind='r'::char ORDER BY c.relname,a.attname LOOP

    IF (rec.attname <> (rec.relname || '_id')) AND (rec.typname='integer' OR rec.typname='int4' OR rec.typname='int2' OR rec.typname='int8') THEN
      sql := 'UPDATE altlast_version1.' || rec.relname || ' SET ' || rec.attname || '=NULL WHERE ' || rec.attname || '=-9999;';
      BEGIN
                EXECUTE sql; 
      EXCEPTION WHEN not_null_violation THEN
      END;
    END IF;
    
    IF rec.typname='date' THEN
      sql := 'UPDATE altlast_version1.' || rec.relname || ' SET ' || rec.attname || '=NULL WHERE ' || rec.attname || ' BETWEEN ''1899-12-01''::date AND ''1899-12-30''::date;';
            BEGIN
                EXECUTE sql ;
            EXCEPTION WHEN not_null_violation THEN
      END;
    END IF;

    IF rec.typname='varchar' THEN
      sql := 'UPDATE altlast_version1.' || rec.relname || ' SET ' || rec.attname || '=NULL WHERE ' || rec.attname || '='''';';
      BEGIN
        EXECUTE sql ;
      EXCEPTION WHEN not_null_violation THEN
      END;
    END IF;   

  END LOOP;
END;  

$$;


--
-- Name: FUNCTION setnull(); Type: COMMENT; Schema: altlast_version1; Owner: -
--

COMMENT ON FUNCTION altlast_version1.setnull() IS 'Funktion setzt die Platzhalter für NULL-Werte, wie sie der Altlast4PC-Client generiert, auf echte NULL-Eintraege';


