--
-- Name: subj_duplicates_find(integer, integer); Type: FUNCTION; Schema: altlast_version1; Owner: -
--

CREATE FUNCTION altlast_version1.subj_duplicates_find(subjid integer, lvl integer) RETURNS SETOF integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    rec record;
    adrcnt integer;
BEGIN

    -- exception wenn irgendwo mehr als eine Address zu einem subjekt erfasst
    SELECT max(foo.cnt) INTO adrcnt FROM (SELECT count(*) as cnt FROM altlast_version1.subj s JOIN altlast_version1.subj_adr sa ON sa.subj_id=s.subj_id JOIN altlast_version1.adr a on a.adr_id=sa.adr_id GROUP BY s.subj_id) AS foo;
    IF adrcnt>1 THEN
        RAISE EXCEPTION 'SHOWMSG Mehr als eine Adresse pro Person wird momentan hier nicht unterstützt.';
    END IF;


    IF lvl=1 THEN
                
        RETURN QUERY SELECT  DISTINCT s.subj_id AS s_subj_id
                FROM (SELECT DISTINCT subj_id,
                    regexp_split_to_table(altlast.concat_subj(name,vorname,taetigkeit),E'[-_\\/\)\(\ \"\,]') AS match FROM altlast_version1.subj) m 
                JOIN  altlast_version1.subj s ON s.name LIKE '%'||m.match||'%' 
                JOIN altlast_version1.subj_adr sa1 ON sa1.subj_id=s.subj_id 
                JOIN altlast_version1.adr a1 on a1.adr_id=sa1.adr_id 
                JOIN altlast_version1.subj_adr sa2 ON sa2.subj_id=m.subj_id 
                JOIN altlast_version1.adr a2 on a2.adr_id=sa2.adr_id 
                WHERE m.subj_id<>s.subj_id 
                    AND m.match IS NOT NULL AND LENGTH(TRIM(m.match))>3
                    AND UPPER(m.match) NOT IN (SELECT UPPER(find) FROM altlast_version1.qs_token_mappings) 
                    AND m.subj_id=subjid 
                    AND ((a1.ort LIKE '%'||m.match||'%') OR (a2.postleitzahl::text LIKE '%'||m.match||'%'));
                
    ELSIF lvl=2 THEN

        RETURN QUERY SELECT  s.subj_id AS s_subj_id
                FROM (SELECT DISTINCT subj_id,
                    regexp_split_to_table(altlast.concat_subj(name,vorname,taetigkeit),E'[-_\\/\)\(\ \"\,]') AS match FROM altlast_version1.subj) m 
                JOIN  altlast_version1.subj s ON s.name LIKE '%'||m.match||'%'
                WHERE m.subj_id<>s.subj_id 
                    AND m.match IS NOT NULL AND LENGTH(TRIM(m.match))>3
                    AND UPPER(m.match) NOT IN (SELECT UPPER(find) FROM altlast_version1.qs_token_mappings) 
                    AND m.subj_id=subjid GROUP BY s.name,s.subj_id;
                
    ELSE
    
        RETURN QUERY SELECT  s.subj_id AS s_subj_id
                FROM (SELECT DISTINCT subj_id,
                    regexp_split_to_table(altlast.qs_token_map(altlast.concat_subj(name,vorname,taetigkeit),'subj'),E'[-_\\/\)\(\ \"\,]') AS match FROM altlast_version1.subj) m 
                JOIN  altlast_version1.subj s ON altlast_version1.qs_token_map(s.name,'subj') LIKE '%'||m.match||'%' 
                WHERE m.subj_id<>s.subj_id 
                    AND m.match IS NOT NULL AND LENGTH(TRIM(m.match))>3
                    AND UPPER(m.match) NOT IN (SELECT UPPER(find) FROM altlast_version1.qs_token_mappings) 
                    AND m.subj_id=subjid GROUP BY s.name,s.subj_id;
                
    END IF;
    
    RETURN;
END;$$;


--
-- Name: FUNCTION subj_duplicates_find(subjid integer, lvl integer); Type: COMMENT; Schema: altlast_version1; Owner: -
--

COMMENT ON FUNCTION altlast_version1.subj_duplicates_find(subjid integer, lvl integer) IS 'findet mögliche Duplikate eines Subjekts und wendet unterschiedliche Schärfe bei der Suche an';


--
-- Name: subj_duplicates_remove(integer, integer[]); Type: FUNCTION; Schema: altlast_version1; Owner: -
--

CREATE FUNCTION altlast_version1.subj_duplicates_remove(subj_ref integer, subj_dups integer[]) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    subjdup integer;
    asql text;
    rec record;
    isben boolean;
BEGIN
    
    FOR subjdup IN SELECT subj_dups[i] FROM generate_series(array_lower(subj_dups,1), array_upper(subj_dups,1)) AS i LOOP
    
        SELECT count(*)>0 INTO isben FROM altlast_version1.ben WHERE subj_id=subjdup;
        IF isben THEN
            RAISE EXCEPTION 'Systembenutzer können nicht entfernt werden.';
        END IF;
    
        IF subjdup != subj_ref THEN
            -- verknüpfungen mit subj_dups die auf das gleiche geschäft mit dem gleichen beziehungstyp verweisen entfernen
            FOR rec IN SELECT gs2.subj_id,gs2.c_gs_subj_bez_art,gs2.gs_id  
                    FROM altlast_version1.gs_subj gs1 
                    JOIN altlast_version1.gs_subj gs2 ON gs1.gs_id=gs2.gs_id AND gs1.c_gs_subj_bez_art=gs2.c_gs_subj_bez_art
                    WHERE gs1.subj_id=subj_ref AND gs2.subj_id=subjdup LOOP
                DELETE FROM altlast_version1.gs_subj m  WHERE m.gs_id=rec.gs_id AND m.subj_id=rec.subj_id AND m.c_gs_subj_bez_art=rec.c_gs_subj_bez_art;
            END LOOP;
            
            -- verknüpfungen mit subj_dups die auf das gleiche obje mit dem gleichen beziehungstyp verweisen entfernen
            FOR rec IN SELECT so2.subj_id,so2.c_subj_obje_bez_art,so2.obje_id  
                        FROM altlast_version1.subj_obje so1 
                        JOIN altlast_version1.subj_obje so2 ON so1.obje_id=so2.obje_id AND so1.c_subj_obje_bez_art=so2.c_subj_obje_bez_art
                        WHERE so1.subj_id=subj_ref AND so2.subj_id=subjdup LOOP
                DELETE FROM altlast_version1.subj_obje m WHERE m.subj_id=rec.subj_id AND m.obje_id=rec.obje_id AND m.c_subj_obje_bez_art=rec.c_subj_obje_bez_art;
            END LOOP;
                
            -- verknüpfungen mit subj_dups die auf das gleiche teilgeschäft mit dem gleichen beziehungstyp verweisen entfernen
            FOR rec IN SELECT gs2.subj_id,gs2.c_gss_subj_bez_art,gs2.gs_id,gs2.gss_id  
                    FROM altlast_version1.gss_subj gs1 
                    JOIN altlast_version1.gss_subj gs2 ON gs1.gs_id=gs2.gs_id AND gs1.c_gss_subj_bez_art=gs2.c_gss_subj_bez_art AND gs1.gss_id=gs2.gss_id
                    WHERE gs1.subj_id=subj_ref AND gs2.subj_id=subjdup LOOP
                DELETE FROM altlast_version1.gss_subj m WHERE m.gs_id=rec.gs_id AND m.subj_id=rec.subj_id AND m.c_gss_subj_bez_art=rec.c_gss_subj_bez_art AND m.gss_id=rec.gss_id;
                
              
            END LOOP;
        
        /*
                -- verknüpfungen mit subj_dups die auf das gleiche geschäft mit dem gleichen beziehungstyp verweisen entfernen
            DELETE FROM altlast_version1.gs_subj m USING (SELECT gs2.subj_id,gs2.c_gs_subj_bez_art,gs2.gs_id  
                    FROM altlast_version1.gs_subj gs1 
                    JOIN altlast_version1.gs_subj gs2 ON gs1.gs_id=gs2.gs_id AND gs1.c_gs_subj_bez_art=gs2.c_gs_subj_bez_art
                    WHERE gs1.subj_id=subj_ref AND gs2.subj_id=subjdup) AS foo
                WHERE m.gs_id=foo.gs_id AND m.subj_id=foo.subj_id AND m.c_gs_subj_bez_art=foo.c_gs_subj_bez_art;
            
            -- verknüpfungen mit subj_dups die auf das gleiche obje mit dem gleichen beziehungstyp verweisen entfernen
            DELETE FROM altlast_version1.subj_obje m USING (SELECT so2.subj_id,so2.c_subj_obje_bez_art,so2.obje_id  
                    FROM altlast_version1.subj_obje so1 
                    JOIN altlast_version1.subj_obje so2 ON so1.obje_id=so2.obje_id AND so1.c_subj_obje_bez_art=so2.c_subj_obje_bez_art
                    WHERE so1.subj_id=subj_ref AND so2.subj_id=subjdup) AS foo
                WHERE m.subj_id=foo.subj_id AND m.obje_id=foo.obje_id AND m.c_subj_obje_bez_art=foo.c_subj_obje_bez_art;
                
            -- verknüpfungen mit subj_dups die auf das gleiche teilgeschäft mit dem gleichen beziehungstyp verweisen entfernen
            DELETE FROM altlast_version1.gss_subj m USING (SELECT gs2.subj_id,gs2.c_gss_subj_bez_art,gs2.gs_id,gs2.gss_id  
                    FROM altlast_version1.gss_subj gs1 
                    JOIN altlast_version1.gss_subj gs2 ON gs1.gs_id=gs2.gs_id AND gs1.c_gss_subj_bez_art=gs2.c_gss_subj_bez_art AND gs1.gss_id=gs2.gss_id
                    WHERE gs1.subj_id=subj_ref AND gs2.subj_id=subjdup) AS foo
                WH
        */
        
            FOR asql IN SELECT 'UPDATE ' ||c.table_schema||'.'||c.table_name||' SET '||c.column_name||'='||subj_ref||' WHERE '||c.column_name||'='||subjdup||';' AS stmt FROM information_schema.columns c
                            JOIN information_schema.tables t ON t.table_name=c.table_name AND t.table_schema=c.table_schema
                            WHERE c.table_schema='altlast' 
                            AND c.column_name = 'subj_id'
                            AND t.table_type = 'BASE TABLE'
                            AND t.table_name NOT IN ('subj_kennung_v','gs_v','subj_v','subj','subj_adr','pers','tele','ben','ben_grp','atsu','imp_subj') ORDER BY length(c.table_name) LOOP
                            
                            -- ORDER BY length(c.table_name) ist ein workaround damit auf andere tabellen aufbauende tabellen als letztes kommen. primär für subj_obje_grun
                           
                --RAISE NOTICE '%',asql;
                BEGIN          
                    EXECUTE asql;
                EXCEPTION WHEN unique_violation THEN
                END;
                            
            END LOOP;

            DELETE FROM altlast_version1.tele WHERE subj_id=subjdup;
            DELETE FROM altlast_version1.pers WHERE subj_id=subjdup;
            DELETE FROM altlast_version1.adr WHERE adr_id IN (SELECT adr_id FROM altlast_version1.subj_adr WHERE subj_id=subjdup);
            DELETE FROM altlast_version1.subj WHERE subj_id=subjdup;
        END IF;
    END LOOP;

END;$$;


--
-- Name: FUNCTION subj_duplicates_remove(subj_ref integer, subj_dups integer[]); Type: COMMENT; Schema: altlast_version1; Owner: -
--

COMMENT ON FUNCTION altlast_version1.subj_duplicates_remove(subj_ref integer, subj_dups integer[]) IS 'setzt alle Referenzen auf Subjekte, die durch die in subj_dups angegebenen Werte von subj_id definiert sind, um auf das in subj_ref definierte Subjekt -> löscht alle Einträge in subj für die in subj_dups definierten Einträge';


--
-- Name: updateobjekoordinaten(integer, public.geometry); Type: FUNCTION; Schema: altlast_version1; Owner: -
--

CREATE FUNCTION altlast_version1.updateobjekoordinaten(integer, public.geometry) RETURNS public.geometry
    LANGUAGE plpgsql
    AS $_$
DECLARE
  obje_id ALIAS FOR $1;
  geom ALIAS FOR $2;
  rec RECORD;
BEGIN
  
  RETURN altlast_version1.UpdateOBJEKoordinaten(int4,x(geom),y(geom));

END;$_$;


--
-- Name: updateobjekoordinaten(integer, integer, integer); Type: FUNCTION; Schema: altlast_version1; Owner: -
--

CREATE FUNCTION altlast_version1.updateobjekoordinaten(integer, integer, integer) RETURNS public.geometry
    LANGUAGE plpgsql
    AS $_$
DECLARE
  obje_id ALIAS FOR $1;
  x ALIAS FOR $2;
  y ALIAS FOR $3;
  rec record;
  res geometry; 
BEGIN
  
  SELECT INTO rec wkb_geometry FROM altlast_version1.obje o INNER JOIN altlast_version1.app_obje ao ON o.obje_id=ao.obje_id INNER JOIN altlast_version1.vflz v ON ao.app_obje_id=v.app_obje_id INNER JOIN altlast_version1.vflgeo g ON v.vflz_id=g.vflz_id;
  
  IF rec.wkb_geometry IS NOT NULL THEN
    res := centroid(rec.wkb_geometry);
  ELSE
    res := GeomFromText('POINT('||x||' '||y||')',-1);
  END IF;
  
  RETURN res;
  
END;$_$;


--
-- Name: width(public.geometry); Type: FUNCTION; Schema: altlast_version1; Owner: -
--

CREATE FUNCTION altlast_version1.width(geom public.geometry) RETURNS double precision
    LANGUAGE plpgsql
    AS $$
DECLARE
  this_srid integer;
  bx box3d;
  dist double precision;
BEGIN
  SELECT srid(geom) INTO this_srid;
  SELECT ST_Extent(geom)::box3d INTO bx;
  SELECT ST_Distance( 
    SetSRID(ST_MakePoint(ST_XMin(bx),ST_YMin(bx))::geometry,this_srid), 
    SetSRID(ST_MakePoint(ST_XMax(bx),ST_YMin(bx))::geometry,this_srid))
    INTO dist;
  RETURN dist;
END
$$;


--
-- Name: FUNCTION width(geom public.geometry); Type: COMMENT; Schema: altlast_version1; Owner: -
--

COMMENT ON FUNCTION altlast_version1.width(geom public.geometry) IS 'Calculate the width of a geometry in projection units.';


--
-- Name: zeitraum_bis(date, date, text); Type: FUNCTION; Schema: altlast_version1; Owner: -
--

CREATE FUNCTION altlast_version1.zeitraum_bis(acc date, indate date, ininfg text) RETURNS date
    LANGUAGE plpgsql
    AS $$
  BEGIN

    IF indate IS NULL AND ininfg='01' THEN
      RETURN '2999-01-01'::date;
    ELSE
      IF indate IS NULL THEN
        RETURN acc;
      ELSE
        IF acc<indate THEN
          RETURN indate;
        ELSE
          RETURN acc;
        END IF;
      END IF;      
    END IF;

  END;
$$;


--
-- Name: zeitraum_unfall(text, date, date); Type: FUNCTION; Schema: altlast_version1; Owner: -
--

CREATE FUNCTION altlast_version1.zeitraum_unfall(acc text, invon date, inbis date) RETURNS text
    LANGUAGE plpgsql
    AS $$
  DECLARE
    zeit text;
  BEGIN
    IF invon IS NULL AND inbis IS NULL THEN
      zeit:=acc;
    ELSE
      IF invon IS NOT NULL AND inbis IS NOT NULL THEN
        IF (inbis>invon) THEN
          zeit:=TO_CHAR( inbis,'DD.MM.YYYY')::text;
        ELSE
          zeit:=TO_CHAR( invon,'DD.MM.YYYY')::text;
        END IF;
      ELSE
        zeit:=TO_CHAR( COALESCE(invon,inbis),'DD.MM.YYYY')::text;
      END IF;
    END IF;
    IF acc IS NULL OR acc='' THEN
      RETURN zeit;
    ELSE
      RETURN acc||', '||zeit;
    END IF;
  END;
$$;


--
-- Name: zeitraum_von(date, date); Type: FUNCTION; Schema: altlast_version1; Owner: -
--

CREATE FUNCTION altlast_version1.zeitraum_von(acc date, indate date) RETURNS date
    LANGUAGE plpgsql
    AS $$
  BEGIN
    IF acc IS NULL THEN
      RETURN indate::date;
    ELSE
      IF indate IS NULL OR acc<indate THEN
        RETURN acc;
      ELSE
        RETURN indate;
      END IF;
    END IF;
  END;
$$;


--
-- Name: bafu_update_data(); Type: FUNCTION; Schema: altlast_wfs; Owner: -
--

CREATE FUNCTION altlast_wfs.bafu_update_data() RETURNS void
    LANGUAGE plpgsql
    AS $$
declare
    this_locale text;
begin
    raise notice 're-creating contents of altlast_wfs.bafu table';
    truncate altlast_wfs.bafu;
    perform setval('altlast_wfs.bafu_mapserver_id', 1); -- reset the sequence to prevent growth of this key.

    for this_locale in select unnest(array['de','fr','it']) as locale 
                loop
        insert into altlast_wfs.bafu (
              vflz_id,
              staonr,
              staobezeichnung,
              staotyp,
              vollzug,
              gemeinde_bfs,
              gemeinde,
              kanton,
              x_koordinate ,
              y_koordinate ,
              wkb_geometry ,
              betrieb_branchen ,
              betrieb_zeitraum ,
              ablag_zeitraum ,
              ablag_gesamtvol  ,
              ablag_stoffe ,
              unfall_zeitpunkt ,
              unfall_stoffe ,
              vorkommnisse ,
              beurteilung ,
              umweltschutzmassnahmen ,
              gefaehrdete_umweltbereiche ,
              festgestellte_einwirkungen ,
              gewaesserschutzbereich ,
              gewaesserschutzzone ,
              ersteintrag_datum ,
              publikation_datum ,
              untersuchungsstand ,
              sanierungsziele ,
              priorisierung_sanierung ,
              priorisierung_untersuchung,
              locale
            )
         select
            v.vflz_id,
            v.vflz_combined_id_kt as staonr,
            v.bezeichnung as staobezeichnung,
            altlast.t(altlast.msgid_code(v.h_vflz_vftyp, v.c_vflz_vftyp), this_locale) as staotyp,
            org.bezeichnung as vollzug,
            v.h_gem_id as gemeinde_bfs,
            h_gem.gemeinde,
            h_gem.c_kanton as kanton,
            v.x_koordinate,
            v.y_koordinate,
            case when st_geometrytype(vflgeo.wkb_geometry) = 'ST_Point' then st_buffer(vflgeo.wkb_geometry, 10) else vflgeo.wkb_geometry end as wkb_geometry,
            betrieb_props.betrieb_branchen,
            betrieb_props.betrieb_zeitraum,
            ablag1_props.ablag_zeitraum,
            ablag1_props.ablag_gesamtvol,
            ablag2_props.ablag_stoffe,
            unfall_props.unfall_zeitpunkt,
            unfall_props.unfall_stoffe,
            vorkommnisse.vorkommnisse,
            altlast.t(altlast.msgid_code(bere.h_bere_res_abwbewe, bere.c_bere_res_abwbewe), this_locale) as beurteilung,
            umweltschutzmassnahmen.umweltschutzmassnahmen,
            umweltbereiche.gefaehrdete_umweltbereiche,
            umweltbereiche.festgestellte_einwirkungen,
            altlast.t(altlast.msgid_code(v.h_vflz_gws_bereich, v.c_vflz_gws_bereich), this_locale) as gewaesserschutzbereich,
            altlast.t(altlast.msgid_code(v.h_vflz_gws_zone, v.c_vflz_gws_zone), this_locale) as gewaesserschutzzone,
            ersteintrag.ersteintrag_datum,
            to_char(vip.dat_latest_published, 'DD.MM.YYYY')::text as publikation_datum,
            altlast.t(altlast.msgid_code(v.h_vflz_unterstand, v.c_vflz_unterstand), this_locale) as untersuchungsstand,
            sanierung.sanierungsziele,
            bere.bere_prio_sanier as priorisierung_sanierung,
            bere.bere_prio_untersuch as priorisierung_untersuchung,
            this_locale as locale

        from altlast.vflz v
        join altlast.vflnr on (vflnr.vflz_id = v.vflz_id) and vflnr.aktiv = true
        join altlast.vflz_is_published_v vip on (vip.vflz_id = v.vflz_id) and vip.is_latest_published
        join altlast.bere_v bere on bere.vflz_id = v.vflz_id and bere.kbs
        join altlast.org on org.org_id = vflnr.org_id
        join altlast.vflgeo on v.vflz_id = vflgeo.vflz_id

        -- restrict using the org configured in a4w
        join altlast_admin.setting stng on stng.value = vflnr.org_id::text
        join altlast_admin.setitem sit on sit.setitem_id = stng.setitem_id and sit.key in ('org', 'astra')

        left join altlast.h_gem on h_gem.h_gem_id = v.h_gem_id
        left join (
            select intb.vflz_id,
                array_to_string(array_agg(ibv.intb_bran_formatted), E'\n') as betrieb_branchen,
                coalesce(to_char(min(intb.intb_vonbetrieb)::date, 'DD.MM.YYYY')::text, altlast.t('unbekannt', this_locale)) || ' ' || altlast.t('bis', this_locale) || ' ' || coalesce(to_char(max(intb.intb_bisbetrieb)::date, 'DD.MM.YYYY')::text, altlast.t('heute', this_locale)) as betrieb_zeitraum
            from altlast.intb
            join altlast.intb_branche_v ibv on ibv.intb_id = intb.intb_id
            group by intb.vflz_id
        ) betrieb_props on betrieb_props.vflz_id = v.vflz_id and v.c_vflz_vftyp = '02'

        left join (
            select inta.vflz_id,
                coalesce(to_char(min(inta.inta_ablag_von)::date, 'DD.MM.YYYY')::text, altlast.t('unbekannt', this_locale)) || ' ' || altlast.t('bis', this_locale) || ' ' || (case
                        when bool_or(inta.zeitraum_bisheute) then altlast.t('heute', this_locale)
                        else coalesce(to_char(max(inta.inta_ablag_bis)::date, 'DD.MM.YYYY')::text, altlast.t('unbekannt', this_locale))
                      end) as ablag_zeitraum,
                sum(inta.inta_vol_kompartiment) as ablag_gesamtvol
            from altlast.inta
            group by inta.vflz_id
        ) ablag1_props on ablag1_props.vflz_id = v.vflz_id and v.c_vflz_vftyp = '01'

        left join (
            select inta.vflz_id,
                array_to_string(array_agg(altlast.t(altlast.msgid_code(kksk.h_kksk_stoffkl, kksk.c_kksk_stoffkl), this_locale) || coalesce(': ' || altlast.t(altlast.msgid_code(kksg.h_kksg_stoffgrp, kksg.c_kksg_stoffgrp), this_locale), '')), E'\n') as ablag_stoffe
            
	        from altlast.inta
	        left join altlast.kksk on kksk.inta_id = inta.inta_id
	        left join altlast.kksg on kksk.kksk_id = kksg.kksk_id
	        group by inta.vflz_id
            
        ) ablag2_props on ablag2_props.vflz_id = v.vflz_id and v.c_vflz_vftyp = '01'

        left join (
            select intu.vflz_id,
                altlast.commacat_all(case when intu.zeitraum_jahr then to_char(intu_unfallvon, 'YYYY') else to_char(intu_unfallvon, 'DD.MM.YYYY') end) as unfall_zeitpunkt,
                array_to_string(array_agg(altlast.t(altlast.msgid_code(inum.h_inum_stoffe, inum.c_inum_stoffe), this_locale) || coalesce(': ' || altlast.t('Restmenge',this_locale) || ' ' || nullif(inum_stoffmng, 0)::text || ' ' || altlast.t('liter', this_locale), '')), E'\n') as unfall_stoffe
            from altlast.intu
            join altlast.inum on inum.intu_id = intu.intu_id
            group by intu.vflz_id
        ) unfall_props on unfall_props.vflz_id = v.vflz_id and v.c_vflz_vftyp = '03'

        left join (
            select veen.vflz_id,
                array_to_string(array_agg(coalesce(altlast.t(altlast.msgid_code(veen.h_veen_natuerlich, veen.c_veen_natuerlich), this_locale) || ': ', '') || coalesce(bem.bem, '')), E'\n') as vorkommnisse
            from altlast.veen
            left join altlast.bem_v bem on bem.key_value = veen.veen_id and bem.public and bem.bemgrp = 'veen.veen_id'
            group by veen.vflz_id
        ) vorkommnisse on vorkommnisse.vflz_id = v.vflz_id

        left join (
            select mass.vflz_id,
                 array_to_string(array_agg(altlast.t(altlast.msgid_code(mass.h_massnahme, mass.c_massnahme), this_locale) || coalesce(': ' || altlast.t('erledigt am', this_locale) || ' ' || to_char(mass.dat_massnahme, 'DD.MM.YYYY')::text, '')), E'\n') as umweltschutzmassnahmen
            from altlast.mass
            group by mass.vflz_id
        ) umweltschutzmassnahmen on umweltschutzmassnahmen.vflz_id = v.vflz_id

        left join (
            select vfus.vflz_id,
                array_to_string(array_agg(altlast.t(altlast.msgid_code(vfus.h_vfus_art_schaden, vfus.c_vfus_art_schaden), this_locale)), E'\n') as gefaehrdete_umweltbereiche,
                array_to_string(array_agg(altlast.t(altlast.msgid_code(vfus.h_vfus_schaeden, vfus.c_vfus_schaeden), this_locale)), E'\n') as festgestellte_einwirkungen
            from altlast.vfus
            group by vfus.vflz_id
        ) umweltbereiche on umweltbereiche.vflz_id = v.vflz_id

        join (
            select vflz.vfl_id,
                to_char(min(dat_publizieren)::date, 'DD.MM.YYYY')::text as ersteintrag_datum
            from altlast.vflz
            where vflz.publizieren
            group by vflz.vfl_id
        ) ersteintrag on ersteintrag.vfl_id = v.vfl_id

        left join (
            select sani.vflz_id,
                array_to_string(array_agg(altlast.t(altlast.msgid_code(sani.h_saniziel, sani.c_saniziel), this_locale)), E'\n') as sanierungsziele
            from altlast.sani
            group by sani.vflz_id
        ) sanierung on sanierung.vflz_id = v.vflz_id

        where vflnr.aktiv
        ;

    end loop;
end
$$;


