--
-- Name: merge_gemeinden(integer, integer); Type: FUNCTION; Schema: altlast_wfs; Owner: -
--

CREATE FUNCTION altlast_wfs.merge_gemeinden(bfsnr1 integer, bfsnr2 integer) RETURNS void
    LANGUAGE plpgsql STRICT
    AS $$
BEGIN
-- Merge 2 adjacent Gemeinden into the first one (Method of delete and insert)
EXECUTE '
INSERT INTO altlast_wfs.manual_edit_gemeinden(
  country,
  bfsnr,
  kantonsnr,
  bezirksnr,
  gemname,
  geom,
  perform_action
)
SELECT
  country,
  bfsnr,
  kantonsnr,
  bezirksnr,
  gemname,
  the_geom,
  ''delete''
FROM
  altlast_wfs.gemeinden
WHERE
  bfsnr = '||bfsnr1||' OR
  bfsnr = '||bfsnr2||';
';

EXECUTE '
INSERT INTO altlast_wfs.manual_edit_gemeinden(
  country,
  bfsnr,
  kantonsnr,
  bezirksnr,
  gemname,
  geom,
  perform_action
)
SELECT
  r1.country,
  r1.bfsnr,
  r1.kantonsnr,
  r1.bezirksnr,
  r1.gemname,
  ST_Multi((ST_Dump(ST_Union(r1.the_geom, r2.the_geom))).geom),
  ''insert''
FROM
  altlast_wfs.gemeinden r1,
  altlast_wfs.gemeinden r2
WHERE
  r1.bfsnr = '||bfsnr1||' AND
  r2.bfsnr = '||bfsnr2||';
';

RAISE NOTICE 'ADDED RECORDS IN altlast_wfs.manual_edit_gemeinden';
END
$$;


--
-- Name: FUNCTION merge_gemeinden(bfsnr1 integer, bfsnr2 integer); Type: COMMENT; Schema: altlast_wfs; Owner: -
--

COMMENT ON FUNCTION altlast_wfs.merge_gemeinden(bfsnr1 integer, bfsnr2 integer) IS 'Merge 2 adjacent Gemeinden into the first one (Method of delete and insert) and insert the result into altlast_wfs.manual_edit_gemeinden';


--
-- Name: merge_ortschaften(integer, text, integer, text); Type: FUNCTION; Schema: altlast_wfs; Owner: -
--

CREATE FUNCTION altlast_wfs.merge_ortschaften(plz1 integer, ortschaft1 text, plz2 integer, ortschaft2 text) RETURNS void
    LANGUAGE plpgsql STRICT
    AS $$
BEGIN
-- Merge 2 adjacent Ortschaften into the first one (Method of delete and insert)
EXECUTE '
INSERT INTO altlast_wfs.manual_edit_ortschaften(
  plz,
  ortschaft,
  geom,
  perform_action
)
SELECT
  plz,
  ortschaft,
  wkb_geometry,
  ''delete''
FROM
  altlast_wfs.ortschaften
WHERE
  (plz = '||plz1||' AND ortschaft = '''||ortschaft1||''') OR
  (plz = '||plz2||' AND ortschaft = '''||ortschaft2||''');
';

EXECUTE '
INSERT INTO altlast_wfs.manual_edit_ortschaften(
  plz,
  ortschaft,
  geom,
  perform_action
)
SELECT
  r1.plz,
  r1.ortschaft,
  ST_Multi((ST_Dump(ST_Union(r1.wkb_geometry, r2.wkb_geometry))).geom),
  ''insert''
FROM
  altlast_wfs.ortschaften r1,
  altlast_wfs.ortschaften r2
WHERE
  (r1.plz = '||plz1||' AND r1.ortschaft = '''||ortschaft1||''') AND
  (r2.plz = '||plz2||' AND r2.ortschaft = '''||ortschaft2||''');
';

RAISE NOTICE 'ADDED RECORDS IN altlast_wfs.manual_edit_ortschaften';
END
$$;


