--
-- Name: pg_append_comment(text, text, text); Type: FUNCTION; Schema: altlast_wfs; Owner: -
--

CREATE FUNCTION altlast_wfs.pg_append_comment(p_table_schema text, p_table_name text, p_comment text) RETURNS void
    LANGUAGE plpgsql STRICT
    AS $$
declare 
    existing_comment text;
begin

    select description into existing_comment
        from pg_class pc
        join pg_namespace pns on pc.relnamespace = pns.oid
        join pg_description pd on pc.oid = pd.objoid
        where pc.relname=p_table_name and pns.nspname=p_table_schema;

    --- will currently only work for tables 
    execute 'comment on table '||quote_ident(p_table_schema)||'.'||quote_ident(p_table_name)||
        ' is '||quote_literal(coalesce(existing_comment, '') || p_comment)||';';
end
$$;


--
-- Name: FUNCTION pg_append_comment(p_table_schema text, p_table_name text, p_comment text); Type: COMMENT; Schema: altlast_wfs; Owner: -
--

COMMENT ON FUNCTION altlast_wfs.pg_append_comment(p_table_schema text, p_table_name text, p_comment text) IS 'Append a string to a comment on a a relation';


