-- Name: h_gem; Type: TABLE; Schema: altlast; Owner: -
--

CREATE TABLE altlast.h_gem (
    h_gem_id integer NOT NULL,
    h_be_id integer,
    bfs_nummer smallint,
    gemeinde_id smallint,
    gemeinde character varying(100),
    c_kanton character varying(8),
