--
-- Name: ag_datenblatt_etiketten_xml_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.ag_datenblatt_etiketten_xml_v AS
 SELECT v.vflz_id,
    v.vfl_id,
    v.vflz_combined_id_kt,
    (v.vflz_combined_id_kt)::character varying(11) AS staonrstamm,
    pd.app_doc_url,
    XMLELEMENT(NAME etikette, XMLELEMENT(NAME staonr_combined, v.vflz_combined_id_kt), XMLELEMENT(NAME staonrstamm, (v.vflz_combined_id_kt)::character varying(11)), XMLELEMENT(NAME bezeichnung,
        CASE
            WHEN (char_length((v.bezeichnung)::text) > 36) THEN (("substring"((v.bezeichnung)::text, 0, 36) || ' .'::text))::character varying
            ELSE v.bezeichnung
        END), XMLELEMENT(NAME vflz_id, v.vflz_id), XMLELEMENT(NAME gemeinde_id, v.h_gem_id), XMLELEMENT(NAME gemeinde, g.gemeinde), XMLELEMENT(NAME aktennummer, pd.app_doc_url)) AS xml
   FROM ((((altlast.vflz v
     LEFT JOIN altlast.h_gem g ON ((g.h_gem_id = v.h_gem_id)))
     LEFT JOIN altlast.pm_vfl pv USING (vfl_id))
     LEFT JOIN altlast.pm_cache pc USING (pm_vfl_id))
     LEFT JOIN altlast.pm_doc pd ON ((pd.pm_cache_id = pc.pm_cache_id)));


--
-- Name: VIEW ag_datenblatt_etiketten_xml_v; Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON VIEW altlast.ag_datenblatt_etiketten_xml_v IS 'AG specific view for labelprinting';


