--
-- Name: bem_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.bem_v AS
 SELECT b.bem_id,
    bg.bemgrp_id,
    bg.bemgrp,
    bg.title,
    bg.description,
    bg.rel_name,
    bg.key_column,
    b.key_value,
    b.bem,
        CASE
            WHEN bg.public THEN b.public
            ELSE bg.public
        END AS public,
    ((COALESCE(bg.sort, 1, bg.sort) * 100000) + COALESCE(b.sort, 1, b.sort)) AS sort
   FROM (altlast.bem b
     JOIN altlast.bemgrp bg ON ((bg.bemgrp_id = b.bemgrp_id)));


