--
-- Name: subj_vflz_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.subj_vflz_v AS
 SELECT sv.subj_vflz_id,
    sv.subj_id,
    sv.c_subj_vflz_bez_art,
    sv.beziehungs_instanz,
    sv.erfassungs_datum,
    sv.erfasser_kuerzel,
    sv.mutations_datum,
    sv.mutierer_kuerzel,
    sv.grundstueck_nr,
    sv.vflz_id,
    sv.h_subj_vflz_bez_art,
    svg.grun_id
   FROM (altlast.subj_vflz sv
     LEFT JOIN altlast.subj_vflz_grun svg ON ((svg.subj_vflz_id = sv.subj_vflz_id)));


--
-- Name: VIEW subj_vflz_v; Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON VIEW altlast.subj_vflz_v IS 'combines the rows of altlast.subj_vflz and subj_vflz_grun';


--
-- Name: vflz_owner_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.vflz_owner_v AS
 SELECT DISTINCT sv.subj_id,
    sv.vflz_id,
    altlast.concat_subj((s.name)::text, (s.vorname)::text, NULL::text) AS formatted_name,
    altlast.t(altlast.msgid_code(p.h_anrede, p.c_anrede)) AS anrede,
    altlast.t(altlast.msgid_code(p.h_titel, p.c_titel)) AS titel,
    s.name,
    s.vorname,
    s.taetigkeit,
    a.strasse,
    a.hausnummer,
    a.postleitzahl,
    a.ort,
    a.c_kanton,
    a.c_land,
    altlast.t(altlast.msgid_code(a.h_land, a.c_land)) AS land,
    altlast.t(altlast.msgid_code(sv.h_subj_vflz_bez_art, sv.c_subj_vflz_bez_art)) AS beziehungsart
   FROM ((((((altlast.subj_vflz_v sv
     JOIN altlast.cod c ON (((c.c_cli_id = sv.h_subj_vflz_bez_art) AND ((c.code)::text = (sv.c_subj_vflz_bez_art)::text))))
     JOIN altlast.cod_bezart ba ON (((c.c_cli_id = ba.c_cli_id_grun_subj) AND ((c.code)::text = (ba.grun_subj)::text) AND ba.eigen)))
     JOIN altlast.subj s USING (subj_id))
     LEFT JOIN altlast.subj_adr USING (subj_id))
     LEFT JOIN altlast.adr a USING (adr_id))
     LEFT JOIN altlast.pers p USING (subj_id))
  ORDER BY sv.vflz_id, sv.subj_id, (altlast.t(altlast.msgid_code(p.h_anrede, p.c_anrede))), (altlast.t(altlast.msgid_code(p.h_titel, p.c_titel))), s.name, s.vorname, s.taetigkeit, a.strasse, a.hausnummer, a.postleitzahl, a.ort, a.c_kanton, a.c_land, (altlast.t(altlast.msgid_code(sv.h_subj_vflz_bez_art, sv.c_subj_vflz_bez_art))), (altlast.t(altlast.msgid_code(a.h_land, a.c_land)));


--
-- Name: VIEW vflz_owner_v; Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON VIEW altlast.vflz_owner_v IS 'Subj which are assigned as owners to locations';


--
-- Name: report_eigentuemer_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.report_eigentuemer_v AS
 SELECT DISTINCT vflz_owner_v.vflz_id,
    vflz_owner_v.subj_id,
    (vflz_owner_v.anrede)::character varying(128) AS anrede,
    (vflz_owner_v.titel)::character varying(128) AS titel,
    vflz_owner_v.name,
    vflz_owner_v.vorname,
    vflz_owner_v.taetigkeit,
    vflz_owner_v.strasse,
    vflz_owner_v.hausnummer,
    vflz_owner_v.postleitzahl,
    vflz_owner_v.ort,
    vflz_owner_v.c_kanton,
    vflz_owner_v.c_land,
    (vflz_owner_v.land)::character varying(128) AS land,
    (vflz_owner_v.beziehungsart)::character varying(128) AS beziehungsart
   FROM altlast.vflz_owner_v;


--
-- Name: VIEW report_eigentuemer_v; Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON VIEW altlast.report_eigentuemer_v IS 'This view is deprecated. Use altlast.vflz_owner_v instead';


