--
-- Name: report_grunddaten_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.report_grunddaten_v AS
 SELECT v.vflz_id,
    v.vflz_combined_id_kt,
    v.vflz_combined_id,
    v.bezeichnung,
    v.h_gem_id,
    v.x_koordinate,
    v.y_koordinate,
    bb.bem AS bemerkungen,
    v.vflz_flurname,
    v.vflz_strasse,
    v.vflz_hausnr,
    v.vflz_postleitzahl,
    v.vflz_ort,
    v.h_vflz_bearbstand,
    v.c_vflz_bearbstand,
    v.h_vflz_vftyp,
    v.c_vflz_vftyp,
    v.vfa_flaeche,
    v.h_vflz_gws_bereich,
    v.c_vflz_gws_bereich,
    ( SELECT cod.bezeichnung
           FROM altlast.cod
          WHERE (((v.c_vflz_gws_zone)::text = (cod.code)::text) AND (cod.c_cli_id = v.h_vflz_gws_zone))) AS c_vflz_gws_zone,
    v.c_vflz_gws_bereich AS c_vflz_gws_bereich_code,
    v.h_vflz_karstgeb,
    v.c_vflz_karstgeb,
    v.h_vflz_durchlaessigkeit,
    v.c_vflz_durchlaessigkeit,
    ( SELECT cod.bezeichnung
           FROM altlast.cod
          WHERE (((v.c_vfbz_unterkellerung)::text = (cod.code)::text) AND (cod.c_cli_id = 78))) AS c_vfbz_unterkellerung,
    org.kuerzel AS owner_org,
    hg.gemeinde,
    hg.c_kanton
   FROM ((((altlast.vflz v
     LEFT JOIN altlast.h_gem hg ON ((v.h_gem_id = hg.h_gem_id)))
     LEFT JOIN ( SELECT bem_v.bem,
            bem_v.key_value
           FROM altlast.bem_v
          WHERE ((bem_v.bemgrp)::text ~~ 'standort'::text)) bb ON ((bb.key_value = v.vflz_id)))
     LEFT JOIN altlast.vflnr ON (((vflnr.vflz_id = v.vflz_id) AND vflnr.aktiv)))
     LEFT JOIN altlast.org USING (org_id));


