    vflz.rechtskraft,
    vflz.publizieren,
    vflz.dat_rechtskraft,
    vflz.dat_publizieren,
    vflz.bezeichnung,
    vflz.h_gem_id,
    vflz.x_koordinate,
    vflz.y_koordinate,
    vflz.z_koordinate,
    vflz.h_vflz_unterstand,
    vflz.c_vflz_unterstand
   FROM ((altlast.vflz
     JOIN altlast_hist.snapshot ON ((vflz.vflz_id = snapshot.key_value)))
     JOIN altlast_hist.history ON ((history.history_id = snapshot.history_id)))
  WHERE (((history.key_column)::text = 'vflz_id'::text) AND snapshot.is_current);


--
-- Name: report_gwvk_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.report_gwvk_v AS
 SELECT g.h_gwvk_relzugw,
    g.c_gwvk_relzugw,
    g.gwvk_flurabstand,
    g.gwvk_id,
    g.vflz_id,
    v.obje_id
   FROM (altlast.gwvk g
     JOIN altlast.vflz_current_v v ON ((g.vflz_id = v.vflz_id)));


--
-- Name: report_inta_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.report_inta_v AS
 SELECT i.inta_vol_kompartiment,
    bb.bem AS inta_ergaenzung,
    i.inta_id,
    i.vflz_id,
        CASE
            WHEN i.zeitraum_vonjahr THEN (date_part('year'::text, i.inta_ablag_von))::text
            ELSE (i.inta_ablag_von)::text
        END AS inta_ablag_von
   FROM ((altlast.inta i
     JOIN altlast.vflz_current_v v ON ((i.vflz_id = v.vflz_id)))
     LEFT JOIN ( SELECT bem_v.bem,
            bem_v.key_value
           FROM altlast.bem_v
          WHERE ((bem_v.bemgrp)::text ~~ 'ablagerung'::text)) bb ON ((bb.key_value = i.inta_id)))
  ORDER BY i.inta_ablag_bis DESC;


--
-- Name: report_intb_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.report_intb_v AS
 SELECT i.intb_firma_name,
    i.intb_firma_strasse,
    i.intb_firma_plz,
    i.intb_firma_ort,
    i.c_intb_bran,
    altlast.t(altlast.msgid_code(i.h_intb_bran, i.c_intb_bran)) AS c_intb_bran_bezeichnung,
    i.intb_groesse,
    (altlast.t(altlast.msgid_code(2004, (i.intb_groesse)::character varying)))::character varying(128) AS intb_groesse_klasse,
    i.intb_relevanz,
    i.intb_zeitschwelle,
    i.intb_mitarbeiter,
    i.intb_personenjahre,
    i.intb_formblatt,
    bb.bem AS intb_ergaenzung,
    i.intb_id,
    i.vflz_id,
    v.obje_id,
        CASE
            WHEN i.zeitraum_bisheute THEN altlast.t('Bis Heute'::text)
            WHEN i.zeitraum_bisjahr THEN (date_part('year'::text, i.intb_bisbetrieb))::text
            ELSE (i.intb_bisbetrieb)::text
        END AS intb_bisbetrieb,
        CASE
            WHEN i.relevant THEN altlast.t('Ja'::text)
            WHEN (i.relevant IS NULL) THEN altlast.t('Unbekannt'::text)
            ELSE altlast.t('Nein'::text)
        END AS intb_relevant,
        CASE
            WHEN i.zeitraum_vonjahr THEN (date_part('year'::text, i.intb_vonbetrieb))::text
            ELSE (i.intb_vonbetrieb)::text
        END AS intb_vonbetrieb,
    kbs.kbs,
    altlast.t(altlast.msgid_code(i.h_intb_res_abwbewe, i.c_intb_res_abwbewe)) AS intb_res_abwbewe
   FROM (((altlast.intb i
     JOIN altlast.vflz_current_v v ON ((i.vflz_id = v.vflz_id)))
     LEFT JOIN altlast.cod_berekbs kbs ON (((kbs.h_bere_res_abwbewe = i.h_intb_res_abwbewe) AND ((kbs.c_bere_res_abwbewe)::text = (i.c_intb_res_abwbewe)::text))))
     LEFT JOIN ( SELECT bem_v.bem,
            bem_v.key_value
           FROM altlast.bem_v
          WHERE ((bem_v.bemgrp)::text ~~ 'betrieb'::text)) bb ON ((bb.key_value = i.intb_id)))
  ORDER BY i.intb_vonbetrieb DESC, i.intb_firma_name;


--
-- Name: report_intu_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.report_intu_v AS
 SELECT i.intu_name,
        CASE
            WHEN i.zeitraum_jahr THEN (date_part('year'::text, i.intu_unfallvon))::text
            ELSE (i.intu_unfallvon)::text
        END AS intu_unfallvon,
    bb.bem AS intu_ergaenzung,
    i.intu_id,
    i.vflz_id,
    v.obje_id
   FROM ((altlast.intu i
     JOIN altlast.vflz_current_v v ON ((i.vflz_id = v.vflz_id)))
     LEFT JOIN ( SELECT b.key_value,
            b.bem
           FROM altlast.bem_v b
          WHERE ((b.bemgrp)::text ~~ 'unfall'::text)) bb ON ((bb.key_value = i.intu_id)));


--
-- Name: report_kksk_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.report_kksk_v AS
 SELECT k.kksk_teilvol,
    k.h_kksk_stoffkl,
    k.c_kksk_stoffkl,
    k.kksk_id,
    i.inta_id,
    v.vflz_id,
    v.obje_id,
        CASE
            WHEN k.zeitraum_bisheute THEN 'bis heute'::text
            WHEN k.zeitraum_bisjahr THEN (date_part('year'::text, k.kksk_ablag_bis))::text
            ELSE (k.kksk_ablag_bis)::text
        END AS kksk_ablag_bis,
        CASE
            WHEN k.zeitraum_vonjahr THEN (date_part('year'::text, k.kksk_ablag_von))::text
            ELSE (k.kksk_ablag_von)::text
        END AS kksk_ablag_von
   FROM ((altlast.kksk k
     JOIN altlast.inta i ON ((k.inta_id = i.inta_id)))
     JOIN altlast.vflz_current_v v ON ((v.vflz_id = i.vflz_id)));


