--

CREATE VIEW altlast.unterstand_dat_v AS
 SELECT DISTINCT unterstand_dat.vfl_id,
    unterstand_dat.tas_finish_date
   FROM ( SELECT pv.vfl_id,
            (pc.tas_finish_date)::date AS tas_finish_date
           FROM ((altlast.pm_cache pc
             JOIN altlast.pm_taskconf tc USING (tas_uid))
             JOIN altlast.pm_vfl pv USING (pm_vfl_id))
          WHERE ((COALESCE((tc.unterstand)::integer, 0) > 0) AND (tc.c_vflz_unterstand IS NOT NULL) AND (pc.tas_finish_date IS NOT NULL) AND (pc.tas_finish_date <= now()))
          ORDER BY pc.tas_finish_date DESC) unterstand_dat;


