    XMLELEMENT(NAME vflnr, XMLATTRIBUTES(v.aktiv AS aktiv), XMLELEMENT(NAME vflnr_id, v.vflnr_id), XMLELEMENT(NAME vflnr_nummer, v.nummer), XMLELEMENT(NAME vflnr_owner, o.option)) AS xml
   FROM (altlast.vflnr v
     LEFT JOIN altlast.lookup_org_v o ON ((v.org_id = o.id)));


--
-- Name: vflz_is_published_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.vflz_is_published_v AS
 SELECT DISTINCT ON (v.vflz_id) v.vflz_id,
        CASE
            WHEN ((p.rnk = 1) AND (p.dat_publizieren IS NULL)) THEN true
            WHEN ((p.rnk = 1) AND (p.dat_publizieren > now())) THEN false
            WHEN ((p.rnk = 1) AND (p.dat_publizieren <= now())) THEN true
            WHEN ((p.rnk = 2) AND p.pub_in_future) THEN true
            ELSE false
        END AS is_latest_published,
        CASE
            WHEN p.pub_in_future THEN ( SELECT p.dat_publizieren
              WHERE ((v.vfl_id = p.vfl_id) AND (p.rnk = 2)))
            ELSE p.max_dat_publizieren
        END AS dat_latest_published
   FROM ((altlast.vflz v
     JOIN altlast.vflz_current_v c USING (vfl_id))
     LEFT JOIN ( SELECT vflz.vflz_id,
            vflz.vfl_id,
            vflz.dat_publizieren,
            dense_rank() OVER (PARTITION BY vflz.vfl_id ORDER BY vflz.vflz_id DESC) AS rnk,
            max_p.max_dat_publizieren,
                CASE
                    WHEN (max_p.max_dat_publizieren > now()) THEN true
                    ELSE false
                END AS pub_in_future
           FROM (altlast.vflz
             LEFT JOIN ( SELECT vflz_1.vfl_id,
                    max(vflz_1.vflz_id) AS max_vflz_id,
                    max(vflz_1.dat_publizieren) AS max_dat_publizieren
                   FROM altlast.vflz vflz_1
                  WHERE vflz_1.publizieren
                  GROUP BY vflz_1.vfl_id) max_p USING (vfl_id))
          WHERE vflz.publizieren
          ORDER BY vflz.vflz_id) p ON ((v.vflz_id = p.vflz_id)));


--
-- Name: VIEW vflz_is_published_v; Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON VIEW altlast.vflz_is_published_v IS 'Allows to check if a location
version is the latest published version.';


--
-- Name: COLUMN vflz_is_published_v.is_latest_published; Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON COLUMN altlast.vflz_is_published_v.is_latest_published IS 'TRUE if
the vflz_id refers to the lastest published version of the location.';


--
-- Name: COLUMN vflz_is_published_v.dat_latest_published; Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON COLUMN altlast.vflz_is_published_v.dat_latest_published IS 'Publication date of the latest published version within a vfl_id, might be
NULL if no published version exists.';


