--
-- Name: app_states_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.app_states_v AS
 SELECT pm_cache.app_uid,
    COALESCE(( SELECT pcv.status
           FROM altlast.pm_cache pcv
          WHERE (((pcv.app_uid)::text = (pm_cache.app_uid)::text) AND ((pcv.status)::text = 'OPEN'::text))
         LIMIT 1), ( SELECT pcv.status
           FROM altlast.pm_cache pcv
          WHERE (((pcv.app_uid)::text = (pm_cache.app_uid)::text) AND ((pcv.status)::text = 'SLEEPING'::text))
         LIMIT 1), ( SELECT pcv.status
           FROM altlast.pm_cache pcv
          WHERE (((pcv.app_uid)::text = (pm_cache.app_uid)::text) AND ((pcv.status)::text = 'CLOSED'::text))
         LIMIT 1)) AS app_status,
        CASE
            WHEN ( SELECT (count(*) > 0)
               FROM altlast.pm_cache pcv
              WHERE (((pcv.app_uid)::text = (pm_cache.app_uid)::text) AND (pcv.tas_finish_date IS NULL))) THEN NULL::timestamp without time zone
            ELSE max(pm_cache.tas_finish_date)
        END AS app_finish_date,
    min(pm_cache.tas_delegate_date) AS app_delegate_date
   FROM altlast.pm_cache
  GROUP BY pm_cache.app_uid;


