--
-- Name: bere_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.bere_v AS
 SELECT COALESCE(cod_berekbs.kbs, false) AS kbs,
    b.vflz_id,
    b.bere_dat_autobewe,
    b.h_bere_res_autobewe,
    b.c_bere_res_autobewe,
    b.bere_dat_abwbewe,
    b.h_bere_res_abwbewe,
    b.c_bere_res_abwbewe,
    bb.bem AS bere_begr_abwbewe,
    b.erfassungs_datum,
    b.erfasser_kuerzel,
    b.mutations_datum,
    b.mutierer_kuerzel,
    b.bere_prio_untersuch,
    bu.bem AS bere_begr_prio_untersuch,
    b.bere_prio_sanier,
    bs.bem AS bere_begr_prio_sanier
   FROM ((((altlast.bere b
     LEFT JOIN altlast.cod_berekbs USING (h_bere_res_abwbewe, c_bere_res_abwbewe))
     LEFT JOIN ( SELECT bb_1.bem_id,
            bb_1.bemgrp_id,
            bb_1.public,
            bb_1.sort,
            bb_1.bem,
            bb_1.erfassungs_datum,
            bb_1.erfasser_kuerzel,
            bb_1.mutations_datum,
            bb_1.mutierer_kuerzel,
            bb_1.key_value,
            bb_1.h_bem_art,
            bb_1.c_bem_art,
            bbg.bemgrp_id,
            bbg.bemgrp,
            bbg.title,
            bbg.description,
            bbg.sort,
            bbg.public,
            bbg.key_column,
            bbg.rel_name,
            bbg.multiple,
            bbg.erfassungs_datum,
            bbg.erfasser_kuerzel,
            bbg.mutations_datum,
            bbg.mutierer_kuerzel
           FROM (altlast.bem bb_1
             JOIN altlast.bemgrp bbg ON (((bbg.bemgrp_id = bb_1.bemgrp_id) AND ((bbg.bemgrp)::text = 'bere_begr_abwbewe'::text))))) bb(bem_id, bemgrp_id, public, sort, bem, erfassungs_datum, erfasser_kuerzel, mutations_datum, mutierer_kuerzel, key_value, h_bem_art, c_bem_art, bemgrp_id_1, bemgrp, title, description, sort_1, public_1, key_column, rel_name, multiple, erfassungs_datum_1, erfasser_kuerzel_1, mutations_datum_1, mutierer_kuerzel_1) ON ((bb.key_value = b.vflz_id)))
     LEFT JOIN ( SELECT bu_1.bem_id,
            bu_1.bemgrp_id,
            bu_1.public,
            bu_1.sort,
            bu_1.bem,
