           FROM (altlast.bem bu_1
             JOIN altlast.bemgrp bug ON (((bug.bemgrp_id = bu_1.bemgrp_id) AND ((bug.bemgrp)::text = 'bere_begr_prio_untersuch'::text))))) bu(bem_id, bemgrp_id, public, sort, bem, erfassungs_datum, erfasser_kuerzel, mutations_datum, mutierer_kuerzel, key_value, h_bem_art, c_bem_art, bemgrp_id_1, bemgrp, title, description, sort_1, public_1, key_column, rel_name, multiple, erfassungs_datum_1, erfasser_kuerzel_1, mutations_datum_1, mutierer_kuerzel_1) ON ((bu.key_value = b.vflz_id)))
     LEFT JOIN ( SELECT bs_1.bem_id,
            bs_1.bemgrp_id,
            bs_1.public,
            bs_1.sort,
            bs_1.bem,
            bs_1.erfassungs_datum,
