--
-- Name: centroid_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.centroid_v AS
 SELECT v.vflz_id,
        CASE
            WHEN (vgeo.wkb_geometry IS NOT NULL) THEN public.st_x(public.st_centroid(vgeo.wkb_geometry))
            ELSE (v.x_koordinate)::double precision
        END AS centroid_x,
        CASE
            WHEN (vgeo.wkb_geometry IS NOT NULL) THEN public.st_y(public.st_centroid(vgeo.wkb_geometry))
            ELSE (v.y_koordinate)::double precision
        END AS centroid_y
   FROM (altlast.vflz v
     LEFT JOIN altlast.vflgeo vgeo ON ((v.vflz_id = vgeo.vflz_id)));


