--
-- Name: geoportal_export_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.geoportal_export_v AS
 WITH lang AS (
         SELECT 'fr'::text AS lang
        )
 SELECT v.vflz_id,
    v.vflz_combined_id_kt AS staonr,
    v.bezeichnung AS staobezeichnung,
    v.dat_rechtskraft AS ersteintrag,
    altlast.t(altlast.msgid_code(v.h_vflz_vftyp, v.c_vflz_vftyp), lang.lang) AS staotyp,
    v.h_gem_id AS gemeinde_bfs,
    h_gem.gemeinde,
        CASE
            WHEN (public.st_geometrytype(vflgeo.wkb_geometry) = 'ST_Point'::text) THEN public.st_buffer(vflgeo.wkb_geometry, (10)::double precision)
            ELSE vflgeo.wkb_geometry
        END AS wkb_geometry,
    betrieb_props.betrieb_branchen,
    betrieb_props.betrieb_zeitraum,
    ablag_props.ablag_zeitraum,
    ablag_props.ablag_gesamtvol,
    unfall_props.unfall_zeitpunkt,
    altlast.t(altlast.msgid_code(bere.h_bere_res_abwbewe, bere.c_bere_res_abwbewe), lang.lang) AS beurteilung,
    umweltbereiche.festgestellte_einwirkungen,
    to_char((vip.dat_latest_published)::timestamp with time zone, 'DD.MM.YYYY'::text) AS publikation_datum,
    parzellen.parzellen,
    v.vflz_flurname,
    betrieb_props.betrieb_strassen AS vflz_strasse,
    v.vflz_hausnr,
    v.vflz_postleitzahl,
    v.vflz_ort,
    v.x_koordinate,
    v.y_koordinate,
    v.publizieren,
    massnahmen.massnahmen,
    bem_begr.bem AS begruend_beurt,
    umweltbereiche.bem AS einwirkungen_bem,
    massnahmen.bem AS massnahmen_bem,
    bere.bere_prio_untersuch AS prio_untersuch
   FROM (((((((((((((((altlast.vflz v
     JOIN lang ON (true))
     JOIN altlast.vflnr ON (((vflnr.vflz_id = v.vflz_id) AND (vflnr.aktiv = true))))
     JOIN altlast.vflz_is_published_v vip ON (((vip.vflz_id = v.vflz_id) AND vip.is_latest_published)))
     JOIN altlast.bere_v bere ON (((bere.vflz_id = v.vflz_id) AND bere.kbs)))
     JOIN altlast.vflgeo ON ((v.vflz_id = vflgeo.vflz_id)))
     JOIN altlast_admin.setting stng ON (((stng.value)::text = (vflnr.org_id)::text)))
     JOIN altlast_admin.setitem sit ON (((sit.setitem_id = stng.setitem_id) AND ((sit.key)::text = 'org'::text))))
     LEFT JOIN altlast.h_gem ON ((h_gem.h_gem_id = v.h_gem_id)))
     LEFT JOIN ( SELECT intb.vflz_id,
            array_to_string(array_agg(altlast.t(altlast.msgid_code(ibv.h_intb_bran, ibv.c_intb_bran), lang_1.lang)), '
'::text) AS betrieb_branchen,
            array_to_string(array_agg(DISTINCT altlast.t((ribv.intb_firma_strasse)::text, lang_1.lang)), '
'::text) AS betrieb_strassen,
            ((((COALESCE(to_char((min(intb.intb_vonbetrieb))::timestamp with time zone, 'DD.MM.YYYY'::text), altlast.t('unbekannt'::text, lang_1.lang)) || ' '::text) || altlast.t('bis'::text, lang_1.lang)) || ' '::text) || COALESCE(to_char((max(intb.intb_bisbetrieb))::timestamp with time zone, 'DD.MM.YYYY'::text), altlast.t('heute'::text, lang_1.lang))) AS betrieb_zeitraum
           FROM lang lang_1,
            ((altlast.intb
             JOIN altlast.intb_branche_v ibv ON ((ibv.intb_id = intb.intb_id)))
             JOIN altlast.report_intb_v ribv ON ((ribv.intb_id = intb.intb_id)))
          GROUP BY intb.vflz_id, lang_1.lang) betrieb_props ON (((betrieb_props.vflz_id = v.vflz_id) AND ((v.c_vflz_vftyp)::text = '02'::text))))
     LEFT JOIN ( SELECT inta.vflz_id,
            ((((COALESCE(to_char((min(inta.inta_ablag_von))::timestamp with time zone, 'DD.MM.YYYY'::text), altlast.t('unbekannt'::text, lang_1.lang)) || ' '::text) || altlast.t('bis'::text, lang_1.lang)) || ' '::text) ||
                CASE
                    WHEN bool_or(inta.zeitraum_bisheute) THEN altlast.t('heute'::text, lang_1.lang)
                    ELSE COALESCE(to_char((max(inta.inta_ablag_bis))::timestamp with time zone, 'DD.MM.YYYY'::text), altlast.t('unbekannt'::text, lang_1.lang))
                END) AS ablag_zeitraum,
            sum(inta.inta_vol_kompartiment) AS ablag_gesamtvol,
            array_to_string(array_agg((altlast.t(altlast.msgid_code(kksk.h_kksk_stoffkl, kksk.c_kksk_stoffkl), lang_1.lang) || COALESCE((': '::text || altlast.t(altlast.msgid_code(kksg.h_kksg_stoffgrp, kksg.c_kksg_stoffgrp), lang_1.lang)), ''::text))), '
'::text) AS ablag_stoffe
           FROM (((altlast.inta
             JOIN lang lang_1 ON (true))
             LEFT JOIN altlast.kksk ON ((kksk.inta_id = inta.inta_id)))
             LEFT JOIN altlast.kksg ON ((kksk.kksk_id = kksg.kksk_id)))
          GROUP BY inta.vflz_id, lang_1.lang) ablag_props ON (((ablag_props.vflz_id = v.vflz_id) AND ((v.c_vflz_vftyp)::text = '01'::text))))
     LEFT JOIN ( SELECT intu.vflz_id,
            altlast.commacat_all(
                CASE
                    WHEN intu.zeitraum_jahr THEN to_char((intu.intu_unfallvon)::timestamp with time zone, 'YYYY'::text)
                    ELSE to_char((intu.intu_unfallvon)::timestamp with time zone, 'DD.MM.YYYY'::text)
                END) AS unfall_zeitpunkt,
            array_to_string(array_agg((altlast.t(altlast.msgid_code(inum.h_inum_stoffe, inum.c_inum_stoffe), lang_1.lang) || COALESCE((((((': '::text || altlast.t('Restmenge'::text, lang_1.lang)) || ' '::text) || (NULLIF(inum.inum_stoffmng, (0)::double precision))::text) || ' '::text) || altlast.t('liter'::text, lang_1.lang)), ''::text))), '
'::text) AS unfall_stoffe
           FROM ((altlast.intu
             JOIN lang lang_1 ON (true))
             LEFT JOIN altlast.inum ON ((inum.intu_id = intu.intu_id)))
          GROUP BY intu.vflz_id, lang_1.lang) unfall_props ON (((unfall_props.vflz_id = v.vflz_id) AND ((v.c_vflz_vftyp)::text = '03'::text))))
     LEFT JOIN ( SELECT vfus.vflz_id,
            array_to_string(array_agg(altlast.t(altlast.msgid_code(vfus.h_vfus_art_schaden, vfus.c_vfus_art_schaden), lang_1.lang)), '
'::text) AS gefaehrdete_umweltbereiche,
            array_to_string(array_agg(altlast.t(altlast.msgid_code(vfus.h_vfus_schaeden, vfus.c_vfus_schaeden), lang_1.lang)), '
'::text) AS festgestellte_einwirkungen,
            array_to_string(array_agg(bem.bem), '
'::text) AS bem
           FROM ((altlast.vfus
             JOIN altlast.bem ON ((vfus.vfus_id = bem.key_value)))
             JOIN lang lang_1 ON (true))
          GROUP BY vfus.vflz_id, lang_1.lang) umweltbereiche ON ((umweltbereiche.vflz_id = v.vflz_id)))
     LEFT JOIN ( SELECT bem.key_value,
            bem.bem
           FROM (altlast.bem
             LEFT JOIN altlast.bemgrp ON ((bemgrp.bemgrp_id = bem.bemgrp_id)))
          WHERE ((bemgrp.bemgrp)::text = 'bere_begr_abwbewe'::text)) bem_begr ON ((bem_begr.key_value = v.vflz_id)))
     LEFT JOIN ( SELECT mass.vflz_id,
            array_to_string(array_agg(altlast.t(altlast.msgid_code(mass.h_massnahme, mass.c_massnahme), lang_1.lang)), '
'::text) AS massnahmen,
            array_to_string(array_agg(bem.bem), '
'::text) AS bem
           FROM ((altlast.mass
             JOIN altlast.bem ON (((mass.mass_id = bem.key_value) AND (bem.bemgrp_id = 15))))
             JOIN lang lang_1 ON (true))
          GROUP BY mass.vflz_id, lang_1.lang) massnahmen ON ((massnahmen.vflz_id = v.vflz_id)))
     LEFT JOIN ( SELECT vflz_parzellen_v.vflz_id,
            array_to_string(array_agg(vflz_parzellen_v.parzellen), ', '::text) AS parzellen
           FROM altlast.vflz_parzellen_v
          GROUP BY vflz_parzellen_v.vflz_id) parzellen ON ((parzellen.vflz_id = v.vflz_id)))
  WHERE vflnr.aktiv
  ORDER BY v.vflz_combined_id_kt;


--
-- Name: VIEW geoportal_export_v; Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON VIEW altlast.geoportal_export_v IS 'View used for exporting data for the Geoportal [refs #5020082]';



