--
-- Name: grundbuch_parzellen_intersect; Type: MATERIALIZED VIEW; Schema: altlast; Owner: -
--

CREATE MATERIALIZED VIEW altlast.grundbuch_parzellen_intersect AS
 SELECT DISTINCT v.vflz_id,
    gb.gb_id,
    gb.grundbuch,
    NULL::text AS parzellen,
    ((((gb.grundbuch)::text || ' ('::text) || (gb.gb_id)::text) || ')'::text) AS lookup_option
   FROM (((altlast._grundbuch gb
     LEFT JOIN altlast.grun g ON ((g.h_gem_id = gb.gb_id)))
     LEFT JOIN altlast.subj_vflz_grun svg USING (grun_id))
     JOIN altlast.vflgeo v ON ((public.st_isvalid(v.wkb_geometry) AND public.st_isvalid(gb.wkb_geometry) AND public.st_intersects(v.wkb_geometry, gb.wkb_geometry))))
  WITH NO DATA;


