-- Name: h_bez; Type: TABLE; Schema: altlast; Owner: -
--

CREATE TABLE altlast.h_bez (
    h_bez_id integer NOT NULL,
    datum_aend date,
    datum_erst date,
    erstell_j integer,
    erstell_m character varying(20),
    herkunft character varying(20),
    herkunft_j integer,
    objektart character varying(20),
    bezirk_id integer,
    bezirk_tei character varying(20),
    bezirk character varying(254),
    h_kanton integer,
    wkb_geometry public.geometry
);


--
-- Name: TABLE h_bez; Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON TABLE altlast.h_bez IS 'Bezirke from the swisstopo Boundary3D Dataset. Droped collumns of the original dataset: uuid, revision_j, revision_m, grund_aend, einwohnerz, icc, bezirksfla, revision_q,see_flaech, herkunft_m. Renamed collumns bezirksnum -> bezirk_id, kantonsnum -> h_kanton, geom -> wkb_geometry, gid -> h_bez_id, name -> bezirk';


