--
-- Name: kbs_hauptbranchen_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.kbs_hauptbranchen_v AS
 SELECT DISTINCT ON (br.vflz_id) br.vflz_id,
    br.c_intb_bran,
    br.bran_bezeichnung
   FROM ( SELECT v.vflz_id,
            i.c_intb_bran,
            (altlast.t(altlast.msgid_code(25, i.c_intb_bran)))::character varying(255) AS bran_bezeichnung
           FROM (altlast.vflz v
             JOIN altlast.intb i ON (((i.vflz_id = v.vflz_id) AND (upper((v.vflz_combined_id_kt)::text) = altlast.imp_vflz_combined_id_tk_bz(upper((i.intb_eva)::text))))))
        UNION
         SELECT v.vflz_id,
            i.c_intb_bran,
            (altlast.t(altlast.msgid_code(25, i.c_intb_bran)))::character varying(255) AS bran_bezeichnung
           FROM (altlast.vflz v
             JOIN altlast.intb i ON (((i.vflz_id = v.vflz_id) AND (upper((v.vflz_combined_id_kt)::text) = altlast.imp_vflz_combined_id_tk_zb(upper((i.intb_eva)::text))))))
        UNION
         SELECT v.vflz_id,
            '8414'::character varying(8) AS c_intb_bran,
            'Ablagerung'::character varying(255) AS bran_bezeichnung
           FROM altlast.vflz v
          WHERE ((v.c_vflz_vftyp)::text = '01'::text)
        UNION
         SELECT v.vflz_id,
            '9811'::character varying(8) AS c_intb_bran,
            'Unfall'::character varying(255) AS bran_bezeichnung
           FROM altlast.vflz v
          WHERE ((v.c_vflz_vftyp)::text = '03'::text)) br
  ORDER BY br.vflz_id;


--
-- Name: VIEW kbs_hauptbranchen_v; Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON VIEW altlast.kbs_hauptbranchen_v IS 'Dieser View stellt die Hauptbranchen eines Standortes dar. Benoetigt fuer den Shapeexport.';


--
-- Name: kbs2public_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.kbs2public_v AS
 SELECT ((vg.vflgeo_id * 100) + generate_series(1, public.st_numgeometries(public.st_multi(vg.wkb_geometry)))) AS gid,
    public.st_geometryn(public.st_multi(vg.wkb_geometry), generate_series(1, public.st_numgeometries(public.st_multi(vg.wkb_geometry)))) AS the_geom,
    vflz.bezeichnung,
    vflz.vflz_combined_id_kt AS standortnr,
    vflz.c_vflz_vftyp,
    ( SELECT altlast.t(altlast.msgid_code(cod.c_cli_id, cod.code), 'de'::text) AS t
           FROM altlast.cod
          WHERE ((cod.c_cli_id = 63) AND ((cod.code)::text = (vflz.c_vflz_vftyp)::text))) AS typ,
    (altlast.killlinebreaks((vflz.vflz_strasse)::text))::character varying(100) AS vflz_strasse,
    vflz.h_gem_id,
    (altlast.killlinebreaks((( SELECT h_gem.gemeinde
           FROM altlast.h_gem
          WHERE (vflz.h_gem_id = h_gem.h_gem_id)))::text))::character varying(100) AS gemeinde,
    b.c_bere_res_abwbewe,
    (altlast.killlinebreaks(( SELECT altlast.t(altlast.msgid_code(cod.c_cli_id, cod.code), 'de'::text) AS t
           FROM altlast.cod
          WHERE ((cod.c_cli_id = 103) AND ((cod.code)::text = (b.c_bere_res_abwbewe)::text)))))::character varying AS katrel,
    vflz.c_vflz_bearbstand,
    (altlast.killlinebreaks(( SELECT altlast.t(altlast.msgid_code(cod.c_cli_id, cod.code), 'de'::text) AS t
           FROM altlast.cod
          WHERE ((cod.c_cli_id = 55) AND ((cod.code)::text = (vflz.c_vflz_bearbstand)::text)))))::character varying AS bearbstand,
    (altlast.killlinebreaks((hb.bran_bezeichnung)::text))::character varying AS branchenbezeichnung,
    hb.c_intb_bran AS branchencode,
    (
        CASE
            WHEN (cc.color_rgb IS NULL) THEN '96 96 96'::character varying
            ELSE cc.color_rgb
        END)::text AS color_rgb,
    vflz.c_vflz_unterstand,
    altlast.killlinebreaks(altlast.t(altlast.msgid_code(cod_vflz_unterstand.c_cli_id, cod_vflz_unterstand.code), 'de'::text)) AS unterstand,
    vflz.vflz_id
   FROM (((((((altlast.vflz
     JOIN altlast.vflz_is_published_v v ON (((vflz.vflz_id = v.vflz_id) AND v.is_latest_published)))
     JOIN altlast.vflgeo vg ON ((vflz.vflz_id = vg.vflz_id)))
     JOIN altlast.bere_v b ON ((b.vflz_id = vflz.vflz_id)))
     LEFT JOIN ( SELECT DISTINCT ON (kbs_hauptbranchen_v.vflz_id) kbs_hauptbranchen_v.vflz_id,
            kbs_hauptbranchen_v.c_intb_bran,
            kbs_hauptbranchen_v.bran_bezeichnung
           FROM altlast.kbs_hauptbranchen_v) hb ON ((hb.vflz_id = vflz.vflz_id)))
     LEFT JOIN altlast.cod_kbscolor cc ON (((cc.c_bere_res_abwbewe)::text = (
        CASE
            WHEN (b.c_bere_res_abwbewe IS NULL) THEN b.c_bere_res_autobewe
            ELSE b.c_bere_res_abwbewe
        END)::text)))
     LEFT JOIN altlast.cod cod_vflz_unterstand ON (((cod_vflz_unterstand.c_cli_id = vflz.h_vflz_unterstand) AND ((cod_vflz_unterstand.code)::text = (vflz.c_vflz_unterstand)::text))))
     JOIN altlast.vflz_is_published_v vip ON ((vip.vflz_id = vflz.vflz_id)))
  WHERE (vip.is_latest_published AND b.kbs);


--
-- Name: VIEW kbs2public_v; Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON VIEW altlast.kbs2public_v IS 'Sicht für die Publikation des KbS im Internet';


