--
-- Name: kbs_betriebe_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.kbs_betriebe_v AS
 SELECT i.intb_id AS gid,
    i.intb_firma_name,
    i.intb_firma_strasse,
    i.intb_firma_plz,
    i.intb_firma_ort,
    (
        CASE
            WHEN (cc.color_rgb IS NULL) THEN '96 96 96'::character varying
            ELSE cc.color_rgb
        END)::text AS color_rgb,
    public.st_setsrid(public.st_point((i.x_koordinate)::double precision, (i.y_koordinate)::double precision), altlast_admin.setting_get_projection()) AS wkb_geometry
   FROM (((altlast.intb i
     JOIN altlast.vflz_current_v USING (vflz_id))
     LEFT JOIN altlast.bere b ON ((b.vflz_id = i.vflz_id)))
     LEFT JOIN altlast.cod_kbscolor cc ON (((cc.c_bere_res_abwbewe)::text = (
        CASE
            WHEN ((i.c_intb_res_abwbewe IS NULL) AND (b.c_bere_res_abwbewe IS NULL)) THEN b.c_bere_res_autobewe
            WHEN (i.c_intb_res_abwbewe IS NULL) THEN b.c_bere_res_abwbewe
            ELSE i.c_intb_res_abwbewe
        END)::text)));


