--
-- Name: searchfield_contaminated_and_public; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.searchfield_contaminated_and_public AS
 SELECT vflz.vflz_id AS id,
    (NOT ((vflz_is_published_v.is_latest_published AND cod_berekbs.kbs) IS DISTINCT FROM true)) AS option
   FROM (((altlast.vflz
     LEFT JOIN altlast.bere USING (vflz_id))
     LEFT JOIN altlast.cod_berekbs USING (h_bere_res_abwbewe, c_bere_res_abwbewe))
     LEFT JOIN altlast.vflz_is_published_v USING (vflz_id));


