-- Name: COLUMN searchfield_contaminated_and_public.option; Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON COLUMN altlast.searchfield_contaminated_and_public.option IS 'TRUE when a vflz is a contaminated version and also published in the KbS. See #3696.';


--
-- Name: vfl_kennung_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.vfl_kennung_v AS
 SELECT v.obje_id,
    v.vfl_id,
    v.vflz_id,
    ((((
        CASE
            WHEN ((v.c_vflz_vftyp)::text = '01'::text) THEN 'A'::text
            WHEN ((v.c_vflz_vftyp)::text = '02'::text) THEN 'B'::text
            WHEN ((v.c_vflz_vftyp)::text = '03'::text) THEN 'U'::text
            WHEN ((v.c_vflz_vftyp)::text = '04'::text) THEN 'S'::text
            ELSE NULL::text
        END || ' '::text) || COALESCE((v.vflz_combined_id_kt)::text, '?'::text)) || ': '::text) || altlast.remove_linebreaks((v.bezeichnung)::text)) AS sto_kennung,
    ((COALESCE((v.vflz_combined_id_kt)::text, '?'::text) || ': '::text) ||
        CASE
            WHEN (length((v.bezeichnung)::text) > 20) THEN (substr((v.bezeichnung)::text, 1, 18) || '...'::text)
            ELSE (v.bezeichnung)::text
        END) AS sto_kennung_kurz,
    (COALESCE((v.vflz_combined_id_kt)::text, '?'::text))::character varying(50) AS stonr,
    (((COALESCE((v.vflz_combined_id_kt)::text, '?'::text) || ': '::text) || altlast.remove_linebreaks((v.bezeichnung)::text)))::character varying AS list_entry
   FROM altlast.vflz v;


--
-- Name: VIEW vfl_kennung_v; Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON VIEW altlast.vfl_kennung_v IS 'Unique short naming of a standort.';


--
-- Name: kbs_public_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.kbs_public_v AS
 SELECT vg.vflgeo_id,
    v.vflz_id,
    public.st_astext(vg.wkb_geometry) AS geometry,
    vg.wkb_geometry,
    (vkv.stonr)::text AS staonr,
    altlast.t(altlast.msgid_code(v.h_vflz_vftyp, v.c_vflz_vftyp), 'de'::text) AS staotyp,
    v.h_gem_id,
    h_gem.gemeinde,
    v.c_vflz_deponietyp,
    v.c_vflz_inbetrieb,
    v.c_vflz_nachsorge,
    bere.c_bere_res_abwbewe,
        CASE
            WHEN (colored_sites.colorcategory = 'gelb'::text) THEN ''::text
            ELSE (c103.bezeichnung)::text
        END AS beweart5,
        CASE
            WHEN (colored_sites.colorcategory = 'gelb'::text) THEN ''::text
            ELSE (c103_8.bezeichnung)::text
        END AS beweart8,
        CASE
            WHEN (colored_sites.colorcategory = 'gelb'::text) THEN ''::text
            ELSE eintrag_msgs.eintrag
        END AS ustand,
        CASE
            WHEN (colored_sites.colorcategory = 'gelb'::text) THEN ''::text
            ELSE
            CASE
                WHEN ((v.c_vflz_vftyp)::text = '03'::text) THEN COALESCE((v.zeitraum_von)::text, 'unbekannt'::text)
                WHEN ((v.zeitraum_von IS NULL) AND (v.zeitraum_bis IS NULL)) THEN 'unbekannt'::text
                ELSE ((
                CASE
                    WHEN (v.zeitraum_von IS NULL) THEN 'unbekannt'::text
                    WHEN v.zeitraum_vonjahr THEN to_char((v.zeitraum_von)::timestamp with time zone, 'YYYY'::text)
                    ELSE to_char((v.zeitraum_von)::timestamp with time zone, 'DD.MM.YYYY'::text)
                END || ' bis '::text) ||
                CASE
                    WHEN (v.zeitraum_bis IS NULL) THEN 'unbekannt'::text
                    WHEN v.zeitraum_bisjahr THEN to_char((v.zeitraum_bis)::timestamp with time zone, 'YYYY'::text)
                    ELSE to_char((v.zeitraum_bis)::timestamp with time zone, 'DD.MM.YYYY'::text)
                END)
            END
        END AS zeitraum,
        CASE
            WHEN (colored_sites.colorcategory = 'gelb'::text) THEN 'in Bearbeitung: Der Standort kann nach der abschliessenden Beurteilung auch unbelastet sein.'::text
            ELSE ('rechtskräftig, '::text || to_char((v.dat_rechtskraft)::timestamp with time zone, 'DD.MM.YYYY'::text))
        END AS ersteintrag,
    to_char((v.dat_publizieren)::timestamp with time zone, 'DD.MM.YYYY'::text) AS letzte_publikation,
    colored_sites.colorcategory AS symbol
   FROM ((((((((( WITH red_sites AS (
                 SELECT searchfield_contaminated_and_public.id AS vflz_id
                   FROM altlast.searchfield_contaminated_and_public
                  WHERE (searchfield_contaminated_and_public.option = true)
                )
         SELECT red_sites.vflz_id,
            'rot'::text AS colorcategory
           FROM red_sites
        UNION
         SELECT v_1.vflz_id,
            'gelb'::text AS colorcategory
           FROM (((altlast.vflz v_1
             JOIN altlast.vflz_is_current_v vc USING (vflz_id))
             JOIN altlast.bere bere_1 ON ((bere_1.vflz_id = v_1.vflz_id)))
             JOIN altlast.cod_berekbs ON (((((bere_1.c_bere_res_abwbewe)::text = (cod_berekbs.c_bere_res_abwbewe)::text) AND ((bere_1.c_bere_res_abwbewe)::text = 'BLKR09'::text) AND (bere_1.h_bere_res_abwbewe = cod_berekbs.h_bere_res_abwbewe)) OR (bere_1.h_bere_res_abwbewe = 103))))
          WHERE (cod_berekbs.kbs AND (vc.is_current = true) AND (NOT (COALESCE((bere_1.c_bere_res_abwbewe)::text, ''::text) = 'BLKR01'::text)) AND (NOT (COALESCE((v_1.c_vflz_bearbstand)::text, ''::text) = 'BLBS09'::text)) AND (NOT (v_1.vflz_id IN ( SELECT red_sites.vflz_id
                   FROM red_sites))))) colored_sites
     JOIN altlast.vflz v ON ((v.vflz_id = colored_sites.vflz_id)))
     JOIN altlast.bere ON ((bere.vflz_id = v.vflz_id)))
     JOIN altlast.vflgeo vg ON ((vg.vflz_id = v.vflz_id)))
     JOIN altlast.vfl_kennung_v vkv ON ((vkv.vflz_id = v.vflz_id)))
     LEFT JOIN altlast.h_gem ON ((h_gem.h_gem_id = v.h_gem_id)))
     LEFT JOIN ( SELECT v_1.vflz_id,
            (COALESCE(kpum.ustand_display, ''::text) || COALESCE(
                CASE
                    WHEN ((kpum.start_or_end_date = 'e'::bpchar) AND ((tas_dates.finish_date IS NOT NULL) OR (pro_dates.finish_date IS NOT NULL))) THEN ((', '::text || (COALESCE(kpum.additional_text, ''::text) || ' '::text)) || COALESCE(to_char(tas_dates.finish_date, 'DD.MM.YYYY'::text), to_char(pro_dates.finish_date, 'DD.MM.YYYY'::text)))
                    WHEN ((tas_dates.delegate_date IS NOT NULL) OR (pro_dates.delegate_date IS NOT NULL)) THEN ((', '::text || (COALESCE(kpum.additional_text, ''::text) || ' '::text)) || COALESCE(to_char(tas_dates.delegate_date, 'DD.MM.YYYY'::text), to_char(pro_dates.delegate_date, 'DD.MM.YYYY'::text)))
                    ELSE NULL::text
                END, ''::text)) AS eintrag
           FROM (((altlast.vflz v_1
             JOIN altlast.kbs_public_ustand_mapping kpum ON ((((kpum.c_vflz_unterstand)::text = (v_1.c_vflz_unterstand)::text) AND (kpum.h_vflz_unterstand = v_1.h_vflz_unterstand))))
             LEFT JOIN ( SELECT pm_vfl.vfl_id,
                    pm_vfl.pro_uid,
                    max(app_states_v.app_finish_date) AS finish_date,
                    min(app_states_v.app_delegate_date) AS delegate_date
                   FROM (altlast.pm_vfl
                     JOIN altlast.app_states_v ON (((pm_vfl.app_uid)::text = (app_states_v.app_uid)::text)))
                  GROUP BY pm_vfl.vfl_id, pm_vfl.pro_uid) pro_dates ON ((((pro_dates.pro_uid)::text = (kpum.con_id)::text) AND (pro_dates.vfl_id = v_1.vfl_id) AND (kpum.process_or_task = 'p'::bpchar))))
             LEFT JOIN ( SELECT pm_vfl.vfl_id,
                    pmc.tas_uid,
                    max(pmc.tas_finish_date) AS finish_date,
                    min(pmc.tas_delegate_date) AS delegate_date
                   FROM (altlast.pm_vfl
                     JOIN altlast.pm_cache pmc ON ((pmc.pm_vfl_id = pm_vfl.pm_vfl_id)))
                  GROUP BY pm_vfl.vfl_id, pmc.tas_uid) tas_dates ON ((((tas_dates.tas_uid)::text = (kpum.con_id)::text) AND (tas_dates.vfl_id = v_1.vfl_id) AND (kpum.process_or_task = 't'::bpchar))))) eintrag_msgs ON (((eintrag_msgs.vflz_id = v.vflz_id) AND (colored_sites.colorcategory <> 'gelb'::text))))
     LEFT JOIN altlast.cod c103 ON ((((bere.c_bere_res_abwbewe)::text = (c103.code)::text) AND (c103.c_cli_id = 103) AND ((c103.code)::text = ANY (ARRAY[('BLKR05'::character varying)::text, ('BLKR13'::character varying)::text, ('BLKR14'::character varying)::text])))))
     LEFT JOIN altlast.cod c103_8 ON ((((bere.c_bere_res_abwbewe)::text = (c103_8.code)::text) AND (c103_8.c_cli_id = 103) AND ((c103_8.code)::text = ANY (ARRAY[('BLKR06'::character varying)::text, ('BLKR07'::character varying)::text, ('BLKR08'::character varying)::text])))))
  WHERE (((bere.c_bere_res_abwbewe)::text <> ('00'::character varying)::text) AND ((bere.h_bere_res_abwbewe <> 103) OR ((bere.c_bere_res_abwbewe)::text <> 'BLKR31'::text)) AND ((bere.h_bere_res_abwbewe <> 103) OR ((bere.c_bere_res_abwbewe)::text <> 'BLKR32'::text)));


--
-- Name: vflz_filename_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.vflz_filename_v AS
 SELECT vflz.vflz_id,
    vflz.vflz_combined_id_kt,
    (rtrim((baseurl_setting.value)::text, '/'::text) || '/'::text) AS baseurl,
        CASE
            WHEN ((prefix_setting.value)::text = ANY ((ARRAY['kbs_sz_'::character varying, 'kbs_ur_'::character varying, 'kbs_zg_'::character varying])::text[])) THEN ((COALESCE((prefix_setting.value)::text, ''::text) || regexp_replace((vflz.vflz_combined_id_kt)::text, '[^w]'::text, ' '::text, 'g'::text)) || '.pdf'::text)
            WHEN ((prefix_setting.value)::text = 'kbs_bazl_'::text) THEN ((COALESCE((prefix_setting.value)::text, ''::text) || regexp_replace(regexp_replace(regexp_replace((vflz.vflz_combined_id_kt)::text, '[ÄÜÖäüö]'::text, '_'::text, 'g'::text), '[^w]'::text, '_'::text, 'g'::text), '__'::text, '_'::text, 'g'::text)) || '.pdf'::text)
            WHEN ((prefix_setting.value)::text = ANY ((ARRAY['kbs_ag_'::character varying, 'kbs_fl_'::character varying])::text[])) THEN ((vflz.vflz_combined_id_kt)::text || '.pdf'::text)
            ELSE ((COALESCE((prefix_setting.value)::text, ''::text) || regexp_replace((vflz.vflz_combined_id_kt)::text, '[^w]'::text, '_'::text, 'g'::text)) || '.pdf'::text)
        END AS filename
   FROM ((((altlast.vflz
     CROSS JOIN altlast_admin.setting baseurl_setting)
     LEFT JOIN altlast_admin.setitem baseurl_setitem ON ((baseurl_setting.setitem_id = baseurl_setitem.setitem_id)))
     CROSS JOIN altlast_admin.setting prefix_setting)
     LEFT JOIN altlast_admin.setitem prefix_setitem ON ((prefix_setting.setitem_id = prefix_setitem.setitem_id)))
  WHERE (((prefix_setitem.key)::text = 'cadastre_ds_prefix'::text) AND ((prefix_setting.role_name)::text = 'default'::text) AND ((baseurl_setitem.key)::text = 'cadastre_ds_url'::text) AND ((baseurl_setting.role_name)::text = 'default'::text));


--
-- Name: VIEW vflz_filename_v; Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON VIEW altlast.vflz_filename_v IS 'Filenames and URLs derived from site number to be used for links to pre-generated datasheets.';


--
-- Name: kbs_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.kbs_v AS
 SELECT DISTINCT v.vflz_id,
    v.vflz_combined_id_kt AS nummer,
    v.bezeichnung,
    altlast.t(altlast.msgid_code(v.h_vflz_vftyp, v.c_vflz_vftyp), (vflz_lang.lang)::text) AS typ,
    v.c_vflz_vftyp,
    altlast.t(altlast.msgid_code(v.h_vflz_unterstand, v.c_vflz_unterstand), (vflz_lang.lang)::text) AS unterstand,
    v.c_vflz_unterstand,
    altlast.t(altlast.msgid_code(b.h_bere_res_abwbewe, b.c_bere_res_abwbewe), (vflz_lang.lang)::text) AS bewertung,
    b.c_bere_res_abwbewe,
    org.bezeichnung AS vollzug,
    ((('Y='::text || (v.x_koordinate)::text) || '&X='::text) || (v.y_koordinate)::text) AS coords,
    vg.wkb_geometry,
    (
        CASE
            WHEN (cc.color_rgb IS NULL) THEN '96 96 96'::character varying
            ELSE cc.color_rgb
        END)::text AS color_rgb,
    (vf.baseurl || vf.filename) AS url,
    vip.dat_latest_published
   FROM ((((((((altlast.vflz v
     JOIN altlast.vflgeo vg USING (vflz_id))
     JOIN altlast.bere_v b USING (vflz_id))
     JOIN altlast.vflz_is_published_v vip USING (vflz_id))
     JOIN altlast.vflz_filename_v vf USING (vflz_id))
     JOIN ( SELECT DISTINCT lang_prios.vflz_id,
            lang_prios.lang
           FROM ( SELECT vlang.vflz_id,
                    COALESCE(COALESCE(h_plz1.lang, h_plz2.lang), 'de'::character varying) AS lang
                   FROM (((altlast.vflz vlang
                     LEFT JOIN altlast.h_plz h_plz1 ON (((h_plz1.plz)::text = (vlang.vflz_postleitzahl)::text)))
                     LEFT JOIN altlast.h_ort ON ((h_ort.h_gem_id = vlang.h_gem_id)))
                     LEFT JOIN altlast.h_plz h_plz2 ON ((h_ort.postleitzahl = h_plz2.plz)))) lang_prios
          ORDER BY lang_prios.vflz_id) vflz_lang ON ((vflz_lang.vflz_id = v.vflz_id)))
     LEFT JOIN altlast.cod_kbscolor cc ON (((cc.h_bere_res_abwbewe = b.h_bere_res_abwbewe) AND ((cc.c_bere_res_abwbewe)::text = (b.c_bere_res_abwbewe)::text))))
     LEFT JOIN altlast.vflnr vn ON (((vn.vflz_id = v.vflz_id) AND vn.aktiv)))
     LEFT JOIN altlast.org ON ((vn.org_id = org.org_id)))
  WHERE (vip.is_latest_published AND b.kbs);


--
-- Name: VIEW kbs_v; Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON VIEW altlast.kbs_v IS 'Data to be published in the cadastre of polluted sites';


--
-- Name: kbs_verdacht_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.kbs_verdacht_v AS
 SELECT v.vflz_id AS gid,
    v.vflz_id AS id,
    v.x_koordinate,
    v.y_koordinate,
    v.bezeichnung,
    v.vflz_combined_id_kt AS objektnr,
    ( SELECT cod.bezeichnung
           FROM altlast.cod
          WHERE ((cod.c_cli_id = v.h_vflz_vftyp) AND ((cod.code)::text = (v.c_vflz_vftyp)::text))) AS typ,
    v.vflz_strasse,
    v.h_gem_id AS gemeindenr,
    ( SELECT h_gem.gemeinde
           FROM altlast.h_gem
          WHERE (v.h_gem_id = h_gem.h_gem_id)) AS gemeinde,
    ( SELECT altlast.t(altlast.msgid_code(cod.c_cli_id, cod.code), 'de'::text) AS t
           FROM altlast.cod
          WHERE ((cod.c_cli_id = b.h_bere_res_abwbewe) AND ((cod.code)::text = (b.c_bere_res_abwbewe)::text))) AS katrel,
    ( SELECT altlast.t(altlast.msgid_code(cod.c_cli_id, cod.code), 'de'::text) AS t
           FROM altlast.cod
          WHERE ((cod.c_cli_id = v.h_vflz_bearbstand) AND ((cod.code)::text = (v.c_vflz_bearbstand)::text))) AS bearbstand,
    m.ma AS baumass,
    ( SELECT
                CASE v.c_vflz_vftyp
                    WHEN '01'::text THEN ('Ablagerung'::character varying)::text
                    WHEN '03'::text THEN ('Unfall'::character varying)::text
                    ELSE hb.bran_bezeichnung
                END AS bran_bezeichnung) AS branchenbezeichnung,
    ( SELECT
                CASE v.c_vflz_vftyp
                    WHEN '01'::text THEN ('8414'::character varying)::text
                    WHEN '03'::text THEN ('981'::character varying)::text
                    ELSE hb.c_intb_bran
                END AS c_intb_bran) AS branchencode,
    (
        CASE
            WHEN (cc.color_rgb IS NULL) THEN '96 96 96'::character varying
            ELSE cc.color_rgb
        END)::text AS color_rgb,
    public.st_setsrid(public.st_point((v.x_koordinate)::double precision, (v.y_koordinate)::double precision), altlast_admin.setting_get_projection()) AS wkb_geometry,
    vflz.c_vflz_unterstand,
    altlast.killlinebreaks(altlast.t(altlast.msgid_code(cod_vflz_unterstand.c_cli_id, cod_vflz_unterstand.code), 'de'::text)) AS unterstand
   FROM ((((((altlast.vflz_current_v v
     JOIN altlast.vflz USING (vflz_id))
     LEFT JOIN altlast.bere b ON ((b.vflz_id = v.vflz_id)))
     LEFT JOIN ( SELECT array_to_string(array_agg(DISTINCT kbs_hauptbranchen_v.bran_bezeichnung), ', '::text) AS bran_bezeichnung,
            array_to_string(array_agg(DISTINCT kbs_hauptbranchen_v.c_intb_bran), ', '::text) AS c_intb_bran,
            kbs_hauptbranchen_v.vflz_id
           FROM altlast.kbs_hauptbranchen_v
          GROUP BY kbs_hauptbranchen_v.vflz_id) hb ON ((hb.vflz_id = v.vflz_id)))
     LEFT JOIN ( SELECT array_to_string(array_agg(DISTINCT ms1.ms), ', '::text) AS ma,
            ms1.vflz_id
           FROM ( SELECT altlast.t(altlast.msgid_code(mass.h_massnahme, mass.c_massnahme), 'de'::text) AS ms,
                    mass.vflz_id
                   FROM altlast.mass) ms1
          GROUP BY ms1.vflz_id) m ON ((m.vflz_id = v.vflz_id)))
     LEFT JOIN altlast.cod_kbscolor cc ON (((cc.c_bere_res_abwbewe)::text = (
        CASE
            WHEN (b.c_bere_res_abwbewe IS NULL) THEN b.c_bere_res_autobewe
            ELSE b.c_bere_res_abwbewe
        END)::text)))
     LEFT JOIN altlast.cod cod_vflz_unterstand ON (((cod_vflz_unterstand.c_cli_id = vflz.h_vflz_unterstand) AND ((cod_vflz_unterstand.code)::text = (vflz.c_vflz_unterstand)::text))));


