--
-- Name: lookup_bere_res_abwbewe_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.lookup_bere_res_abwbewe_v AS
 SELECT foo.value,
    foo.label,
    foo.sort,
    foo.style,
    foo.class
   FROM ( SELECT altlast.commacat_all((c.code)::text) AS value,
                CASE
                    WHEN (COALESCE(k.kbs, false) = true) THEN 'Belastet'::text
                    ELSE 'Unbelastet'::text
                END AS label,
                CASE
                    WHEN (COALESCE(k.kbs, false) = true) THEN 1000
                    ELSE 2000
                END AS sort,
            NULL::text AS style,
            NULL::text AS class
           FROM (altlast.cod c
             LEFT JOIN altlast.cod_berekbs k ON ((((c.code)::text = (k.c_bere_res_abwbewe)::text) AND (c.c_cli_id = k.h_bere_res_abwbewe))))
          WHERE (c.c_cli_id = 103)
          GROUP BY (COALESCE(k.kbs, false) = true)
        UNION
         SELECT c.code AS value,
            altlast.msgid_code(c.c_cli_id, c.code) AS label,
                CASE
                    WHEN (COALESCE(k.kbs, false) = true) THEN ((COALESCE((c.sort_key)::integer, 0) + 1000) + 1)
                    ELSE ((COALESCE((c.sort_key)::integer, 0) + 2000) + 1)
                END AS sort,
            'padding-left:1em;'::text AS style,
                CASE
                    WHEN c.c_status THEN NULL::text
                    ELSE 'disabled-code'::text
                END AS class
           FROM (altlast.cod c
             LEFT JOIN altlast.cod_berekbs k ON ((((c.code)::text = (k.c_bere_res_abwbewe)::text) AND (c.c_cli_id = k.h_bere_res_abwbewe))))
          WHERE (c.c_cli_id = 103)) foo
  ORDER BY foo.sort;


