--
-- Name: lookup_beziehungsart_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.lookup_beziehungsart_v AS
 SELECT foo.value,
    foo.label,
    foo.sort,
    foo.style
   FROM ( SELECT altlast.commacat_all(((('code.'::text || c.c_cli_id) || '.'::text) || (c.code)::text)) AS value,
                CASE
                    WHEN (COALESCE(k.eigen, false) = true) THEN 'Eingentümer'::text
                    ELSE 'Sonstige'::text
                END AS label,
                CASE
                    WHEN (COALESCE(k.eigen, false) = true) THEN 1000
                    ELSE 2000
                END AS sort,
            NULL::text AS style
           FROM (altlast.cod c
             LEFT JOIN altlast.cod_bezart k ON (((((c.code)::text = (k.subj_category)::text) AND (c.c_cli_id = k.c_cli_id_subj_category)) OR (((c.code)::text = (k.pm_cache_subj)::text) AND (c.c_cli_id = k.c_cli_id_pm_cache_subj)) OR (((c.code)::text = (k.grun_subj)::text) AND (c.c_cli_id = k.c_cli_id_grun_subj)))))
          WHERE ((c.c_cli_id IN ( SELECT cod_bezart.c_cli_id_subj_category
                   FROM altlast.cod_bezart
                UNION
                 SELECT cod_bezart.c_cli_id_pm_cache_subj
                   FROM altlast.cod_bezart
                UNION
                 SELECT cod_bezart.c_cli_id_grun_subj
                   FROM altlast.cod_bezart)) AND (COALESCE(c.c_status, false) = true))
          GROUP BY (COALESCE(k.eigen, false) = true)
        UNION
         SELECT altlast.commacat_all(((('code.'::text || c.c_cli_id) || '.'::text) || (c.code)::text)) AS value,
            altlast.t(altlast.msgid_code(c.c_cli_id, c.code), 'de'::text) AS label,
                CASE
                    WHEN (COALESCE(k.eigen, false) = true) THEN 1001
                    ELSE 2001
                END AS sort,
            'padding-left:1em;'::text AS style
           FROM (altlast.cod c
             LEFT JOIN altlast.cod_bezart k ON (((((c.code)::text = (k.subj_category)::text) AND (c.c_cli_id = k.c_cli_id_subj_category)) OR (((c.code)::text = (k.pm_cache_subj)::text) AND (c.c_cli_id = k.c_cli_id_pm_cache_subj)) OR (((c.code)::text = (k.grun_subj)::text) AND (c.c_cli_id = k.c_cli_id_grun_subj)))))
          WHERE ((c.c_cli_id IN ( SELECT cod_bezart.c_cli_id_subj_category
                   FROM altlast.cod_bezart
                UNION
                 SELECT cod_bezart.c_cli_id_pm_cache_subj
                   FROM altlast.cod_bezart
                UNION
                 SELECT cod_bezart.c_cli_id_grun_subj
                   FROM altlast.cod_bezart)) AND (COALESCE(c.c_status, false) = true))
          GROUP BY (altlast.t(altlast.msgid_code(c.c_cli_id, c.code), 'de'::text)), k.eigen) foo
  ORDER BY foo.sort, foo.label;


