-- Name: export; Type: TABLE; Schema: altlast_admin; Owner: -
--

CREATE TABLE altlast_admin.export (
    export_id integer NOT NULL,
    search_id integer,
    user_id integer,
    filename text,
    created timestamp without time zone DEFAULT now(),
    updated timestamp without time zone,
    name text,
    status character varying(20) DEFAULT 'TODO'::character varying NOT NULL,
    erfassungs_datum timestamp without time zone DEFAULT now(),
    erfasser_kuerzel character varying(8) DEFAULT "current_user"(),
    mutations_datum timestamp without time zone,
    mutierer_kuerzel character varying(8),
    pool_id integer,
    send_notification boolean DEFAULT false,
    CONSTRAINT export_search_status_check CHECK (((status)::text = ANY (ARRAY[('TODO'::character varying)::text, ('DONE'::character varying)::text, ('FAILED'::character varying)::text, ('IN_PROGRESS'::character varying)::text])))
);


