--
-- Name: lookup_gemeinde_bfs_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.lookup_gemeinde_bfs_v AS
 WITH setting AS (
         SELECT setting.value AS kanton
           FROM (altlast_admin.setting
             JOIN altlast_admin.setitem USING (setitem_id))
          WHERE ((setitem.key)::text = 'kanton'::text)
        )
 SELECT h_gem.h_gem_id AS id,
    ((h_gem.gemeinde)::text ||
        CASE
            WHEN (h_gem.bfs_nummer IS NOT NULL) THEN ((' ('::text || lpad((h_gem.bfs_nummer)::text, 4, '0'::text)) || ')'::text)
            ELSE NULL::text
        END) AS option
   FROM altlast.h_gem
  WHERE
        CASE
            WHEN ((( SELECT setting.kanton
               FROM setting))::text <> '-1'::text) THEN ((h_gem.c_kanton)::text = (( SELECT setting.kanton
               FROM setting))::text)
            ELSE (h_gem.h_gem_id IS NOT NULL)
        END
  ORDER BY h_gem.gemeinde;


