-- Name: lookup_postleitzahl_ortsname_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.lookup_postleitzahl_ortsname_v AS
 WITH setting AS (
         SELECT setting.value AS kanton
           FROM (altlast_admin.setting
             JOIN altlast_admin.setitem USING (setitem_id))
          WHERE ((setitem.key)::text = 'kanton'::text)
        )
 SELECT h_ort.h_ort_id AS id,
    ((h_ort.postleitzahl || ' '::text) || (h_ort.ortsname)::text) AS option
   FROM (altlast.h_ort
     JOIN altlast.h_gem USING (h_gem_id))
  WHERE
        CASE
            WHEN ((( SELECT setting.kanton
               FROM setting))::text <> '-1'::text) THEN ((h_gem.c_kanton)::text = (( SELECT setting.kanton
               FROM setting))::text)
            ELSE (h_ort.h_gem_id IS NOT NULL)
        END
  ORDER BY h_ort.postleitzahl, h_ort.ortsname;


