--
-- Name: lookup_tasktitle_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.lookup_tasktitle_v AS
 SELECT altlast.commacat_all((ptp.tas_uid)::text) AS id,
    altlast.pm_content_get((ptp.pro_uid)::text, 'PRO_TITLE'::text) AS option,
    altlast.pm_content_get((ptp.pro_uid)::text, 'PRO_TITLE'::text) AS process_title,
    'process'::text AS type,
    'font-weight: bold;'::text AS style
   FROM altlast.pm_task ptp
  GROUP BY ptp.pro_uid
UNION
 SELECT ptt.tas_uid AS id,
    ('  '::text || altlast.pm_content_get((ptt.tas_uid)::text, 'TAS_TITLE'::text)) AS option,
    altlast.pm_content_get((ptt.pro_uid)::text, 'PRO_TITLE'::text) AS process_title,
    'task'::text AS type,
    'padding-left:12px;'::text AS style
   FROM altlast.pm_task ptt
  ORDER BY 3, 4, 2;


