    altlast.concat_subj((s.name)::text, (s.vorname)::text, NULL::text) AS option
   FROM (altlast.subj s
     JOIN altlast_admin.acl_user u ON ((u.subj_id = s.subj_id)))
  ORDER BY (altlast.concat_subj((s.name)::text, (s.vorname)::text, NULL::text));


