-- Name: pm_cache_subj_eigentuemer_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.pm_cache_subj_eigentuemer_v AS
 SELECT foo.pm_cache_id,
    (((count(foo.subj_kennung))::text || ' Eigentümer: '::text) || altlast.commacat_all(foo.subj_kennung)) AS eigentuemer
   FROM ( SELECT ps.pm_cache_subj_id,
            ps.pm_cache_id,
            ps.subj_id,
            s.subj_kennung
           FROM (altlast.pm_cache_subj ps
             JOIN altlast.subj_kennung_v s USING (subj_id))
          WHERE ((ps.c_pm_cache_subj_bez_art)::text = ANY (ARRAY[('1'::character varying)::text, ('2'::character varying)::text, ('5'::character varying)::text, ('6'::character varying)::text]))
          ORDER BY s.subj_kennung) foo
  GROUP BY foo.pm_cache_id;


