--

CREATE VIEW altlast.pm_cache_subj_fachbuero_v AS
 SELECT foo.pm_cache_id,
    altlast.commacat_all(foo.subj_kennung) AS fachbuero
   FROM ( SELECT ps.pm_cache_subj_id,
            ps.pm_cache_id,
            ps.subj_id,
            s.subj_kennung
           FROM (altlast.pm_cache_subj ps
             JOIN altlast.subj_kennung_v s USING (subj_id))
          WHERE ((ps.c_pm_cache_subj_bez_art)::text = '11'::text)
          ORDER BY s.subj_kennung) foo
  GROUP BY foo.pm_cache_id;


