--
-- Name: pm_cache_subj_sachbearbeiter_subj_ids_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.pm_cache_subj_sachbearbeiter_subj_ids_v AS
 SELECT foo.pm_cache_id,
    foo.subj_id,
    foo.subj_kennung AS sachbearbeiter
   FROM ( SELECT ps.pm_cache_subj_id,
            ps.pm_cache_id,
            ps.subj_id,
            sk.subj_kennung
           FROM (((altlast.pm_cache_subj ps
             JOIN altlast.subj_kennung_v sk USING (subj_id))
             JOIN altlast.subj_category sc ON ((sk.subj_id = sc.subj_id)))
             JOIN altlast.cod_bezart cb ON (((cb.c_cli_id_pm_cache_subj = ps.h_pm_cache_subj_bez_art) AND ((cb.pm_cache_subj)::text = (ps.c_pm_cache_subj_bez_art)::text) AND (NOT ((sc.c_category)::text IS DISTINCT FROM (cb.subj_category)::text)))))
          WHERE ((cb.subj_category)::text = 'bearb'::text)
          ORDER BY sk.subj_kennung) foo;


