--
-- Name: pm_process; Type: TABLE; Schema: altlast; Owner: -
--

CREATE TABLE altlast.pm_process (
    pro_uid character varying(32) NOT NULL
);


--
-- Name: TABLE pm_process; Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON TABLE altlast.pm_process IS 'lists all types of tasks from PM and connects them to their processes. readonly. lists also tasks of subprocesses';


--
-- Name: pm_cache_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.pm_cache_v AS
 SELECT p.pm_cache_id,
    p.pm_vfl_id,
    p.app_uid,
    p.app_thread,
    p.del_index,
    p.usr_uid,
    p.tas_uid,
    p.subj_id,
        CASE
            WHEN ((p.status)::text = 'SLEEPING'::text) THEN NULL::timestamp without time zone
            ELSE p.tas_due_date
        END AS tas_due_date,
    p.tas_finish_date,
    p.tas_delegate_date,
        CASE
            WHEN (((p.status)::text = 'OPEN'::text) AND (p.tas_due_date <= ((((now() + '14 days'::interval))::text)::date)::timestamp without time zone)) THEN true
            ELSE NULL::boolean
        END AS is_due,
    p.status,
        CASE
            WHEN ((p.status)::text = 'OPEN'::text) THEN true
            ELSE false
        END AS is_open,
    p.vflz_id,
    pv.vfl_id,
    COALESCE(tas_title_1.con_value, tas_title_2.con_value, tas_title_3.con_value) AS tas_title,
    pt.pro_uid,
    COALESCE(pro_title_1.con_value, pro_title_2.con_value, pro_title_3.con_value) AS pro_title
   FROM (((((((((altlast.pm_cache p
     LEFT JOIN altlast.pm_vfl pv USING (pm_vfl_id))
     JOIN altlast.pm_task pt USING (tas_uid))
     JOIN altlast.pm_process pp ON (((pt.pro_uid)::text = (pp.pro_uid)::text)))
     LEFT JOIN ( SELECT pc.con_id,
            pc.con_value,
            pc.con_category
           FROM ((altlast.pm_content pc
             JOIN altlast_admin.setting st ON (((pc.con_lang)::text = (st.value)::text)))
             JOIN altlast_admin.setitem si ON ((si.setitem_id = st.setitem_id)))
          WHERE (((si.key)::text = 'language'::text) AND ((pc.con_category)::text = 'TAS_TITLE'::text) AND ((st.role_name)::name = "current_user"()))) tas_title_1 ON (((tas_title_1.con_id)::text = (p.tas_uid)::text)))
     LEFT JOIN ( SELECT pc.con_id,
            pc.con_value,
            2 AS sort_key,
            pc.con_category
           FROM altlast.pm_content pc
          WHERE (((pc.con_lang)::text = 'de'::text) AND ((pc.con_category)::text = 'TAS_TITLE'::text))) tas_title_2 ON (((tas_title_2.con_id)::text = (p.tas_uid)::text)))
     LEFT JOIN ( SELECT pc.con_id,
            pc.con_value,
            3 AS sort_key,
            pc.con_category
           FROM altlast.pm_content pc
          WHERE ((pc.con_category)::text = 'TAS_TITLE'::text)
         LIMIT 1) tas_title_3 ON (((tas_title_3.con_id)::text = (p.tas_uid)::text)))
     LEFT JOIN ( SELECT pc.con_id,
            pc.con_value,
            pc.con_category
           FROM ((altlast.pm_content pc
             JOIN altlast_admin.setting st ON (((pc.con_lang)::text = (st.value)::text)))
             JOIN altlast_admin.setitem si ON ((si.setitem_id = st.setitem_id)))
          WHERE (((si.key)::text = 'language'::text) AND ((pc.con_category)::text = 'PRO_TITLE'::text) AND ((st.role_name)::name = "current_user"()))) pro_title_1 ON (((pro_title_1.con_id)::text = (pt.pro_uid)::text)))
     LEFT JOIN ( SELECT pc.con_id,
            pc.con_value,
            2 AS sort_key,
            pc.con_category
           FROM altlast.pm_content pc
          WHERE (((pc.con_lang)::text = 'de'::text) AND ((pc.con_category)::text = 'PRO_TITLE'::text))) pro_title_2 ON (((pro_title_2.con_id)::text = (pt.pro_uid)::text)))
     LEFT JOIN ( SELECT pc.con_id,
            pc.con_value,
            3 AS sort_key,
            pc.con_category
           FROM altlast.pm_content pc
          WHERE ((pc.con_category)::text = 'PRO_TITLE'::text)
         LIMIT 1) pro_title_3 ON (((pro_title_3.con_id)::text = (pt.pro_uid)::text)));


