    pds.subj_id,
    pds.pm_doc_id,
    pds.h_pm_doc_subj_bez_art,
    pds.c_pm_doc_subj_bez_art,
    pds.erfassungs_datum,
    pds.erfasser_kuerzel,
    pds.mutations_datum,
    pds.mutierer_kuerzel,
    pdsg.grun_id
   FROM (altlast.pm_doc_subj pds
     LEFT JOIN altlast.pm_doc_subj_grun pdsg ON ((pds.pm_doc_subj_id = pdsg.pm_doc_subj_id)));


