--
-- Name: pm_field_values_current_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.pm_field_values_current_v AS
 SELECT pv.vfl_id,
    pv.pro_uid,
    pv.app_uid,
    fv.field_name,
    fv.field_phptype,
    fv.field_value,
    fv.field_value_int,
    fv.field_value_double,
    fv.field_value_timestamp
   FROM (((altlast.pm_vfl pv
     JOIN altlast.pm_cache pc ON ((pc.pm_vfl_id = pv.pm_vfl_id)))
     JOIN ( SELECT pm_cache.pm_vfl_id,
            max(pm_cache.app_thread) AS app_thread,
            max(pm_cache.del_index) AS del_index
           FROM altlast.pm_cache
          GROUP BY pm_cache.pm_vfl_id) latest_pm_cache_version ON (((latest_pm_cache_version.pm_vfl_id = pc.pm_vfl_id) AND (latest_pm_cache_version.app_thread = pc.app_thread) AND (latest_pm_cache_version.del_index = pc.del_index))))
     JOIN altlast.pm_cache_field_values fv ON ((fv.pm_cache_id = pc.pm_cache_id)));


