CREATE TABLE altlast.pm_rule (
    pm_rule_id integer NOT NULL,
    event_name text NOT NULL,
    rule_group text NOT NULL,
    rule_type text NOT NULL,
    "values" text[],
    description text,
    erfassungs_datum timestamp without time zone DEFAULT now(),
    erfasser_kuerzel character varying(8) DEFAULT "current_user"(),
    mutations_datum timestamp without time zone,
    mutierer_kuerzel character varying(8),
    CONSTRAINT pm_rule_rule_group_check CHECK ((rule_group = ANY (ARRAY['CONDITION'::text, 'ACTION'::text])))
);


--
-- Name: TABLE pm_rule; Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON TABLE altlast.pm_rule IS '
implements rules when the user is allowed to perform certain actions.

The rules are based on the constellation of the currently open tasks.
Multiple rules for the same event will be treated like "AND".

CONDITIONS:
 IN_CURRENT_TASKS: one of the currently open tasks equals this tas_uid
 NOT_IN_CURRENT_TASKS: the task is currently not open

ACTIONS:
  FINISH_TASK: will finish the task stored in the value array
';


