--
-- Name: pm_translations_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.pm_translations_v AS
 SELECT DISTINCT foo2.msgid,
    foo2.msgstr,
    foo2.locale
   FROM ( SELECT ((pm_cache.tas_uid)::text || ':TAS_TITLE'::text) AS msgid,
            altlast.pm_content_get((pm_cache.tas_uid)::text, 'TAS_TITLE'::text, lang.locale) AS msgstr,
            lang.locale
           FROM (altlast.pm_cache
             JOIN ( SELECT 'de'::text AS locale
                UNION
                 SELECT 'fr'::text AS text
                UNION
                 SELECT 'it'::text AS text) lang ON (true))) foo2
  WHERE (NOT (foo2.msgid IN ( SELECT translations.msgid
           FROM altlast.translations)));


