--
-- Name: pm_vfl_subj_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.pm_vfl_subj_v AS
 SELECT pmc.pm_vfl_id,
    pcsv.subj_id,
    pcsv.h_pm_cache_subj_bez_art AS h_bez_art,
    pcsv.c_pm_cache_subj_bez_art AS c_bez_art,
    pcsv.grun_id
   FROM (altlast.pm_cache pmc
     JOIN altlast.pm_cache_subj_v pcsv ON ((pcsv.pm_cache_id = pmc.pm_cache_id)))
UNION
 SELECT pmc.pm_vfl_id,
    pdsv.subj_id,
    pdsv.h_pm_doc_subj_bez_art AS h_bez_art,
    pdsv.c_pm_doc_subj_bez_art AS c_bez_art,
    pdsv.grun_id
   FROM ((altlast.pm_cache pmc
     JOIN altlast.pm_doc pd ON ((pd.pm_cache_id = pmc.pm_cache_id)))
     JOIN altlast.pm_doc_subj_v pdsv ON ((pdsv.pm_doc_id = pd.pm_doc_id)))
UNION
 SELECT pmc.pm_vfl_id,
    bsv.subj_id,
    bsv.h_bem_subj_bez_art AS h_bez_art,
    bsv.c_bem_subj_bez_art AS c_bez_art,
    bsv.grun_id
   FROM (((altlast.bem_subj_v bsv
     JOIN altlast.bem b ON ((bsv.bem_id = b.bem_id)))
     JOIN altlast.bemgrp bg ON (((bg.bemgrp_id = b.bemgrp_id) AND ((bg.bemgrp)::text = 'pm_cache'::text))))
     JOIN altlast.pm_cache pmc ON ((pmc.pm_cache_id = b.key_value)));


