--
-- Name: qs_done_investigations_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.qs_done_investigations_v AS
 SELECT max(v.vflz_id) AS vflz_id,
    altlast.t('Alle Voruntersuchungen abgeschlossen'::text) AS reason,
    v.vflz_combined_id_kt
   FROM (((altlast.vflz_current_v v
     JOIN altlast.bere b USING (vflz_id))
     JOIN ( SELECT foo.vflz_combined_id_kt
           FROM ( SELECT v_1.vflz_id,
                    v_1.vflz_combined_id_kt,
                    pm_cache_v.status,
                    max((pm_cache_v.status)::text) AS max_status
                   FROM (altlast.pm_cache_v
                     JOIN altlast.vflz v_1 USING (vfl_id))
                  WHERE (pm_cache_v.pro_title ~~ 'AltL. 03 Voruntersuchung %'::text)
                  GROUP BY v_1.vflz_id, v_1.vflz_combined_id_kt, pm_cache_v.status
                  ORDER BY pm_cache_v.status DESC) foo
          WHERE (foo.max_status = 'CLOSED'::text)) pm_done USING (vflz_combined_id_kt))
     JOIN ( SELECT foo.vflz_combined_id_kt
           FROM ( SELECT v_1.vflz_combined_id_kt,
                    b_1.c_bere_res_abwbewe
                   FROM (altlast.vflz v_1
                     JOIN altlast.bere b_1 USING (vflz_id))
                  WHERE (altlast.t(altlast.msgid_code(b_1.h_bere_res_abwbewe, b_1.c_bere_res_abwbewe), 'de'::text) = 'Belastet, untersuchungsbedürftig'::text)
                  GROUP BY v_1.vflz_combined_id_kt, b_1.c_bere_res_abwbewe) foo) bere_status USING (vflz_combined_id_kt))
  WHERE (altlast.t(altlast.msgid_code(b.h_bere_res_abwbewe, b.c_bere_res_abwbewe), 'de'::text) <> 'Belastet, untersuchungsbedürftig'::text)
  GROUP BY v.vflz_combined_id_kt;


--
-- Name: VIEW qs_done_investigations_v; Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON VIEW altlast.qs_done_investigations_v IS 'Looks for locations with done investigations';


--
-- Name: qs_done_reconstructions_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.qs_done_reconstructions_v AS
 SELECT max(v.vflz_id) AS vflz_id,
    altlast.t('Sanierung abgeschlossen'::text) AS reason,
    v.vflz_combined_id_kt
   FROM (((altlast.vflz_current_v v
     JOIN altlast.bere b USING (vflz_id))
     JOIN ( SELECT foo.vflz_combined_id_kt
           FROM ( SELECT v_1.vflz_id,
                    v_1.vflz_combined_id_kt,
                    pm_cache_v.status,
                    max((pm_cache_v.status)::text) AS max_status
                   FROM (altlast.pm_cache_v
                     JOIN altlast.vflz v_1 USING (vfl_id))
                  WHERE (pm_cache_v.pro_title ~~ 'AltL. 04% Sanierung %'::text)
                  GROUP BY v_1.vflz_id, pm_cache_v.status, v_1.vflz_combined_id_kt
                  ORDER BY pm_cache_v.status DESC) foo
          WHERE (foo.max_status = 'CLOSED'::text)) pm USING (vflz_combined_id_kt))
     JOIN ( SELECT foo.vflz_combined_id_kt
           FROM ( SELECT v_1.vflz_combined_id_kt,
                    b_1.c_bere_res_abwbewe
                   FROM (altlast.vflz v_1
                     JOIN altlast.bere b_1 USING (vflz_id))
                  WHERE (altlast.t(altlast.msgid_code(b_1.h_bere_res_abwbewe, b_1.c_bere_res_abwbewe), 'de'::text) = 'Belastet, sanierungsbedürftig'::text)
                  GROUP BY v_1.vflz_combined_id_kt, b_1.c_bere_res_abwbewe) foo) bere_status USING (vflz_combined_id_kt))
  WHERE (altlast.t(altlast.msgid_code(b.h_bere_res_abwbewe, b.c_bere_res_abwbewe), 'de'::text) <> 'Belastet, sanierungsbedürftig'::text)
  GROUP BY v.vflz_combined_id_kt;


--
-- Name: VIEW qs_done_reconstructions_v; Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON VIEW altlast.qs_done_reconstructions_v IS 'Looks for locations with done reconstructions';


--
-- Name: qs_duplicated_combined_id_kt_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.qs_duplicated_combined_id_kt_v AS
 SELECT vflz_current_v.vflz_id,
    (altlast.t('Doppelte Standort-Nummer: '::text) || (vflz_current_v.vflz_combined_id_kt)::text) AS reason
   FROM altlast.vflz_current_v
  WHERE ((vflz_current_v.vflz_combined_id_kt)::text IN ( SELECT vflz_current_v_1.vflz_combined_id_kt
           FROM altlast.vflz_current_v vflz_current_v_1
          GROUP BY vflz_current_v_1.vflz_combined_id_kt
         HAVING (count(*) > 1)));


--
-- Name: VIEW qs_duplicated_combined_id_kt_v; Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON VIEW altlast.qs_duplicated_combined_id_kt_v IS 'Looks for duplicated location numbers';


--
-- Name: qs_duplicated_geometry; Type: MATERIALIZED VIEW; Schema: altlast; Owner: -
--

CREATE MATERIALIZED VIEW altlast.qs_duplicated_geometry AS
 SELECT DISTINCT v1.vflz_id,
    row_number() OVER (ORDER BY v1.vflz_id) AS qs_id,
    (altlast.t('Identische Geometrie wie '::text) || (v2.vflz_combined_id_kt)::text) AS reason
   FROM (((altlast.vflz_current_v v1
     JOIN altlast.vflgeo g1 ON ((v1.vflz_id = g1.vflz_id)))
     JOIN altlast.vflgeo g2 ON ((public.st_isvalid(g1.wkb_geometry) AND public.st_isvalid(g2.wkb_geometry) AND public.st_equals(g1.wkb_geometry, g2.wkb_geometry) AND (g1.vflz_id <> g2.vflz_id))))
     JOIN altlast.vflz_current_v v2 ON ((v2.vflz_id = g2.vflz_id)))
  WITH NO DATA;


--
-- Name: qs_duplicated_geometry_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.qs_duplicated_geometry_v AS
 SELECT qs_duplicated_geometry.vflz_id,
    qs_duplicated_geometry.reason
   FROM altlast.qs_duplicated_geometry;


--
-- Name: VIEW qs_duplicated_geometry_v; Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON VIEW altlast.qs_duplicated_geometry_v IS 'Looks for duplicated geometries';


--
-- Name: qs_duplicated_number_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.qs_duplicated_number_v AS
 SELECT DISTINCT v1.vflz_id,
    (altlast.t('Redundante Nummer '::text) || (n1.nummer)::text) AS reason
   FROM (((altlast.vflz_current_v v1
     JOIN altlast.vflnr n1 ON ((v1.vflz_id = n1.vflz_id)))
     JOIN altlast.vflnr n2 ON ((((n1.nummer)::text = (n2.nummer)::text) AND (n2.vflz_id <> n1.vflz_id))))
     JOIN altlast.vflz_current_v v2 ON ((n2.vflz_id = v2.vflz_id)))
  ORDER BY (altlast.t('Redundante Nummer '::text) || (n1.nummer)::text);


--
-- Name: VIEW qs_duplicated_number_v; Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON VIEW altlast.qs_duplicated_number_v IS 'Looks for duplicated location numbers across organizations';


--
-- Name: qs_duplicated_titles_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.qs_duplicated_titles_v AS
 SELECT DISTINCT vflz_current_v.vflz_id,
    altlast.t('Doppelte Bezeichnung'::text) AS reason
   FROM altlast.vflz_current_v
  WHERE ((vflz_current_v.bezeichnung)::text IN ( SELECT vflz_current_v_1.bezeichnung
           FROM altlast.vflz_current_v vflz_current_v_1
          GROUP BY vflz_current_v_1.bezeichnung
         HAVING (count(*) > 1)));


--
-- Name: VIEW qs_duplicated_titles_v; Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON VIEW altlast.qs_duplicated_titles_v IS 'Looks for duplicated location titles';


--
-- Name: qs_geomoverlaps_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.qs_geomoverlaps_v AS
 SELECT DISTINCT v.vflz_id
   FROM (((altlast.vflz_current_v v
     JOIN altlast.vflgeo g ON ((g.vflz_id = v.vflz_id)))
     JOIN altlast.vflz_current_v v2 ON ((((v.c_vflz_vftyp)::text = (v2.c_vflz_vftyp)::text) AND (v.vflz_id <> v2.vflz_id) AND v.rechtskraft)))
     JOIN altlast.vflgeo g2 ON (((g2.vflz_id = v2.vflz_id) AND (g.wkb_geometry OPERATOR(public.&&) g2.wkb_geometry) AND public.st_intersects(g.wkb_geometry, g2.wkb_geometry))))
  WHERE (public.st_isvalid(g.wkb_geometry) AND public.st_isvalid(g2.wkb_geometry))
  ORDER BY v.vflz_id;


--
-- Name: VIEW qs_geomoverlaps_v; Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON VIEW altlast.qs_geomoverlaps_v IS 'test for intersection of geometries of standorte of same type in the cadastre';


--
-- Name: qs_invalid_geometries_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.qs_invalid_geometries_v AS
 SELECT DISTINCT v.vflz_id,
    public.st_isvalidreason(g.wkb_geometry) AS st_isvalidreason
   FROM (altlast.vflz_current_v v
     JOIN altlast.vflgeo g USING (vflz_id))
  WHERE (NOT public.st_isvalid(g.wkb_geometry));


--
-- Name: VIEW qs_invalid_geometries_v; Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON VIEW altlast.qs_invalid_geometries_v IS 'Looks for invalid geometries';


--
-- Name: qs_invalid_gws_codes_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.qs_invalid_gws_codes_v AS
 SELECT DISTINCT ON (error.vflz_id) error.vflz_id,
    error.reason
   FROM ( SELECT v.vflz_id,
                CASE
                    WHEN (v.h_vflz_gws_bereich IS NULL) THEN ('Codeliste unbekannt für Code '::text || (v.c_vflz_gws_bereich)::text)
                    ELSE ((('Ungültiger Code '::text || (v.c_vflz_gws_bereich)::text) || ' für Codeliste '::text) || v.h_vflz_gws_bereich)
                END AS reason
           FROM altlast.vflz v
          WHERE ((NOT ((v.c_vflz_gws_bereich)::text IN ( SELECT c.code
                   FROM altlast.cod c
                  WHERE (v.h_vflz_gws_bereich = c.c_cli_id)))) AND (v.c_vflz_gws_bereich IS NOT NULL))
        UNION
         SELECT vflz.vflz_id,
            (('Codeliste '::text || vflz.h_vflz_gws_bereich) || ' ist nicht länger gültig'::text) AS reason
           FROM altlast.vflz
          WHERE ((vflz.c_vflz_gws_bereich IS NOT NULL) AND (vflz.h_vflz_gws_bereich IS NOT NULL) AND (vflz.h_vflz_gws_bereich <> 10017))) error;


--
-- Name: VIEW qs_invalid_gws_codes_v; Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON VIEW altlast.qs_invalid_gws_codes_v IS 'Lists all invalid codes for „Gewässerschutzbereich“. Invalid means codes not matching their code list or outdated code lists';


--
-- Name: qs_mandatory_fields_cached_v; Type: TABLE; Schema: altlast; Owner: -
--

CREATE TABLE altlast.qs_mandatory_fields_cached_v (
    vflz_id integer NOT NULL,
