--
-- Name: TABLE qs_mandatory_fields_cached_v; Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON TABLE altlast.qs_mandatory_fields_cached_v IS 'Materialized version of altlast.qs_mandatory_fields_v. Contained data is maintained by a background task (Altlast_Cron_Plugin_ReindexRequiredFields).';


