--
-- Name: searchfield; Type: TABLE; Schema: altlast_admin; Owner: -
--

CREATE TABLE altlast_admin.searchfield (
    searchfield_id integer NOT NULL,
    label character varying,
    width integer,
    fld_type character varying,
    lookup character varying,
    search_type character varying,
    sort integer DEFAULT 0,
    rel_name character varying,
    col character varying,
    col_output character varying,
    searchfieldgroup_id integer,
    c_cli_id integer,
    rel_alt character varying,
    col_alt character varying,
    special_icon character varying,
    translate_output boolean DEFAULT false NOT NULL,
    fts boolean DEFAULT false NOT NULL,
    erfassungs_datum timestamp without time zone DEFAULT now(),
    erfasser_kuerzel character varying(8) DEFAULT "current_user"(),
    mutations_datum timestamp without time zone,
    mutierer_kuerzel character varying(8),
    searchfield_ident bigint
);


--
-- Name: TABLE searchfield; Type: COMMENT; Schema: altlast_admin; Owner: -
--

COMMENT ON TABLE altlast_admin.searchfield IS 'Contains information on how to display search fields in the GUI. A standard GUI search field may refer to more than one database field.
Dont forget your entry in searchfield_searchcategory!';


