COMMENT ON COLUMN altlast_admin.searchfield.label IS 'label shown in search forms';


--
-- Name: COLUMN searchfield.width; Type: COMMENT; Schema: altlast_admin; Owner: -
--

COMMENT ON COLUMN altlast_admin.searchfield.width IS 'width of search field in pixels';


--
-- Name: COLUMN searchfield.fld_type; Type: COMMENT; Schema: altlast_admin; Owner: -
--

COMMENT ON COLUMN altlast_admin.searchfield.fld_type IS 'searchfield type, for example text field, checkbox, or user defined type';


--
-- Name: COLUMN searchfield.lookup; Type: COMMENT; Schema: altlast_admin; Owner: -
--

COMMENT ON COLUMN altlast_admin.searchfield.lookup IS 'name of a view containing options, used for example for fld_type value list';


--
-- Name: COLUMN searchfield.search_type; Type: COMMENT; Schema: altlast_admin; Owner: -
