-- Name: COLUMN searchfield.searchfield_ident; Type: COMMENT; Schema: altlast_admin; Owner: -
--

COMMENT ON COLUMN altlast_admin.searchfield.searchfield_ident IS 'Generated , attribute-based ID of a searchfield to attempt to correlate searchfield from different clients.

Issue #4110040';


--
-- Name: qs_mandatory_fields_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.qs_mandatory_fields_v AS
 SELECT invalids.vflz_id,
    (altlast.t('Ungültig: '::text) || altlast.commacat_all(invalids.label)) AS reason
   FROM ( SELECT vflz_current_v.vflz_id,
            COALESCE(altlast.t((searchfield.label)::text), (((validation.table_name)::text || '.'::text) || (validation.column_name)::text)) AS label
           FROM ((( SELECT fields.h_bere_res_abwbewe,
                    fields.c_bere_res_abwbewe,
                    fields.fields[fields.i][1] AS table_name,
                    fields.fields[fields.i][2] AS column_name
                   FROM ( SELECT cr.h_bere_res_abwbewe,
                            cr.c_bere_res_abwbewe,
                            generate_series(array_lower(cr.fields, 1), array_upper(cr.fields, 1)) AS i,
                            cr.fields
                           FROM altlast.cod_required cr) fields) validation
             CROSS JOIN altlast.vflz_current_v)
             LEFT JOIN altlast_admin.searchfield ON ((((searchfield.rel_name)::text = ('altlast.'::text || (validation.table_name)::text)) AND ((searchfield.col)::name = validation.column_name))))
          WHERE ((NOT ((validation.table_name = 'dummy'::name) AND (validation.column_name = 'dummy'::name))) AND (altlast.required_field_valid(vflz_current_v.vflz_id, validation.h_bere_res_abwbewe, validation.c_bere_res_abwbewe, (validation.table_name)::text, validation.column_name,
                CASE
                    WHEN ((validation.table_name = 'vflnr'::name) AND (validation.column_name = 'aktiv'::name)) THEN 'vflnr_active_defined'::text
                    WHEN ((validation.table_name = 'dummy'::name) AND (validation.column_name = 'bav_number'::name)) THEN 'bav_number_present'::text
                    WHEN ((validation.table_name = 'dummy'::name) AND (validation.column_name = 'non_bav_number'::name)) THEN 'non_bav_number_present'::text
                    WHEN ((validation.table_name = 'dummy'::name) AND (validation.column_name = 'betreiber'::name)) THEN 'betreiber_present'::text
                    WHEN ((validation.table_name = 'dummy'::name) AND (validation.column_name = 'eigen'::name)) THEN 'eigen_present'::text
                    WHEN (validation.table_name = ANY (ARRAY['inta'::name, 'kksk'::name])) THEN 'any_filled_inta'::text
                    WHEN ((validation.table_name = 'vflz'::name) AND (validation.column_name = 'c_vflz_inbetrieb'::name)) THEN 'any_filled_inta'::text
                    WHEN ((validation.table_name = 'vflz'::name) AND (validation.column_name = 'c_vflz_deponietyp'::name)) THEN 'vflz_inbetrieb_ja'::text
                    WHEN ((validation.table_name = 'vflz'::name) AND (validation.column_name = 'c_vflz_nachsorge'::name)) THEN 'vflz_inbetrieb_nein'::text
                    WHEN (validation.table_name = 'intb'::name) THEN 'any_filled_intb'::text
                    WHEN (validation.table_name = ANY (ARRAY['intu'::name, 'inum'::name])) THEN 'any_filled_intu'::text
                    ELSE 'any_filled'::text
                END) = false))) invalids
  GROUP BY invalids.vflz_id;


--
-- Name: VIEW qs_mandatory_fields_v; Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON VIEW altlast.qs_mandatory_fields_v IS 'Lists locations for which mandatory fields are not filled out correctly.';


--
-- Name: qs_missing_geometry_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.qs_missing_geometry_v AS
 SELECT vflz_current_v.vflz_id
   FROM altlast.vflz_current_v
  WHERE (NOT (vflz_current_v.vflz_id IN ( SELECT vflgeo.vflz_id
           FROM altlast.vflgeo)));


--
-- Name: VIEW qs_missing_geometry_v; Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON VIEW altlast.qs_missing_geometry_v IS 'Looks for locations without geometries';


--
-- Name: qs_missing_h_gem_id_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.qs_missing_h_gem_id_v AS
 SELECT vflz_current_v.vflz_id
   FROM altlast.vflz_current_v
  WHERE (vflz_current_v.h_gem_id IS NULL);


--
-- Name: VIEW qs_missing_h_gem_id_v; Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON VIEW altlast.qs_missing_h_gem_id_v IS 'Looks for locations without communities set';


--
-- Name: qs_pmformfield_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.qs_pmformfield_v AS
 SELECT vflz.vflz_id,
    (((altlast.t('Fehlende Felder bei Geschäft "'::text) || altlast.pm_content_get((pmv.pro_uid)::text, 'PRO_TITLE'::text)) || '": '::text) || altlast.commacat_all(pf.label)) AS reason
   FROM (((altlast.pm_formfieldqs pfq
     JOIN altlast.pm_formfield pf ON ((pf.pm_formfield_id = pfq.pm_formfield_id)))
     JOIN altlast.pm_vfl pmv ON ((pfq.pm_vfl_id = pmv.pm_vfl_id)))
     JOIN altlast.vflz_current_v vflz ON ((vflz.vfl_id = pmv.vfl_id)))
  WHERE (pfq.is_empty AND pf.required)
  GROUP BY vflz.vflz_id, pmv.pm_vfl_id, pmv.pro_uid;


--
-- Name: qs_wrong_h_gem_id_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.qs_wrong_h_gem_id_v AS
 SELECT v.vflz_id,
    altlast.t('Falsche Gemeinde'::text) AS reason,
    v.vflz_combined_id_kt
   FROM (((altlast.vflz_current_v v
     JOIN altlast.vflgeo o USING (vflz_id))
     LEFT JOIN altlast._gemeinden g ON ((public.st_isvalid(o.wkb_geometry) AND public.st_isvalid(g.wkb_geometry) AND public.st_intersects(o.wkb_geometry, g.wkb_geometry) AND (COALESCE(v.h_gem_id, 0) = g.bfs_nr))))
     LEFT JOIN altlast.h_gem h USING (h_gem_id))
  WHERE (public.st_isvalid(o.wkb_geometry) AND (g.bfs_nr IS NULL));


--
-- Name: VIEW qs_wrong_h_gem_id_v; Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON VIEW altlast.qs_wrong_h_gem_id_v IS 'Looks for locations with communities or cantons different form coummity geometries';


--
-- Name: qs_wrong_postal_code_or_town; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.qs_wrong_postal_code_or_town AS
 SELECT vflz_current_v.vflz_id,
    ((((COALESCE(((vflz_current_v.vflz_postleitzahl)::text || ' '::text), ''::text) || COALESCE(((vflz_current_v.vflz_ort)::text || ' '::text), ''::text)) || altlast.t('nicht in Gemeinde'::text)) || ' '::text) || (h_gem.gemeinde)::text) AS reason
   FROM (altlast.vflz_current_v
     JOIN altlast.h_gem USING (h_gem_id))
  WHERE ((NOT (vflz_current_v.vflz_id IN ( SELECT vflz.vflz_id
           FROM (altlast.vflz
             JOIN altlast.h_ort ON ((((vflz.vflz_postleitzahl)::text = (h_ort.postleitzahl)::text) AND ((vflz.vflz_ort)::text = (h_ort.ortsname)::text))))))) AND ((vflz_current_v.vflz_postleitzahl IS NOT NULL) OR (vflz_current_v.vflz_ort IS NOT NULL)));


--
-- Name: report_documents_bl_xml_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.report_documents_bl_xml_v AS
 SELECT pm_doc.pm_doc_id,
    pm_vfl.vfl_id,
    pm_doc.app_doc_category,
    xmlagg(XMLELEMENT(NAME document, XMLATTRIBUTES(pm_doc.pm_doc_id AS pm_doc_id), XMLELEMENT(NAME document_title, pm_doc.app_doc_title), XMLELEMENT(NAME document_category, altlast.t(altlast.msgid_code(10022, (pm_doc.app_doc_category)::character varying))), XMLELEMENT(NAME document_create_date, ((pm_doc.app_doc_create_date)::date)::text), XMLELEMENT(NAME document_receipt_date, ((pm_doc.app_doc_receipt_date)::date)::text), XMLELEMENT(NAME authors, ( SELECT xmlagg(authors.author) AS xmlagg
           FROM ( SELECT xmlagg(XMLELEMENT(NAME author, XMLATTRIBUTES(subj.vorname AS vorname, subj.name AS name), XMLELEMENT(NAME document_author_subj_kennung, pm_doc_author.subj_kennung), XMLELEMENT(NAME document_author_ort, doc_author_adr.ort))) AS author
                   FROM ((((altlast.pm_doc_subj pm_doc_subj
                     JOIN altlast.subj ON ((pm_doc_subj.subj_id = subj.subj_id)))
                     LEFT JOIN altlast.subj_kennung_v pm_doc_author ON ((pm_doc_author.subj_id = pm_doc_subj.subj_id)))
                     LEFT JOIN altlast.subj_adr doc_author_subj_adr ON ((doc_author_subj_adr.subj_id = pm_doc_author.subj_id)))
                     LEFT JOIN altlast.adr doc_author_adr ON ((doc_author_adr.adr_id = doc_author_subj_adr.adr_id)))
                  WHERE ((pm_doc_subj.pm_doc_id = pm_doc.pm_doc_id) AND (pm_doc_subj.h_pm_doc_subj_bez_art = 2) AND ((pm_doc_subj.c_pm_doc_subj_bez_art)::text = '13'::text))
                  GROUP BY pm_doc_author.subj_id) authors)))) AS document
   FROM ((altlast.pm_vfl
     LEFT JOIN altlast.pm_cache ON ((pm_cache.pm_vfl_id = pm_vfl.pm_vfl_id)))
     LEFT JOIN altlast.pm_doc ON ((pm_doc.pm_cache_id = pm_cache.pm_cache_id)))
  GROUP BY pm_vfl.vfl_id, pm_doc.pm_doc_id, pm_doc.app_doc_category, pm_doc.app_doc_create_date
 HAVING (pm_doc.pm_doc_id IS NOT NULL)
  ORDER BY pm_doc.app_doc_create_date DESC;


--
-- Name: report_documents_xml_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.report_documents_xml_v AS
SELECT
    NULL::integer AS pm_doc_id,
    NULL::integer AS vfl_id,
    NULL::text AS app_doc_category,
    NULL::xml AS document,
    NULL::timestamp without time zone AS app_doc_receipt_date;


--
-- Name: VIEW report_documents_xml_v; Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON VIEW altlast.report_documents_xml_v IS 'Documents and their authors as XML fragment for use in reports.';


--
-- Name: report_eigentuemer_parz; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.report_eigentuemer_parz AS
 SELECT v.vflz_id,
    sv.subj_id,
    altlast.commacat_all(DISTINCT (g.gb_nummer)::text) AS grundstueck_nr,
    altlast.commacat_all((bb.bem)::text) AS commacat_all
   FROM ((((altlast.vflz v
     JOIN altlast.subj_vflz sv ON ((v.vflz_id = sv.vflz_id)))
     LEFT JOIN altlast.subj_vflz_grun svg ON ((sv.subj_vflz_id = svg.subj_vflz_id)))
     LEFT JOIN altlast.grun g ON ((svg.grun_id = g.grun_id)))
     LEFT JOIN ( SELECT b.key_value,
            b.bem
           FROM altlast.bem b
          WHERE (b.bemgrp_id = 11)) bb ON ((bb.key_value = svg.subj_vflz_id)))
  GROUP BY v.vflz_id, sv.subj_id, sv.c_subj_vflz_bez_art, sv.subj_vflz_id;


--
-- Name: report_jasper_additional_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.report_jasper_additional_v AS
 SELECT vflz.vflz_id,
    lang.language,
        CASE
            WHEN ((altlast.t(altlast.msgid_code(COALESCE(vflz.h_vflz_gws_bereich, 10017), vflz.c_vflz_gws_bereich), (lang.language)::text) IS NULL) OR (altlast.t(altlast.msgid_code(COALESCE(vflz.h_vflz_gws_bereich, 10017), vflz.c_vflz_gws_bereich), (lang.language)::text) = ''::text)) THEN '-'::text
            ELSE altlast.t(altlast.msgid_code(COALESCE(vflz.h_vflz_gws_bereich, 10017), vflz.c_vflz_gws_bereich), (lang.language)::text)
        END AS gwsbereich,
        CASE
            WHEN ((altlast.t(altlast.msgid_code(COALESCE(vflz.h_vflz_gws_zone, 10018), vflz.c_vflz_gws_zone), (lang.language)::text) IS NULL) OR (altlast.t(altlast.msgid_code(COALESCE(vflz.h_vflz_gws_zone, 10018), vflz.c_vflz_gws_zone), (lang.language)::text) = ''::text)) THEN '-'::text
            ELSE altlast.t(altlast.msgid_code(COALESCE(vflz.h_vflz_gws_zone, 10018), vflz.c_vflz_gws_zone), (lang.language)::text)
        END AS gwszone,
        CASE
            WHEN ((altlast.t(altlast.msgid_code(COALESCE(vflz.h_vflz_karstgeb, 80), vflz.c_vflz_karstgeb), (lang.language)::text) IS NULL) OR (altlast.t(altlast.msgid_code(COALESCE(vflz.h_vflz_karstgeb, 80), vflz.c_vflz_karstgeb), (lang.language)::text) = ''::text)) THEN '-'::text
            ELSE altlast.t(altlast.msgid_code(COALESCE(vflz.h_vflz_karstgeb, 80), vflz.c_vflz_karstgeb), (lang.language)::text)
        END AS karstgebiet,
        CASE
            WHEN ((altlast.t(altlast.msgid_code(COALESCE(vflz.h_vflz_durchlaessigkeit, 58), vflz.c_vflz_durchlaessigkeit), (lang.language)::text) IS NULL) OR (altlast.t(altlast.msgid_code(COALESCE(vflz.h_vflz_durchlaessigkeit, 58), vflz.c_vflz_durchlaessigkeit), (lang.language)::text) = ''::text)) THEN '-'::text
            ELSE altlast.t(altlast.msgid_code(COALESCE(vflz.h_vflz_durchlaessigkeit, 58), vflz.c_vflz_durchlaessigkeit), (lang.language)::text)
        END AS durchlaessigkeit,
        CASE
            WHEN ((altlast.t(altlast.msgid_code(report_gwvk_v.h_gwvk_relzugw, report_gwvk_v.c_gwvk_relzugw), (lang.language)::text) IS NULL) OR (altlast.t(altlast.msgid_code(report_gwvk_v.h_gwvk_relzugw, report_gwvk_v.c_gwvk_relzugw), (lang.language)::text) = ''::text)) THEN '-'::text
            ELSE altlast.t(altlast.msgid_code(report_gwvk_v.h_gwvk_relzugw, report_gwvk_v.c_gwvk_relzugw), (lang.language)::text)
        END AS flurabstand,
        CASE
            WHEN ((gwnu.gwnu_distanz)::text IS NULL) THEN '-'::text
            ELSE (gwnu.gwnu_distanz)::text
        END AS gwnu_distanz,
        CASE
            WHEN ((altlast.t(altlast.msgid_code(gwnu.h_gwnu_nutzung, gwnu.c_gwnu_nutzung), (lang.language)::text) IS NULL) OR (altlast.t(altlast.msgid_code(gwnu.h_gwnu_nutzung, gwnu.c_gwnu_nutzung), (lang.language)::text) = ''::text)) THEN '-'::text
            ELSE altlast.t(altlast.msgid_code(gwnu.h_gwnu_nutzung, gwnu.c_gwnu_nutzung), (lang.language)::text)
        END AS gwnu_nutzung,
        CASE
            WHEN ((report_ogw_v.ogw_name IS NULL) OR ((report_ogw_v.ogw_name)::text = ''::text)) THEN '-'::character varying
            ELSE report_ogw_v.ogw_name
        END AS ogw_name,
        CASE
            WHEN ((report_ogw_v.ogw_distanz)::text IS NULL) THEN '-'::text
            ELSE (report_ogw_v.ogw_distanz)::text
        END AS ogw_distanz
   FROM ((((altlast.vflz
     LEFT JOIN altlast.report_gwvk_v ON ((report_gwvk_v.vflz_id = vflz.vflz_id)))
     LEFT JOIN altlast.gwnu ON ((gwnu.vflz_id = vflz.vflz_id)))
     LEFT JOIN altlast.report_ogw_v ON ((report_ogw_v.vflz_id = vflz.vflz_id)))
     CROSS JOIN ( SELECT translations.locale AS language
           FROM altlast.translations
          GROUP BY translations.locale) lang)
  GROUP BY vflz.vflz_id, lang.language, vflz.h_vflz_gws_bereich, vflz.c_vflz_gws_bereich, vflz.h_vflz_gws_zone, vflz.c_vflz_gws_zone, vflz.h_vflz_karstgeb, vflz.c_vflz_karstgeb, vflz.h_vflz_durchlaessigkeit, vflz.c_vflz_durchlaessigkeit, report_gwvk_v.h_gwvk_relzugw, report_gwvk_v.c_gwvk_relzugw, gwnu.gwnu_distanz, gwnu.h_gwnu_nutzung, gwnu.c_gwnu_nutzung, report_ogw_v.ogw_name, report_ogw_v.ogw_distanz;


--
-- Name: report_jasper_doc_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.report_jasper_doc_v AS
 SELECT pm_doc.pm_doc_id,
    pm_vfl.vfl_id,
    pm_doc.app_doc_category,
    pm_doc.app_doc_title,
    altlast.t(altlast.msgid_code(10022, (pm_doc.app_doc_category)::character varying)) AS document_category,
    (pm_doc.app_doc_create_date)::date AS app_doc_create_date,
    (pm_doc.app_doc_receipt_date)::date AS app_doc_receipt_date,
    subj.vorname,
    subj.name,
    pm_doc_author.subj_kennung,
    doc_author_adr.ort,
        CASE
            WHEN (pm_doc_author.subj_kennung IS NOT NULL) THEN concat(pm_doc_author.subj_kennung, ', ', doc_author_adr.ort)
            WHEN ((subj.name IS NULL) AND (subj.vorname IS NULL) AND (pm_doc_author.subj_kennung IS NOT NULL)) THEN concat(pm_doc_author.subj_kennung, ', ', doc_author_adr.ort)
            WHEN ((subj.name IS NOT NULL) AND (subj.vorname IS NOT NULL) AND (pm_doc_author.subj_kennung IS NULL)) THEN concat(subj.vorname, ' ', subj.name, ', ', doc_author_adr.ort)
            WHEN ((subj.name IS NOT NULL) AND (subj.vorname IS NULL) AND (pm_doc_author.subj_kennung IS NULL)) THEN concat(subj.name, ', ', doc_author_adr.ort)
            WHEN ((subj.name IS NULL) AND (subj.vorname IS NULL) AND (pm_doc_author.subj_kennung IS NULL)) THEN NULL::text
            ELSE concat(subj.vorname, ' ', subj.name, ', ', pm_doc_author.subj_kennung, ', ', doc_author_adr.ort)
        END AS author
   FROM (((((((altlast.pm_vfl
     LEFT JOIN altlast.pm_cache ON ((pm_cache.pm_vfl_id = pm_vfl.pm_vfl_id)))
     LEFT JOIN altlast.pm_doc ON ((pm_doc.pm_cache_id = pm_cache.pm_cache_id)))
     LEFT JOIN altlast.pm_doc_subj ON (((pm_doc_subj.pm_doc_id = pm_doc.pm_doc_id) AND (pm_doc_subj.h_pm_doc_subj_bez_art = 2) AND ((pm_doc_subj.c_pm_doc_subj_bez_art)::text = '13'::text))))
     LEFT JOIN altlast.subj ON ((pm_doc_subj.subj_id = subj.subj_id)))
     LEFT JOIN altlast.subj_kennung_v pm_doc_author ON ((pm_doc_author.subj_id = pm_doc_subj.subj_id)))
     LEFT JOIN altlast.subj_adr doc_author_subj_adr ON ((doc_author_subj_adr.subj_id = pm_doc_author.subj_id)))
     LEFT JOIN altlast.adr doc_author_adr ON ((doc_author_adr.adr_id = doc_author_subj_adr.adr_id)))
  WHERE (pm_doc.app_doc_category = '07'::text);


--
-- Name: report_jasper_massnahme_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.report_jasper_massnahme_v AS
 SELECT mass.vflz_id,
    lang.language,
        CASE
            WHEN (mass.c_massnahme IS NULL) THEN '-'::text
            ELSE altlast.t(altlast.msgid_code(mass.h_massnahme, mass.c_massnahme), (lang.language)::text)
        END AS massnahme,
    (mass.ang_massnahme)::text AS ang_massnahme,
    mass.dat_massnahme,
        CASE
            WHEN (bem_v.bem IS NULL) THEN '-'::character varying
            ELSE bem_v.bem
        END AS bem
   FROM ((altlast.mass
     LEFT JOIN altlast.bem_v ON (((bem_v.key_value = mass.mass_id) AND ((bem_v.bemgrp)::text = 'mass.mass_id'::text))))
     CROSS JOIN ( SELECT translations.locale AS language
           FROM altlast.translations
          GROUP BY translations.locale) lang);


--
-- Name: report_jasper_nubo_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.report_jasper_nubo_v AS
 SELECT report_nubo_v.vflz_id,
    lang.language,
        CASE
            WHEN (report_nubo_v.c_nubo_nutzungsart IS NULL) THEN '-'::text
            ELSE altlast.t(altlast.msgid_code(COALESCE(report_nubo_v.h_nubo_nutzungsart, 87), report_nubo_v.c_nubo_nutzungsart), (lang.language)::text)
        END AS nubo_nutzungsart,
        CASE
            WHEN (report_nubo_v.c_nubo_akt_nutzung IS NULL) THEN '-'::text
            WHEN ((report_nubo_v.c_nubo_akt_nutzung)::text = '-1'::text) THEN '-'::text
            ELSE altlast.t(altlast.msgid_code(report_nubo_v.h_nubo_akt_nutzung, report_nubo_v.c_nubo_akt_nutzung), (lang.language)::text)
        END AS nubo_akt_nutzung
   FROM (altlast.report_nubo_v
     CROSS JOIN ( SELECT translations.locale AS language
           FROM altlast.translations
          GROUP BY translations.locale) lang);


--
-- Name: report_jasper_sanierbere_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.report_jasper_sanierbere_v AS
 SELECT bere.vflz_id,
    lang.language,
        CASE
            WHEN ((bere.bere_prio_sanier)::text IS NULL) THEN '-'::text
            ELSE (bere.bere_prio_sanier)::text
        END AS bere_prio_sanier,
        CASE
            WHEN (bem_begr_prio_sanier.bem IS NULL) THEN '-'::character varying
            ELSE bem_begr_prio_sanier.bem
        END AS bem
   FROM (((altlast.bere
     LEFT JOIN altlast.bem_v bem_abwbewe ON (((bem_abwbewe.key_value = bere.vflz_id) AND ((bem_abwbewe.bemgrp)::text = 'bere_begr_abwbewe'::text))))
     LEFT JOIN altlast.bem_v bem_begr_prio_sanier ON (((bem_begr_prio_sanier.key_value = bere.vflz_id) AND ((bem_begr_prio_sanier.bemgrp)::text = 'bere_begr_prio_sanier'::text))))
     CROSS JOIN ( SELECT translations.locale AS language
           FROM altlast.translations
          GROUP BY translations.locale) lang)
  WHERE ((bere.bere_prio_sanier IS NOT NULL) OR (bem_begr_prio_sanier.bem IS NOT NULL));


--
-- Name: report_jasper_saniziel_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.report_jasper_saniziel_v AS
 SELECT bere.vflz_id,
    lang.language,
        CASE
            WHEN (sani.c_saniziel IS NULL) THEN '-'::text
            ELSE altlast.t(altlast.msgid_code(sani.h_saniziel, sani.c_saniziel), (lang.language)::text)
        END AS saniziel,
        CASE
            WHEN (bem_v.bem IS NULL) THEN '-'::character varying
            ELSE bem_v.bem
        END AS bem
   FROM (((altlast.bere
     LEFT JOIN altlast.sani ON ((sani.vflz_id = bere.vflz_id)))
     LEFT JOIN altlast.bem_v ON (((bem_v.key_value = sani.sani_id) AND ((bem_v.bemgrp)::text = 'sani.sani_id'::text))))
     CROSS JOIN ( SELECT translations.locale AS language
           FROM altlast.translations
          GROUP BY translations.locale) lang)
  WHERE ((sani.h_saniziel IS NOT NULL) OR (sani.c_saniziel IS NOT NULL) OR (bem_v.bem IS NOT NULL));


--
-- Name: report_jasper_veen_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.report_jasper_veen_v AS
 SELECT veen.vflz_id,
    lang.language,
    veen.veen_datum,
        CASE
            WHEN (veen.c_veen_natuerlich IS NULL) THEN '-'::text
            ELSE altlast.t(altlast.msgid_code(veen.h_veen_natuerlich, veen.c_veen_natuerlich), (lang.language)::text)
        END AS veen_natuerlich,
        CASE
            WHEN (bem_v.bem IS NULL) THEN '-'::character varying
            ELSE bem_v.bem
        END AS bem
   FROM ((altlast.veen
     LEFT JOIN altlast.bem_v ON (((bem_v.key_value = veen.veen_id) AND ((bem_v.bemgrp)::text = 'veen.veen_id'::text))))
     CROSS JOIN ( SELECT translations.locale AS language
           FROM altlast.translations
          GROUP BY translations.locale) lang);


--
-- Name: report_jasper_vfus_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.report_jasper_vfus_v AS
 SELECT vfus.vflz_id,
    lang.language,
    altlast.msgid_code(COALESCE(vfus.h_vfus_art_schaden, 101), vfus.c_vfus_art_schaden) AS vfus_art_schaden_msgid,
        CASE
            WHEN (vfus.c_vfus_art_schaden IS NULL) THEN '-'::text
            ELSE altlast.t(altlast.msgid_code(COALESCE(vfus.h_vfus_art_schaden, 101), vfus.c_vfus_art_schaden), (lang.language)::text)
        END AS vfus_art_schaden,
        CASE
            WHEN (vfus.c_vfus_schaeden IS NULL) THEN '-'::text
            ELSE altlast.t(altlast.msgid_code(vfus.h_vfus_schaeden, vfus.c_vfus_schaeden), (lang.language)::text)
        END AS vfus_schaeden,
        CASE
            WHEN (bem_v.bem IS NULL) THEN '-'::character varying
            ELSE bem_v.bem
        END AS bem
   FROM ((altlast.vfus
     LEFT JOIN altlast.bem_v ON (((bem_v.key_value = vfus.vfus_id) AND ((bem_v.bemgrp)::text = 'vfus.vfus_id'::text))))
     CROSS JOIN ( SELECT translations.locale AS language
           FROM altlast.translations
          GROUP BY translations.locale) lang)
  ORDER BY vfus.vflz_id;


--
-- Name: rpt_param; Type: TABLE; Schema: altlast; Owner: -
--

CREATE TABLE altlast.rpt_param (
    param_id integer NOT NULL,
    bezeichnung character varying(50),
    tag character varying(20),
    datentyp character varying(20),
    lookup character varying(50),
    standardwert text,
    sortierung integer DEFAULT 0,
    erfassungs_datum timestamp without time zone DEFAULT now(),
    erfasser_kuerzel character varying(8) DEFAULT "current_user"(),
    mutations_datum timestamp without time zone,
    mutierer_kuerzel character varying(8)
);


--
-- Name: COLUMN rpt_param.bezeichnung; Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON COLUMN altlast.rpt_param.bezeichnung IS 'Name für den Parameter. Zur verwendung für den Benutzer';


--
-- Name: COLUMN rpt_param.tag; Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON COLUMN altlast.rpt_param.tag IS 'Tagname für den Parameter. Der Parameter wird im erzeugten XML unter /report/params/[tag] geführt';


--
-- Name: COLUMN rpt_param.datentyp; Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON COLUMN altlast.rpt_param.datentyp IS 'Der Datentyp wird nicht von reportgen selbst benötigt, sondern wurde für die Benutzeroberfläche der eigentlich Applikation aufgenommen';


--
-- Name: COLUMN rpt_param.lookup; Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON COLUMN altlast.rpt_param.lookup IS 'Nicht von reportgen selbst benötigt. Für Applikation';


--
-- Name: COLUMN rpt_param.standardwert; Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON COLUMN altlast.rpt_param.standardwert IS 'Standardwert für den Parameter. Falls der Parameter nicht definert ist, wird er hiermit durch reportgen vervollständigt. Der Wert "now()" wird dynamisch als das aktuelle Datum interpretiert.';


--
-- Name: COLUMN rpt_param.sortierung; Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON COLUMN altlast.rpt_param.sortierung IS 'Die Sortierung wird wiederum nur von der Benutzerobefläche der Applikation verwendet';


--
-- Name: report_jasper_base_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.report_jasper_base_v AS
 SELECT v.vflz_id,
    lang.language,
    vflz.vfl_id,
    vflz.vflz_combined_id_kt AS standortnummer,
        CASE
            WHEN (vflz.bezeichnung IS NULL) THEN '-'::character varying
            ELSE vflz.bezeichnung
        END AS bezeichnung,
        CASE
            WHEN ((altlast.t(altlast.msgid_code(v.h_vflz_vftyp, v.c_vflz_vftyp), (lang.language)::text) IS NULL) OR (altlast.t(altlast.msgid_code(v.h_vflz_vftyp, v.c_vflz_vftyp), (lang.language)::text) = ''::text)) THEN '-'::text
            ELSE altlast.t(altlast.msgid_code(v.h_vflz_vftyp, v.c_vflz_vftyp), (lang.language)::text)
        END AS standorttyp,
        CASE
            WHEN (vflz.x_koordinate IS NULL) THEN '-'::text
            ELSE (vflz.x_koordinate)::text
        END AS x_koordinate,
        CASE
            WHEN (vflz.y_koordinate IS NULL) THEN '-'::text
            ELSE (vflz.y_koordinate)::text
        END AS y_koordinate,
        CASE
            WHEN ((vflz.vflz_strasse IS NULL) OR ((vflz.vflz_strasse)::text = ''::text)) THEN ('-'::text)::character varying
            ELSE vflz.vflz_strasse
        END AS vflz_strasse,
        CASE
            WHEN ((vflz.vflz_flurname IS NULL) OR ((vflz.vflz_flurname)::text = ''::text)) THEN ('-'::text)::character varying
            ELSE vflz.vflz_flurname
        END AS vflz_flurname,
    vflz.vflz_postleitzahl,
    h_gem.bfs_nummer,
    v.owner_org,
    vflz.vflz_ort,
    altlast.t(altlast.msgid_code(v.h_vflz_bearbstand, v.c_vflz_bearbstand), (lang.language)::text) AS bearbeitungsstand,
        CASE
            WHEN ((v.gemeinde IS NULL) OR ((v.gemeinde)::text = ''::text)) THEN '-'::character varying
            ELSE v.gemeinde
        END AS gemeinde,
    v.bemerkungen,
    replace(to_char(altlast.bestscalefactor(public.st_buffer(vflgeo.wkb_geometry, (50)::double precision), (17.0)::double precision, (14.56)::double precision), '9G999'::text), ','::text, ''''::text) AS wms_scale,
    altlast.queryextent(altlast.scaleextent(public.st_buffer(vflgeo.wkb_geometry, (50)::double precision), (17.0)::double precision, (17.0)::double precision)) AS wms_extent,
    (((layerasused.url || '&BBOX='::text) || altlast.queryextent(altlast.scaleextent(public.st_buffer(vflgeo.wkb_geometry, (50)::double precision), (17.0)::double precision, (17.0)::double precision))) || '&WIDTH=1000&HEIGHT=1000'::text) AS background_url,
    (((((kbs.url || '&VFLZ='::text) || v.vflz_id) || '&BBOX='::text) || altlast.queryextent(altlast.scaleextent(public.st_buffer(vflgeo.wkb_geometry, (50)::double precision), (17.0)::double precision, (17.0)::double precision))) || '&WIDTH=1000&HEIGHT=1000'::text) AS kbs_url,
    vflz.dat_rechtskraft,
    ( SELECT vflz_is_published_v.dat_latest_published
           FROM altlast.vflz_is_published_v
          WHERE ((vflz_is_published_v.vflz_id IN ( SELECT vflz_any_in_vfl.vflz_id
                   FROM altlast.vflz vflz_any_in_vfl
                  WHERE (vflz_any_in_vfl.vfl_id = vflz.vfl_id))) AND vflz_is_published_v.is_latest_published)) AS dat_publizieren,
    bere.c_bere_res_abwbewe,
        CASE
            WHEN ((altlast.t(altlast.msgid_code(bere.h_bere_res_abwbewe, bere.c_bere_res_abwbewe), (lang.language)::text) IS NULL) OR (altlast.t(altlast.msgid_code(bere.h_bere_res_abwbewe, bere.c_bere_res_abwbewe), (lang.language)::text) = ''::text)) THEN '-'::text
            ELSE altlast.t(altlast.msgid_code(bere.h_bere_res_abwbewe, bere.c_bere_res_abwbewe), (lang.language)::text)
        END AS bewertung,
    altlast.t(altlast.msgid_code(10104, bere.c_bere_res_abwbewe), (lang.language)::text) AS rechtlicher_bezug,
    altlast.t(altlast.msgid_code(10105, bere.c_bere_res_abwbewe), (lang.language)::text) AS handlungsbedarf,
        CASE
            WHEN (vfus.vflz_id IS NOT NULL) THEN true
            ELSE false
        END AS vfus_true,
        CASE
            WHEN (vfus_gw.vflz_id IS NOT NULL) THEN true
            ELSE false
        END AS vfus_gw_true,
        CASE
            WHEN (vfus_ogw.vflz_id IS NOT NULL) THEN true
            ELSE false
        END AS vfus_ogw_true,
        CASE
            WHEN (vfus_b.vflz_id IS NOT NULL) THEN true
            ELSE false
        END AS vfus_b_true,
        CASE
            WHEN (vfus_l.vflz_id IS NOT NULL) THEN true
            ELSE false
        END AS vfus_l_true,
        CASE
            WHEN (vfus_einw.vflz_id IS NOT NULL) THEN true
            ELSE false
        END AS vfus_einw_true,
        CASE
            WHEN (nubo.vflz_id IS NOT NULL) THEN true
            ELSE false
        END AS nubo_true,
        CASE
            WHEN (doc.vfl_id IS NOT NULL) THEN true
            ELSE false
        END AS doc_true,
        CASE
            WHEN (veen.vflz_id IS NOT NULL) THEN true
            ELSE false
        END AS veen_true,
        CASE
            WHEN (mass.vflz_id IS NOT NULL) THEN true
            ELSE false
        END AS mass_true,
        CASE
            WHEN (sani_bere.vflz_id IS NOT NULL) THEN true
            ELSE false
        END AS sani_bere_true,
        CASE
            WHEN (sani_ziel.vflz_id IS NOT NULL) THEN true
            ELSE false
        END AS sani_ziel_true
   FROM (((((((((((((((((((altlast.vflz vflz
     JOIN altlast.report_grunddaten_v v ON ((vflz.vflz_id = v.vflz_id)))
     CROSS JOIN ( SELECT translations.locale AS language
           FROM altlast.translations
          GROUP BY translations.locale) lang)
     LEFT JOIN altlast.h_gem ON ((h_gem.h_gem_id = vflz.h_gem_id)))
     LEFT JOIN altlast.vflgeo vflgeo ON ((vflgeo.vflz_id = v.vflz_id)))
     LEFT JOIN altlast.bere bere ON ((bere.vflz_id = v.vflz_id)))
     CROSS JOIN ( SELECT rpt_param.standardwert AS url
           FROM altlast.rpt_param
          WHERE ((rpt_param.tag)::text = 'layerAsUsed'::text)) layerasused)
     CROSS JOIN ( SELECT rpt_param.standardwert AS url
           FROM altlast.rpt_param
          WHERE ((rpt_param.tag)::text = 'kbslayer'::text)) kbs)
     LEFT JOIN ( SELECT report_jasper_vfus_v.vflz_id
           FROM altlast.report_jasper_vfus_v
          GROUP BY report_jasper_vfus_v.vflz_id) vfus ON ((vfus.vflz_id = vflz.vflz_id)))
     LEFT JOIN ( SELECT report_jasper_vfus_v.vflz_id
           FROM altlast.report_jasper_vfus_v
          WHERE (report_jasper_vfus_v.vfus_art_schaden_msgid = 'code.101.02'::text)
          GROUP BY report_jasper_vfus_v.vflz_id) vfus_gw ON ((vfus_gw.vflz_id = vflz.vflz_id)))
     LEFT JOIN ( SELECT report_jasper_vfus_v.vflz_id
           FROM altlast.report_jasper_vfus_v
          WHERE (report_jasper_vfus_v.vfus_art_schaden_msgid = 'code.101.03'::text)
          GROUP BY report_jasper_vfus_v.vflz_id) vfus_ogw ON ((vfus_ogw.vflz_id = vflz.vflz_id)))
     LEFT JOIN ( SELECT report_jasper_vfus_v.vflz_id
           FROM altlast.report_jasper_vfus_v
          WHERE (report_jasper_vfus_v.vfus_art_schaden_msgid = 'code.101.05'::text)
          GROUP BY report_jasper_vfus_v.vflz_id) vfus_b ON ((vfus_b.vflz_id = vflz.vflz_id)))
     LEFT JOIN ( SELECT report_jasper_vfus_v.vflz_id
           FROM altlast.report_jasper_vfus_v
          WHERE (report_jasper_vfus_v.vfus_art_schaden_msgid = 'code.101.04'::text)
          GROUP BY report_jasper_vfus_v.vflz_id) vfus_l ON ((vfus_l.vflz_id = vflz.vflz_id)))
     LEFT JOIN ( SELECT report_jasper_vfus_v.vflz_id
           FROM altlast.report_jasper_vfus_v
          WHERE ((report_jasper_vfus_v.vfus_schaeden <> '-'::text) OR ((report_jasper_vfus_v.bem)::text <> '-'::text))
          GROUP BY report_jasper_vfus_v.vflz_id) vfus_einw ON ((vfus_einw.vflz_id = vflz.vflz_id)))
     LEFT JOIN ( SELECT report_jasper_nubo_v.vflz_id
           FROM altlast.report_jasper_nubo_v
          GROUP BY report_jasper_nubo_v.vflz_id) nubo ON ((nubo.vflz_id = vflz.vflz_id)))
     LEFT JOIN ( SELECT report_jasper_doc_v.vfl_id
           FROM altlast.report_jasper_doc_v
          GROUP BY report_jasper_doc_v.vfl_id) doc ON ((doc.vfl_id = vflz.vfl_id)))
     LEFT JOIN ( SELECT report_jasper_veen_v.vflz_id
           FROM altlast.report_jasper_veen_v
          GROUP BY report_jasper_veen_v.vflz_id) veen ON ((veen.vflz_id = vflz.vflz_id)))
     LEFT JOIN ( SELECT report_jasper_massnahme_v.vflz_id
           FROM altlast.report_jasper_massnahme_v
          GROUP BY report_jasper_massnahme_v.vflz_id) mass ON ((mass.vflz_id = vflz.vflz_id)))
     LEFT JOIN ( SELECT report_jasper_sanierbere_v.vflz_id
           FROM altlast.report_jasper_sanierbere_v
          GROUP BY report_jasper_sanierbere_v.vflz_id) sani_bere ON ((sani_bere.vflz_id = vflz.vflz_id)))
     LEFT JOIN ( SELECT report_jasper_saniziel_v.vflz_id
           FROM altlast.report_jasper_saniziel_v
          GROUP BY report_jasper_saniziel_v.vflz_id) sani_ziel ON ((sani_ziel.vflz_id = vflz.vflz_id)));


--
-- Name: report_jasper_examination_bl_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.report_jasper_examination_bl_v AS
 SELECT vflz.vflz_id,
    ( SELECT (pm_cache_v.tas_finish_date)::date AS tas_finish_date
           FROM altlast.pm_cache_v
          WHERE (((pm_cache_v.vfl_id = vflz.vfl_id) AND ((pm_cache_v.pro_uid)::text = '9968655694cf66cae7a0ca4081874979'::text) AND ((pm_cache_v.tas_uid)::text = '1945967324cf66dc6414422064165975'::text)) OR ((pm_cache_v.vfl_id = vflz.vfl_id) AND ((pm_cache_v.pro_uid)::text = '00671b9584b044ac9287aae8e26d23eb'::text) AND ((pm_cache_v.tas_uid)::text = '208210bd37c1463b9a5a02631ad5a9ae'::text)))
          ORDER BY pm_cache_v.status, pm_cache_v.tas_finish_date DESC
         LIMIT 1) AS hist_voruntersuchung,
    ( SELECT (pm_cache_v.tas_finish_date)::date AS tas_finish_date
           FROM altlast.pm_cache_v
          WHERE (((pm_cache_v.vfl_id = vflz.vfl_id) AND ((pm_cache_v.pro_uid)::text = '9968655694cf66cae7a0ca4081874979'::text) AND ((pm_cache_v.tas_uid)::text = '1518928124cfb41e111da07024401490'::text)) OR ((pm_cache_v.vfl_id = vflz.vfl_id) AND ((pm_cache_v.pro_uid)::text = '00671b9584b044ac9287aae8e26d23eb'::text) AND ((pm_cache_v.tas_uid)::text = 'c8ffea73df7f4bc69220c9c3755332e9'::text)))
          ORDER BY pm_cache_v.status, pm_cache_v.tas_finish_date DESC
         LIMIT 1) AS techn_voruntersuchung,
    ( SELECT (pm_cache_v.tas_finish_date)::date AS tas_finish_date
           FROM altlast.pm_cache_v
          WHERE (((pm_cache_v.vfl_id = vflz.vfl_id) AND ((pm_cache_v.pro_uid)::text = '3325376984dd3d784d92321083161229'::text) AND ((pm_cache_v.tas_uid)::text = '7864449164dd3db329fa002000688408'::text)) OR ((pm_cache_v.vfl_id = vflz.vfl_id) AND ((pm_cache_v.pro_uid)::text = '9356e665da6847e886ed636b543756d8'::text) AND ((pm_cache_v.tas_uid)::text = 'c2ac59d3c3b542e8b0e08ef2ee59d047'::text)))
          ORDER BY pm_cache_v.status, pm_cache_v.tas_finish_date DESC
         LIMIT 1) AS detailuntersuchung,
    ( SELECT (pm_cache_v.tas_finish_date)::date AS tas_finish_date
           FROM altlast.pm_cache_v
          WHERE (((pm_cache_v.vfl_id = vflz.vfl_id) AND ((pm_cache_v.pro_uid)::text = '7007438844d80827c2b3024047513405'::text)) OR ((pm_cache_v.vfl_id = vflz.vfl_id) AND ((pm_cache_v.pro_uid)::text = 'd92df770807e46caafc36e68d4e7a808'::text)))
          ORDER BY pm_cache_v.status, pm_cache_v.tas_finish_date DESC
         LIMIT 1) AS ueberwachung,
    ( SELECT (pm_cache_v.tas_finish_date)::date AS tas_finish_date
           FROM altlast.pm_cache_v
          WHERE (((pm_cache_v.vfl_id = vflz.vfl_id) AND ((pm_cache_v.pro_uid)::text = '3325376984dd3d784d92321083161229'::text) AND ((pm_cache_v.tas_uid)::text = '7036041434dd3eabd672eb9006519031'::text)) OR ((pm_cache_v.vfl_id = vflz.vfl_id) AND ((pm_cache_v.pro_uid)::text = 'c07c22d5d1934bf68726a32b531b047e'::text) AND ((pm_cache_v.tas_uid)::text = '69b4642dba604a89a94778407fd672a6'::text)) OR ((pm_cache_v.vfl_id = vflz.vfl_id) AND ((pm_cache_v.pro_uid)::text = 'cb7f29eca12546f491683ec4d5ceb524'::text) AND ((pm_cache_v.tas_uid)::text = 'ff5bef49c65347128eb27cfbe21a9f75'::text)))
          ORDER BY pm_cache_v.status, pm_cache_v.tas_finish_date DESC
         LIMIT 1) AS sanierung
   FROM altlast.vflz;


--
-- Name: report_jasper_inta_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.report_jasper_inta_v AS
 SELECT report_kksk_v.vflz_id,
    lang.language,
        CASE
            WHEN (report_kksk_v.kksk_teilvol = (0)::double precision) THEN 'unbekannt'::text
            WHEN ((report_kksk_v.kksk_teilvol)::text IS NULL) THEN '-'::text
            ELSE (report_kksk_v.kksk_teilvol)::text
        END AS kksk_teilvol,
        CASE
            WHEN (report_kksk_v.c_kksk_stoffkl IS NULL) THEN '-'::text
            ELSE altlast.t(altlast.msgid_code(report_kksk_v.h_kksk_stoffkl, report_kksk_v.c_kksk_stoffkl), (lang.language)::text)
        END AS stoffklasse,
    concat(
        CASE
            WHEN ((date_part('year'::text, kksk.kksk_ablag_von))::text IS NULL) THEN 'unbekannt'::text
            ELSE (date_part('year'::text, kksk.kksk_ablag_von))::text
        END, ' - ',
        CASE
            WHEN kksk.zeitraum_bisheute THEN 'heute'::text
            ELSE (date_part('year'::text, kksk.kksk_ablag_bis))::text
        END) AS ablag_zeitraum
   FROM ((altlast.report_kksk_v
     JOIN altlast.kksk kksk ON ((kksk.kksk_id = report_kksk_v.kksk_id)))
     CROSS JOIN ( SELECT translations.locale AS language
           FROM altlast.translations
          GROUP BY translations.locale) lang)
  ORDER BY report_kksk_v.vflz_id;


--
-- Name: report_jasper_intb_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.report_jasper_intb_v AS
 SELECT report_intb_v.vflz_id,
    lang.language,
    intb.relevant,
        CASE
            WHEN (report_intb_v.intb_firma_name IS NULL) THEN '-'::character varying
            ELSE report_intb_v.intb_firma_name
        END AS intb_firma_name,
        CASE
            WHEN (report_intb_v.c_intb_bran_bezeichnung IS NULL) THEN '-'::text
            ELSE altlast.t(report_intb_v.c_intb_bran_bezeichnung, (lang.language)::text)
        END AS intb_bran_bezeichnung,
    concat(
        CASE
            WHEN ((date_part('year'::text, intb.intb_vonbetrieb))::text IS NULL) THEN 'unbekannt'::text
            ELSE (date_part('year'::text, intb.intb_vonbetrieb))::text
        END, ' - ',
        CASE
            WHEN intb.zeitraum_bisheute THEN 'heute'::text
            ELSE (date_part('year'::text, intb.intb_bisbetrieb))::text
        END) AS betrieb_zeitraum
   FROM ((altlast.report_intb_v
     JOIN altlast.intb ON ((report_intb_v.intb_id = intb.intb_id)))
     CROSS JOIN ( SELECT translations.locale AS language
           FROM altlast.translations
          GROUP BY translations.locale) lang)
  WHERE intb.relevant
  ORDER BY report_intb_v.vflz_id;


--
-- Name: report_jasper_intu_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.report_jasper_intu_v AS
 SELECT inum.inum_id,
    report_intu_v.vflz_id,
    lang.language,
    (report_intu_v.intu_unfallvon)::date AS intu_unfallvon,
        CASE
            WHEN (inum.c_inum_stoffe IS NULL) THEN '-'::text
            ELSE altlast.t(altlast.msgid_code(inum.h_inum_stoffe, inum.c_inum_stoffe), (lang.language)::text)
        END AS intu_stoffe,
        CASE
            WHEN ((inum.inum_stoffmng)::text IS NULL) THEN '-'::text
            ELSE (inum.inum_stoffmng)::text
        END AS inum_stoffmng
   FROM ((altlast.report_intu_v
     JOIN altlast.inum ON ((report_intu_v.intu_id = inum.intu_id)))
     CROSS JOIN ( SELECT translations.locale AS language
           FROM altlast.translations
          GROUP BY translations.locale) lang)
  ORDER BY report_intu_v.vflz_id;


--
-- Name: report_jasper_jahresbericht_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.report_jasper_jahresbericht_v AS
 SELECT altlast.t(altlast.msgid_code(v.h_vflz_vftyp, v.c_vflz_vftyp), 'de'::text) AS standorttyp,
    v.vflz_combined_id_kt AS standortnummer,
    v.bezeichnung,
        CASE
            WHEN ((org_aktiv_v.bezeichnung)::text = 'BAV'::text) THEN 'BAV'::text
            ELSE 'andere'::text
        END AS vollzug,
    altlast.t(altlast.msgid_code(bere.h_bere_res_abwbewe, bere.c_bere_res_abwbewe), 'de'::text) AS beurteilung,
        CASE
            WHEN ((bere.c_bere_res_abwbewe)::text = ANY (ARRAY[('02'::character varying)::text, ('03'::character varying)::text, ('BAV70'::character varying)::text, ('BAV71'::character varying)::text, ('BAV81'::character varying)::text])) THEN 'Belastet'::text
            WHEN ((bere.c_bere_res_abwbewe)::text = ANY (ARRAY[('01'::character varying)::text])) THEN 'unbelastet'::text
            WHEN (bere.c_bere_res_abwbewe IS NULL) THEN 'Beurteilung ausstehend'::text
            ELSE altlast.t(altlast.msgid_code(bere.h_bere_res_abwbewe, bere.c_bere_res_abwbewe), 'de'::text)
        END AS kategorie_beurteilung,
    altlast.t(altlast.msgid_code(v.h_vflz_bearbstand, v.c_vflz_bearbstand), 'de'::text) AS bearbeitungsstand,
    altlast.t(altlast.msgid_code(v.h_vflz_unterstand, v.c_vflz_unterstand), 'de'::text) AS untersuchungsstand,
    vflz.dat_rechtskraft AS datum_ersteintrag,
    1 AS summe
   FROM (((altlast.vflz_current_v v
     LEFT JOIN altlast.vflz USING (vflz_id))
     LEFT JOIN altlast.org_aktiv_v USING (vflz_id))
     LEFT JOIN altlast.bere USING (vflz_id));


--
-- Name: vflz_parzellen_materialization_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.vflz_parzellen_materialization_v AS
 SELECT DISTINCT foo.vflz_id,
    foo.h_gem_id,
    foo.grun_id,
    foo.gb_nummer
   FROM ( SELECT v.vflz_id,
            g.h_gem_id,
            g.grun_id,
            g.gb_nummer
           FROM (altlast.grun g
             JOIN altlast.vflgeo v ON ((public.st_isvalid(v.wkb_geometry) AND public.st_isvalid(g.wkb_geometry) AND public.st_intersects(v.wkb_geometry, g.wkb_geometry) AND public.st_intersects(public.st_buffer(public.st_setsrid(v.wkb_geometry, altlast_admin.setting_get_projection()), ('-1'::integer)::double precision), g.wkb_geometry))))
          WHERE g.c_status
        UNION
         SELECT sv.vflz_id,
            g.h_gem_id,
            g.grun_id,
            g.gb_nummer
           FROM ((altlast.subj_vflz sv
             JOIN altlast.subj_vflz_grun svg USING (subj_vflz_id))
             JOIN altlast.grun g ON ((svg.grun_id = g.grun_id)))
          WHERE g.c_status) foo
  ORDER BY foo.vflz_id, foo.h_gem_id, foo.gb_nummer;


--
-- Name: VIEW vflz_parzellen_materialization_v; Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON VIEW altlast.vflz_parzellen_materialization_v IS 'prepares and aggregates vflz_parzellen_v content for materialization. used by materialize functions/triggers.';


--
-- Name: report_jasper_parzellen_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.report_jasper_parzellen_v AS
 SELECT vpm.vflz_id,
    vpm.h_gem_id,
    h_gem.gemeinde,
    altlast.commacat_all((vpm.gb_nummer)::text) AS parzellen
   FROM (altlast.vflz_parzellen_materialization_v vpm
     JOIN altlast.h_gem USING (h_gem_id))
  GROUP BY vpm.h_gem_id, vpm.vflz_id, h_gem.gemeinde;


--
-- Name: report_jasper_pm_open_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.report_jasper_pm_open_v AS
 SELECT pmc.pm_cache_id,
    pmc.vflz_id,
    vflz.bezeichnung,
    vflz.vflz_combined_id_kt,
    pro_name.con_value AS pro_name,
    tas_name.con_value AS tas_name,
    concat(subj.name, ' ', subj.vorname) AS bearbeiter,
    pm_cache_subj_sachbearbeiter_v.sachbearbeiter AS zugewiesener_sachbearbeiter,
    pmc.tas_init_date AS letztebearbeitung,
    pmc.tas_due_date
   FROM ((((((altlast.pm_cache pmc
     LEFT JOIN altlast.pm_content tas_name ON ((((tas_name.con_id)::text = (pmc.tas_uid)::text) AND ((tas_name.con_lang)::text = 'de'::text))))
     LEFT JOIN altlast.pm_vfl ON ((pmc.pm_vfl_id = pm_vfl.pm_vfl_id)))
     LEFT JOIN altlast.pm_content pro_name ON ((((pro_name.con_id)::text = (pm_vfl.pro_uid)::text) AND ((pro_name.con_lang)::text = 'de'::text))))
     LEFT JOIN altlast.pm_cache_subj_sachbearbeiter_v ON ((pm_cache_subj_sachbearbeiter_v.pm_cache_id = pmc.pm_cache_id)))
     LEFT JOIN altlast.subj ON ((pmc.subj_id = subj.subj_id)))
     LEFT JOIN altlast.vflz ON ((vflz.vflz_id = pmc.vflz_id)))
  WHERE (((pmc.status)::text = 'OPEN'::text) AND (vflz.vflz_combined_id_kt IS NOT NULL))
  ORDER BY (concat(subj.name, ' ', subj.vorname)), pmc.tas_due_date DESC, pmc.tas_init_date;


--
-- Name: report_jasper_processes; Type: TABLE; Schema: altlast; Owner: -
--

CREATE TABLE altlast.report_jasper_processes (
    tas_title text,
    count bigint,
    label text
);


--
-- Name: vfl_pool; Type: TABLE; Schema: altlast; Owner: -
--

CREATE TABLE altlast.vfl_pool (
    vfl_pool_id integer NOT NULL,
    pool_id integer NOT NULL,
    vfl_id integer NOT NULL,
    erfassungs_datum timestamp without time zone DEFAULT now(),
    erfasser_kuerzel character varying(8) DEFAULT "current_user"(),
    mutations_datum timestamp without time zone,
    mutierer_kuerzel character varying(8)
);


--
-- Name: TABLE vfl_pool; Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON TABLE altlast.vfl_pool IS 'm:n-Zuordnung von Standorten zu Pools';


--
-- Name: vflnr_all_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.vflnr_all_v AS
 SELECT v.vflnr_id,
    v.vflz_id,
    v.nummer AS vflnr_nummer,
    o.option AS vflnr_owner
   FROM (altlast.vflnr v
     LEFT JOIN altlast.lookup_org_v o ON ((v.org_id = o.id)));


--
-- Name: report_lu_intern_standort_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.report_lu_intern_standort_v AS
 SELECT v.vflz_id,
    v.vfl_id,
    ( SELECT xmlagg(standort.standort) AS xmlagg
           FROM ( SELECT xmlagg(XMLELEMENT(NAME standort, XMLELEMENT(NAME vflz_id, vflz.vflz_id), XMLELEMENT(NAME language, language.language), XMLELEMENT(NAME vflz_combined_id_kt, vflz.vflz_combined_id_kt), XMLELEMENT(NAME gemeinde, h_gem.gemeinde), XMLELEMENT(NAME bezeichnung, vflz.bezeichnung), XMLELEMENT(NAME x_koordinate, vflz.x_koordinate), XMLELEMENT(NAME y_koordinate, vflz.y_koordinate), XMLELEMENT(NAME z_koordinate, vflz.z_koordinate), XMLELEMENT(NAME vflz_strasse, vflz.vflz_strasse), XMLELEMENT(NAME vflz_hausnr, vflz.vflz_hausnr), XMLELEMENT(NAME vflz_postleitzahl, vflz.vflz_postleitzahl), XMLELEMENT(NAME vflz_flurname, vflz.vflz_flurname), XMLELEMENT(NAME vfa_flaeche, vflz.vfa_flaeche), XMLELEMENT(NAME owner_org, vflz.owner_org), XMLELEMENT(NAME vflz_ort, vflz.vflz_ort), XMLELEMENT(NAME bearbstand, altlast.t(altlast.msgid_code(vflz.h_vflz_bearbstand, vflz.c_vflz_bearbstand), language.language)), XMLELEMENT(NAME c_vflz_bearbstand, vflz.c_vflz_bearbstand), XMLELEMENT(NAME vflz_vftyp, altlast.t(altlast.msgid_code(vflz.h_vflz_vftyp, vflz.c_vflz_vftyp), language.language)), XMLELEMENT(NAME c_vflz_vftyp, vflz.c_vflz_vftyp), XMLELEMENT(NAME vflz_gws_bereich, altlast.t(altlast.msgid_code(COALESCE(vflz.h_vflz_gws_bereich, 10017), vflz.c_vflz_gws_bereich), language.language)), XMLELEMENT(NAME c_vflz_gws_bereich, vflz.c_vflz_gws_bereich), XMLELEMENT(NAME vflz_gws_zone, altlast.t(altlast.msgid_code(COALESCE(vflz.h_vflz_gws_zone, 10018), vflz.c_vflz_gws_zone), language.language)), XMLELEMENT(NAME c_vflz_gws_zone, vflz.c_vflz_gws_zone), XMLELEMENT(NAME vflz_durchlaessigkeit, altlast.t(altlast.msgid_code(COALESCE(vflz.h_vflz_durchlaessigkeit, 58), vflz.c_vflz_durchlaessigkeit), language.language)), XMLELEMENT(NAME c_vflz_durchlaessigkeit, vflz.c_vflz_durchlaessigkeit), XMLELEMENT(NAME vflz_karstgeb, altlast.t(altlast.msgid_code(COALESCE(vflz.h_vflz_karstgeb, 80), vflz.c_vflz_karstgeb), language.language)), XMLELEMENT(NAME c_vflz_karstgeb, vflz.c_vflz_karstgeb), XMLELEMENT(NAME vflz_unterstand, altlast.t(altlast.msgid_code(v.h_vflz_unterstand, v.c_vflz_unterstand), language.language)), XMLELEMENT(NAME c_vflz_unterstand, v.c_vflz_unterstand), XMLELEMENT(NAME gem_parzellen, ( SELECT xmlagg(gem_parzellen.gem_parzelle) AS xmlagg
                           FROM ( SELECT xmlagg(XMLELEMENT(NAME gem_parzelle, XMLELEMENT(NAME grundbuch, gb.grundbuch), XMLELEMENT(NAME parzellen, vpv.parzellen))) AS gem_parzelle
                                   FROM (altlast.vflz_parzellen_v vpv
                                     JOIN altlast.grundbuch_v gb ON ((vpv.h_gem_id = gb.gb_id)))
                                  WHERE (vflz.vflz_id = vpv.vflz_id)
                                  GROUP BY gb.grundbuch
