--
-- Name: vflz_projection_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.vflz_projection_v AS
 SELECT center_points.vflz_id,
    public.st_x(public.st_transform(center_points.source_geometry, 21781)) AS x_21781,
    public.st_y(public.st_transform(center_points.source_geometry, 21781)) AS y_21781,
    public.st_x(public.st_transform(center_points.source_geometry, 2056)) AS x_2056,
    public.st_y(public.st_transform(center_points.source_geometry, 2056)) AS y_2056
   FROM ( SELECT vflz.vflz_id,
            vflz.x_koordinate,
            vflz.y_koordinate,
            vflz.z_koordinate,
            public.st_setsrid(
                CASE
                    WHEN (vflz.z_koordinate IS NULL) THEN public.st_makepoint((vflz.x_koordinate)::double precision, (vflz.y_koordinate)::double precision)
                    ELSE public.st_makepoint((vflz.x_koordinate)::double precision, (vflz.y_koordinate)::double precision, (vflz.z_koordinate)::double precision)
                END, altlast_admin.setting_get_projection()) AS source_geometry
           FROM altlast.vflz) center_points;


