                                    XMLELEMENT(NAME pool, XMLELEMENT(NAME bezeichnung, pool.bezeichnung)) AS pool
                                   FROM (altlast.vfl_pool vp
                                     JOIN altlast.pool USING (pool_id))
                                  WHERE (vp.vfl_id = v.vfl_id)
                                  ORDER BY pool.bezeichnung DESC) pools)), ( SELECT xmlagg(owner.owner) AS xmlagg
                           FROM ( SELECT xmlagg(XMLELEMENT(NAME owner, XMLELEMENT(NAME anrede, altlast.t(owner_v.anrede, language.language)), XMLELEMENT(NAME titel, altlast.t(owner_v.titel, language.language)), XMLELEMENT(NAME vorname, owner_v.vorname), XMLELEMENT(NAME name, owner_v.name), XMLELEMENT(NAME strasse, owner_v.strasse), XMLELEMENT(NAME hausnummer, owner_v.hausnummer), XMLELEMENT(NAME postleitzahl, owner_v.postleitzahl), XMLELEMENT(NAME ort, owner_v.ort), ( SELECT xmlagg(gem_parzellen.gem_parzellen) AS xmlagg
   FROM ( SELECT xmlagg(XMLELEMENT(NAME gem_parzellen, XMLELEMENT(NAME gemeinde, foo.gemeinde), XMLELEMENT(NAME parzellen, foo.parzellen))) AS gem_parzellen
     FROM ( SELECT h_gem_1.gemeinde,
        altlast.commacat_all((grun.gb_nummer)::text) AS parzellen
       FROM (((altlast.grun
         JOIN altlast.subj_vflz_grun USING (grun_id))
         JOIN altlast.subj_vflz sv_1 USING (subj_vflz_id))
         JOIN altlast.h_gem h_gem_1 USING (h_gem_id))
      WHERE (grun.c_status AND (sv_1.subj_id = owner_v.subj_id) AND (vflz.vflz_id = sv_1.vflz_id))
      GROUP BY sv_1.subj_id, h_gem_1.gemeinde) foo) gem_parzellen))) AS owner
                                   FROM altlast.vflz_owner_v owner_v
                                  WHERE (vflz.vflz_id = owner_v.vflz_id)) owner))) AS standort
                   FROM (((((((altlast.vflz
                     CROSS JOIN ( SELECT 'de'::text AS language) language)
                     JOIN altlast.h_gem USING (h_gem_id))
                     LEFT JOIN altlast.bem_v standort_bem ON (((standort_bem.key_value = vflz.vflz_id) AND ((standort_bem.bemgrp)::text = 'standort'::text))))
                     LEFT JOIN altlast.bem_v umwelt_bem ON (((umwelt_bem.key_value = vflz.vflz_id) AND ((umwelt_bem.bemgrp)::text = 'umwelt'::text))))
                     JOIN altlast.report_grunddaten_v ON ((vflz.vflz_id = report_grunddaten_v.vflz_id)))
                     JOIN altlast_hist.snapshot sv ON ((sv.key_value = vflz.vflz_id)))
                     LEFT JOIN altlast.vflgeo ON ((vflz.vflz_id = vflgeo.vflz_id)))
                  WHERE (vflz.vflz_id = v.vflz_id)) standort) AS xml
   FROM altlast.vflz v;


--
-- Name: VIEW report_standort_v; Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON VIEW altlast.report_standort_v IS 'report data for bs';


--
-- Name: report_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.report_v AS
 SELECT v.vflz_id,
    lang.language,
    vflz.vflz_combined_id_kt AS standortnummer,
    vflz.bezeichnung,
    vflz.x_koordinate,
    vflz.y_koordinate,
    vflz.vflz_strasse,
    vflz.vflz_postleitzahl,
    h_gem.bfs_nummer,
    v.owner_org,
    vflz.vflz_ort,
    altlast.t(altlast.msgid_code(v.h_vflz_bearbstand, v.c_vflz_bearbstand), (lang.language)::text) AS bearbeitungsstand,
    altlast.t(altlast.msgid_code(v.h_vflz_vftyp, v.c_vflz_vftyp), (lang.language)::text) AS typ,
    vflz.c_vflz_vftyp AS standortstyp,
    v.gemeinde,
    v.bemerkungen,
    altlast.bestscalefactor(public.st_buffer(vflgeo.wkb_geometry, (50)::double precision), (17.0)::double precision, (14.56)::double precision) AS wms_scale,
    altlast.queryextent(altlast.scaleextent(public.st_buffer(vflgeo.wkb_geometry, (50)::double precision), (17.0)::double precision, (14.56)::double precision)) AS wms_extent,
    (((layerasused.url || '&BBOX='::text) || altlast.queryextent(altlast.scaleextent(public.st_buffer(vflgeo.wkb_geometry, (50)::double precision), (17.0)::double precision, (14.56)::double precision))) || '&WIDTH=1000&HEIGHT=1000'::text) AS background_url,
    (((((kbs.url || '&VFLZ='::text) || v.vflz_id) || '&BBOX='::text) || altlast.queryextent(altlast.scaleextent(public.st_buffer(vflgeo.wkb_geometry, (50)::double precision), (17.0)::double precision, (14.56)::double precision))) || '&WIDTH=1000&HEIGHT=1000'::text) AS kbs_url,
    vflz.dat_rechtskraft,
    ( SELECT (vflz_is_published_v.dat_latest_published)::text AS dat_latest_published
           FROM altlast.vflz_is_published_v
          WHERE ((vflz_is_published_v.vflz_id IN ( SELECT vflz_any_in_vfl.vflz_id
                   FROM altlast.vflz vflz_any_in_vfl
                  WHERE (vflz_any_in_vfl.vfl_id = vflz.vfl_id))) AND vflz_is_published_v.is_latest_published)) AS dat_publizieren,
    altlast.t(altlast.msgid_code(bere.h_bere_res_abwbewe, bere.c_bere_res_abwbewe), (lang.language)::text) AS bewertung,
    altlast.t(altlast.msgid_code(10104, bere.c_bere_res_abwbewe), (lang.language)::text) AS rechtlicher_bezug,
    altlast.t(altlast.msgid_code(10105, bere.c_bere_res_abwbewe), (lang.language)::text) AS handlungsbedarf
   FROM (((((((altlast.vflz vflz
     JOIN altlast.report_grunddaten_v v ON ((vflz.vflz_id = v.vflz_id)))
     CROSS JOIN ( SELECT translations.locale AS language
           FROM altlast.translations
          GROUP BY translations.locale) lang)
     LEFT JOIN altlast.h_gem ON ((h_gem.h_gem_id = vflz.h_gem_id)))
     LEFT JOIN altlast.vflgeo vflgeo ON ((vflgeo.vflz_id = v.vflz_id)))
     LEFT JOIN altlast.bere bere ON ((bere.vflz_id = v.vflz_id)))
     CROSS JOIN ( SELECT rpt_param.standardwert AS url
           FROM altlast.rpt_param
          WHERE ((rpt_param.tag)::text = 'layerAsUsed'::text)) layerasused)
     CROSS JOIN ( SELECT rpt_param.standardwert AS url
           FROM altlast.rpt_param
          WHERE ((rpt_param.tag)::text = 'kbslayer'::text)) kbs);


