--
-- Name: routejoin_constraints; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.routejoin_constraints AS
 SELECT table_fks.t_pk_oid,
    pgns_pk.nspname AS t_pk_schema,
    pgc_pk.relname AS t_pk_table,
    table_fks.t_pk_columns,
    table_fks.t_fk_oid,
    pgns_fk.nspname AS t_fk_schema,
    pgc_fk.relname AS t_fk_table,
    table_fks.t_fk_columns,
    table_fks.conname
   FROM ((((( SELECT pgc.oid AS t_pk_oid,
            pgcn.confrelid AS t_fk_oid,
            pgcn.conname,
            ( SELECT ARRAY( SELECT pga.attname
                           FROM (generate_series(array_lower(pgcn.conkey, 1), array_upper(pgcn.conkey, 1)) gs(gs)
                             JOIN pg_attribute pga ON (((pga.attrelid = pgc.oid) AND (pga.attnum = pgcn.conkey[gs.gs]))))
                          ORDER BY gs.gs) AS pk_columns) AS t_pk_columns,
            ( SELECT ARRAY( SELECT pga.attname
                           FROM (generate_series(array_lower(pgcn.confkey, 1), array_upper(pgcn.confkey, 1)) gs(gs)
                             JOIN pg_attribute pga ON (((pga.attrelid = pgcn.confrelid) AND (pga.attnum = pgcn.confkey[gs.gs]))))
                          ORDER BY gs.gs) AS fk_columns) AS t_fk_columns
           FROM ((pg_class pgc
             JOIN pg_constraint pgcn ON ((pgcn.conrelid = pgc.oid)))
             JOIN pg_namespace pgn ON ((pgn.oid = pgc.relnamespace)))
          WHERE (pgcn.contype = 'f'::"char")) table_fks
     JOIN pg_class pgc_pk ON ((pgc_pk.oid = table_fks.t_pk_oid)))
     JOIN pg_namespace pgns_pk ON ((pgns_pk.oid = pgc_pk.relnamespace)))
     JOIN pg_class pgc_fk ON ((pgc_fk.oid = table_fks.t_fk_oid)))
     JOIN pg_namespace pgns_fk ON ((pgns_fk.oid = pgc_fk.relnamespace)));


--
-- Name: VIEW routejoin_constraints; Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON VIEW altlast.routejoin_constraints IS '
these routes are derivated from foreignkey constraints.

to overrride/ingore some of these routes see the table
altlast.routejoin_userdefined.
';


--
-- Name: routejoin_userdefined; Type: TABLE; Schema: altlast; Owner: -
--

CREATE TABLE altlast.routejoin_userdefined (
    ru_id integer NOT NULL,
    t_pk_schema name DEFAULT 'altlast'::name,
    t_pk_table name,
    t_pk_columns name[],
    t_fk_schema name DEFAULT 'altlast'::name,
    t_fk_table name,
    t_fk_columns name[],
    left_join boolean DEFAULT false,
    routing_cost integer DEFAULT 100,
    action character varying DEFAULT 'add'::character varying,
    erfassungs_datum timestamp without time zone DEFAULT now(),
    erfasser_kuerzel character varying(8) DEFAULT "current_user"(),
    mutations_datum timestamp without time zone,
    mutierer_kuerzel character varying(8),
    CONSTRAINT routejoin_userdefined_action_check CHECK (((action)::text = ANY (ARRAY[('add'::character varying)::text, ('ignore'::character varying)::text]))),
    CONSTRAINT routejoin_userdefined_routing_cost_check CHECK ((routing_cost > 0))
);


--
-- Name: TABLE routejoin_userdefined; Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON TABLE altlast.routejoin_userdefined IS '
this table allows the definition of additional routes, for example for
views, and ignoring of existing routes from  altlast.routejoin_constraints.

The routes are matched against altlast.routejoin_constraints using all of
the t_* columns. the order whether a table is in t_pk or t_fk matters.

The "action" column defines if the route is added or ignore. See the check
constraint for possible values.

"routing_cost" allows teaking the routers preference for this route. The lower
the value is, the more prefered to route is. The default value is 100, the minimum
0. The router tries to reuse existing joins.

Column "left_join" - when true, a LEFT JOIN is used.';


--
-- Name: routejoin_routes; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.routejoin_routes AS
(
         SELECT rc.t_pk_oid,
            rc.t_pk_table,
            rc.t_pk_schema,
            rc.t_pk_columns,
            rc.t_fk_oid,
            rc.t_fk_table,
            rc.t_fk_schema,
            rc.t_fk_columns,
            100 AS routing_cost,
            false AS left_join
           FROM (altlast.routejoin_constraints rc
             LEFT JOIN altlast.routejoin_userdefined ru ON (((ru.t_pk_schema = rc.t_pk_schema) AND (ru.t_pk_table = rc.t_pk_table) AND (ru.t_pk_columns = rc.t_pk_columns) AND (ru.t_fk_schema = rc.t_fk_schema) AND (ru.t_fk_table = rc.t_fk_table) AND (ru.t_fk_columns = rc.t_fk_columns))))
          WHERE (ru.action IS NULL)
        EXCEPT
         SELECT pcpk.oid AS t_pk_oid,
            ru.t_pk_table,
            ru.t_pk_schema,
            ru.t_pk_columns,
            pcfk.oid AS t_fk_oid,
            ru.t_fk_table,
            ru.t_fk_schema,
            ru.t_fk_columns,
            ru.routing_cost,
            ru.left_join
           FROM ((((altlast.routejoin_userdefined ru
             JOIN pg_class pcpk ON ((pcpk.relname = ru.t_pk_table)))
             JOIN pg_namespace pnpk ON (((pcpk.relnamespace = pnpk.oid) AND (pnpk.nspname = ru.t_pk_schema))))
             JOIN pg_class pcfk ON ((pcfk.relname = ru.t_fk_table)))
             JOIN pg_namespace pfpk ON (((pcfk.relnamespace = pfpk.oid) AND (pfpk.nspname = ru.t_fk_schema))))
          WHERE ((ru.action)::text = 'ignore'::text)
        EXCEPT
         SELECT pcfk.oid AS t_pk_oid,
            ru.t_fk_table AS t_pk_table,
            ru.t_fk_schema AS t_pk_schema,
            ru.t_fk_columns AS t_pk_columns,
            pcpk.oid AS t_fk_oid,
            ru.t_pk_table AS t_fk_table,
            ru.t_pk_schema AS t_fk_schema,
            ru.t_pk_columns AS t_fk_columns,
            ru.routing_cost,
            ru.left_join
           FROM ((((altlast.routejoin_userdefined ru
             JOIN pg_class pcpk ON ((pcpk.relname = ru.t_pk_table)))
             JOIN pg_namespace pnpk ON (((pcpk.relnamespace = pnpk.oid) AND (pnpk.nspname = ru.t_pk_schema))))
             JOIN pg_class pcfk ON ((pcfk.relname = ru.t_fk_table)))
             JOIN pg_namespace pfpk ON (((pcfk.relnamespace = pfpk.oid) AND (pfpk.nspname = ru.t_fk_schema))))
          WHERE ((ru.action)::text = 'ignore'::text)
) UNION
 SELECT pcpk.oid AS t_pk_oid,
    ru.t_pk_table,
    ru.t_pk_schema,
    ru.t_pk_columns,
    pcfk.oid AS t_fk_oid,
    ru.t_fk_table,
    ru.t_fk_schema,
    ru.t_fk_columns,
    ru.routing_cost,
    ru.left_join
   FROM ((((altlast.routejoin_userdefined ru
     JOIN pg_class pcpk ON ((pcpk.relname = ru.t_pk_table)))
     JOIN pg_namespace pnpk ON (((pcpk.relnamespace = pnpk.oid) AND (pnpk.nspname = ru.t_pk_schema))))
     JOIN pg_class pcfk ON ((pcfk.relname = ru.t_fk_table)))
     JOIN pg_namespace pfpk ON (((pcfk.relnamespace = pfpk.oid) AND (pfpk.nspname = ru.t_fk_schema))))
  WHERE ((ru.action)::text = 'add'::text);


--
-- Name: VIEW routejoin_routes; Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON VIEW altlast.routejoin_routes IS '
this view contains the combined routes from altlast.routejoin_constraints
and altlast.routejoin_userdefined, which get used by the routing functions.';


--
-- Name: routejoin_oidlookup; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.routejoin_oidlookup AS
 SELECT DISTINCT routejoin_routes.t_pk_oid AS oid,
    routejoin_routes.t_pk_table AS "table",
    routejoin_routes.t_pk_schema AS schema
   FROM altlast.routejoin_routes
UNION
 SELECT routejoin_routes.t_fk_oid AS oid,
    routejoin_routes.t_fk_table AS "table",
    routejoin_routes.t_fk_schema AS schema
   FROM altlast.routejoin_routes;


