CREATE TABLE altlast.rpt_report (
    report_id integer NOT NULL,
    bezeichnung character varying(50),
    stylesheet character varying(300),
    kategorie character varying,
    standard boolean,
    vorschau character varying(300),
    sortierung integer,
    sqlquery text,
    xmldef text,
    whereclause text,
    orderclause text,
    inlinevariables text,
    transformer character varying(20) DEFAULT 'XML'::character varying NOT NULL,
    erfassungs_datum timestamp without time zone DEFAULT now(),
    erfasser_kuerzel character varying(8) DEFAULT "current_user"(),
    mutations_datum timestamp without time zone,
    mutierer_kuerzel character varying(8),
    type integer
);


--
-- Name: COLUMN rpt_report.bezeichnung; Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON COLUMN altlast.rpt_report.bezeichnung IS 'Name für dneReport, welcher auch in der Benutzeroberfläche dargestellt werden soll.';


--
-- Name: COLUMN rpt_report.stylesheet; Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON COLUMN altlast.rpt_report.stylesheet IS 'Pfad zum XSL-Stylesheet für den Report. Dieser Pfad ist relativ zu dem in der reportgen.ini der Applikation definierten Stylesheetverzeichnis ';


--
-- Name: COLUMN rpt_report.kategorie; Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON COLUMN altlast.rpt_report.kategorie IS 'Kategorie des Reports. Ermöglicht die Spezifizierung meherer alternativer Reports für eine Aktion in der Applikation';


--
-- Name: COLUMN rpt_report.standard; Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON COLUMN altlast.rpt_report.standard IS 'True definiert einen Report als Standardreport für eine Kategorie';


--
-- Name: COLUMN rpt_report.vorschau; Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON COLUMN altlast.rpt_report.vorschau IS 'Eventueller Link zu einem Vorschaubild';


--
-- Name: COLUMN rpt_report.sortierung; Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON COLUMN altlast.rpt_report.sortierung IS 'Sortierungreihenfolge der Reports in der Bneutzeroberfläche der Applikation';


--
-- Name: COLUMN rpt_report.sqlquery; Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON COLUMN altlast.rpt_report.sqlquery IS 'Der SQL-Query für das zu generierende XML. Die Where-Bedingung muss allerdings in die Spalte whereclause, die Order-Bedingung nach orderclause';


--
-- Name: COLUMN rpt_report.xmldef; Type: COMMENT; Schema: altlast; Owner: -
