--
-- Name: searchfield_app_finanzen; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.searchfield_app_finanzen AS
 SELECT vflz.vflz_id AS id,
    (NOT (((pm_vfl.pro_uid)::text = ANY (ARRAY[('b39a6ffee40d43b1af66414ba170b056'::character varying)::text, ('10780988354d0d372f0eda0047530076'::character varying)::text, ('97428624054be16d7934582048587996'::character varying)::text, ('78611027854b65089e82e90054102445'::character varying)::text, ('34363974354b67d0176a545053182270'::character varying)::text, ('74989431954b39b440351a0029181913'::character varying)::text])) IS DISTINCT FROM true)) AS option
   FROM (altlast.vflz
     LEFT JOIN altlast.pm_vfl USING (vfl_id));


--
-- Name: VIEW searchfield_app_finanzen; Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON VIEW altlast.searchfield_app_finanzen IS 'Contains all vflz.';


--
-- Name: COLUMN searchfield_app_finanzen.option; Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON COLUMN altlast.searchfield_app_finanzen.option IS 'TRUE when a vflz has one of the following Processmaker apps: VASA-Abgeltung, Ersatzvornahme, Schlussabrechnung, Vorsorge Fond, Vollzug Kanton, Vorschussverfügung. See #5040127.';


--
-- Name: searchfield_betreiber_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.searchfield_betreiber_v AS
 SELECT DISTINCT sv.subj_id AS id,
    beteiligte_v.subj_kennung AS option,
    sv.vflz_id
   FROM (altlast.beteiligte_v
     JOIN altlast.subj_vflz_v sv USING (subj_id))
  WHERE ((sv.c_subj_vflz_bez_art)::text = '1'::text);


--
-- Name: searchfield_bez_vflz_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.searchfield_bez_vflz_v AS
 SELECT vg.vflz_id,
    h_bez.h_bez_id,
    h_bez.bezirk
   FROM (altlast.vflgeo vg
     LEFT JOIN ( SELECT h_bez_1.wkb_geometry,
            h_bez_1.h_bez_id,
            h_bez_1.bezirk
           FROM altlast.h_bez h_bez_1
          WHERE (h_bez_1.h_kanton = 19)) h_bez ON (public.st_intersects(vg.wkb_geometry, h_bez.wkb_geometry)));


--
-- Name: VIEW searchfield_bez_vflz_v; Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON VIEW altlast.searchfield_bez_vflz_v IS 'Combination of Bezirke and Standorte in Kanton Aargau';


--
-- Name: searchfield_fplh_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.searchfield_fplh_v AS
 SELECT DISTINCT sv.subj_id AS id,
    beteiligte_v.subj_kennung AS option,
    sv.vflz_id
   FROM (altlast.beteiligte_v
     JOIN altlast.subj_vflz_v sv USING (subj_id))
  WHERE ((sv.c_subj_vflz_bez_art)::text = '8'::text);


--
-- Name: searchfield_gem_vflz_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.searchfield_gem_vflz_v AS
 SELECT v.vflz_id,
    v.h_gem_id,
    h_gem.gemeinde
   FROM (altlast.vflz v
     LEFT JOIN altlast.h_gem USING (h_gem_id));


--
-- Name: VIEW searchfield_gem_vflz_v; Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON VIEW altlast.searchfield_gem_vflz_v IS 'Serch for primary gemeinde set under Grunddaten';


--
-- Name: searchfield_gemeinde_parzellen_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.searchfield_gemeinde_parzellen_v AS
 SELECT DISTINCT v.vflz_id,
    COALESCE(p.h_gem_id, v.h_gem_id) AS h_gem_id,
    COALESCE(g2.gemeinde, g1.gemeinde) AS gemeinde,
    p.parzellen,
    ((COALESCE(g2.gemeinde, g1.gemeinde))::text ||
        CASE
            WHEN (COALESCE(g2.bfs_nummer, g1.bfs_nummer) IS NOT NULL) THEN ((' ('::text || lpad((COALESCE(g2.bfs_nummer, g1.bfs_nummer))::text, 4, '0'::text)) || ')'::text)
            ELSE NULL::text
        END) AS lookup_option,
    v.h_gem_id AS gemeinde_standort,
    g1.gemeinde AS gemeindename_standort,
    g1.gemeinde AS gemeinde_vflz
   FROM (((altlast.vflz v
     LEFT JOIN altlast.h_gem g1 ON ((v.h_gem_id = g1.h_gem_id)))
     LEFT JOIN altlast.vflz_parzellen_v p USING (vflz_id))
     LEFT JOIN altlast.h_gem g2 ON ((g2.h_gem_id = p.h_gem_id)));


--
-- Name: VIEW searchfield_gemeinde_parzellen_v; Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON VIEW altlast.searchfield_gemeinde_parzellen_v IS 'Lists parcel
assignments to locations including community id h_gem_id  and name. If no
parcels are assigned, takes the h_gem_id from vflz.';


--
-- Name: searchfield_grundbuch_parzellen_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.searchfield_grundbuch_parzellen_v AS
 SELECT DISTINCT sources_combined.vflz_id,
    sources_combined.gb_id AS h_gem_id,
    sources_combined.grundbuch AS gemeinde,
    sources_combined.parzellen,
    sources_combined.lookup_option
   FROM ( SELECT DISTINCT subj_vflz.vflz_id,
            gb.gb_id,
            gb.grundbuch,
            g.gb_nummer AS parzellen,
            ((((gb.grundbuch)::text || ' ('::text) || (gb.gb_id)::text) || ')'::text) AS lookup_option
           FROM (((altlast._grundbuch gb
             LEFT JOIN altlast.grun g ON ((g.h_gem_id = gb.gb_id)))
             LEFT JOIN altlast.subj_vflz_grun svg USING (grun_id))
             JOIN altlast.subj_vflz USING (subj_vflz_id))
        UNION
         SELECT DISTINCT grundbuch_parzellen_intersect.vflz_id,
            grundbuch_parzellen_intersect.gb_id,
            grundbuch_parzellen_intersect.grundbuch,
            grundbuch_parzellen_intersect.parzellen,
            grundbuch_parzellen_intersect.lookup_option
           FROM altlast.grundbuch_parzellen_intersect) sources_combined
  GROUP BY sources_combined.vflz_id, sources_combined.gb_id, sources_combined.grundbuch, sources_combined.parzellen, sources_combined.lookup_option;


--
-- Name: VIEW searchfield_grundbuch_parzellen_v; Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON VIEW altlast.searchfield_grundbuch_parzellen_v IS 'Lists parcel
assignments to grundbuch id gb_id  and name.';


