--
-- Name: searchfield_standort_beteiligte_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.searchfield_standort_beteiligte_v AS
 SELECT beteiligte_v.subj_id AS id,
    beteiligte_v.subj_kennung AS option
   FROM altlast.beteiligte_v;


--
-- Name: searchfield_standort_eigentuemer_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.searchfield_standort_eigentuemer_v AS
 SELECT DISTINCT sv.subj_id AS id,
    s.subj_kennung AS option,
    sv.vflz_id
   FROM ((((altlast.beteiligte_v
     JOIN altlast.subj_vflz_v sv USING (subj_id))
     JOIN altlast.cod c ON (((c.c_cli_id = sv.h_subj_vflz_bez_art) AND ((c.code)::text = (sv.c_subj_vflz_bez_art)::text))))
     JOIN altlast.cod_bezart ba ON (((c.c_cli_id = ba.c_cli_id_grun_subj) AND ((c.code)::text = (ba.grun_subj)::text) AND ba.eigen)))
     JOIN altlast.subj_kennung_v s USING (subj_id));


--
-- Name: searchfield_subj_hausnummer_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.searchfield_subj_hausnummer_v AS
 SELECT subj_adr.subj_id,
    adr.hausnummer
   FROM ((altlast.adr
     JOIN altlast.subj_adr USING (adr_id))
     JOIN altlast.subj USING (subj_id));


--
-- Name: searchfield_vflz_postleitzahl_ortsname_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.searchfield_vflz_postleitzahl_ortsname_v AS
 SELECT vflz.vflz_id,
    h_ort.h_ort_id,
    (((vflz.vflz_postleitzahl)::text || ' '::text) || (vflz.vflz_ort)::text) AS lookup_option
   FROM (altlast.vflz
     LEFT JOIN altlast.h_ort ON ((((h_ort.postleitzahl)::text = (vflz.vflz_postleitzahl)::text) AND ((h_ort.ortsname)::text = (vflz.vflz_ort)::text))));


--
-- Name: shapeexport_geoportal_de_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.shapeexport_geoportal_de_v AS
 SELECT v.vflz_id,
    v.vflz_combined_id_kt AS standort,
    altlast.t(altlast.msgid_code(v.h_vflz_vftyp, v.c_vflz_vftyp), 'de'::text) AS standorttyp,
    altlast.t(altlast.msgid_code(v.h_vflz_vftyp, v.c_vflz_vftyp), 'fr'::text) AS standorttyp_fr,
    COALESCE(betrieb_props.betrieb_branchen, ablag_props.ablag_branche, schiessan_props.schiessan_branche, unfall_props.unfall_branche) AS branche,
    COALESCE(betrieb_props.betrieb_branchen_fr, ablag_props.ablag_branche_fr, schiessan_props.schiessan_branche_fr, unfall_props.unfall_branche_fr) AS branche_fr,
    altlast.t(altlast.msgid_code(bere.h_bere_res_abwbewe, bere.c_bere_res_abwbewe), 'de'::text) AS statusaltlv,
    altlast.t(altlast.msgid_code(bere.h_bere_res_abwbewe, bere.c_bere_res_abwbewe), 'fr'::text) AS statusaltlv_fr,
    altlast.t(altlast.msgid_code(v.h_vflz_unterstand, v.c_vflz_unterstand), 'de'::text) AS untersuchungsmassnahmen,
    altlast.t(altlast.msgid_code(v.h_vflz_unterstand, v.c_vflz_unterstand), 'fr'::text) AS untersuchungsmassnahmen_fr,
    ablag_props.ablag_stoffe AS inhalt,
    ablag_props.ablag_stoffe_fr AS inhalt_fr,
    ablag_props.ablag_gesamtvol AS volumen,
    COALESCE(betrieb_props.inbetrieb, ablag_props.inbetrieb, schiessan_props.inbetrieb) AS inbetrieb,
    COALESCE(betrieb_props.von, ablag_props.von, schiessan_props.von, unfall_props.von) AS anfangbetrieb,
    COALESCE(betrieb_props.von_fr, ablag_props.von_fr, schiessan_props.von_fr, unfall_props.von_fr) AS anfangbetrieb_fr,
    COALESCE(betrieb_props.bis, ablag_props.bis, schiessan_props.bis) AS endebetrieb,
    COALESCE(betrieb_props.bis_fr, ablag_props.bis_fr, schiessan_props.bis_fr) AS endebetrieb_fr,
    to_char((v.dat_rechtskraft)::timestamp with time zone, 'DD.MM.YYYY'::text) AS ersteintrag,
    to_char((v.dat_publizieren)::timestamp with time zone, 'DD.MM.YYYY'::text) AS letzteanpassung,
    to_char(((sh.created)::date)::timestamp with time zone, 'DD.MM.YYYY'::text) AS lastsnapshot,
    vfus_agg.festgestellteumwelteinwirkungen,
    vfus_agg.festgestellteumwelteinwirkungen_fr,
    veen_agg.besonderevorkommnisse,
    veen_agg.besonderevorkommnisse_fr,
        CASE
            WHEN (public.st_geometrytype(vflgeo.wkb_geometry) = 'ST_Point'::text) THEN public.st_buffer(vflgeo.wkb_geometry, (10)::double precision)
            ELSE vflgeo.wkb_geometry
        END AS wkb_geometry
   FROM (((((((((((((altlast.vflz v
     JOIN altlast.vflnr ON (((vflnr.vflz_id = v.vflz_id) AND (vflnr.aktiv = true))))
     JOIN altlast.vflz_is_published_v vip ON ((vip.vflz_id = v.vflz_id)))
     JOIN altlast_hist.snapshot sh ON (((sh.history_id = 1) AND (sh.key_value = v.vflz_id))))
     JOIN altlast.bere_v bere ON (((bere.vflz_id = v.vflz_id) AND bere.kbs)))
     JOIN altlast.vflgeo ON ((v.vflz_id = vflgeo.vflz_id)))
     JOIN altlast_admin.setting stng ON (((stng.value)::text = (vflnr.org_id)::text)))
     JOIN altlast_admin.setitem sit ON (((sit.setitem_id = stng.setitem_id) AND ((sit.key)::text = 'org'::text))))
     LEFT JOIN ( SELECT inta.vflz_id,
            altlast.t(altlast.msgid_code(25, '8414'::character varying), 'de'::text) AS ablag_branche,
            altlast.t(altlast.msgid_code(25, '8414'::character varying), 'fr'::text) AS ablag_branche_fr,
            ((((COALESCE(to_char((min(inta.inta_ablag_von))::timestamp with time zone, 'DD.MM.YYYY'::text), altlast.t('unbekannt'::text, 'de'::text)) || ' '::text) || altlast.t('bis'::text, 'de'::text)) || ' '::text) ||
                CASE
                    WHEN bool_or(inta.zeitraum_bisheute) THEN altlast.t('heute'::text, 'de'::text)
                    ELSE COALESCE(to_char((max(inta.inta_ablag_bis))::timestamp with time zone, 'DD.MM.YYYY'::text), altlast.t('unbekannt'::text, 'de'::text))
                END) AS ablag_zeitraum,
            bool_or(inta.zeitraum_bisheute) AS inbetrieb,
            (COALESCE(to_char((min(inta.inta_ablag_von))::timestamp with time zone, 'DD.MM.YYYY'::text), altlast.t('unbekannt'::text, 'de'::text)) || ' '::text) AS von,
            (COALESCE(to_char((min(inta.inta_ablag_von))::timestamp with time zone, 'DD.MM.YYYY'::text), altlast.t('unbekannt'::text, 'fr'::text)) || ' '::text) AS von_fr,
                CASE
                    WHEN bool_or(inta.zeitraum_bisheute) THEN altlast.t('heute'::text, 'de'::text)
                    ELSE COALESCE(to_char((max(inta.inta_ablag_bis))::timestamp with time zone, 'DD.MM.YYYY'::text), altlast.t('unbekannt'::text, 'de'::text))
                END AS bis,
                CASE
                    WHEN bool_or(inta.zeitraum_bisheute) THEN altlast.t('heute'::text, 'fr'::text)
                    ELSE COALESCE(to_char((max(inta.inta_ablag_bis))::timestamp with time zone, 'DD.MM.YYYY'::text), altlast.t('unbekannt'::text, 'fr'::text))
                END AS bis_fr,
            sum(inta.inta_vol_kompartiment) AS ablag_gesamtvol,
            array_to_string(array_agg((altlast.t(altlast.msgid_code(kksk.h_kksk_stoffkl, kksk.c_kksk_stoffkl), 'de'::text) || COALESCE((': '::text || altlast.t(altlast.msgid_code(kksg.h_kksg_stoffgrp, kksg.c_kksg_stoffgrp), 'de'::text)), ''::text))), '

'::text) AS ablag_stoffe,
            array_to_string(array_agg((altlast.t(altlast.msgid_code(kksk.h_kksk_stoffkl, kksk.c_kksk_stoffkl), 'fr'::text) || COALESCE((': '::text || altlast.t(altlast.msgid_code(kksg.h_kksg_stoffgrp, kksg.c_kksg_stoffgrp), 'fr'::text)), ''::text))), '

'::text) AS ablag_stoffe_fr
           FROM ((altlast.inta
             LEFT JOIN altlast.kksk ON ((kksk.inta_id = inta.inta_id)))
             LEFT JOIN altlast.kksg ON ((kksk.kksk_id = kksg.kksk_id)))
          GROUP BY inta.vflz_id) ablag_props ON (((ablag_props.vflz_id = v.vflz_id) AND ((v.c_vflz_vftyp)::text = '01'::text))))
     LEFT JOIN ( SELECT intb.vflz_id,
            array_to_string(array_agg(ibv.intb_bran_formatted), ' '::text) AS betrieb_branchen,
            array_to_string(array_agg(ibv.intb_bran_formatted_fr), ' '::text) AS betrieb_branchen_fr,
            ((((COALESCE(to_char((min(intb.intb_vonbetrieb))::timestamp with time zone, 'DD.MM.YYYY'::text), altlast.t('unbekannt'::text, 'de'::text)) || ' '::text) || altlast.t('bis'::text, 'de'::text)) || ' '::text) ||
                CASE
                    WHEN bool_or(intb.zeitraum_bisheute) THEN altlast.t('heute'::text, 'de'::text)
                    ELSE COALESCE(to_char((max(intb.intb_bisbetrieb))::timestamp with time zone, 'DD.MM.YYYY'::text), altlast.t('unbekannt'::text, 'de'::text))
                END) AS betrieb_zeitraum,
            ((((COALESCE(to_char((min(intb.intb_vonbetrieb))::timestamp with time zone, 'DD.MM.YYYY'::text), altlast.t('unbekannt'::text, 'fr'::text)) || ' '::text) || altlast.t('bis'::text, 'fr'::text)) || ' '::text) ||
                CASE
                    WHEN bool_or(intb.zeitraum_bisheute) THEN altlast.t('heute'::text, 'fr'::text)
                    ELSE COALESCE(to_char((max(intb.intb_bisbetrieb))::timestamp with time zone, 'DD.MM.YYYY'::text), altlast.t('unbekannt'::text, 'fr'::text))
                END) AS betrieb_zeitraum_fr,
            bool_or(intb.zeitraum_bisheute) AS inbetrieb,
            (COALESCE(to_char((min(intb.intb_vonbetrieb))::timestamp with time zone, 'DD.MM.YYYY'::text), altlast.t('unbekannt'::text, 'de'::text)) || ' '::text) AS von,
            (COALESCE(to_char((min(intb.intb_vonbetrieb))::timestamp with time zone, 'DD.MM.YYYY'::text), altlast.t('unbekannt'::text, 'fr'::text)) || ' '::text) AS von_fr,
                CASE
                    WHEN bool_or(intb.zeitraum_bisheute) THEN altlast.t('heute'::text, 'de'::text)
                    ELSE COALESCE(to_char((max(intb.intb_bisbetrieb))::timestamp with time zone, 'DD.MM.YYYY'::text), altlast.t('unbekannt'::text, 'de'::text))
                END AS bis,
                CASE
                    WHEN bool_or(intb.zeitraum_bisheute) THEN altlast.t('heute'::text, 'fr'::text)
                    ELSE COALESCE(to_char((max(intb.intb_bisbetrieb))::timestamp with time zone, 'DD.MM.YYYY'::text), altlast.t('unbekannt'::text, 'fr'::text))
                END AS bis_fr
           FROM (altlast.intb
             LEFT JOIN altlast.intb_branche_v ibv ON ((ibv.intb_id = intb.intb_id)))
          GROUP BY intb.vflz_id) betrieb_props ON (((betrieb_props.vflz_id = v.vflz_id) AND ((v.c_vflz_vftyp)::text = '02'::text))))
     LEFT JOIN ( SELECT intu.vflz_id,
            altlast.t(altlast.msgid_code(25, '98'::character varying), 'de'::text) AS unfall_branche,
            altlast.t(altlast.msgid_code(25, '98'::character varying), 'fr'::text) AS unfall_branche_fr,
            (COALESCE(to_char((min(intu.intu_unfallvon))::timestamp with time zone, 'DD.MM.YYYY'::text), altlast.t('unbekannt'::text, 'de'::text)) || ' '::text) AS von,
            (COALESCE(to_char((min(intu.intu_unfallvon))::timestamp with time zone, 'DD.MM.YYYY'::text), altlast.t('unbekannt'::text, 'fr'::text)) || ' '::text) AS von_fr,
            sum(inum.inum_stoffmng) AS intu_gesamtvol,
            array_to_string(array_agg(altlast.t(altlast.msgid_code(inum.h_inum_stoffe, inum.c_inum_stoffe), 'de'::text)), '

'::text) AS unfall_stoffe,
            array_to_string(array_agg(altlast.t(altlast.msgid_code(inum.h_inum_stoffe, inum.c_inum_stoffe), 'de'::text)), '

'::text) AS unfall_stoffe_fr
           FROM (altlast.intu
             LEFT JOIN altlast.inum ON ((inum.intu_id = intu.intu_id)))
          GROUP BY intu.vflz_id) unfall_props ON (((unfall_props.vflz_id = v.vflz_id) AND ((v.c_vflz_vftyp)::text = '03'::text))))
     LEFT JOIN ( SELECT intb.vflz_id,
            altlast.t(altlast.msgid_code(25, '9143'::character varying), 'de'::text) AS schiessan_branche,
            altlast.t(altlast.msgid_code(25, '9143'::character varying), 'fr'::text) AS schiessan_branche_fr,
            ((((COALESCE(to_char((min(intb.intb_vonbetrieb))::timestamp with time zone, 'DD.MM.YYYY'::text), altlast.t('unbekannt'::text, 'de'::text)) || ' '::text) || altlast.t('bis'::text, 'de'::text)) || ' '::text) ||
                CASE
                    WHEN bool_or(intb.zeitraum_bisheute) THEN altlast.t('heute'::text, 'de'::text)
                    ELSE COALESCE(to_char((max(intb.intb_bisbetrieb))::timestamp with time zone, 'DD.MM.YYYY'::text), altlast.t('unbekannt'::text, 'de'::text))
                END) AS betrieb_zeitraum,
            ((((COALESCE(to_char((min(intb.intb_vonbetrieb))::timestamp with time zone, 'DD.MM.YYYY'::text), altlast.t('unbekannt'::text, 'fr'::text)) || ' '::text) || altlast.t('bis'::text, 'fr'::text)) || ' '::text) ||
                CASE
                    WHEN bool_or(intb.zeitraum_bisheute) THEN altlast.t('heute'::text, 'fr'::text)
                    ELSE COALESCE(to_char((max(intb.intb_bisbetrieb))::timestamp with time zone, 'DD.MM.YYYY'::text), altlast.t('unbekannt'::text, 'fr'::text))
                END) AS betrieb_zeitraum_fr,
            bool_or(intb.zeitraum_bisheute) AS inbetrieb,
            (COALESCE(to_char((min(intb.intb_vonbetrieb))::timestamp with time zone, 'DD.MM.YYYY'::text), altlast.t('unbekannt'::text, 'de'::text)) || ' '::text) AS von,
            (COALESCE(to_char((min(intb.intb_vonbetrieb))::timestamp with time zone, 'DD.MM.YYYY'::text), altlast.t('unbekannt'::text, 'fr'::text)) || ' '::text) AS von_fr,
                CASE
                    WHEN bool_or(intb.zeitraum_bisheute) THEN altlast.t('heute'::text, 'de'::text)
                    ELSE COALESCE(to_char((max(intb.intb_bisbetrieb))::timestamp with time zone, 'DD.MM.YYYY'::text), altlast.t('unbekannt'::text, 'de'::text))
                END AS bis,
                CASE
                    WHEN bool_or(intb.zeitraum_bisheute) THEN altlast.t('heute'::text, 'fr'::text)
                    ELSE COALESCE(to_char((max(intb.intb_bisbetrieb))::timestamp with time zone, 'DD.MM.YYYY'::text), altlast.t('unbekannt'::text, 'fr'::text))
                END AS bis_fr
           FROM altlast.intb
          GROUP BY intb.vflz_id) schiessan_props ON (((schiessan_props.vflz_id = v.vflz_id) AND ((v.c_vflz_vftyp)::text = '04'::text))))
     LEFT JOIN ( SELECT vfus.vflz_id,
            array_to_string(array_agg(((altlast.t(altlast.msgid_code(vfus.h_vfus_art_schaden, vfus.c_vfus_art_schaden), 'de'::text) || COALESCE((': '::text || altlast.t(altlast.msgid_code(vfus.h_vfus_schaeden, vfus.c_vfus_schaeden), 'de'::text)), ''::text)) || COALESCE(((' ('::text || replace((bem.bem)::text, 'Menaces environnement: '::text, ''::text)) || ')'::text), ''::text))), '
'::text) AS festgestellteumwelteinwirkungen,
            array_to_string(array_agg(((altlast.t(altlast.msgid_code(vfus.h_vfus_art_schaden, vfus.c_vfus_art_schaden), 'fr'::text) || COALESCE((': '::text || altlast.t(altlast.msgid_code(vfus.h_vfus_schaeden, vfus.c_vfus_schaeden), 'fr'::text)), ''::text)) || COALESCE(((' ('::text || replace((bem.bem)::text, 'Menaces environnement: '::text, ''::text)) || ')'::text), ''::text))), '
'::text) AS festgestellteumwelteinwirkungen_fr
           FROM ((altlast.vfus
             JOIN altlast.bem ON ((bem.key_value = vfus.vfus_id)))
             JOIN altlast.bemgrp ON (((bemgrp.bemgrp_id = bem.bemgrp_id) AND ((bemgrp.bemgrp)::text = 'vfus.vfus_id'::text))))
          GROUP BY vfus.vflz_id) vfus_agg ON ((vfus_agg.vflz_id = v.vflz_id)))
     LEFT JOIN ( SELECT veen.vflz_id,
            array_to_string(array_agg(((COALESCE((to_char((veen.veen_datum)::timestamp with time zone, 'dd.mm.YYYY'::text) || ': '::text), ''::text) || COALESCE(altlast.t(altlast.msgid_code(veen.h_veen_natuerlich, veen.c_veen_natuerlich), 'fr'::text), ''::text)) || COALESCE(((' ('::text || (bem.bem)::text) || ')'::text), ''::text))), '
'::text) AS besonderevorkommnisse_fr,
            array_to_string(array_agg(((COALESCE((to_char((veen.veen_datum)::timestamp with time zone, 'dd.mm.YYYY'::text) || ': '::text), ''::text) || COALESCE(altlast.t(altlast.msgid_code(veen.h_veen_natuerlich, veen.c_veen_natuerlich), 'de'::text), ''::text)) || COALESCE(((' ('::text || (bem.bem)::text) || ')'::text), ''::text))), '
'::text) AS besonderevorkommnisse
           FROM ((altlast.veen
             JOIN altlast.bem ON ((bem.key_value = veen.veen_id)))
             JOIN altlast.bemgrp ON (((bemgrp.bemgrp_id = bem.bemgrp_id) AND ((bemgrp.bemgrp)::text = 'veen.veen_id'::text))))
          GROUP BY veen.vflz_id, bem.bem) veen_agg ON ((veen_agg.vflz_id = v.vflz_id)))
  WHERE (vip.is_latest_published AND bere.kbs);


