-- Name: subj_parzellen_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.subj_parzellen_v AS
 SELECT foo.subj_id,
    foo.h_gem_id,
    foo.parzellen
   FROM ( SELECT sv.subj_id,
            grun.h_gem_id,
            altlast.commacat_all((grun.gb_nummer)::text) AS parzellen
           FROM ((altlast.grun
             JOIN altlast.subj_vflz_grun USING (grun_id))
             JOIN altlast.subj_vflz sv USING (subj_vflz_id))
          GROUP BY sv.subj_id, grun.h_gem_id) foo;


