--
-- Name: subj_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.subj_v AS
 SELECT s.subj_id,
    a.adr_id,
    a.strasse,
    bem.bem AS bemerkungen,
    g.postleitzahl
   FROM (((((altlast.subj s
     LEFT JOIN altlast.subj_kennung_v sk ON ((sk.subj_id = s.subj_id)))
     LEFT JOIN altlast.subj_adr sa ON ((sa.subj_id = s.subj_id)))
     LEFT JOIN altlast.adr a ON ((a.adr_id = sa.adr_id)))
     LEFT JOIN altlast.gemeindeort_v g ON (((g.h_gem_id = a.h_gem_id) AND ((a.ort)::text = (g.ortsname)::text))))
     LEFT JOIN altlast.bem_v bem ON ((((bem.bemgrp)::text = 'subjekt'::text) AND (bem.key_value = s.subj_id))));


--
-- Name: VIEW subj_v; Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON VIEW altlast.subj_v IS 'DEPRECATION NOTICE:
The field postleitzahl of this view is deprectated as the h_gem_id in adr is no longer maintained. The plz is stored seperately in adr.';


--
-- Name: subj_vflz_grun_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.subj_vflz_grun_v AS
 SELECT svg.grun_id,
    g.gb_nummer,
    g.h_gem_id,
    sv.subj_id,
    sv.c_subj_vflz_bez_art AS c_eigentums_art
   FROM ((altlast.subj_vflz sv
     JOIN altlast.subj_vflz_grun svg USING (subj_vflz_id))
     JOIN altlast.grun g ON ((svg.grun_id = g.grun_id)))
  WHERE (g.c_status = true);


