--
-- Name: vflz_erfasste_parzellen_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.vflz_erfasste_parzellen_v AS
 SELECT string_agg(DISTINCT (g.gb_nummer)::text, ', '::text) AS erfasste_parzellen,
    COALESCE(gdb.grundbuch, h_gem.gemeinde) AS gb_gem,
    subj_vflz.vflz_id
   FROM ((((altlast.subj_vflz
     LEFT JOIN altlast.subj_vflz_grun USING (subj_vflz_id))
     LEFT JOIN altlast.grun g USING (grun_id))
     JOIN altlast._grundbuch gdb ON (((g.h_gem_id = gdb.bfs_nr) OR (g.h_gem_id = gdb.gb_id))))
     LEFT JOIN altlast.h_gem h_gem ON ((h_gem.h_gem_id = gdb.bfs_nr)))
  GROUP BY subj_vflz.vflz_id, gdb.grundbuch, h_gem.gemeinde;


--
-- Name: VIEW vflz_erfasste_parzellen_v; Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON VIEW altlast.vflz_erfasste_parzellen_v IS 'Erfasste Parzellen. Falls die Parzellen über altlast.parzellen_v nicht abgerufen werden.';


--
-- Name: vflz_grundbuch_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.vflz_grundbuch_v AS
 SELECT svv.vflz_id,
    COALESCE(gdb.grundbuch, h_gem.gemeinde) AS grundbuch,
    gdb.gb_id,
    h_gem.gemeinde,
    h_gem.bfs_nummer,
    gdb.c_kanton,
    gdb.wkb_geometry
   FROM (((altlast.subj_vflz_v svv
     JOIN altlast.grun g USING (grun_id))
     JOIN altlast._grundbuch gdb ON (((g.h_gem_id = gdb.bfs_nr) OR (g.h_gem_id = gdb.gb_id))))
     LEFT JOIN altlast.h_gem h_gem ON ((h_gem.h_gem_id = gdb.bfs_nr)))
  GROUP BY svv.vflz_id, g.h_gem_id, h_gem.gemeinde, h_gem.bfs_nummer, gdb.gb_id, gdb.grundbuch, gdb.c_kanton, gdb.wkb_geometry
  ORDER BY h_gem.gemeinde;


