--
-- Name: tpl_1_overview_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.tpl_1_overview_v AS
 SELECT v.vflz_id,
    ( SELECT xmlagg(standort.standort) AS xmlagg
           FROM ( SELECT xmlagg(XMLELEMENT(NAME standort, XMLELEMENT(NAME vflz_id, vflz.vflz_id), XMLELEMENT(NAME gem_parzellen_geo, ( SELECT xmlagg(gem_parzellen_geo.gem_parzelle_geo) AS xmlagg
                           FROM ( SELECT xmlagg(XMLELEMENT(NAME gem_parzelle_geo, XMLELEMENT(NAME gemeinde, foo.gemeinde), XMLELEMENT(NAME bfs_nummer, foo.bfs_nummer), XMLELEMENT(NAME parzellen, ( SELECT xmlagg(parzellen.parzelle) AS xmlagg
   FROM ( SELECT xmlagg(XMLELEMENT(NAME parzelle, vpv.parcel)) AS parzelle
     FROM (altlast.vflz_parcels_v vpv
       JOIN altlast.h_gem USING (h_gem_id))
    WHERE ((vflz.vflz_id = vpv.vflz_id) AND ((h_gem.gemeinde)::text = (foo.gemeinde)::text))) parzellen)))) AS gem_parzelle_geo
                                   FROM ( SELECT vpv.vflz_id,
    h_gem.gemeinde,
    h_gem.bfs_nummer
   FROM (altlast.vflz_parcels_v vpv
     JOIN altlast.h_gem USING (h_gem_id))
  WHERE (vflz.vflz_id = vpv.vflz_id)
  GROUP BY vpv.h_gem_id, vpv.vflz_id, h_gem.gemeinde, h_gem.bfs_nummer
  ORDER BY h_gem.gemeinde) foo) gem_parzellen_geo)), XMLELEMENT(NAME eva_all_reports, ( SELECT xmlagg(XMLELEMENT(NAME eva_all_report, ( SELECT xmlagg(eva_report.eva_report) AS xmlagg
