      GROUP BY g.gb_nummer) bar) parzellen)))) AS gem_parzelle_collected
                                   FROM ( SELECT svv.vflz_id,
    h_gem.gemeinde,
    h_gem.bfs_nummer
   FROM ((altlast.subj_vflz_v svv
     JOIN altlast.grun g USING (grun_id))
     JOIN altlast.h_gem USING (h_gem_id))
  WHERE (vflz.vflz_id = svv.vflz_id)
  GROUP BY g.h_gem_id, svv.vflz_id, h_gem.gemeinde, h_gem.bfs_nummer
  ORDER BY h_gem.gemeinde) foo) gem_parzellen_collected)), ( SELECT xmlagg(owner.owner) AS xmlagg
                           FROM ( SELECT xmlagg(XMLELEMENT(NAME owner, XMLELEMENT(NAME vorname, owner_v.vorname), XMLELEMENT(NAME name, owner_v.name))) AS owner
                                   FROM altlast.vflz_owner_v owner_v
                                  WHERE (vflz.vflz_id = owner_v.vflz_id)) owner))) AS standort
                   FROM altlast.vflz
                  WHERE (vflz.vflz_id = v.vflz_id)) standort) AS xml
   FROM altlast.vflz v;


