--
-- Name: vflgeo_bud_parzis_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.vflgeo_bud_parzis_v AS
 SELECT foo.vflgeo_id,
    foo.vflz_id,
    foo.geometry,
    foo.wkb_geometry,
    foo.vflz_combined_id_kt,
    foo.obje_bezeichnung,
    foo.c_vflz_vftyp,
    foo.c_vflz_bearbstand,
    foo.c_bewertung,
    foo.c_vflz_unterstand,
    foo.h_gem_id,
    c1.bezeichnung AS vftyp,
    c2.bezeichnung AS bearbstand,
    c3.bezeichnung AS bewertung,
    c4.bezeichnung AS unterstand,
    g.gemeinde,
    foo.c_vflz_deponietyp,
    foo.c_vflz_inbetrieb,
    foo.c_vflz_nachsorge
   FROM (((((( SELECT g_1.vflgeo_id,
            v.vflz_id,
            public.st_astext(g_1.wkb_geometry) AS geometry,
            g_1.wkb_geometry,
            v.vflz_combined_id_kt,
            v.bezeichnung AS obje_bezeichnung,
            v.c_vflz_vftyp,
            v.c_vflz_bearbstand,
            vflz.c_vflz_deponietyp,
            vflz.c_vflz_inbetrieb,
            vflz.c_vflz_nachsorge,
            (
                CASE
                    WHEN (b.c_bere_res_abwbewe IS NULL) THEN 'BLKR09'::character varying
                    ELSE b.c_bere_res_abwbewe
                END)::text AS c_bewertung,
            v.c_vflz_unterstand,
            v.h_gem_id
           FROM (((altlast.vflz_current_v v
             JOIN altlast.vflgeo g_1 ON ((g_1.vflz_id = v.vflz_id)))
             LEFT JOIN altlast.bere b ON ((b.vflz_id = v.vflz_id)))
             JOIN altlast.vflz ON ((vflz.vflz_id = v.vflz_id)))) foo
     LEFT JOIN altlast.h_gem g USING (h_gem_id))
     LEFT JOIN altlast.cod c1 ON (((c1.c_cli_id = 63) AND ((c1.code)::text = (foo.c_vflz_vftyp)::text))))
     LEFT JOIN altlast.cod c2 ON (((c2.c_cli_id = 55) AND ((c2.code)::text = (foo.c_vflz_bearbstand)::text))))
     LEFT JOIN altlast.cod c3 ON (((c3.c_cli_id = 103) AND ((c3.code)::text = foo.c_bewertung))))
     LEFT JOIN altlast.cod c4 ON (((c4.c_cli_id = 10023) AND ((c4.code)::text = (foo.c_vflz_unterstand)::text))));


--
-- Name: VIEW vflgeo_bud_parzis_v; Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON VIEW altlast.vflgeo_bud_parzis_v IS 'BS specific. Queried by external tool running at BL.';


