    erfassungs_datum timestamp without time zone DEFAULT now(),
    erfasser_kuerzel character varying(8) DEFAULT "current_user"(),
    mutations_datum timestamp without time zone DEFAULT now(),
    mutierer_kuerzel character varying(8)
);


--
-- Name: vflgeo_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.vflgeo_v AS
 SELECT g.vflgeo_id,
    v.vflz_id,
    g.wkb_geometry,
    v.vflz_combined_id_kt AS stonr,
    v.bezeichnung,
    v.c_vflz_bearbstand,
    v.c_vflz_bearbstand AS c_bearbeitungsstand,
    v.c_vflz_vftyp,
    (b.c_bere_res_abwbewe)::text AS c_bewertung,
    (
        CASE
            WHEN (cc.color_rgb IS NULL) THEN '0 0 0'::character varying
            ELSE cc.color_rgb
        END)::text AS color_rgb,
    (
        CASE
            WHEN (cc.color_rgb IS NULL) THEN 0
            ELSE altlast.mapserver_drawing_priority(altlast.mapserver_color_to_triple((cc.color_rgb)::text))
        END)::text AS drawing_priority,
    altlast.t(altlast.msgid_code(v.h_vflz_bearbstand, v.c_vflz_bearbstand)) AS bearbeitungsstand,
    altlast.t(altlast.msgid_code(v.h_vflz_vftyp, v.c_vflz_vftyp), 'de'::text) AS standorttyp,
    altlast.t(altlast.msgid_code(b.h_bere_res_abwbewe, b.c_bere_res_abwbewe), 'de'::text) AS beurteilung
   FROM (((altlast.vflz v
     JOIN altlast.vflgeo g ON ((g.vflz_id = v.vflz_id)))
     LEFT JOIN altlast.bere b ON ((b.vflz_id = v.vflz_id)))
     LEFT JOIN altlast.cod_kbscolor cc ON (((cc.c_bere_res_abwbewe)::text = (b.c_bere_res_abwbewe)::text)));


--
-- Name: VIEW vflgeo_v; Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON VIEW altlast.vflgeo_v IS 'Minimal view to vflgeo for usage with mapserver. this view should be kept fast.
This version only respect c_bere_res_abwbewe for color. c_vflz_bearbstand could be also interpreted if needed.';


