--
-- Name: vflnr_exclusive_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.vflnr_exclusive_v AS
 SELECT vflnr.vflz_id,
    (vflnr.nummer)::text AS nummer
   FROM altlast.vflnr
EXCEPT
 SELECT vflz.vflz_id,
    (vflz.vflz_combined_id_kt)::text AS nummer
   FROM altlast.vflz;


--
-- Name: VIEW vflnr_exclusive_v; Type: COMMENT; Schema: altlast; Owner: -
--

COMMENT ON VIEW altlast.vflnr_exclusive_v IS 'Show only those numbers in result list that are not currently active. 
But search for active and inactive numbers at a time.';


--
-- Name: vflnr_hist_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.vflnr_hist_v AS
 SELECT v.vflz_id AS current_vflz_id,
    v2.vflz_id,
    vflnr.vflnr_id,
    vflnr.nummer,
    org.kuerzel,
    COALESCE(s.created, vfl.erfassungs_datum) AS created
   FROM (((((altlast.vflz v
     LEFT JOIN altlast.vflz vfl ON ((vfl.vfl_id = v.vfl_id)))
     LEFT JOIN altlast_hist.snapshot s ON (((vfl.vflz_id = s.key_value) AND (s.history_id = 1))))
     JOIN altlast.vflz v2 ON ((v2.vflz_id = vfl.vflz_id)))
     JOIN altlast.vflnr ON (((vflnr.vflz_id = v2.vflz_id) AND vflnr.aktiv)))
     JOIN altlast.org USING (org_id))
  WHERE (NOT s.is_current)
  ORDER BY COALESCE(s.created, vfl.erfassungs_datum) DESC;


--
-- Name: vflnr_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.vflnr_v AS
 SELECT v.vflz_id,
    COALESCE(n.nummer, 'unbekannte Nummer'::character varying, n.nummer) AS nummer,
    n.org_id
   FROM (altlast.vflz v
     LEFT JOIN altlast.vflnr n USING (vflz_id));


