--
-- Name: vflz_duration_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.vflz_duration_v AS
 SELECT DISTINCT vflz.vflz_id,
    ((COALESCE(
        CASE
            WHEN vflz.zeitraum_vonjahr THEN (date_part('year'::text, vflz.zeitraum_von))::text
            ELSE (vflz.zeitraum_von)::text
        END, ''::text) || '..'::text) || COALESCE(
        CASE
            WHEN vflz.zeitraum_vonjahr THEN (date_part('year'::text, vflz.zeitraum_bis))::text
            ELSE (vflz.zeitraum_bis)::text
        END, ''::text)) AS duration,
    vflz.zeitraum_von,
    vflz.zeitraum_bis
   FROM altlast.vflz;


--
-- Name: vflz_hist_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.vflz_hist_v AS
 SELECT hs.key_value AS vflz_id,
    hs.created
   FROM (altlast_hist.snapshot hs
     JOIN altlast_hist.history hh ON ((hh.history_id = hs.history_id)))
  WHERE (((hh.key_column)::text = 'vflz_id'::text) AND (hs.is_current = true));


--
-- Name: vflz_icons_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.vflz_icons_v AS
 SELECT DISTINCT ON (icons.vflz_id) icons.vflz_id,
    (icons.icon || '.png'::text) AS icon,
    (icons.icon || '_medium.png'::text) AS icon_medium,
    (icons.icon || '_large.png'::text) AS icon_large
   FROM ( SELECT vflz.vflz_id,
            (('img/standort'::text ||
                CASE
                    WHEN vflz_is_current_v.is_current THEN ''::text
                    ELSE '_historized'::text
                END) ||
                CASE
                    WHEN vflz.publizieren THEN (
                    CASE
                        WHEN (COALESCE(cod_berekbs.kbs, false) = false) THEN '_unpublished'::text
                        ELSE '_published'::text
                    END ||
                    CASE
                        WHEN (vflz_is_published_v.is_latest_published OR vflz_is_current_v.is_current) THEN ''::text
                        ELSE '_old'::text
                    END)
                    ELSE ''::text
                END) AS icon
           FROM ((((altlast.vflz
             JOIN altlast.vflz_is_current_v USING (vflz_id))
             LEFT JOIN altlast.bere USING (vflz_id))
             LEFT JOIN altlast.cod_berekbs ON (((cod_berekbs.h_bere_res_abwbewe = bere.h_bere_res_abwbewe) AND ((cod_berekbs.c_bere_res_abwbewe)::text = (bere.c_bere_res_abwbewe)::text))))
             JOIN altlast.vflz_is_published_v USING (vflz_id))) icons;


--
-- Name: vflz_kbs_all_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.vflz_kbs_all_v AS
 SELECT vflz.vflz_id,
    vflz.vflz_combined_id_kt AS standortnummer,
    altlast.t(altlast.msgid_code(vflz.h_vflz_vftyp, vflz.c_vflz_vftyp)) AS standortstyp,
    vflz.bezeichnung,
    altlast.t(altlast.msgid_code(b.h_bere_res_abwbewe, b.c_bere_res_abwbewe)) AS bewertung,
    altlast.t(altlast.msgid_code(vflz.h_vflz_bearbstand, vflz.c_vflz_bearbstand)) AS bearbeitungsstand,
    vflgeo.wkb_geometry,
    (
        CASE
            WHEN (cc.color_rgb IS NULL) THEN '0 0 0'::character varying
            ELSE cc.color_rgb
        END)::text AS color_rgb,
    (
        CASE
            WHEN (cc.color_rgb IS NULL) THEN 0
            ELSE altlast.mapserver_drawing_priority(altlast.mapserver_color_to_triple((cc.color_rgb)::text))
        END)::text AS drawing_priority
   FROM (((((altlast.vflz
     JOIN altlast_hist.snapshot ON ((vflz.vflz_id = snapshot.key_value)))
     JOIN altlast_hist.history ON ((history.history_id = snapshot.history_id)))
     JOIN altlast.bere b USING (vflz_id))
     LEFT JOIN altlast.cod_kbscolor cc ON (((cc.c_bere_res_abwbewe)::text = (b.c_bere_res_abwbewe)::text)))
     LEFT JOIN altlast.vflgeo USING (vflz_id))
  WHERE (((history.key_column)::text = 'vflz_id'::text) AND snapshot.is_current);


--
-- Name: vflz_parcels_materialization_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.vflz_parcels_materialization_v AS
 SELECT sources_combined.vflz_id,
    sources_combined.h_gem_id,
    sources_combined.grun_id,
    sources_combined.gb_nummer,
    bool_or(sources_combined.source_geometry) AS source_geometry
   FROM ( SELECT v.vflz_id,
            g.h_gem_id,
            g.grun_id,
            g.gb_nummer,
            true AS source_geometry
           FROM (altlast.grun g
             JOIN altlast.vflgeo v ON ((public.st_isvalid(v.wkb_geometry) AND public.st_isvalid(g.wkb_geometry) AND public.st_intersects(v.wkb_geometry, g.wkb_geometry))))
          WHERE g.c_status
        UNION
         SELECT sv.vflz_id,
            g.h_gem_id,
            g.grun_id,
            g.gb_nummer,
            false AS source_geometry
           FROM ((altlast.subj_vflz sv
             JOIN altlast.subj_vflz_grun svg USING (subj_vflz_id))
             JOIN altlast.grun g ON ((svg.grun_id = g.grun_id)))
          WHERE g.c_status) sources_combined
  GROUP BY sources_combined.vflz_id, sources_combined.h_gem_id, sources_combined.grun_id, sources_combined.gb_nummer;


--
-- Name: vflz_parzellen_geo_v; Type: VIEW; Schema: altlast; Owner: -
--

CREATE VIEW altlast.vflz_parzellen_geo_v AS
 SELECT vflz_parcels_v.vflz_id,
    vflz_parcels_v.h_gem_id,
    altlast.commacat_all(vflz_parcels_v.parcel) AS parzellen
   FROM altlast.vflz_parcels_v
  WHERE vflz_parcels_v.source_geometry
  GROUP BY vflz_parcels_v.vflz_id, vflz_parcels_v.h_gem_id;


