CREATE VIEW altlast.vflz_subj_all AS
 SELECT subj_vflz.subj_id,
    subj_vflz.vflz_id
   FROM altlast.subj_vflz
UNION
 SELECT pm_cache_subj.subj_id,
    vflz.vflz_id
   FROM (((altlast.pm_cache_subj
     JOIN altlast.pm_cache USING (pm_cache_id))
     JOIN altlast.pm_vfl USING (pm_vfl_id))
     JOIN altlast.vflz USING (vfl_id))
UNION
 SELECT pm_doc_subj.subj_id,
    vflz.vflz_id
   FROM ((((altlast.pm_doc_subj
     JOIN altlast.pm_doc USING (pm_doc_id))
     JOIN altlast.pm_cache USING (pm_cache_id))
     JOIN altlast.pm_vfl USING (pm_vfl_id))
     JOIN altlast.vflz USING (vfl_id));


