--

CREATE VIEW altlast.vollzug_sbb_v AS
 SELECT o.org_id,
    o.kuerzel,
    v.vfl_id,
    v.vflz_id
   FROM (((altlast.vflz v
     JOIN altlast_hist.snapshot h ON (((h.history_id = 1) AND (h.key_value = v.vflz_id))))
     JOIN altlast.vflnr n ON (((n.vflz_id = v.vflz_id) AND n.aktiv)))
     JOIN altlast.org o ON ((o.org_id = n.org_id)))
  WHERE (h.reason = 'initial copy'::text);


