-- Name: zusa; Type: TABLE; Schema: altlast; Owner: -
--

CREATE TABLE altlast.zusa (
    zusa_id integer NOT NULL,
    vflz_id integer,
    h_zusa_art integer DEFAULT 57,
    c_zusa_art character varying(8) DEFAULT '05'::character varying,
    zusa_angaben character varying,
