--
-- Name: auth; Type: VIEW; Schema: altlast_admin; Owner: -
--

CREATE VIEW altlast_admin.auth AS
 SELECT pa.rolname,
    pa.rolpassword
   FROM ((pg_authid pa
     JOIN pg_auth_members pam ON ((pa.oid = pam.member)))
     JOIN pg_authid pag ON ((pag.oid = pam.roleid)))
  WHERE (pag.rolname = 'altlast'::name);


--
-- Name: VIEW auth; Type: COMMENT; Schema: altlast_admin; Owner: -
--

COMMENT ON VIEW altlast_admin.auth IS 'lists all altlast relevant roles from pg_catalog. used for the authentication to access altlast';


--
-- Name: cod_references; Type: VIEW; Schema: altlast_admin; Owner: -
--

CREATE VIEW altlast_admin.cod_references AS
 SELECT (a.table_name)::character varying AS table_name,
    a.col,
    count(*) AS col_count,
    (COALESCE(sum(a.default_c_cli_id), (0)::bigint))::integer AS default_c_cli_id
   FROM ( SELECT pg_class.relname AS table_name,
            "substring"((pg_attribute.attname)::text, '[c|h]\_(.*)'::text) AS col,
            (pg_get_expr(pg_attrdef.adbin, pg_attrdef.adrelid))::integer AS default_c_cli_id
           FROM (((pg_namespace altlast_namespace
             JOIN pg_class ON ((pg_class.relnamespace = altlast_namespace.oid)))
             JOIN pg_attribute ON ((pg_attribute.attrelid = pg_class.oid)))
             LEFT JOIN pg_attrdef ON (((pg_attrdef.adnum = pg_attribute.attnum) AND (pg_attrdef.adrelid = pg_attribute.attrelid) AND (pg_attribute.attname ~~* 'h\_%'::text))))
          WHERE ((altlast_namespace.nspname = 'altlast'::name) AND ((pg_attribute.attname ~~* 'c\_%'::text) OR (pg_attribute.attname ~~* 'h\_%'::text)) AND ((pg_class.relname)::text <> ALL (ARRAY[('cod'::character varying)::text, ('c_cli'::character varying)::text, ('branchen'::character varying)::text, ('bra_asw_noga'::character varying)::text, ('byta_cod'::character varying)::text, ('ecod'::character varying)::text, ('grun_subj'::character varying)::text, ('cod_bezart'::character varying)::text, ('cod_berekbs'::character varying)::text, ('cod_kbscolor'::character varying)::text, ('attr'::character varying)::text])) AND (pg_class.relkind = 'r'::"char") AND ((pg_attribute.attname ~~* 'c\_%'::text) OR ((pg_attribute.attname ~~* 'h\_%'::text) AND (pg_get_expr(pg_attrdef.adbin, pg_attrdef.adrelid) ~ '^[0-9]+$'::text))) AND (NOT ((pg_class.relname ~~* '_bkp_%'::text) OR (pg_class.relname ~~* '%_backup'::text) OR (pg_class.relname ~~* '%_bkp'::text))))) a
  GROUP BY a.table_name, a.col
 HAVING (count(*) = 2);


--
-- Name: VIEW cod_references; Type: COMMENT; Schema: altlast_admin; Owner: -
--

COMMENT ON VIEW altlast_admin.cod_references IS 'lists all code fields checked when modifiying codes through the altlast gui.
only tables with a col_count=2 will be checked. col_count=1 indicates that the corresponding h_column is missing ';


