--
-- Name: permissions; Type: VIEW; Schema: altlast_admin; Owner: -
--

CREATE VIEW altlast_admin.permissions AS
 WITH unrestricted AS (
         SELECT NULL::integer AS int4,
            acl_user.rolname,
            acl_resource.resource_name,
            acl_action.action_name
           FROM (((((altlast_admin.acl_user
             JOIN altlast_admin.acl_role_user ON ((acl_user.user_id = acl_role_user.user_id)))
             JOIN altlast_admin.acl_acl ON ((acl_role_user.role_id = acl_acl.role_id)))
             JOIN altlast_admin.acl_action ON ((acl_acl.action_id = acl_action.action_id)))
             JOIN altlast_admin.acl_resource ON ((acl_action.resource_id = acl_resource.resource_id)))
             JOIN altlast_admin.acl_role ON ((acl_role_user.role_id = acl_role.role_id)))
          WHERE (acl_acl.allow AND (acl_role.pool_id IS NULL))
        )
 SELECT DISTINCT grants.vfl_id,
    grants.rolname,
    grants.resource_name,
    grants.action_name
   FROM ( SELECT vfl_pool.vfl_id,
            acl_user.rolname,
            acl_resource.resource_name,
            acl_action.action_name
           FROM ((((((altlast_admin.acl_user
             JOIN altlast_admin.acl_role_user ON ((acl_user.user_id = acl_role_user.user_id)))
             JOIN altlast_admin.acl_acl ON ((acl_role_user.role_id = acl_acl.role_id)))
             JOIN altlast_admin.acl_action ON ((acl_acl.action_id = acl_action.action_id)))
             JOIN altlast_admin.acl_resource ON ((acl_action.resource_id = acl_resource.resource_id)))
             JOIN altlast_admin.acl_role ON ((acl_role_user.role_id = acl_role.role_id)))
             JOIN altlast.vfl_pool ON ((acl_role.pool_id = vfl_pool.pool_id)))
          WHERE (acl_acl.allow AND (NOT (((acl_resource.resource_name)::text, (acl_action.action_name)::text) IN ( SELECT unrestricted.resource_name,
                    unrestricted.action_name
                   FROM unrestricted))))
        UNION
         SELECT unrestricted.int4,
            unrestricted.rolname,
            unrestricted.resource_name,
            unrestricted.action_name
           FROM unrestricted) grants;


--
-- Name: VIEW permissions; Type: COMMENT; Schema: altlast_admin; Owner: -
--

COMMENT ON VIEW altlast_admin.permissions IS 'Lists all granted permissions';


--
-- Name: COLUMN permissions.vfl_id; Type: COMMENT; Schema: altlast_admin; Owner: -
--

COMMENT ON COLUMN altlast_admin.permissions.vfl_id IS 'vfl_id for which the permission applies. NULL means permissions that apply for all vfl_id.';


