    ili_code character varying(8) NOT NULL,
    ili_c_cli_id integer NOT NULL,
    pro_uid character varying(32),
    tas_uid character varying(32),
    a4w_code character varying(20)
);


--
-- Name: task_mapping_v; Type: VIEW; Schema: altlast_ili; Owner: -
--

CREATE VIEW altlast_ili.task_mapping_v AS
 SELECT cm.ili_code,
    cm.ili_c_cli_id,
    cm.pro_uid,
    cm.tas_uid,
    cl.code_long,
    pc.con_value AS tas_title,
    cm.a4w_code
   FROM ((altlast_ili.task_mapping cm
     JOIN altlast_ili.cod_long cl ON (((cl.c_cli_id = cm.ili_c_cli_id) AND ((cl.code)::text = (cm.ili_code)::text))))
     LEFT JOIN altlast.pm_content pc ON ((((pc.con_category)::text = 'TAS_TITLE'::text) AND ((pc.con_id)::text = (cm.tas_uid)::text) AND ((pc.con_lang)::text = 'de'::text))));


