--
-- Name: ffh; Type: VIEW; Schema: altlast_user; Owner: -
--

CREATE VIEW altlast_user.ffh AS
 WITH perm AS (
         SELECT permissions.vfl_id
           FROM altlast_admin.permissions
          WHERE (((permissions.rolname)::text = 'mag'::text) AND ((permissions.resource_name)::text = 'standort'::text) AND ((permissions.action_name)::text = 'show-location-data'::text))
        )
 SELECT search_sql.type_de_site,
    search_sql.num_ro_site,
    search_sql.description,
    search_sql.commune,
    search_sql.evaluation,
    search_sql.phase_de_travail,
    search_sql.phase_d_investigation,
    search_sql.ex_cution,
    search_sql.postleitzahl_ortsname
   FROM ( SELECT DISTINCT vflz.vflz_id AS data_id,
            vfl_kennung_v.sto_kennung AS map_list_title,
            vfl_kennung_v.list_entry,
            vflz_icons_v.icon_medium,
            altlast.t(altlast.msgid_code(vflz.h_vflz_vftyp, vflz.c_vflz_vftyp)) AS type_de_site,
            vflz.vflz_combined_id_kt AS num_ro_site,
            vflz.bezeichnung AS description,
            searchfield_gemeinde_parzellen_v.gemeinde AS commune,
            altlast.t(altlast.msgid_code(bere.h_bere_res_abwbewe, bere.c_bere_res_abwbewe)) AS evaluation,
            altlast.t(altlast.msgid_code(vflz.h_vflz_bearbstand, vflz.c_vflz_bearbstand)) AS phase_de_travail,
            altlast.t(altlast.msgid_code(vflz.h_vflz_unterstand, vflz.c_vflz_unterstand)) AS phase_d_investigation,
            org_aktiv_v.bezeichnung AS ex_cution,
            searchfield_vflz_postleitzahl_ortsname_v.lookup_option AS postleitzahl_ortsname
           FROM ((((((((altlast.vflz
             LEFT JOIN altlast.bere ON ((bere.vflz_id = vflz.vflz_id)))
             LEFT JOIN altlast.org_aktiv_v ON ((org_aktiv_v.vflz_id = vflz.vflz_id)))
             LEFT JOIN altlast.searchfield_gemeinde_parzellen_v ON ((searchfield_gemeinde_parzellen_v.vflz_id = vflz.vflz_id)))
             LEFT JOIN altlast.searchfield_vflz_postleitzahl_ortsname_v ON ((searchfield_vflz_postleitzahl_ortsname_v.vflz_id = vflz.vflz_id)))
             LEFT JOIN altlast.vfl_kennung_v ON ((vfl_kennung_v.vflz_id = vflz.vflz_id)))
             LEFT JOIN altlast.vflz_is_current_v ON ((vflz.vflz_id = vflz_is_current_v.vflz_id)))
             LEFT JOIN altlast.vflz_icons_v ON ((vflz.vflz_id = vflz_icons_v.vflz_id)))
             JOIN perm ON (((vflz.vfl_id = perm.vfl_id) OR (perm.vfl_id IS NULL))))
          WHERE ((vflz.vflz_id IN ( SELECT vflz_1.vflz_id
                   FROM (altlast.vflz vflz_1
                     LEFT JOIN altlast.bere bere_1 ON ((bere_1.vflz_id = vflz_1.vflz_id)))
