   FROM ( SELECT DISTINCT vflz.vflz_id AS data_id,
            vfl_kennung_v.sto_kennung AS map_list_title,
            vfl_kennung_v.list_entry,
            vflz_icons_v.icon_medium,
            vflz.bezeichnung AS description,
            vflz.vflz_combined_id_kt AS num_ro_site,
            (searchfield_pmfv_datum_ausza_abgel_und_ausza_verur.value)::date AS schlussabrechnung_auszahlung_abgeltungen_und_auszahlung_verursa,
            searchfield_pmfv_ausbezahlte_abgeltungen_betrag.value AS schlussabrechnung_betrag_abgeltungen,
