            searchfield_pmfv_summe_ausgaben.value AS schlussabrechnung_summe_ausgaben,
            searchfield_pmfv_summe_einnahmen.value AS schlussabrechnung_summe_einnahmen,
            searchfield_pmfv_empfang_vasa_betrag.value AS vasa_abgeltungen_betrag_vasa,
