            searchfield_pmfv_teilzahlung_summe.value AS vollzug_kanton_summe_teilzahlung,
            searchfield_pmfv_voraussichtliche_kosten.value AS vollzug_kanton_vorausichtliche_kosten,
            (searchfield_pmfv_voraussichtliche_kosten_datum.value)::date AS vollzug_kanton_vorausichtliche_kosten_datum,
            searchfield_pmfv_voraussichtliche_vasa_abgeltungen.value AS vollzug_kanton_voraussichliche_vasa_abgeltungen,
            (searchfield_pmfv_voraussichtli_vasa_abgeltungen_datum.value)::date AS vollzug_kanton_voraussichliche_vasa_abgeltungen_datum,
            searchfield_pmfv_voraussichtliche_rueckzahlung_betrag.value AS vollzug_kanton_voraussichlicher_betrag_r_ckzahlung,
            (searchfield_pmfv_voraussichtliche_rueckzahlung_datum.value)::date AS vollzug_kanton_voraussichlicher_betrag_r_ckzahlung_datum,
            searchfield_pmfv_rueckzahlung_vorschuss_betrag.value AS vorschussverf_gung_betrag_r_ckzahlung,
            (searchfield_pmfv_rueckzahlung_vorschuss_datum.value)::date AS vorschussverf_gung_betrag_r_ckzahlung_datum,
            searchfield_pmfv_vorschuss_betrag.value AS vorschussverf_gung_betrag_vorschuss,
            (searchfield_pmfv_vorschuss_betrag_datum.value)::date AS vorschussverf_gung_betrag_vorschuss_datum,
            searchfield_pmfv_voraussic_betrag_vorschuss_rueckzahl.value AS vorschussverf_gung_vorausichtlicher_betrag_r_ckzahlung,
            (searchfield_pmfv_vorauszahlung_betrag_datum.value)::date AS vorsorge_fond_betrag_vorauszahlung_datum,
            searchfield_pmfv_vorauszahlung_betrag_vasa.value AS vorsorge_fond_betrag_vorauszahlung_vasa,
            (searchfield_pmfv_voraussichtlicher_betrag_fond_datum.value)::date AS vorsorge_fond_voraussichtliche_abgeltungen_datum,
            searchfield_pmfv_voraussichtlicher_betrag_lsites.value AS vorsorge_fond_voraussichtliche_abgeltungen_lsites,
            searchfield_pmfv_voraussichtlicher_betrag_vasa.value AS vorsorge_fond_voraussichtliche_abgeltungen_vasa,
            searchfield_pmfv_vorauszahlung_betrag_lsites.value AS vorsorge_fonds_betrag_vorauszahlung_lsites,
            searchfield_gemeinde_parzellen_v.gemeinde AS commune,
            subj.taetigkeit AS activit_,
            intb_branche_v.intb_bran_formatted AS branche,
            altlast.t(altlast.msgid_code(intb_branche_v.h_intb_bran, intb_branche_v.c_intb_bran)) AS branchen_name,
            bere.bere_prio_untersuch AS prioris_besoin_d_investigation,
            altlast.t(altlast.msgid_code(vflz.h_vflz_bearbstand, vflz.c_vflz_bearbstand)) AS phase_de_travail,
            altlast.t(altlast.msgid_code(vflz.h_vflz_unterstand, vflz.c_vflz_unterstand)) AS phase_d_investigation,
            altlast.t(altlast.msgid_code(bere.h_bere_res_abwbewe, bere.c_bere_res_abwbewe)) AS evaluation,
            lookup_bem_bere_begr_abwbewe_v.bem AS justification_de_l_valuation,
            lookup_bem_bere_begr_prio_untersuch_v.bem AS justification_priorit_pour_le_besoin_d_investigation,
            lookup_bem_bere_begr_prio_sanier_v.bem AS justification_priorit_pour_le_besoin_de_surveillance_d_assainis
           FROM ((((((((((((((((((((((((((((((((((((((((altlast.vflz
             LEFT JOIN altlast.bere ON ((bere.vflz_id = vflz.vflz_id)))
             LEFT JOIN altlast.subj_vflz ON ((subj_vflz.vflz_id = vflz.vflz_id)))
             LEFT JOIN altlast.subj ON ((subj.subj_id = subj_vflz.subj_id)))
             LEFT JOIN altlast.lookup_bem_bere_begr_abwbewe_v ON ((lookup_bem_bere_begr_abwbewe_v.key_value = vflz.vflz_id)))
             LEFT JOIN altlast.lookup_bem_bere_begr_prio_sanier_v ON ((lookup_bem_bere_begr_prio_sanier_v.key_value = vflz.vflz_id)))
             LEFT JOIN altlast.lookup_bem_bere_begr_prio_untersuch_v ON ((lookup_bem_bere_begr_prio_untersuch_v.key_value = vflz.vflz_id)))
             LEFT JOIN altlast.searchfield_gemeinde_parzellen_v ON ((searchfield_gemeinde_parzellen_v.vflz_id = vflz.vflz_id)))
             LEFT JOIN altlast.vflz_is_current_v ON ((vflz.vflz_id = vflz_is_current_v.vflz_id)))
             LEFT JOIN altlast.vfl_kennung_v ON ((vfl_kennung_v.vflz_id = vflz.vflz_id)))
             LEFT JOIN altlast.vflz_icons_v ON ((vflz.vflz_id = vflz_icons_v.vflz_id)))
             LEFT JOIN altlast.searchfield_pmfv_empfang_vasa_betrag ON ((searchfield_pmfv_empfang_vasa_betrag.vfl_id = vflz.vfl_id)))
             LEFT JOIN altlast.searchfield_pmfv_empfang_vasa_betrag_datum ON ((searchfield_pmfv_empfang_vasa_betrag_datum.vfl_id = vflz.vfl_id)))
             LEFT JOIN altlast.searchfield_pmfv_vorschuss_betrag ON ((searchfield_pmfv_vorschuss_betrag.vfl_id = vflz.vfl_id)))
             LEFT JOIN altlast.searchfield_pmfv_vorschuss_betrag_datum ON ((searchfield_pmfv_vorschuss_betrag_datum.vfl_id = vflz.vfl_id)))
             LEFT JOIN altlast.searchfield_pmfv_rueckzahlung_vorschuss_betrag ON ((searchfield_pmfv_rueckzahlung_vorschuss_betrag.vfl_id = vflz.vfl_id)))
             LEFT JOIN altlast.searchfield_pmfv_rueckzahlung_vorschuss_datum ON ((searchfield_pmfv_rueckzahlung_vorschuss_datum.vfl_id = vflz.vfl_id)))
             LEFT JOIN altlast.searchfield_pmfv_voraussic_betrag_vorschuss_rueckzahl ON ((searchfield_pmfv_voraussic_betrag_vorschuss_rueckzahl.vfl_id = vflz.vfl_id)))
             LEFT JOIN altlast.searchfield_pmfv_voraussichtlicher_betrag_lsites ON ((searchfield_pmfv_voraussichtlicher_betrag_lsites.vfl_id = vflz.vfl_id)))
             LEFT JOIN altlast.searchfield_pmfv_voraussichtlicher_betrag_vasa ON ((searchfield_pmfv_voraussichtlicher_betrag_vasa.vfl_id = vflz.vfl_id)))
             LEFT JOIN altlast.searchfield_pmfv_voraussichtlicher_betrag_fond_datum ON ((searchfield_pmfv_voraussichtlicher_betrag_fond_datum.vfl_id = vflz.vfl_id)))
             LEFT JOIN altlast.searchfield_pmfv_vorauszahlung_betrag_lsites ON ((searchfield_pmfv_vorauszahlung_betrag_lsites.vfl_id = vflz.vfl_id)))
             LEFT JOIN altlast.searchfield_pmfv_vorauszahlung_betrag_vasa ON ((searchfield_pmfv_vorauszahlung_betrag_vasa.vfl_id = vflz.vfl_id)))
             LEFT JOIN altlast.searchfield_pmfv_vorauszahlung_betrag_datum ON ((searchfield_pmfv_vorauszahlung_betrag_datum.vfl_id = vflz.vfl_id)))
             LEFT JOIN altlast.searchfield_pmfv_voraussichtliche_kosten ON ((searchfield_pmfv_voraussichtliche_kosten.vfl_id = vflz.vfl_id)))
             LEFT JOIN altlast.searchfield_pmfv_voraussichtliche_kosten_datum ON ((searchfield_pmfv_voraussichtliche_kosten_datum.vfl_id = vflz.vfl_id)))
             LEFT JOIN altlast.searchfield_pmfv_voraussichtliche_vasa_abgeltungen ON ((searchfield_pmfv_voraussichtliche_vasa_abgeltungen.vfl_id = vflz.vfl_id)))
             LEFT JOIN altlast.searchfield_pmfv_voraussichtli_vasa_abgeltungen_datum ON ((searchfield_pmfv_voraussichtli_vasa_abgeltungen_datum.vfl_id = vflz.vfl_id)))
             LEFT JOIN altlast.searchfield_pmfv_voraussichtliche_rueckzahlung_betrag ON ((searchfield_pmfv_voraussichtliche_rueckzahlung_betrag.vfl_id = vflz.vfl_id)))
             LEFT JOIN altlast.searchfield_pmfv_voraussichtliche_rueckzahlung_datum ON ((searchfield_pmfv_voraussichtliche_rueckzahlung_datum.vfl_id = vflz.vfl_id)))
             LEFT JOIN altlast.searchfield_pmfv_teilzahlung_summe ON ((searchfield_pmfv_teilzahlung_summe.vfl_id = vflz.vfl_id)))
             LEFT JOIN altlast.searchfield_pmfv_summe_einnahmen ON ((searchfield_pmfv_summe_einnahmen.vfl_id = vflz.vfl_id)))
             LEFT JOIN altlast.searchfield_pmfv_summe_ausgaben ON ((searchfield_pmfv_summe_ausgaben.vfl_id = vflz.vfl_id)))
             LEFT JOIN altlast.searchfield_pmfv_ausbezahlte_abgeltungen_betrag ON ((searchfield_pmfv_ausbezahlte_abgeltungen_betrag.vfl_id = vflz.vfl_id)))
             LEFT JOIN altlast.searchfield_pmfv_auszahlung_verursacher_betrag ON ((searchfield_pmfv_auszahlung_verursacher_betrag.vfl_id = vflz.vfl_id)))
             LEFT JOIN altlast.searchfield_pmfv_datum_ausza_abgel_und_ausza_verur ON ((searchfield_pmfv_datum_ausza_abgel_und_ausza_verur.vfl_id = vflz.vfl_id)))
             LEFT JOIN altlast.searchfield_pmfv_rueckzahlung_verursacher_bertrag ON ((searchfield_pmfv_rueckzahlung_verursacher_bertrag.vfl_id = vflz.vfl_id)))
             LEFT JOIN altlast.searchfield_pmfv_datum_rueckzahlung_verursacher ON ((searchfield_pmfv_datum_rueckzahlung_verursacher.vfl_id = vflz.vfl_id)))
             LEFT JOIN altlast.intb ON ((intb.vflz_id = vflz.vflz_id)))
             LEFT JOIN altlast.intb_branche_v ON ((intb.intb_id = intb_branche_v.intb_id)))
             JOIN perm ON (((vflz.vfl_id = perm.vfl_id) OR (perm.vfl_id IS NULL))))
          WHERE ((vflz.vflz_id IN ( SELECT vflz_1.vflz_id
                   FROM (altlast.vflz vflz_1
                     LEFT JOIN altlast.bere bere_1 ON ((bere_1.vflz_id = vflz_1.vflz_id)))
                  WHERE ((COALESCE((bere_1.c_bere_res_abwbewe)::text, ''::text) = 'status5'::text) AND (COALESCE((vflz_1.c_vflz_vftyp)::text, ''::text) = '01'::text)))) AND (vflz_is_current_v.is_current = true))) search_sql
  ORDER BY search_sql.description, search_sql.data_id;


--
-- Name: step; Type: VIEW; Schema: altlast_user; Owner: -
--

CREATE VIEW altlast_user.step AS
 WITH perm AS (
         SELECT permissions.vfl_id
           FROM altlast_admin.permissions
          WHERE (((permissions.rolname)::text = 'geko'::text) AND ((permissions.resource_name)::text = 'standort'::text) AND ((permissions.action_name)::text = 'show-location-data'::text))
        )
 SELECT search_sql.standorttyp,
    search_sql.standort_nummer,
    search_sql.bezeichnung,
    search_sql.gemeinde,
    search_sql.beurteilung,
    search_sql.bearbeitungsstand,
    search_sql.phase_d_investigation,
    search_sql.vollzug
   FROM ( SELECT DISTINCT vflz.vflz_id AS data_id,
            vfl_kennung_v.sto_kennung AS map_list_title,
            vfl_kennung_v.list_entry,
            vflz_icons_v.icon_medium,
            altlast.t(altlast.msgid_code(vflz.h_vflz_vftyp, vflz.c_vflz_vftyp)) AS standorttyp,
            vflz.vflz_combined_id_kt AS standort_nummer,
            vflz.bezeichnung,
            searchfield_gemeinde_parzellen_v.gemeinde,
            altlast.t(altlast.msgid_code(bere.h_bere_res_abwbewe, bere.c_bere_res_abwbewe)) AS beurteilung,
            altlast.t(altlast.msgid_code(vflz.h_vflz_bearbstand, vflz.c_vflz_bearbstand)) AS bearbeitungsstand,
            altlast.t(altlast.msgid_code(vflz.h_vflz_unterstand, vflz.c_vflz_unterstand)) AS phase_d_investigation,
            org_aktiv_v.bezeichnung AS vollzug
           FROM (((((((altlast.vflz
             LEFT JOIN altlast.bere ON ((bere.vflz_id = vflz.vflz_id)))
             LEFT JOIN altlast.org_aktiv_v ON ((org_aktiv_v.vflz_id = vflz.vflz_id)))
             LEFT JOIN altlast.searchfield_gemeinde_parzellen_v ON ((searchfield_gemeinde_parzellen_v.vflz_id = vflz.vflz_id)))
             LEFT JOIN altlast.vfl_kennung_v ON ((vfl_kennung_v.vflz_id = vflz.vflz_id)))
             LEFT JOIN altlast.vflz_is_current_v ON ((vflz.vflz_id = vflz_is_current_v.vflz_id)))
             LEFT JOIN altlast.vflz_icons_v ON ((vflz.vflz_id = vflz_icons_v.vflz_id)))
             JOIN perm ON (((vflz.vfl_id = perm.vfl_id) OR (perm.vfl_id IS NULL))))
          WHERE ((vflz.vflz_id IN ( SELECT vflz_1.vflz_id
                   FROM altlast.vflz vflz_1
                  WHERE (COALESCE((vflz_1.bezeichnung)::text, ''::text) ~~* '%step%'::text))) AND (vflz_is_current_v.is_current = true))) search_sql
  ORDER BY search_sql.standorttyp, search_sql.data_id;


