--
-- Name: _repair_v; Type: VIEW; Schema: altlast_version1; Owner: -
--

CREATE VIEW altlast_version1._repair_v AS
 SELECT DISTINCT ON (dg.stonr) dg.vflgeo_id,
    dg.wkb_geometry,
    dg.stonr,
    dg.bezeichnung,
    (g.gs_id IS NOT NULL) AS mitbrief,
    dg.gb_nummern_1
   FROM ((((altlast_version1._repair_grun_diff_gb_nummern dg
     JOIN altlast_version1.vflz v ON ((v.vflz_id = dg.vflz_id)))
     JOIN altlast_version1.obje o ON ((v.obje_id = o.obje_id)))
     LEFT JOIN altlast_version1.gs_obje go ON ((go.obje_id = o.obje_id)))
     LEFT JOIN altlast_version1.gs g ON (((go.gs_id = g.gs_id) AND ((g.c_gs_typ)::text = ANY (ARRAY[('5'::character varying)::text, ('6'::character varying)::text, ('7'::character varying)::text, ('8'::character varying)::text])))))
  WHERE (g.gs_id IS NOT NULL)
  ORDER BY dg.stonr;


