     JOIN altlast_hist.snapshot ON ((vflz.vflz_id = snapshot.key_value)))
     JOIN altlast_hist.history ON ((history.history_id = snapshot.history_id)))
  WHERE (((history.key_column)::text = 'vflz_id'::text) AND snapshot.is_current);


--
-- Name: centroid_v; Type: VIEW; Schema: altlast_version1; Owner: -
--

CREATE VIEW altlast_version1.centroid_v AS
 SELECT o.obje_id,
    v.vflz_id,
        CASE
            WHEN (vgeo.wkb_geometry IS NOT NULL) THEN public.st_x(public.st_centroid(vgeo.wkb_geometry))
            ELSE (o.x_koordinate)::double precision
        END AS centroid_x,
        CASE
            WHEN (vgeo.wkb_geometry IS NOT NULL) THEN public.st_y(public.st_centroid(vgeo.wkb_geometry))
            ELSE (o.y_koordinate)::double precision
        END AS centroid_y
   FROM ((altlast_version1.obje o
     JOIN altlast_version1.vflz_current_v v ON ((v.obje_id = o.obje_id)))
     LEFT JOIN altlast_version1.vflgeo vgeo ON ((v.vflz_id = vgeo.vflz_id)));


--
-- Name: VIEW centroid_v; Type: COMMENT; Schema: altlast_version1; Owner: -
--

COMMENT ON VIEW altlast_version1.centroid_v IS 'Zeigt für jedes obje den centroid. Falls keine Geometrie vorhanden, werden die koordinaten aus obje genutzt';


