--
-- Name: obje_kennung_v; Type: VIEW; Schema: altlast_version1; Owner: -
--

CREATE VIEW altlast_version1.obje_kennung_v AS
 SELECT o.obje_id,
    v.vflz_id,
    (((((( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((v.c_vflz_vftyp)::text = (cod.code)::text) AND (cod.c_cli_id = 63))))::text || ' '::text) || (v.vflz_combined_id_kt)::text) || ': '::text) || altlast_version1.remove_linebreaks((o.bezeichnung)::text)) AS sto_kennung,
    (((v.vflz_combined_id_kt)::text || ': '::text) ||
        CASE
            WHEN (length((o.bezeichnung)::text) > 20) THEN (substr((o.bezeichnung)::text, 1, 18) || '...'::text)
            ELSE (o.bezeichnung)::text
        END) AS sto_kennung_kurz,
    v.vflz_combined_id_kt AS stonr,
    v.vflz_combined_id AS alternate_stonr
   FROM ((altlast_version1.obje o
     JOIN altlast_version1.vflz_current_v v ON (((o.obje_id = v.obje_id) AND v.zust_aktuell)))
     LEFT JOIN altlast_version1.bere b ON ((v.vflz_id = b.vflz_id)))
  WHERE (COALESCE((b.c_bere_res_abwbewe)::text, ''::text) <> ALL (ARRAY[('00'::character varying)::text, ('BLKR10'::character varying)::text]))
  ORDER BY v.vflz_combined_id_kt;


--
-- Name: VIEW obje_kennung_v; Type: COMMENT; Schema: altlast_version1; Owner: -
--

COMMENT ON VIEW altlast_version1.obje_kennung_v IS 'Eindeutig identifizierende
Kurz-Kennzeichnung fur einen Standort. Da jeder Kanton andere Vorgaben
hat, wie die Kennung zusammengesetzt werden soll, immer diesen View
statt Hartkodierung in der Applikation verwenden.';


