--
-- Name: fts_obje_v; Type: VIEW; Schema: altlast_version1; Owner: -
--

CREATE VIEW altlast_version1.fts_obje_v AS
 SELECT v.vflz_id,
    o.obje_id,
    o.sto_kennung,
    COALESCE(v.bemerkungen, ''::text) AS "Bemerkungen Standort",
    COALESCE(o.sto_kennung, ''::text) AS "Standort",
    COALESCE(ia.inta_ergaenzung, ''::character varying) AS "Bemerkungen Ablagerung",
    COALESCE(( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((k.c_kksk_stoffkl)::text = (cod.code)::text) AND (cod.c_cli_id = 94))), ''::character varying) AS "Stoffklasse",
    COALESCE(( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((kg.c_kksg_stoffgrp)::text = (cod.code)::text) AND (cod.c_cli_id >= 110) AND (cod.c_cli_id <= 114))), ''::character varying) AS "Stoffgruppe Ablagerung",
    COALESCE(ib.intb_ergaenzung, ''::character varying) AS "Bemerkungen Betrieb",
    COALESCE(iu.intu_ergaenzung, ''::character varying) AS "Bemerkungen Unfall",
    COALESCE(( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((k.c_kksk_stoffkl)::text = (cod.code)::text) AND (cod.c_cli_id = 117))), ''::character varying) AS "Unfall",
    (((COALESCE(bf.befr_aussage, ''::character varying))::text || ' '::text) || (COALESCE(bf.befr_zusatzinfo, ''::character varying))::text) AS "Befragte Personen",
    ((COALESCE(be.bere_begr_abwbewe, ''::text) || ' '::text) || (COALESCE(be.bere_begr_abw_art32c, ''::character varying))::text) AS "Bewertung",
    (((COALESCE(dk.doku_titel, ''::character varying))::text || ' '::text) || (COALESCE(dk.doku_abstract, ''::character varying))::text) AS "Dokumentation",
    COALESCE(eg.emiss_ergpotemissionen, ''::character varying) AS "Emissionen",
    COALESCE(( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((fw.c_frwa_fremdwasser)::text = (cod.code)::text) AND (cod.c_cli_id = 6))), ''::character varying) AS "Fremdwasser",
    COALESCE(ge.geol_geologie, ''::text) AS "Geologie",
    (((COALESCE(gs.gs_titel, ''::character varying))::text || ' '::text) || (COALESCE(gs.bemerkungen, ''::character varying))::text) AS "Geschäft",
    (((COALESCE(gss.gss_titel, ''::character varying))::text || ' '::text) || (COALESCE(gss.bemerkungen, ''::character varying))::text) AS "Teilgeschäft",
    (((COALESCE(gw.gwms_bezeichnung, ''::character varying))::text || ' '::text) || COALESCE((gw.gwms_gaso_nummer)::text, ''::text)) AS "GW-Messstelle",
    COALESCE(( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((gu.c_gwnu_nutzung)::text = (cod.code)::text) AND (cod.c_cli_id = 88))), ''::character varying) AS "Grundwasser",
    COALESCE(gv.gwvk_name_gw, ''::character varying) AS "Grundwasservork",
    COALESCE(kf.kumf_ergkunstumfeld, ''::character varying) AS "Bemerkungen künstl. Umfeld",
    (((COALESCE(( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((nb.c_nubo_nutzungsart)::text = (cod.code)::text) AND (cod.c_cli_id = 87))), ''::character varying))::text || ' akt. Nutzung '::text) || (COALESCE(( SELECT COALESCE(cod.bezeichnung, 'unbekannt'::character varying) AS "coalesce"
           FROM altlast_version1.cod
          WHERE (((nb.c_nubo_akt_nutzung)::text = (cod.code)::text) AND
                CASE
                    WHEN (nb.c_nubo_nutzungsart = '01'::bpchar) THEN (cod.c_cli_id = 83)
                    WHEN (nb.c_nubo_nutzungsart = '02'::bpchar) THEN (cod.c_cli_id = 84)
                    WHEN (nb.c_nubo_nutzungsart = '03'::bpchar) THEN (cod.c_cli_id = 85)
                    WHEN (nb.c_nubo_nutzungsart = '04'::bpchar) THEN (cod.c_cli_id = 86)
                    ELSE (cod.c_cli_id < '-9999'::integer)
                END)), ''::character varying))::text) AS "Nutzung Boden",
    COALESCE(nf.numf_ergnatumfeld, ''::character varying) AS "Bemerkungen nat. Umfeld",
    COALESCE(nz.nutzb_ergnutzboden, ''::character varying) AS "Bemerkungen Nutzung Boden",
    COALESCE(nw.nutzw_ergnutzwasser, ''::character varying) AS "Bemerkungen Nutzung Wasser",
    COALESCE(( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((ogw.c_ogw_nutzung)::text = (cod.code)::text) AND (cod.c_cli_id = 89))), ''::character varying) AS "Nutzung OGW",
    COALESCE(( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((vk.c_veek_verdflaeche)::text = (cod.code)::text) AND (cod.c_cli_id = 60))), ''::character varying) AS "Ereignis",
    COALESCE(( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((vn.c_veen_natuerlich)::text = (cod.code)::text) AND (cod.c_cli_id = 61))), ''::character varying) AS "Ereignis natürlich",
    COALESCE(vs.vfsv_sonst_vorkomm, ''::character varying) AS "Sonst. Vorkommnisse",
    (((COALESCE(( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((vu.c_vfus_art_schaden)::text = (cod.code)::text) AND (cod.c_cli_id = 101))), ''::character varying))::text || ' '::text) || (COALESCE(( SELECT COALESCE(cod.bezeichnung, 'unbekannt'::character varying) AS "coalesce"
           FROM altlast_version1.cod
          WHERE (((vu.c_vfus_schaeden)::text = (cod.code)::text) AND
                CASE
                    WHEN ((vu.c_vfus_art_schaden)::text = '02'::text) THEN (cod.c_cli_id = 102)
                    WHEN ((vu.c_vfus_art_schaden)::text = '03'::text) THEN (cod.c_cli_id = 102)
                    WHEN ((vu.c_vfus_art_schaden)::text = '04'::text) THEN (cod.c_cli_id = 100)
                    WHEN ((vu.c_vfus_art_schaden)::text = '05'::text) THEN (cod.c_cli_id = 99)
                    ELSE (cod.c_cli_id < '-9999'::integer)
                END)), ''::character varying))::text) AS "Schäden",
    COALESCE(( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((gu.c_gwnu_nutzung)::text = (cod.code)::text) AND (cod.c_cli_id = 91))), ''::character varying) AS "Pot. Gasemissionen",
    (((COALESCE(( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((zs.c_zusa_art)::text = (cod.code)::text) AND (cod.c_cli_id = 57))), ''::character varying))::text || ' '::text) || (COALESCE(zs.zusa_angaben, ''::character varying))::text) AS "Zusatzakten",
    ((((COALESCE(( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((v.c_vflz_gws_bereich)::text = (cod.code)::text) AND (cod.c_cli_id = 72))), ''::character varying))::text || (COALESCE(( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((v.c_vflz_durchlaessigkeit)::text = (cod.code)::text) AND (cod.c_cli_id = 58))), ''::character varying))::text) ||
        CASE
            WHEN (((v.c_vflz_ex_infiltration)::text = '01'::text) OR ((v.c_vflz_ex_infiltration)::text = '03'::text)) THEN ' Exfiltration '::text
            ELSE ''::text
        END) ||
        CASE
            WHEN (((v.c_vflz_ex_infiltration)::text = '01'::text) OR ((v.c_vflz_ex_infiltration)::text = '02'::text)) THEN ' Karstgebiet '::text
            ELSE ''::text
        END) AS "Nat. Umfeld",
    COALESCE(( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((v.c_vflz_ex_infiltration)::text = (cod.code)::text) AND (cod.c_cli_id = 68))), ''::character varying) AS "Exfiltration"
   FROM ((((((((((((((((((((((((((((((((((altlast_version1.vflz_current_v v
     JOIN altlast_version1.obje_kennung_v o ON ((o.obje_id = v.obje_id)))
     JOIN altlast_version1.obje o2 ON ((o2.obje_id = o.obje_id)))
     LEFT JOIN altlast_version1.bere be ON ((be.vflz_id = v.vflz_id)))
     LEFT JOIN altlast_version1.inta ia ON ((ia.vflz_id = v.vflz_id)))
     LEFT JOIN altlast_version1.kksk k ON ((k.vflz_id = v.vflz_id)))
     LEFT JOIN altlast_version1.kksg kg ON ((kg.kksk_id = k.kksk_id)))
     LEFT JOIN altlast_version1.intb ib ON ((ib.vflz_id = v.vflz_id)))
     LEFT JOIN altlast_version1.formba fa ON (((ib.intb_id = fa.intb_id) AND ((fa.intb_formblatt)::text = (ib.intb_formblatt)::text) AND (fa.antwort = 'J'::bpchar))))
     LEFT JOIN altlast_version1.formbq fq ON ((((fq.intb_formblatt)::text = (fa.intb_formblatt)::text) AND (fq.fragenr = fa.fragenr))))
     LEFT JOIN altlast_version1.intu iu ON ((iu.vflz_id = v.vflz_id)))
     LEFT JOIN altlast_version1.inum inu ON ((inu.intu_id = iu.intu_id)))
     LEFT JOIN altlast_version1.befr bf ON ((bf.vflz_id = v.vflz_id)))
     LEFT JOIN altlast_version1.doku dk ON ((dk.vflz_id = v.vflz_id)))
     LEFT JOIN altlast_version1.emiss eg ON ((eg.vflz_id = v.vflz_id)))
     LEFT JOIN altlast_version1.frwa fw ON ((fw.vflz_id = v.vflz_id)))
     LEFT JOIN altlast_version1.geol ge ON ((ge.vflz_id = v.vflz_id)))
     LEFT JOIN altlast_version1.gs_obje go ON ((go.obje_id = o.obje_id)))
     LEFT JOIN altlast_version1.gs gs ON ((gs.gs_id = go.gs_id)))
     LEFT JOIN altlast_version1.gss gss ON ((gss.gs_id = gs.gs_id)))
     LEFT JOIN altlast_version1.gwms gw ON ((gw.vflz_id = v.vflz_id)))
     LEFT JOIN altlast_version1.gwnu gu ON ((v.vflz_id = gu.vflz_id)))
     LEFT JOIN altlast_version1.gwvk gv ON ((gv.vflz_id = v.vflz_id)))
     LEFT JOIN altlast_version1.kumf kf ON ((kf.vflz_id = v.vflz_id)))
     LEFT JOIN altlast_version1.nubo nb ON ((nb.vflz_id = v.vflz_id)))
     LEFT JOIN altlast_version1.numf nf ON ((nf.vflz_id = v.vflz_id)))
     LEFT JOIN altlast_version1.nutzb nz ON ((nz.vflz_id = v.vflz_id)))
     LEFT JOIN altlast_version1.nutzw nw ON ((nw.vflz_id = v.vflz_id)))
     LEFT JOIN altlast_version1.ogw ogw ON ((ogw.vflz_id = v.vflz_id)))
     LEFT JOIN altlast_version1.veek vk ON ((vk.vflz_id = v.vflz_id)))
     LEFT JOIN altlast_version1.veen vn ON ((vn.vflz_id = v.vflz_id)))
     LEFT JOIN altlast_version1.vfsv vs ON ((vs.vflz_id = v.vflz_id)))
     LEFT JOIN altlast_version1.vfus vu ON ((vu.vflz_id = v.vflz_id)))
     LEFT JOIN altlast_version1.vgas vg ON ((vg.vflz_id = v.vflz_id)))
     LEFT JOIN altlast_version1.zusa zs ON ((zs.vflz_id = v.vflz_id)))
  WHERE (COALESCE((be.c_bere_res_abwbewe)::text, ''::text) <> ALL (ARRAY[('00'::character varying)::text, ('BLKR10'::character varying)::text]));


