--
-- Name: grunddaten_subj_v; Type: VIEW; Schema: altlast_version1; Owner: -
--

CREATE VIEW altlast_version1.grunddaten_subj_v AS
 SELECT DISTINCT ON (s.subj_id, v.vflz_combined_id_kt) k.sto_kennung,
    v.vflz_combined_id_kt AS nummer,
    o.obje_id,
    o.bezeichnung,
    ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((v.c_vflz_vftyp)::text = (cod.code)::text) AND (cod.c_cli_id = 63))) AS verdachtsflaechentyp,
    ( SELECT h_gem.gemeinde
           FROM altlast_version1.h_gem
          WHERE (o.h_gem_id = h_gem.h_gem_id)) AS gemeinde,
    ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((v.c_vflz_bearbstand)::text = (cod.code)::text) AND (cod.c_cli_id = 55))) AS bearbeitungsstand,
    s.subj_id,
    s.name,
    s.vorname,
    s.taetigkeit
   FROM (((((altlast_version1.obje o
     JOIN altlast_version1.obje_kennung_v k ON ((k.obje_id = o.obje_id)))
     JOIN altlast_version1.vflz_current_v v ON ((v.obje_id = o.obje_id)))
     JOIN altlast_version1.subj_obje so ON ((o.obje_id = so.obje_id)))
     JOIN altlast_version1.subj s ON ((s.subj_id = so.subj_id)))
     LEFT JOIN altlast_version1.bere b ON ((v.vflz_id = b.vflz_id)))
  WHERE (COALESCE((b.c_bere_res_abwbewe)::text, ''::text) <> ALL (ARRAY[('00'::character varying)::text, ('BLKR10'::character varying)::text]))
  ORDER BY s.subj_id, v.vflz_combined_id_kt;


--
-- Name: gs_diff; Type: VIEW; Schema: altlast_version1; Owner: -
--

CREATE VIEW altlast_version1.gs_diff AS
 SELECT DISTINCT v.vflz_id,
    altlast_version1.textcat_all(((((((cgt.bezeichnung)::text || ' '::text) || (cgs.bezeichnung)::text) || ' '::text) ||
        CASE
            WHEN (cgss.gs_id IS NULL) THEN '----'::text
            ELSE 'xxxxxx'::text
        END) || '
'::text)) AS gsdiff
   FROM (((((altlast_version1.vflz v
     JOIN altlast_version1.gs_obje go ON ((go.obje_id = v.obje_id)))
     JOIN ( SELECT gs.gs_id,
            gs.org_id,
            gs.gs_titel,
            gs.bemerkungen,
            gs.start_datum_planung,
            gs.end_datum_planung,
            gs.start_datum_ist,
            gs.end_datum_ist,
            gs.erfassungs_datum,
            gs.erfasser_kuerzel,
            gs.mutations_datum,
            gs.mutierer_kuerzel,
            gs.h_gs_status,
            gs.c_gs_status,
            gs.c_gs_typ,
            gs.h_gs_typ
           FROM altlast_version1.gs
          ORDER BY COALESCE(gs.start_datum_ist, COALESCE(gs.end_datum_ist, '1900-01-01'::date))) g ON ((g.gs_id = go.gs_id)))
     JOIN altlast_version1.cod cgt ON ((((cgt.code)::text = (g.c_gs_typ)::text) AND (cgt.c_cli_id = 2002))))
     JOIN altlast_version1.cod cgs ON ((((cgs.code)::text = (g.c_gs_status)::text) AND (cgs.c_cli_id = 2001))))
     LEFT JOIN ( SELECT gss.gs_id,
            count(*) AS count
           FROM altlast_version1.gss
          GROUP BY gss.gs_id) cgss ON ((cgss.gs_id = g.gs_id)))
  WHERE ((g.c_gs_typ)::text = ANY (ARRAY[('5'::character varying)::text, ('7'::character varying)::text, ('3'::character varying)::text]))
  GROUP BY v.vflz_id
  ORDER BY v.vflz_id, (altlast_version1.textcat_all(((((((cgt.bezeichnung)::text || ' '::text) || (cgs.bezeichnung)::text) || ' '::text) ||
        CASE
            WHEN (cgss.gs_id IS NULL) THEN '----'::text
            ELSE 'xxxxxx'::text
        END) || '
'::text)));


