--
-- Name: gs_gss_changes_v; Type: VIEW; Schema: altlast_version1; Owner: -
--

CREATE VIEW altlast_version1.gs_gss_changes_v AS
 SELECT go.obje_id,
    c.key_id AS gs_id,
    NULL::bigint AS gss_id,
    c.kategorie,
    k.sto_kennung,
    c.titel,
    c.changes,
    c."timestamp",
    c.mutierer_kuerzel,
    c.lc_id
   FROM ((altlast_version1.obje_kennung_v k
     JOIN altlast_version1.gs_obje go ON ((go.obje_id = k.obje_id)))
     JOIN altlast_version1.latest_changes c ON ((c.key_id = go.gs_id)))
  WHERE ((c.kategorie)::text = 'gs'::text)
UNION
 SELECT go.obje_id,
    go.gs_id,
    c.key_id AS gss_id,
    c.kategorie,
    k.sto_kennung,
    c.titel,
    c.changes,
    c."timestamp",
    c.mutierer_kuerzel,
    c.lc_id
   FROM ((altlast_version1.obje_kennung_v k
     JOIN altlast_version1.gss_obje go ON ((go.obje_id = k.obje_id)))
     JOIN altlast_version1.latest_changes c ON ((c.key_id = go.gss_id)))
  WHERE ((c.kategorie)::text = 'gss'::text);


