--
-- Name: gs_v; Type: VIEW; Schema: altlast_version1; Owner: -
--

CREATE VIEW altlast_version1.gs_v AS
 SELECT ges.stonr,
    ges.standort,
    ges.typ,
    ges.due,
        CASE
            WHEN (ges.titel IS NULL) THEN 'kein Geschäft definiert'::text
            ELSE ges.titel
        END AS titel,
    ges.duedate,
    ges.obje_id,
    ges.abschluss,
    ges.start_datum_planung,
    ges.start_datum_ist,
    ges.status,
    ges.gs_id,
    ges.gss_id,
    ges.pool_bezeichnung,
    ges.beteiligte,
    ges.gemeinde,
    ges.parzelle,
    ges.vflz_strasse,
    ges.vflz_hausnr
   FROM ( SELECT v.vflz_combined_id_kt AS stonr,
            o.bezeichnung AS standort,
            ( SELECT cod.bezeichnung
                   FROM altlast_version1.cod
                  WHERE ((cod.c_cli_id = gss.h_gss_typ) AND ((cod.code)::text = ((gss.c_gss_typ)::text || ''::text)))) AS typ,
            ('   - '::text || (gss.gss_titel)::text) AS titel,
            gss.end_datum_planung AS duedate,
            o.obje_id,
            gss.end_datum_ist AS abschluss,
            gss.start_datum_planung,
            gss.start_datum_ist,
            ac.bezeichnung AS status,
            gs.gs_id,
            gss.gss_id,
            p.bezeichnung AS pool_bezeichnung,
            gas.subj AS beteiligte,
            altlast_version1.due_gs(false, (gss.c_gss_status)::text, gss.start_datum_planung, gss.end_datum_planung, gss.start_datum_ist, gss.end_datum_ist) AS due,
            gov.gemeinde,
            grn.gb_nummer AS parzelle,
            v.vflz_strasse,
            v.vflz_hausnr
           FROM ((((((((((((altlast_version1.obje o
             JOIN altlast_version1.vflz_current_v v ON ((v.obje_id = o.obje_id)))
             JOIN altlast_version1.gs_obje gao ON ((gao.obje_id = o.obje_id)))
             JOIN altlast_version1.gs ON ((gao.gs_id = gs.gs_id)))
             JOIN altlast_version1.gss ON ((gs.gs_id = gss.gs_id)))
             JOIN altlast_version1.cod ac ON (((ac.c_cli_id = gss.h_gss_status) AND ((ac.code)::text = (gss.c_gss_status)::text))))
             LEFT JOIN altlast_version1.subj_obje_grun sog ON ((sog.obje_id = o.obje_id)))
             LEFT JOIN altlast_version1.grun grn ON ((grn.grun_id = sog.grun_id)))
             LEFT JOIN altlast_version1.h_gem gov ON ((o.h_gem_id = gov.h_gem_id)))
             LEFT JOIN altlast_version1.obje_pool op ON ((op.obje_id = o.obje_id)))
             LEFT JOIN altlast_version1.pool p ON ((op.pool_id = p.pool_id)))
             LEFT JOIN altlast_version1.gs_subj_all_v gas ON (((gas.gs_gss_id = gss.gss_id) AND (gas.isgs = false))))
             LEFT JOIN altlast_version1.bere b ON ((v.vflz_id = b.vflz_id)))
          WHERE (COALESCE((b.c_bere_res_abwbewe)::text, ''::text) <> ALL (ARRAY[('00'::character varying)::text, ('BLKR10'::character varying)::text]))
        UNION
         SELECT v.vflz_combined_id_kt AS stonr,
            o.bezeichnung AS standort,
            ( SELECT cod.bezeichnung
                   FROM altlast_version1.cod
                  WHERE ((cod.c_cli_id = gs.h_gs_typ) AND ((cod.code)::text = ((gs.c_gs_typ)::text || ''::text)))) AS typ,
            substr((gs.gs_titel)::text, 1, 120) AS titel,
            gs.end_datum_planung AS duedate,
            o.obje_id,
            gs.end_datum_ist AS abschluss,
            gs.start_datum_planung,
            gs.start_datum_ist,
            ac.bezeichnung AS status,
            gs.gs_id,
            '-1'::integer AS gss_id,
            p.bezeichnung AS pool_bezeichnung,
            gas.subj AS beteiligte,
            altlast_version1.due_gs(false, (gs.c_gs_status)::text, gs.start_datum_planung, gs.end_datum_planung, gs.start_datum_ist, gs.end_datum_ist) AS due,
            gov.gemeinde,
            grn.gb_nummer AS parzelle,
            v.vflz_strasse,
            v.vflz_hausnr
           FROM (((((((((((altlast_version1.obje o
             JOIN altlast_version1.vflz_current_v v ON ((v.obje_id = o.obje_id)))
             LEFT JOIN altlast_version1.subj_obje_grun sog ON ((sog.obje_id = o.obje_id)))
             LEFT JOIN altlast_version1.grun grn ON ((grn.grun_id = sog.grun_id)))
             LEFT JOIN altlast_version1.h_gem gov ON ((o.h_gem_id = gov.h_gem_id)))
             LEFT JOIN altlast_version1.obje_pool op ON ((op.obje_id = o.obje_id)))
             LEFT JOIN altlast_version1.pool p ON ((op.pool_id = p.pool_id)))
             LEFT JOIN altlast_version1.gs_obje gao ON ((gao.obje_id = o.obje_id)))
             LEFT JOIN altlast_version1.gs ON ((gao.gs_id = gs.gs_id)))
             LEFT JOIN altlast_version1.cod ac ON (((ac.c_cli_id = gs.h_gs_status) AND ((ac.code)::text = (gs.c_gs_status)::text))))
             LEFT JOIN altlast_version1.gs_subj_all_v gas ON (((gas.gs_gss_id = gs.gs_id) AND gas.isgs)))
             LEFT JOIN altlast_version1.bere b ON ((v.vflz_id = b.vflz_id)))
          WHERE (COALESCE((b.c_bere_res_abwbewe)::text, ''::text) <> ALL (ARRAY[('00'::character varying)::text, ('BLKR10'::character varying)::text]))) ges;


--
-- Name: gsimport_gs_all_v; Type: VIEW; Schema: altlast_version1; Owner: -
--

CREATE VIEW altlast_version1.gsimport_gs_all_v AS
 SELECT vc.vflz_id,
    gs.gs_id,
    gs.c_gs_typ,
    gs.gs_titel,
        CASE
            WHEN ((gs.c_gs_status)::text = ANY (ARRAY[('50'::character varying)::text, ('51'::character varying)::text])) THEN 'CLOSED'::text
            ELSE 'OPEN'::text
        END AS del_thread_status,
    gs.c_gs_status,
    gs.bemerkungen AS gs_bemerkungen,
    gss.gss_id,
    gss.c_gss_typ,
    c2003.bezeichnung AS gss_typ,
    gss.gss_titel,
    gss.bemerkungen AS gss_bemerkungen,
    vc.c_vflz_bearbstand AS v1_c_vflz_bearbstand
   FROM (((((((((altlast_version1.vflz vc
     JOIN altlast_version1.gs_obje go ON ((go.obje_id = vc.obje_id)))
     LEFT JOIN altlast_version1.gs gs ON ((go.gs_id = gs.gs_id)))
     LEFT JOIN altlast_version1.gss ON ((gss.gs_id = gs.gs_id)))
     LEFT JOIN altlast_version1.cod c2002 ON (((c2002.c_cli_id = 2002) AND ((c2002.code)::text = (gs.c_gs_typ)::text) AND (gs.c_gs_typ IS NOT NULL) AND (c2002.code IS NOT NULL))))
     LEFT JOIN altlast_version1.cod c2003 ON (((c2003.c_cli_id = 2003) AND ((c2003.code)::text = (gss.c_gss_typ)::text))))
     LEFT JOIN altlast_version1.cod c2001 ON (((c2001.c_cli_id = 2001) AND ((c2001.code)::text = (gs.c_gs_status)::text))))
     LEFT JOIN altlast_version1.cod c20011 ON (((c20011.c_cli_id = 2001) AND ((c20011.code)::text = (gss.c_gss_status)::text))))
     LEFT JOIN altlast_version1.byta_gss ON ((byta_gss.gss_id = gss.gss_id)))
     LEFT JOIN altlast_version1.byta ON ((byta_gss.gss_id = byta.byta_id)));


