--
-- Name: kbs_public_v; Type: VIEW; Schema: altlast_version1; Owner: -
--

CREATE VIEW altlast_version1.kbs_public_v AS
 SELECT foo2.vflgeo_id,
    foo2.vflz_id,
    foo2.wkb_geometry,
    foo2.staonr,
    foo2.staotyp,
    foo2.h_gem_id,
    foo2.gemeinde,
        CASE
            WHEN (foo2.symbol = 'gelb'::text) THEN ''::text
            ELSE foo2.beweart5
        END AS beweart5,
        CASE
            WHEN (foo2.symbol = 'gelb'::text) THEN ''::text
            ELSE foo2.beweart8
        END AS beweart8,
        CASE
            WHEN (foo2.symbol = 'gelb'::text) THEN ''::text
            ELSE foo2.ustand
        END AS ustand,
        CASE
            WHEN (foo2.symbol = 'gelb'::text) THEN ''::text
            ELSE foo2.zeitraum
        END AS zeitraum,
    foo2.eintrag,
    foo2.symbol
   FROM ( SELECT foo.vflgeo_id,
            foo.vflz_id,
            foo.wkb_geometry,
            (foo.staonr)::text AS staonr,
            (c63.bezeichnung)::text AS staotyp,
            foo.h_gem_id,
            (gem.gemeinde)::text AS gemeinde,
            (c103.bezeichnung)::text AS beweart5,
            (c103_8.bezeichnung)::text AS beweart8,
            altlast_version1.kbs_ustand(foo.obje_id) AS ustand,
            foo.zeitraum,
                CASE
                    WHEN (foo.dateintrag IS NULL) THEN 'in Bearbeitung: Der Standort kann nach der abschliessenden Beurteilung auch unbelastet sein.'::text
                    ELSE ('rechtskräftig, '::text || foo.dateintrag)
                END AS eintrag,
                CASE
                    WHEN (foo.dateintrag IS NULL) THEN 'gelb'::text
                    ELSE 'rot'::text
                END AS symbol
           FROM ((((( SELECT g.vflgeo_id,
                    v.vflz_id,
                    v.obje_id,
                    g.wkb_geometry,
                    v.vflz_combined_id_kt AS staonr,
                    v.c_vflz_vftyp,
                    o.h_gem_id,
                    v.c_vflz_bearbstand,
                    (
                        CASE
                            WHEN ((b.c_bere_res_abwbewe)::text = ANY (ARRAY[('BLKR05'::character varying)::text, ('BLKR13'::character varying)::text, ('BLKR14'::character varying)::text])) THEN b.c_bere_res_abwbewe
                            ELSE NULL::character varying
                        END)::text AS c_bewertung_art5,
                    (
                        CASE
                            WHEN ((b.c_bere_res_abwbewe)::text = ANY (ARRAY[('BLKR06'::character varying)::text, ('BLKR07'::character varying)::text, ('BLKR08'::character varying)::text])) THEN b.c_bere_res_abwbewe
                            ELSE NULL::character varying
                        END)::text AS c_bewertung_art8,
                    to_char((altlast_version1.get_bewe_date(v.obje_id))::timestamp with time zone, 'DD.MM.YYYY'::text) AS dateintrag,
                    COALESCE(foozeit.zeitraum, 'unbekannt'::text) AS zeitraum
                   FROM ((((altlast_version1.obje o
                     JOIN altlast_version1.vflz_current_v v ON ((o.obje_id = v.obje_id)))
                     JOIN altlast_version1.vflgeo g ON ((g.vflz_id = v.vflz_id)))
                     JOIN altlast_version1.bere b ON ((b.vflz_id = v.vflz_id)))
                     LEFT JOIN ( SELECT zeitab.typ_id AS vflz_id,
                            zeitab.c_typ,
                                CASE
                                    WHEN ((zeitab.zeitraum_von IS NULL) AND (zeitab.zeitraum_bis <= '0001-01-01'::date)) THEN 'unbekannt'::text
                                    ELSE ((
                                    CASE
WHEN (zeitab.zeitraum_von IS NULL) THEN 'unbekannt'::text
ELSE (date_part('year'::text, zeitab.zeitraum_von))::text
                                    END || ' bis '::text) ||
                                    CASE
WHEN (zeitab.zeitraum_bis > now()) THEN 'heute'::text
WHEN (zeitab.zeitraum_bis <= '0001-01-01'::date) THEN 'unbekannt'::text
ELSE (date_part('year'::text, zeitab.zeitraum_bis))::text
                                    END)
                                END AS zeitraum
                           FROM ( SELECT ii.vflz_id AS typ_id,
                                    '02'::text AS c_typ,
                                    altlast_version1.zeitraum_von(ii.intb_vonbetrieb) AS zeitraum_von,
                                    altlast_version1.zeitraum_bis(ii.intb_bisbetrieb, (ii.c_intb_infg_bisbetrieb)::text) AS zeitraum_bis
                                   FROM (altlast_version1.intb ii
                                     JOIN altlast_version1.rusa r ON (((r.keyfield_value = ii.intb_id) AND ((r.dataset_name)::text = 'INTB'::text) AND ((r.keyfield_name)::text = 'INTB_ID'::text) AND ((r.rusa_data)::text <> '51'::text))))
                                  GROUP BY ii.vflz_id
                                UNION
                                 SELECT ia.vflz_id AS typ_id,
                                    '01'::text AS c_typ,
                                    altlast_version1.zeitraum_von(ia.inta_ablag_von) AS zeitraum_von,
                                    altlast_version1.zeitraum_bis(ia.inta_ablag_bis, (ia.c_inta_infg_ablag_bis)::text) AS zeitraum_bis
                                   FROM altlast_version1.inta ia
                                  GROUP BY ia.vflz_id) zeitab
                        UNION
                         SELECT iu.vflz_id,
                            '03'::text,
                            altlast_version1.zeitraum_unfall(iu.intu_unfallvon, iu.intu_unfallbis) AS zeitraum
                           FROM altlast_version1.intu iu
                          GROUP BY iu.vflz_id) foozeit ON (((foozeit.vflz_id = v.vflz_id) AND ((v.c_vflz_vftyp)::text = foozeit.c_typ))))
                  WHERE ((b.c_bere_res_abwbewe)::text = ANY (ARRAY[('BLKR09'::character varying)::text, ('BLKR05'::character varying)::text, ('BLKR13'::character varying)::text, ('BLKR14'::character varying)::text, ('BLKR06'::character varying)::text, ('BLKR07'::character varying)::text, ('BLKR08'::character varying)::text, ('BLKR12'::character varying)::text]))) foo
             LEFT JOIN altlast_version1.cod c63 ON ((((foo.c_vflz_vftyp)::text = (c63.code)::text) AND (c63.c_cli_id = 63))))
             LEFT JOIN altlast_version1.h_gem gem ON ((gem.h_gem_id = foo.h_gem_id)))
             LEFT JOIN altlast_version1.cod c103 ON (((foo.c_bewertung_art5 = (c103.code)::text) AND (c103.c_cli_id = 103))))
             LEFT JOIN altlast_version1.cod c103_8 ON (((foo.c_bewertung_art8 = (c103_8.code)::text) AND (c103_8.c_cli_id = 103))))) foo2;


--
-- Name: VIEW kbs_public_v; Type: COMMENT; Schema: altlast_version1; Owner: -
--

COMMENT ON VIEW altlast_version1.kbs_public_v IS 'View fuer die Aufschaltung des oeffentlichen KbS. Alle anzuzeigenden Standorte sind beretis gefiltert.';


--
-- Name: kbsgeo; Type: TABLE; Schema: altlast_version1; Owner: -
--

CREATE TABLE altlast_version1.kbsgeo (
    kbsgeo_id integer NOT NULL,
