--
-- Name: latest_changes_v; Type: VIEW; Schema: altlast_version1; Owner: -
--

CREATE VIEW altlast_version1.latest_changes_v AS
 SELECT foo.typ,
    foo.gs_id,
    foo.gss_id,
    foo.bemerkungen,
    foo.titel,
    foo.start_datum_planung,
    foo.start_datum_ist,
    foo.end_datum_planung,
    foo.end_datum_ist,
    foo.beteiligte,
    foo.mutations_datum
   FROM ( SELECT 'gs'::character varying AS typ,
            gs.gs_id,
            NULL::bigint AS gss_id,
            gs.bemerkungen,
            gs.gs_titel AS titel,
            gs.start_datum_planung,
            gs.start_datum_ist,
            gs.end_datum_planung,
            gs.end_datum_ist,
            gs_bet.beteiligte,
            gs.mutations_datum
           FROM (altlast_version1.gs gs
             JOIN ( SELECT g2.gs_id,
                    altlast_version1.commacat_all((((s.vorname)::text || ' '::text) || (s.name)::text)) AS beteiligte
                   FROM (altlast_version1.gs_subj g2
                     JOIN altlast_version1.subj s ON ((s.subj_id = g2.subj_id)))
                  GROUP BY g2.gs_id) gs_bet ON ((gs_bet.gs_id = gs.gs_id)))
        UNION
         SELECT 'gss'::character varying AS typ,
            gss.gs_id,
            gss.gss_id,
            gss.bemerkungen,
            gss.gss_titel AS titel,
            gss.start_datum_planung,
            gss.start_datum_ist,
            gss.end_datum_planung,
            gss.end_datum_ist,
            gss_bet.beteiligte,
            gss.mutations_datum
           FROM (altlast_version1.gss gss
             JOIN ( SELECT g2.gss_id,
                    g2.gs_id,
                    altlast_version1.commacat_all((((s.vorname)::text || ' '::text) || (s.name)::text)) AS beteiligte
                   FROM (altlast_version1.gss_subj g2
                     JOIN altlast_version1.subj s ON ((s.subj_id = g2.subj_id)))
                  GROUP BY g2.gss_id, g2.gs_id) gss_bet ON (((gss_bet.gs_id = gss.gs_id) AND (gss_bet.gss_id = gss.gss_id))))) foo
  WHERE (foo.mutations_datum IS NOT NULL)
  ORDER BY foo.mutations_datum DESC;


