    b.befr_aussage,
    b.befr_datum,
    b.befr_zusatzinfo,
    b.befr_id,
    b.vflz_id,
    v.obje_id
   FROM (altlast_version1.befr b
     JOIN altlast_version1.vflz v USING (vflz_id))
  WHERE ((v.zust_aktuell = true) OR (v.zust_aktuell IS NULL))
  ORDER BY b.befr_datum DESC;


