--
-- Name: report_bere_v; Type: VIEW; Schema: altlast_version1; Owner: -
--

CREATE VIEW altlast_version1.report_bere_v AS
 SELECT b.bere_begr_abw_art32c,
    b.bere_begr_abwbewe,
    b.c_bere_abw_art32c,
    b.c_bere_art_autobewe,
    b.c_bere_art32c,
    b.c_bere_res_abwbewe,
    b.c_bere_res_autobewe,
    b.h_bere_abw_art32c,
    b.h_bere_art_autobewe,
    b.h_bere_art32c,
    b.h_bere_res_abwbewe,
    b.h_bere_res_autobewe,
    b.vflz_id,
        CASE
            WHEN (((b.c_bere_res_abwbewe)::text = ''::text) OR (b.c_bere_res_abwbewe IS NULL)) THEN b.c_bere_res_autobewe
            ELSE b.c_bere_res_abwbewe
        END AS c_bez_max_katrel,
        CASE
            WHEN (((b.c_bere_res_abwbewe)::text = ''::text) OR (b.c_bere_res_abwbewe IS NULL)) THEN 'manuell'::text
            ELSE 'automatisch'::text
        END AS bewe_art,
        CASE
            WHEN (((b.c_bere_res_abwbewe)::text = ''::text) OR (b.c_bere_res_abwbewe IS NULL)) THEN ( SELECT cod.bezeichnung
               FROM altlast_version1.cod
              WHERE (((b.c_bere_res_autobewe)::text = (cod.code)::text) AND (cod.c_cli_id = 103)))
            ELSE ( SELECT cod.bezeichnung
               FROM altlast_version1.cod
              WHERE (((b.c_bere_res_abwbewe)::text = (cod.code)::text) AND (cod.c_cli_id = 103)))
        END AS bez_max_katrel,
    v.obje_id
   FROM (altlast_version1.bere b
     JOIN altlast_version1.vflz_current_v v ON ((v.vflz_id = b.vflz_id)))
  WHERE ((v.zust_aktuell = true) OR (v.zust_aktuell IS NULL));


--
-- Name: report_berebl_v; Type: VIEW; Schema: altlast_version1; Owner: -
--

CREATE VIEW altlast_version1.report_berebl_v AS
 SELECT foo.bere_begr_abw_art32c,
    foo.bere_begr_abwbewe,
    foo.c_bere_abw_art32c,
    foo.c_bere_art_autobewe,
    foo.c_bere_art32c,
    foo.c_bere_res_abwbewe,
    foo.c_bere_res_autobewe,
    foo.h_bere_abw_art32c,
    foo.h_bere_art_autobewe,
    foo.h_bere_art32c,
    foo.h_bere_res_abwbewe,
    foo.h_bere_res_autobewe,
    foo.vflz_id,
    foo.c_bez_max_katrel,
    foo.bewe_art,
    foo.bez_max_katrel,
    foo.abfragetyp
   FROM ( SELECT b.bere_begr_abw_art32c,
            b.bere_begr_abwbewe,
            b.c_bere_abw_art32c,
            b.c_bere_art_autobewe,
            b.c_bere_art32c,
            b.c_bere_res_abwbewe,
            b.c_bere_res_autobewe,
            b.h_bere_abw_art32c,
            b.h_bere_art_autobewe,
            b.h_bere_art32c,
            b.h_bere_res_abwbewe,
            b.h_bere_res_autobewe,
            b.vflz_id,
                CASE
                    WHEN (((b.c_bere_res_abwbewe)::text = ''::text) OR (b.c_bere_res_abwbewe IS NULL)) THEN b.c_bere_res_autobewe
                    ELSE b.c_bere_res_abwbewe
                END AS c_bez_max_katrel,
                CASE
                    WHEN (((b.c_bere_res_abwbewe)::text = ''::text) OR (b.c_bere_res_abwbewe IS NULL)) THEN 'manuell'::text
                    ELSE 'automatisch'::text
                END AS bewe_art,
                CASE
                    WHEN (((b.c_bere_res_abwbewe)::text = ''::text) OR (b.c_bere_res_abwbewe IS NULL)) THEN ( SELECT cod.bezeichnung
                       FROM altlast_version1.cod
                      WHERE (((b.c_bere_res_autobewe)::text = (cod.code)::text) AND (cod.c_cli_id = 103)))
                    ELSE ( SELECT cod.bezeichnung
                       FROM altlast_version1.cod
                      WHERE (((b.c_bere_res_abwbewe)::text = (cod.code)::text) AND (cod.c_cli_id = 103)))
                END AS bez_max_katrel,
            ''::text AS abfragetyp
           FROM (altlast_version1.bere b
             JOIN altlast_version1.vflz_current_v v ON ((v.vflz_id = b.vflz_id)))
          WHERE ((v.zust_aktuell = true) OR (v.zust_aktuell IS NULL))) foo;


