    ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((d.c_doku_bereich)::text = (cod.code)::text) AND (cod.c_cli_id = 53))) AS c_doku_bereich,
    d.doku_autor,
    d.doku_datum,
    d.doku_archivort,
    d.doku_id,
    d.vflz_id,
    v.obje_id
   FROM (altlast_version1.doku d
     JOIN altlast_version1.vflz_current_v v ON ((d.vflz_id = v.vflz_id)))
  WHERE (((v.zust_aktuell = true) OR (v.zust_aktuell IS NULL)) AND ((d.c_doku_bereich)::text = '08'::text))
  ORDER BY d.doku_datum DESC;


