--
-- Name: report_eigentuemer_parz_v; Type: VIEW; Schema: altlast_version1; Owner: -
--

CREATE VIEW altlast_version1.report_eigentuemer_parz_v AS
 SELECT o.obje_id,
    so.subj_id,
    altlast_version1.commacat_all(DISTINCT (g.gb_nummer)::text) AS grundstueck_nr,
    altlast_version1.commacat_all((so.bemerkungen)::text) AS commacat_all
   FROM (((altlast_version1.obje o
     JOIN altlast_version1.subj_obje so ON ((o.obje_id = so.obje_id)))
     LEFT JOIN altlast_version1.subj_obje_grun sog ON (((sog.obje_id = o.obje_id) AND (sog.subj_id = so.subj_id) AND ((so.c_subj_obje_bez_art)::text = (sog.c_subj_obje_bez_art)::text))))
     LEFT JOIN altlast_version1.grun g ON ((sog.grun_id = g.grun_id)))
  GROUP BY o.obje_id, so.subj_id, so.c_subj_obje_bez_art;


