--
-- Name: report_eigentuemer_v; Type: VIEW; Schema: altlast_version1; Owner: -
--

CREATE VIEW altlast_version1.report_eigentuemer_v AS
 SELECT DISTINCT o.obje_id,
    s.subj_id,
    ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((p.c_anrede)::text = (cod.code)::text) AND (cod.c_cli_id = 31))) AS anrede,
    ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((p.c_titel)::text = (cod.code)::text) AND (cod.c_cli_id = 32))) AS titel,
    s.name,
    s.vorname,
    s.taetigkeit,
    a.strasse,
    a.hausnummer,
    a.postleitzahl,
    a.ort,
    a.c_kanton,
    a.c_land,
    ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE ((cod.c_cli_id = 14) AND ((cod.code)::text = (a.c_land)::text))) AS land,
    ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE ((cod.c_cli_id = 22) AND ((cod.code)::text = (so.c_subj_obje_bez_art)::text))) AS beziehungsart
   FROM (((((altlast_version1.obje o
     JOIN altlast_version1.subj_obje so ON ((o.obje_id = so.obje_id)))
     JOIN altlast_version1.subj s ON ((so.subj_id = s.subj_id)))
     LEFT JOIN altlast_version1.subj_adr sa ON ((sa.subj_id = s.subj_id)))
     LEFT JOIN altlast_version1.adr a ON ((sa.adr_id = a.adr_id)))
     LEFT JOIN altlast_version1.pers p ON ((s.subj_id = p.subj_id)))
  WHERE ((so.c_subj_obje_bez_art)::text = ANY (ARRAY[('1'::character varying)::text, ('2'::character varying)::text, ('3'::character varying)::text, ('4'::character varying)::text, ('5'::character varying)::text, ('6'::character varying)::text, ('7'::character varying)::text]))
  ORDER BY o.obje_id, s.subj_id, ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((p.c_anrede)::text = (cod.code)::text) AND (cod.c_cli_id = 31))), ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((p.c_titel)::text = (cod.code)::text) AND (cod.c_cli_id = 32))), s.name, s.vorname, s.taetigkeit, a.strasse, a.hausnummer, a.postleitzahl, a.ort, a.c_kanton, a.c_land, ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE ((cod.c_cli_id = 22) AND ((cod.code)::text = (so.c_subj_obje_bez_art)::text))), ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE ((cod.c_cli_id = 14) AND ((cod.code)::text = (a.c_land)::text)));


--
-- Name: report_emiss_v; Type: VIEW; Schema: altlast_version1; Owner: -
--

CREATE VIEW altlast_version1.report_emiss_v AS
 SELECT e.emiss_ergpotemissionen,
    e.vflz_id,
    v.obje_id
   FROM (altlast_version1.emiss e
     JOIN altlast_version1.vflz_current_v v ON ((e.vflz_id = v.vflz_id)))
  WHERE ((v.zust_aktuell = true) OR (v.zust_aktuell IS NULL));


--
-- Name: report_export_csv; Type: VIEW; Schema: altlast_version1; Owner: -
--

CREATE VIEW altlast_version1.report_export_csv AS
 SELECT v.vflz_combined_id_kt AS "Standortsnummer",
    bv.bez_max_katrel AS "Bewertung",
    s.beziehungsart AS "Beziehungsart",
    s.anrede AS "Anrede",
    s.titel AS "Titel",
    s.name AS "Name",
    s.vorname AS "Vorname",
    s.taetigkeit AS "Tätigkeit",
    s.strasse AS "Strasse",
    s.hausnummer AS "Hausnummer",
    s.postleitzahl AS "Postleitzahl",
    s.ort,
    s.c_kanton AS "Ort",
    s.c_land AS "Land",
    v.obje_id,
    s.subj_id
   FROM ((altlast_version1.vflz_current_v v
     JOIN altlast_version1.report_bere_v bv ON ((bv.vflz_id = v.vflz_id)))
     JOIN altlast_version1.report_eigentuemer_v s ON ((s.obje_id = v.obje_id)));


--
-- Name: report_formba_v; Type: VIEW; Schema: altlast_version1; Owner: -
--

CREATE VIEW altlast_version1.report_formba_v AS
 SELECT t1.intb_id,
    t1.intb_formblatt,
    t1.fragenr,
    t1.fragekurz AS frage,
        CASE
            WHEN (fba.antwort = 'J'::bpchar) THEN 'JA'::text
            ELSE
            CASE
                WHEN (fba.antwort = 'N'::bpchar) THEN 'NEIN'::text
                ELSE 'UNBEKANNT'::text
            END
        END AS antwort,
    v.obje_id
   FROM (((altlast_version1.vflz v
     JOIN altlast_version1.intb i ON ((i.vflz_id = v.vflz_id)))
     JOIN ( SELECT fbq.intb_formblatt,
            fbq.fragenr,
            fbq.fragekurz,
            ii.intb_id
           FROM (altlast_version1.intb ii
             JOIN altlast_version1.formbq fbq ON ((upper((ii.intb_formblatt)::text) = upper((fbq.intb_formblatt)::text))))
          WHERE (ii.intb_formblatt IS NOT NULL)) t1 ON ((t1.intb_id = i.intb_id)))
     LEFT JOIN altlast_version1.formba fba ON (((fba.intb_id = t1.intb_id) AND (fba.fragenr = t1.fragenr) AND (upper((t1.intb_formblatt)::text) = upper((fba.intb_formblatt)::text)))))
  WHERE ((v.zust_aktuell = true) OR (v.zust_aktuell IS NULL))
  ORDER BY v.vflz_id, i.intb_id, t1.fragenr;


