--
-- Name: report_grunddaten_v; Type: VIEW; Schema: altlast_version1; Owner: -
--

CREATE VIEW altlast_version1.report_grunddaten_v AS
 SELECT o.obje_id,
    v.vflz_id,
    v.vflz_combined_id_kt,
    v.vflz_combined_id,
    o.bezeichnung,
    o.h_gem_id,
    o.x_koordinate,
    o.y_koordinate,
    v.vflz_flurname,
    v.vflz_strasse,
    v.vflz_hausnr,
    v.vflz_postleitzahl,
    v.vflz_ort,
    ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((v.c_vflz_bearbstand)::text = (cod.code)::text) AND (cod.c_cli_id = 55))) AS vflz_bearbstand,
    v.c_vflz_bearbstand,
    ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((v.c_vflz_vftyp)::text = (cod.code)::text) AND (cod.c_cli_id = 63))) AS vflz_vftyp,
    v.c_vflz_vftyp,
    ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((v.c_vflz_infg_x_koord)::text = (cod.code)::text) AND (cod.c_cli_id = 76))) AS c_vflz_infg_x_koord,
    ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((v.c_vflz_infg_y_koord)::text = (cod.code)::text) AND (cod.c_cli_id = 76))) AS c_vflz_infg_y_koord,
    v.vfa_flaeche,
    ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((v.c_vfa_infg_flaeche)::text = (cod.code)::text) AND (cod.c_cli_id = 76))) AS c_vfa_infg_flaeche,
    ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((v.c_vflz_gws_bereich)::text = (cod.code)::text) AND (cod.c_cli_id = 72))) AS c_vflz_gws_bereich,
    ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((v.c_vflz_karstgeb)::text = (cod.code)::text) AND (cod.c_cli_id = 80))) AS c_vflz_karstgeb,
    ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((v.c_vflz_durchlaessigkeit)::text = (cod.code)::text) AND (cod.c_cli_id = 58))) AS c_vflz_durchlaessigkeit,
    ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((v.c_vflz_infg_durchlaessigkeit)::text = (cod.code)::text) AND (cod.c_cli_id = 90))) AS c_vflz_infg_durchlaessigkeit,
    ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((v.c_vflz_ex_infiltration)::text = (cod.code)::text) AND (cod.c_cli_id = 68))) AS c_vflz_ex_infiltration,
    ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((v.c_vflz_infg_ex_infiltration)::text = (cod.code)::text) AND (cod.c_cli_id = 90))) AS c_vflz_infg_ex_infiltration,
    v.vflz_niederschlag,
    ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((v.c_vflz_infg_niederschlag)::text = (cod.code)::text) AND (cod.c_cli_id = 76))) AS c_vflz_infg_niederschlag,
    v.vfa_lockergestein,
    ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((v.c_vfa_infg_lockergestein)::text = (cod.code)::text) AND (cod.c_cli_id = 76))) AS c_vfa_infg_lockergestein,
    ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((v.c_vflz_ofabdichtung)::text = (cod.code)::text) AND (cod.c_cli_id = 79))) AS c_vflz_ofabdichtung,
    ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((v.c_vfa_abltsickerwasser)::text = (cod.code)::text) AND (cod.c_cli_id = 56))) AS c_vfa_abltsickerwasser,
    ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((v.c_vflz_metfass)::text = (cod.code)::text) AND (cod.c_cli_id = 79))) AS c_vflz_metfass,
    ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((v.c_vflz_metablt)::text = (cod.code)::text) AND (cod.c_cli_id = 56))) AS c_vflz_metablt,
    ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((v.c_vflz_metkntrablt)::text = (cod.code)::text) AND (cod.c_cli_id = 79))) AS c_vflz_metkntrablt,
    ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((v.c_vflz_fremdablt)::text = (cod.code)::text) AND (cod.c_cli_id = 56))) AS c_vflz_fremdablt,
    ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((v.c_vflz_fremdfass)::text = (cod.code)::text) AND (cod.c_cli_id = 79))) AS c_vflz_fremdfass,
    ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((v.c_vflz_fremdkntrablt)::text = (cod.code)::text) AND (cod.c_cli_id = 79))) AS c_vflz_fremdkntrablt,
    ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((v.c_vfbz_unterkellerung)::text = (cod.code)::text) AND (cod.c_cli_id = 78))) AS c_vfbz_unterkellerung,
    ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((v.c_vflz_zugang)::text = (cod.code)::text) AND (cod.c_cli_id = 105))) AS c_vflz_zugang,
    ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((v.c_vflz_freil_schadstoff)::text = (cod.code)::text) AND (cod.c_cli_id = 80))) AS c_vflz_freil_schadstoff,
    ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((v.c_vfaz_seitenabdichtung)::text = (cod.code)::text) AND (cod.c_cli_id = 79))) AS c_vfaz_seitenabdichtung,
    ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((v.c_vfaz_entgasanlage)::text = (cod.code)::text) AND (cod.c_cli_id = 64))) AS c_vfaz_entgasanlage,
    ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((v.c_vfaz_sohlenabdichtung)::text = (cod.code)::text) AND (cod.c_cli_id = 79))) AS c_vfaz_sohlenabdichtung,
    v.vfa_grad_ueberdeck,
    ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((v.c_vfa_ablart)::text = (cod.code)::text) AND (cod.c_cli_id = 50))) AS c_vfa_ablart,
    ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((v.c_vfa_maechtigkeit_ueberdeck)::text = (cod.code)::text) AND (cod.c_cli_id = 85))) AS c_vfa_maechtigkeit_ueberdeck,
    ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((v.c_vfaz_sickerfassung)::text = (cod.code)::text) AND (cod.c_cli_id = 79))) AS c_vfaz_sickerfassung,
    v.vflz_abst_siedlung,
    ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((v.c_vflz_infg_abst_siedlung)::text = (cod.code)::text) AND (cod.c_cli_id = 76))) AS c_vflz_infg_abst_siedlung,
    ( SELECT
                CASE
                    WHEN (quel.quel_description IS NOT NULL) THEN quel.quel_description
                    ELSE ''::text
                END AS "case"
           FROM altlast_version1.quel
          WHERE (((quel.quel_dataset_name)::text = 'OBJE'::text) AND ((quel.quel_field_name)::text = 'X_KOORDINATE'::text) AND (quel.quel_id = o.obje_id))) AS quel_lage,
    v.owner_org,
    hg.gemeinde,
    hg.c_kanton
   FROM ((altlast_version1.vflz v
     JOIN altlast_version1.obje o ON ((o.obje_id = v.obje_id)))
     LEFT JOIN altlast_version1.h_gem hg ON ((o.h_gem_id = hg.h_gem_id)));


