-- Name: VIEW report_grunddaten_v; Type: COMMENT; Schema: altlast_version1; Owner: -
--

COMMENT ON VIEW altlast_version1.report_grunddaten_v IS 'required by report version1_geko';


--
-- Name: report_gs_obje_v; Type: VIEW; Schema: altlast_version1; Owner: -
--

CREATE VIEW altlast_version1.report_gs_obje_v AS
 SELECT gso.obje_id,
    gs.gs_id,
    gs.gs_titel,
    gs.bemerkungen AS gs_bemerkungen,
    gs.start_datum_planung,
    gs.end_datum_planung,
    gs.start_datum_ist,
    gs.end_datum_ist,
    gs.c_gs_status,
    ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE ((cod.c_cli_id = 2001) AND ((cod.code)::text = (gs.c_gs_status)::text))) AS gs_status
   FROM (altlast_version1.gs
     JOIN altlast_version1.gs_obje gso ON ((gs.gs_id = gso.gs_id)))
  ORDER BY
        CASE
            WHEN (gs.end_datum_ist IS NULL) THEN ('now'::text)::date
            ELSE gs.end_datum_ist
        END DESC;


--
-- Name: VIEW report_gs_obje_v; Type: COMMENT; Schema: altlast_version1; Owner: -
--

COMMENT ON VIEW altlast_version1.report_gs_obje_v IS 'required by report version1_geko';


--
-- Name: report_gs_subj_v; Type: VIEW; Schema: altlast_version1; Owner: -
--

CREATE VIEW altlast_version1.report_gs_subj_v AS
 SELECT gs.gs_id,
    gss.subj_id,
    s.name,
    s.vorname,
    s.taetigkeit,
    a.c_land,
    a.c_kanton,
    a.strasse,
    a.ort,
    a.hausnummer,
    p.c_anrede,
    ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE ((cod.c_cli_id = 1) AND ((cod.code)::text = (p.c_anrede)::text))) AS anrede,
    p.c_titel,
    ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE ((cod.c_cli_id = 32) AND ((cod.code)::text = (p.c_titel)::text))) AS titel,
    ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE ((cod.c_cli_id = 22) AND ((cod.code)::text = (gss.c_gs_subj_bez_art)::text))) AS beziehungsart
   FROM ((((((altlast_version1.gs
     JOIN altlast_version1.gs_obje gso ON ((gs.gs_id = gso.gs_id)))
     JOIN altlast_version1.gs_subj gss ON ((gs.gs_id = gss.gs_id)))
     JOIN altlast_version1.subj s ON ((s.subj_id = gss.subj_id)))
     LEFT JOIN altlast_version1.pers p ON ((p.subj_id = s.subj_id)))
     LEFT JOIN altlast_version1.subj_adr sa ON ((sa.subj_id = s.subj_id)))
     LEFT JOIN altlast_version1.adr a ON ((a.adr_id = sa.adr_id)))
  ORDER BY
        CASE
            WHEN (gs.end_datum_ist IS NULL) THEN ('now'::text)::date
            ELSE gs.end_datum_ist
        END DESC;


--
-- Name: VIEW report_gs_subj_v; Type: COMMENT; Schema: altlast_version1; Owner: -
--

COMMENT ON VIEW altlast_version1.report_gs_subj_v IS 'required by report version1_geko';


--
-- Name: report_gss_obje_v; Type: VIEW; Schema: altlast_version1; Owner: -
--

CREATE VIEW altlast_version1.report_gss_obje_v AS
 SELECT gsso.obje_id,
    gss.gss_id,
    gss.gs_id,
    gss.gss_titel,
    gss.bemerkungen,
    gss.start_datum_planung,
    gss.end_datum_planung,
    gss.start_datum_ist,
    gss.end_datum_ist,
    ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE ((cod.c_cli_id = gss.h_gss_status) AND ((cod.code)::text = (gss.c_gss_status)::text))) AS gss_status
   FROM (altlast_version1.gss
     LEFT JOIN altlast_version1.gss_obje gsso ON ((gss.gss_id = gsso.gss_id)))
  ORDER BY
        CASE
            WHEN (gss.end_datum_ist IS NULL) THEN ('now'::text)::date
            ELSE gss.end_datum_ist
        END DESC;


--
-- Name: report_gss_subj_v; Type: VIEW; Schema: altlast_version1; Owner: -
--

CREATE VIEW altlast_version1.report_gss_subj_v AS
 SELECT gss.gss_id,
    gsss.subj_id,
    s.name,
    s.vorname,
    s.taetigkeit,
    a.c_land,
    a.c_kanton,
    a.strasse,
    a.ort,
    a.hausnummer,
    p.c_anrede,
    ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE ((cod.c_cli_id = 1) AND ((cod.code)::text = (p.c_anrede)::text))) AS anrede,
    p.c_titel,
    ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE ((cod.c_cli_id = 32) AND ((cod.code)::text = (p.c_titel)::text))) AS titel,
    ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE ((cod.c_cli_id = 22) AND ((cod.code)::text = (gsss.c_gss_subj_bez_art)::text))) AS beziehungsart
   FROM (((((altlast_version1.gss_subj gsss
     JOIN altlast_version1.gss gss ON ((gss.gss_id = gsss.gss_id)))
     JOIN altlast_version1.subj s ON ((s.subj_id = gsss.subj_id)))
     LEFT JOIN altlast_version1.pers p ON ((p.subj_id = s.subj_id)))
     LEFT JOIN altlast_version1.subj_adr sa ON ((sa.subj_id = s.subj_id)))
     LEFT JOIN altlast_version1.adr a ON ((a.adr_id = sa.adr_id)))
  ORDER BY
        CASE
            WHEN (gss.end_datum_ist IS NULL) THEN ('now'::text)::date
            ELSE gss.end_datum_ist
        END DESC;


--
-- Name: VIEW report_gss_subj_v; Type: COMMENT; Schema: altlast_version1; Owner: -
--

COMMENT ON VIEW altlast_version1.report_gss_subj_v IS 'required by report version1_geko';


--
-- Name: report_gwnu_v; Type: VIEW; Schema: altlast_version1; Owner: -
--

CREATE VIEW altlast_version1.report_gwnu_v AS
 SELECT ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((g.c_gwnu_nutzung)::text = (cod.code)::text) AND (cod.c_cli_id = 88))) AS c_gwnu_nutzung,
    g.gwnu_distanz,
    ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((g.c_gwnu_infg_distanz)::text = (cod.code)::text) AND (cod.c_cli_id = 90))) AS c_gwnu_infg_distanz,
    g.gwnu_id,
    v.obje_id
   FROM (altlast_version1.gwnu g
     JOIN altlast_version1.vflz v USING (vflz_id))
  WHERE ((v.zust_aktuell = true) OR (v.zust_aktuell IS NULL));


--
-- Name: VIEW report_gwnu_v; Type: COMMENT; Schema: altlast_version1; Owner: -
--

COMMENT ON VIEW altlast_version1.report_gwnu_v IS 'required by report version1_datenblatt';


--
-- Name: report_gwvk_v; Type: VIEW; Schema: altlast_version1; Owner: -
--

CREATE VIEW altlast_version1.report_gwvk_v AS
 SELECT g.gwvk_name_gw,
    ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((g.c_gwvk_relzugw)::text = (cod.code)::text) AND (cod.c_cli_id = 71))) AS c_gwvk_relzugw,
    ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((g.c_gwvk_infg_relzugw)::text = (cod.code)::text) AND (cod.c_cli_id = 90))) AS c_gwvk_infg_relzugw,
    g.gwvk_flurabstand,
    ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((g.c_gwvk_infg_flurabstand)::text = (cod.code)::text) AND (cod.c_cli_id = 90))) AS c_gwvk_infg_flurabstand,
    g.gwvk_abstand_sohle,
    ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((g.c_gwvk_infg_abstand_sohle)::text = (cod.code)::text) AND (cod.c_cli_id = 90))) AS c_gwvk_infg_abstand_sohle,
    ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((g.c_gwvk_sohle_ablagerung)::text = (cod.code)::text) AND (cod.c_cli_id = 69))) AS c_gwvk_sohle_ablagerung,
    ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((g.c_gwvk_infg_sohle_ablagerung)::text = (cod.code)::text) AND (cod.c_cli_id = 90))) AS c_gwvk_infg_sohle_ablagerung,
    g.gwvk_id,
    v.obje_id
   FROM (altlast_version1.gwvk g
     JOIN altlast_version1.vflz v USING (vflz_id))
  WHERE ((v.zust_aktuell = true) OR (v.zust_aktuell IS NULL));


