--
-- Name: report_inta_v; Type: VIEW; Schema: altlast_version1; Owner: -
--

CREATE VIEW altlast_version1.report_inta_v AS
 SELECT i.inta_vol_kompartiment,
    ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((i.c_inta_infg_vol_kompartiment)::text = (cod.code)::text) AND (cod.c_cli_id = 76))) AS c_inta_infg_vol_kompartiment,
    i.inta_ablag_von,
    ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((i.c_inta_infg_ablag_von)::text = (cod.code)::text) AND (cod.c_cli_id = 90))) AS c_inta_infg_ablag_von,
    i.inta_ablag_bis,
    ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((i.c_inta_infg_ablag_bis)::text = (cod.code)::text) AND (cod.c_cli_id = 90))) AS c_inta_infg_ablag_bis,
    i.inta_ergaenzung,
    i.inta_id,
    v.obje_id,
    ( SELECT
                CASE
                    WHEN (quel.quel_description IS NOT NULL) THEN quel.quel_description
                    ELSE ''::text
                END AS "case"
           FROM altlast_version1.quel
          WHERE ((quel.quel_dataset_name = 'INTA'::bpchar) AND (quel.quel_field_name = 'INTA_ABLAG_BIS'::bpchar) AND (quel.quel_id = i.inta_id))) AS quel_ausdehnung,
    ( SELECT
                CASE
                    WHEN (quel.quel_description IS NOT NULL) THEN quel.quel_description
                    ELSE ''::text
                END AS "case"
           FROM altlast_version1.quel
          WHERE ((quel.quel_dataset_name = 'INTA'::bpchar) AND (quel.quel_field_name = 'INTA_ABLAG_VON'::bpchar) AND (quel.quel_id = i.inta_id))) AS quel_zeitraum
   FROM (altlast_version1.inta i
     JOIN altlast_version1.vflz v USING (vflz_id))
  WHERE ((v.zust_aktuell = true) OR (v.zust_aktuell IS NULL))
  ORDER BY i.inta_ablag_bis DESC;


