-- Name: VIEW report_inta_v; Type: COMMENT; Schema: altlast_version1; Owner: -
--

COMMENT ON VIEW altlast_version1.report_inta_v IS 'required by report version1_datenblatt';


--
-- Name: report_intb_v; Type: VIEW; Schema: altlast_version1; Owner: -
--

CREATE VIEW altlast_version1.report_intb_v AS
 SELECT i.intb_firma_name,
    i.intb_firma_vorname,
    i.intb_firma_strasse,
    i.intb_firma_hausnummer,
    i.intb_firma_hausnummer_zusatz,
    i.intb_firma_plz,
    i.intb_firma_ort,
    i.c_intb_bran,
    ( SELECT b.bezeichnung
           FROM altlast_version1.branchen b
          WHERE (((i.c_intb_bran)::text = (b.code)::text) AND (b.c_cli_id = 25))) AS c_intb_bran_bezeichnung,
    i.c_intb_bran_noga,
    ( SELECT b.bezeichnung
           FROM altlast_version1.branchen b
          WHERE (((i.c_intb_bran_noga)::text = (b.code)::text) AND (b.c_cli_id = 250))) AS c_intb_bran_noga_bezeichnung,
    i.intb_vonbetrieb,
    ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((i.c_intb_infg_vonbetrieb)::text = (cod.code)::text) AND (cod.c_cli_id = 90))) AS c_intb_infg_vonbetrieb,
    i.intb_bisbetrieb,
    ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((i.c_intb_infg_bisbetrieb)::text = (cod.code)::text) AND (cod.c_cli_id = 90))) AS c_intb_infg_bisbetrieb,
    i.intb_groesse,
    ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((i.intb_groesse || ''::text) = (cod.code)::text) AND (cod.c_cli_id = 2004))) AS intb_groesse_klasse,
    ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((i.c_intb_infg_groesse)::text = (cod.code)::text) AND (cod.c_cli_id = 76))) AS c_intb_infg_groesse,
    ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((i.c_intb_bel_substanz)::text = (cod.code)::text) AND (cod.c_cli_id = 80))) AS c_intb_bel_substanz,
    ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((i.c_intb_art32c)::text = (cod.code)::text) AND (cod.c_cli_id = 80))) AS c_intb_art32c,
    i.intb_relevanz,
    i.intb_zeitschwelle,
    i.intb_mitarbeiter,
    i.intb_personenjahre,
    i.intb_formblatt,
    i.intb_ergaenzung,
    i.intb_id,
    v.obje_id
   FROM (altlast_version1.intb i
     JOIN altlast_version1.vflz v USING (vflz_id))
  WHERE ((v.zust_aktuell = true) OR (v.zust_aktuell IS NULL))
  ORDER BY i.intb_firma_name;


