-- Name: VIEW report_intb_v; Type: COMMENT; Schema: altlast_version1; Owner: -
--

COMMENT ON VIEW altlast_version1.report_intb_v IS 'required by report version1_datenblatt';


--
-- Name: report_intu_v; Type: VIEW; Schema: altlast_version1; Owner: -
--

CREATE VIEW altlast_version1.report_intu_v AS
 SELECT ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((im.c_inum_stoffe)::text = (cod.code)::text) AND (cod.c_cli_id = 117))) AS c_inum_stoffe,
    im.inum_ausgelaufen,
    ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((im.c_inum_infg_ausgelaufen)::text = (cod.code)::text) AND (cod.c_cli_id = 76))) AS c_inum_infg_ausgelaufen,
    im.inum_zurueckgewonnen,
    ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((im.c_inum_infg_zurueckgewonnen)::text = (cod.code)::text) AND (cod.c_cli_id = 76))) AS c_inum_infg_zurueckgewonnen,
    im.inum_stoffmng,
    ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((im.c_inum_infg_stoffmng)::text = (cod.code)::text) AND (cod.c_cli_id = 76))) AS c_inum_infg_stoffmng,
    ( SELECT
                CASE
                    WHEN (quel.quel_description IS NOT NULL) THEN quel.quel_description
                    ELSE ''::text
                END AS "case"
           FROM altlast_version1.quel
          WHERE ((quel.quel_dataset_name = 'INUM'::bpchar) AND (quel.quel_field_name = 'INUM_STOFFMNG'::bpchar) AND (quel.quel_id = im.inum_id))) AS quel_menge,
    ( SELECT
                CASE
                    WHEN (quel.quel_description IS NOT NULL) THEN quel.quel_description
                    ELSE ''::text
                END AS "case"
           FROM altlast_version1.quel
          WHERE ((quel.quel_dataset_name = 'INUM'::bpchar) AND (quel.quel_field_name = 'C_INUM_STOFFE'::bpchar) AND (quel.quel_id = im.inum_id))) AS quel_stoffe,
    i.intu_name,
    i.intu_vorname,
    i.intu_strasse,
    i.intu_hausnummer,
    i.intu_hausnummer_zusatz,
    i.intu_plz,
    i.intu_ort,
    i.intu_unfallvon,
    ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((i.c_intu_infg_unfallvon)::text = (cod.code)::text) AND (cod.c_cli_id = 90))) AS c_intu_infg_unfallvon,
    i.intu_unfallbis,
    ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((i.c_intu_infg_unfallbis)::text = (cod.code)::text) AND (cod.c_cli_id = 90))) AS c_intu_infg_unfallbis,
    i.intu_ergaenzung,
    ( SELECT
                CASE
                    WHEN (quel.quel_description IS NOT NULL) THEN quel.quel_description
                    ELSE ''::text
                END AS "case"
           FROM altlast_version1.quel
          WHERE ((quel.quel_dataset_name = 'INTU'::bpchar) AND (quel.quel_field_name = 'INTU_UNFALLVON'::bpchar) AND (quel.quel_id = i.intu_id))) AS quel_datum,
    im.inum_id,
    i.intu_id,
    v.obje_id
   FROM ((altlast_version1.intu i
     JOIN altlast_version1.inum im USING (intu_id))
     JOIN altlast_version1.vflz v ON ((v.vflz_id = i.vflz_id)))
  WHERE ((v.zust_aktuell = true) OR (v.zust_aktuell IS NULL))
  ORDER BY i.intu_unfallbis DESC;


