CREATE VIEW altlast_version1.report_kksg_v AS
 SELECT g.kksg_teilvol,
    ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((g.c_kksg_infg_teilvol)::text = (cod.code)::text) AND (cod.c_cli_id = 76))) AS c_kksg_infg_teilvol,
    ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((g.c_kksg_stoffgrp)::text = (cod.code)::text) AND (cod.c_cli_id = g.h_kksg_stoffgrp))) AS c_kksg_stoffgrp,
    ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((g.c_kksg_infg_stoffgrp)::text = (cod.code)::text) AND (cod.c_cli_id = 90))) AS c_kksg_infg_stoffgrp,
    g.kksg_id,
    k.kksk_id,
    i.inta_id,
    v.obje_id
   FROM (((altlast_version1.kksg g
     JOIN altlast_version1.kksk k ON ((g.kksk_id = k.kksk_id)))
     JOIN altlast_version1.inta i ON ((k.inta_id = i.inta_id)))
     JOIN altlast_version1.vflz v ON ((v.vflz_id = i.vflz_id)))
  WHERE ((v.zust_aktuell = true) OR (v.zust_aktuell IS NULL));


