-- Name: VIEW report_kksg_v; Type: COMMENT; Schema: altlast_version1; Owner: -
--

COMMENT ON VIEW altlast_version1.report_kksg_v IS 'required by report version1_datenblatt';


--
-- Name: report_kksk_v; Type: VIEW; Schema: altlast_version1; Owner: -
--

CREATE VIEW altlast_version1.report_kksk_v AS
 SELECT k.kksk_teilvol,
    ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((k.c_kksk_infg_teilvol)::text = (cod.code)::text) AND (cod.c_cli_id = 76))) AS c_kksk_infg_teilvol,
    ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((k.c_kksk_stoffkl)::text = (cod.code)::text) AND (cod.c_cli_id = 94))) AS c_kksk_stoffkl,
    ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((k.c_kksk_infg_stoffkl)::text = (cod.code)::text) AND (cod.c_cli_id = 90))) AS c_kksk_infg_stoffkl,
    k.kksk_id,
    i.inta_id,
    v.obje_id,
    k.kksk_ablag_von,
    ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((k.c_kksk_infg_ablag_von)::text = (cod.code)::text) AND (cod.c_cli_id = 90))) AS c_kksk_infg_ablag_von,
    k.kksk_ablag_bis,
    ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((k.c_kksk_infg_ablag_bis)::text = (cod.code)::text) AND (cod.c_cli_id = 90))) AS c_kksk_infg_ablag_bis,
    ( SELECT
                CASE
                    WHEN (quel.quel_description IS NOT NULL) THEN quel.quel_description
                    ELSE ''::text
                END AS "case"
           FROM altlast_version1.quel
          WHERE ((quel.quel_dataset_name = 'KKSK'::bpchar) AND (quel.quel_field_name = 'KKSK_TEILVOL'::bpchar) AND (quel.quel_id = k.kksk_id))) AS quel_volumen,
    ( SELECT
                CASE
                    WHEN (quel.quel_description IS NOT NULL) THEN quel.quel_description
                    ELSE ''::text
                END AS "case"
           FROM altlast_version1.quel
          WHERE ((quel.quel_dataset_name = 'KKSK'::bpchar) AND (quel.quel_field_name = 'C_KKSK_STOFFKL'::bpchar) AND (quel.quel_id = k.kksk_id))) AS quel_inhalt,
    ( SELECT
                CASE
                    WHEN (quel.quel_description IS NOT NULL) THEN quel.quel_description
                    ELSE ''::text
                END AS "case"
           FROM altlast_version1.quel
          WHERE ((quel.quel_dataset_name = 'KKSK'::bpchar) AND (quel.quel_field_name = 'KKSK_ABLAG_VON'::bpchar) AND (quel.quel_id = k.kksk_id))) AS quel_zeitraum
   FROM ((altlast_version1.kksk k
     JOIN altlast_version1.inta i ON ((k.inta_id = i.inta_id)))
     JOIN altlast_version1.vflz v ON ((v.vflz_id = i.vflz_id)))
  WHERE ((v.zust_aktuell = true) OR (v.zust_aktuell IS NULL));


