CREATE VIEW altlast_version1.report_nubo_v AS
 SELECT ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE ((n.c_nubo_nutzungsart = (cod.code)::bpchar) AND (cod.c_cli_id = 87))) AS c_nubo_nutzungsart,
    ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((n.c_nubo_akt_nutzung)::text = (cod.code)::text) AND (cod.c_cli_id = n.h_nubo_akt_nutzung))) AS c_nubo_akt_nutzung,
    n.h_nubo_akt_nutzung,
    ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((n.c_nubo_infg_akt_nutzung)::text = (cod.code)::text) AND (cod.c_cli_id = 90))) AS c_nubo_infg_akt_nutzung,
    n.nubo_flaechen,
    ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((n.c_nubo_infg_flaechen)::text = (cod.code)::text) AND (cod.c_cli_id = 90))) AS c_nubo_infg_flaechen,
    n.nubo_id,
    n.vflz_id,
    v.obje_id
   FROM (altlast_version1.nubo n
     JOIN altlast_version1.vflz v USING (vflz_id))
  WHERE ((v.zust_aktuell = true) OR (v.zust_aktuell IS NULL));


