--
-- Name: report_obje_subj_v; Type: VIEW; Schema: altlast_version1; Owner: -
--

CREATE VIEW altlast_version1.report_obje_subj_v AS
 SELECT so.obje_id,
    so.subj_id,
    so.grundstueck_nr,
    s.name,
    s.vorname,
    s.taetigkeit,
    a.c_land,
    a.c_kanton,
    a.ort,
    a.postleitzahl,
    a.strasse,
    a.hausnummer,
    p.c_anrede,
    ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE ((cod.c_cli_id = 1) AND ((cod.code)::text = (p.c_anrede)::text))) AS anrede,
    p.c_titel,
    ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE ((cod.c_cli_id = 32) AND ((cod.code)::text = (p.c_titel)::text))) AS titel,
    ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE ((cod.c_cli_id = 22) AND ((cod.code)::text = (so.c_subj_obje_bez_art)::text))) AS beziehungsart,
    so.bemerkungen AS subj_obje_bemerkungen,
    s.bemerkungen AS subj_bemerkungen
   FROM ((((altlast_version1.subj s
     JOIN altlast_version1.subj_obje so ON ((so.subj_id = s.subj_id)))
     LEFT JOIN altlast_version1.pers p ON ((p.subj_id = s.subj_id)))
     LEFT JOIN altlast_version1.subj_adr sa ON ((sa.subj_id = s.subj_id)))
     LEFT JOIN altlast_version1.adr a ON ((a.adr_id = sa.adr_id)));


--
-- Name: VIEW report_obje_subj_v; Type: COMMENT; Schema: altlast_version1; Owner: -
--

COMMENT ON VIEW altlast_version1.report_obje_subj_v IS 'required by report version1_geko';


--
-- Name: report_ogw_v; Type: VIEW; Schema: altlast_version1; Owner: -
--

CREATE VIEW altlast_version1.report_ogw_v AS
 SELECT o.ogw_name,
    ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((o.c_ogw_rellage)::text = (cod.code)::text) AND (cod.c_cli_id = 70))) AS c_ogw_rellage,
    ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((o.c_ogw_art_gewaesser)::text = (cod.code)::text) AND (cod.c_cli_id = 66))) AS c_ogw_art_gewaesser,
    ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((o.c_ogw_bau_gewaesser)::text = (cod.code)::text) AND (cod.c_cli_id = 67))) AS c_ogw_bau_gewaesser,
    o.ogw_distanz,
    ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((o.c_ogw_infg_distanz)::text = (cod.code)::text) AND (cod.c_cli_id = 90))) AS c_ogw_infg_distanz,
    o.ogw_gefaelle,
    ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((o.c_ogw_infg_gefaelle)::text = (cod.code)::text) AND (cod.c_cli_id = 90))) AS c_ogw_infg_gefaelle,
    ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((o.c_ogw_nutzung)::text = (cod.code)::text) AND (cod.c_cli_id = 89))) AS c_ogw_nutzung,
    o.ogw_distanz_nutzung,
    ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((o.c_ogw_infg_distanz_nutzung)::text = (cod.code)::text) AND (cod.c_cli_id = 90))) AS c_ogw_infg_distanz_nutzung,
    o.ogw_id,
    v.obje_id
   FROM (altlast_version1.ogw o
     JOIN altlast_version1.vflz v USING (vflz_id))
  WHERE ((v.zust_aktuell = true) OR (v.zust_aktuell IS NULL));


--
-- Name: VIEW report_ogw_v; Type: COMMENT; Schema: altlast_version1; Owner: -
--

COMMENT ON VIEW altlast_version1.report_ogw_v IS 'required by report version1_datenblatt';



--
-- Name: soru_deprecated; Type: TABLE; Schema: altlast_version1; Owner: -
--

CREATE TABLE altlast_version1.soru_deprecated (
    vflz_id integer NOT NULL,
    soru_grundstueck_nr character varying,
    soru_grundeigentuemer character varying,
    soru_betreiber character varying,
    soru_betriebsform character varying(20),
    soru_bur_nummer integer,
    soru_betriebsart smallint,
    soru_betriebstyp character varying(3),
    soru_rechtsform smallint,
    soru_sprache smallint DEFAULT 1,
    h_soru_zustand integer DEFAULT 125,
    c_soru_zustand character varying(8),
    erfassungs_datum timestamp without time zone DEFAULT now(),
    erfasser_kuerzel character varying(8) DEFAULT "current_user"(),
    mutations_datum timestamp without time zone DEFAULT now(),
    mutierer_kuerzel character varying(8)
);


--
-- Name: TABLE soru_deprecated; Type: COMMENT; Schema: altlast_version1; Owner: -
--

COMMENT ON TABLE altlast_version1.soru_deprecated IS 'soru steht fuer Solothurner Rucksack-Tabelle. Enthaelt ergaenzende Informationen zum Standort und den zugehoerigen Parzellen, Eigentuemern und Betreibern. Die Informationen werden teils redundant zu Daten in den Tabellen subj_obje, grun, grun_subj und grun_obje bzw. zu Informationen aus dem GIS gefuehrt. Sinnvoll ist, die Daten in soru teilweise ueber Trigger auf den anderen Tabellen zu fuellen oder einfach durch einen View zu ersetzen. Verwendung finden die redundanten Daten derzeit haeufig in Reports.';


--
-- Name: COLUMN soru_deprecated.soru_grundstueck_nr; Type: COMMENT; Schema: altlast_version1; Owner: -
--

COMMENT ON COLUMN altlast_version1.soru_deprecated.soru_grundstueck_nr IS 'Komma-getrennte Liste der Grundstuecksnummern';


--
-- Name: COLUMN soru_deprecated.soru_grundeigentuemer; Type: COMMENT; Schema: altlast_version1; Owner: -
--

COMMENT ON COLUMN altlast_version1.soru_deprecated.soru_grundeigentuemer IS 'Liste der Grundeigentuemer und Parzellen in folgendem Format: Parzellen-Nummer Grundeigentuemer;';


--
-- Name: COLUMN soru_deprecated.soru_betreiber; Type: COMMENT; Schema: altlast_version1; Owner: -
--

COMMENT ON COLUMN altlast_version1.soru_deprecated.soru_betreiber IS 'Betrieber von Betrieben oder Deponien am Standort';


--
-- Name: COLUMN soru_deprecated.soru_betriebsform; Type: COMMENT; Schema: altlast_version1; Owner: -
--

COMMENT ON COLUMN altlast_version1.soru_deprecated.soru_betriebsform IS 'Betriebsform der Betriebe am Standort';


--
-- Name: COLUMN soru_deprecated.soru_betriebsart; Type: COMMENT; Schema: altlast_version1; Owner: -
--

COMMENT ON COLUMN altlast_version1.soru_deprecated.soru_betriebsart IS 'Betriebsarten';


--
-- Name: COLUMN soru_deprecated.soru_betriebstyp; Type: COMMENT; Schema: altlast_version1; Owner: -
--

COMMENT ON COLUMN altlast_version1.soru_deprecated.soru_betriebstyp IS 'Betriebstypen';


--
-- Name: COLUMN soru_deprecated.soru_rechtsform; Type: COMMENT; Schema: altlast_version1; Owner: -
--

COMMENT ON COLUMN altlast_version1.soru_deprecated.soru_rechtsform IS 'Rechtsformen';


--
-- Name: COLUMN soru_deprecated.soru_sprache; Type: COMMENT; Schema: altlast_version1; Owner: -
--

COMMENT ON COLUMN altlast_version1.soru_deprecated.soru_sprache IS 'ungenutzt';


--
-- Name: COLUMN soru_deprecated.c_soru_zustand; Type: COMMENT; Schema: altlast_version1; Owner: -
--

COMMENT ON COLUMN altlast_version1.soru_deprecated.c_soru_zustand IS 'ungenutzt';


--
-- Name: soru_triggered; Type: TABLE; Schema: altlast_version1; Owner: -
--

CREATE TABLE altlast_version1.soru_triggered (
    vflz_id bigint NOT NULL,
    soru_grundstueck_nr text
);


--
-- Name: TABLE soru_triggered; Type: COMMENT; Schema: altlast_version1; Owner: -
--

COMMENT ON TABLE altlast_version1.soru_triggered IS 'Enthaelt die Parzellennummern, die aus der Verschneidung von Standort- und Parzellengeometrie entstehen. Aktualisierung durch Trigger auf vflgeo';


--
-- Name: soru; Type: VIEW; Schema: altlast_version1; Owner: -
--

CREATE VIEW altlast_version1.soru AS
 SELECT v.vflz_id,
    rt.soru_grundstueck_nr,
    (ru.soru_grundeigentuemer)::text AS soru_grundeigentuemer,
    (ru.soru_betreiber)::text AS soru_betreiber,
    (ru.soru_betriebsform)::text AS soru_betriebsform,
    ru.soru_bur_nummer,
    ru.soru_betriebsart,
    (ru.soru_betriebstyp)::text AS soru_betriebstyp,
    ru.soru_rechtsform,
    ru.soru_sprache,
    ru.h_soru_zustand,
    (ru.c_soru_zustand)::text AS c_soru_zustand,
    ru.erfassungs_datum,
    (ru.erfasser_kuerzel)::text AS erfasser_kuerzel,
    ru.mutations_datum,
    (ru.mutierer_kuerzel)::text AS mutierer_kuerzel
   FROM ((((altlast_version1.obje o
     JOIN altlast_version1.vflz_current_v v ON ((v.obje_id = o.obje_id)))
     LEFT JOIN altlast_version1.soru_deprecated ru ON ((v.vflz_id = ru.vflz_id)))
     LEFT JOIN altlast_version1.soru_triggered rt ON ((v.vflz_id = rt.vflz_id)))
     LEFT JOIN altlast_version1.bere b ON ((v.vflz_id = b.vflz_id)))
  WHERE (COALESCE((b.c_bere_res_abwbewe)::text, ''::text) <> ALL (ARRAY[('00'::character varying)::text, ('BLKR10'::character varying)::text]));


--
-- Name: VIEW soru; Type: COMMENT; Schema: altlast_version1; Owner: -
--

COMMENT ON VIEW altlast_version1.soru IS 'Imitiert die alte Tabelle soru. Die Tabelle soru ist als Backup in soru_deprecated enthalten';


--
-- Name: report_soru_v; Type: VIEW; Schema: altlast_version1; Owner: -
--

CREATE VIEW altlast_version1.report_soru_v AS
 SELECT s.vflz_id,
    s.soru_grundstueck_nr,
    s.soru_grundeigentuemer,
    s.soru_betreiber,
    s.soru_betriebsform,
    s.soru_betriebsart,
    s.soru_betriebstyp,
    ( SELECT c.bezeichnung
           FROM altlast_version1.cod c
          WHERE ((c.c_cli_id = 27) AND ((c.code)::text = (s.soru_rechtsform)::text))) AS soru_rechtsform,
    s.soru_rechtsform AS soru_c_rechtsform,
    v.obje_id
   FROM (altlast_version1.soru s
     JOIN altlast_version1.vflz_current_v v ON ((s.vflz_id = v.vflz_id)))
  WHERE ((v.zust_aktuell = true) OR (v.zust_aktuell IS NULL));


--
-- Name: report_veek_v; Type: VIEW; Schema: altlast_version1; Owner: -
--

CREATE VIEW altlast_version1.report_veek_v AS
 SELECT ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE ((vk.c_veek_verdflaeche = (cod.code)::bpchar) AND (cod.c_cli_id = 60))) AS c_veek_verdflaeche,
    vk.veek_datum,
    ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((vk.c_veek_infg_datum)::text = (cod.code)::text) AND (cod.c_cli_id = 90))) AS c_veek_infg_datum,
    vk.veek_id,
    vk.vflz_id,
    v.obje_id
   FROM (altlast_version1.veek vk
     JOIN altlast_version1.vflz v USING (vflz_id))
  WHERE ((v.zust_aktuell = true) OR (v.zust_aktuell IS NULL))
  ORDER BY vk.veek_datum DESC;


--
-- Name: VIEW report_veek_v; Type: COMMENT; Schema: altlast_version1; Owner: -
--

COMMENT ON VIEW altlast_version1.report_veek_v IS 'required by report version1_datenblatt';


--
-- Name: report_veen_v; Type: VIEW; Schema: altlast_version1; Owner: -
--

CREATE VIEW altlast_version1.report_veen_v AS
 SELECT ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((ve.c_veen_natuerlich)::text = (cod.code)::text) AND (cod.c_cli_id = 61))) AS c_veen_natuerlich,
    ve.veen_datum,
    ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((ve.c_veen_infg_datum)::text = (cod.code)::text) AND (cod.c_cli_id = 90))) AS c_veen_infg_datum,
    ve.veen_id,
    ve.vflz_id,
    v.obje_id
   FROM (altlast_version1.veen ve
     JOIN altlast_version1.vflz v USING (vflz_id))
  WHERE ((v.zust_aktuell = true) OR (v.zust_aktuell IS NULL))
  ORDER BY ve.veen_datum DESC;


--
-- Name: VIEW report_veen_v; Type: COMMENT; Schema: altlast_version1; Owner: -
--

COMMENT ON VIEW altlast_version1.report_veen_v IS 'required by report version1_datenblatt';


--
-- Name: report_versand_moeglich_v; Type: VIEW; Schema: altlast_version1; Owner: -
--

CREATE VIEW altlast_version1.report_versand_moeglich_v AS
 SELECT DISTINCT o.obje_id
   FROM (altlast_version1.obje o
     LEFT JOIN ( SELECT v1.obje_id,
            v1.vflz_id
           FROM ((altlast_version1.gs gs
             JOIN altlast_version1.gs_obje gso ON ((gs.gs_id = gso.gs_id)))
             JOIN altlast_version1.vflz_current_v v1 ON ((v1.obje_id = gso.obje_id)))
          WHERE ((gs.c_gs_status)::text = '52'::text)
        UNION
         SELECT v2.obje_id,
            v2.vflz_id
           FROM ((altlast_version1.gss
             JOIN altlast_version1.gss_obje gsso ON ((gss.gss_id = gsso.gss_id)))
             JOIN altlast_version1.vflz_current_v v2 ON ((v2.obje_id = gsso.obje_id)))
          WHERE ((gss.c_gss_status)::text = '52'::text)) kein_versand ON ((o.obje_id = kein_versand.obje_id)))
  WHERE (kein_versand.vflz_id IS NULL)
  ORDER BY o.obje_id;


--
-- Name: VIEW report_versand_moeglich_v; Type: COMMENT; Schema: altlast_version1; Owner: -
--

COMMENT ON VIEW altlast_version1.report_versand_moeglich_v IS 'listet alle obje, bei denen der versand nicht durch den status "versand zurueckstellen" eines (teil-)geschaefts blockiert wird.';


--
-- Name: report_vfsv_v; Type: VIEW; Schema: altlast_version1; Owner: -
--

CREATE VIEW altlast_version1.report_vfsv_v AS
 SELECT vv.vfsv_sonst_vorkomm,
    vv.vfsv_dat_sonst_vorkomm,
    ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((vv.c_vfsv_infg_dat_sonst_vorkomm)::text = (cod.code)::text) AND (cod.c_cli_id = 90))) AS c_vfsv_infg_dat_sonst_vorkomm,
    vv.vfsv_id,
    v.obje_id
   FROM (altlast_version1.vfsv vv
     JOIN altlast_version1.vflz v USING (vflz_id))
  WHERE ((v.zust_aktuell = true) OR (v.zust_aktuell IS NULL))
  ORDER BY vv.vfsv_dat_sonst_vorkomm DESC;


--
-- Name: VIEW report_vfsv_v; Type: COMMENT; Schema: altlast_version1; Owner: -
--

COMMENT ON VIEW altlast_version1.report_vfsv_v IS 'required by report version1_datenblatt';


--
-- Name: report_vfus_v; Type: VIEW; Schema: altlast_version1; Owner: -
--

CREATE VIEW altlast_version1.report_vfus_v AS
 SELECT ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((vs.c_vfus_art_schaden)::text = (cod.code)::text) AND (cod.c_cli_id = 101))) AS c_vfus_art_schaden,
    ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((vs.c_vfus_schaeden)::text = (cod.code)::text) AND (cod.c_cli_id = vs.h_vfus_schaeden))) AS c_vfus_schaeden,
    vs.h_vfus_schaeden,
    vs.vfus_id,
    v.obje_id
   FROM (altlast_version1.vfus vs
     JOIN altlast_version1.vflz v USING (vflz_id))
  WHERE ((v.zust_aktuell = true) OR (v.zust_aktuell IS NULL));


--
-- Name: VIEW report_vfus_v; Type: COMMENT; Schema: altlast_version1; Owner: -
--

COMMENT ON VIEW altlast_version1.report_vfus_v IS 'required by report version1_datenblatt';


--
-- Name: report_vgas_v; Type: VIEW; Schema: altlast_version1; Owner: -
--

CREATE VIEW altlast_version1.report_vgas_v AS
 SELECT ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((vg.c_vgas_gasemissionen)::text = (cod.code)::text) AND (cod.c_cli_id = 91))) AS c_vgas_gasemissionen,
    vg.vgas_id,
    vg.vflz_id,
    v.obje_id
   FROM (altlast_version1.vgas vg
     JOIN altlast_version1.vflz_current_v v ON ((vg.vflz_id = v.vflz_id)))
  WHERE ((v.zust_aktuell = true) OR (v.zust_aktuell IS NULL));


--
-- Name: report_zusa_v; Type: VIEW; Schema: altlast_version1; Owner: -
--

CREATE VIEW altlast_version1.report_zusa_v AS
 SELECT ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE (((z.c_zusa_art)::text = (cod.code)::text) AND (cod.c_cli_id = 57))) AS c_zusa_art,
    z.zusa_angaben,
    z.zusa_id,
    v.obje_id
   FROM (altlast_version1.zusa z
     JOIN altlast_version1.vflz v USING (vflz_id))
  WHERE ((v.zust_aktuell = true) OR (v.zust_aktuell IS NULL));


--
-- Name: VIEW report_zusa_v; Type: COMMENT; Schema: altlast_version1; Owner: -
--

COMMENT ON VIEW altlast_version1.report_zusa_v IS 'required by report version1_datenblatt';


