--
-- Name: rpt_report; Type: TABLE; Schema: altlast_version1; Owner: -
--

CREATE TABLE altlast_version1.rpt_report (
    report_id integer NOT NULL,
    bezeichnung character varying(50),
    stylesheet character varying(300),
    kategorie character varying(50),
    standard boolean,
    vorschau character varying(300),
    sortierung integer,
    sqlquery text,
    xmldef text,
    whereclause text,
    orderclause text,
    inlinevariables text,
    type integer,
    transformer character varying(20) DEFAULT 'XML'::character varying NOT NULL
);


--
-- Name: COLUMN rpt_report.bezeichnung; Type: COMMENT; Schema: altlast_version1; Owner: -
--

COMMENT ON COLUMN altlast_version1.rpt_report.bezeichnung IS 'Name für dneReport, welcher auch in der Benutzeroberfläche dargestellt werden soll.';


--
-- Name: COLUMN rpt_report.stylesheet; Type: COMMENT; Schema: altlast_version1; Owner: -
--

COMMENT ON COLUMN altlast_version1.rpt_report.stylesheet IS 'Pfad zum XSL-Stylesheet für den Report. Dieser Pfad ist relativ zu dem in der reportgen.ini der Applikation definierten Stylesheetverzeichnis ';


--
-- Name: COLUMN rpt_report.kategorie; Type: COMMENT; Schema: altlast_version1; Owner: -
--

COMMENT ON COLUMN altlast_version1.rpt_report.kategorie IS 'Kategorie des Reports. Ermöglicht die Spezifizierung meherer alternativer Reports für eine Aktion in der Applikation';


--
-- Name: COLUMN rpt_report.standard; Type: COMMENT; Schema: altlast_version1; Owner: -
--

COMMENT ON COLUMN altlast_version1.rpt_report.standard IS 'True definiert einen Report als Standardreport für eine Kategorie';


--
-- Name: COLUMN rpt_report.vorschau; Type: COMMENT; Schema: altlast_version1; Owner: -
--

COMMENT ON COLUMN altlast_version1.rpt_report.vorschau IS 'Eventueller Link zu einem Vorschaubild';


--
-- Name: COLUMN rpt_report.sortierung; Type: COMMENT; Schema: altlast_version1; Owner: -
--

COMMENT ON COLUMN altlast_version1.rpt_report.sortierung IS 'Sortierungreihenfolge der Reports in der Bneutzeroberfläche der Applikation';


--
-- Name: COLUMN rpt_report.sqlquery; Type: COMMENT; Schema: altlast_version1; Owner: -
--

COMMENT ON COLUMN altlast_version1.rpt_report.sqlquery IS 'Der SQL-Query für das zu generierende XML. Die Where-Bedingung muss allerdings in die Spalte whereclause, die Order-Bedingung nach orderclause';


--
-- Name: COLUMN rpt_report.xmldef; Type: COMMENT; Schema: altlast_version1; Owner: -
--

COMMENT ON COLUMN altlast_version1.rpt_report.xmldef IS 'Die Query2XML-Definition für das aus dem sqlquery zu generierende XML. Der Root-Tag muss report lauten. Syntax siehe http://query2xml.sourceforge.net/';


--
-- Name: COLUMN rpt_report.whereclause; Type: COMMENT; Schema: altlast_version1; Owner: -
--

COMMENT ON COLUMN altlast_version1.rpt_report.whereclause IS 'Kommagetrennte liste mit Spalten für die WHERE-Bedingung für den sqlquery. Die Werte für diese Spalten werden aus gleichnamigen URL-Parametern bezogen';


--
-- Name: COLUMN rpt_report.orderclause; Type: COMMENT; Schema: altlast_version1; Owner: -
--

COMMENT ON COLUMN altlast_version1.rpt_report.orderclause IS 'Eine ORDER-Bedingung nach der die Ergebnisse des SQLs in sqlquery sortiert werden. Die Spalten müssen den Spaltennamen in sqlquery entsprechen';


--
-- Name: COLUMN rpt_report.inlinevariables; Type: COMMENT; Schema: altlast_version1; Owner: -
--

COMMENT ON COLUMN altlast_version1.rpt_report.inlinevariables IS 'Kommagetrennte Liste von Variable deren Vorkommen innerhalb des sqlquery durch gleichnamige URL-Parameter ersetzt werden. Notation innerhalb des SQLs für eine hier als VAR1 geführte Varaible ist [VAR1]';


