--
-- Name: subj_v; Type: VIEW; Schema: altlast_version1; Owner: -
--

CREATE VIEW altlast_version1.subj_v AS
 SELECT s.subj_id,
    a.adr_id,
    s.name,
    s.vorname,
    s.taetigkeit,
    g.gemeindeort,
    a.strasse,
    a.hausnummer,
    a.hausnummer_zusatz,
    o.bezeichnung AS standort,
    v.vflz_combined_id_kt AS stonr,
    o.obje_id,
    p.bezeichnung AS pool_bezeichnung,
    sk.subj_kennung,
    s.bemerkungen,
    g.postleitzahl,
    g.postleitzahl_zusatz,
    g.ortsname
   FROM ((((((((((altlast_version1.subj s
     LEFT JOIN altlast_version1.subj_kennung_v sk ON ((sk.subj_id = s.subj_id)))
     LEFT JOIN altlast_version1.subj_adr sa ON ((sa.subj_id = s.subj_id)))
     LEFT JOIN altlast_version1.adr a ON ((a.adr_id = sa.adr_id)))
     LEFT JOIN altlast_version1.gemeindeort_v g ON (((g.h_gem_id = a.h_gem_id) AND ((a.ort)::text = (g.ortsname)::text))))
     LEFT JOIN altlast_version1.subj_obje so ON ((so.subj_id = s.subj_id)))
     LEFT JOIN altlast_version1.obje o ON ((o.obje_id = so.obje_id)))
     LEFT JOIN altlast_version1.vflz_current_v v ON ((v.obje_id = o.obje_id)))
     LEFT JOIN altlast_version1.obje_pool op ON ((op.obje_id = o.obje_id)))
     LEFT JOIN altlast_version1.pool p ON ((op.pool_id = p.pool_id)))
     LEFT JOIN altlast_version1.bere b ON ((v.vflz_id = b.vflz_id)))
  WHERE (COALESCE((b.c_bere_res_abwbewe)::text, ''::text) <> ALL (ARRAY[('00'::character varying)::text, ('BLKR10'::character varying)::text]))
  ORDER BY s.subj_id, a.adr_id;


