--
-- Name: vflgeo_bud_v; Type: VIEW; Schema: altlast_version1; Owner: -
--

CREATE VIEW altlast_version1.vflgeo_bud_v AS
 SELECT g.vflgeo_id,
    v.vflz_id,
    g.wkb_geometry,
    v.vflz_combined_id_kt,
    o.bezeichnung AS obje_bezeichnung,
    v.c_vflz_vftyp,
    v.c_vflz_bearbstand,
    (
        CASE
            WHEN (b.c_bere_res_abwbewe IS NULL) THEN 'BLKR09'::character varying
            ELSE b.c_bere_res_abwbewe
        END)::text AS c_bewertung,
    o.h_gem_id
   FROM (((altlast_version1.obje o
     JOIN altlast_version1.vflz_current_v v ON ((o.obje_id = v.obje_id)))
     JOIN altlast_version1.vflgeo g ON ((g.vflz_id = v.vflz_id)))
     JOIN altlast_version1.bere b ON ((b.vflz_id = v.vflz_id)));


