    vflgeo_bud_v.c_vflz_vftyp,
    vflgeo_bud_v.c_vflz_bearbstand,
    vflgeo_bud_v.c_bewertung,
    vflgeo_bud_v.h_gem_id
   FROM altlast_version1.vflgeo_bud_v;


