--
-- Name: vflsan_v; Type: VIEW; Schema: altlast_version1; Owner: -
--

CREATE VIEW altlast_version1.vflsan_v AS
 SELECT g.vflsan_id,
    v.vflz_id,
    g.wkb_geometry,
    v.vflz_combined_id_kt AS stonr,
    o.bezeichnung,
    ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE ((cod.c_cli_id = 63) AND ((cod.code)::text = (v.c_vflz_vftyp)::text))) AS typ,
    ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE ((cod.c_cli_id = 55) AND ((cod.code)::text = (v.c_vflz_bearbstand)::text))) AS bearbeitungsstand,
    ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE ((cod.c_cli_id = 103) AND ((cod.code)::text = (
                CASE
                    WHEN (b.c_bere_res_abwbewe IS NULL) THEN b.c_bere_res_autobewe
                    ELSE b.c_bere_res_abwbewe
                END)::text))) AS bewertung,
    ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE ((cod.c_cli_id = 103) AND ((cod.code)::text = (b.c_bere_res_autobewe)::text))) AS automatisch,
    ( SELECT cod.bezeichnung
           FROM altlast_version1.cod
          WHERE ((cod.c_cli_id = 103) AND ((cod.code)::text = (b.c_bere_res_abwbewe)::text))) AS manuell
   FROM (((altlast_version1.obje o
     JOIN altlast_version1.vflz_current_v v ON ((o.obje_id = v.obje_id)))
     JOIN altlast_version1.vflsan g ON ((g.vflz_id = v.vflz_id)))
     LEFT JOIN altlast_version1.bere b ON ((b.vflz_id = v.vflz_id)))
  WHERE ((COALESCE(b.c_bere_res_abwbewe, ''::character varying))::text <> ALL (ARRAY[('00'::character varying)::text, ('BLKR10'::character varying)::text]));


