-- Name: gemeinden; Type: TABLE; Schema: altlast_wfs; Owner: -
--

CREATE TABLE altlast_wfs.gemeinden (
    gid integer NOT NULL,
    objectid double precision,
    objorig character varying(20),
    dateofchng date,
    country character varying(20),
    bfsnr double precision,
    kantonsnr double precision,
    bezirksnr double precision,
    gemname character varying(50),
    gemflaeche numeric,
    gemteil double precision,
    seenr double precision,
    seename character varying(50),
    uuid character varying(40),
    objorig_ye character varying(20),
    seeflaeche numeric,
    objval character varying(50),
    the_geom public.geometry,
    CONSTRAINT enforce_dims_the_geom CHECK ((public.st_ndims(the_geom) = 2)),
    CONSTRAINT enforce_geotype_the_geom CHECK (((public.geometrytype(the_geom) = 'MULTIPOLYGON'::text) OR (the_geom IS NULL))),
    CONSTRAINT enforce_srid_the_geom CHECK ((public.st_srid(the_geom) = ANY (ARRAY[2056, 21781])))
);


--
-- Name: TABLE gemeinden; Type: COMMENT; Schema: altlast_wfs; Owner: -
--

COMMENT ON TABLE altlast_wfs.gemeinden IS 'Imported from swissBOUNDARIES3D080312 dataset

Issue #3010012';


--
-- Name: kanton_kuerzel; Type: TABLE; Schema: altlast_wfs; Owner: -
--

CREATE TABLE altlast_wfs.kanton_kuerzel (
    kantonsnr integer,
    kuerzel character varying(3)
);


--
-- Name: gemeinde_v; Type: VIEW; Schema: altlast_wfs; Owner: -
--

CREATE VIEW altlast_wfs.gemeinde_v AS
 SELECT min(gemgeoms.gid) AS gid,
    gemgeoms.bfsnr,
    gemgeoms.country,
    gemgeoms.name,
    gemgeoms.kanton,
    public.st_collect(gemgeoms.wkb_geometry) AS wkb_geometry
   FROM ( SELECT g.gid,
            g.bfsnr,
            g.country,
            g.gemname AS name,
            k.kuerzel AS kanton,
            (public.st_dump(g.the_geom)).geom AS wkb_geometry
           FROM (altlast_wfs.gemeinden g
             LEFT JOIN altlast_wfs.kanton_kuerzel k ON ((((k.kantonsnr)::double precision = g.kantonsnr) AND ((g.country)::text = 'CH'::text))))
          WHERE (((g.country)::text = ANY (ARRAY[('CH'::character varying)::text, ('LI'::character varying)::text])) AND ((g.seenr = (0)::double precision) OR (g.seenr IS NULL)))) gemgeoms
  GROUP BY gemgeoms.bfsnr, gemgeoms.country, gemgeoms.name, gemgeoms.kanton;


