--
-- Name: tg_kbs_intern; Type: VIEW; Schema: altlast_wfs; Owner: -
--

CREATE VIEW altlast_wfs.tg_kbs_intern AS
 SELECT v.vflz_id AS mapserver_id,
    ('stao'::text || (v.vflz_id)::text) AS stao_tid,
    v.vflz_combined_id_kt AS katasternummer,
    v.bezeichnung,
    c.bezeichnung AS bearbeitungsstand_kbs,
        CASE
            WHEN ((( SELECT s.value AS url_geoportal
               FROM (altlast_admin.setting s
                 JOIN altlast_admin.setitem t USING (setitem_id))
              WHERE ((t.title)::text = 'URL_Standort'::text)) IS NOT NULL) AND ((( SELECT s.value
               FROM (altlast_admin.setting s
                 JOIN altlast_admin.setitem t USING (setitem_id))
              WHERE ((t.title)::text = 'URL_Standort_Indikator'::text)))::text = 'wfs_staonr'::text)) THEN (((( SELECT s.value AS url_geoportal
               FROM (altlast_admin.setting s
                 JOIN altlast_admin.setitem t USING (setitem_id))
              WHERE ((t.title)::text = 'URL_Standort'::text)))::text || '&wfs_staonr='::text) || (v.vflz_combined_id_kt)::text)
            WHEN ((( SELECT s.value AS url_geoportal
               FROM (altlast_admin.setting s
                 JOIN altlast_admin.setitem t USING (setitem_id))
              WHERE ((t.title)::text = 'URL_Standort'::text)) IS NOT NULL) AND ((( SELECT s.value
               FROM (altlast_admin.setting s
                 JOIN altlast_admin.setitem t USING (setitem_id))
              WHERE ((t.title)::text = 'URL_Standort_Indikator'::text)))::text = 'xy_koordinates'::text)) THEN (((((( SELECT s.value AS url_geoportal
               FROM (altlast_admin.setting s
                 JOIN altlast_admin.setitem t USING (setitem_id))
              WHERE ((t.title)::text = 'URL_Standort'::text)))::text || '?Y='::text) || (public.st_x(public.st_makepoint((v.x_koordinate)::double precision, (v.y_koordinate)::double precision)))::text) || '&X='::text) || (public.st_y(public.st_makepoint((v.x_koordinate)::double precision, (v.y_koordinate)::double precision)))::text)
            WHEN ((( SELECT s.value AS url_geoportal
               FROM (altlast_admin.setting s
                 JOIN altlast_admin.setitem t USING (setitem_id))
              WHERE ((t.title)::text = 'URL_Standort'::text)) IS NOT NULL) AND ((( SELECT s.value
               FROM (altlast_admin.setting s
                 JOIN altlast_admin.setitem t USING (setitem_id))
              WHERE ((t.title)::text = 'URL_Standort_Indikator'::text)))::text <> ALL (ARRAY[('wfs_staonr'::character varying)::text, ('xy_koordinates'::character varying)::text]))) THEN (( SELECT s.value AS url_geoportal
               FROM (altlast_admin.setting s
                 JOIN altlast_admin.setitem t USING (setitem_id))
              WHERE ((t.title)::text = 'URL_Standort'::text)))::text
            ELSE NULL::text
        END AS url_standort,
    vflgeo.wkb_geometry,
    h_gem.gemeinde,
        CASE
            WHEN (parzellen.parzellen = ': '::text) THEN NULL::text
            ELSE parzellen.parzellen
        END AS parzellen,
    NULL::text AS egrid,
    staotyp_mapping.code_long AS standorttyp,
        CASE
            WHEN ((v.c_vflz_inbetrieb)::text = '01'::text) THEN (true)::text
            ELSE (false)::text
        END AS inbetrieb,
        CASE
            WHEN ((v.c_vflz_inbetrieb)::text = '01'::text) THEN (v.c_vflz_deponietyp)::text
            ELSE NULL::text
        END AS deponietyp,
        CASE
            WHEN ((v.c_vflz_nachsorge)::text = '01'::text) THEN (true)::text
            ELSE (false)::text
        END AS nachsorge,
        CASE
            WHEN (untmass_aktuellste.untmass IS NOT NULL) THEN untmass_aktuellste.untmass
            ELSE 'UntMassn1'::text
        END AS untersuchungsmassnahmen,
    statusaltlv_mapping.code_long AS statusaltlv,
    v.dat_rechtskraft AS ersteintrag,
    (( SELECT (vflz_is_published_v.dat_latest_published)::text AS dat_latest_published
           FROM altlast.vflz_is_published_v
          WHERE ((vflz_is_published_v.vflz_id IN ( SELECT vflz_any_in_vfl.vflz_id
                   FROM altlast.vflz vflz_any_in_vfl
                  WHERE (vflz_any_in_vfl.vfl_id = v.vfl_id))) AND vflz_is_published_v.is_latest_published)))::date AS letzteanpassung,
        CASE
            WHEN (( SELECT s.value
               FROM (altlast_admin.setting s
                 JOIN altlast_admin.setitem t USING (setitem_id))
              WHERE ((t.title)::text = 'URL_KbS_Auszug'::text)) IS NOT NULL) THEN ((( SELECT s.value
               FROM (altlast_admin.setting s
                 JOIN altlast_admin.setitem t USING (setitem_id))
              WHERE ((t.title)::text = 'URL_KbS_Auszug'::text)))::text || vfilename.filename)
            ELSE NULL::text
        END AS url_kbs_auszug,
    bem_standort.bem AS bemerkung,
    ('zb'::text || (vflnr.org_id)::text) AS zustaendigkeitkataster_id,
    org.bezeichnung AS zustaendigkeitkataster,
    parzellen.grundbuch
   FROM ((((((((((((((altlast.vflz_current_v cv
     LEFT JOIN altlast.vflz v USING (vflz_id))
     LEFT JOIN altlast_ili.cod_mapping_v staotyp_mapping ON (((staotyp_mapping.c_cli_id = v.h_vflz_vftyp) AND ((staotyp_mapping.code)::text = (v.c_vflz_vftyp)::text))))
     LEFT JOIN altlast.bere_v ON (((bere_v.vflz_id = v.vflz_id) AND bere_v.kbs)))
     LEFT JOIN altlast_ili.cod_mapping_v statusaltlv_mapping ON (((statusaltlv_mapping.c_cli_id = bere_v.h_bere_res_abwbewe) AND ((statusaltlv_mapping.code)::text = (bere_v.c_bere_res_abwbewe)::text))))
     LEFT JOIN altlast.vflnr ON (((v.vflz_id = vflnr.vflz_id) AND vflnr.aktiv)))
     LEFT JOIN altlast.vflgeo ON ((vflgeo.vflz_id = v.vflz_id)))
     LEFT JOIN altlast.bemgrp bemg_standort ON ((bemg_standort.public AND ((bemg_standort.bemgrp)::text = 'standort'::text))))
     LEFT JOIN altlast.bem bem_standort ON (((bem_standort.bemgrp_id = bemg_standort.bemgrp_id) AND (bem_standort.key_value = v.vflz_id) AND bem_standort.public)))
     LEFT JOIN altlast.vflz_filename_v vfilename ON ((vfilename.vflz_id = v.vflz_id)))
     LEFT JOIN ( SELECT p2.vflz_id,
            array_to_string(array_agg(concat(p2.nbident, ': ', p2.par1)), '; '::text) AS parzellen,
            array_to_string(array_agg(p2.grundbuch), '; '::text) AS grundbuch
           FROM ( SELECT p1.vflz_id,
                    p1.nbident,
                    array_to_string(array_agg(p1.gb_nummer ORDER BY p1.gb_nummer), ','::text) AS par1,
                    (p1.grundbuch)::text AS grundbuch
                   FROM ( SELECT ('TG'::text || g.h_gem_id) AS nbident,
                            sv.vflz_id,
                            g.gb_nummer,
                            agb.grundbuch
                           FROM (((altlast.subj_vflz sv
                             LEFT JOIN altlast.subj_vflz_grun svg ON ((sv.subj_vflz_id = svg.subj_vflz_id)))
                             LEFT JOIN altlast.grun g ON ((svg.grun_id = g.grun_id)))
                             LEFT JOIN altlast.grundbuch_v agb ON ((agb.gb_id = g.h_gem_id)))
                          GROUP BY g.h_gem_id, sv.vflz_id, g.gb_nummer, agb.grundbuch
                          ORDER BY sv.vflz_id, g.gb_nummer) p1
                  GROUP BY p1.vflz_id, p1.nbident, p1.grundbuch
                  ORDER BY p1.vflz_id) p2
          GROUP BY p2.vflz_id) parzellen ON ((parzellen.vflz_id = v.vflz_id)))
     LEFT JOIN ( SELECT unt.vfl_id,
            array_to_string(array_agg(unt.code_long), ','::text) AS untmass
           FROM ( SELECT tm.code_long,
                    tm.ili_code,
                    tm.ili_c_cli_id,
                    v_1.vfl_id
                   FROM (altlast_ili.task_mapping_v tm
                     JOIN altlast.vflz v_1 ON (((v_1.c_vflz_unterstand)::text = (tm.a4w_code)::text)))
                  GROUP BY tm.code_long, tm.ili_code, tm.ili_c_cli_id, v_1.vfl_id
                  ORDER BY v_1.vfl_id) unt
          GROUP BY unt.vfl_id) untmass_aktuellste ON ((untmass_aktuellste.vfl_id = v.vfl_id)))
     LEFT JOIN altlast.h_gem ON ((h_gem.h_gem_id = v.h_gem_id)))
     LEFT JOIN altlast.cod c ON (((c.c_cli_id = v.h_vflz_bearbstand) AND ((c.code)::text = (v.c_vflz_bearbstand)::text))))
     LEFT JOIN altlast.org ON ((vflnr.org_id = org.org_id)));


