--
-- Name: report_documents_xml_v _RETURN; Type: RULE; Schema: altlast; Owner: -
--

CREATE OR REPLACE VIEW altlast.report_documents_xml_v AS
 SELECT pm_doc.pm_doc_id,
    pm_vfl.vfl_id,
    pm_doc.app_doc_category,
    xmlagg(XMLELEMENT(NAME document, XMLATTRIBUTES(pm_doc.pm_doc_id AS pm_doc_id), XMLELEMENT(NAME document_title, pm_doc.app_doc_title), XMLELEMENT(NAME document_category, altlast.t(altlast.msgid_code(10022, (pm_doc.app_doc_category)::character varying))), XMLELEMENT(NAME document_create_date, to_char(pm_doc.app_doc_create_date, 'DD.MM.YYYY'::text)), XMLELEMENT(NAME document_receipt_date, to_char(pm_doc.app_doc_receipt_date, 'DD.MM.YYYY'::text)), XMLELEMENT(NAME authors, ( SELECT xmlagg(authors.author) AS xmlagg
           FROM ( SELECT xmlagg(XMLELEMENT(NAME author, XMLATTRIBUTES(subj.vorname AS vorname, subj.name AS name), XMLELEMENT(NAME document_author_subj_kennung, pm_doc_author.subj_kennung), XMLELEMENT(NAME document_author_ort, doc_author_adr.ort))) AS author
                   FROM ((((altlast.pm_doc_subj pm_doc_subj
                     JOIN altlast.subj ON ((pm_doc_subj.subj_id = subj.subj_id)))
                     LEFT JOIN altlast.subj_kennung_v pm_doc_author ON ((pm_doc_author.subj_id = pm_doc_subj.subj_id)))
                     LEFT JOIN altlast.subj_adr doc_author_subj_adr ON ((doc_author_subj_adr.subj_id = pm_doc_author.subj_id)))
                     LEFT JOIN altlast.adr doc_author_adr ON ((doc_author_adr.adr_id = doc_author_subj_adr.adr_id)))
                  WHERE ((pm_doc_subj.pm_doc_id = pm_doc.pm_doc_id) AND ((pm_doc_subj.c_pm_doc_subj_bez_art)::text = 'autor'::text))
                  GROUP BY pm_doc_author.subj_id) authors)))) AS document,
    pm_doc.app_doc_receipt_date
   FROM ((altlast.pm_vfl
     LEFT JOIN altlast.pm_cache ON ((pm_cache.pm_vfl_id = pm_vfl.pm_vfl_id)))
     LEFT JOIN altlast.pm_doc ON ((pm_doc.pm_cache_id = pm_cache.pm_cache_id)))
  GROUP BY pm_vfl.vfl_id, pm_doc.pm_doc_id, pm_doc.app_doc_category, pm_doc.app_doc_create_date
 HAVING (pm_doc.pm_doc_id IS NOT NULL)
  ORDER BY pm_doc.app_doc_receipt_date DESC, pm_doc.app_doc_create_date DESC;


